/* Capture pages at rest for design review. */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await page.click('button[type="submit"], form button');
  await page.waitForTimeout(1200);
}

async function shoot(page, url, out, h = 1400, full = false) {
  await page.setViewportSize({ width: 1440, height: h });
  await page.goto(BASE + url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.screenshot({ path: path.join(__dirname, '..', out), fullPage: full });
  console.log('shot', out);
}

(async () => {
  const exe = findBrowser();
  const browser = await chromium.launch({ executablePath: exe });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1400 } });
  const page = await ctx.newPage();

  // The landing is the one page reviewed whole: its bands run well past one viewport.
  await shoot(page, '/', 'review-landing.png', 1400, true);
  await shoot(page, '/tracks', 'review-tracks.png');
  await shoot(page, '/pricing', 'review-pricing.png');

  await login(page, 'jordan@example.com');
  await shoot(page, '/tracks', 'review-rider.png');

  const ctx2 = await browser.newContext({ viewport: { width: 1440, height: 1400 } });
  const page2 = await ctx2.newPage();
  await login(page2, 'admin@motopass.example.com');
  await shoot(page2, '/admin', 'review-admin.png');
  await shoot(page2, '/admin/reports', 'review-reports.png');
  await shoot(page2, '/admin/tiers', 'review-tiers.png');

  await browser.close();
})();

/*
 * Generates the default rider avatars used across the app.
 *
 * The demo has no photo upload, so every seed account gets a deterministic
 * randomized pixel pattern instead of a fake photo of a real person. The
 * pattern is a horizontally mirrored 5x5 grid seeded from the account key, so
 * it is stable per account but differs between accounts. Colors stay on-brand:
 * each key keeps its own jersey/accent hue over the dark surface gradient.
 *
 * Run:
 *
 *   node scripts/gen-avatars.cjs
 *
 * Output: public/avatars/<key>.svg — referenced by User.avatarUrl in the seed.
 */
const fs = require('fs');
const path = require('path');

const palettes = {
  quinn:      { bg1: '#10251f', bg2: '#0d0f12', jersey: '#2fe0a0', accent: '#7df0c6' },
  alex:       { bg1: '#16242c', bg2: '#0d0f12', jersey: '#d6ff3f', accent: '#93ad2f' },
  jordan:     { bg1: '#2d1519', bg2: '#0d0f12', jersey: '#ff5a5f', accent: '#ff8a8f' },
  sam:        { bg1: '#151f2f', bg2: '#0d0f12', jersey: '#4aa3ff', accent: '#7cc0ff' },
  riley:      { bg1: '#1b2a19', bg2: '#0d0f12', jersey: '#7bd85a', accent: '#a8e88c' },
  taylor:     { bg1: '#2a1626', bg2: '#0d0f12', jersey: '#ff6ec7', accent: '#ffa6dd' },
  casey:      { bg1: '#2c2513', bg2: '#0d0f12', jersey: '#ffc63f', accent: '#ffe08a' },
  morgan:     { bg1: '#251b2f', bg2: '#0d0f12', jersey: '#b479ff', accent: '#d3b0ff' },
  devon:      { bg1: '#0f2b26', bg2: '#0d0f12', jersey: '#2fe0c0', accent: '#8bf3dd' },
  harper:     { bg1: '#2b1418', bg2: '#0d0f12', jersey: '#ff5a5f', accent: '#ff9aa0' },
  marcus:     { bg1: '#14233a', bg2: '#0d0f12', jersey: '#4aa3ff', accent: '#8cc6ff' },
  elena:      { bg1: '#2d1f12', bg2: '#0d0f12', jersey: '#ff9a3f', accent: '#ffc38f' },
  theo:       { bg1: '#1d2a16', bg2: '#0d0f12', jersey: '#8bd85a', accent: '#b6ec93' },
  priya:      { bg1: '#2a1630', bg2: '#0d0f12', jersey: '#e06eff', accent: '#f0aaff' },
  nadia:      { bg1: '#2c2713', bg2: '#0d0f12', jersey: '#ffd23f', accent: '#ffe98a' },
  jesse:      { bg1: '#122a2a', bg2: '#0d0f12', jersey: '#3fd6c4', accent: '#8bf0e4' },
  rowan:      { bg1: '#2a1a12', bg2: '#0d0f12', jersey: '#ff8a3f', accent: '#ffb98a' },
  skyler:     { bg1: '#1a1f2e', bg2: '#0d0f12', jersey: '#6f8cff', accent: '#aebeff' },
  parker:     { bg1: '#1c242e', bg2: '#0d0f12', jersey: '#9fb4c9', accent: '#cbd9e6' },
  op221mx:    { bg1: '#132730', bg2: '#0d0f12', jersey: '#3fd6c4', accent: '#7ff0e2' },
  opEastBend: { bg1: '#2b1e15', bg2: '#0d0f12', jersey: '#ff8a3f', accent: '#ffb27f' },
  opBusco:    { bg1: '#1a2330', bg2: '#0d0f12', jersey: '#6f8cff', accent: '#a8baff' },
  admin:      { bg1: '#1e2126', bg2: '#0d0f12', jersey: '#c9d1d9', accent: '#e6ebf0' },
};

// Deterministic PRNG (mulberry32) seeded from a string key, so a given account
// always renders the same pattern.
function rngFrom(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  let a = h >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const GRID = 5; // 5x5, left half randomized then mirrored
const SIZE = 400;
const CELL = SIZE / GRID;
const INSET = 6; // gutter between pixels
const RADIUS = 5;

function svg(key, p) {
  const rnd = rngFrom(key);

  // Left half of the grid (cols 0..2), then mirrored to cols 3..4.
  const on = [];
  const hot = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.ceil(GRID / 2); col++) {
      const filled = rnd() < 0.52;
      on[row * GRID + col] = filled;
      hot[row * GRID + col] = filled && rnd() < 0.3;
    }
  }
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < Math.floor(GRID / 2); col++) {
      const src = row * GRID + (GRID - 1 - col);
      on[src] = on[row * GRID + col];
      hot[src] = hot[row * GRID + col];
    }
  }

  // Guarantee some ink so no account renders an empty tile.
  if (!on.some(Boolean)) on[Math.floor(rnd() * GRID) * GRID + 2] = true;

  const pixels = [];
  for (let row = 0; row < GRID; row++) {
    for (let col = 0; col < GRID; col++) {
      const i = row * GRID + col;
      if (!on[i]) continue;
      const fill = hot[i] ? p.accent : p.jersey;
      const x = col * CELL + INSET;
      const y = row * CELL + INSET;
      const w = CELL - INSET * 2;
      pixels.push(`<rect x="${x}" y="${y}" width="${w}" height="${w}" rx="${RADIUS}" fill="${fill}"/>`);
    }
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${SIZE} ${SIZE}" width="${SIZE}" height="${SIZE}" role="img">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="${p.bg1}"/>
      <stop offset="1" stop-color="${p.bg2}"/>
    </linearGradient>
  </defs>
  <rect width="${SIZE}" height="${SIZE}" fill="url(#bg)"/>
  ${pixels.join('\n  ')}
</svg>
`;
}

const out = path.join(__dirname, '..', 'public', 'avatars');
fs.mkdirSync(out, { recursive: true });
for (const [key, p] of Object.entries(palettes)) {
  fs.writeFileSync(path.join(out, `${key}.svg`), svg(key, p));
}
console.log(`wrote ${Object.keys(palettes).length} pixel-pattern avatars to ${out}`);

/* Prove the gate's toast layer reads in the Astryx register while
   `enableAstryxUI` is on, and that the banner corner comes back with the flag
   off. Redeems one real day per run, so undo each rider afterwards:
     cd server && RIDER=<email> npx tsx scripts/undo-gate-redemption.ts
   (copy that script in from the moto-pass-reference skill first). */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = 'http://localhost:5180';
const RIDER = process.env.RIDER || 'riley@example.com';
const THEME = process.env.THEME || 'dark';
const TAG = process.env.TAG || 'astryx';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser() });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await ctx.newPage();
  page.on('console', (m) => {
    if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text().slice(0, 200));
  });
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.evaluate((t) => localStorage.setItem('motopass.theme', t), THEME);
  await page.fill('#email', 'ops@221mx.example.com');
  await page.fill('#password', 'dialed123');
  // The Astryx auth page's submit is `.axa-submit`; the plain `Login.tsx`
  // fallback is a bare `button.primary` inside its form (no type attribute).
  await page.click('.axa-form button.axa-submit, form button.primary, form button[type="submit"]');
  await page.waitForTimeout(1800);

  await page.goto(`${BASE}/operator/dashboard`, { waitUntil: 'networkidle' });
  await page.waitForSelector('#rider-search-email', { timeout: 8000 });
  await page.fill('#rider-search-email', RIDER);
  await page.waitForTimeout(200);
  await page.click('button.lookup-search-btn');
  await page.waitForSelector('.lookup-hits li', { timeout: 8000 });
  await page.click('.lookup-hits li');
  await page.waitForSelector('.gate-actions', { timeout: 8000 });
  await page.waitForTimeout(400);

  const labels = await page.$$eval('.gate-actions button', (bs) =>
    bs.map((b) => `${b.className} :: ${(b.textContent || '').trim()}`),
  );
  console.log('gate actions:', JSON.stringify(labels));
  await page.click('.gate-actions button.primary');
  // The approval lands through the page's one handler, then the toast enters.
  await page.waitForSelector('.axt-stack, .toast-stack', { timeout: 8000 });
  await page.waitForTimeout(500);

  const read = await page.evaluate(() => {
    const pick = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return { found: false };
      const cs = getComputedStyle(el);
      const box = el.getBoundingClientRect();
      return {
        found: true,
        cls: el.className,
        text: (el.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 120),
        bg: cs.backgroundColor,
        border: cs.borderTopColor,
        radius: cs.borderTopLeftRadius,
        font: cs.fontFamily.slice(0, 40),
        size: cs.fontSize,
        pad: cs.padding,
        shadow: cs.boxShadow.slice(0, 60),
        box: { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) },
      };
    };
    return {
      theme: document.documentElement.dataset.theme,
      astryxStack: pick('.axt-stack'),
      astryxToast: pick('.axt-toast'),
      astryxTitle: pick('.axt-title'),
      astryxDetail: pick('.axt-detail'),
      astryxMark: pick('.axt-mark'),
      astryxX: pick('.axt-x'),
      bannerStack: pick('.toast-stack'),
      banner: pick('.toast-stack .banner'),
      marginTop: document.querySelector('.axt-stack')
        ? getComputedStyle(document.querySelector('.axt-stack')).marginTop
        : null,
    };
  });
  console.log(JSON.stringify(read, null, 2));

  const shotDir = path.join(os.homedir(), 'opt-shots', 'motopass-toast');
  fs.mkdirSync(shotDir, { recursive: true });
  const box = (read.astryxToast.found ? read.astryxToast.box : read.banner.box) || null;
  await page.screenshot({ path: path.join(shotDir, `${TAG}-${THEME}-page.png`) });
  if (box) {
    await page.screenshot({
      path: path.join(shotDir, `${TAG}-${THEME}-corner.png`),
      clip: {
        x: Math.max(0, box.x - 16),
        y: Math.max(0, box.y - 16),
        width: Math.min(1440 - Math.max(0, box.x - 16), box.w + 32),
        height: Math.min(1000 - Math.max(0, box.y - 16), box.h + 32),
      },
    });
  }
  console.log('shots:', shotDir);

  // The exit: the × starts it, the row keeps its place for EXIT_MS (180) and is
  // then cut, so a notice fades down instead of blinking out of the corner.
  const dismiss = await page.evaluate(() => !!document.querySelector('.axt-x'));
  if (dismiss) {
    await page.click('.axt-x');
    const leaving = await page.$$eval('.axt-item.leaving', (n) => n.length);
    await page.waitForTimeout(400);
    const left = await page.$$eval('.axt-toast', (n) => n.length);
    console.log(JSON.stringify({ dismiss, leaving, leftAfterExit: left }));
  }
  await browser.close();
})();

// One-off: the two auth pages, signed out. Proves the routes, the redirect
// off the old `?mode=register` link, and the switch between them.
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = 'http://localhost:5180';
const exe = (() => {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const d of fs.readdirSync(root)) {
    if (!d.startsWith('chromium-')) continue;
    for (const sub of ['chrome-linux/chrome', 'chrome-linux/headless_shell']) {
      const p = path.join(root, d, sub);
      if (fs.existsSync(p)) return p;
    }
  }
  return undefined;
})();

(async () => {
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 950 } });
  const out = [];
  const say = (k, v) => { out.push(`${v ? 'OK  ' : 'FAIL'} ${k}`); };

  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  say('/login draws the sign-in form', (await page.textContent('h1')) === 'Sign in');
  say('/login has no name field', (await page.$('#name')) === null);
  say('/login carries the demo accounts', (await page.$('text=Demo accounts')) !== null);
  await page.screenshot({ path: 'login-page.png', fullPage: true });

  await page.click('button:has-text("Need an account? Register")');
  await page.waitForURL((u) => u.pathname === '/signup');
  say('the switch lands on /signup', new URL(page.url()).pathname === '/signup');
  say('/signup draws the create form', (await page.textContent('h1')) === 'Create account');
  say('/signup asks for a name', (await page.$('#name')) !== null);
  say('/signup drops the demo accounts', (await page.$('text=Demo accounts')) === null);
  say('/signup submits as Create account', /Create account/.test(await page.textContent('form')));
  await page.screenshot({ path: 'signup-page.png', fullPage: true });

  await page.click('button:has-text("Already have an account? Sign in")');
  await page.waitForURL((u) => u.pathname === '/login');
  say('the switch returns to /login', new URL(page.url()).pathname === '/login');

  // The old deep link, and the deep link carried across the switch.
  await page.goto(`${BASE}/login?mode=register`, { waitUntil: 'networkidle' });
  say('/login?mode=register redirects to /signup', new URL(page.url()).pathname === '/signup');
  await page.goto(`${BASE}/login?next=%2Ftracks%2Fperks`, { waitUntil: 'networkidle' });
  await page.click('button:has-text("Need an account? Register")');
  await page.waitForURL((u) => u.pathname === '/signup');
  say('the switch carries ?next across', page.url().includes('next=%2Ftracks%2Fperks'));

  // The pricing CTAs, signed out.
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await page.click('.tier-card:not(.popular) .tier-cta');
  await page.waitForURL((u) => u.pathname === '/signup');
  say('the free CTA opens /signup', new URL(page.url()).pathname === '/signup');
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await page.click('.tier-card.popular .tier-cta');
  await page.waitForURL((u) => u.pathname === '/signup');
  say('the paid CTA opens /signup', new URL(page.url()).pathname === '/signup');

  // The landing's free-tier CTA.
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  const href = await page.$eval('a:has-text("Create a free account")', (a) => new URL(a.href).pathname);
  say('the landing CTA points at /signup', href === '/signup');

  // Mobile reflow of both.
  await page.setViewportSize({ width: 390, height: 900 });
  for (const p of ['/login', '/signup']) {
    await page.goto(BASE + p, { waitUntil: 'networkidle' });
    const over = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
    say(`no horizontal overflow at 390px ${p}`, !over);
  }
  await page.screenshot({ path: 'signup-mobile.png', fullPage: true });

  console.log(out.join('\n'));
  console.log(out.some((l) => l.startsWith('FAIL')) ? '\nSOMETHING FAILED' : '\nall clear');
  await browser.close();
})();

/* Probe: the calendar date cards no longer print the event description.
 *   node scripts/probe-event-note.cjs     (dev server :5180, API :4010) */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.PROBE_BASE || 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await page.click('button[type="submit"], form button');
  await page.waitForTimeout(1400);
}

const read = (page) =>
  page.evaluate(() => ({
    cards: document.querySelectorAll('.event-edit-row, .event-row').length,
    notes: document.querySelectorAll('.event-note').length,
    sample: (document.querySelector('.event-edit-row, .event-row') || {}).innerText || '',
  }));

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser(), args: ['--no-sandbox'] });

  const rider = await (await browser.newContext({ viewport: { width: 1440, height: 1000 } })).newPage();
  await login(rider, 'quinn@example.com');
  await rider.goto(`${BASE}/tracks/calendar`, { waitUntil: 'networkidle' });
  await rider.waitForTimeout(900);
  console.log('rider /tracks/calendar', JSON.stringify(await read(rider)));

  const owner = await (await browser.newContext({ viewport: { width: 1440, height: 1000 } })).newPage();
  await login(owner, 'ops@221mx.example.com');
  await owner.goto(`${BASE}/operator/calendar`, { waitUntil: 'networkidle' });
  await owner.waitForTimeout(900);
  console.log('owner /operator/calendar', JSON.stringify(await read(owner)));

  const pub = await (await browser.newContext({ viewport: { width: 1440, height: 1000 } })).newPage();
  await pub.goto(`${BASE}/tracks/221-mx`, { waitUntil: 'networkidle' });
  await pub.waitForTimeout(900);
  console.log('venue /tracks/221-mx', JSON.stringify(await read(pub)));

  await browser.close();
})();

/* Ad-hoc probe: is the footer below the fold on a short page?
 *
 *   cd client && node scripts/probe-footer-fold.cjs
 *
 * Reads the footer's top edge against the viewport bottom at scroll 0, then
 * scrolls to the page foot and confirms it is reachable.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium_headless_shell-')) {
      const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
      if (fs.existsSync(p)) return p;
    }
  }
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium-')) {
      const p = path.join(root, dir, 'chrome-linux64', 'chrome');
      if (fs.existsSync(p)) return p;
    }
  }
  return null;
}

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser() });
  const page = await browser.newPage({ viewport: { width: 1600, height: 1250 } });

  // sign in as the operator (dialed123)
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', 'ops@221mx.example.com');
  await page.fill('#password', 'dialed123');
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);

  for (const route of ['/operator/dashboard', '/operator/reports']) {
    await page.goto(`${BASE}${route}`, { waitUntil: 'networkidle' });
    await page.waitForSelector('.site-footer', { timeout: 15000 });
    await page.waitForTimeout(600);
    const at0 = await page.evaluate(() => {
      const f = document.querySelector('.site-footer').getBoundingClientRect();
      return {
        footerTop: Math.round(f.top),
        footerH: Math.round(f.height),
        vh: window.innerHeight,
        docH: document.documentElement.scrollHeight,
