/** Loads /tracks with the network held for `hold` ms and reads the frame. */
async function frameOf(ctx, { hold = 6000, width = 1400, height = 900 } = {}) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width, height });
  await page.route('**/api/tracks*', async (route) => {
    await new Promise((r) => setTimeout(r, hold));
    route.continue();
  });
  await page.goto(`${BASE}/tracks`);
  await page.waitForSelector('.net-skel', { timeout: 15000 });
  await page.waitForTimeout(400);
  const read = await page.evaluate(() => {
    const q = (s) => document.querySelectorAll(s).length;
    const box = (s) => {
      const n = document.querySelector(s);
      if (!n) return null;
      const r = n.getBoundingClientRect();
      return { w: Math.round(r.width), h: Math.round(r.height) };
    };
    return {
      rows: q('.net-skel-row'),
      rowH: Math.round(document.querySelector('.net-skel-row')?.getBoundingClientRect().height ?? 0),
      filter: q('.net-skel .sk-filter'),
      meters: q('.net-skel .sk-meter'),
      idBar: q('.net-skel .sk-id'),
      sort: q('.net-skel .sk-sort'),
      rail: box('.net-skel .pass-aux'),
      map: box('.net-skel .map-pane'),
      pageH: Math.round(document.querySelector('.net-skel').getBoundingClientRect().height),
      busy: document.querySelector('.net-skel')?.getAttribute('aria-busy'),
    };
  });
  return { page, read };
}

(async () => {
  fs.mkdirSync(SHOTS, { recursive: true });
  const browser = await chromium.launch({ executablePath: findBrowser(), args: ['--no-sandbox'] });

  // --- A visitor -----------------------------------------------------------
  {
    const ctx = await browser.newContext();
    const { page, read } = await frameOf(ctx);
    check('the frame is the whole page', read.pageH >= 700, `h=${read.pageH}`);
    check('the rail floats in its own place', read.rail && read.rail.w === 384, JSON.stringify(read.rail));
    check('the canvas holds the screen', read.map && read.map.h >= 700, JSON.stringify(read.map));
    check('venue lines are drawn', read.rows === 14, String(read.rows));
    check('a visitor gets no slice control', read.filter === 0);
    check('a visitor gets no day read', read.meters === 0);
    check('the head still names who is reading', read.idBar === 1);
    check('the sort control is in the head', read.sort === 1);
    check('announced as busy', read.busy === 'true');
    await page.screenshot({ path: path.join(SHOTS, 'net-skel-visitor.png') });

    // The loaded page must land on the same frame.
    await page.waitForSelector('.day-row', { timeout: 20000 });
    await page.waitForTimeout(600);
    const loaded = await page.evaluate(() => {
      const b = (s) => {
        const r = document.querySelector(s)?.getBoundingClientRect();
        return r ? { w: Math.round(r.width), h: Math.round(r.height) } : null;
      };
      return { rail: b('.pass-aux'), map: b('.map-pane'), row: b('.day-row') };
    });
    check(
      'a venue line is as tall as the one that replaces it',
      Math.abs(loaded.row.h - read.rowH) <= 2,
      `${read.rowH} vs ${loaded.row.h}`
    );
    check(
      'the rail lands where the frame drew it',
      loaded.rail && Math.abs(loaded.rail.w - read.rail.w) <= 1 && Math.abs(loaded.rail.h - read.rail.h) <= 2,
      `${JSON.stringify(read.rail)} vs ${JSON.stringify(loaded.rail)}`
    );
    check(
      'the canvas lands where the frame drew it',
      loaded.map && Math.abs(loaded.map.h - read.map.h) <= 2,
      `${JSON.stringify(read.map)} vs ${JSON.stringify(loaded.map)}`
    );
    await page.screenshot({ path: path.join(SHOTS, 'net-loaded-visitor.png') });

    // Phone: the stacked column, with the seam button's own bar. Its own load,
    // held again, so the frame can be read before anything lands.
    const phoneBoxes = () => {
      const b = (s) => {
        const r = document.querySelector(s)?.getBoundingClientRect();
        return r ? { y: Math.round(r.top), h: Math.round(r.height) } : null;
      };
      return {
        rail: b('.pass-aux'),
        map: b('.map-pane'),
        handle: b('.rail-toggle-row'),
        handleDisplay: getComputedStyle(document.querySelector('.rail-toggle-row')).display,
      };
    };
    await page.close();
    const ph = await ctx.newPage();
    await ph.setViewportSize({ width: 390, height: 844 });
    await ph.route('**/api/tracks*', async (route) => {
      await new Promise((r) => setTimeout(r, 6000));
      route.continue();
    });
    await ph.goto(`${BASE}/tracks`);
    await ph.waitForSelector('.net-skel', { timeout: 15000 });
    await ph.waitForTimeout(400);
    const phoneSkel = await ph.evaluate(phoneBoxes);
    await ph.screenshot({ path: path.join(SHOTS, 'net-skel-phone.png') });
    await ph.waitForSelector('.day-row', { timeout: 20000 });
    await ph.waitForTimeout(400);
    const phoneLoaded = await ph.evaluate(phoneBoxes);
    check('stacked, the list sits under the map', phoneSkel.rail.y > phoneSkel.map.y + phoneSkel.map.h - 2, JSON.stringify(phoneSkel));
    check('the seam row is there on a phone', phoneSkel.handleDisplay === 'flex', phoneSkel.handleDisplay);
    check(
      'the phone split is the loaded one',
      Math.abs(phoneSkel.map.h - phoneLoaded.map.h) <= 2 &&
        Math.abs(phoneSkel.rail.h - phoneLoaded.rail.h) <= 2 &&
        Math.abs(phoneSkel.map.y - phoneLoaded.map.y) <= 1,
      `${JSON.stringify(phoneSkel)} vs ${JSON.stringify(phoneLoaded)}`
    );
    await ctx.close();
  }

  // --- The free tier -------------------------------------------------------
  {
    const ctx = await browser.newContext();
    await login(ctx, 'quinn@example.com');
    const { page, read } = await frameOf(ctx, { hold: 6000 });
    check('a free rider gets the slice control', read.filter === 1);
    check('a free rider gets no day read', read.meters === 0);
    await page.screenshot({ path: path.join(SHOTS, 'net-skel-free.png') });
    await ctx.close();
  }

  // --- A paid rider --------------------------------------------------------
  {
    const ctx = await browser.newContext();
    await login(ctx, 'alex@example.com');
    const { page, read } = await frameOf(ctx, { hold: 6000 });
    check('a paid rider gets the slice control', read.filter === 1);
    check('a paid rider gets the day read on every line', read.meters === 14, String(read.meters));
    await page.screenshot({ path: path.join(SHOTS, 'net-skel-paid.png') });
    await ctx.close();
  }

  // --- An operator ---------------------------------------------------------
  {
    const ctx = await browser.newContext();
    await login(ctx, 'ops@221mx.example.com');
    const { page, read } = await frameOf(ctx, { hold: 6000 });
    check('an operator gets no slice control', read.filter === 0);
    check('an operator gets no day read', read.meters === 0);
    await page.screenshot({ path: path.join(SHOTS, 'net-skel-operator.png') });
    await ctx.close();
  }

  await browser.close();
  console.log(fails ? `\n${fails} FAILED` : '\nall checks passed');
  process.exit(fails ? 1 : 0);
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

