  if (fs.existsSync(p)) exe = p;
}
const BASE = process.env.MAP_BASE || 'http://localhost:5180';
let fails = 0;
const check = (l, ok, x) => { if (ok) console.log('OK   ' + l); else { fails++; console.log('FAIL ' + l + (x === undefined ? '' : ' — ' + x)); } };

(async () => {
  const b = await chromium.launch(exe ? { executablePath: exe } : {});
  const p = await b.newPage({ viewport: { width: 390, height: 844 } });
  const errs = []; p.on('pageerror', e => errs.push(String(e.message)));
  await p.goto(BASE + '/tracks', { waitUntil: 'networkidle' });
  await p.waitForSelector('.day-row', { timeout: 25000 });
  await p.waitForTimeout(500);
  const bx = (s) => p.$eval(s, n => { const r = n.getBoundingClientRect(); return { top: Math.round(r.top), h: Math.round(r.height) }; });
