  check('the map is not covered', (await bx('.map-pane')).h >= 118);

  // drag up: taller panel, shorter map
  let h = await bx('.rail-resize');
  await p.mouse.move(195, h.top + 13); await p.mouse.down(); await p.mouse.move(195, 90, { steps: 12 }); await p.mouse.up();
  await p.waitForTimeout(250);
  const up = { map: await bx('.map-pane'), panel: await bx('.venue-float') };
  check('dragging up grows the picked panel', up.panel.h > panel.h && up.map.h < (await bx('.map-pane')).h + 1, `${panel.h} → ${up.panel.h}, map ${up.map.h}`);
  check('the map keeps its strip', up.map.h >= 118, up.map.h);

  // drag down: floor, never gone
  h = await bx('.rail-resize');
  await p.mouse.move(195, h.top + 13); await p.mouse.down(); await p.mouse.move(195, 830, { steps: 12 }); await p.mouse.up();
  await p.waitForTimeout(250);
  const down = await bx('.venue-float');
  check('the picked panel keeps a readable floor', down.h >= 166, down.h);
  check('its name is still on screen', await p.isVisible('.venue-float .track-panel-body h2'));
  check('the pair still fits one screen', (await bx('.map-pane')).h + 26 + down.h <= 844 - 40, JSON.stringify({ map: (await bx('.map-pane')).h, panel: down.h }));

