/* Probe: the network page's stacked panel is resizable both ways.
 *
 *   node scripts/probe-rail-resize.cjs      (dev server on :5180)
 *
 * Asserts the handle is only a stacked-surface control, that dragging up grows
 * the list while a strip of map stays on screen, that dragging down shrinks the
 * list to its floor rather than hiding it, and that the pair keeps one screen.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.MAP_BASE || 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, extra) {
  if (ok) console.log(`OK   ${label}`);
  else {
    fails++;
    console.log(`FAIL ${label}${extra === undefined ? '' : ` — ${extra}`}`);
  }
}

const box = (page, sel) =>
  page.$eval(sel, (n) => {
    const r = n.getBoundingClientRect();
    return { top: Math.round(r.top), height: Math.round(r.height), width: Math.round(r.width) };
  });

/** Drag the handle to an absolute viewport y. */
async function dragTo(page, y) {
  const h = await box(page, '.rail-resize');
  const x = h.width / 2 + (await box(page, '.rail-resize')).top * 0;
  const mid = { x, y: h.top + h.height / 2 };
  await page.mouse.move(mid.x, mid.y);
  await page.mouse.down();
  await page.mouse.move(mid.x, y, { steps: 12 });
  await page.mouse.up();
  await page.waitForTimeout(160);
}

(async () => {
  const exe = findBrowser();
  const browser = await chromium.launch(exe ? { executablePath: exe } : {});

  // ---- a phone's width: stacked, with the handle -------------------------
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.day-row', { timeout: 20000 });
  await page.waitForTimeout(400);

  check('the handle is on screen at a phone width', await page.isVisible('.rail-resize'));
  check(
    'the handle sits between the map and the list',
    (await box(page, '.rail-resize')).top >= (await box(page, '.map-pane')).top &&
      (await box(page, '.rail-resize')).top <= (await box(page, '.pass-aux')).top
  );

  const start = {
    map: (await box(page, '.map-pane')).height,
    rail: (await box(page, '.pass-aux')).height,
    win: await page.evaluate(() => window.innerHeight),
  };
  check('the panel opens with the list on the screen', start.rail > 200, start.rail);
  // Measured off the header itself: `--header-h` is written by a script in
  // index.html and reads 0 before it runs, which made this check lie on the
  // deployed build while the layout was right.
  const headerH = await page.evaluate(() => {
    const el = document.querySelector('header, .site-header');
    return el ? Math.round(el.getBoundingClientRect().height) : 57;
  });
  check(
    'the pair opens to one screen',
    Math.abs(start.map + 26 + start.rail - (start.win - headerH)) < 4,
    JSON.stringify({ ...start, headerH })
  );

  // Drag the boundary far up: the list grows, a strip of map survives.
  await dragTo(page, 40);
  const up = {
    map: (await box(page, '.map-pane')).height,
    rail: (await box(page, '.pass-aux')).height,
  };
  check('dragging up grows the list', up.rail > start.rail, `${start.rail} → ${up.rail}`);
  check('the map cannot be completely covered', up.map >= 118, up.map);
  check('the list never runs off the screen', up.rail + 26 + up.map <= start.win + 2, JSON.stringify(up));

  // Drag the boundary far down: the panel shrinks to its floor, never to nothing.
  await dragTo(page, 830);
  const down = {
    map: (await box(page, '.map-pane')).height,
    rail: (await box(page, '.pass-aux')).height,
  };
  check('dragging down grows the map', down.map > up.map, `${up.map} → ${down.map}`);
  check('the panel cannot be completely hidden', down.rail >= 166, down.rail);
  check('the panel keeps a row on screen', await page.isVisible('.day-row'), down.rail);
  check(
    'the list is the scroller once it is short',
    await page.$eval('.pass-aux .day-grid', (n) => n.scrollHeight > n.clientHeight)
  );

  // Keyboard: arrows trade the same step.
  await page.focus('.rail-resize');
  const beforeKey = (await box(page, '.pass-aux')).height;
  await page.keyboard.press('ArrowUp');
  const afterKey = (await box(page, '.pass-aux')).height;
  check('arrows resize the panel too', afterKey === beforeKey + 24, `${beforeKey} → ${afterKey}`);

  // Double-click restores the default split.
  await page.dblclick('.rail-resize');
  const reset = (await box(page, '.pass-aux')).height;
  check('a double-click restores the default split', Math.abs(reset - start.rail) <= 2, `${start.rail} vs ${reset}`);

  await page.screenshot({ path: 'resize-phone.png', fullPage: true });

  // A pick takes the list's seat, and the handle with it.
  await page.click('.day-row:nth-child(1) .day-open');
  await page.waitForSelector('.venue-float .track-panel', { timeout: 5000 });
  check('a pick puts the handle away with the list', !(await page.isVisible('.rail-resize')));

  await page.close();

  // ---- a desktop width: side-by-side, no handle -------------------------
  const wide = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await wide.goto(`${BASE}/tracks`, { waitUntil: 'networkidle' });
  await wide.waitForSelector('.day-row', { timeout: 20000 });
  await wide.waitForTimeout(400);
  check('the handle is not rendered on the canvas', !(await wide.isVisible('.rail-resize')));
  check(
    'the rail still floats over the map',
    (await box(wide, '.pass-aux')).width === 384 && (await box(wide, '.pass-aux')).top === (await box(wide, '.map-pane')).top + 16,
    JSON.stringify(await box(wide, '.pass-aux'))
  );
  await wide.close();

  await browser.close();
  console.log(fails ? `\n${fails} FAILED` : '\nall checks passed');
  process.exit(fails ? 1 : 0);
})();

