 * that decide it, into ~/opt-shots/motopass-astryx-nav/ (space-free, ready for
 * MEDIA:).
 *
 *   node scripts/shoot-astryx-nav.cjs
 *
 * Reuses the dev server on :5180 and the Chromium under ~/.cache/ms-playwright.
 *
 * States: signed out and a rider, dark and light, at rest and scrolled, a phone
 * at 390, and the operator's list at 768 with the compact Menu closed and open.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { chromium } = require('playwright-core');

const BASE = process.env.BASE || 'http://localhost:5180';
const OUT = path.join(os.homedir(), 'opt-shots', 'motopass-astryx-nav');
const PASSWORD = 'dialed123';

function chromiumPath() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  const picks = [];
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium_headless_shell-')) {
      picks.push(path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell'));
      picks.push(path.join(root, dir, 'chrome-linux', 'headless_shell'));
    }
    if (dir.startsWith('chromium-')) {
      picks.push(path.join(root, dir, 'chrome-linux64', 'chrome'));
      picks.push(path.join(root, dir, 'chrome-linux', 'chrome'));
    }
  }
  return picks.find((p) => fs.existsSync(p)) || null;
}

const THEME = (t) =>
  `try { ${t === 'light' ? "localStorage.setItem('motopass.theme','light')" : "localStorage.removeItem('motopass.theme')"} } catch (e) {}`;

async function header(page, file) {
  await page.evaluate(() => document.fonts.ready);
  await page.waitForSelector('header');
  await page.screenshot({ path: path.join(OUT, file), clip: await clip(page) });
  const info = await page.evaluate(() => {
    const h = document.querySelector('header');
    const brand = document.querySelector('.ax-brand');
    return {
      cls: h.className,
      headerH: Math.round(h.getBoundingClientRect().height),
      brandColor: brand ? getComputedStyle(brand).color : null,
      linkCount: document.querySelectorAll('.ax-link, .ax-menu-item').length,
      active: (document.querySelector('.ax-link.is-active, .ax-menu-item.is-active') || {}).textContent || null,
      overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    };
  });
  console.log(file, JSON.stringify(info));
}

async function clip(page) {
  const box = await page.evaluate(() => ({
    w: document.documentElement.clientWidth,
    h: Math.min(220, window.innerHeight),
  }));
  return { x: 0, y: 0, width: box.w, height: box.h };
}

