const PATTERNS = [
  ['6 on / 4 off', 6, 4],
  ['6 on / 5 off', 6, 5],
  ['8 on / 6 off', 8, 6],
  ['10 on / 6 off', 10, 6],
];

function field([label, dash, gap]) {
  const layers = ['90deg', '90deg', '0deg', '0deg']
    .map((a) => `repeating-linear-gradient(${a}, #ff8a3f 0 ${dash}px, transparent ${dash}px ${dash + gap}px)`)
    .join(',\n      ');
  return `
  <div class="item">
    <div class="cap">${label}</div>
    <div class="scan-redeem" style="--dash:${layers}; color:#e8eaed; background:#14171c;
      border-radius:6px; padding:32px 24px; text-align:center; font:600 17px/1 system-ui, sans-serif;">
      Redeem Pass
      <span class="edge" style="--dash:${layers};"></span>
    </div>
  </div>`;
}

const html = `<!doctype html><meta charset="utf-8">
<style>
  body { margin:0; padding:22px; background:#0d0f12; color:#8b93a1; font:13px/1.4 system-ui, sans-serif; }
  .item { margin-bottom:18px; }
  .cap { margin:0 0 6px; font:600 11px/1 ui-monospace, monospace; letter-spacing:.08em; text-transform:uppercase; color:#8b93a1; }
  .scan-redeem { position:relative; }
  .edge { position:absolute; inset:0; border-radius:6px; pointer-events:none; background-image:var(--dash);
    background-size:100% 1px,100% 1px,1px 100%,1px 100%;
    background-position:0 0,0 100%,0 0,100% 0; background-repeat:no-repeat; }
</style>
${PATTERNS.map(field).join('')}`;

(async () => {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  let exe = null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) { exe = p; break; }
  }
  if (!exe) for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) { exe = p; break; }
  }
  const tmp = path.join(os.tmpdir(), 'redeem-patterns.html');
  fs.writeFileSync(tmp, html);
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 900, height: 460 }, deviceScaleFactor: 2 });
  await page.goto('file://' + tmp);
  await page.waitForTimeout(300);
  const out = path.join(os.homedir(), 'opt-shots', 'redeem-patterns.png');
  fs.mkdirSync(path.dirname(out), { recursive: true });
  await page.locator('body').screenshot({ path: out });
  console.log('wrote', out);
  await browser.close();
})();

/* Crop one PNG per option section of the Moto Pass event date/time pack.
   Uses the repo's playwright-core plus the browser already in ~/.cache/ms-playwright. */
const path = require('path');
const os = require('os');
const fs = require('fs');
const { chromium } = require('playwright-core');

const URL = 'http://localhost:5180/event-date-options.html';
const OUT = path.join(os.homedir(), 'opt-shots', 'motopass-event-date');
const IDS = ['a', 'b', 'c', 'd', 'e', 'f'];

const findChrome = () => {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  throw new Error('no chromium in ~/.cache/ms-playwright');
};

const WAIT_IMGS = `() => Promise.race([
  Promise.all([...document.images].map(i => i.complete ? 1 : new Promise(r => { i.onload = i.onerror = r; }))),
  new Promise(r => setTimeout(r, 9000)),
])`;

const INFO = (sid) => {
  const el = document.querySelector('#' + sid);
  return {
    h: Math.round(el.getBoundingClientRect().height),
    broken: [...el.querySelectorAll('img')].filter((i) => i.complete && i.naturalWidth === 0).map((i) => i.getAttribute('src')),
    clipped: [...el.querySelectorAll('*')].filter((e) => e.clientHeight > 0 && e.scrollHeight > e.clientHeight + 2).length,
  };
};

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const browser = await chromium.launch({ executablePath: findChrome() });
  const pg = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });
  const errs = [];
  pg.on('pageerror', (e) => errs.push(String(e)));
  pg.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
  await pg.goto(URL, { waitUntil: 'domcontentloaded' });
  await pg.evaluate(WAIT_IMGS);
  await pg.evaluate(() => document.fonts.ready.then(() => 1));
  await pg.waitForTimeout(1000);
  for (const sid of IDS) {
    console.log(sid, JSON.stringify(await pg.evaluate(INFO, sid)));
    const el = await pg.$('#' + sid);
    await el.screenshot({ path: path.join(OUT, sid + '.png') });
  }
  console.log('errors:', errs.slice(0, 6));
  await browser.close();
})();

