/**
 * Shoots the header proposal: one section crop per take, the tablet/phone
 * cluster, and the light-theme row.
 *
 *   node scripts/shoot-nav-astryx-options.cjs
 *
 * Reuses the dev server on :5180 and the Chromium under ~/.cache/ms-playwright.
 * Writes into ~/opt-shots/motopass-nav-astryx/ (space-free, ready for MEDIA:).
 *
 * Traps handled:
 *   - `waitUntil: 'load'` hangs on the Figtree stylesheet; 'domcontentloaded'
 *     plus an explicit `document.fonts.ready` is what returns.
 *   - the proposal builds its rows in JS, so the shot waits for `.take` nodes
 *     rather than for the first paint.
 *   - the hero photograph is a real file under /tracks/, so the shot waits for
 *     the background image to decode or the row reads flat.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { chromium } = require('playwright-core');

const URL = process.env.NAV_URL || 'http://localhost:5180/nav-astryx-options.html';
const OUT = path.join(os.homedir(), 'opt-shots', 'motopass-nav-astryx');

function chromiumPath() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  const picks = [];
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium_headless_shell-')) {
      picks.push(path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell'));
      picks.push(path.join(root, dir, 'chrome-linux', 'headless_shell'));
    }
    if (dir.startsWith('chromium-')) {
      picks.push(path.join(root, dir, 'chrome-linux64', 'chrome'));
      picks.push(path.join(root, dir, 'chrome-linux', 'chrome'));
    }
  }
  return picks.find((p) => fs.existsSync(p)) || null;
}

(async () => {
  const exe = chromiumPath();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  fs.mkdirSync(OUT, { recursive: true });

  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });

  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('response', (r) => { if (r.status() >= 400) errors.push(`${r.status()} ${r.url()}`); });

  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await page.evaluate(() => document.fonts.ready.then(() => 1));
  await page.waitForSelector('.take-a .nav', { timeout: 10000 });
  await page.locator('.take-a').first().screenshot({ path: path.join(OUT, 'rule.png') });

  // The photographic row is a CSS background: decode it before shooting.
  await page.evaluate(async () => {
    const img = new Image();
    img.src = '/tracks/221-mx.jpg';
    await img.decode().catch(() => {});
  });
  await page.waitForTimeout(400);

  const counts = await page.evaluate(() => ({
    takes: document.querySelectorAll('.take').length,
    navs: document.querySelectorAll('.nav').length,
    light: document.querySelectorAll('.demo.light').length,
    brandInk: getComputedStyle(document.querySelector('.take-a .brand')).color,
  }));
  console.log('counts:', JSON.stringify(counts));

  await page.screenshot({ path: path.join(OUT, 'overview.png'), fullPage: true });

  for (const id of ['a', 'b', 'c']) {
    await page.locator(`.take-${id}:not(.rule)`).screenshot({ path: path.join(OUT, `take-${id}.png`) });
  }
  // The compaction rule is a rule of the nav, not of a take — its own crop.
  await page.locator('.take.rule').screenshot({ path: path.join(OUT, 'take-rule.png') });

  // The tablet/phone cluster of the recommended take, then its light row.
  await page.locator('.take-a:not(.rule) .row2').nth(1).screenshot({ path: path.join(OUT, 'widths.png') });
  await page.locator('.take-a:not(.rule) .demo.light').screenshot({ path: path.join(OUT, 'light.png') });

  console.log('errors:', errors.length ? errors : 'none');
  console.log('out:', OUT);
  await browser.close();
})();

/**
 * Shoots the "what the pass carries" option pack, one crop per section.
 *
 *   node scripts/shoot-pass-carries-options.cjs
 *
 * Reuses the dev server on :5180 and the Chromium already under
 * ~/.cache/ms-playwright, so it downloads nothing. Writes into
 * ~/opt-shots/motopass-pass-carries/ (space-free, ready for MEDIA: lines).
 *
 * Traps this handles, all of which cost time before:
 *   - `waitUntil: 'load'` hangs on the Figtree stylesheet; 'domcontentloaded'
 *     plus an explicit bounded font/image wait is the one that returns.
 *   - `document.fonts.ready` is a FontFaceSet and is not serialisable, so the
 *     evaluate never settles — promise a value out of it.
 *   - a section screenshot is taken after scrolling it to the top: rects read
 *     at scroll 0, and smooth scrolling is switched off first, or the crop
 *     lands mid-animation on the section above.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { chromium } = require('playwright-core');

const URL = process.env.PACK_URL || 'http://localhost:5180/pass-carries-astryx-options.html';
const OUT = path.join(os.homedir(), 'opt-shots', 'motopass-pass-carries');

function chromiumPath() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  const picks = [];
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium_headless_shell-')) {
      picks.push(path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell'));
      picks.push(path.join(root, dir, 'chrome-linux', 'headless_shell'));
    }
    if (dir.startsWith('chromium-')) {
      picks.push(path.join(root, dir, 'chrome-linux64', 'chrome'));
      picks.push(path.join(root, dir, 'chrome-linux', 'chrome'));
    }
  }
  return picks.find((p) => fs.existsSync(p)) || null;
}

(async () => {
  const exe = chromiumPath();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  fs.mkdirSync(OUT, { recursive: true });

  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 }, deviceScaleFactor: 2 });

  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await page.evaluate(() => document.fonts.ready.then(() => 1));
  await page.addStyleTag({ content: '*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}' });

  const ids = await page.evaluate(() => [...document.querySelectorAll('section.opt')].map((s) => s.id));
  if (!ids.length) throw new Error('no sections found');

  for (const id of ids) {
    const info = await page.evaluate((sid) => {
      const el = document.getElementById(sid);
      window.scrollTo(0, el.getBoundingClientRect().top + window.scrollY);
      return { h: Math.round(el.getBoundingClientRect().height) };
    }, id);
    await page.waitForTimeout(120);
    const el = await page.$('#' + id);
    await el.screenshot({ path: path.join(OUT, `${id}.png`) });
    const stats = await page.evaluate((sid) => {
      const root = document.getElementById(sid);
      const broken = [...root.querySelectorAll('img')].filter((i) => i.complete && i.naturalWidth === 0).length;
      const clipped = [...root.querySelectorAll('*')].filter((n) => n.scrollWidth > n.clientWidth + 1 && getComputedStyle(n).overflow === 'hidden').length;
      return { broken, clipped };
    }, id);
    console.log(`${id}: h=${info.h} broken=${stats.broken} clipped=${stats.clipped}`);
  }

  console.log('errors:', errors.length ? errors : 'none');
  console.log('out:', OUT);
  await browser.close();
})();

/* Shots of the rider profile's two form sheets (/user): the page as it opens,
