 *
 *   node scripts/shoot-profile-sheets.cjs
 *
 * Writes into ~/opt-shots/motopass-profile-sheets/. Read-only: it signs in as
 * the seeded free rider and never submits a form.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.PROFILE_BASE || 'http://localhost:5180';
