 * MEDIA: lines): a full page at 1440, four band crops, and a phone frame.
 *
 * Traps handled: 'load' hangs on the Figtree stylesheet (domcontentloaded +
 * explicit fonts ready), and the map is a network surface, so the harness
 * waits for loaded tiles before shooting or the pane reads flat grey.
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { chromium } = require('playwright-core');

const URL = process.env.PROFILE_URL || 'http://localhost:5180/track-profile-astryx-mirror.html';
const OUT = path.join(os.homedir(), 'opt-shots', 'motopass-track-profile-astryx');

function chromiumPath() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  const picks = [];
  for (const dir of fs.readdirSync(root)) {
    if (dir.startsWith('chromium_headless_shell-')) {
      picks.push(path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell'));
      picks.push(path.join(root, dir, 'chrome-linux', 'headless_shell'));
    }
    if (dir.startsWith('chromium-')) {
      picks.push(path.join(root, dir, 'chrome-linux64', 'chrome'));
      picks.push(path.join(root, dir, 'chrome-linux', 'chrome'));
    }
  }
  return picks.find((p) => fs.existsSync(p)) || null;
}

async function settle(page) {
  await page.evaluate(() => document.fonts.ready.then(() => 1));
  await page.waitForSelector('#heroImg[src]', { timeout: 15000 });
  await page.waitForFunction(() => document.querySelectorAll('img.leaflet-tile-loaded').length > 12, null, { timeout: 20000 })
    .catch(() => console.warn('tiles did not finish; shooting anyway'));
  await page.waitForTimeout(700);
}

(async () => {
  const exe = chromiumPath();
  if (!exe) { console.error('No Playwright Chromium found in ~/.cache/ms-playwright.'); process.exit(1); }
  fs.mkdirSync(OUT, { recursive: true });

  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });

  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await settle(page);

  await page.screenshot({ path: path.join(OUT, 'page-full.png'), fullPage: true });

  const bands = [
    ['top', '.ax-page'],
    ['location', '.ax-loc'],
    ['schedule', '#schedule'],
    ['reviews', '#reviews'],
  ];
  for (const [name, sel] of bands) {
    const el = await page.$(sel);
    if (!el) { console.warn('missing', sel); continue; }
    await el.scrollIntoViewIfNeeded();
    await page.waitForTimeout(250);
    const box = await el.boundingBox();
    if (name === 'top') {
      // the first screen: gallery through the operator note
      await page.evaluate(() => window.scrollTo(0, 0));
      await page.waitForTimeout(250);
      await page.screenshot({ path: path.join(OUT, 'hero.png'), clip: { x: 0, y: 0, width: 1440, height: 900 } });
    } else {
      await page.screenshot({
        path: path.join(OUT, name + '.png'),
        clip: { x: 0, y: Math.max(0, box.y + (await page.evaluate(() => window.scrollY)) - 40), width: 1440, height: Math.min(box.height + 80, 1600) },
        fullPage: true,
      });
    }
  }

  // Phone frames at 390: the first screen, then the schedule block. Full-page
  // phone PNGs are too tall to read (and too big to hand over), so shoot crops.
  const phone = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true });
  await phone.goto(URL, { waitUntil: 'domcontentloaded' });
  await settle(phone);
  await phone.screenshot({ path: path.join(OUT, 'phone.png'), clip: { x: 0, y: 0, width: 390, height: 1500 }, fullPage: true });
  await phone.evaluate(() => document.querySelector('#schedule').scrollIntoView());
  await phone.waitForTimeout(400);
  await phone.screenshot({ path: path.join(OUT, 'phone-schedule.png'), clip: { x: 0, y: 0, width: 390, height: 844 } });

  console.log('wrote', OUT);
  console.log('errors:', errors.length ? errors : 'none');
  const dims = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    innerW: window.innerWidth,
    height: document.documentElement.scrollHeight,
    photos: document.querySelectorAll('#gallery img').length,
    events: document.querySelectorAll('.ax-event').length,
    reviews: document.querySelectorAll('.ax-rev').length,
  }));
  console.log(dims);

  await browser.close();
})();

