  await page.goto(URL, { waitUntil: 'domcontentloaded' });
  await page.evaluate(() => document.fonts.ready.then(() => 1));
  await page.waitForSelector('.day-row', { timeout: 20000 });
  // The rail's own marker that the register is on, not a guess from the tokens.
  const on = await page.evaluate(() => document.querySelector('.pass-page').classList.contains('axt-page'));
  console.log(`axt-page on root: ${on}`);
  await page.waitForFunction(
    () => document.querySelectorAll('img.leaflet-tile-loaded').length > 20,
    null,
    { timeout: 20000 }
  ).catch(() => {});
  await page.waitForTimeout(600);
  await page.screenshot({ path: path.join(OUT, 'network.png') });

  // Pick 4-State (the venue the reference screenshot had open).
  await page.click('.day-row:nth-child(2) .day-open');
  await page.waitForSelector('.venue-float .track-panel', { timeout: 8000 });
  await page.waitForTimeout(1600);
  await page.screenshot({ path: path.join(OUT, 'picked.png') });
  await page.locator('.venue-float').screenshot({ path: path.join(OUT, 'inspector.png') });
  await page.locator('.pass-aux').screenshot({ path: path.join(OUT, 'rail.png') });

  const read = await page.evaluate(() => {
    const box = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
