    };
    const v = document.querySelector('.venue-float');
    const vx = v.getBoundingClientRect();
    const rel = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { left: Math.round(r.left - vx.left), right: Math.round(vx.right - r.right), top: Math.round(r.top - vx.top), h: Math.round(r.height) };
    };
    const name = document.querySelector('.track-panel-head h2');
    const pill = document.querySelector('.track-panel-head .status-pill');
    const prof = document.querySelector('.track-panel-links a.track-links-btn:not(.track-links-icon)');
