      socialsRight: socials ? Math.round(vx.right - socials.getBoundingClientRect().right) : null,
      nameMid: name ? Math.round((name.getBoundingClientRect().top + name.getBoundingClientRect().bottom) / 2 - vx.top) : null,
      pillMid: pill ? Math.round((pill.getBoundingClientRect().top + pill.getBoundingClientRect().bottom) / 2 - vx.top) : null,
      rowH: Math.round(document.querySelector('.day-row').getBoundingClientRect().height),
      rows,
    };
  });
  console.log(JSON.stringify(read, null, 1));

  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(900);
  await page.screenshot({ path: path.join(OUT, 'phone.png') });

  // The light palette is a second set of the same tokens; a dark island on a
  // light page is the failure mode to catch here, not contrast.
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.evaluate(() => {
    localStorage.setItem('motopass.theme', 'light');
    location.reload();
  });
  await page.waitForSelector('.day-row', { timeout: 20000 });
  await page.click('.day-row:nth-child(2) .day-open');
  await page.waitForSelector('.venue-float .track-panel', { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(1500);
  await page.screenshot({ path: path.join(OUT, 'picked-light.png') });
  await page.evaluate(() => localStorage.removeItem('motopass.theme'));

  console.log('errors:', errors.length ? errors : 'none');
  console.log('out:', OUT);
  await browser.close();
})();

/**
