    { timeout: 20000 }
  ).catch(() => {});
  await page.waitForTimeout(600);

  const rows = await page.evaluate(() => document.querySelectorAll('.ax-row').length);
  const count = await page.textContent('#count');
  console.log(`rows=${rows} count=${count}`);

  await page.screenshot({ path: path.join(OUT, 'canvas.png') });

  // The pick: 4-State, the venue the reference screenshot had open, so the two
