  await page.click('.ax-row:has-text("4-State")');
  await page.waitForSelector('.ax-venue:not([hidden]) .ax-hours tr', { timeout: 5000 });
  await page.waitForTimeout(1400); // flyTo settles, tiles redraw
  const open = await page.evaluate(() => !document.querySelector('#venue').hidden);
  console.log(`inspector open=${open}`);

  await page.screenshot({ path: path.join(OUT, 'canvas-picked.png') });

  // Two crops for the detail read: the rail as one block, the inspector as one.
  await page.locator('.ax-rail').screenshot({ path: path.join(OUT, 'rail.png') });
  await page.locator('.ax-venue').screenshot({ path: path.join(OUT, 'inspector.png') });

  // A phone read: the floats stack and the pick replaces the list.
  await page.setViewportSize({ width: 390, height: 844 });
  await page.addStyleTag({ content: '*{scroll-behavior:auto!important}' });
  await page.evaluate(() => document.querySelector('#venue').scrollIntoView({ block: 'start' }));
  await page.waitForTimeout(900);
