})();

/* Headless verification of the rider's calendar (/tracks/calendar).
 *
 * The one surface: the dates at the tracks the account follows, read as the
 * week the venue's owner reads — same shell, same week grid, same cards —
 * with no editor behind it. A rider on any tier gets it (following is the free
 * tier's whole surface), and the read comes and goes with the follow control.
 *
 *   cd client && npm run verify:calendar    (dev server on :5180, API on :4010)
 *
 * The run WRITES one follow and puts it back: the free demo account (quinn)
 * unfollows a track through the API, reads that its dates left, then
 * re-follows it. If the run dies midway, reseed before trusting the demo data:
 *   cd server && npm run seed
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.CALENDAR_BASE || 'http://localhost:5180';

let pass = 0;
let fail = 0;
const check = (label, ok, detail = '') => {
  if (ok) {
    pass++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    fail++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
};

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('#email', email);
  await page.fill('#password', 'dialed123');
  await page.click('button[type="submit"], form button');
  await page.waitForTimeout(1200);
}

const open = async (page, url) => {
  await page.goto(`${BASE}${url}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
};

/** The shape both calendars should carry — asked of the live page, so a
 *  restyle that renames one of them fails the parity check rather than
 *  drifting quietly. */
const SHELL = [
  '.event-list-title b',
  '.cal-editor[data-week]',
  '.cal-editor[data-month]',
  '.event-editor',
  '.event-list-head',
  '.wk',
  '.wk-grid',
  '.wk-dow',
  '.wk-allday-label',
  '.wk-times',
  '.wk-col',
];

/** What only the page that writes carries — it must not be on the rider's.
 *  A card's cover (`event-open`) is not one of them any more: both calendars
 *  open a sheet from a card, and the rider's is the read-only one, so the
 *  markers are the editor's own affordances — the Add Event control and the
 *  editor sheet — rather than the button that opens a read. */
const EDITOR = ['.cal-top button.primary', '.event-sheet:not(.event-read)', '.wk-slot', 'input', 'select[name="ev-kind"]'];

const shape = (page, selectors) =>
  page.evaluate((sels) => Object.fromEntries(sels.map((s) => [s, !!document.querySelector(s)])), selectors);

const cardVenues = (page) =>
  page.$$eval('.rider-cal .event-card-venue', (as) => [...new Set(as.map((a) => a.textContent.trim()))]);

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser(), args: ['--no-sandbox'] });

  // ---- The free rider ------------------------------------------------
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  const page = await ctx.newPage();
  await login(page, 'quinn@example.com');

  const follows = await page.evaluate(() =>
    fetch('/api/me/follows', { credentials: 'include' }).then((r) => r.json())
  );
  const followed = (follows.data?.follows ?? []).map((f) => f.name);
  check('the demo account follows tracks', followed.length > 0, followed.join(', '));

  const nav = await page.$$eval('header nav a', (as) => as.map((a) => a.textContent.trim()));
  check('the rider nav names the calendar', nav.includes('Calendar'), nav.join(', '));

  await open(page, '/tracks/calendar');
  check('the page opens as its own route', page.url().endsWith('/tracks/calendar'), page.url());

  const riderShape = await shape(page, SHELL);
  check(
    'the rider reads the owner\'s calendar shell',
    Object.values(riderShape).every(Boolean),
    Object.entries(riderShape).filter(([, ok]) => !ok).map(([s]) => s).join(', ') || 'every part present'
  );

  const riderEditor = await shape(page, EDITOR);
  check(
    'and nothing on it writes',
    Object.values(riderEditor).every((v) => !v),
    Object.entries(riderEditor).filter(([, ok]) => ok).map(([s]) => s).join(', ') || 'no editor affordance'
  );
  check('no Add Event control', (await page.$$('button')).length > 0 && !(await page.$('text=Add Event')));

  const rows = await page.$$eval('.rider-cal .event-edit-row.is-read', (rs) => rs.length);
  check('the month lists the dates as cards', rows > 0, `${rows} cards`);
  const venues = await cardVenues(page);
  check(
    'every card names a track the account follows',
    venues.length > 0 && venues.every((v) => followed.includes(v)),
    venues.join(', ')
  );
  /* The card is a control — a rider opens the date — but what it opens has no
     editor in it: the owner's own sheet, read rather than written. */
  const cardCursor = await page.$eval('.rider-cal .event-edit-row', (el) => getComputedStyle(el).cursor);
  check('a card is a control', cardCursor === 'pointer', cardCursor);
  check(
    'and the venue name on it is still the top click',
    await page.evaluate(() => {
      const a = document.querySelector('.rider-cal .event-card-venue');
      if (!a) return false;
      const box = a.getBoundingClientRect();
      const hit = document.elementFromPoint(box.left + 4, box.top + box.height / 2);
      return a === hit || a.contains(hit);
    })
  );

  /* The card's cover is the control, but a rider's card carries the venue link
     over it (`z-index: 2`), so a centre click lands on the link instead. Aim
     at the title band, which the cover owns. */
  await page.locator('.rider-cal .event-edit-row .event-open').first().click({ position: { x: 24, y: 14 } });
  await page.waitForTimeout(400);
  const readSheet = await page.evaluate(() => {
    const s = document.querySelector('.sheet.event-read');
    if (!s) return null;
    return {
      title: s.querySelector('.sheet-title')?.textContent.trim() ?? '',
      kind: s.querySelector('.pill')?.textContent.trim() ?? '',
      labels: [...s.querySelectorAll('.ev-label')].map((l) => l.textContent.trim()),
      readback: s.querySelector('.ev-readback')?.innerText.replace(/\n/g, ' ') ?? '',
      wells: s.querySelectorAll('.ev-well').length,
      venue: s.querySelector('.event-read-venue')?.getAttribute('href') ?? '',
      banner: s.querySelector('.event-read-banner')?.getAttribute('href') ?? '',
      bannerName: s.querySelector('.event-read-banner-name')?.textContent.trim() ?? '',
      bannerWhere: s.querySelector('.event-read-banner-where')?.textContent.trim() ?? '',
      // The banner's photo and its two lines sit side by side: the cut on the
      // left of the name, not over it.
      bannerLayout: (() => {
        const row = s.querySelector('.event-read-banner');
        const img = row?.querySelector('.event-read-banner-thumb');
        const text = row?.querySelector('.event-read-banner-text');
        if (!row || !img || !text) return '';
        const r = row.getBoundingClientRect();
        const i = img.getBoundingClientRect();
        const t = text.getBoundingClientRect();
        const beside = i.right <= t.left + 1 && Math.abs(i.height - 56) <= 1;
        const inside = r.height >= i.height && r.width >= i.width;
        return beside && inside ? 'row' : 'not a row';
      })(),
      fields: s.querySelectorAll('input, select, textarea').length,
      writes: s.querySelectorAll('button.primary, button.danger').length,
      // A control's name may be its text or, on an icon button, its label.
      buttons: [...s.querySelectorAll('button')]
        .map((b) => b.textContent.trim() || b.getAttribute('aria-label') || '')
        .join('|'),
      focused: String(document.activeElement?.className ?? ''),
    };
  });
  check('a card opens the date', !!readSheet?.title, readSheet?.title ?? 'no sheet');
  check(
    'it says what is on, in a sentence',
    !!readSheet && readSheet.readback.length > 0 && readSheet.labels.length === 0,
    readSheet ? `${readSheet.labels.join(', ') || 'no labels'} — ${readSheet.readback}` : 'no sheet'
  );
  check(
    'and there is nothing on it to write',
    !!readSheet && readSheet.fields === 0 && readSheet.writes === 0,
    readSheet ? `${readSheet.fields} fields, ${readSheet.writes} write buttons` : 'no sheet'
  );
  check('the read draws no field wells', !!readSheet && readSheet.wells === 0, `${readSheet?.wells} wells`);
  check(
    'it names the venue the date is at',
    !!readSheet && /^\/tracks\//.test(readSheet.banner) && readSheet.bannerName.length > 0,
    readSheet ? `${readSheet.bannerName} → ${readSheet.banner}` : 'no sheet'
  );
  check(
    "and the banner carries the venue's place",
    !!readSheet && readSheet.bannerWhere.includes(', '),
