  );
  check(
    'the head names the date only, not the track',
    !!readSheet && readSheet.venue === '',
    readSheet?.venue || 'no venue link in the head'
  );
  check(
    "the banner's photo is a small cut beside the name",
    !!readSheet && readSheet.bannerLayout === 'row',
    readSheet?.bannerLayout || 'no banner'
  );
  check(
    'Close is the only thing it offers',
    !!readSheet && readSheet.buttons.split('|').length === 1 && /close/i.test(readSheet.buttons),
