  );
  check('the sheet takes the focus', !!readSheet?.focused.includes('event-read'), readSheet?.focused);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  check('Escape puts the read sheet away', !(await page.$('.sheet.event-read')));

  const chips = await page.$$eval('.rider-cal .wk-chip, .rider-cal .wk-aday', (cs) => cs.length);
