  // ---- The owner's own page: the same shell, with the editor ----------
  const ctxOp = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  const pageOp = await ctxOp.newPage();
  await login(pageOp, 'ops@221mx.example.com');
  await open(pageOp, '/operator/calendar');
  const opShape = await shape(pageOp, SHELL);
  const same = SHELL.every((s) => opShape[s] === riderShape[s]);
  check('the owner\'s page reads the same shell', same, Object.entries(opShape).filter(([s, v]) => v !== riderShape[s]).map(([s]) => s).join(', '));
  const opEditor = await shape(pageOp, EDITOR);
  check(
    'and it is the owner\'s page that writes',
    opEditor['.cal-top button.primary'] && !riderEditor['.cal-top button.primary'],
    'op has an Add Event control, rider does not'
  );
  check('an operator is not left on the rider route', !pageOp.url().includes('/tracks/calendar'), pageOp.url());

  // ---- A paid rider with no follows: the prompt ------------------------
  const ctx2 = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  const page2 = await ctx2.newPage();
  await login(page2, 'alex@example.com');
  await open(page2, '/tracks/calendar');
  check(
    'a paid rider reads the same page',
    (await page2.textContent('.event-list-title b')).trim() ===
      (await page.textContent('.event-list-title b')).trim(),
    page2.url()
  );
  check('an empty calendar asks them to follow a track', !!(await page2.$('.rider-cal-empty')));
  check('the prompt leads back to the network', !!(await page2.$('.rider-cal-empty a[href="/tracks"]')));
  /* Nothing to show is not nothing to draw: the month, the week and the column
     all stay, and the prompt fills the column the cards would have. */
  check('an empty calendar is still a calendar', !!(await page2.$('.rider-cal .cal-editor .wk-grid')));
  check(
    'and the prompt rides in the column beside the week',
    !!(await page2.$('.rider-cal .cal-editor .event-editor .rider-cal-empty')),
    'the left column keeps its own block'
  );
  check(
    'the empty read has no editor',
    !(await page2.$('.rider-cal .wk-slot, .rider-cal select[name="ev-kind"]'))
  );

  // ---- An operator is sent to its own home -----------------------------
  const ctx3 = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  const page3 = await ctx3.newPage();
  await login(page3, 'ops@221mx.example.com');
  await open(page3, '/tracks/calendar');
  check('an operator is sent to their own home', page3.url().includes('/operator/'), page3.url());

  console.log(`\n=== ${pass} passed, ${fail} failed ===\n`);
  await browser.close();
  process.exit(fail === 0 ? 0 : 1);
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

/* Headless verification of the site cursor, on every page.
 *
 * The cursor is a canvas + a blend-mode square, and neither a typecheck nor a
 * build can see it: it has to paint. This drives a real headless Chromium, moves
 * the pointer with real events, and reads the pixels back — the square's 6px
 * footprint, the tail that gathers while the pointer moves and clears when it
 * stops, the hairline square's hover and pressed states, and the two gates
 * (reduced motion, coarse pointer) that are supposed to switch it off.
 *
 *   cd client && npm run verify:cursor        (dev server must be running on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.CURSOR_BASE || 'http://localhost:5180';
const ACCENT = [255, 138, 63]; // --accent, Moto Pass orange

/* The cursor has a kill switch in the component (`CURSOR_ENABLED`). While it is
   off nothing mounts, so this suite has nothing to read — it says so and exits
   clean instead of failing twenty checks against an absent layer. Read the flag
   from the component itself so the two can never disagree. */
const COMPONENT = path.join(__dirname, '..', 'src', 'components', 'CanvasCursor.tsx');
function cursorEnabled() {
  if (!fs.existsSync(COMPONENT)) return true;
  const src = fs.readFileSync(COMPONENT, 'utf8');
  return !/const\s+CURSOR_ENABLED\s*=\s*false/.test(src);
}

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

/** Everything the canvas has painted, as a footprint plus the strongest pixel. */
async function painted(page) {
  return page.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    if (!c) return null;
    const ctx = c.getContext('2d');
    const d = ctx.getImageData(0, 0, c.width, c.height).data;
    let n = 0;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -1;
    let maxY = -1;
    let alpha = 0;
    let colour = null;
    for (let i = 0; i < d.length; i += 4) {
      if (d[i + 3] <= 8) continue;
      n++;
      const px = (i / 4) % c.width;
      const py = Math.floor(i / 4 / c.width);
      if (px < minX) minX = px;
      if (px > maxX) maxX = px;
      if (py < minY) minY = py;
      if (py > maxY) maxY = py;
      if (d[i + 3] > alpha) {
        alpha = d[i + 3];
        colour = [d[i], d[i + 1], d[i + 2]];
      }
    }
    return n
      ? { n, box: [minX, minY, maxX, maxY], w: maxX - minX + 1, h: maxY - minY + 1, alpha, colour }
      : { n: 0, box: null, w: 0, h: 0, alpha: 0, colour: null };
  });
}

async function squareState(page) {
  return page.evaluate(() => {
    const el = document.getElementById('canvas-cursor-hover');
    if (!el) return null;
    const st = getComputedStyle(el);
    const m = (st.transform.match(/matrix\(([^)]+)\)/) || [])[1];
    const scale = m ? parseFloat(m.split(',')[0]) : 1;
    return {
      opacity: parseFloat(st.opacity),
      scale,
      blend: st.mixBlendMode,
      background: st.backgroundColor,
      borderWidth: parseFloat(st.borderTopWidth),
      borderColour: st.borderTopColor,
      height: st.height,
      pressed: el.classList.contains('pressed'),
      pointerEvents: st.pointerEvents,
    };
  });
}

/** Settle the pointer somewhere and let the ease finish (it is 0.18 a frame). */
async function settle(page, x, y) {
  await page.mouse.move(x, y, { steps: 1 });
  // 0.82 per frame leaves ~1.5px after 30 frames, so a half-second is NOT
  // settled — the ease needs the better part of a second to converge.
  await page.waitForTimeout(900);
}

async function main() {
  if (!cursorEnabled()) {
    console.log('site cursor is switched off (CURSOR_ENABLED = false in CanvasCursor.tsx)');
    console.log('nothing to verify — flip the flag to true to re-run these checks');
    process.exit(0);
  }
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));

  /* --- it mounts, and it is only paint ------------------------------------ */
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  await page.waitForSelector('#canvas-cursor', { timeout: 15000 });
  await page.waitForSelector('#canvas-cursor-hover', { timeout: 15000 });
  check('the canvas and the hairline square are mounted', true);

  const layers = await page.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const h = document.getElementById('canvas-cursor-hover');
    const cs = getComputedStyle(c);
    const hs = getComputedStyle(h);
    return {
      canvasPE: cs.pointerEvents,
      canvasPos: cs.position,
      squarePE: hs.pointerEvents,
      canvasZ: +cs.zIndex,
      squareZ: +hs.zIndex,
      sheetZ: 1200, // the app's sheet layer
      native: getComputedStyle(document.body).cursor,
    };
  });
  check('neither layer takes a click', layers.canvasPE === 'none' && layers.squarePE === 'none',
    JSON.stringify(layers));
  check('both ride over the sheets and toasts', layers.canvasZ > 1200 && layers.squareZ > layers.canvasZ,
    `canvas ${layers.canvasZ}, square ${layers.squareZ}`);
  check('the native pointer is left alone', layers.native === 'auto' || layers.native === 'default',
    layers.native);

  /* --- the square on the pointer ------------------------------------------ */
  await settle(page, 620, 700);
  const rest = await painted(page);
  check('a still pointer paints a single mark', rest.n > 0 && rest.n <= 140, JSON.stringify(rest));
  // A half-pixel origin bleeds one extra antialiased column, so 6 or 7 reads.
  const nine = (v) => v === 6 || v === 7;
  check('the mark is the 6px square', nine(rest.w) && nine(rest.h), `${rest.w}x${rest.h}`);
  check('the mark is centred on the pointer',
    rest.box && Math.abs((rest.box[0] + rest.box[2]) / 2 - 620) <= 1 && Math.abs((rest.box[1] + rest.box[3]) / 2 - 700) <= 1,
    JSON.stringify(rest.box));
  check('the mark is the accent colour',
    rest.colour && rest.colour.every((v, i) => Math.abs(v - ACCENT[i]) <= 3), JSON.stringify(rest.colour));

  /* --- the tail: gathers at speed, gone at rest ---------------------------- */
  await page.mouse.move(300, 420, { steps: 1 });
  await page.waitForTimeout(300);
  await page.mouse.move(900, 460, { steps: 24 });
  const moving = await painted(page);
  const stillMoving = await painted(page);
  check('a moving pointer trails', moving.w > 40, `span ${moving.w}x${moving.h}`);
  check('the trail is fainter than the square', moving.n / Math.max(1, moving.w) > 1.2 && moving.h < 40,
    `${moving.n} px over ${moving.w}x${moving.h}`);

  await page.waitForTimeout(700);
  const stopped = await painted(page);
  check('the trail clears when the pointer stops', stopped.w <= 12 && stopped.h <= 12,
    `${stopped.w}x${stopped.h}`);
  void stillMoving;

  /* --- over something clickable ------------------------------------------- */
  const link = await page.$('header a[href="/"]');
  const box = await link.boundingBox();
  await settle(page, Math.round(box.x + box.width / 2), Math.round(box.y + box.height / 2));
  await page.waitForTimeout(400);
  const hover = await squareState(page);
  const hoverPixels = await painted(page);
  check('the hairline square comes up over a link', hover.opacity > 0.6, JSON.stringify(hover));
  check('it desaturates what it covers', hover.blend === 'saturation', hover.blend);
  // Chrome's computed border-width rounds 1.25px to 1px; the hairline is the point.
  check('it is a hairline with no ink at rest', hover.borderWidth >= 1 && hover.borderWidth <= 1.5 && hover.borderColour.replace(/ /g, '') === 'rgba(0,0,0,0)',
    `${hover.borderWidth}px ${hover.borderColour}`);
  check('it is square and about 2rem tall', hover.height === '31.99px' || hover.height === '32px',
    hover.height);
  check('the square on the pointer hands over to it', hoverPixels.n === 0 || hoverPixels.alpha < 40,
    JSON.stringify(hoverPixels));

  /* --- pressed ------------------------------------------------------------ */
  await page.mouse.down();
  await page.waitForTimeout(250);
  const pressed = await squareState(page);
  const pressedPixels = await painted(page);
  const shot = path.join(__dirname, '..', 'cursor-verification.png');
  await page.screenshot({ path: shot });
  check('a press flips the square to its pressed read', pressed.pressed, JSON.stringify(pressed));
  check('the fill drops and the hairline takes ink',
    pressed.background.replace(/ /g, '') === 'rgba(0,0,0,0)' && pressed.blend === 'normal' &&
      pressed.borderColour.replace(/ /g, '') !== 'rgba(0,0,0,0)',
    `${pressed.background} / ${pressed.blend} / ${pressed.borderColour}`);
  check('it snaps in smaller than its hover size', pressed.scale > 0.4 && pressed.scale < 0.9,
    String(pressed.scale));
  check('the square on the pointer comes back while pressed', nine(pressedPixels.w) && nine(pressedPixels.h),
    `${pressedPixels.w}x${pressedPixels.h}`);
  await page.mouse.up();
  await page.waitForTimeout(300);
  const released = await squareState(page);
  check('releasing puts the pressed read away', !released.pressed, JSON.stringify(released));

  /* --- over a button: the grey square is gone ----------------------------- */
  // The desaturating block reads as a grey rectangle stamped across the fill of
  // a CTA, and the press stamped the same square wherever the click landed — so
  // over a button neither the resting square nor the press reads.
  const btn = await page.$('button.primary');
  await btn.scrollIntoViewIfNeeded();
  const bb = await btn.boundingBox();
  await settle(page, Math.round(bb.x + bb.width / 2), Math.round(bb.y + bb.height / 2));
  await page.waitForTimeout(400);
  const onButton = await squareState(page);
  check('no square over a button at rest', onButton.opacity < 0.05, JSON.stringify(onButton));

  await page.mouse.down();
  await page.waitForTimeout(250);
  const btnPressed = await squareState(page);
  const btnPressedPixels = await painted(page);
  check('clicking a button stamps no square either', btnPressed.pressed && btnPressed.opacity < 0.05,
    JSON.stringify(btnPressed));
  check('and no square on the pointer comes back while it is down',
    btnPressedPixels.n === 0 || btnPressedPixels.alpha < 40, JSON.stringify(btnPressedPixels));
  await page.mouse.up();
  await page.waitForTimeout(250);

  /* --- the ink follows the accent token ----------------------------------- */
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await settle(page, 400, 700);
  const before = await painted(page);
  await page.evaluate(() => document.documentElement.style.setProperty('--accent', '#3fd0ff'));
  await settle(page, 420, 700);
  const after = await painted(page);
  check('the ink follows --accent', after.colour && after.colour[2] > 200 && after.colour[0] < 120,
    `before ${JSON.stringify(before.colour)} after ${JSON.stringify(after.colour)}`);

  /* --- on a retina screen ------------------------------------------------- */
  // Worth its own context: at dpr 2 the backing store is twice the viewport, and
  // a canvas left at its intrinsic size lays out at 2560x1800 CSS px instead —
  // which reads as a mark that is right in the top-left corner and drifts further
  // off the pointer the further you move. Measure it, do not assume it.
  const retina = await browser.newContext({
    viewport: { width: 1280, height: 900 },
    deviceScaleFactor: 2,
  });
  const hi = await retina.newPage();
  await hi.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  await hi.waitForSelector('#canvas-cursor', { timeout: 15000 });
  const layer = await hi.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const r = c.getBoundingClientRect();
    return { dpr: window.devicePixelRatio, attr: [c.width, c.height], rect: [Math.round(r.width), Math.round(r.height)], viewport: [window.innerWidth, window.innerHeight] };
  });
  check('the layer is the viewport in CSS px at dpr 2',
    layer.dpr === 2 && layer.attr[0] === layer.viewport[0] * 2 &&
      layer.rect[0] === layer.viewport[0] && layer.rect[1] === layer.viewport[1],
    JSON.stringify(layer));

  await settle(hi, 1180, 840);
  const far = await hi.evaluate(() => {
    const c = document.getElementById('canvas-cursor');
    const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
    let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1;
    for (let i = 0; i < d.length; i += 4) {
      if (d[i + 3] <= 8) continue;
      const px = (i / 4) % c.width;
      const py = Math.floor(i / 4 / c.width);
      if (px < minX) minX = px;
      if (px > maxX) maxX = px;
      if (py < minY) minY = py;
      if (py > maxY) maxY = py;
    }
    const r = document.getElementById('canvas-cursor-hover').getBoundingClientRect();
    return {
      centre: [(minX + maxX) / 2 / window.devicePixelRatio, (minY + maxY) / 2 / window.devicePixelRatio],
      // The square's own box, so the -50% centring inside its transform is not
      // mine to re-derive.
      squareAt: [r.left + r.width / 2, r.top + r.height / 2],
    };
  });
  check('the mark lands on the pointer at dpr 2, far from the origin',
    Math.abs(far.centre[0] - 1180) <= 1.5 && Math.abs(far.centre[1] - 840) <= 1.5, JSON.stringify(far.centre));
  check('the hairline square lands on it too',
    Math.abs(far.squareAt[0] - 1180) <= 1 && Math.abs(far.squareAt[1] - 840) <= 1, JSON.stringify(far.squareAt));
  await retina.close();

  /* --- the two gates ------------------------------------------------------ */
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  check('reduced motion gets no cursor',
    (await page.$('#canvas-cursor')) === null && (await page.$('#canvas-cursor-hover')) === null);

  await page.emulateMedia({ reducedMotion: null });
  await page.setViewportSize({ width: 390, height: 780 });
  await page.goto(`${BASE}/`, { waitUntil: 'networkidle' });
  const fineHere = await page.evaluate(() => matchMedia('(hover: hover) and (pointer: fine)').matches);
  if (!fineHere) check('a coarse pointer gets no cursor', (await page.$('#canvas-cursor')) === null);
  else check('a narrow window keeps the fine-pointer cursor', true);

  /* --- nothing thrown along the way --------------------------------------- */
  check('no page errors', errors.length === 0, errors.slice(0, 2).join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'all checks passed' : `${fails} check(s) failed`}`);
  console.log(`screenshot: ${shot}`);
  process.exit(fails ? 1 : 0);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/* Verify the email and phone fields sanitise as you type, state their rule when
   the reader leaves them, and never build a request from a value the API would
   refuse. Three surfaces, one rule set:

     /forgot-password   the reset ask — a malformed address is refused at the
                        field, and the POST is never sent
     /login             sign-in and sign-up share #email and #phone; controls
                        and zero-width marks are stripped on the way in, and a
                        malformed address or number is refused before the POST
     /operator/profile  the venue contact email and phone — both optional, but
                        an invalid one keeps the save from reaching PATCH
                        /owner/track

   cd client && node scripts/verify-email-validation.cjs
   (dev server on :5180, API on :4010)
*/
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.EMAIL_BASE || 'http://localhost:5180';
const ZWSP = '\u200B';
const RTL = '\u202E';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

const say = (label, ok, detail) => console.log(`${ok ? 'PASS' : 'FAIL'} | ${label} | ${detail}`);

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser() });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1100 } });
  const page = await ctx.newPage();

  const count = { forgot: 0, login: 0, owner: 0 };
  page.on('request', (r) => {
    const u = r.url();
    if (r.method() !== 'GET' && u.includes('/api/auth/forgot-password')) count.forgot++;
    if (r.method() !== 'GET' && u.includes('/api/auth/login')) count.login++;
    if (r.method() === 'PATCH' && u.includes('/api/owner/track')) count.owner++;
  });
  page.on('console', (m) => {
    if (m.type() === 'error') console.log('console error:', m.text().slice(0, 200));
  });

  // ---------------------------------------------------------------- forgot
  await page.goto(`${BASE}/forgot-password`, { waitUntil: 'networkidle' });
  const email = page.locator('#email');
  await email.fill(`riley@example.com${ZWSP}${RTL}`);
  const stripped = await email.inputValue();
  say('forgot: controls and bidi marks stripped on paste', stripped === 'riley@example.com', JSON.stringify(stripped));

  await email.fill('riley@example');
  await page.waitForTimeout(150);
  const hint = page.locator('#email-hint');
  say(
    'forgot: a half-typed address stays quiet while typing',
    (await hint.count()) === 0,
    `hints=${await hint.count()}`
  );
  await page.keyboard.press('Tab');
  await page.waitForTimeout(200);
  say(
    'forgot: malformed address shows the field hint on blur',
    (await hint.count()) === 1 && (await email.getAttribute('aria-invalid')) === 'true',
    JSON.stringify((await hint.count()) ? await hint.first().innerText() : '')
  );

  await page.click('.axa-submit');
  await page.waitForTimeout(500);
  say('forgot: malformed address sends no request', count.forgot === 0, `requests=${count.forgot}`);

  await email.fill('riley@example.com');
  await page.waitForTimeout(150);
  say('forgot: hint clears once the address is valid', (await page.locator('#email-hint').count()) === 0, '');
  await page.click('.axa-submit');
  await page.waitForTimeout(900);
  const okText = await page.locator('.axa-alert.ok').count();
  say('forgot: valid address sends exactly one request', count.forgot === 1 && okText === 1, `requests=${count.forgot}`);

  // -------------------------------------------------------- register gate
  await page.goto(`${BASE}/signup`, { waitUntil: 'networkidle' });
  const regEmail = page.locator('#email');
  const regSubmit = page.locator('.axa-submit');
  await page.fill('#name', 'Test Rider');
  await regEmail.fill('riley@example.c');
  await page.waitForTimeout(200);
  say(
    'register: a half-typed address raises no notice while typing',
    (await page.locator('#email-hint').count()) === 0 &&
      (await page.locator('.axa-alert.bad').count()) === 0,
    ''
  );
  // Blur by clicking the heading: Tab would land in the phone field and mark
  // that one touched too.
  await page.locator('h1').first().click();
  await page.waitForTimeout(200);
  const regBlur = await page.locator('#email-hint').first().innerText().catch(() => '');
  say(
    'register: leaving a one-letter TLD states the rule under the field, not in the card notice',
    regBlur.toLowerCase().includes('valid email') &&
      (await regEmail.getAttribute('aria-invalid')) === 'true' &&
      (await page.locator('.axa-alert.bad').count()) === 0,
    JSON.stringify(regBlur.slice(0, 60))
  );
  await page.fill('#password', 'dialed123');
  await page.fill('#confirm', 'dialed123');
  await page.check('#agree');
  await page.waitForTimeout(200);
  say(
    'register: a one-letter TLD keeps the CTA disabled',
    await regSubmit.isDisabled(),
    `disabled=${await regSubmit.isDisabled()}`
  );
  await regEmail.fill('riley@example.com');
  await page.waitForTimeout(200);
  say(
    'register: notice clears and the CTA enables once the address is valid',
    !(await regSubmit.isDisabled()) &&
      (await page.locator('#email-hint').count()) === 0 &&
      (await page.locator('.axa-alert.bad').count()) === 0,
    ''
  );

  // The optional phone: quiet while typing, its rule on blur, and a number the
  // API would refuse keeps the CTA dead — blank stays fine.
  const regPhone = page.locator('#phone');
  await regPhone.fill('828');
  await page.waitForTimeout(150);
  say(
    'register: a half-typed phone raises no hint while typing',
    (await page.locator('#phone-hint').count()) === 0,
    ''
  );
  await page.locator('h1').first().click();
  await page.waitForTimeout(200);
  const regPhoneHint = await page.locator('#phone-hint').first().innerText().catch(() => '');
  say(
    'register: leaving a 3-digit phone states the rule under the field',
    regPhoneHint.toLowerCase().includes('phone') &&
      (await regPhone.getAttribute('aria-invalid')) === 'true' &&
      (await regSubmit.isDisabled()),
    JSON.stringify(regPhoneHint.slice(0, 60))
  );
  await regPhone.fill('828 555 0142');
  await page.waitForTimeout(200);
  say(
    'register: a full number clears the hint and enables the CTA',
    (await page.locator('#phone-hint').count()) === 0 && !(await regSubmit.isDisabled()),
    ''
  );
  await regPhone.fill('');
  await page.waitForTimeout(200);
  say(
    'register: a blank optional phone is not an error',
    (await page.locator('#phone-hint').count()) === 0 && !(await regSubmit.isDisabled()),
    ''
  );

  // ----------------------------------------------------------------- login
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  const loginEmail = page.locator('#email');

  // The blur rule first, on a field nothing has touched: quiet while typing,
  // and the rule stated the moment focus leaves.
  await loginEmail.fill('ops@221mx');
  await page.waitForTimeout(200);
  say(
    'login: a half-typed address raises no notice while typing',
    (await page.locator('#email-hint').count()) === 0 &&
      (await page.locator('.axa-alert.bad').count()) === 0,
    ''
  );
  await page.keyboard.press('Tab');
  await page.waitForTimeout(200);
  const blurNotice = await page.locator('#email-hint').first().innerText().catch(() => '');
  say(
    'login: leaving a malformed address states the rule under the field',
    blurNotice.toLowerCase().includes('valid email') &&
      (await loginEmail.getAttribute('aria-invalid')) === 'true' &&
      (await page.locator('.axa-alert.bad').count()) === 0,
    `hint=${JSON.stringify(blurNotice.slice(0, 60))} requests=${count.login}`
  );

  await loginEmail.fill(`ops@221mx.example.com${ZWSP}`);
  say('login: zero-width mark stripped on paste', (await loginEmail.inputValue()) === 'ops@221mx.example.com', '');
  say(
    'login: the hint clears once the address is valid',
    (await page.locator('#email-hint').count()) === 0,
    ''
  );
  const atCount = await loginEmail.inputValue();
  await loginEmail.fill(`ops@@221mx.example.com${ZWSP}`);
  say('login: a second @ never survives the field', (await loginEmail.inputValue()) === 'ops@221mx.example.com', JSON.stringify(await loginEmail.inputValue()));

  await page.fill('#password', 'dialed123');
  await loginEmail.fill('ops@221mx');
  await page.waitForTimeout(150);
  await page.click('.axa-submit');
  await page.waitForTimeout(700);
  const notice = await page.locator('[role="alert"], .banner, .alert, .axa-alert').first().innerText().catch(() => '');
  say(
    'login: malformed address sends no request',
    count.login === 0 && notice.toLowerCase().includes('valid email'),
    `requests=${count.login} notice=${JSON.stringify(notice.slice(0, 80))}`
  );

  // A real sign-in still lands (the operator's own home).
  await loginEmail.fill('ops@221mx.example.com');
  await page.click('.axa-submit');
  await page.waitForURL('**/operator/**', { timeout: 8000 }).catch(() => {});
  say('login: valid address signs in', count.login === 1 && page.url().includes('/operator'), `url=${page.url()}`);
  void atCount;

  // --------------------------------------------------------- owner profile
  await page.goto(`${BASE}/operator/profile`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  const ownerEmail = page.locator('label:text-is("Email") + input');
  const before = await ownerEmail.inputValue();
  const save = page.locator('button.primary', { hasText: 'Save profile' });

  await ownerEmail.fill('not-an-address');
  await page.waitForTimeout(150);
  const ownerHint = page.locator('#owner-email-hint');
  say(
    'owner: a half-typed contact email stays quiet while typing',
    (await ownerHint.count()) === 0,
    `hints=${await ownerHint.count()}`
  );
  await page.locator('h1').first().click();
  await page.waitForTimeout(200);
  say(
    'owner: malformed contact email shows the field hint on blur',
    (await ownerHint.count()) === 1 && (await ownerEmail.getAttribute('aria-invalid')) === 'true',
    JSON.stringify((await ownerHint.count()) ? await ownerHint.first().innerText() : '')
  );

  await save.click();
  await page.waitForTimeout(900);
  say('owner: malformed contact email blocks the save', count.owner === 0, `patches=${count.owner}`);

  await ownerEmail.fill(`gate${ZWSP}@221mx.example.com`);
  say('owner: zero-width mark stripped on paste', (await ownerEmail.inputValue()) === 'gate@221mx.example.com', '');

  // The venue phone, on the same terms: optional, but a written number has to
  // be one, and a refused one keeps the save from leaving.
  const ownerPhone = page.locator('label:text-is("Phone") + input');
  const beforePhone = await ownerPhone.inputValue();
  await ownerPhone.fill('828');
  await page.waitForTimeout(150);
  say(
    'owner: a half-typed phone stays quiet while typing',
    (await page.locator('#owner-phone-hint').count()) === 0,
    ''
  );
  await page.locator('h1').first().click();
  await page.waitForTimeout(200);
  const ownerPhoneHint = page.locator('#owner-phone-hint');
  say(
    'owner: malformed phone shows the hint on blur',
    (await ownerPhoneHint.count()) === 1 &&
      (await ownerPhone.getAttribute('aria-invalid')) === 'true',
    JSON.stringify((await ownerPhoneHint.count()) ? await ownerPhoneHint.first().innerText() : '')
  );
  await save.click();
  await page.waitForTimeout(900);
  say('owner: malformed phone blocks the save', count.owner === 0, `patches=${count.owner}`);

  // Put back exactly what was there (a blank contact address is valid).
  await ownerEmail.fill(before);
  await ownerPhone.fill(beforePhone);
  await page.waitForTimeout(150);
  await save.click();
  await page.waitForTimeout(1200);
  say(
    'owner: valid contact email and phone save',
    count.owner === 1 && (await page.locator('#owner-phone-hint').count()) === 0,
    `patches=${count.owner}`
  );

  await browser.close();
})().catch((err) => {
  console.error('verify failed:', err);
  process.exit(1);
});

