/* The rider search always loads empty: a search left in the box, or a card left
   open, must not come back on a reload. Proves a fresh load shows blank fields,
   no results, and that nothing about the search is written to the tab store. */
const path = require('path');
const fs = require('fs');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

const ids = ['email', 'name', 'phone'];
const vals = (page) =>
  page.evaluate(
    (keys) =>
      Object.fromEntries(keys.map((k) => [k, document.getElementById(`rider-search-${k}`)?.value])),
    ids
  );

(async () => {
  const browser = await chromium.launch({ executablePath: findBrowser() });
  const ctx = await browser.newContext({
    viewport: { width: 1440, height: 1000 },
    deviceScaleFactor: Number(process.env.DSF || 2),
  });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push(m.text());
  });

  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.fill('#email', 'ops@221mx.example.com');
  await page.fill('#password', 'dialed123');
