  await page.waitForTimeout(900);

  // 1. A search that finds a rider and opens the card.
  await page.fill('#rider-search-name', 'riley');
  await page.click('.lookup-search-btn');
  await page.waitForSelector('.lookup-hit, .gate-name', { timeout: 8000 }).catch(() => {});
  await page.waitForTimeout(600);
  const before = {
    vals: await vals(page),
    hits: await page.locator('.lookup-hit').count(),
    results: await page.locator('.lookup-hit, .gate-name').count(),
    stored: await page.evaluate(() => sessionStorage.getItem('motopass.gate')),
  };
