  // 2. A reload lands on blank fields and nothing else.
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  const after = {
    vals: await vals(page),
    searching: await page.locator('.scan-lookup').getByText('Searching…').count(),
    card: await page.locator('.gate-name').count(),
    noMatch: await page.locator('.lookup-hint').count(),
    button: await page.locator('.lookup-search-btn').isDisabled(),
    stored: await page.evaluate(() => sessionStorage.getItem('motopass.gate')),
  };
