/* Headless verification of column sorting, across every table in the app.
 *
 * For each table on each page it walks every sortable header and asserts that
 * clicking it permutes the rows without losing any, that a second click flips
 * the direction, and that aria-sort reports the state for assistive tech. When
 * the displayed values explain the order on their own it also asserts the exact
 * reversal, and when every value parses as a distinct number it asserts the
 * order is numeric rather than text. Columns whose sort key is not what the
 * cell shows (a count shown inside a sentence) are judged on the first two
 * properties only.
 *
 *   cd client && npm run verify:sorting     (dev server on :5180)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.SORT_BASE || 'http://localhost:5180';
const PASSWORD = 'dialed123';

const PAGES = [
  // /tracks is the network page and carries no table on purpose — perks are
  // cards there, the per-track surface is day rows. The first entry is signed
  // out on purpose: the page is public. Only the pages below that own a table
  // are asserted.
  { url: '/tracks', name: 'network page', noTable: true, waitFor: '.day-grid' },
  { url: '/admin/users', name: 'admin users', login: 'admin@motopass.example.com' },
  { url: '/admin/tracks', name: 'admin tracks', login: 'admin@motopass.example.com' },
  { url: '/admin/tiers', name: 'admin tiers', login: 'admin@motopass.example.com' },
  { url: '/admin/reports', name: 'admin reports', login: 'admin@motopass.example.com' },
  { url: '/admin/quickbooks', name: 'quickbooks preview', login: 'admin@motopass.example.com', preview: true },
  { url: '/operator/dashboard', name: 'operator dashboard', login: 'ops@221mx.example.com' },
];

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
let checks = 0;
function check(label, ok, detail = '') {
  checks++;
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

/** Numbers, so currency and +N compare as values. Null when not all numeric. */
function asNumbers(values) {
  const nums = [];
  for (const v of values) {
    const m = /^[+]?\$?([\d,]+(?:\.\d+)?)%?$/.exec(v.replace(/\s/g, ''));
    if (!m) return null;
    nums.push(Number(m[1].replace(/,/g, '')));
  }
  return nums;
}

function cmp(a, b) {
  const [na, nb] = [asNumbers([a]), asNumbers([b])];
  if (na && nb) return na[0] - nb[0];
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
}

/** True when the displayed values alone explain a strict order. */
function strictlyOrdered(values) {
  return values.every((v, i) => i === 0 || cmp(values[i - 1], v) < 0);
}

async function login(page, email) {
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.waitForSelector('form #email');
  await page.fill('#email', email);
  await page.fill('#password', PASSWORD);
  await Promise.all([
    page.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
}

const sameRows = (a, b) => a.join('\u0000') === b.join('\u0000');

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const browser = await chromium.launch({ executablePath: exe });
  const errors = [];

  for (const spec of PAGES) {
    // A fresh context per page: /login redirects away when already signed in.
    const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
    const page = await ctx.newPage();
    page.on('pageerror', (e) => errors.push(`${spec.name}: ${e.message}`));

    if (spec.login) await login(page, spec.login);
    await page.goto(`${BASE}${spec.url}`, { waitUntil: 'networkidle' });
    if (spec.preview) {
      await page.waitForSelector('button:has-text("Preview")', { timeout: 15000 });
      await page.click('button:has-text("Preview")');
      await page.waitForSelector('table tbody tr', { timeout: 15000 });
    }
    if (spec.waitFor) await page.waitForSelector(spec.waitFor, { timeout: 15000 }).catch(() => {});
    else await page.waitForSelector('table', { timeout: 15000 }).catch(() => {});
    await page.waitForTimeout(400);

    const tables = await page.$$('table');
    if (!tables.length) {
      if (spec.noTable) {
        check(`${spec.name}: no table to sort (rows, as designed)`, true);
        await ctx.close();
        continue;
      }
      check(`${spec.name}: renders a table`, false, 'no table');
      await ctx.close();
      continue;
    }
    if (spec.noTable) {
      check(`${spec.name}: stays tableless`, false, `found ${tables.length} table(s)`);
    }

    for (let ti = 0; ti < tables.length; ti++) {
      const btns = await tables[ti].$$('thead th .sort-btn');
      const rowCount = await tables[ti].$$eval('tbody tr', (r) => r.length);
      if (!btns.length) {
        check(`${spec.name} table ${ti + 1}: exposes sortable headers`, false, `${rowCount} rows, 0 sortable`);
        continue;
      }

      for (let bi = 0; bi < btns.length; bi++) {
        const label = await btns[bi].evaluate((el) => el.textContent.trim());
        const col = await btns[bi].evaluate((el) => [...el.closest('tr').children].indexOf(el.closest('th')));
        const read = () =>
          tables[ti].$$eval(
            'tbody tr',
            (rows, ci) =>
              rows.map((r) => ({
                key: [...r.children].map((c) => c.textContent.trim()).join('|'),
                value: (r.children[ci]?.textContent || '').trim(),
              })),
            col
          );

        const base = await read();
        if (base.length < 2) continue;
        const baseKeys = base.map((r) => r.key).sort();

        await btns[bi].click();
        await page.waitForTimeout(120);
        const asc = await read();
        const ariaAsc = await btns[bi].evaluate((el) => el.closest('th').getAttribute('aria-sort'));

        await btns[bi].click();
        await page.waitForTimeout(120);
        const desc = await read();
        const ariaDesc = await btns[bi].evaluate((el) => el.closest('th').getAttribute('aria-sort'));

        const where = `${spec.name} › ${label}`;
        const ascVals = asc.map((r) => r.value);
        const descVals = desc.map((r) => r.value);
        const reasons = [];

        if (!sameRows(asc.map((r) => r.key).sort(), baseKeys) || !sameRows(desc.map((r) => r.key).sort(), baseKeys)) {
          reasons.push('row set changed');
        }
        if (ariaAsc !== 'ascending' || ariaDesc !== 'descending') reasons.push(`aria ${ariaAsc}/${ariaDesc}`);

        if (strictlyOrdered(ascVals)) {
          if (!sameRows(descVals, ascVals.slice().reverse())) reasons.push('direction did not flip');
        } else if (strictlyOrdered(descVals)) {
          if (!sameRows(ascVals, descVals.slice().reverse())) reasons.push('direction did not flip');
        }

        const nums = asNumbers(ascVals);
        if (nums && new Set(nums).size === nums.length) {
          const ascOk = nums.every((n, i) => i === 0 || nums[i - 1] < n);
          const descNums = asNumbers(descVals) ?? [];
          const descOk =
            descNums.length === nums.length && descNums.every((n, i) => i === 0 || descNums[i - 1] > n);
          if (!ascOk || !descOk) reasons.push('numeric order wrong');
        }

        check(
          `${where}: sorts both ways, ${base.length} rows`,
          reasons.length === 0,
          reasons.length ? `${reasons.join('; ')} — ${ascVals.join(', ')}` : ''
        );
      }
    }

    await ctx.close();
  }

  check('no JS errors while sorting', errors.length === 0, errors.slice(0, 3).join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? `ALL ${checks} SORTING CHECKS PASSED` : `${fails} of ${checks} SORTING CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

/* Headless verification of the upgrade welcome (/tracks?checkout=success).
 *
 * A rider who has just paid used to get a toast that said the pass was live and
 * then vanished. The welcome is now a modal, and it carries two lines only:
 * the pass's name and the date it is valid through, with the perks link and one
 * action. This asserts that shape stays intact.
 *
 * The run registers a fresh free-tier rider (a unique email), buys the pass
 * (the dev simulator completes it — no card is ever charged), and asserts
 * the welcome that the return trip raises. It leaves the seeded demo accounts
 * untouched.
 *
 *   cd client && npm run verify:upgrade     (dev server on :5180, API on :4010)
 *
 * Uses playwright-core with an explicit browser path so it works with the
 * browsers already in ~/.cache/ms-playwright and downloads nothing.
 */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { chromium } = require('playwright-core');

const BASE = process.env.UPGRADE_BASE || 'http://localhost:5180';

function findBrowser() {
  const root = path.join(os.homedir(), '.cache', 'ms-playwright');
  if (!fs.existsSync(root)) return null;
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium_headless_shell-')) continue;
    const p = path.join(root, dir, 'chrome-headless-shell-linux64', 'chrome-headless-shell');
    if (fs.existsSync(p)) return p;
    const alt = path.join(root, dir, 'chrome-linux', 'headless_shell');
    if (fs.existsSync(alt)) return alt;
  }
  for (const dir of fs.readdirSync(root)) {
    if (!dir.startsWith('chromium-')) continue;
    const p = path.join(root, dir, 'chrome-linux64', 'chrome');
    if (fs.existsSync(p)) return p;
  }
  return null;
}

let fails = 0;
function check(label, ok, detail = '') {
  if (!ok) fails++;
  console.log(`${ok ? 'OK  ' : 'FAIL'}  ${label}${detail ? ` — ${detail}` : ''}`);
}

async function main() {
  const exe = findBrowser();
  if (!exe) {
    console.error('No Playwright Chromium found in ~/.cache/ms-playwright.');
    process.exit(1);
  }
  const email = `welcome-${Date.now()}@example.com`;
  const password = 'dialed123';

  const browser = await chromium.launch({ executablePath: exe });
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e.message)));

  // ---- A fresh free-tier rider ------------------------------------------
  // Account creation is its own page now; the sign-in page's switch is a link
  // between the two.
  await page.goto(`${BASE}/login`, { waitUntil: 'networkidle' });
  await page.click('button:has-text("Need an account? Register")');
  await page.waitForURL((u) => u.pathname === '/signup', { timeout: 10000 });
  check('the register switch opens /signup', new URL(page.url()).pathname === '/signup', page.url());
  await page.waitForSelector('form #name');
  await page.fill('#name', 'Welcome Tester');
  await page.fill('#email', email);
  await page.fill('#password', password);
  await page.fill('#confirm', password);
  // Optional on the API's `registerSchema` — the gate looks riders up by phone.
  await page.fill('#phone', '828 555 0142');
  await page.check('#agree');
  const [registerRes] = await Promise.all([
    page.waitForResponse(
      (r) => r.url().includes('/api/auth/register') && r.request().method() === 'POST',
      { timeout: 20000 }
    ),
    page.waitForURL((u) => u.pathname === '/verify-email', { timeout: 20000 }),
    page.click('form button.primary'),
  ]);
  const registerJson = await registerRes.json().catch(() => ({}));
  const devLink = registerJson?.data?.devLink ?? null;
  check(
    'a fresh signup lands on the confirm step, not signed in',
    new URL(page.url()).pathname === '/verify-email',
    page.url()
  );
  check(
    'the confirm step names the address it is waiting on',
    (await page.textContent('.axa-head')).includes(email),
    (await page.textContent('.axa-head')).replace(/\s+/g, ' ').trim()
  );

  // No mail account on this box, so the API hands the link back in the register
  // reply. Opening it spends the token and finishes the signup.
  check('the API hands the confirm link back off production', Boolean(devLink), String(devLink));
  // The reply carries the API's configured origin; keep its path and query but
  // land it on the base under test, so a tailnet hostname never blocks the run.
  const confirmPath = devLink ? new URL(devLink).pathname + new URL(devLink).search : '';
  await Promise.all([
    page.waitForURL((u) => u.pathname === '/tracks', { timeout: 20000 }),
    page.goto(`${BASE}${confirmPath}`),
  ]);
  check('confirming the address lands on the network', new URL(page.url()).pathname === '/tracks', page.url());

  // ---- Buy the pass ----------------------------------------------------
  // Placeholder Stripe keys: the Pricing page completes the purchase through
  // the dev simulator and makes the /tracks?checkout=success return trip on
  // its own. Real keys open Stripe Checkout instead — no card is ever touched:
  // the harness completes the PENDING payment through the same simulator and
  // makes the return trip itself.
  await page.goto(`${BASE}/pricing`, { waitUntil: 'networkidle' });
  await page.waitForSelector('.tier-card.popular .tier-cta', { timeout: 15000 });
  await page.click('.tier-card.popular .tier-cta');
  await page.waitForTimeout(1500);
  if (page.url().includes('checkout.stripe.com')) {
    const pays = await (await page.request.get(`${BASE}/api/me/payments`)).json();
    const pending = pays?.data?.payments?.find((p) => p.status === 'PENDING');
    check('the pass starts a pending payment', Boolean(pending), JSON.stringify(pays?.data?.payments ?? []).slice(0, 160));
    const sim = await page.request.post(`${BASE}/api/payments/dev/simulate/${pending.id}`);
    const simJson = await sim.json().catch(() => ({}));
    check('the simulator completes it without a card', sim.ok() && Boolean(simJson.success), simJson.message ?? String(sim.status()));
    await page.goto(`${BASE}/tracks?checkout=success`, { waitUntil: 'networkidle' });
  }

  // The return trip raises the welcome once the pass and its days have been
  // re-read.
  await page.waitForSelector('.upgrade-welcome', { timeout: 30000 });

  const modal = await page.$eval('.upgrade-welcome', (el) => ({
    role: el.getAttribute('role'),
    modal: el.getAttribute('aria-modal'),
    labelled: el.getAttribute('aria-labelledby'),
    title: el.querySelector('.sheet-title')?.textContent.trim(),
    meta: el.querySelector('.upgrade-meta')?.textContent.replace(/\s+/g, ' ').trim(),
    lines: [...el.querySelectorAll('h2, p')].map((x) => x.textContent.replace(/\s+/g, ' ').trim()),
    actions: [...el.querySelectorAll('.sheet-actions > *')].map((x) => x.textContent.trim()),
  }));

  check('the welcome is a real dialog', modal.role === 'dialog' && modal.modal === 'true', `${modal.role}/${modal.modal}`);
  check('the dialog is labelled by its title', modal.labelled === 'upgrade-welcome-title', String(modal.labelled));
  check('it welcomes the rider to the tier they bought', modal.title === 'Welcome to the Moto Pass', String(modal.title));
  check('the second line carries the validity date', /^Pass valid through \w+ \d{1,2}, \d{4}$/.test(modal.meta ?? ''), modal.meta);
  check('the sheet is two lines, no more', modal.lines.length === 2, modal.lines.join(' | '));

  check('the actions offer the perks and a way on', modal.actions.join(',') === 'See the perks on your pass,Let\'s go', modal.actions.join(','));

  // The toast it replaced must be gone: the upgrade is not a notice any more.
  check('no upgrade toast is left behind', (await page.$$eval('.toast', (t) => t.length)) === 0);
  check('the checkout params are retired once handled', !page.url().includes('checkout='), page.url());

  await page.screenshot({ path: 'upgrade-welcome.png' });

  // ---- It closes, and the network is underneath -------------------------
  await page.click('.upgrade-welcome button.primary');
  await page.waitForSelector('.upgrade-welcome', { state: 'detached', timeout: 5000 });
  check('the primary action closes the welcome', (await page.$$eval('.upgrade-welcome', (m) => m.length)) === 0);
  check('the network page is still there behind it', (await page.$$eval('.pass-map', (m) => m.length)) === 1);
  check('the rider is on the pass now, not the free tier', (await page.textContent('.rail-pass-name')).includes('Moto Pass'), await page.textContent('.rail-pass-name'));

  // ---- Mobile -----------------------------------------------------------
  await page.setViewportSize({ width: 390, height: 900 });
  await page.waitForTimeout(300);
  check('no horizontal overflow at 390px', !(await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1)));

  check('no JS errors during the upgrade', errors.length === 0, errors.join(' | '));

  await browser.close();
  console.log(`\n${fails === 0 ? 'ALL UPGRADE WELCOME CHECKS PASSED' : `${fails} UPGRADE WELCOME CHECK(S) FAILED`}`);
  process.exit(fails === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

import { Navigate, Route, Routes, useLocation } from 'react-router-dom';
import { ReactNode } from 'react';
import { useAuth, homePathFor, Role } from './lib/auth';
import { enableAstryxUI, enableCommunity, enableRiderDashboard } from './lib/featureFlags';
import { usePresale } from './lib/launch';
import Layout from './components/Layout/Layout';
import Landing from './pages/Landing/Landing';
import AstryxLanding from './pages/Landing/AstryxLanding';
import Pricing from './pages/Pricing/Pricing';
import PricingAstryx from './pages/Pricing/PricingAstryx';
import TrackProfile from './pages/TrackProfile/TrackProfile';
import Login from './pages/Login';
import AuthAstryx from './pages/Auth/AuthAstryx';
import ForgotPassword from './pages/Auth/ForgotPassword';
import ResetPassword from './pages/Auth/ResetPassword';
import VerifyEmail from './pages/Auth/VerifyEmail';
import Privacy from './pages/Privacy';
import Terms from './pages/Terms';
import Support from './pages/Support';
import TermsAstryx from './pages/Legal/TermsAstryx';
import PrivacyAstryx from './pages/Legal/PrivacyAstryx';
import SupportAstryx from './pages/Legal/SupportAstryx';
import PartnersAstryx from './pages/Partners/PartnersAstryx';
import RiderHome from './pages/rider/RiderHome/RiderHome';
import RiderPerks from './pages/rider/RiderPerks';
import RiderCalendar from './pages/rider/RiderCalendar/RiderCalendar';
import RiderCalendarAstryx from './pages/rider/RiderCalendar/RiderCalendarAstryx';
import RiderDashboard from './pages/rider/RiderDashboard/RiderDashboard';
import UserProfile from './pages/user/UserProfile/UserProfile';
import UserProfileAstryx from './pages/user/UserProfile/UserProfileAstryx';
import OperatorDashboard from './pages/operator/OperatorDashboard';
import OperatorReports from './pages/operator/OperatorReports';
import OperatorProfile from './pages/operator/OperatorProfile/OperatorProfile';
import OperatorCalendar from './pages/operator/OperatorCalendar/OperatorCalendar';
import OperatorCommunity from './pages/operator/OperatorCommunity/OperatorCommunity';
import AdminHome from './pages/admin/AdminHome/AdminHome';
import AdminTracks from './pages/admin/AdminTracks/AdminTracks';
import AdminUsers from './pages/admin/AdminUsers';
import AdminTiers from './pages/admin/AdminTiers';
import AdminReports from './pages/admin/AdminReports/AdminReports';
import AdminQuickBooks from './pages/admin/AdminQuickBooks';

function Guard({ roles, children }: { roles: Role[]; children: ReactNode }) {
  const { user, loading } = useAuth();
  const location = useLocation();
  if (loading) return <div className="muted" style={{ padding: 24 }}>Loading…</div>;
  if (!user) return <Navigate to="/login" state={{ from: location.pathname }} replace />;
  if (!roles.includes(user.role)) return <Navigate to={homePathFor(user.role)} replace />;
  return <>{children}</>;
}

/**
 * A route the presale closes: the network, a venue page, the rider's calendar
 * and perks. It sends the reader to `/`, which answers the same question the
 * API does — the presale page for a visitor, `/pricing` for a signed-in account
 * with no pass. The API refuses these reads on its own (middleware/presaleGate
 * on the server); this only keeps the router from mounting a page that would
 * render empty, and keeps gated deep links landing somewhere real instead of on
 * a 404.
 */
function PresaleGate({ children }: { children: ReactNode }) {
  const { presaleMode, loading } = usePresale();
  if (loading) return null;
  if (presaleMode) return <Navigate to="/" replace />;
  return <>{children}</>;
}

/**
 * The marketing homepage at `/`. It belongs to visitors: a signed-out reader
 * gets the public landing, and a signed-in account is sent to its own home. By
 * default that home is `/tracks` — the network page, which serves every role and
 * reads the same for a rider, an operator or an admin. The header's brand link
 * points here, so it still lands a signed-in reader somewhere real rather than
 * back on the sales copy.
 *
 * When `enableRiderDashboard` is on, a rider's home is the dashboard instead, so
 * the brand link opens it.
 *
 * While the presale runs every visitor gets this same home page, signed in or
 * not: the launch phase is the page's own read, so its partner band prints
 * placeholder tiles instead of a network the API refuses. A signed-in rider is
 * never bounced off `/` during the sale — the header's brand link is a promise
 * that it opens the home page — and with `/tracks` gated there is nowhere else
 * for that click to land that would read as the site's front door.
 */
function Home() {
  const { user, loading } = useAuth();
  const { phase, loading: launchLoading } = usePresale();
  // Gate on the /auth/me read and the launch read: rendering either landing
  // while one resolves would flash the wrong page for a frame.
  if (loading || launchLoading) return null;
  // An operator's home is the dashboard, not the network page.
  if (user) {
    if (user.role === 'OPERATOR') return <Navigate to="/operator/dashboard" replace />;
    if (user.role === 'RIDER' && enableRiderDashboard) return <Navigate to="/dashboard" replace />;
    // The brand link opens the home page for a signed-in account too, for the
    // length of the presale: the sale is the site's front door, and `/tracks`
    // is either gated (no pass) or a jump the reader did not ask for.
    if (phase === 'PRESALE') return enableAstryxUI ? <AstryxLanding /> : <Landing />;
    return <Navigate to="/tracks" replace />;
  }
  // Two registers: the reference design system's landing, and the original one.
  // Both stay mounted-able so flipping a flag back is a one-line change.
  return enableAstryxUI ? <AstryxLanding /> : <Landing />;
}

/**
 * The rider portal used to live under `/rider`; the network page is `/tracks`
 * now, so every old link lands on its new home: `/rider` → `/tracks`,
 * `/rider/history` → `/tracks/history`, which now lands on the profile's
 * rides card (`/user`).
 */
function RiderRedirect() {
  const { pathname, search } = useLocation();
  return <Navigate to={pathname.replace(/^\/rider\b/, '/tracks') + search} replace />;
}

export default function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route path="/" element={<Home />} />
        <Route path="/pricing" element={enableAstryxUI ? <PricingAstryx /> : <Pricing />} />

        {/* The network page, for everyone: riders read their pass there, a
            visitor reads each venue's live status. Behind the presale gate,
            which the API applies to the reads as well. */}
        <Route
          path="/tracks"
          element={
            <PresaleGate>
              <RiderHome />
            </PresaleGate>
          }
        />
        <Route
          path="/tracks/:slug"
          element={
            <PresaleGate>
              <TrackProfile />
            </PresaleGate>
          }
        />
        {/* History lives on the rider's profile now; the old route lands there. */}
        <Route path="/tracks/history" element={<Navigate to="/user" replace />} />
        {/* The rider's own calendar: the dates at the tracks they follow. Every
            rider gets it, free tier included — following is the free surface.
            Its Astryx mirror while `enableAstryxUI` is on; `RiderCalendar` is
            untouched and comes back exactly when the flag flips. `/calendar`
            is the same page under its own name — the nav's Calendar entry
            still points here. */}
        <Route
          path="/tracks/calendar"
          element={
            <Guard roles={['RIDER']}>
              <PresaleGate>
                {enableAstryxUI ? <RiderCalendarAstryx /> : <RiderCalendar />}
              </PresaleGate>
            </Guard>
          }
        />
        <Route path="/calendar" element={<Navigate to="/tracks/calendar" replace />} />
        <Route
          path="/tracks/perks"
          element={
            <Guard roles={['RIDER']}>
              <PresaleGate>
                <RiderPerks />
              </PresaleGate>
            </Guard>
          }
        />

        {/* The rider's dashboard — the signed-in rider's landing page, reached
            from the header's brand link. Paused behind `enableRiderDashboard`:
            with the flag off, a straight URL lands on the network page. */}
        <Route
          path="/dashboard"
          element={
            enableRiderDashboard ? (
              <Guard roles={['RIDER']}><RiderDashboard /></Guard>
            ) : (
              <Navigate to="/tracks" replace />
            )
          }
        />

        {/* The rider's own profile — where the account menu's identity card lands.
            The Astryx mirror while `enableAstryxUI` is on; `UserProfile` is
            untouched and comes back exactly when the flag flips. */}
        <Route
          path="/user"
          element={
            <Guard roles={['RIDER']}>
              {enableAstryxUI ? <UserProfileAstryx /> : <UserProfile />}
            </Guard>
          }
        />

        <Route path="/rider/*" element={<RiderRedirect />} />

        {/* Two auth pages, one component: sign-in and account creation. The
            Astryx pair while `enableAstryxUI` is on; `Login` is untouched. */}
        <Route
          path="/login"
          element={enableAstryxUI ? <AuthAstryx mode="login" /> : <Login mode="login" />}
        />
        <Route
          path="/signup"
          element={enableAstryxUI ? <AuthAstryx mode="register" /> : <Login mode="register" />}
        />
        {/* The reset path off the sign-in card. Both pages wear the Astryx card
            (AuthAstryx.scss) whatever the flag says: they are new surfaces, not a
            second register of an existing one, so there is no plain twin to keep
            in step. The flag still picks the sign-in page they lead back to. */}
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/reset-password" element={<ResetPassword />} />
        {/* The step between signing up and signing in: the link a signup mails
            lands here (?token=…), and a fresh signup is sent here to wait on it. */}
        <Route path="/verify-email" element={<VerifyEmail />} />
        {/* The three document pages, in the reference design system's register
            while `enableAstryxUI` is on. `Terms`, `Privacy` and `Support` are
            untouched and come back exactly when the flag flips. */}
        <Route
          path="/privacy"
          element={enableAstryxUI ? <PrivacyAstryx /> : <Privacy />}
        />
        <Route path="/terms" element={enableAstryxUI ? <TermsAstryx /> : <Terms />} />
        {/* Where the account menu's Support entry and the footer's Support link
            land, instead of opening a mail client. */}
        <Route
          path="/support"
          element={enableAstryxUI ? <SupportAstryx /> : <Support />}
        />

        {/* The track-owner page the landing's invitation band opens. It has no
            plain twin to mirror, so it wears the Astryx register whatever the
            flag says, like the two reset pages. */}
        <Route path="/partners" element={<PartnersAstryx />} />

        {/* The operator's home: the dashboard — the scanning station alone. */}
        <Route path="/operator/dashboard" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorDashboard /></Guard>} />
        {/* The season's read and the activity log; split off the dashboard. */}
        <Route path="/operator/reports" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorReports /></Guard>} />
        <Route path="/operator/profile" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorProfile /></Guard>} />
        {/* Where the season is written; the profile page only reads it. */}
        <Route path="/operator/calendar" element={<Guard roles={['OPERATOR', 'ADMIN']}><OperatorCalendar /></Guard>} />
        {/* The venue's community — who rides here, and the photos they post.
            Paused: see enableCommunity in lib/featureFlags.ts. A straight URL
            lands on the dashboard while it is off, so nothing dead-links. */}
        <Route
          path="/operator/community"
          element={
            enableCommunity ? (
              <Guard roles={['OPERATOR', 'ADMIN']}><OperatorCommunity /></Guard>
            ) : (
              <Navigate to="/operator/dashboard" replace />
            )
          }
        />
        {/* The page was the followers view; old links land on the community. */}
        <Route
          path="/operator/followers"
          element={<Navigate to={enableCommunity ? '/operator/community' : '/operator/dashboard'} replace />}
        />
        {/* The scanning station lived at /scan (and at /operator before that),
            so both land on the dashboard; the log has its own page again. */}
        <Route path="/scan" element={<Navigate to="/operator/dashboard" replace />} />
        <Route path="/operator" element={<Navigate to="/operator/dashboard" replace />} />
        <Route path="/operator/log" element={<Navigate to="/operator/reports" replace />} />

        <Route path="/admin" element={<Guard roles={['ADMIN']}><AdminHome /></Guard>} />
        <Route path="/admin/tracks" element={<Guard roles={['ADMIN']}><AdminTracks /></Guard>} />
        <Route path="/admin/users" element={<Guard roles={['ADMIN']}><AdminUsers /></Guard>} />
        <Route path="/admin/tiers" element={<Guard roles={['ADMIN']}><AdminTiers /></Guard>} />
        <Route path="/admin/reports" element={<Guard roles={['ADMIN']}><AdminReports /></Guard>} />
        <Route path="/admin/quickbooks" element={<Guard roles={['ADMIN']}><AdminQuickBooks /></Guard>} />

        <Route path="*" element={<div className="card">Not found.</div>} />
      </Route>
    </Routes>
  );
}

