import { useRef, useState } from 'react';
import { api } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import Avatar from '../Avatar/Avatar';
import './AvatarPicker.scss';

const MAX_BYTES = 5 * 1024 * 1024;
const ACCEPT = 'image/png,image/jpeg,image/webp,image/gif,image/avif';

/**
 * The rider's own profile photo, shown inside the Details sheet.
 *
 * The picked file is read to a data URL and POSTed to `/auth/me/avatar`; the
 * server stores it and answers the managed reference that `/auth/me` carries
 * from then on, so the page refreshes the account rather than holding its own
 * copy. Removing the photo clears the field and the pixel-pattern fallback
 * comes back. The checks here mirror the server's (type and 5 MB) only to spare
 * a doomed request — the server is still the boundary.
 */
export default function AvatarPicker({ className = 'avatar-picker' }: { className?: string }) {
  const { user, refresh } = useAuth();
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  if (!user) return null;

  const save = async (dataUrl: string | null) => {
    setErr(null);
    setBusy(true);
    try {
      const res = dataUrl
        ? await api.post<{ url: string }>('/auth/me/avatar', { dataUrl })
        : await api.patch('/auth/me', { avatarUrl: '' });
      if (!res.success) {
        setErr(res.message || 'Could not save your photo.');
        return;
      }
      await refresh();
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Could not save your photo.');
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const pick = async (file: File) => {
    setErr(null);
    if (!ACCEPT.split(',').includes(file.type)) {
      setErr('Upload a PNG, JPG, WEBP, GIF or AVIF image.');
      return;
    }
    if (file.size > MAX_BYTES) {
      setErr('That image is too large — keep it under 5 MB.');
      return;
    }
    const dataUrl = await new Promise<string>((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => resolve(String(fr.result));
      fr.onerror = () => reject(new Error('Could not read that file.'));
      fr.readAsDataURL(file);
    }).catch((e: unknown) => {
      setErr(e instanceof Error ? e.message : 'Could not read that file.');
      return '';
    });
    if (dataUrl) await save(dataUrl);
  };

  return (
    <div className={`${className} avatar-picker`}>
      <Avatar src={user.avatarUrl} name={user.name} className="avatar-picker-photo" />
      <div className="avatar-picker-text">
        <span className="avatar-picker-label">Photo</span>
        <div className="avatar-picker-actions">
          <input
            ref={fileRef}
            type="file"
            accept={ACCEPT}
            style={{ display: 'none' }}
            onChange={(e) => {
              const f = e.target.files?.[0];
              if (f) void pick(f);
            }}
          />
          <button
            type="button"
            className="ghost small"
            disabled={busy}
            onClick={() => fileRef.current?.click()}
          >
            {busy ? 'Uploading…' : user.avatarUrl ? 'Change photo' : 'Upload photo'}
          </button>
          {user.avatarUrl && (
            <button type="button" className="ghost small" disabled={busy} onClick={() => void save(null)}>
              Remove
            </button>
          )}
        </div>
        <span className="tiny muted">Square images crop best. PNG, JPG, WEBP, GIF or AVIF, under 5 MB.</span>
        {err && (
          <div className="tiny bad-text" role="alert">
            {err}
          </div>
        )}
      </div>
    </div>
  );
}

