import { useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import type { ProfileEvent } from '../../lib/events';
import { ampmTime, dayRange } from '../../lib/events';
import './EventReadSheet.scss';

/**
 * A date read, not written: the owner's event sheet with every control taken
 * out. A rider and a signed-out visitor both open it — neither one owns the
 * date — so it names what is on and stops. No Save, no Remove, no field to
 * type into: the date reads as a sentence and the note as a paragraph, the way
 * a reader would say them.
 *
 * The one fact the owner's sheet keeps to itself is `isActive`: the public
 * reads serve active dates only, so there is no Shown row here to lie with.
 * Escape, the backdrop and the × in the top-right corner all put it away.
 */
export default function EventReadSheet({
  event,
  banner,
  onClose,
}: {
  event: ProfileEvent;
  /**
   * The track the date is at, drawn as its profile banner at the foot of the
   * read: the venue's photo beside its name and place, the row opening its
   * profile page. A rider's week holds every track they follow, so the sheet
   * says which venue each date is at — and it says it here, never in the head,
   * so the head stays the date's own. `photo` is null for a venue with nothing
   * shot: the row still names it.
   */
  banner?: { name: string; slug: string; where?: string | null; photo?: string | null } | null;
  onClose: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  /* Focus lands on the panel once, when the sheet opens — its own effect, with
     no dependency. `onClose` is a fresh arrow every render of the page, so
     folding this into the listener below re-ran it on every keystroke and
     pulled the cursor back out to the panel: one character in, the rest of the
     typing went nowhere. */
  useEffect(() => {
    panel.current?.focus();
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const from = event.startMinutes;
  const to = event.endMinutes;
  // The hours are a pair, so a date either carries both or reads all-day — the
  // same read `ampmLabel` makes of it on a card.
  const timed = from != null || to != null;

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet event-sheet event-read"
        role="dialog"
        aria-modal="true"
        aria-labelledby="event-read-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="row wrap spread event-read-head">
          <h4 className="sheet-title" id="event-read-title">
            {event.title}
          </h4>
          <button type="button" className="event-read-close" onClick={onClose} aria-label="Close the event">
            <svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true">
              <path d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {/* Nothing to read back out of a well: the when on one line, then the
            note. The hours the date runs are already in the sentence, so the
            span it works out to is not repeated beside it. */}
        <div className="event-read-body">
          <div className="ev-readback">
            <p className="ev-note">{readSentence(event, timed, from, to)}</p>
          </div>

          {event.description && <p className="event-read-note">{event.description}</p>}
        </div>

        {/* The track's own profile banner, at the foot of the read: a small cut
            of the venue's photo on the left, its name and place on the right,
            and the whole row the way onto that page. A venue with nothing shot
            still gets the row — the date says where it is either way. */}
        {banner && (
          <Link className="event-read-banner" to={`/tracks/${banner.slug}`}>
            {banner.photo ? (
              <img className="event-read-banner-thumb" src={banner.photo} alt="" loading="lazy" />
            ) : (
              <span className="event-read-banner-thumb event-read-banner-thumb-fallback" aria-hidden="true" />
            )}
            <span className="event-read-banner-text">
              <span className="event-read-banner-name">{banner.name}</span>
              {banner.where && <span className="event-read-banner-where">{banner.where}</span>}
            </span>
            <svg className="event-read-banner-go" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true">
              <path d="M6 3.5L10.5 8 6 12.5" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </Link>
        )}
      </div>
    </div>
  );
}

/** The date said the way the owner's own sheet says it, in a reader's words. */
function readSentence(ev: ProfileEvent, timed: boolean, from: number | null, to: number | null) {
  const when = dayRange(ev);
  if (!timed) return `All day on ${when}.`;
  if (from != null && to != null) return `From ${ampmTime(from)} until ${ampmTime(to)}, ${when}.`;
  if (from != null) return `Opens ${ampmTime(from)}, ${when}.`;
  return `Closes ${ampmTime(to!)}, ${when}.`;
}

/* FollowButton — styles owned by FollowButton.tsx.
   Split out of styles/global.scss; imported once from FollowButton.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The follow toggle. Following is open to every account — a free one included —
   so it reads as a quiet control, then fills in once it is on. */
.follow-toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  background: none;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  cursor: pointer;
}

.follow-toggle:hover { color: var(--text); border-color: var(--muted); }

.follow-toggle.on { color: var(--accent); border-color: rgba(var(--accent-rgb), 0.45); }

.follow-toggle:disabled { opacity: 0.6; cursor: default; }

.follow-toggle svg { flex: 0 0 auto; }

/* The moment following lands: the control takes one short punch and its action
   glyph draws itself in — transform and stroke only, so nothing under it moves.
   Fires on the click, not on the tracks the server already had followed when
   the list opened; those paint in place. */
.follow-toggle.pulse {
  animation: follow-punch 340ms cubic-bezier(0.2, 0.9, 0.25, 1);
}

.follow-toggle.pulse svg path:last-of-type {
  stroke-dasharray: 12;
  animation: follow-draw 300ms cubic-bezier(0.2, 0.9, 0.25, 1) 90ms forwards;
}

@keyframes follow-punch {
  0% { transform: scale(1); }
  35% { transform: scale(1.14); }
  70% { transform: scale(0.97); }
  100% { transform: scale(1); }
}

@keyframes follow-draw {
  from { stroke-dashoffset: 12; }
  to { stroke-dashoffset: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .follow-toggle.pulse,
  .follow-toggle.pulse svg path:last-of-type { animation: none; }
}

import { useEffect, useRef, useState } from 'react';
import { api } from '../../lib/api';
import './FollowButton.scss';

/** How long the click's one authored moment runs: the longest of the punch,
 *  the glyph draw and the ring, with a little headroom. */
const PULSE_MS = 700;

/**
 * The follow toggle. Following a track is what a free account does with the
 * network, so the control is live on every tier; the server is the source of
 * truth and this only mirrors the last response. The control names the action
 * it takes rather than the state it is in: a rider who already follows the
 * track reads "Unfollow", one who does not reads "Follow". The glyph is a rider
 * and the mark that goes with that action — a plus to add the track, a minus
 * to drop it. `iconOnly` drops the label and leaves the glyph, for a control
 * that sits on a photo's corner.
 *
 * A click also lands the control: `pulse` carries the class that fires the
 * punch and the glyph's draw-in, so a card the server already had followed
 * opens without animating and only the click moves. The class is restarted on
 * every click — off and back on — so a repeat fires it again.
 */
export default function FollowButton({
  trackId,
  name,
  following,
  onChange,
  compact = false,
  iconOnly = false,
}: {
  trackId: string;
  name: string;
  following: boolean;
  onChange?: (following: boolean) => void;
  compact?: boolean;
  iconOnly?: boolean;
}) {
  const [on, setOn] = useState(following);
  const [busy, setBusy] = useState(false);
  const [pulse, setPulse] = useState(false);
  const pulseTimer = useRef<number | undefined>(undefined);

  /**
   * The control outlives the venue it names: the inspector over the map keeps
   * one instance and re-points it at whichever venue is picked next, so the
   * flag mirrored from the last one would stand on every venue that follows —
   * a rider who follows one track would read every other track as followed
   * too. Mirror the prop again whenever the venue changes or the server's own
   * flag lands.
   */
  useEffect(() => {
    setOn(following);
  }, [trackId, following]);

  useEffect(() => () => window.clearTimeout(pulseTimer.current), []);

  const toggle = async () => {
    setBusy(true);
    const next = !on;
    const res = next
      ? await api.post<{ following: boolean }>(`/me/follows/${trackId}`)
      : await api.del<{ following: boolean }>(`/me/follows/${trackId}`);
    setBusy(false);
    if (!res.success) return;
    setOn(next);
    onChange?.(next);
    /* Drop the class, then re-add it on the next frame: the computed animation
       goes to `none` and back, so the moment runs even on a rapid repeat. */
    setPulse(false);
    window.clearTimeout(pulseTimer.current);
    window.requestAnimationFrame(() => {
      setPulse(true);
      pulseTimer.current = window.setTimeout(() => setPulse(false), PULSE_MS);
    });
  };

  return (
    <button
      type="button"
      className={`follow-toggle ${on ? 'on' : ''} ${pulse ? 'pulse' : ''} ${
        compact ? 'compact' : ''
      } ${iconOnly ? 'icon-only' : ''}`}
      aria-pressed={on}
      aria-label={on ? `Unfollow ${name}` : `Follow ${name}`}
      title={on ? `Unfollow ${name}` : `Follow ${name}`}
      disabled={busy}
      onClick={toggle}
    >
      <svg width="13" height="13" viewBox="0 0 16 16" aria-hidden="true">
        {/* The rider: a head over a shoulder line. */}
        <circle
          cx="4.8"
          cy="4.8"
          r="2.4"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.3"
        />
        <path
          d="M0.9 13.3c0-2.3 1.75-4 3.9-4s3.9 1.7 3.9 4"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.3"
          strokeLinecap="round"
        />
        {/* The action: add the track, or drop it again. */}
        {on ? (
          <path
            d="M10.1 10.3h5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        ) : (
          <path
            d="M12.5 7.8v5M10.1 10.3h5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        )}
      </svg>
      {!iconOnly && <span>{on ? 'Unfollow' : 'Follow'}</span>}
    </button>
  );
}

