import { useRef, useState, type DragEvent } from 'react';
import { api } from '../../lib/api';
import { cleanLine } from '../../lib/sanitize';
import PhotoLightbox from '../PhotoLightbox/PhotoLightbox';
import { dropSide, insertAt, reorder } from '../../lib/dragReorder';
import './GalleryManager.scss';

export interface OwnerPhoto {
  id: string;
  url: string;
  caption: string | null;
  category: string;
}

const CATEGORIES = ['TRACK', 'FACILITY', 'RACE_DAY'];
const CATEGORY_LABEL: Record<string, string> = {
  TRACK: 'Track',
  FACILITY: 'Facility',
  RACE_DAY: 'Race day',
};

const MAX_PHOTOS = 24;

/**
 * The venue's photo gallery in the owner console.
 *
 * The first photo is the one the public page opens on, so order is the whole
 * point of this panel: move a frame up and it moves up there. Order can be
 * changed three ways — the arrows on each row, dragging a row by its grip, and
 * dragging the frames in the full-screen viewer — and all of them save the same
 * way, by posting the whole id list.
 *
 * Adding accepts a file (read to a data URL, then stored on Spaces or local
 * disk) or a URL to an image already hosted elsewhere, the same two ways the
 * banner picker works.
 */
export default function GalleryManager({
  photos,
  trackId,
  onChange,
  onMessage,
}: {
  photos: OwnerPhoto[];
  /** Only sent so an admin editing another venue resolves the right one. */
  trackId?: string;
  onChange: (photos: OwnerPhoto[]) => void;
  onMessage: (msg: string) => void;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [url, setUrl] = useState('');
  const [busy, setBusy] = useState(false);
  // Which frame the operator has opened full screen, if any.
  const [viewing, setViewing] = useState<number | null>(null);
  // Dragging a row: which one is in hand, and which gap it would land in.
  const [dragFrom, setDragFrom] = useState<number | null>(null);
  const [dropAt, setDropAt] = useState<{ index: number; side: 'before' | 'after' } | null>(null);

  const withTrack = (body: Record<string, unknown>) => (trackId ? { ...body, trackId } : body);

  const add = async (payload: { dataUrl?: string; url?: string }) => {
    setBusy(true);
    const res = await api.post<{ photo: OwnerPhoto }>(
      '/owner/track/photos',
      withTrack({
        ...payload,
        ...(payload.url !== undefined ? { url: cleanLine(payload.url, 600) } : {}),
      })
    );
    setBusy(false);
    onMessage(res.message ?? (res.success ? 'Photo added.' : 'Could not add that photo.'));
    if (res.success && res.data?.photo) {
      onChange([...photos, res.data.photo]);
      setUrl('');
    }
  };

  const pickFile = async (file: File) => {
    const dataUrl = await new Promise<string>((resolve, reject) => {
      const fr = new FileReader();
      fr.onload = () => resolve(String(fr.result));
      fr.onerror = () => reject(new Error('Could not read that file.'));
      fr.readAsDataURL(file);
    }).catch(() => '');
    if (fileRef.current) fileRef.current.value = '';
    if (!dataUrl) {
      onMessage('Could not read that file.');
      return;
    }
    await add({ dataUrl });
  };

  const edit = async (id: string, patch: { category?: string; caption?: string }) => {
    const clean = {
      ...patch,
      ...(patch.caption !== undefined ? { caption: cleanLine(patch.caption, 200) } : {}),
    };
    onChange(photos.map((p) => (p.id === id ? { ...p, ...clean } : p)));
    const res = await api.patch(`/owner/track/photos/${id}`, withTrack(clean));
    if (!res.success) onMessage(res.message ?? 'Could not save that photo.');
  };

  /**
   * Put the frame at `from` into the gap at `toInsert` (0…length, in the list as
   * it stands now). The open frame in the viewer is followed across the move, so
   * a drag never swaps the photo out from under the operator.
   */
  const moveTo = async (from: number, toInsert: number) => {
    const { items: next, moved } = reorder(photos, from, toInsert);
    if (next.every((p, i) => p.id === photos[i].id)) return;
    onChange(next);
    setViewing((v) => (v === null ? v : moved[v] ?? v));
    const res = await api.post('/owner/track/photos/reorder', withTrack({ ids: next.map((p) => p.id) }));
    if (!res.success) onMessage(res.message ?? 'Could not reorder the gallery.');
  };

  const move = (index: number, by: number) => moveTo(index, index + (by > 0 ? 2 : -1));

  const endDrag = () => {
    setDragFrom(null);
    setDropAt(null);
  };

  const dragOver = (e: DragEvent<HTMLDivElement>, index: number) => {
    if (dragFrom === null) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const side = dropSide(e, e.currentTarget.getBoundingClientRect());
    setDropAt((prev) => (prev && prev.index === index && prev.side === side ? prev : { index, side }));
  };

  const drop = (e: DragEvent<HTMLDivElement>) => {
    if (dragFrom === null || !dropAt) return;
    e.preventDefault();
    const to = insertAt(dropAt.index, dropAt.side);
    endDrag();
    // Dropping a frame onto either side of itself is a no-op, not a save.
    if (to !== dragFrom && to !== dragFrom + 1) moveTo(dragFrom, to);
  };

  const remove = async (id: string) => {
    const res = await api.del(`/owner/track/photos/${id}${trackId ? `?trackId=${trackId}` : ''}`);
    onMessage(res.message ?? (res.success ? 'Photo removed.' : 'Could not remove that photo.'));
    if (res.success) {
      onChange(photos.filter((p) => p.id !== id));
      setViewing(null);
    }
  };

  return (
    <section className="card stack">
      <h3>Photos</h3>
      <p className="small muted" style={{ margin: 0 }}>
        The first frame is what the venue page opens on. Drag a frame by its grip to reorder. {photos.length} of{' '}
        {MAX_PHOTOS}.
      </p>

      {photos.length === 0 && <div className="small muted">No photos yet. The page falls back to the banner.</div>}

      <div className="gallery-manager">
        {photos.map((p, i) => (
          <div
            key={p.id}
            className={[
              'gallery-row',
              dragFrom === i ? 'dragging' : '',
              dropAt && dropAt.index === i && dragFrom !== null ? `drop-${dropAt.side}` : '',
            ]
              .filter(Boolean)
              .join(' ')}
            onDragOver={(e) => dragOver(e, i)}
            onDragLeave={() => setDropAt((prev) => (prev && prev.index === i ? null : prev))}
            onDrop={drop}
          >
            <button
              type="button"
              className="gallery-grip"
              draggable
              onDragStart={(e) => {
                setDragFrom(i);
                e.dataTransfer.effectAllowed = 'move';
                // Firefox only starts a drag with some data set.
                e.dataTransfer.setData('text/plain', p.id);
              }}
              onDragEnd={endDrag}
              aria-label={`Drag photo ${i + 1} to reorder`}
              title="Drag to reorder"
            >
              <svg width="10" height="16" viewBox="0 0 10 16" aria-hidden="true" fill="currentColor">
                <circle cx="3" cy="4" r="1.2" />
                <circle cx="7" cy="4" r="1.2" />
                <circle cx="3" cy="8" r="1.2" />
                <circle cx="7" cy="8" r="1.2" />
                <circle cx="3" cy="12" r="1.2" />
                <circle cx="7" cy="12" r="1.2" />
              </svg>
            </button>
            <div className="gallery-thumb">
              <button
                type="button"
                className="gallery-thumb-open"
                onClick={() => setViewing(i)}
                aria-label={`Open photo ${i + 1} full screen`}
                title="Open full screen"
              >
                <img src={p.url} alt="" draggable={false} />
              </button>
            </div>
            <div className="gallery-fields">
              <select
                value={p.category}
                onChange={(e) => edit(p.id, { category: e.target.value })}
                aria-label="Photo category"
              >
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>
                    {CATEGORY_LABEL[c]}
                  </option>
                ))}
              </select>
              <input
                placeholder="Caption (optional)"
                defaultValue={p.caption ?? ''}
                onBlur={(e) => {
                  if ((e.target.value || '') !== (p.caption ?? '')) edit(p.id, { caption: e.target.value });
                }}
              />
            </div>
            <div className="row gallery-row-actions">
              {i === 0 && <span className="tiny muted">Opening frame</span>}
              <button type="button" className="ghost small" disabled={i === 0} onClick={() => move(i, -1)}>
                ↑
              </button>
              <button
                type="button"
                className="ghost small"
                disabled={i === photos.length - 1}
                onClick={() => move(i, 1)}
              >
                ↓
              </button>
              <button type="button" className="ghost small danger" onClick={() => remove(p.id)}>
                Remove
              </button>
            </div>
          </div>
        ))}
      </div>

      {viewing !== null && photos[viewing] && (
        <PhotoLightbox
          photos={photos}
          name="Gallery"
          index={viewing}
          onIndex={setViewing}
          onClose={() => setViewing(null)}
          onReorder={moveTo}
        />
      )}

      <div className="row wrap image-picker-controls">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
          style={{ display: 'none' }}
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) pickFile(f);
          }}
        />
        <button
          type="button"
          className="ghost small"
          disabled={busy || photos.length >= MAX_PHOTOS}
          onClick={() => fileRef.current?.click()}
        >
          {busy ? 'Adding…' : 'Add a photo'}
        </button>
        <input
          className="image-url"
          placeholder="…or paste an image URL"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && url.trim()) add({ url: url.trim() });
          }}
        />
        <button
          type="button"
          className="ghost small"
          disabled={busy || !url.trim() || photos.length >= MAX_PHOTOS}
          onClick={() => add({ url: url.trim() })}
        >
          Add from URL
        </button>
      </div>
    </section>
  );
}

/* HoursWeek — styles owned by HoursWeek.tsx.
   Split out of styles/global.scss; imported once from HoursWeek.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The week itself: a real table, one row a day, so the day and its hours line
   up as two columns instead of reading as a list of sentences. The reader's own
   day keeps its mark. A shut day reads "Closed", never blank, and every line is
   full-strength ink — the only muted text is the parenthesised date, which is an
   aside to the day label. The table wears no outer border: a hairline between
   rows is the whole grid. It sits in the profile's Location & Hours block (see
   `.loc-*` at the end of this file), so it carries no card material of its own. */
.hours-week {
  width: 100%;
  margin: 0;
  border-collapse: collapse;
  border: 0;
}

/* Inner rules only — no border above the first row or below the last, and no
   left/right edge, so the block stays flush with its column. */
.hours-row th,
.hours-row td {
  padding: 7px 8px;
  border: 0;
  border-top: 1px solid var(--line);
  text-align: left;
  vertical-align: baseline;
}

.hours-row:first-child th,
.hours-row:first-child td { border-top: 0; }

/* Day column: fixed width so the seven dates line up down the table. */
.hours-row th {
  width: 116px;
  font-size: 13px;
  font-weight: 400;
  color: var(--text);
  letter-spacing: normal;
  white-space: nowrap;
}

.hours-row th abbr { text-decoration: none; letter-spacing: 0.02em; }

/* This week's date beside the day, so the repeating week is anchored: Mon reads
   "Mon (11/02)". Tabular so the seven dates line up down the column, and the
   one piece of muted text in the block. */
.hours-date { margin-left: 8px; white-space: nowrap; color: var(--muted); font-variant-numeric: tabular-nums; }

.hours-row td.hours-value { font-size: 14px; font-variant-numeric: tabular-nums; }

/* Today's row carries no shading and no accent: the only mark on it is the
   plain "Open now" line, sitting beside the hours in the same cell so the
   rule above each row runs the full width. */
.hours-row .status-pill { margin-left: 10px; padding: 0; border: 0; background: none; white-space: nowrap; }

/* The state reads as bare coloured text, never a chip: "Open now" takes the app's own
   ok green, so it lands beside the hours the way a plain line does. */
.hours-row .status-pill.status-open { color: var(--ok); }

.hours-summary { margin: 0; font-size: 14px; }

/* On the profile the week is a read-only column of days, not a list to pick
   from, so the global row-hover tint (`tbody tr:hover` in global.scss) is
   dropped here — nothing on these rows is clickable. */
.profile-loc .hours-week tbody tr:hover { background: transparent; }

/* The week is a column of days beside the map, not a card of its own — the
   material it would have worn is stripped here. */
.hours-week-block { margin: 0; }

import {
  dateLabel,
  HOURS_CLOSED,
  HOURS_WEEK_DAYS,
  stripHoursLabel,
  todayHoursKey,
  weekDates,
  type HoursWeek as Week,
} from '../../lib/hoursWeek';
import { TRACK_STATUS_CLASS, statusLabel } from '../../lib/trackAccess';
import './HoursWeek.scss';

/**
 * The venue's week on its profile: one line per day, with the day the reader is
 * on marked, so "can I ride today" is answered without counting rows. The live
 * venue status rides on today's own line, read off fields on file, never a
 * computed open/close time (the week is free text, so there is no time in it to
 * count down from).
 *
 * A venue with no week on file falls back to the single hours line the network
 * rail already reads, rather than showing seven empty days.
 */
export default function HoursWeek({
  week,
  summary,
  status,
}: {
  week: Week | null;
  summary?: string | null;
  /** The venue's live status (OPEN / WEATHER_HOLD / CLOSED) — drawn on today. */
  status?: string | null;
}) {
  if (!week) {
    if (!summary) return null;
    return (
      <section className="stack hours-week-block">
        <h3>Hours</h3>
        <p className="hours-summary">{summary}</p>
      </section>
    );
  }

  const today = todayHoursKey();
  // The week repeats, so each day label carries this week's date: "Wed" alone
  // does not say whether that Wednesday has already gone by.
  const dates = weekDates();
  const todayValue = week[today] || HOURS_CLOSED;
  const running = todayValue !== HOURS_CLOSED;

  return (
    <section className="stack hours-week-block">
      <h3>Hours</h3>
      {/* A real table, so the day and its hours are two columns rather than two
          halves of a sentence. Only inner rules are drawn (see the sheet). */}
      <table className="hours-week">
        <tbody>
          {HOURS_WEEK_DAYS.map(({ key, label, full }) => {
            const value = week[key] || HOURS_CLOSED;
            const isToday = key === today;
            return (
              <tr key={key} className={isToday ? 'hours-row is-today' : 'hours-row'}>
                <th scope="row">
                  <abbr title={full}>{label}</abbr>
                  {/* The date sits in parentheses, so it reads as an aside to the
                      repeating day label rather than a second column of text. */}
                  <span className="hours-date">({dateLabel(dates[key])})</span>
                </th>
                <td className={value === HOURS_CLOSED ? 'hours-value is-closed' : 'hours-value'}>
                  {/* The row already says these are hours, so the stored line's
                      own label ("Practice") comes off: 9am–4pm. */}
                  {stripHoursLabel(value)}
                  {/* The live status, on the one row it belongs to: a venue
                      running today says so, and the pill's own class carries the
                      state. It rides in the hours cell so the rule stays one
                      width on every row. */}
                  {isToday && running && status && (
                    <span className={`status-pill ${TRACK_STATUS_CLASS[status] ?? 'status-open'}`}>
                      {status === 'OPEN' ? 'Open now' : statusLabel(status)}
                    </span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </section>
  );
}

/* ImagePicker — styles owned by ImagePicker.tsx.
   Split out of styles/global.scss; imported once from ImagePicker.tsx and
   still plain global class names (this app uses no CSS modules). */

.image-picker label { display: block; }

.image-preview {
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px dashed var(--line);
  border-radius: var(--radius);
  background: var(--bg-3);
  overflow: hidden;
}

.image-preview.wide { aspect-ratio: 16 / 5; max-height: 200px; }

.image-preview.square { width: 96px; height: 96px; }

.image-preview img { width: 100%; height: 100%; object-fit: cover; display: block; }

.bad-text { color: var(--bad); }

import { useRef, useState } from 'react';
import { api } from '../../lib/api';
import './ImagePicker.scss';

/**
 * One image slot in the track-profile console — the banner or the logo.
 *
 * Two ways in, because an owner may have the art in either place: pick a file
 * (it is read to a data URL, POSTed to /owner/track/assets, and comes back as a
 * managed reference — /api/media/<key> on Spaces, /api/uploads/<key> on local
 * disk) or paste a URL to an image already hosted elsewhere.
 * Either way the value that is kept on the track is a URL.
 */
export default function ImagePicker({
  label,
  kind,
  value,
  trackId,
  onChange,
  wide = false,
}: {
  label: string;
  kind: 'banner' | 'logo';
  value: string | null;
  /** Only sent so an admin editing another track resolves the right one. */
  trackId?: string;
  onChange: (url: string | null) => void;
  wide?: boolean;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const upload = async (file: File) => {
    setErr(null);
    setBusy(true);
    try {
      const dataUrl = await new Promise<string>((resolve, reject) => {
        const fr = new FileReader();
        fr.onload = () => resolve(String(fr.result));
        fr.onerror = () => reject(new Error('Could not read that file.'));
        fr.readAsDataURL(file);
      });
      const res = await api.post<{ url: string }>('/owner/track/assets', {
        kind,
        dataUrl,
        ...(trackId ? { trackId } : {}),
      });
      if (!res.success || !res.data?.url) {
        setErr(res.message || 'Upload failed.');
        return;
      }
      onChange(res.data.url);
    } catch (e) {
      setErr(e instanceof Error ? e.message : 'Upload failed.');
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  return (
    <div className="stack image-picker">
      <label>{label}</label>
      <div className={`image-preview ${wide ? 'wide' : 'square'}`}>
        {value ? <img src={value} alt="" /> : <span className="tiny muted">No image</span>}
      </div>
      <div className="row wrap image-picker-controls">
        <input
          ref={fileRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
          style={{ display: 'none' }}
          onChange={(e) => {
            const f = e.target.files?.[0];
            if (f) upload(f);
          }}
        />
        <button type="button" className="ghost small" disabled={busy} onClick={() => fileRef.current?.click()}>
          {busy ? 'Uploading…' : 'Upload image'}
        </button>
        {value && (
          <button type="button" className="ghost small" onClick={() => onChange(null)}>
            Clear
          </button>
        )}
      </div>
      <input
        className="image-url"
        placeholder="…or paste an image URL"
        value={value ?? ''}
        onChange={(e) => onChange(e.target.value || null)}
      />
      {err && <div className="tiny bad-text">{err}</div>}
    </div>
  );
}

/* AstryxNav — styles owned by AstryxNav.tsx (the shell header while
   `enableAstryxUI` is on).

   The header carries its own token block, scoped to `.ax-nav`, exactly as the
   Astryx pages scope theirs to `.ax-page` / `.axp-page`, so the reference
   system's surfaces, ink and radii never leak into the rest of the shell.
   Nothing here writes to `:root`.

   The bar itself is glass: nothing at rest, so the page opens edge to edge
   under it, then a slight tint of its own ground plus a backdrop blur once the
   page has moved beneath it. The tint and the ink follow the theme, because a
   transparent bar has to answer for the page behind it — the one exception is
   the landing's hero photograph, which no palette can answer for, so that state
   takes the light ink pair in either theme (`.over-photo`). */

.ax-nav {
  /* Surfaces. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;

  /* Pointer states, in the ink's own colour at two weights. */
  --ax-hover: rgba(242, 244, 246, 0.06);
  --ax-hover-strong: rgba(242, 244, 246, 0.08);

  /* The chrome the bar wears once scrolled: its own ground at ~60%, thin enough
     that the page keeps reading through the blur. */
  --ax-chrome: rgba(17, 17, 18, 0.6);

  /* The accent is Moto Pass's own orange, and it has one job in this bar: the
     free tier's Upgrade chip. Nothing navigational wears it. The two edges are
     the accent at the chip's hairline and hover weights. */
  --ax-accent: #ff8a3f;
  --ax-accent-line: rgba(255, 138, 63, 0.45);
  --ax-accent-tint: rgba(255, 138, 63, 0.12);

  /* Radii and the one motion step the controls use. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-pill: 999px;
  --ax-e-fast: 100ms;

  /* Floating layers only. */
  --ax-shadow: 0 4px 6px rgba(0, 0, 0, 0.35), 0 12px 24px rgba(0, 0, 0, 0.45);

  position: sticky;
  top: 0;
  /* Above the network map: Leaflet's panes (400) and controls (1000) are
     positioned with a z-index while the map pane is no stacking context, so
     they compete here at the root — the account menu and the compact Menu
     panel have to clear them. Under the sheet (1200) and the toasts (1100). */
  z-index: 1050;
  background: transparent;
  border-bottom: 1px solid transparent;
  font-family: 'Figtree Variable', Figtree, system-ui, -apple-system, 'Segoe UI', sans-serif;
  transition: background 200ms ease, border-color 200ms ease, box-shadow 200ms ease,
    backdrop-filter 200ms ease;
}

/* Scrolled: the page is moving under the bar, so it takes a slight tint of its
   own ground and a blur — enough for the type to hold its contrast over
   whatever passes beneath, thin enough that the bar still reads as glass. */
.ax-nav.is-scrolled {
  background: var(--ax-chrome);
  border-bottom-color: var(--ax-line);
  backdrop-filter: blur(14px) saturate(1.1);
  -webkit-backdrop-filter: blur(14px) saturate(1.1);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.16);
}

/* The light palette, restated for the bar. A transparent header answers for the
   page behind it, so the ink flips with the theme: white on #f1f4f7 has nothing
   to sit on. `:not(.over-photo)` keeps the photograph's own pair below, which is
   dark in either theme. */
:root[data-theme='light'] .ax-nav:not(.over-photo) {
  --ax-body: #f1f4f7;
  --ax-surface: #ffffff;
  --ax-raised: #ffffff;
  --ax-line: rgba(5, 54, 89, 0.1);
  --ax-line-strong: #ccd3db;

  --ax-ink: #0a1317;
  --ax-ink-2: #4e606f;

  --ax-hover: rgba(5, 54, 89, 0.06);
  --ax-hover-strong: rgba(5, 54, 89, 0.09);

  --ax-chrome: rgba(241, 244, 247, 0.66);

  /* The burnt orange the light pages use; #ff8a3f sits at ~2:1 on white. */
  --ax-accent: #eb6e00;
  --ax-accent-line: rgba(235, 110, 0, 0.45);
  --ax-accent-tint: rgba(235, 110, 0, 0.1);

  --ax-shadow: 0 4px 6px rgba(5, 54, 89, 0.08), 0 12px 24px rgba(5, 54, 89, 0.14);
}

/* Over the landing's hero photograph: no palette can answer for a picture, so
   the bar takes the light ink pair in either theme — and, once scrolled, a dark
   tint rather than the theme's, which would wash the photo out on a light page. */
.ax-nav.over-photo {
  --ax-ink: #f2f4f6;
  --ax-ink-2: rgba(242, 244, 246, 0.8);
  --ax-line: rgba(242, 244, 246, 0.16);
  --ax-line-strong: rgba(242, 244, 246, 0.32);
  --ax-raised: rgba(255, 255, 255, 0.14);
  --ax-hover: rgba(255, 255, 255, 0.1);
  --ax-hover-strong: rgba(255, 255, 255, 0.16);
  --ax-chrome: rgba(13, 15, 18, 0.55);
}

.ax-nav.over-photo.is-scrolled {
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.22);
}

.ax-nav-in {
  display: flex;
  align-items: center;
  gap: 24px;
  max-width: 1550px;
  height: 64px;
  margin: 0 auto;
  padding: 0 20px;
}

/* ---- brand: the lockup file, in the bar's ink --------------------------------- */

.ax-nav .ax-brand {
  /* Room for the stacked mark, not a line of type: 38px tall inside the 64px
     row, so the lockup reads at a glance without crowding the bar. */
  --brand-logo-h: 38px;

  display: flex;
  align-items: center;
  color: var(--ax-ink);
  text-decoration: none;
  white-space: nowrap;
  flex: none;
}

.ax-nav .ax-brand:hover,
.ax-nav .ax-brand:focus {
  color: var(--ax-ink);
  text-decoration: none;
  opacity: 0.9;
}

/* ---- destinations: the current one is underlined ---------------------------- */

.ax-nav .ax-links {
  display: flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
}

.ax-nav .ax-link {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 10px;
  border-radius: var(--ax-r-inner);
  font-size: 14px;
  font-weight: 500;
  color: var(--ax-ink-2);
  text-decoration: none;
  white-space: nowrap;
  transition: color var(--ax-e-fast) ease, background var(--ax-e-fast) ease;
}

.ax-nav .ax-link:hover {
  color: var(--ax-ink);
  background: var(--ax-hover);
  text-decoration: none;
}

/* The current page is marked the way the rest of the shell marks it: the label
   itself carries the weight, in the bar's own ink, on an underline — no box, no
   ring, no raised surface. A tinted rectangle next to the Upgrade chip read as
   a second button; the rule reads as "you are here". */
.ax-nav .ax-link.is-active {
  color: var(--ax-ink);
  background: transparent;
  box-shadow: none;
  text-decoration: underline;
  text-decoration-thickness: 2px;
  text-underline-offset: 6px;
  text-decoration-color: var(--ax-ink);
}

.ax-nav .ax-link.is-active:hover {
  background: transparent;
  color: var(--ax-ink);
  text-decoration: underline;
  text-decoration-color: var(--ax-ink);
}

/* ---- the free tier's standing offer (UpgradeLink) --------------------------- */

.ax-nav .upgrade-link {
  height: 26px;
  margin-left: 6px;
  padding: 0 10px;
  border-radius: var(--ax-r-pill);
  font-size: 13px;
  font-weight: 600;
  color: var(--ax-accent);
  box-shadow: inset 0 0 0 1px var(--ax-accent-line);
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  white-space: nowrap;
}

.ax-nav .upgrade-link:hover {
  background: var(--ax-accent-tint);
  box-shadow: inset 0 0 0 1px var(--ax-accent);
  text-decoration: none;
}

/* ---- the end of the row: Sign in, or the signed-in identity ----------------- */

.ax-nav .ax-end {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  white-space: nowrap;
}

.ax-nav .ax-signin {
  display: inline-flex;
  align-items: center;
  height: 34px;
  padding: 0 14px;
  border-radius: var(--ax-r-inner);
  font-size: 14px;
  font-weight: 500;
  color: var(--ax-ink);
  text-decoration: none;
  box-shadow: inset 0 0 0 1px var(--ax-line-strong);
  transition: background var(--ax-e-fast) ease;
}

.ax-nav .ax-signin:hover {
  background: var(--ax-hover-strong);
  color: var(--ax-ink);
  text-decoration: none;
}

/* The account menu is its own component; here it only takes the bar's material
   and its 32px round shape. */
.ax-nav .acct-btn {
  width: 32px;
  height: 32px;
  background: var(--ax-raised);
  border: 1px solid var(--ax-line-strong);
  border-radius: var(--ax-r-pill);
}

.ax-nav .acct-btn:hover {
  border-color: var(--ax-ink-2);
}

/* ---- below 1100px a staff list is one control ------------------------------ */

.ax-nav .ax-menu-wrap {
  position: relative;
  flex: none;
}

.ax-nav .ax-menu-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 34px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--ax-r-inner);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--ax-line-strong);
  font: inherit;
  font-size: 14px;
  font-weight: 500;
  color: var(--ax-ink);
  white-space: nowrap;
  cursor: pointer;
}

.ax-nav .ax-menu-btn:hover {
  background: var(--ax-hover-strong);
}

.ax-nav .ax-menu-btn svg {
  flex: none;
  opacity: 0.75;
}

/* A floating layer: it earns the border and the shadow together. */
.ax-nav .ax-menu-panel {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  z-index: 2;
  display: grid;
  gap: 2px;
  min-width: 232px;
  max-height: calc(100svh - 96px);
  overflow-y: auto;
  padding: 6px;
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-element);
  box-shadow: var(--ax-shadow);
}

.ax-nav .ax-menu-item {
  display: block;
  padding: 8px 10px;
  border-radius: var(--ax-r-inner);
  font-size: 14px;
  font-weight: 500;
  color: var(--ax-ink-2);
  text-decoration: none;
  white-space: nowrap;
}

.ax-nav .ax-menu-item:hover {
  background: var(--ax-hover);
  color: var(--ax-ink);
  text-decoration: none;
}

.ax-nav .ax-menu-item.is-active {
  background: var(--ax-raised);
  color: var(--ax-ink);
}

/* ---- focus: a neutral ring, so the accent stays the Upgrade chip's alone ---- */

.ax-nav .ax-brand:focus-visible,
.ax-nav .ax-link:focus-visible,
.ax-nav .ax-signin:focus-visible,
.ax-nav .ax-menu-btn:focus-visible,
.ax-nav .ax-menu-item:focus-visible,
.ax-nav .upgrade-link:focus-visible {
  outline: 2px solid var(--ax-ink-2);
  outline-offset: 1px;
}

/* ---- phone: brand, the links that matter, the avatar ----------------------- */

@media (max-width: 560px) {
  .ax-nav-in {
    gap: 12px;
    padding: 0 12px;
  }

  .ax-nav .ax-brand {
    --brand-logo-h: 30px;
  }

  .ax-nav .ax-link {
    padding: 0 6px;
  }

  /* The offer rides on the pricing page and the account menu at this width. */
  .ax-nav .upgrade-link {
    display: none;
  }
}

import { useEffect, useRef, useState } from 'react';
import type { RefObject } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import AccountMenu from '../AccountMenu/AccountMenu';
import BrandLogo from '../BrandLogo/BrandLogo';
import UpgradeLink from '../UpgradeLink';
import { useAuth } from '../../lib/auth';
// Self-hosted Figtree, as the landing, the pricing mirror and the legal pages
// do — never a CDN link.
import '@fontsource-variable/figtree';
import './AstryxNav.scss';

/**
 * The shell's header in the Astryx register — the same type, surfaces, radii
 * and control shapes the landing, pricing and legal pages already read in.
 *
 * It is a swap, not a second header: Layout.tsx still owns the destination
 * lists (per role, presale-aware), the scroll read and the hero read, and the
 * account menu and the upgrade chip stay their own components. What this file
 * owns is the markup and one rule of its own — below 1100px a staff link list
 * becomes a single Menu control, so ten admin destinations never wrap a 64px
 * row. Flipping `enableAstryxUI` off restores the previous header exactly.
 */

export interface NavItem {
  to: string;
  label: string;
}

interface Props {
  links: NavItem[];
  /** The page has scrolled under the header, so the chrome lifts a step. */
  scrolled: boolean;
  /** The bar is over the landing's hero photograph, so it takes light ink. */
  overPhoto: boolean;
  headerRef: RefObject<HTMLElement>;
}

/** Below this width a long destination list collapses behind one trigger. */
const COMPACT_QUERY = '(max-width: 1100px)';
/** Below this width even a short staff list is wider than the row. */
const NARROW_QUERY = '(max-width: 640px)';

/** More than this many destinations is a staff console's list, not a rider's two. */
const MENU_ABOVE = 4;
/** On a phone, this many destinations is all that fits beside the brand. */
const MENU_ABOVE_NARROW = 2;

function useMedia(query: string) {
  const [hit, setHit] = useState(() => window.matchMedia(query).matches);
  useEffect(() => {
    const mq = window.matchMedia(query);
    const read = () => setHit(mq.matches);
    read();
    mq.addEventListener('change', read);
    return () => mq.removeEventListener('change', read);
  }, [query]);
  return hit;
}

const CHEVRON = (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
    <path d="M6 9l6 6 6-6" />
  </svg>
);

export default function AstryxNav({ links, scrolled, overPhoto, headerRef }: Props) {
  const { user } = useAuth();
  const { pathname } = useLocation();
  const compact = useMedia(COMPACT_QUERY);
  const narrow = useMedia(NARROW_QUERY);
  const [open, setOpen] = useState(false);
  const wrap = useRef<HTMLDivElement>(null);

  /* The compact rule is the nav's, not a role's: a rider's two links keep the
     plain list at every width, a staff console's list becomes one trigger as
     soon as it is wider than the row. */
  const asMenu = (compact && links.length > MENU_ABOVE) || (narrow && links.length > MENU_ABOVE_NARROW);

  /* A destination was taken, or the route changed under the panel. */
  useEffect(() => setOpen(false), [pathname]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    const onDown = (e: MouseEvent) => {
      if (wrap.current && !wrap.current.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener('keydown', onKey);
    document.addEventListener('mousedown', onDown);
    return () => {
      window.removeEventListener('keydown', onKey);
      document.removeEventListener('mousedown', onDown);
    };
  }, [open]);

  const chrome = ['ax-nav', scrolled && 'is-scrolled', overPhoto && 'over-photo'].filter(Boolean).join(' ');

  return (
    <header ref={headerRef} className={chrome}>
      <div className="ax-nav-in">
        {/* The lockup, not a word: `/assets/moto-pass-logo.svg` through
            BrandLogo, masked so it wears the bar's own ink token and follows
            the theme (light ink over the hero photograph, dark ink on a light
            page). The name still reaches assistive tech, from the span's
            label and the link's. */}
        <NavLink to="/" className="ax-brand" aria-label="Moto Pass, home">
          <BrandLogo />
        </NavLink>

        {asMenu ? (
          <div className="ax-menu-wrap" ref={wrap}>
            <button
              type="button"
              className="ax-menu-btn"
              aria-haspopup="menu"
              aria-expanded={open}
              onClick={() => setOpen((o) => !o)}
            >
              Menu
              {CHEVRON}
            </button>
            {open && (
              <div className="ax-menu-panel" role="menu">
                {links.map((l) => (
                  <NavLink
                    key={l.to}
                    to={l.to}
                    end
                    role="menuitem"
                    className={({ isActive }) => (isActive ? 'ax-menu-item is-active' : 'ax-menu-item')}
                  >
                    {l.label}
                  </NavLink>
                ))}
              </div>
            )}
          </div>
        ) : (
          <nav className="ax-links" aria-label="Primary">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end
                className={({ isActive }) => (isActive ? 'ax-link is-active' : 'ax-link')}
              >
                {l.label}
              </NavLink>
            ))}
            {/* The free tier's standing offer — the accent's one home here. */}
            <UpgradeLink />
          </nav>
        )}

        <div className="ax-end">
          {user ? (
            <AccountMenu />
          ) : (
            <NavLink to="/login" className="ax-signin">
              Sign in
            </NavLink>
          )}
        </div>
      </div>
    </header>
  );
}

/* Layout — styles owned by Layout.tsx.
   Split out of styles/global.scss; imported once from Layout.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The shell's own dropdown (.acct-pop) has to clear the map's tiles, so the
   header carries a z-index above Leaflet's. */
/* The header's own ink, and its one exception: over the landing's hero
   photograph the palette cannot answer for what is behind the type, so the
   header takes the light pair there (Layout reads the hero's foot to decide;
   `--scrim-photo` gives it a dark chrome to sit on). */
.app-header.over-photo {
  --header-ink: #f2f4f6;
  --header-ink-muted: rgba(242, 244, 246, 0.8);
  --header-line: rgba(242, 244, 246, 0.32);
}

/* Sign in is the shell's one quiet action, not a filled CTA: it answers the
   header's own ink and carries no fill until you point at it, so it holds over
   the landing hero photograph and the scrolled chrome alike. */
.app-header .header-signin {
  background: transparent;
  color: var(--header-ink);
  border: 1px solid var(--header-line);
  font-weight: 500;
}

.app-header .header-signin:hover:not(:disabled) {
  opacity: 1;
  border-color: var(--header-ink-muted);
  background: var(--tint-strong);
}

.app-header .header-signin:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }

/* The free tier's standing offer (UpgradeLink): a quiet chip beside the nav
   links, in the accent so it reads as the one thing to do rather than another
   destination. Same hairline register as Sign in, so the shell keeps one
   control shape — no fill until you point at it, which also holds it over the
   landing hero's photograph. Only a rider on the free tier renders it. */
.app-header .upgrade-link {
  color: var(--accent);
  border: 1px solid rgba(var(--accent-rgb), 0.45);
  border-radius: var(--radius);
  padding: 2px 10px;
  font-weight: 500;
  text-decoration: none;
  white-space: nowrap;
}

.app-header .upgrade-link:hover {
  background: rgba(var(--accent-rgb), 0.12);
  border-color: var(--accent);
  text-decoration: none;
}

.app-header .upgrade-link:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }

import { useEffect, useRef, useState } from 'react';
import { NavLink, Outlet, useLocation } from 'react-router-dom';
import { useAuth } from '../../lib/auth';
import { enableAstryxUI, enableCommunity } from '../../lib/featureFlags';
import { usePresale } from '../../lib/launch';
import AccountMenu from '../AccountMenu/AccountMenu';
import AccentSwitcher from '../AccentSwitcher/AccentSwitcher';
import BrandLogo from '../BrandLogo/BrandLogo';
import PresaleSwitcher, { PreviewGateNotice } from '../PresaleSwitcher/PresaleSwitcher';
import Footer from '../Footer/Footer';
import UpgradeLink from '../UpgradeLink';
import AstryxNav from './AstryxNav';
import './Layout.scss';

export default function Layout() {
  const { user } = useAuth();
  const { pathname } = useLocation();
  /* While the presale runs, the network and the calendar are closed to this
     caller, so the header must not offer them as links: an entry that bounces
     straight back to `/` reads as a broken page, not as a gate. Staff and pass
     holders have `presaleMode === false` and their full nav. */
  const { presaleMode } = usePresale();

  /* The header rides over the page at rest and only takes on chrome once the
     page has moved under it — a bare scroll offset, so the read is the same on
     every route (ScrollToTop resets the offset on navigation, so each page
     opens transparent again). rAF-coalesced: scroll fires far more often than
     the browser paints. */
  const [scrolled, setScrolled] = useState(false);
  /* ...and while it is over the landing's hero it is over a *photograph*, which
     no palette can answer for: that one state takes light ink on a dark chrome
     in either theme (`--scrim-photo` / `.over-photo` in Layout.scss). */
  const [overHero, setOverHero] = useState(false);
  const headerRef = useRef<HTMLElement>(null);

  useEffect(() => {
    let frame = 0;
    const read = () => {
      frame = 0;
      setScrolled(window.scrollY > 8);
      /* The hero runs the whole first screen, so the header is over it until the
         page has scrolled clean past its foot. Two registers, two readings: the
         previous home page's band scrolls away, so its own foot decides; the
         Astryx one is pinned and covered by the sheet after it (`.ax-flow`), so
         the bar is over the photograph until that sheet reaches the header. */
      const hero =
        pathname === '/' ? document.querySelector('.landing-hero, .ax-hero') : null;
      const sheet = pathname === '/' ? document.querySelector('.ax-flow') : null;
      const head = headerRef.current?.offsetHeight ?? 57;
      setOverHero(
        sheet
          ? sheet.getBoundingClientRect().top > head
          : !!hero && hero.getBoundingClientRect().bottom >= head
      );
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(read);
    };
    read();
    /* A route opens at scroll 0, so nothing fires after the outgoing page's hero
       leaves and React mounts the next one — read again on a short ladder so the
       new page's own hero is seen. The band's height is a viewport unit, not a
       function of its data or its photograph, so a few beats is all it takes. */
    const ladder = [0, 150, 600, 1500].map((t) => setTimeout(read, t));
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => {
      ladder.forEach(clearTimeout);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [pathname]);

  const links =
    user?.role === 'ADMIN'
      ? [
          { to: '/admin', label: 'Overview' },
          { to: '/admin/tracks', label: 'Tracks' },
          { to: '/admin/users', label: 'Users' },
          { to: '/admin/tiers', label: 'Tiers' },
          { to: '/admin/reports', label: 'Reports' },
          { to: '/admin/quickbooks', label: 'QuickBooks' },
          { to: '/operator/profile', label: 'Track profile' },
          { to: '/operator/calendar', label: 'Calendar' },
          ...(enableCommunity ? [{ to: '/operator/community', label: 'Community' }] : []),
          { to: '/operator/dashboard', label: 'Dashboard' },
          { to: '/operator/reports', label: 'Reports' },
        ]
      : user?.role === 'OPERATOR'
        ? [
            { to: '/operator/dashboard', label: 'Dashboard' },
            { to: '/operator/reports', label: 'Reports' },
            { to: '/tracks', label: 'Tracks' },
            { to: '/operator/calendar', label: 'Calendar' },
            ...(enableCommunity ? [{ to: '/operator/community', label: 'Community' }] : []),
          ]
        : user
          ? presaleMode
            ? // The presale closes the network to a rider without a pass; the
              // offer is the only surface they have.
              [{ to: '/pricing', label: 'Pricing' }]
            : [
                { to: '/tracks', label: 'Tracks' },
                { to: '/tracks/calendar', label: 'Calendar' },
              ]
          : presaleMode
            ? [{ to: '/pricing', label: 'Pricing' }]
            : [
                { to: '/tracks', label: 'Tracks' },
                { to: '/pricing', label: 'Pricing' },
              ];

  return (
    <>
      <div style={{ minHeight: '100%', display: 'flex', flexDirection: 'column' }}>
        {enableAstryxUI ? (
          /* The Astryx register's header (AstryxNav.tsx). It is handed the same
             link lists and the same scroll read this component has always
             computed; the markup below is untouched and comes back with the
             flag off. */
          <AstryxNav links={links} scrolled={scrolled} overPhoto={overHero} headerRef={headerRef} />
        ) : (
        <header
          ref={headerRef}
          className={overHero ? 'app-header over-photo' : 'app-header'}
          style={{
            borderBottom: `1px solid ${
              scrolled ? (overHero ? 'var(--scrim-photo-line)' : 'var(--line)') : 'transparent'
            }`,
            position: 'sticky',
            top: 0,
            /* Transparent at rest; half-opacity surface + blur once the page
               has scrolled under it. Over the landing's photograph the chrome
               goes dark in either theme so the light ink keeps its contrast. */
            background: scrolled ? (overHero ? 'var(--scrim-photo)' : 'var(--scrim-half)') : 'transparent',
            backdropFilter: scrolled ? 'blur(12px)' : 'none',
            WebkitBackdropFilter: scrolled ? 'blur(12px)' : 'none',
            transition: 'background 200ms ease, border-color 200ms ease, backdrop-filter 200ms ease',
            /* Above the network map: Leaflet's panes (400) and controls (1000)
               are positioned with a z-index while the map pane is no stacking
               context, so they compete here at the root — the header's own
               dropdown (the account menu) has to clear them. Under the sheet (1200) and the toasts (1100). */
            zIndex: 1050,
          }}
        >
          <div
            className="row wrap"
            style={{ maxWidth: 1550, margin: '0 auto', padding: '10px 20px', gap: 16 }}
          >
            <div className="row" style={{ gap: 18, minWidth: 0 }}>
              <NavLink
                to="/"
                aria-label="Moto Pass, home"
                style={{
                  /* The lockup file, in the header's ink; 30px keeps the row at
                     the height the previous wordmark set. */
                  ['--brand-logo-h' as string]: '30px',
                  display: 'flex',
                  alignItems: 'center',
                  whiteSpace: 'nowrap',
                  color: 'var(--header-ink)',
                }}
              >
                <BrandLogo />
              </NavLink>
              <nav className="row wrap" style={{ gap: 14 }}>
                {links.map((l) => (
                  <NavLink
                    key={l.to}
                    to={l.to}
                    end
                    className="small"
                    style={({ isActive }) => ({
                      color: isActive ? 'var(--header-ink)' : 'var(--header-ink-muted)',
                      textDecoration: isActive ? 'underline' : 'none',
                      textUnderlineOffset: 4,
                    })}
                  >
                    {l.label}
                  </NavLink>
                ))}
                {/* The free tier's standing offer, on every route. */}
                <UpgradeLink />
              </nav>
            </div>

            <div className="row" style={{ gap: 10, whiteSpace: 'nowrap', marginLeft: 'auto' }}>
              {user ? (
                <AccountMenu />
              ) : (
                <NavLink to="/login">
                  <button className="small header-signin">Sign in</button>
                </NavLink>
              )}
            </div>
          </div>
        </header>
        )}

        {/* The page area always runs at least one screen past the header, so the
            footer starts exactly at the fold — out of sight until the reader
            scrolls for it. Short pages (the gate dashboard, a report with no
            rows) used to park the footer inside the first screen. */}
        <main
          style={{
            maxWidth: 1550,
            margin: '0 auto',
            padding: '22px 20px 60px',
            width: '100%',
            flex: 1,
            minHeight: 'calc(100svh - var(--header-h, 57px))',
          }}
        >
          {/* TEMPORARY: the live preview's footnote — see PresaleSwitcher.tsx. */}
          <PreviewGateNotice />
          <Outlet />
        </main>

        <footer>
          {/* .site-footer carries the rule and the tint; the shell just ends here. */}
          <Footer />
        </footer>

        {/* TEMPORARY: floating presale / live view switch — remove with the component. */}
        <PresaleSwitcher />

        {/* TEMPORARY: floating accent picker — remove with the component. */}
        <AccentSwitcher />
      </div>
    </>
  );
}

/* MonthGrid — styles owned by MonthGrid.tsx.
   Split out of styles/global.scss; imported once from MonthGrid.tsx and
   still plain global class names (this app uses no CSS modules). */

.cal-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }

.cal-month { font-size: 13px; font-weight: 600; }

.cal-grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 2px; }

.cal-dow span {
  padding-bottom: 4px;
  font-size: 10px;
  letter-spacing: 0.06em;
  text-align: center;
  color: var(--muted);
}

.cal-day {
  display: flex;
  align-items: center;
  justify-content: center;
  /* Taller than a numeral needs: the cell is the thing you aim at on a date,
     so it keeps a comfortable target rather than hugging the type. */
  height: 44px;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  background: none;
  border: 1px solid transparent;
  border-radius: var(--radius);
  cursor: default;
}

.cal-day.is-out { opacity: 0.35; }

/* A booked day is a control: fill it, and let hover sit on the border. */
.cal-day.has-event {
  color: var(--text);
  font-weight: 600;
  background: var(--bg-3);
  border-color: var(--line);
  cursor: pointer;
}

.cal-day.has-event:hover { border-color: var(--muted); }

/* One signal per state: today is an outline, the picked day is a fill. */
.cal-day.is-today { border-color: rgba(var(--accent-rgb), 0.5); }

.cal-day.is-picked { background: var(--accent); border-color: transparent; color: #10130a; }

/* A posted gate read tints its date: caution amber, closed dimmed. A date
   with its own event keeps the event fill — the gate rides in the title. */
.cal-day.has-gate { font-weight: 600; color: var(--text); border-color: var(--line); }

.cal-day.gate-weather_hold { border-color: rgba(251, 191, 36, 0.55); }

.cal-day.gate-closed { opacity: 0.6; text-decoration: line-through; text-decoration-thickness: 1px; }

.cal-day.gate-open.has-gate { border-color: rgba(var(--ice-rgb), 0.4); }

import { firstOfMonth } from '../../lib/events';
import './MonthGrid.scss';

/**
 * The month at the head of a schedule: six rows of days with a chevron either
 * side of the month's name.
 *
 * It keeps no state of its own — whoever draws it owns the month it is showing
 * — so the venue profile's read-only calendar and the owner's calendar page step
 * the same grid the same way. A day with dates on it fills and answers a pick;
 * every other day stays a quiet numeral.
 */
export interface CalDay {
  d: Date;
  key: string;
  inMonth: boolean;
}

interface Props {
  view: { year: number; month: number };
  days: CalDay[];
  /** Today, as `YYYY-MM-DD`, so a day can mark itself without a second clock. */
  today: string;
  /** How many dates fall on a day — `0` reads as a plain numeral. */
  countFor: (key: string) => number;
  /** The gate read posted for a day, when the operator set one. */
  statusFor?: (key: string) => string | null;
  /** The day the reader picked, or `null`. */
  picked?: string | null;
  onStep: (delta: number) => void;
  onPickDay: (key: string) => void;
}

const DOW = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const MONTH_FMT: Intl.DateTimeFormatOptions = { month: 'long', year: 'numeric', timeZone: 'UTC' };

export default function MonthGrid({ view, days, today, countFor, statusFor, picked, onStep, onPickDay }: Props) {
  return (
    <div className="cal">
      <div className="cal-head">
        <button className="cal-nav" onClick={() => onStep(-1)} aria-label="Previous month">
          ‹
        </button>
        <b className="cal-month">{firstOfMonth(view.year, view.month).toLocaleDateString(undefined, MONTH_FMT)}</b>
        <button className="cal-nav" onClick={() => onStep(1)} aria-label="Next month">
          ›
        </button>
      </div>

      <div className="cal-grid cal-dow" aria-hidden="true">
        {DOW.map((d, i) => (
          <span key={`${d}${i}`}>{d}</span>
        ))}
      </div>

      <div className="cal-grid cal-days">
        {days.map(({ d, key, inMonth }) => {
          const count = countFor(key);
          // The gate the operator posted for the day, when they posted one —
          // a scheduled Caution or Closed reads on the date itself.
          const gate = statusFor?.(key) ?? null;
          const label = d.toLocaleDateString(undefined, {
            weekday: 'long',
            month: 'long',
            day: 'numeric',
            timeZone: 'UTC',
          });
          const cls = [
            'cal-day',
            inMonth ? '' : 'is-out',
            key === today ? 'is-today' : '',
            key === picked ? 'is-picked' : '',
            gate ? `gate-${gate.toLowerCase()}` : '',
          ]
            .filter(Boolean)
            .join(' ');
          const gateWord = gate === 'OPEN' ? 'Open' : gate === 'CLOSED' ? 'Closed' : gate ? 'Caution' : '';
          return count > 0 ? (
            <button
              key={key}
              type="button"
              className={`${cls} has-event`}
              title={`${label}: ${count} ${count === 1 ? 'date' : 'dates'}${gateWord ? ` · ${gateWord}` : ''}`}
              aria-label={`${label}, ${count} ${count === 1 ? 'date' : 'dates'}${gateWord ? `, ${gateWord}` : ''}`}
              aria-pressed={key === picked}
              onClick={() => onPickDay(key)}
            >
              {d.getUTCDate()}
            </button>
          ) : gate ? (
            <span key={key} className={`${cls} has-gate`} title={`${label}: ${gateWord}`} aria-label={`${label}, ${gateWord}`}>
              {d.getUTCDate()}
            </span>
          ) : (
            <span key={key} className={cls}>
              {d.getUTCDate()}
            </span>
          );
        })}
      </div>
    </div>
  );
}

/* NetworkSkeleton — styles owned by NetworkSkeleton.tsx.
   The network page's loading frame: the page's own geometry (reused from
   RiderHome.scss and DaysByTrack.scss) with placeholder bars in the boxes the
   venues will fill. Plain global class names, as the app keeps them; every
   rule here is scoped to `.net-skel` so no other page's shape moves. */

.net-skel .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* One placeholder bar. The pulse is the whole motion: a slow breath between the
   card's own surface and the lifted one, calm enough to read as waiting rather
   than as work — the same register the calendar's frame keeps. */
.net-skel .sk {
  display: block;
  border-radius: 5px;
  background: var(--bg-3);
  animation: net-skel-pulse 1.8s ease-in-out infinite;
}

@keyframes net-skel-pulse {
  0%,
  100% { opacity: 0.55; }
  50% { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .net-skel .sk { animation: none; opacity: 0.75; }
}

/* ---- The canvas --------------------------------------------------------- */
/* The tiles' own frame, held by the surface they land on: a faint grid at the
   map's scale, with the network's dots at rest. Nothing moves — a map that
   animates under a loading read draws the eye away from the rail beside it. */
.net-skel-map {
  background-color: var(--bg-2);
  background-image:
    linear-gradient(color-mix(in srgb, var(--line) 65%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--line) 65%, transparent) 1px, transparent 1px);
  background-size: 72px 72px;
  background-position: -1px -1px;
}

.net-skel-pin {
  position: absolute;
  width: 10px;
  height: 10px;
  border: 1px solid color-mix(in srgb, var(--pin-edge) 45%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 32%, transparent);
  transform: translate(-50%, -50%);
}

/* The seam row's button, at the size the real one holds. It sits inside the
   page's own row, so the phone breakpoint hides it on the canvas for free. */
.net-skel .sk-handle {
  width: 56px;
  height: 20px;
  border-radius: 999px;
}

/* ---- The rail's head ---------------------------------------------------- */
.net-skel .sk-id { width: 118px; height: 12px; }

/* The rail's head filter is a checkbox with its label, so the placeholder is a
   short band at the control's own height. */
.net-skel .sk-filter { width: 74px; height: 26px; border-radius: var(--radius); }

.net-skel .sk-sort { width: 78px; height: 22px; border-radius: var(--radius); }

/* ---- One venue line ----------------------------------------------------- */
/* The line is the real one's board: the gate light, the venue's two lines
   beside it, and the pass's read at the outer end. Same padding, same two text
   rows and the same hairline, so a line stands as tall as the venue that will
   replace it (55px) and the list never re-flows when the network lands. */
.net-skel-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  grid-template-rows: 17px 17px;
  gap: 2px 9px;
  align-content: start;
  padding: 9px 12px;
  border-bottom: 1px solid var(--line);
}

.net-skel-row:last-child { border-bottom: 0; }

/* The gate light is one dot in the row's first column, centred where the real
   light sits — it is a status, not the pass's read, so every reader gets it. */
.net-skel .sk-dot {
  grid-column: 1;
  grid-row: 1 / span 2;
  align-self: start;
  width: 8px;
  height: 8px;
  margin: 4px 2px 0;
  border-radius: 50%;
}

.net-skel .sk-name {
  grid-column: 2;
  grid-row: 1;
  align-self: center;
  height: 12px;
}

.net-skel .sk-sub {
  grid-column: 2;
  grid-row: 2;
  align-self: center;
  height: 9px;
}

/* The pass's read: only where terms exist. A gated rail draws no bar here at
   all, exactly as its rows end at the venue's name and location. */
.net-skel .sk-meter {
  grid-column: 3;
  grid-row: 1 / span 2;
  align-self: center;
  width: 54px;
  height: 12px;
}

import type { CSSProperties } from 'react';
import './NetworkSkeleton.scss';

/** How many venue lines the rail draws while the network is on its way. */
const ROWS = 14;

/**
 * The rail's line widths, so the frame reads as a list of venues rather than
 * as a comb of identical bars. Cycled, so fourteen lines never repeat a bar.
 */
const NAME_W = [86, 68, 92, 74, 81, 63, 88, 71, 95, 66, 78, 84, 61, 90];
const SUB_W = [52, 40, 46, 57, 38, 50, 44, 55, 41, 48, 53, 39, 56, 43];

/** A few venues' dots on the map's surface — the network it will draw, at rest. */
const PINS: [number, number][] = [
  [22, 34],
  [35, 26],
  [46, 41],
  [58, 30],
  [64, 52],
  [40, 58],
  [27, 62],
  [52, 68],
  [70, 22],
  [18, 47],
];

/** How tall the stacked layout's seam row is, in px — the page's own constant. */
const STACK_HANDLE_H = 26;

/**
 * The network page's loading frame.
 *
 * It is the page, not a line of text in its place: the same canvas band, the
 * same rail floating over its left edge, the same head and the same venue
 * lines, so the network lands where the reader is already looking instead of
 * pushing a blank page down. The frame reuses the page's own geometry classes
 * (`.pass-page`, `.pass-map`, `.pass-aux`, `.day-grid`), so it carries the
 * canvas heights, the phone split and the rail's scroller for free.
 *
 * Only what this reader will actually get is drawn, the way `CalendarSkeleton`
 * leaves out the owner's bar for a rider:
 * - `filter` is the rail's slice control, which only a rider's own list offers
 *   (the Following slice); a visitor and an operator get a head with no control
 *   there, so the frame has none either.
 * - `terms` is the pass's own read at the end of a line — days left and their
 *   meter. A visitor, the free tier and a lapsed pass read the same rail with
 *   no terms, so their frame keeps that column empty.
 *
 * Both default to false: before the session and the pass are known, the frame
 * draws only what every reader gets, then refines as those answers land.
 */
export default function NetworkSkeleton({
  filter = false,
  terms = false,
}: {
  /** The rider-only slice control in the rail's head. */
  filter?: boolean;
  /** The pass's day read at the foot of each venue line. */
  terms?: boolean;
}) {
  return (
    <div
      className="stack pass-page net-skel"
      role="status"
      aria-live="polite"
      aria-busy="true"
    >
      <section className="pass-layout with-map">
        {/* Inside the frame, not beside it: `.pass-page.stack` spaces its own
            children apart, and a screen-reader line as a sibling would push the
            canvas down by that gap. */}
        <span className="sr-only">Loading the network…</span>

        {/* The two seats the stacked layout splits the screen into, written the
            same way the page writes its own opening state: the list unfurled at
            85svh and the map taking whatever the seam row leaves. Copied rather
            than guessed, so the phone lands on the same split. */}
        <div
          className="pass-map"
          style={
            {
              '--stack-rail-h': '85svh',
              '--stack-map-h': `calc(var(--page-h) - 85svh - ${STACK_HANDLE_H}px)`,
            } as CSSProperties
          }
        >
          {/* The canvas, at the surface it will be: the tiles' frame without
              the tiles, and the venues dotted on it at rest. */}
          <div className="map-pane net-skel-map" aria-hidden="true">
            {PINS.map(([left, top], i) => (
              <span
                key={i}
                className="net-skel-pin"
                style={{ left: `${left}%`, top: `${top}%` } as CSSProperties}
              />
            ))}
          </div>

          {/* The stacked column's seam button. It is the page's own row, so the
              phone breakpoint hides it on the canvas and shows it where the
              list and map stack — exactly as the loaded page does. */}
          <div className="rail-toggle-row">
            <span className="sk sk-handle" aria-hidden="true" />
          </div>

          <aside className="pass-aux" id="pass-rail" aria-hidden="true">
            <section className="day-rail">
              <div className="rail-pass">
                <div className="rail-pass-id">
                  <span className="sk sk-id" />
                </div>

                <div className="rail-tools">
                  {filter && <span className="sk sk-filter" />}
                  <span className="sk sk-sort" />
                </div>
              </div>

              <div className="day-grid">
                {Array.from({ length: ROWS }, (_, i) => (
                  <div
                    className={`net-skel-row${terms ? ' with-terms' : ''}`}
                    key={i}
                  >
                    <span className="sk sk-dot" />
                    <span
                      className="sk sk-name"
                      style={{ width: `${NAME_W[i % NAME_W.length]}%` }}
                    />
                    <span
                      className="sk sk-sub"
                      style={{ width: `${SUB_W[i % SUB_W.length]}%` }}
                    />
                    {terms && <span className="sk sk-meter" />}
                  </div>
                ))}
              </div>
            </section>
          </aside>
        </div>
      </section>
    </div>
  );
}

/* OperatorStats — styles owned by OperatorStats.tsx.
   Split out of styles/global.scss; imported once from OperatorStats.tsx and
   still plain global class names (this app uses no CSS modules). */

/* ---- Operator dashboard stats --------------------------------------------
   The venue's operating read (components/OperatorStats.tsx), one view per tab.
   The numbers themselves are labelled fact rows, not KPI tiles — the cards
   carry shapes: a 30-day column run and labelled bar rows. Every colour is a
   token, so the section follows the theme and the accent swatch. */
.stats-section { display: flex; flex-direction: column; gap: 18px; }

.stats-section h2 { margin: 0; }

.stats-head { display: flex; align-items: center; justify-content: space-between; gap: 16px 24px; flex-wrap: wrap; }

/* Two pills, not one: the timeframe (Today / Season / Last 30 days) and the
   view read inside it. They wrap together as a cluster, so the timeframe never
   drifts away from the options it governs. */
.stats-pills { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-width: 0; }

/* Two pills are more than a phone row can hold, so each one scrolls sideways
   inside itself instead of pushing the page wide. Labels never wrap — a
   two-line pill is unreadable. */
.stats-head .pill-toggle { margin-top: 0; max-width: 100%; overflow-x: auto; scrollbar-width: none; }

.stats-head .pill-toggle::-webkit-scrollbar { display: none; }

.stats-head .pill-toggle button { flex: 0 0 auto; white-space: nowrap; }

.stat-card {
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 14px 16px;
}

.stat-card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 12px; }

.stat-card-head h3 { margin: 0; }

/* Labelled column runs — the venue's weekday and hourly shape. One column a
   bucket, its count over it and its name under it, all sitting on the
   hairline baseline. A bucket with nothing at the gate keeps a stub so the
   gaps stay legible. */
.stat-vbars { display: flex; align-items: flex-end; gap: 6px; }

.stat-vbar { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 6px; }

.stat-vbar-count { font-size: 11px; line-height: 1; color: var(--muted); font-variant-numeric: tabular-nums; }

.stat-vbar-track {
  width: 100%; height: 104px; display: flex; align-items: flex-end; justify-content: center;
  border-bottom: 1px solid var(--line);
}

.stat-vbar-track > i {
  display: block; width: 72%; max-width: 34px; background: var(--accent);
  border-radius: 1px 1px 0 0;
}

.stat-vbar.is-empty .stat-vbar-track > i { background: var(--dim); }

.stat-vbar.is-empty .stat-vbar-count { color: var(--dim); }

.stat-vbar-label { font-size: 11px; color: var(--muted); white-space: nowrap; }

.stat-bar-count { font-size: 12px; text-align: right; font-variant-numeric: tabular-nums; flex: 0 0 auto; min-width: 30px; }

/* The day run folded into the overview: one column a day, sitting on the
   hairline baseline. A day with nothing at the gate keeps a stub so the gaps
   stay legible. */
.stat-day-run-head { margin: 14px 0 8px; border-top: 1px solid var(--line); padding-top: 10px; }

.stat-cols { display: flex; align-items: flex-end; gap: 3px; height: 64px; border-bottom: 1px solid var(--line); }

.stat-col { flex: 1 1 0; height: 100%; display: flex; align-items: flex-end; justify-content: center; }

.stat-col > i { display: block; width: 62%; max-width: 20px; background: var(--accent); border-radius: 1px 1px 0 0; }

.stat-col.is-empty > i { background: var(--dim); }

.stat-cols-axis { display: flex; justify-content: space-between; margin-top: 6px; }

/* Hairline rows — top riders and the denial reasons. */
.stat-rows { display: flex; flex-direction: column; }

.stat-row { display: flex; align-items: baseline; gap: 10px; padding: 7px 0; }

.stat-row + .stat-row { border-top: 1px solid var(--line); }

.stat-row-name { flex: 1 1 auto; min-width: 0; font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* The ride-kind mix closes the season card as one more hairline row. */
.stat-mix { border-top: 1px solid var(--line); padding-top: 8px; line-height: 1.5; }

import { useEffect, useState } from 'react';
import { api, money } from '../../lib/api';
import './OperatorStats.scss';

interface RangeSummary {
  checkins: number;
  riders: number;
  collectedCents: number;
  rideDays: number;
  perRideDay: number;
  repeatRiders: number;
  repeatRate: number;
  newRiders: number;
  avgVisits: number;
  scans: number;
  approved: number;
  denied: number;
  approvalRate: number | null;
}

interface TrackStats {
  trackName: string;
  trackSlug: string;
  seasonYear: number;
  asOf: string;
  range: { key: RangeKey; label: string; from: string; to: string };
  summary: RangeSummary;
  kinds: Record<string, number>;
  days: { day: string; checkins: number }[];
  weekday: { label: string; checkins: number }[];
  hours: { hour: number; checkins: number }[];
  topRiders: { name: string; visits: number; paidCents: number }[];
  denials: { code: string | null; reason: string | null; count: number }[];
  audience: {
    followers: number;
    upcoming: number;
    nextEvent: {
      title: string;
      kind: string;
      day: string;
      startMinutes: number | null;
      endMinutes: number | null;
    } | null;
  };
}

const KIND_LABEL: Record<string, string> = {
  FREE: 'included',
  DISCOUNT: 'discounted',
};

/** The timeframe pill: it owns the range every other option is read in. */
const RANGES = [
  { key: 'today', label: 'Today' },
  { key: 'season', label: 'Season' },
  { key: 'window', label: 'Last 30 days' },
] as const;
type RangeKey = (typeof RANGES)[number]['key'];

/** The view pill: the shape the selected range is read as. */
const VIEWS = [
  { key: 'summary', label: 'Overview' },
  { key: 'days', label: 'Busiest days' },
  { key: 'hours', label: 'Peak hours' },
  { key: 'riders', label: 'Riders' },
] as const;
type ViewKey = (typeof VIEWS)[number]['key'];

/** Gates open early: the fallback window the hourly read covers when a season
    has no check-ins yet, 6am through 6pm. */
const HOUR_FROM = 6;
const HOUR_TO = 18;

/** Hours of quiet kept around the venue's active window, at each end, so the
    gate's shape is read against the hours either side of it. */
const HOUR_PAD = 2;
/** The narrowest run worth drawing — a short working day of columns. */
const HOUR_MIN_SPAN = 8;

/**
 * The hours worth drawing: the venue's own active window, opened out by
 * HOUR_PAD hours at each end and never narrower than HOUR_MIN_SPAN columns. A
 * range with nothing at the gate falls back to the widened default.
 */
function hourWindow(hours: { hour: number; checkins: number }[]): { hour: number; checkins: number }[] {
  const active = hours.filter((h) => h.checkins > 0);
  if (!active.length) return hours.filter((h) => h.hour >= HOUR_FROM && h.hour <= HOUR_TO);
  let from = Math.max(0, active[0].hour - HOUR_PAD);
  let to = Math.min(23, active[active.length - 1].hour + HOUR_PAD);
  while (to - from + 1 < HOUR_MIN_SPAN) {
    if (to < 23) to += 1;
    else if (from > 0) from -= 1;
    else break;
  }
  return hours.filter((h) => h.hour >= from && h.hour <= to);
}

function hourLabel(h: number): string {
  if (h === 0) return '12a';
  if (h < 12) return `${h}a`;
  if (h === 12) return '12p';
  return `${h - 12}p`;
}

function shortDay(day: string): string {
  return new Date(`${day}T00:00:00Z`).toLocaleDateString(undefined, {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  });
}

/** How a range names itself under a card's heading. */
function rangeNote(range: { key: RangeKey; from: string; to: string }): string {
  if (range.key === 'today') return shortDay(range.to);
  if (range.key === 'season') return 'to date';
  return `${shortDay(range.from)} – ${shortDay(range.to)}`;
}

/** The range's own short name, for a card heading. */
function rangeHeading(key: RangeKey): string {
  return key === 'window' ? 'Last 30 days' : key === 'season' ? 'Season' : 'Today';
}

/** The range in the middle of a sentence. */
function rangeWords(key: RangeKey): string {
  return key === 'window' ? 'in the last 30 days' : key === 'season' ? 'this season' : 'today';
}

/** One labelled fact — the label left, the figure it names on the same line. */
function Fact({ label, value }: { label: string; value: string | number }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

/** A labelled column run: one column per bucket, the count over it and the
    bucket's name under it. A bucket with nothing keeps a stub so the gaps
    between the gate's busy hours stay legible. */
function ColumnRun({
  rows,
  max,
}: {
  rows: { key: string; label: string; count: number; title?: string }[];
  max: number;
}) {
  return (
    <div className="stat-vbars">
      {rows.map((r) => (
        <div
          key={r.key}
          className={`stat-vbar${r.count ? '' : ' is-empty'}`}
          title={r.title ?? `${r.label} · ${r.count}`}
        >
          <span className="stat-vbar-count">{r.count}</span>
          <span className="stat-vbar-track">
            <i style={{ height: r.count ? `${Math.max(4, (r.count / max) * 100)}%` : '3px' }} />
          </span>
          <span className="stat-vbar-label">{r.label}</span>
        </div>
      ))}
    </div>
  );
}

/**
 * The venue's operating read, on the operator's dashboard. Two pills: the
 * timeframe (today, the season, the trailing month) owns the range, and the
 * view beside it is read inside that range — so no figure on the right can
 * quote a season while the pill says a month. Every number is counted
 * server-side off the redemption + scan ledgers.
 */
export default function OperatorStats({
  trackId,
  reloadKey = 0,
}: {
  trackId?: string | null;
  reloadKey?: number;
}) {
  const [stats, setStats] = useState<TrackStats | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [range, setRange] = useState<RangeKey>('today');
  const [view, setView] = useState<ViewKey>('summary');

  useEffect(() => {
    let live = true;
    setLoadError(null);
    const q = new URLSearchParams({ range });
    if (trackId) q.set('trackId', trackId);
    api
      .get<TrackStats>(`/operator/stats?${q.toString()}`)
      .then((r) => {
        if (live && r.data) setStats(r.data);
      })
      .catch(() => {
        if (live) setLoadError('Could not load stats.');
      });
    return () => {
      live = false;
    };
  }, [trackId, reloadKey, range]);

  // A section that vanishes reads as a broken page; a quiet line keeps the
  // operator oriented while the read loads, or names the failure.
  if (!stats) {
    return (
      <section className="stats-section">
        <div className="stat-card small muted">{loadError ?? 'Loading track stats…'}</div>
      </section>
    );
  }

  const { summary } = stats;
  const maxWeekday = Math.max(1, ...stats.weekday.map((d) => d.checkins));
  const hourRows = hourWindow(stats.hours);
  const maxHour = Math.max(1, ...hourRows.map((h) => h.checkins));
  const maxDay = Math.max(1, ...stats.days.map((d) => d.checkins));
  const busiest = stats.days.length
    ? stats.days.reduce((a, b) => (b.checkins > a.checkins ? b : a), stats.days[0])
    : null;
  const kinds = Object.entries(stats.kinds).filter(([, n]) => n > 0);
  const note = rangeNote(stats.range);

  return (
    <section className="stats-section">
      <div className="stats-head">
        <div className="row wrap">
          <h2>Track stats</h2>
        </div>
        <div className="stats-pills">
          <div className="pill-toggle" role="group" aria-label="Timeframe">
            {RANGES.map((r) => (
              <button key={r.key} aria-pressed={range === r.key} onClick={() => setRange(r.key)}>
                {r.label}
              </button>
            ))}
          </div>
          <div className="pill-toggle" role="group" aria-label="View">
            {VIEWS.map((v) => (
              <button key={v.key} aria-pressed={view === v.key} onClick={() => setView(v.key)}>
                {v.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {view === 'summary' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>{rangeHeading(range)}</h3>
            <span className="tiny muted">{note}</span>
          </div>
          <dl className="fact-list">
            {range === 'today' ? (
              <>
                <Fact label="Riders in" value={summary.riders} />
                <Fact label="Check-ins" value={summary.checkins} />
                <Fact label="Collected at the window" value={money(summary.collectedCents)} />
                <Fact
                  label="Scans approved"
                  value={
                    summary.approvalRate == null
                      ? 'None yet'
                      : `${summary.approved} of ${summary.scans} · ${summary.approvalRate}%`
                  }
                />
                <Fact label="Turned away" value={summary.denied} />
              </>
            ) : (
              <>
                <Fact label="Check-ins" value={summary.checkins} />
                <Fact label="Riders" value={summary.riders} />
                <Fact
                  label="Came back"
                  value={`${summary.repeatRiders} of ${summary.riders} · ${summary.repeatRate}%`}
                />
                <Fact label="Riders a ride day" value={summary.perRideDay} />
                <Fact label="Collected at the window" value={money(summary.collectedCents)} />
                <Fact
                  label="First time here"
                  value={`${summary.newRiders} ${rangeWords(range)}`}
                />
              </>
            )}
          </dl>
          {range !== 'today' && !!kinds.length && (
            <div className="stat-mix tiny muted">
              {kinds.map(([k, n], i) => (
                <span key={k}>
                  {i > 0 && ' · '}
                  {n} {KIND_LABEL[k] ?? k.toLowerCase()}
                </span>
              ))}
            </div>
          )}
          {stats.days.length > 1 && busiest && (
            <>
              <div className="row spread tiny muted stat-day-run-head">
                <span>Busiest {busiest.checkins} on {shortDay(busiest.day)}</span>
                <span>{maxDay} in a day</span>
              </div>
              <div className="stat-cols">
                {stats.days.map((d) => (
                  <span
                    key={d.day}
                    className={`stat-col${d.checkins ? '' : ' is-empty'}`}
                    title={`${shortDay(d.day)} · ${d.checkins} check-ins`}
                  >
                    <i style={{ height: d.checkins ? `${Math.max(8, (d.checkins / maxDay) * 100)}%` : '3px' }} />
                  </span>
                ))}
              </div>
              <div className="stat-cols-axis tiny muted">
                <span>{shortDay(stats.days[0].day)}</span>
                <span>{shortDay(stats.days[Math.floor(stats.days.length / 2)].day)}</span>
                <span>{shortDay(stats.days[stats.days.length - 1].day)}</span>
              </div>
            </>
          )}
        </div>
      )}

      {view === 'days' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Busiest days</h3>
            <span className="tiny muted">check-ins, {stats.range.label.toLowerCase()}</span>
          </div>
          <ColumnRun
            max={maxWeekday}
            rows={stats.weekday.map((d) => ({ key: d.label, label: d.label, count: d.checkins }))}
          />
        </div>
      )}

      {view === 'hours' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Peak gate hours</h3>
            <span className="tiny muted">when riders arrive, {stats.range.label.toLowerCase()}</span>
          </div>
          <ColumnRun
            max={maxHour}
            rows={hourRows.map((h) => ({
              key: String(h.hour),
              label: hourLabel(h.hour),
              count: h.checkins,
            }))}
          />
        </div>
      )}

      {view === 'riders' && (
        <div className="stat-card">
          <div className="stat-card-head">
            <h3>Top riders</h3>
          </div>
          <div className="stat-rows">
            {stats.topRiders.map((r) => (
              <div className="stat-row" key={r.name}>
                <span className="stat-row-name">{r.name}</span>
                <span className="tiny muted">{r.paidCents ? money(r.paidCents) : '—'}</span>
                <span className="stat-bar-count">{r.visits}</span>
              </div>
            ))}
            {!stats.topRiders.length && (
              <div className="small muted">No riders {rangeWords(range)}.</div>
            )}
          </div>
        </div>
      )}
    </section>
  );
}

