.qr-sheet .pass-code { width: 100%; }

.qr-sheet .pass-id-foot { text-align: center; justify-items: center; }

import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import QrPanel from '../QrPanel/QrPanel';
import { dayStr } from '../../lib/api';
import './PassQrSheet.scss';

/**
 * The pass QR on its own layer, so it can be held up at the gate without the
 * chrome that opened it — the account menu's, or the network rail's `Pass QR`
 * button. Escape or a click on the backdrop closes it.
 *
 * Portalled to the body on purpose: the app header carries `backdrop-filter`,
 * which makes it a containing block for fixed children, so an overlay rendered
 * in place would be trapped inside the header strip when opened from there.
 */
export default function PassQrSheet({
  active,
  expiresAt,
  status,
  onClose,
}: {
  active: boolean;
  expiresAt: string;
  status: string;
  onClose: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  /* Focus lands on the panel once, when the sheet opens — its own effect, with
     no dependency. `onClose` is a fresh arrow every render of the page, so
     folding this into the listener below re-ran it on every keystroke and
     pulled the cursor back out to the panel: one character in, the rest of the
     typing went nowhere. */
  useEffect(() => {
    panel.current?.focus();
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return createPortal(
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet qr-sheet"
        role="dialog"
        aria-modal="true"
        aria-labelledby="pass-qr-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id="pass-qr-title">
          Pass QR code
        </h2>
        <QrPanel active={active} bare />
        <div className="pass-id-foot">
          <span>
            Valid through <strong>{dayStr(expiresAt)}</strong>
            {!active && ` · ${status.toLowerCase()}`}
          </span>
        </div>
        <div className="sheet-actions">
          <button className="ghost" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* The eye toggle sits inside the field's own right edge, so the input keeps the
   app's material and only reserves the glyph's column. Colour is inherited
   (muted by opacity) rather than tokenised, so the same rule reads on the plain
   forms and on the Astryx auth page's `--ax-*` surfaces. */

.password-field {
  position: relative;
  display: block;
}

.password-field input.password-input {
  width: 100%;
  padding-right: 40px;
}

.password-eye {
  position: absolute;
  top: 50%;
  right: 3px;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 6px;
  color: inherit;
  opacity: 0.5;
  transition: opacity 0.12s ease;
}

.password-eye:hover:not(:disabled),
.password-eye:focus-visible {
  opacity: 1;
}

.password-eye[aria-pressed='true'] {
  opacity: 0.85;
}

.password-eye:focus-visible {
  outline: 2px solid var(--accent-2, var(--ax-accent, currentColor));
  outline-offset: 1px;
}

.password-eye svg {
  display: block;
  width: 17px;
  height: 17px;
}

import { useId, useState } from 'react';
import type { ChangeEvent, FocusEvent } from 'react';
import './PasswordField.scss';

/**
 * A password input with an eye toggle: the field is masked by default and the
 * button reveals what was typed, then masks it again.
 *
 * The accessible pattern is the standard one — the field stays `type="password"`
 * (so a screen reader never announces the characters of a hidden password), the
 * toggle is a real `button` with a name that swaps ("Show password" / "Hide
 * password"), `aria-pressed` for the state and `aria-controls` for the field it
 * drives. The SVG is `aria-hidden`, so the glyph never becomes the button's
 * name. A screen-reader user therefore only sees plain text after pressing the
 * toggle themselves, and the control announces its own state either way.
 *
 * Anything else about the input (id, autocomplete, required, aria-invalid, the
 * error wiring) is passed straight through, so the field can replace a bare
 * `<input type="password">` without touching the form around it.
 */
export default function PasswordField({
  id,
  name,
  value,
  onChange,
  onBlur,
  autoComplete,
  placeholder,
  required,
  autoFocus,
  ariaInvalid,
  ariaDescribedBy,
}: {
  /** The label's `htmlFor` target; generated when the caller has none. */
  id?: string;
  name?: string;
  value: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
  onBlur?: (e: FocusEvent<HTMLInputElement>) => void;
  autoComplete?: string;
  placeholder?: string;
  required?: boolean;
  autoFocus?: boolean;
  ariaInvalid?: boolean;
  ariaDescribedBy?: string;
}) {
  const generated = useId();
  const inputId = id ?? generated;
  const [visible, setVisible] = useState(false);

  return (
    <div className="password-field">
      <input
        id={inputId}
        name={name}
        className="password-input"
        type={visible ? 'text' : 'password'}
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        autoComplete={autoComplete}
        placeholder={placeholder}
        required={required}
        autoFocus={autoFocus}
        aria-invalid={ariaInvalid ? true : undefined}
        aria-describedby={ariaDescribedBy}
        /* A visible password is still a secret: no spellcheck, no autocorrect,
           no sentence-capitalisation on the revealed text. */
        spellCheck={false}
        autoCorrect="off"
        autoCapitalize="off"
      />
      <button
        type="button"
        className="password-eye"
        onClick={() => setVisible((v) => !v)}
        aria-pressed={visible}
        aria-controls={inputId}
        aria-label={visible ? 'Hide password' : 'Show password'}
        title={visible ? 'Hide password' : 'Show password'}
      >
        {visible ? (
          <svg viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
            <path
              d="M2.5 3.5 17.5 16.5M8.1 8.2a2.7 2.7 0 0 0 3.7 3.7M5.4 5.9C3.7 7 2.4 8.5 1.8 10c1.3 2.9 4.4 5 8.2 5 1.6 0 3-.4 4.2-1.1M8.6 5.1c.5-.1.9-.1 1.4-.1 3.8 0 6.9 2.1 8.2 5-.4.9-1 1.8-1.7 2.5"
              stroke="currentColor"
              strokeWidth="1.4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        ) : (
          <svg viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
            <path
              d="M1.8 10c1.3-2.9 4.4-5 8.2-5s6.9 2.1 8.2 5c-1.3 2.9-4.4 5-8.2 5s-6.9-2.1-8.2-5Z"
              stroke="currentColor"
              strokeWidth="1.4"
              strokeLinejoin="round"
            />
            <circle cx="10" cy="10" r="2.7" stroke="currentColor" strokeWidth="1.4" />
          </svg>
        )}
      </button>
    </div>
  );
}

