import { useEffect, useState } from 'react';
import Banner from '../Banner/Banner';
import { api } from '../../lib/api';
import PerkSheet from '../PerkSheet/PerkSheet';
import './PerksSection.scss';

interface Perk {
  id: string;
  code: string;
  title: string;
  description: string | null;
  discountType: string;
  value: number;
  trackName: string | null;
  trackWebsite: string | null;
  redeemed: boolean;
}

/**
 * Offers attached to the pass, one card per offer: the offer and a single redeem
 * action. Redeem opens a sheet carrying the how-to-redeem detail — the offer's
 * own description, the code, and where it is good — and the sheet's confirm
 * records the redemption.
 *
 * The section renders its own heading, so the heading can carry a pulsing marker
 * while any offer on the pass is still unredeemed. It lives on the network page;
 * the /tracks/perks route renders the same thing (as an h1, with a blurb).
 */
export default function PerksSection({
  titleAs: Heading = 'h2',
  blurb,
}: {
  titleAs?: 'h1' | 'h2';
  blurb?: string;
}) {
  const [perks, setPerks] = useState<Perk[]>([]);
  const [msg, setMsg] = useState<{ ok: boolean; text: string } | null>(null);
  const [loading, setLoading] = useState(true);
  const [sheetPerk, setSheetPerk] = useState<Perk | null>(null);
  const [busy, setBusy] = useState(false);

  const load = async () => {
    const res = await api.get<{ perks: Perk[] }>('/me/perks');
    setPerks(res.data?.perks ?? []);
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const redeem = async (code: string) => {
    setBusy(true);
    const res = await api.post(`/me/perks/${code}/redeem`);
    setBusy(false);
    setSheetPerk(null);
    setMsg({ ok: res.success, text: res.message });
    load();
  };

  // Anything not yet redeemed is still sitting there to be claimed.
  const pending = perks.filter((p) => !p.redeemed).length;

  return (
    <section className="stack">
      <Heading className="perk-head">
        {pending > 0 && <span className="perk-ping" aria-hidden="true" />}
        <span>Perks &amp; discounts</span>
      </Heading>
      {blurb && <div className="perk-head-blurb small muted">{blurb}</div>}

      {msg && <Banner tone={msg.ok ? 'ok' : 'bad'} close>{msg.text}</Banner>}

      {loading ? (
        <div className="muted">Loading perks…</div>
      ) : (
        <div className="perk-grid">
          {perks.map((p) => (
            <div className={`perk-card ${p.redeemed ? 'redeemed' : ''}`} key={p.id}>
              <span className="perk-card-title">{p.title}</span>
              {p.redeemed ? (
                <span className="perk-cta done">Redeemed</span>
              ) : (
                <button className="perk-cta" onClick={() => setSheetPerk(p)}>
                  Redeem
                </button>
              )}
            </div>
          ))}
          {!perks.length && <div className="muted small">No perks on your pass yet.</div>}
        </div>
      )}

      {sheetPerk && (
        <PerkSheet
          perk={sheetPerk}
          busy={busy}
          onClose={() => setSheetPerk(null)}
          onRedeem={redeem}
        />
      )}
    </section>
  );
}

/* PhotoLightbox — styles owned by PhotoLightbox.tsx.
   Split out of styles/global.scss; imported once from PhotoLightbox.tsx and
   still plain global class names (this app uses no CSS modules). */

/* Full-screen viewer for the whole set — the grid only ever shows seven.
   Above the sticky header (1050): at 60 the header's row covered the viewer's
   own bar and its close control. Under the sheet (1200). */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 1150;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: 10px;
  padding: 14px clamp(12px, 4vw, 40px) 22px;
  /* Slightly transparent so the page reads through the scrim. */
  background: rgba(6, 7, 9, .86);
}

.lightbox-bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; }

.lightbox-close {
  width: 34px;
  height: 34px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--bg-3);
  color: var(--text);
  font-size: 22px;
  line-height: 1;
  /* kill the global button padding (8px 14px) — inside a 34px square it left a
     6px-wide content box, so the × landed ~4.4px right of centre. */
  padding: 0;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.lightbox-close:hover { border-color: var(--muted); }

/* The row is pinned to the stage's own height: left to itself the grid sizes it
   to the photo, so `max-height: 100%` on the image would resolve against the
   photo and never shrink it — it would spill over whatever sits below. */
.lightbox-stage { position: relative; display: grid; grid-template-rows: minmax(0, 1fr); place-items: center; min-height: 0; cursor: zoom-out; }

.lightbox-stage img {
  cursor: default;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  display: block;
  border-radius: 6px;
}

.lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--scrim-soft);
  color: var(--text);
  cursor: pointer;
  font-size: 16px;
  line-height: 1;
}

.lightbox-nav:hover { background: var(--bg-3); }

.lightbox-nav.prev { left: 6px; }

.lightbox-nav.next { right: 6px; }

.lightbox-caption {
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
  padding: 4px 10px;
  border-radius: 4px;
  background: rgba(9, 10, 12, .8);
}

/* With a detail card in the corner the caption moves to the other foot, so the
   two never sit on top of one another. */
.lightbox-stage.has-detail .lightbox-caption { left: 12px; transform: none; }

/* The caller's detail card. It is placed by script against the photo's own box
   (see placeAside) — this is the fallback position for the frame before the
   first measurement, and the sheet it becomes below 640px, where the script
   stands down and the stylesheet pins it across the stage's foot. */
.lightbox-aside {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 2;
  max-width: min(360px, calc(100% - 24px));
  pointer-events: auto;
}

@media (max-width: 640px) {
  .lightbox-aside {
    left: 12px;
    right: 12px;
    bottom: 12px;
    max-width: none;
  }
}

/* The filmstrip under the stage: the whole set in one row. It never shows more
   than eight at once — a thumb is an eighth of the row's width, capped so a
   wide screen still stops at eight — and fewer fit as the screen narrows. The
   paging arrows exist only when the row has somewhere to go, which is exactly
   the case of a ninth photo or a screen too narrow for the eight. */
.lightbox-strip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  max-width: 1184px;
  margin: 0 auto;
}

.lightbox-strip {
  display: flex;
  flex: 1;
  min-width: 0;
  gap: 8px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scrollbar-width: none;
}

.lightbox-strip::-webkit-scrollbar { display: none; }

.lightbox-thumb {
  flex: 0 0 auto;
  width: clamp(44px, calc((100% - 56px) / 8), 140px);
  aspect-ratio: 4 / 3;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 4px;
  overflow: hidden;
  background: var(--bg-3);
  opacity: .5;
  cursor: pointer;
  transition: opacity .15s ease, border-color .15s ease;
}

.lightbox-thumb img { width: 100%; height: 100%; object-fit: cover; display: block; }

.lightbox-thumb:hover { opacity: .8; }

.lightbox-thumb.active { opacity: 1; border-color: var(--muted); }

/* In the owner console the strip is also the ordering control, so the frames
   read as something you can pick up — the public gallery leaves this off. */
.lightbox-strip.reorderable .lightbox-thumb { cursor: grab; }

.lightbox-strip.reorderable .lightbox-thumb:active { cursor: grabbing; }

.lightbox-thumb.dragging { opacity: .3; }

.lightbox-thumb.drop-before { box-shadow: inset 2px 0 0 var(--accent); border-color: var(--accent); }

.lightbox-thumb.drop-after { box-shadow: inset -2px 0 0 var(--accent); border-color: var(--accent); }

.lightbox-strip-nav {
  flex: none;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--scrim-soft);
  color: var(--text);
  font-size: 14px;
  line-height: 1;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.lightbox-strip-nav:hover { background: var(--bg-3); }

/* An arrow that has nowhere to go is invisible but still takes its place: if it
   dropped out of the layout the strip would grow, the row would no longer look
   paged, and the arrow would flicker back in at the end of the set. */
.lightbox-strip-nav[hidden] {
  display: grid;
  visibility: hidden;
  pointer-events: none;
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type DragEvent,
  type ReactNode,
} from 'react';
import { dropSide, insertAt } from '../../lib/dragReorder';
import './PhotoLightbox.scss';

export interface LightboxPhoto {
  id: string;
  url: string;
  caption: string | null;
}

/**
 * Full-screen viewer for a photo set.
 *
 * Shared by the public venue gallery and the owner console, so a frame the
 * operator is managing opens at the same size, with the same arrows, keys and
 * filmstrip, as it does on the page. The caller owns which frame is open; this
 * only reports movement back.
 *
 * The strip holds the whole set in one row, eight thumbs at a time on a wide
 * screen and fewer as the screen narrows, so the paging arrows are only there
 * when the row actually has somewhere to go.
 *
 * When the caller passes `onReorder`, the strip also becomes the ordering
 * control: drag a frame left or right and it reports the new place. The public
 * page leaves that off — a visitor viewing the gallery is not editing it.
 */
export default function PhotoLightbox({
  photos,
  name,
  index,
  onIndex,
  onClose,
  onReorder,
  aside,
}: {
  photos: LightboxPhoto[];
  /** Used for the fallback alt text. */
  name: string;
  index: number;
  onIndex: (next: number) => void;
  onClose: () => void;
  /** `toInsert` is a gap index into the list as it stands (0…length). */
  onReorder?: (from: number, toInsert: number) => void;
  /** Detail card pinned inside the photo's bottom-right corner — a review's
   *  words and its rider, say. Laid over the frame itself, not over the scrim,
   *  so it stays beside the photo on a wide screen and drops to the stage's
   *  foot as a sheet below 640px. */
  aside?: ReactNode;
}) {
  const close = onClose;
  const step = useCallback(
    (by: number) => onIndex((index + by + photos.length) % photos.length),
    [index, photos.length, onIndex]
  );

  // Dragging a thumb: which one is in hand, and which gap it would land in.
  const [dragFrom, setDragFrom] = useState<number | null>(null);
  const [dropAt, setDropAt] = useState<{ index: number; side: 'before' | 'after' } | null>(null);

  const endDrag = useCallback(() => {
    setDragFrom(null);
    setDropAt(null);
  }, []);

  const dragOver = (e: DragEvent<HTMLButtonElement>, i: number) => {
    if (dragFrom === null) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const side = dropSide(e, e.currentTarget.getBoundingClientRect(), 'x');
    setDropAt((prev) => (prev && prev.index === i && prev.side === side ? prev : { index: i, side }));
  };

  const drop = (e: DragEvent<HTMLButtonElement>) => {
    if (dragFrom === null || !dropAt || !onReorder) return;
    e.preventDefault();
    const to = insertAt(dropAt.index, dropAt.side);
    if (to !== dragFrom && to !== dragFrom + 1) onReorder(dragFrom, to);
    endDrag();
  };

  const stripRef = useRef<HTMLDivElement | null>(null);

  // The aside tracks the *photo's* box, not the stage's: the stage is the whole
  // viewing area, and a landscape frame leaves empty columns beside it where a
  // card pinned to the stage would float off the picture entirely. So the
  // image's rect is measured and the card is placed against it.
  const stageRef = useRef<HTMLDivElement | null>(null);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const asideRef = useRef<HTMLDivElement | null>(null);

  const placeAside = useCallback(() => {
    const stage = stageRef.current;
    const img = imgRef.current;
    const panel = asideRef.current;
    if (!stage || !img || !panel) return;
    // Below 640px the stylesheet takes over and pins the card to the stage's
    // foot as a sheet — the measurements would only fight it.
    if (window.innerWidth <= 640) {
      panel.style.removeProperty('left');
      panel.style.removeProperty('top');
      panel.style.removeProperty('right');
      panel.style.removeProperty('bottom');
      panel.style.removeProperty('max-width');
      return;
    }
    const sr = stage.getBoundingClientRect();
    const ir = img.getBoundingClientRect();
    const pad = 12;
    // A card never wider than the photo it sits on, and never wider than 360.
    panel.style.maxWidth = `${Math.min(360, Math.max(200, Math.round(ir.width - pad * 2)))}px`;
    const pw = panel.offsetWidth;
    const ph = panel.offsetHeight;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
    panel.style.left = `${Math.max(pad, Math.round(ir.right - sr.left - pw - pad))}px`;
    panel.style.top = `${Math.max(pad, Math.round(ir.bottom - sr.top - ph - pad))}px`;
  }, []);

  const [canPage, setCanPage] = useState({ back: false, on: false });

  const syncStrip = useCallback(() => {
    const el = stripRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    const next = { back: el.scrollLeft > 2, on: el.scrollLeft < max - 2 };
    // A scroll event fires many times over; keep the render off unless the
    // arrows would actually change.
    setCanPage((prev) => (prev.back === next.back && prev.on === next.on ? prev : next));
  }, []);

  const page = useCallback(
    (by: number) => {
      const el = stripRef.current;
      if (!el) return;
      el.scrollBy({ left: by * el.clientWidth });
      // The paging scroll is instant, so the position is already settled — read
      // it now rather than waiting on a scroll event to come back around.
      syncStrip();
    },
    [syncStrip]
  );

  useEffect(() => {
    const el = stripRef.current;
    if (!el) return;
    syncStrip();
    const ro = new ResizeObserver(syncStrip);
    ro.observe(el);
    // The observer covers the strip's own size; the window listener makes the
    // arrows land in the same frame as a resize rather than a beat later.
    window.addEventListener('resize', syncStrip);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', syncStrip);
    };
  }, [syncStrip]);

  // Keep the photo on screen in view as the viewer moves through the set. The
  // strip may have just shifted, so re-read the arrows rather than leaving them
  // a step behind.
  useEffect(() => {
    const el = stripRef.current;
    const active = el?.querySelector<HTMLElement>('.lightbox-thumb.active');
    if (!el || !active) return;
    const left = active.offsetLeft;
    const right = left + active.offsetWidth;
    if (left < el.scrollLeft) el.scrollTo({ left: left - 8 });
    else if (right > el.scrollLeft + el.clientWidth) {
      el.scrollTo({ left: right - el.clientWidth + 8 });
    }
    syncStrip();
  }, [index, syncStrip]);

  useEffect(() => {
    if (!aside) return;
    placeAside();
    const ro = new ResizeObserver(placeAside);
    const stage = stageRef.current;
    if (stage) ro.observe(stage);
    window.addEventListener('resize', placeAside);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', placeAside);
    };
  }, [aside, index, placeAside]);

  /* One lock for the viewer's whole life. `overflow: hidden` on the body makes
     the page unscrollable — and on a page whose body is the scroll container
     (the app's pages are, since html and body are both 100% tall) that lock
     leaves the offset on the body, not the window. Read and restore both: on a
     long venue the page scrolls the window, on a short one the body carries the
     offset. Kept apart from the key handler above: that one re-runs on every
     frame step, and a lock that re-captured the offset each time would restore
     the wrong place. Layout, not passive: the restore has to land in the
     unmount commit, before the page's own recentre runs its next animation
     frame — a passive cleanup runs after paint and would scroll away from the
     card it just centred. */
  useLayoutEffect(() => {
    const prev = document.body.style.overflow;
    const wasAtWindow = window.scrollY;
    const wasAtBody = document.body.scrollTop;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
      // Restoring `overflow` drops the body's own offset, so set it back
      // before the window's (a short page has no window offset at all).
      if (wasAtBody) document.body.scrollTop = wasAtBody;
      window.scrollTo(0, wasAtWindow);
    };
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') close();
      if (e.key === 'ArrowRight') step(1);
      if (e.key === 'ArrowLeft') step(-1);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [close, step]);

  return (
    <div className="lightbox" role="dialog" aria-modal="true" onClick={close}>
      <div className="lightbox-bar">
        <span className="row" style={{ gap: 10, alignItems: 'baseline' }}>
          <span className="small muted">
            {index + 1} / {photos.length}
          </span>
          {onReorder && <span className="tiny muted">Drag a frame to reorder</span>}
        </span>
        <button type="button" className="lightbox-close" onClick={close} aria-label="Close viewer" title="Close">
          <svg width="15" height="15" viewBox="0 0 14 14" aria-hidden="true">
            <path
              d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              strokeLinecap="round"
            />
          </svg>
        </button>
      </div>
      <div
        className={`lightbox-stage${aside ? ' has-detail' : ''}`}
        ref={stageRef}
        onClick={(e) => {
          // Clicks inside the stage never reach the backdrop; clicking the
          // letterboxing around the photo (the stage itself) closes.
          e.stopPropagation();
          if (e.target === e.currentTarget) close();
        }}
      >
        <button type="button" className="lightbox-nav prev" onClick={() => step(-1)} aria-label="Previous photo">
          ←
        </button>
        <img
          ref={imgRef}
          src={photos[index].url}
          alt={photos[index].caption ?? `${name} photo ${index + 1}`}
          onLoad={placeAside}
        />
        {photos[index].caption && <div className="lightbox-caption small">{photos[index].caption}</div>}
        {aside && (
          <div className="lightbox-aside" ref={asideRef}>
            {aside}
          </div>
        )}
        <button type="button" className="lightbox-nav next" onClick={() => step(1)} aria-label="Next photo">
          →
        </button>
      </div>

      <div className="lightbox-strip-row" onClick={(e) => e.stopPropagation()}>
        <button
          type="button"
          className="lightbox-strip-nav"
          hidden={!canPage.back}
          onClick={() => page(-1)}
          aria-label="Earlier photos"
          title="Earlier"
        >
          ←
        </button>
        <div className={`lightbox-strip${onReorder ? ' reorderable' : ''}`} ref={stripRef} onScroll={syncStrip}>
          {photos.map((p, i) => (
            <button
              key={p.id}
              type="button"
              className={[
                'lightbox-thumb',
                i === index ? 'active' : '',
                dragFrom === i ? 'dragging' : '',
                dropAt && dropAt.index === i && dragFrom !== null ? `drop-${dropAt.side}` : '',
              ]
                .filter(Boolean)
                .join(' ')}
              onClick={() => onIndex(i)}
              aria-label={`Show ${name} photo ${i + 1}`}
              aria-current={i === index}
              draggable={!!onReorder}
              onDragStart={(e) => {
                if (!onReorder) return;
                setDragFrom(i);
                e.dataTransfer.effectAllowed = 'move';
                // Firefox only starts a drag with some data set.
                e.dataTransfer.setData('text/plain', p.id);
              }}
              onDragOver={(e) => dragOver(e, i)}
              onDragLeave={() => setDropAt((prev) => (prev && prev.index === i ? null : prev))}
              onDrop={drop}
              onDragEnd={endDrag}
            >
              <img src={p.url} alt="" draggable={false} />
            </button>
          ))}
        </div>
        <button
          type="button"
          className="lightbox-strip-nav"
          hidden={!canPage.on}
          onClick={() => page(1)}
          aria-label="Later photos"
          title="Later"
        >
          →
        </button>
      </div>
    </div>
  );
}

/* PresaleSwitcher — styles owned by PresaleSwitcher.tsx.
   Plain global class names, same as the rest of the app (no CSS modules).
   Bottom left, clear of the map's zoom control and the page's own footer. */

/* ── TEMPORARY: presale / live view switch (see components/PresaleSwitcher.tsx) ── */
.presale-switch {
  position: fixed;
  left: 18px;
  bottom: 18px;
  z-index: 1150;
  display: flex;
  align-items: center;
  gap: 6px;
}

.presale-switch-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg-2);
  box-shadow: var(--shadow);
  color: var(--text);
  font: inherit;
  font-size: 12px;
  letter-spacing: 0.01em;
  cursor: pointer;
}

.presale-switch-btn:hover { border-color: var(--accent); }

.presale-switch-btn:focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: 2px;
}

/* The dot names the phase: filled while the presale view is on. */
.presale-switch-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1px solid var(--muted);
  background: transparent;
}

.presale-switch-dot.on {
  border-color: var(--accent);
  background: var(--accent);
}

.presale-switch-reset {
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg-2);
  color: var(--muted);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.presale-switch-reset:hover { border-color: var(--accent); color: var(--text); }

/* The footnote a live preview carries while the API's gate is still closed.
   Sits at the top of the page area, one muted line, no border. */
.presale-switch-note {
  margin: 0 0 14px;
  padding: 8px 12px;
  border-left: 2px solid var(--accent);
  background: var(--bg-2);
  border-radius: var(--radius);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

/**
 * TEMPORARY — the presale / live view switch.
 *
 * A small floating control at the bottom left for showing either face of the
 * site: the presale page with the nav cut to Pricing, or the full network.
 * It sets the preview override in `lib/launch.tsx`, which drives what the UI
 * renders *and* pushes the same phase to `POST /api/launch/view`, so the
 * server's gate moves with it and the network really reads. Production refuses
 * that write unless `LAUNCH_ALLOW_PREVIEW=true` (or the caller is an ADMIN);
 * `PreviewGateNotice` names that case when the pages come back 403 anyway.
 *
 * The label reads the view on screen (`presaleMode`), not the raw server phase,
 * so a pass holder browsing normally still sees "Live". The choice persists in
 * localStorage until `reset`, which follows the server again.
 *
 * Remove this file + its `.presale-switch*` SCSS block + the <PresaleSwitcher />
 * and <PreviewGateNotice /> lines in Layout.tsx to take it back out.
 */
import { usePresale } from '../../lib/launch';
import { useLocation } from 'react-router-dom';
import './PresaleSwitcher.scss';

/** The window's last day, as the notice names it: `Jan 1, 2027`. */
function formatDay(iso: string | null): string | null {
  if (!iso) return null;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return null;
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
}

export default function PresaleSwitcher() {
  const { presaleMode, view, setView, loading } = usePresale();
  // Nothing to switch until the read lands: a button that reads "Live" for a
  // frame on the presale page is the wrong answer, not an early one.
  if (loading) return null;
  const next = presaleMode ? 'live' : 'presale';

  return (
    <div className="presale-switch">
      <button
        type="button"
        className="presale-switch-btn"
        aria-label={`View: ${presaleMode ? 'presale' : 'live'}, switch to ${next}`}
        title={`View: ${presaleMode ? 'presale' : 'live'}, switch to ${next}`}
        onClick={() => setView(presaleMode ? 'OPEN' : 'PRESALE')}
      >
        <span className={`presale-switch-dot${presaleMode ? ' on' : ''}`} aria-hidden="true" />
        {presaleMode ? 'Presale' : 'Live'}
      </button>
      {view && (
        <button
          type="button"
          className="presale-switch-reset"
          aria-label="Follow the server's launch window again"
          title="Follow the server's launch window again"
          onClick={() => setView(null)}
        >
          reset
        </button>
      )}
    </div>
  );
}

/**
 * The honest footnote to a live preview the server did not take: production
 * refuses `POST /api/launch/view` unless the domain allows it, so the switch
 * moves only the client and the network, a venue page and the rider's calendar
 * still answer 403 and draw empty. Renders nothing in every other state,
 * including a normal live site.
 */
export function PreviewGateNotice() {
  const { view, serverGateOpen, presaleEndsAt, loading } = usePresale();
  const { pathname } = useLocation();
  if (loading || view !== 'OPEN' || serverGateOpen) return null;
  /* Only the surfaces the gate actually closes: the network, a venue page, the
     rider's calendar and perks. The home and pricing pages read fine. */
  const gated =
    pathname === '/tracks/history'
      ? false
      : /^\/tracks(\/[^/]+)?$/.test(pathname) || /^\/tracks\/(calendar|perks)$/.test(pathname);
  if (!gated) return null;
  const closes = formatDay(presaleEndsAt);
  return (
    <p className="presale-switch-note" role="status">
      Preview: the presale gate still closes the network{closes ? ` until ${closes}` : ''}. Gated
      pages read as empty here.
    </p>
  );
}

import { useAuth } from '../lib/auth';
import FollowButton from './FollowButton/FollowButton';
import { statusLabel, type MapTrack } from '../lib/trackAccess';

/**
 * The compact profile of the track picked in the rail: the venue's name, the
 * follow control, and its hours today — the three things a rider checks without
 * opening the full panel. Pinned to the bottom of the rail so it stays in reach
 * while the rail shows the day list or the picked track's own panel.
 *
 * `onFollow` reports the toggle up to the rail, which is the one place the
 * network's follow flags are held.
 */
export default function ProfileMini({
  track,
  onFollow,
}: {
  track: MapTrack;
  onFollow?: (trackId: string, following: boolean) => void;
}) {
  const { user } = useAuth();
  return (
    <div className="profile-mini">
      <div className="profile-mini-head">
        <span className="profile-mini-name">{track.name}</span>
        {/* Following belongs to a rider account: a visitor gets the card
            without it, and so does an operator. */}
        {user && user.role === 'RIDER' && (
          <FollowButton
            trackId={track.id}
            name={track.name}
            following={Boolean(track.following)}
            onChange={(f) => onFollow?.(track.id, f)}
            compact
          />
        )}
      </div>

      <div className="profile-mini-hours">
        <span className="muted">Hours today</span>
        {track.hours ? (
          <b>{track.hours}</b>
        ) : (
          <b className={`status-pill status-${track.status.toLowerCase()}`}>
            {statusLabel(track.status)}
          </b>
        )}
      </div>
    </div>
  );
}

/**
 * One SVG icon for the perks section: a ticket stub, on a 16px grid at
 * stroke-width 1.5. `currentColor` so the card decides the colour. Every promo
 * type renders the same ticket icon — the type is not drawn on the card at all
 * (no icon variant, no label), so the offer title is what names the perk.
 */

const svgProps = {
  width: 16,
  height: 16,
  viewBox: '0 0 16 16',
  fill: 'none',
  stroke: 'currentColor',
  strokeWidth: 1.5,
  strokeLinecap: 'round' as const,
  strokeLinejoin: 'round' as const,
  'aria-hidden': true,
  focusable: 'false' as const,
};

export const PROMO_TYPE_LABEL: Record<string, string> = {
  PERCENT: 'Percent off',
  FIXED_AMOUNT: 'Amount off',
  OFFER: 'Free item',
  FREE_DAY: 'Free day',
  BUNDLE: 'Bundle',
  EARLY_ACCESS: 'Early access',
};

export function promoTypeLabel(type: string): string {
  return PROMO_TYPE_LABEL[type] ?? 'Offer';
}

export default function PromoTypeIcon(_props: { type: string }) {
  // A ticket stub — used for every promo type.
  return (
    <svg {...svgProps}>
      <path d="M2.6 4.9h10.8a1 1 0 0 1 1 1v.7a1.3 1.3 0 0 0 0 2.8v.7a1 1 0 0 1-1 1H2.6a1 1 0 0 1-1-1v-.7a1.3 1.3 0 0 0 0-2.8v-.7a1 1 0 0 1 1-1z" />
      <line x1="8" y1="5.6" x2="8" y2="10.4" strokeDasharray="1.1 1.4" />
    </svg>
  );
}

/* QrPanel — styles owned by QrPanel.tsx.
   Split out of styles/global.scss; imported once from QrPanel.tsx and
   still plain global class names (this app uses no CSS modules). */

.pass-code { display: flex; flex-direction: column; align-items: center; gap: 8px; }

.pass-code .row { justify-content: center; }

import { useCallback, useEffect, useRef, useState } from 'react';
import Banner from '../Banner/Banner';
import QRCode from 'qrcode';
import { api } from '../../lib/api';
import './QrPanel.scss';

interface QrToken {
  token: string;
  expiresAt: string;
  nonce: string;
  passId: string;
}

/**
 * Live QR pass. The token is short-lived and signed server-side, so a
 * screenshot of an old code will not scan. Refreshes automatically.
 *
 * `bare` drops the outer card so the panel can sit inside the pass object
 * itself rather than as a separate tile beside it.
 */
export default function QrPanel({ active, bare = false }: { active: boolean; bare?: boolean }) {
  const [data, setData] = useState<QrToken | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [secondsLeft, setSecondsLeft] = useState(0);
  const [showToken, setShowToken] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const load = useCallback(async () => {
    const res = await api.get<QrToken>('/me/qr-token');
    if (!res.success || !res.data) {
      setErr(res.message);
      setData(null);
      return;
    }
    setErr(null);
    setData(res.data);
  }, []);

  useEffect(() => {
    if (!active) return;
    load();
    const id = setInterval(load, 25_000);
    return () => clearInterval(id);
  }, [active, load]);

  useEffect(() => {
    if (!data) return;
    const tick = () => {
      const left = Math.max(Math.round((new Date(data.expiresAt).getTime() - Date.now()) / 1000), 0);
      setSecondsLeft(left);
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, [data]);

  useEffect(() => {
    if (!data || !canvasRef.current) return;
    QRCode.toCanvas(canvasRef.current, data.token, {
      width: 168,
      margin: 1,
      color: { dark: '#0d0f12', light: '#ffffff' },
    });
  }, [data]);

  const save = () => {
    if (!canvasRef.current) return;
    const link = document.createElement('a');
    link.download = 'moto-pass-qr.png';
    link.href = canvasRef.current.toDataURL('image/png');
    link.click();
  };

  if (!active) {
    return (
      <div className={bare ? 'pass-code' : 'card'}>
        <span className="small muted">An active pass is required to generate a code.</span>
      </div>
    );
  }

  const body = (
    <>
      <div style={{ background: '#fff', padding: 10, borderRadius: 6, lineHeight: 0 }}>
        <canvas ref={canvasRef} />
      </div>
      <div className="row" style={{ gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
        <span className="tiny muted">
          {secondsLeft > 0 ? `valid ${secondsLeft}s` : 'refreshing…'}
        </span>
      </div>
      <div className="row wrap" style={{ gap: 8 }}>
        <button className="ghost small" onClick={save} disabled={!data}>
          Save to device
        </button>
        <button className="ghost small" onClick={() => setShowToken((s) => !s)}>
          {showToken ? 'Hide code' : 'Show code'}
        </button>
      </div>
      {showToken && data && (
        <div style={{ width: '100%', maxWidth: 320 }}>
          <label>Scan code (paste at a station)</label>
          <textarea
            className="mono tiny"
            readOnly
            rows={3}
            value={data.token}
            onFocus={(e) => e.currentTarget.select()}
          />
        </div>
      )}
    </>
  );

  if (bare) {
    return (
      <div className="pass-code">
        {err && <Banner tone="bad" close>{err}</Banner>}
        {body}
      </div>
    );
  }

  return (
    <div className="card stack">
      <div className="row spread">
        <h3 style={{ margin: 0 }}>Pass QR code</h3>
        <span className={`pill ${secondsLeft > 0 ? 'ok' : 'bad'}`}>
          {secondsLeft > 0 ? `valid ${secondsLeft}s` : 'refreshing…'}
        </span>
      </div>
      {err && <Banner tone="bad" close>{err}</Banner>}
      <div className="row" style={{ gap: 18, alignItems: 'flex-start', flexWrap: 'wrap' }}>
        {body}
      </div>
    </div>
  );
}

/* The rider dashboard's scan-in log — a narrow column, not a page-wide table:
   the venue reads on the left, the time it was scanned on the right. */
.recent-scans {
