import { useEffect, useState } from 'react';
import { api, timeStr } from '../../lib/api';
import './RecentScans.scss';

interface Redemption {
  id: string;
  trackName: string;
  kind: string;
  day: string;
  redeemedAt: string;
}

/** 20 rows a page — the dashboard column carries a short recent log; the
    whole ledger pages on the rider's own profile (`/user`). */
const PER_PAGE = 20;

/** `Nov 8 · 09:41`, with the year only once the row is from another season. */
function whenLabel(iso: string): string {
  const d = new Date(iso);
  const date = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  const year = d.getFullYear() === new Date().getFullYear() ? '' : `, ${d.getFullYear()}`;
  return `${date}${year} · ${timeStr(iso)}`;
}

/**
 * The rider's own scan-ins, newest first: one line per visit, the venue on
 * the left and the time it was scanned on the right. Paginated over 20 rows
 * off `/me/history`'s `page` / `perPage` read.
 */
export default function RecentScans() {
  const [rows, setRows] = useState<Redemption[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let live = true;
    setLoading(true);
    setError(null);
    api
      .get<{ redemptions: Redemption[]; total: number }>(
        `/me/history?page=${page}&perPage=${PER_PAGE}`
      )
      .then((res) => {
        if (!live) return;
        if (!res.success) {
          setError(res.message || 'Could not load your scan-ins.');
          setRows([]);
          setTotal(0);
          return;
        }
        setRows(res.data?.redemptions ?? []);
        setTotal(res.data?.total ?? 0);
      })
      .catch(() => {
        if (live) setError('Could not load your scan-ins.');
      })
      .finally(() => {
        if (live) setLoading(false);
      });
    return () => {
      live = false;
    };
  }, [page]);

  const totalPages = Math.max(1, Math.ceil(total / PER_PAGE));
  const from = total ? (page - 1) * PER_PAGE + 1 : 0;
  const to = Math.min(page * PER_PAGE, total);

  return (
    <section className="recent-scans">
      <div className="rs-head">
        <h2>Recent scan-ins</h2>
        {!!total && <span className="tiny muted">{total} total</span>}
      </div>

      {loading && <div className="small muted">Loading…</div>}
      {!loading && error && <div className="small muted">{error}</div>}

      {!loading && !error && !rows.length && (
        <div className="small muted">No scans yet.</div>
      )}

      {!loading && !error && !!rows.length && (
        <>
          <ol className="rs-list">
            {rows.map((r) => (
              <li key={r.id} className="rs-row">
                <span className="rs-track">{r.trackName}</span>
                <span className="rs-when">{whenLabel(r.redeemedAt)}</span>
              </li>
            ))}
          </ol>

          {totalPages > 1 && (
            <div className="rs-pager">
              <button
                type="button"
                className="ghost small"
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                disabled={page === 1}
              >
                Prev
              </button>
              <span className="tiny muted rs-range">
                {from}–{to} of {total}
              </span>
              <button
                type="button"
                className="ghost small"
                onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                disabled={page === totalPages}
              >
                Next
              </button>
            </div>
          )}
        </>
      )}
    </section>
  );
}

/* RiderLookup — styles owned by RiderLookup.tsx.
   Split out of styles/global.scss; imported once from RiderLookup.tsx and
   still plain global class names (this app uses no CSS modules). */

/* Find a rider — the gate's second way in. The sheet is a search field over a
   short list of riders; each row names the rider, what pass they hold and what
   is left at this track, then carries the one action. */
.lookup-sheet { width: min(520px, 100%); }

.lookup-sheet .scan-mode { margin: 0 0 12px; justify-self: start; }

.lookup-field { display: grid; gap: 10px; margin-bottom: 12px; }

/* Three keys and the button in one row: label over field, the button resting on
   the fields' baseline. Only the field in use can hold text, so the other two
   read empty and dimmed. */
.lookup-field-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr)) auto;
  gap: 10px;
  /* Tops, not bottoms: an error under one key must not lift or drop the
     others, so every cell hangs from the same label line. */
  align-items: start;
}

.lookup-field-cell { display: grid; gap: 4px; min-width: 0; }

/* Fixed label line so the button can be offset by exactly one label + gap and
   land level with the inputs without measuring anything at runtime. */
.lookup-field-cell label { font-size: 0.78rem; line-height: 1.4; color: var(--muted); margin: 0; }

.lookup-field-cell input { min-width: 0; }

.lookup-field-cell input.is-idle { color: var(--muted); }

/* Bad text is named under the field that holds it, and the field's own edge
   carries the same tint — no banner, no jump in the row. */
.lookup-field-cell input[aria-invalid='true'] {
  border-color: rgba(248, 113, 113, 0.55);
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.25);
}

.lookup-field-error { font-size: 11px; line-height: 1.35; color: var(--bad); }

/* Half a key is not an error, only unfinished: same line, same size, no red. */
.lookup-field-hint { font-size: 11px; line-height: 1.35; color: var(--muted); }

/* An autofilled idle key keeps the dimmed ink too — Chrome's text-fill colour
   would otherwise light it up like the field in use. */
.lookup-field-cell input.is-idle:-webkit-autofill { -webkit-text-fill-color: var(--muted); }

.lookup-field-cell input.is-idle::placeholder { opacity: 0.5; }

/* Rests on the inputs' line, not the labels': one label line plus the cell gap.
   On one column the row stacks, so the offset is dropped. */
.lookup-search-btn {
  align-self: start;
  min-width: 104px;
  white-space: nowrap;
  margin-top: calc(0.78rem * 1.4 + 4px);
}

@media (max-width: 720px) {
  .lookup-field-grid { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 720px) {
  .lookup-search-btn { width: 100%; margin-top: 0; }
}

.lookup-field label { font-size: 0.78rem; color: var(--muted); }

.lookup-hint { padding: 6px 0 2px; }

/* The list is a stack of tiles, not a divided table: each rider is one inset
   card carrying their pattern avatar, their name, and the two ways to reach
   them. The panel's own hairlines are gone, so the rows read as separate
   things to pick rather than lines in a ledger. */
.lookup-hits {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.lookup-hit {
  background: var(--bg-3);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color 0.12s ease;
}

.lookup-hit:hover { border-color: rgba(var(--accent-rgb), 0.55); }

/* The row is the door: the avatar, then the rider's name over their email and
   phone. Nothing else — the standing is the card's job once it opens. */
.lookup-hit-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 11px 14px;
  background: none;
  border: 0;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.lookup-hit-row:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }

.lookup-hit-avatar {
  display: block;
  width: 32px;
  height: 32px;
  border-radius: var(--radius);
  overflow: hidden;
  background: var(--bg-2);
}

.lookup-hit-avatar > img,
.lookup-hit-avatar > svg { display: block; width: 100%; height: 100%; }

.lookup-hit-main { display: grid; gap: 2px; min-width: 0; }

.lookup-hit-main strong { font-size: 0.94rem; font-weight: 600; }

.lookup-hit-main strong,
.lookup-hit-main .small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* The gate view: who the rider is on the left, what the pass says and what can
   be done on the right, divided by one hairline. The decision never hides
   behind a hover, and the id wraps rather than trims — the operator reads it
   out loud at the window. */
.gate-view {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1fr);
  gap: 0 24px;
}

.gate-identity { min-width: 0; padding: 6px 0 4px; }

/* The identity opens on the rider's own photo — the image the result row
   showed, so the card reads as that row opened up. */
.gate-head { display: flex; align-items: center; gap: 12px; }

.gate-photo {
  width: 48px;
  height: 48px;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--bg-3);
  object-fit: cover;
}

.gate-head-text { display: grid; gap: 2px; min-width: 0; }

.gate-name { margin: 0; font-size: 20px; font-weight: 600; letter-spacing: -0.01em; color: var(--text); }

.gate-contact { margin-top: 2px; overflow-wrap: anywhere; }

/* One fact fills the row: a lone Rider ID would otherwise be held to half the
   width by a fixed two-track grid and wrap mid-string. auto-fit collapses the
   empty track, and re-forms it as soon as a second fact is added. */
.gate-facts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 14px 20px;
  margin: 16px 0 0;
}

.gate-facts dt,
.gate-rows dt {
  margin-bottom: 2px;
  font-size: 12px;
  color: var(--muted);
}

.gate-facts dd { margin: 0; font-size: 13px; }

/* The rider id copies from a glyph beside the string, not from a text button in
   the action row: the id is what the operator hands on, so the control sits
   with it. A hairline square that answers with a check for a moment. */
.gate-id { display: flex; align-items: center; gap: 7px; min-width: 0; overflow-wrap: normal; }

.gate-id-text { overflow-wrap: anywhere; }

.copy-id {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--muted);
}

.copy-id:hover:not(:disabled) { opacity: 1; border-color: var(--muted); color: var(--text); }

.copy-id svg { display: block; }

/* Hover beats the copied state on specificity, so name it here too: the check
   has to stay accent-coloured under the pointer that just pressed it. */
.copy-id.copied,
.copy-id.copied:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }

.gate-decision { border-left: 1px solid var(--line); padding: 6px 0 4px 24px; }

.gate-decision-title { margin: 0 0 8px; font-size: 18px; font-weight: 600; letter-spacing: -0.01em; }

.gate-rows { display: grid; margin: 0; }

.gate-rows > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 9px 0;
}

.gate-rows > div + div { border-top: 1px solid var(--line); }

.gate-rows dt { margin: 0; font-size: 13px; color: var(--text); }

.gate-rows dd { margin: 0; font-size: 13px; font-variant-numeric: tabular-nums; }

.gate-rows dd.ok { color: var(--ok); font-weight: 600; }

.gate-rows dd.bad { color: var(--bad); font-weight: 600; }

.gate-rows dd.muted { color: var(--muted); }

/* The days already spent, under the identity: one hairline row per day, the
   date in tabular numerals so a column of them lines up. Folded by default —
   the head is the control and its arrow turns as the record opens. */
.gate-history { margin-top: 20px; }

.gate-history-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 0;
  background: none;
  border: 0;
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.gate-history-title {
  font-size: 13px;
  font-weight: 600;
}

.gate-history-head:hover .gate-history-title { color: var(--accent); }

.gate-history-arrow {
  flex: none;
  color: var(--muted);
  transition: transform 160ms ease-out, color 140ms ease-out;
}

.gate-history[data-open='true'] .gate-history-arrow {
  color: var(--accent);
  transform: rotate(90deg);
}

.gate-history-rows { list-style: none; margin: 4px 0 0; padding: 0; }

.gate-history-rows li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 13px;
}

.gate-history-rows li + li { border-top: 1px solid var(--line); }

.gate-history-when { color: var(--muted); font-variant-numeric: tabular-nums; }

.gate-history-kind {
  font-size: 12px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

/* What stands between this rider and a day, said on the panel rather than as a
   denial after the tap: the scan's own reason code and sentence. */
.gate-notice {
  display: grid;
  gap: 4px;
  margin-top: 12px;
  padding: 10px 12px;
  background: var(--bg-3);
  border: 1px solid rgba(248, 113, 113, 0.45);
  border-radius: var(--radius);
}

.gate-notice strong { color: var(--bad); }

/* The verdict spans the panel above the controls: it is the reason the row
   below is disabled, so it reads before the buttons rather than beside the
   pass figures. */
.gate-view > .gate-notice { grid-column: 1 / -1; margin-top: 16px; }

.gate-note { margin-top: 10px; }

.gate-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-top: 18px; }

/* A free-tier rider with a day in hand has no action, and the row's hairline
   would otherwise close an empty band. */
.gate-actions:empty { display: none; }

.gate-actions button { font-size: 13px; }

/* The actions sit under both columns, not inside the pass column: the row
   spans the panel and a hairline closes the divider above it. */
.gate-view > .gate-actions {
  grid-column: 1 / -1;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

/* The sheet is the narrow home: below the columns' worth of room, the decision
   drops under the identity and the divider turns horizontal. */
.lookup-sheet .gate-view { grid-template-columns: 1fr; gap: 18px 0; }

.lookup-sheet .gate-decision { border-left: 0; border-top: 1px solid var(--line); padding: 16px 0 4px; }

/* Neither half of the station is a card: the search and the results both sit
   straight on the page, the hits list separated from the fields by the band's
   own gap. */
.lookup-results,
.scan-lookup {
  display: grid;
  gap: 12px;
}

/* The one exception is an open rider: the gate view is a document, not a row,
   so it takes the card material back while the list stays bare. Equal
   specificity with the sheet reset below, which therefore still wins inside
   the sheet. */
.lookup-results.has-rider {
  padding: 20px 22px 22px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
}

/* Inside the sheet the section is not a card — the sheet already is one. */
.lookup-sheet .scan-lookup,
.lookup-sheet .lookup-results {
  padding: 0;
  background: none;
  border: 0;
  border-radius: 0;
}

.lookup-sheet .scan-lookup { margin-bottom: 14px; }

.lookup-sheet .lookup-results {
  margin-top: 2px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.scan-lookup-head { flex-wrap: wrap; row-gap: 10px; }

.scan-lookup-title { margin: 0; font-size: 18px; font-weight: 600; letter-spacing: -0.01em; }

.scan-lookup-actions { gap: 10px; flex-wrap: wrap; }

.scan-lookup .scan-mode { margin: 0; justify-self: start; }

.scan-lookup .lookup-field { margin-bottom: 0; }

/* The results head is a label, not a second page title: a quiet line over the rows. */
.lookup-results-head { flex-wrap: wrap; row-gap: 10px; }

.lookup-results-title {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
}

/* The way back rests above the list's card, upper-left: outside the material,
   quieter than anything inside it, an arrow at the way out. */
.lookup-back-row { justify-self: start; margin-bottom: -9px; }

.lookup-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 0;
  background: none;
  border: 0;
  border-radius: 3px;
