import { useEffect, useState } from 'react';
import './ThemeToggle.scss';

/**
 * Theme toggle — dark (default) / light.
 *
 * Flips the whole app by setting `data-theme` on <html>: every surface reads the
 * `--bg` / `--bg-2` / `--text` / `--line` tokens, and the light palette is just a
 * second set of those tokens in global.scss. The choice persists in localStorage
 * (`motopass.theme`); the pre-paint script in index.html applies the stored value
 * before React mounts so the dark palette never flashes first.
 */

type Theme = 'dark' | 'light';

const STORE_KEY = 'motopass.theme';

function stored(): Theme {
  try {
    return localStorage.getItem(STORE_KEY) === 'light' ? 'light' : 'dark';
  } catch {
    return 'dark';
  }
}

function apply(theme: Theme) {
  const root = document.documentElement;
  if (theme === 'light') root.dataset.theme = 'light';
  else delete root.dataset.theme;
  // Keep the mobile browser chrome in step with the surface behind it.
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', theme === 'light' ? '#f5f6f8' : '#0d0f12');
}

export default function ThemeToggle() {
  const [theme, setTheme] = useState<Theme>(stored);

  useEffect(() => {
    apply(theme);
    try {
      if (theme === 'dark') localStorage.removeItem(STORE_KEY);
      else localStorage.setItem(STORE_KEY, theme);
    } catch {
      /* private mode — the choice just won't persist */
    }
  }, [theme]);

  const next = theme === 'dark' ? 'light' : 'dark';

  return (
    <button
      type="button"
      className="theme-toggle"
      aria-pressed={theme === 'light'}
      aria-label={`Switch to ${next} theme`}
      title={`Switch to ${next} theme`}
      onClick={() => setTheme(next)}
    >
      {/* A track with a round knob: dark parks it right under a moon, light
          parks it left under a sun. */}
      <span className="tt-track">
        <span className="tt-thumb">
          {theme === 'dark' ? (
            /* Moon: the app is dark, clicking goes light. */
            <svg width="9" height="9" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path
                d="M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5Z"
                stroke="currentColor"
                strokeWidth="1.9"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            /* Sun: the app is light, clicking goes dark. */
            <svg width="10" height="10" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="1.9" />
              <path
                d="M12 2.6v2.1M12 19.3v2.1M2.6 12h2.1M19.3 12h2.1M5.4 5.4l1.5 1.5M17.1 17.1l1.5 1.5M18.6 5.4l-1.5 1.5M6.9 17.1l-1.5 1.5"
                stroke="currentColor"
                strokeWidth="1.9"
                strokeLinecap="round"
              />
            </svg>
          )}
        </span>
      </span>
    </button>
  );
}

/* ToastStack — styles owned by ToastStack.tsx.
   Split out of styles/global.scss; imported once from ToastStack.tsx and
   still plain global class names (this app uses no CSS modules). */

/* Several floating notices at once: each newer one lands at the corner and the
   older ones stand above it, one gap apart. The stack owns the corner; a notice
   owns nothing but its own row, so it can leave without moving the others. */
.toast-stack {
  position: fixed;
  right: 18px;
  bottom: 18px;
  margin: 0;
  z-index: 1100;
  width: min(360px, calc(100vw - 36px));
  display: flex;
  /* Newest at the corner: the list appends, so the last row sits lowest. */
  flex-direction: column;
  gap: 10px;
  /* The corner is transparent to the page; only the notices take a click. */
  pointer-events: none;
}

.toast-item {
  pointer-events: auto;
  animation: toast-in 0.18s ease-out;
}

.toast-stack .banner { background-color: var(--bg-2); box-shadow: var(--shadow); }

@keyframes toast-in {
  from { opacity: 0; transform: translateY(6px); }
}

import { useCallback, useEffect, useRef, useState } from 'react';
import Banner from '../Banner/Banner';
import './ToastStack.scss';

/** One notice in flight. `id` is the stack's own key, never the server's. */
export interface Toast {
  id: number;
  tone: 'ok' | 'bad' | 'warn' | 'bare';
  title: string;
  detail?: string;
  /** Override the stack's default stay for this one notice. A confirmation the
      reader has to act on (figures to collect at the window) needs longer than
      a plain "saved". */
  ms?: number;
  /** Set once the notice is on its way out; it keeps its row until the exit runs. */
  leaving?: boolean;
}

/** How long a notice stays up. Short on purpose: it is a confirmation, not a
    record — the log holds the record. */
const TOAST_MS = 4000;
/** More than this never fits the corner, and the oldest has already been read. */
const MAX_TOASTS = 3;
/** The exit animation's length (`toast-out` in global.scss). The row is cut
    only after it, so a notice fades down instead of blinking out mid-read. */
const EXIT_MS = 180;

/**
 * The toasts in flight, oldest first. Each one retires on its own timer, so two
 * notices raised a second apart leave a second apart. `push` is stable, which is
 * what lets a caller hand it to a child without tearing that child down.
 */
export function useToasts(ms = TOAST_MS) {
  const seq = useRef(0);
  const timers = useRef(new Map<number, number>());
  const exits = useRef(new Map<number, number>());
  const [toasts, setToasts] = useState<Toast[]>([]);

  const dismiss = useCallback((id: number) => {
    const timer = timers.current.get(id);
    if (timer) {
      window.clearTimeout(timer);
      timers.current.delete(id);
    }
    if (exits.current.has(id)) return;
    // Start the exit, then cut the row when the animation ends.
    setToasts((list) => list.map((t) => (t.id === id ? { ...t, leaving: true } : t)));
    exits.current.set(
      id,
      window.setTimeout(() => {
        exits.current.delete(id);
        setToasts((list) => list.filter((t) => t.id !== id));
      }, EXIT_MS),
    );
  }, []);

  const push = useCallback(
    (toast: Omit<Toast, 'id' | 'leaving'>) => {
      const id = ++seq.current;
      setToasts((list) => [...list, { ...toast, id }].slice(-MAX_TOASTS));
      timers.current.set(
        id,
        window.setTimeout(() => dismiss(id), toast.ms ?? ms),
      );
    },
    [dismiss, ms],
  );

  // An unmount hands every pending timer back.
  useEffect(() => {
    const pending = timers.current;
    const pendingExits = exits.current;
    return () => {
      pending.forEach((timer) => window.clearTimeout(timer));
      pending.clear();
      pendingExits.forEach((timer) => window.clearTimeout(timer));
      pendingExits.clear();
    };
  }, []);

  return { toasts, push, dismiss };
}

/**
 * The bottom-right toast layer. Newest at the corner, older notices standing
 * above it, one gap apart — never overlapping, never pushing the page.
 */
export default function ToastStack({
  toasts,
  onDismiss,
}: {
  toasts: Toast[];
  onDismiss: (id: number) => void;
}) {
  if (toasts.length === 0) return null;
  return (
    <div className="toast-stack" role="status" aria-live="polite">
      {toasts.map((toast) => (
        <div
          className={`toast-item${toast.leaving ? ' leaving' : ''}`}
          key={toast.id}
        >
          <Banner tone={toast.tone} close onDismiss={() => onDismiss(toast.id)}>
            <strong>{toast.title}</strong>
            {toast.detail && <div className="small">{toast.detail}</div>}
          </Banner>
        </div>
      ))}
    </div>
  );
}

/* ToastStackAstryx — styles owned by ToastStackAstryx.tsx (the toast layer
   while `enableAstryxUI` is on).

   Same rules as AstryxLanding.scss / PricingAstryx.scss / RiderCalendarAstryx.scss:
   the register's tokens are declared scoped to `.axt-stack`, never on `:root`, and
   every rule is written under that wrapper. The component draws its own notice
   rather than the app's `.banner`, so nothing here has to out-specify Banner.scss
   or global.scss's `.toast*` layer — those stay for the flag-off path.

   Tone is a mark, not a fill: a filled card per tone paints the corner green at
   the gate, where the reader is looking at a rider, not at the page. */

.axt-stack {
  /* Surfaces, one step each. */
  --ax-surface: #1f1f22;
  --ax-line: rgba(242, 244, 246, 0.1);

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* Tone marks. The card material never moves — only the dot does. */
  --ax-ok: #7fe0a3;
  --ax-warn: #fbbf24;
  --ax-bad: #f87171;

  /* Radii. */
  --ax-r-element: 12px;
  --ax-r-pill: 999px;

  /* Type ramp — only the steps this layer uses. */
  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;

  /* Spacing steps (the register counts in 6s). */
  --ax-s-1: 6px;
  --ax-s-2: 12px;

  --ax-shadow: 0 4px 6px rgba(0, 0, 0, 0.35), 0 12px 24px rgba(0, 0, 0, 0.45);

  position: fixed;
  right: 18px;
  bottom: 18px;
  /* The stack rhythm skips a fixed overlay; this is the guard so a `.stack`
     parent can never nudge the corner. */
  margin: 0;
  z-index: 1100;
  width: min(360px, calc(100vw - 36px));
  display: flex;
  /* Newest at the corner: the list appends, so the last row sits lowest. */
  flex-direction: column;
  gap: 10px;
  /* The corner is transparent to the page; only the notices take a click. */
  pointer-events: none;

  font-family: 'Figtree Variable', Figtree, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-xs);
  line-height: 1.45;
  color: var(--ax-ink);
  -webkit-font-smoothing: antialiased;
}

.axt-item {
  pointer-events: auto;
  animation: axt-in 0.18s ease-out;
}

.axt-toast {
  display: flex;
  align-items: flex-start;
  gap: var(--ax-s-2);
  padding: var(--ax-s-2) var(--ax-s-2) var(--ax-s-2) 14px;
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-element);
  background: var(--ax-surface);
  box-shadow: var(--ax-shadow);
}

/* Sits on the title's cap height rather than the row's centre. */
.axt-mark {
  flex: 0 0 auto;
  width: 8px;
  height: 8px;
  margin-top: 5px;
  border-radius: var(--ax-r-pill);
  background: var(--ax-ink-3);
}

.axt-toast.ok .axt-mark { background: var(--ax-ok); }
.axt-toast.warn .axt-mark { background: var(--ax-warn); }
.axt-toast.bad .axt-mark { background: var(--ax-bad); }

.axt-body {
  flex: 1 1 auto;
  min-width: 0;
}

.axt-title {
  display: block;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--ax-ink);
}

.axt-detail {
  margin-top: 3px;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

/* A pill control, per the register: the glyph is the only thing in it. */
.axt-x {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--ax-r-pill);
  background: transparent;
  color: var(--ax-ink-2);
  cursor: pointer;
}

.axt-x:hover { color: var(--ax-ink); border-color: var(--ax-line); }
.axt-x:focus-visible { outline: 2px solid var(--ax-ink-2); outline-offset: 1px; }

/* The app's light palette, restated for this layer's surfaces. */
:root[data-theme='light'] .axt-stack {
  --ax-surface: #ffffff;
  --ax-line: rgba(5, 54, 89, 0.1);
  --ax-ink: #0a1317;
  --ax-ink-2: #4e606f;
  --ax-ink-3: #7d8b98;
  --ax-ok: #157a43;
  --ax-warn: #b57c07;
  --ax-bad: #c9453f;
  --ax-shadow: 0 4px 6px rgba(5, 54, 89, 0.08), 0 12px 24px rgba(5, 54, 89, 0.14);
}

@keyframes axt-in {
  from { opacity: 0; transform: translateY(6px); }
}

/* The exit is the entrance backwards, run before the row is cut (EXIT_MS). */
.axt-item.leaving {
  animation: axt-out 0.18s ease-in forwards;
  pointer-events: none;
}

@keyframes axt-out {
  to { opacity: 0; transform: translateY(6px); }
}

@media (prefers-reduced-motion: reduce) {
  .axt-item { animation: none; }
  .axt-item.leaving { animation: none; opacity: 0; }
}

import type { Toast } from './ToastStack';
// Self-hosted Figtree, as the landing, the pricing mirror and the rider calendar
// do — never a CDN link.
import '@fontsource-variable/figtree';
import './ToastStackAstryx.scss';

/**
 * The toast layer in the reference design system's register (Astryx), chosen by
 * `enableAstryxUI`. `ToastStack` is still here in full and untouched — flip the
 * flag to `false` and the banner-corner notices come back exactly as they were.
 *
 * Same contract as `ToastStack`: it renders the list `useToasts` hands it
 * (newest lowest, oldest above, one gap apart), reports the dismiss, and keeps
 * the polite live region. What changes is the register — Figtree, the system's
 * surfaces and radii, one notice per Card with a tone mark, a pill dismiss —
 * and it draws its own notice instead of the app's `Banner`, so the banner's
 * translucent tone tints (and the opacity guards they needed over the map)
 * never come into it.
 *
 * The exit's length lives in the stylesheet (`axt-out`), and `useToasts` cuts
 * the row after its own matching EXIT_MS — this component owns neither timer.
 */
export default function ToastStackAstryx({
  toasts,
  onDismiss,
}: {
  toasts: Toast[];
  onDismiss: (id: number) => void;
}) {
  if (toasts.length === 0) return null;
  return (
    <div className="axt-stack" role="status" aria-live="polite">
      {toasts.map((toast) => (
        <div
          className={`axt-item${toast.leaving ? ' leaving' : ''}`}
          key={toast.id}
        >
          <div className={`axt-toast ${toast.tone}`}>
            {/* The tone reads as a mark, not as a fill: a filled card per tone
                would paint the corner green at the gate. */}
            <span className="axt-mark" aria-hidden="true" />
            <div className="axt-body">
              <strong className="axt-title">{toast.title}</strong>
              {toast.detail && <div className="axt-detail">{toast.detail}</div>}
            </div>
            <button
              type="button"
              className="axt-x"
              aria-label="Dismiss"
              title="Dismiss"
              onClick={() => onDismiss(toast.id)}
            >
              <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true" focusable="false">
                <path
                  d="M1.6 1.6 8.4 8.4M8.4 1.6 1.6 8.4"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.4"
                  strokeLinecap="round"
                />
              </svg>
            </button>
          </div>
        </div>
      ))}
    </div>
  );
}

/* TrackGallery — styles owned by TrackGallery.tsx.
