/* The venue gallery: the page opens on one frame and the rest sit beside it.
   1 + 6 is the whole shape — the hero sets the height, the grid fills it, so
   the block reads as one panel rather than a stack of crops. */
.photo-gallery {
  display: grid;
  grid-template-columns: minmax(0, 2.15fr) minmax(0, 1fr);
  gap: 6px;
}

.photo-gallery.solo { grid-template-columns: minmax(0, 1fr); }

.photo-hero {
  position: relative;
  display: block;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-2);
  cursor: pointer;
  aspect-ratio: 16 / 9;
}

.photo-hero img { width: 100%; height: 100%; object-fit: cover; display: block; transition: opacity .15s ease; }

.photo-gallery.solo .photo-hero { aspect-ratio: 16 / 5; max-height: 320px; }

.photo-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .02em;
  padding: 3px 8px;
  border-radius: 4px;
  background: rgba(9, 10, 12, .68);
  border: 1px solid var(--line);
  color: var(--text);
  backdrop-filter: blur(4px);
}

.photo-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-auto-rows: minmax(0, 1fr);
  gap: 6px;
  min-height: 0;
}

.photo-tile {
