.photo-tile img { width: 100%; height: 100%; object-fit: cover; display: block; transition: opacity .15s ease; }

.photo-hero:hover img, .photo-tile:hover img { opacity: .86; }

.photo-more img { opacity: .5; }

.photo-more-label {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 13px;
  font-weight: 600;
