/* TrackName — styles owned by TrackName.tsx.
   Split out of styles/global.scss; imported once from TrackName.tsx and
   still plain global class names (this app uses no CSS modules). */

/* Track name that opens the track's own site in a new tab. */
.track-link { display: inline-flex; align-items: center; gap: 5px; }

.track-link svg { flex: 0 0 auto; opacity: 0.45; }

.track-link:hover { color: var(--text); text-decoration: underline; text-underline-offset: 3px; }

.track-link:hover svg { opacity: 1; }

.track-site { color: var(--muted); display: inline-flex; }

.track-site:hover { color: var(--text); }

import { Link } from 'react-router-dom';
import './TrackName.scss';

/**
 * A track's name in a table cell.
 *
 * Two shapes:
 *  - With `to` (the network directory): the name is an internal link to that
 *    track's profile page, and the venue's own site stays beside it as the
 *    external-link glyph — the profile is the hub, the site is one of its links.
 *  - Without `to` (operator log, history, perks, admin): the name itself is the
 *    link out to the track's site, as before.
 *
 * A track with no site on file renders as plain text in either shape.
 */
function ExternalLinkIcon() {
  return (
    <svg
      width="12"
      height="12"
      viewBox="0 0 12 12"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.4"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M5 3H3.5A1.5 1.5 0 0 0 2 4.5v4A1.5 1.5 0 0 0 3.5 10h4A1.5 1.5 0 0 0 9 8.5V7" />
      <path d="M7 2h3v3" />
      <path d="M6.2 5.8 10 2" />
    </svg>
  );
}

export default function TrackName({
  name,
  website,
  to,
}: {
  name: string;
  website?: string | null;
  /** Route to the track's own profile page — the directory passes it. */
  to?: string;
}) {
  if (!to) {
    if (!website) return <>{name}</>;
    return (
      <a
        className="track-link"
        href={website}
        target="_blank"
        rel="noopener noreferrer"
        title={`${name}: opens their site in a new tab`}
      >
        {name}
        <ExternalLinkIcon />
      </a>
    );
  }

  return (
    <>
      <Link className="track-name-link" to={to} title={`${name}: track profile`}>
        {name}
      </Link>
      {website && (
        <a
          className="track-site"
          href={website}
          target="_blank"
          rel="noopener noreferrer"
          title={`${name}: opens their site in a new tab`}
        >
          <ExternalLinkIcon />
        </a>
      )}
    </>
  );
}

/* TrackPanel — styles owned by TrackPanel.tsx.
   Split out of styles/global.scss; imported once from TrackPanel.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The picked venue's inspector: the photograph as the card's masthead with the
   close on its corner, then the venue, the pass's terms there, and the track's
   own links. It floats over the map's right edge, so the rail it was picked
   from stays where it was. */
.track-panel { position: relative; gap: 0; }

.track-close {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 3;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  padding: 0;
  color: var(--text);
  background: color-mix(in srgb, var(--bg) 76%, transparent);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.track-close:hover { opacity: 1; border-color: var(--muted); }

.track-close:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }

/* The phone's way out: the same corner, the same action, drawn as a back arrow
   because the inspector is standing where the list was. Hidden on the canvas,
   where `.track-close` owns the corner. */
.track-back {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 3;
  display: none;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  color: var(--text);
  background: color-mix(in srgb, var(--bg) 76%, transparent);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.track-back:hover { opacity: 1; border-color: var(--muted); }

.track-back:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }

@media (max-width: 900px) {
  .track-close { display: none; }
  .track-back { display: grid; }
}

.track-panel-photo {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border-radius: var(--radius);
  background: var(--bg-3);
}

.track-panel-body { gap: 8px; }

/* The body carries its own rhythm — `.stack` spaces by margin-top, not gap, so
   the page-wide 20px landed on the children without an explicit margin reset
   (where the venue is, the note under the facts) and the panel alternated
   27px / 7px / 7px / 27px. One value here makes it even. */
.track-panel-body > * + * { margin-top: 10px; }

.track-panel-body h2 { margin: 0; font-size: 19px; letter-spacing: -0.01em; }

/* The city / state line keeps its own 5px under the venue name. */
.track-panel .track-panel-body > .small.muted.track-panel-place { margin-top: 5px; }

/* The venue's name and the follow toggle share one row: the control rides
   the right edge of the head, so following a track reads as acting on the
   venue by name rather than as a stray button at the panel's foot. */
.track-panel-head { display: flex; align-items: center; gap: 10px; }

.track-panel-head h2 { min-width: 0; }

/* The venue's name in the head is the second door into its profile, so it
   wears the app's quiet name link rather than the h2's plain ink — no
   underline in the panel either way, the hover colour is the only cue. */
.track-panel-head h2 .track-name-link { text-decoration: none; }

.track-panel-head h2 .track-name-link:hover { text-decoration: none; }

/* The venue's gate read sits under its name and place, on the block's left
   edge — a fact about the venue, not a peer of the follow control on the head
   row. The cluster must not stretch, and the two pills keep their own tighter
   gap. */
.track-panel-status { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; width: fit-content; }

.track-panel-status .status-pill { flex: 0 0 auto; }

/* Tight to the place line above it — name, where it is and its status read as
   one block — so it overrides the body's 10px rhythm. */
.track-panel-body > .track-panel-status { margin-top: 8px; }

.track-panel-head .follow-toggle { flex: 0 0 auto; margin-left: auto; }

/* 30px of air above the week: the venue and where it is read as one block,
   and the hours sit clearly below it. */
.track-panel-hours { margin-top: 30px; }

/* The week's card, in the panel's 356px: the day column tightens and the rows
   lose a little of the profile's air so seven lines stay a block rather than a
   second scroll. Today's row drops back to the plain day/value pair — the panel
   head owns the status pill, so no third column is needed here. */
.track-panel-hours .hours-row th {
  /* 92px, not 52: the day label carries its date ("Wed (11/04)"). */
  width: 92px;
}

.track-panel-hours .hours-row th,
.track-panel-hours .hours-row td { padding: 4px 6px; }

.track-panel-hours h3 { margin-bottom: 6px; }

.track-panel-actions { gap: 10px; }

.track-panel-links { gap: 8px; }

/* The socials ride as glyphs, pushed to the row's right edge, so the one text
   button (the venue's profile) starts the line and the row never wraps at the
   panel's 356px. Same 1px frame as the text button, squared off to the glyph. */
.track-panel-socials { margin-left: auto; gap: 8px; flex: 0 0 auto; }

@media (max-width: 900px) {
  .track-panel-socials { margin-left: 0; }
}

import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';
import FollowButton from '../FollowButton/FollowButton';
import type { Entitlement } from '../DaysByTrack/DaysByTrack';
import HoursWeek from '../HoursWeek/HoursWeek';
import { useAuth } from '../../lib/auth';
import type { TrackPerk } from '../../lib/trackOffers';
import { TRACK_STATUS_CLASS, statusLabel, type MapTrack } from '../../lib/trackAccess';
import './TrackPanel.scss';

/**
 * What one partner track is, from the rider's seat: the venue, where it is and
 * the week it runs, then the days the pass leaves there — before the ways out:
 * the track's own profile, site and feeds. It rides over the map's right edge
 * as the picked venue's inspector,
 * beside the rail the pick came from — the list is never swapped out for it —
 * so the × is the way back to the bare map rather than to a list.
 */
export default function TrackPanel({
  track,
  gated = false,
  lapsed = false,
  onClose,
  onFollow,
}: {
  track: MapTrack;
  /** The rail's per-track entitlement: still accepted so its call site stays as
   *  it was, but the panel no longer prints a day ledger. */
  ent: Entitlement | undefined;
  /** The track's perks and whether the pass is active: still accepted from the
   *  rail so its call site stays as it was, but the panel no longer reads the
   *  offers off them. */
  perks: TrackPerk[];
  active: boolean;
  /** Free tier or a lapsed pass: the pass's own terms are withheld, so hide the
   *  day facts. */
  gated?: boolean;
  /** The terms are missing because the pass on this account has expired, not
   *  because the tier does not carry them — the note below says which. */
  lapsed?: boolean;
  /** Put the inspector away. */
  onClose: () => void;
  /** Reports the follow toggle up to the rail that renders this panel. */
  onFollow?: (trackId: string, following: boolean) => void;
}) {
  const { user } = useAuth();
  const where = [track.city, track.region].filter(Boolean).join(', ');
  // The full week, not a one-line summary: the panel prints the profile's own
  // Hours card, so a rider reads the days they are planning around here.
  // Following is a rider action — an operator owns a venue rather than
  // following it, so the control never renders for one.

  // The ways out, after the profile: the venue's own site and feeds ride as
  // icon buttons so the row stays one line at the panel's 356px. Each keeps its
  // name as the anchor's label — for a screen reader, and as the tooltip.
  const links: { label: string; href: string; icon: ReactNode }[] = [];
  if (track.website)
    links.push({
      label: 'Website',
      href: track.website,
      icon: (
        /* The link mark on a 24 grid: the panel's icon square scales it to 16px,
           where strokeWidth 2 reads the same weight as the feeds' 1.4. */
        <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
          <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" />
            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" />
          </g>
        </svg>
      ),
    });
  if (track.instagram)
    links.push({
      label: 'Instagram',
      href: track.instagram,
      icon: (
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          <rect x="1.9" y="1.9" width="12.2" height="12.2" rx="3.6" fill="none" stroke="currentColor" strokeWidth="1.4" />
          <circle cx="8" cy="8" r="3" fill="none" stroke="currentColor" strokeWidth="1.4" />
          <circle cx="11.85" cy="4.15" r="0.95" fill="currentColor" />
        </svg>
      ),
    });
  if (track.facebook)
    links.push({
      label: 'Facebook',
      href: track.facebook,
      icon: (
        <svg viewBox="0 0 16 16" aria-hidden="true" focusable="false">
          {/* The wordmark's own path is taller than the two line glyphs beside
              it, so it is scaled into the same optical box. */}
          <path d="M9.9 15V8.7h2.1l.35-2.5H9.9V4.6c0-.72.2-1.21 1.23-1.21h1.32V1.15A17.6 17.6 0 0 0 10.53 1C8.62 1 7.32 2.16 7.32 4.3v1.9H5.2v2.5h2.12V15z"
            fill="currentColor" transform="translate(0.27 0.96) scale(0.88)" />
        </svg>
      ),
    });

  return (
    <section className="stack track-panel">
      {/* Two ways out, one action: on the desktop canvas this is the × on the
          photograph's corner (the list stays beside it), while on a phone the
          inspector has replaced the list, so the same control reads as a back
          arrow and says where it goes. */}
      <button type="button" className="track-close" onClick={onClose} aria-label="Close the venue details">
        <svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true">
          <path d="M3.2 3.2l7.6 7.6M10.8 3.2l-7.6 7.6" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
      </button>
      <button type="button" className="track-back" onClick={onClose} aria-label="Back to the track list">
        <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true">
          <path d="M8.3 2.6L3.9 7l4.4 4.4" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>

      {track.imageUrl && <img className="track-panel-photo" src={track.imageUrl} alt="" />}

      <div className="stack track-panel-body">
        <div className="row track-panel-head">
          {/* The name is the second way into the venue's own profile — the
              head reads as the venue, so clicking it should go where the
              Track profile button goes. */}
          <h2>
            <Link
              className="track-name-link"
              to={`/tracks/${track.slug}`}
              title={`${track.name}: track profile`}
            >
              {track.name}
            </Link>
          </h2>
          {/* The name and the follow control only: the gate read lives under
              the venue's place line, not on this row. */}
          {/* Following belongs to a rider account: a visitor gets the panel
              without it, and so does an operator. */}
          {user && user.role === 'RIDER' && (
            <FollowButton
              trackId={track.id}
              name={track.name}
              following={Boolean(track.following)}
              onChange={(f) => onFollow?.(track.id, f)}
              compact
            />
          )}
        </div>
        {where && <div className="small muted track-panel-place">{where}</div>}

        {/* Today's gate, and tomorrow's when the operator has scheduled it —
            the read sits under the venue's name and place on the block's left
            edge: it is a fact about the venue, not a peer of the follow
            control on the head row. */}
        {(track.status !== 'WEATHER_HOLD' || track.tomorrowStatus) && (
          <div className="track-panel-status">
            {/* A weather hold prints no pill: the amber 'Caution' read is noise
                on the panel, and the rail's gate light carries the same word. */}
            {track.status !== 'WEATHER_HOLD' && (
              <span className={`status-pill ${TRACK_STATUS_CLASS[track.status] ?? 'status-open'}`}>
                {statusLabel(track.status)}
              </span>
            )}
            {track.tomorrowStatus && (
              <span className={`status-pill ${TRACK_STATUS_CLASS[track.tomorrowStatus.status] ?? 'status-open'}`}>
                Tomorrow · {statusLabel(track.tomorrowStatus.status)}
              </span>
            )}
          </div>
        )}

        {/* The operator's own word to riders — a standing note about the venue
            (gate times, parking, a work day) rather than today's gate read, so
            it rides on its own line above the facts whenever they left one. The
            venue's day-status note is not repeated here: the head's status pill
            and the rail's gate light both carry it. */}
        {track.riderMessage && (
          <div className="operator-message">
            <span className="muted">From the operator</span>
            <p className="small">{track.riderMessage}</p>
          </div>
        )}

        {/* The venue's whole week: the same Hours card the venue profile prints,
            every day listed with the reader's own day marked. The live status
            already rides the head, so the week prints without its pill. */}
        <div className="track-panel-hours">
          <HoursWeek week={track.hoursWeek ?? null} summary={track.hours} />
        </div>

        {gated && lapsed && (
          <div className="small muted">
            No active pass this season. Included days and member discounts come with a paid pass.
          </div>
        )}
      </div>

      <div className="stack track-panel-actions">
        <div className="row wrap track-panel-links">
          <Link className="track-links-btn" to={`/tracks/${track.slug}`}>
            Track profile
          </Link>
          {links.length > 0 && (
            <div className="row track-panel-socials">
              {links.map((l) => (
                <a
                  key={l.label}
                  className="track-links-btn track-links-icon"
                  href={l.href}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={l.label}
                  title={l.label}
                >
                  {l.icon}
                </a>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

/* TrackReviews — styles owned by TrackReviews.tsx.
   Split out of styles/global.scss; imported once from TrackReviews.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The review composer on the venue page: the stars, the account, the frames.
   A rider writes one review per venue and edits that same one afterwards. */
.track-reviews { gap: 12px; }

/* The rider's own review is edited from the section head, right of the title.
   Defined here rather than reused from the operator console's sheet (that page
   owns `.section-tools` in its own chunk, which never loads on a venue page). */
.track-reviews .section-tools {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}

.track-reviews-callout {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  border: 1px dashed var(--line);
  border-radius: 8px;
  padding: 10px 12px;
}

.track-reviews-callout p { margin: 0; flex: 1 1 220px; }

/* The composer is a modal now — it rides the app's own `.sheet-backdrop` +
   `.sheet` chrome (see TrackReviews.tsx), so the form body keeps only its grid
   and the sheet supplies the surface. */
.track-reviews-sheet { width: min(560px, 100%); }

.track-reviews-form {
  display: grid;
  gap: 10px;
}

.track-reviews-rating { display: flex; align-items: center; gap: 10px; }

.track-reviews-stars { display: flex; gap: 2px; }

.track-reviews-stars button {
  padding: 0 2px;
  border: 0;
  background: none;
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  color: var(--line);
}

.track-reviews-stars button.on { color: var(--accent); }

.track-reviews-body {
  width: 100%;
  resize: vertical;
  font: inherit;
  color: var(--text);
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 8px 10px;
}

.track-reviews-attach-row,
.track-reviews-actions-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.track-reviews-pick {
  display: inline-flex;
  align-items: center;
  padding: 7px 12px;
  border: 1px dashed var(--line);
  border-radius: 6px;
  font-size: 0.82rem;
  color: var(--muted);
  cursor: pointer;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.track-reviews-pick:hover { border-color: var(--accent); color: var(--text); }

.track-reviews-pick input { display: none; }

.track-reviews-keep { display: grid; gap: 6px; }

.track-reviews-keep-row { display: flex; gap: 8px; flex-wrap: wrap; }

.track-reviews-keep-item {
  position: relative;
  display: grid;
  gap: 4px;
  width: 84px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 4px;
  cursor: pointer;
  font-size: 0.7rem;
}

.track-reviews-keep-item.off { opacity: 0.45; }

.track-reviews-keep-item img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: 4px;
}

.track-reviews-keep-item input { position: absolute; top: 4px; right: 4px; }

/* A card that has frames raises the viewer on click — the pointer says so, and
   the whole card is the target, not just the thumbnails. */
.track-review-card.is-openable { cursor: zoom-in; }

.track-review-card.is-openable:hover { border-color: var(--muted); }

.track-review-card.is-openable:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* The card a link from elsewhere in the app landed on: a ring on the accent for
   a moment after the scroll settles, so a review with no frames to raise still
   reads as the one the reader asked for. */
.track-review-card.is-target,
.track-review-card.is-target:hover {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

/* The review's own card inside the viewer, laid over the bottom-right of the
   frame: the rider, the date, the stars, and the account they wrote. It is
   glass over the photo so the picture still reads around it. */
.lightbox-review {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, .14);
  border-radius: 10px;
  background: rgba(10, 12, 16, .86);
  backdrop-filter: blur(12px);
  box-shadow: 0 14px 40px rgba(0, 0, 0, .5);
  /* It arrives a beat after the frame: a short fade with a few pixels of rise,
     nothing that draws the eye away from the photo. */
  animation: lightbox-review-in .22s ease-out both;
}

@keyframes lightbox-review-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .lightbox-review { animation: none; }
}

.lightbox-review-head {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.lightbox-review-face {
  width: 32px;
  height: 32px;
  border-radius: 6px;
  object-fit: cover;
  flex: 0 0 auto;
}

.lightbox-review-who { display: grid; min-width: 0; }

.lightbox-review-who b { font-size: .92rem; }

.lightbox-review-who .tiny {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lightbox-review .track-review-stars { font-size: .85rem; }

/* Long accounts scroll inside the card rather than growing past the photo. */
.lightbox-review-body {
  margin: 0;
  font-size: .86rem;
  line-height: 1.5;
  white-space: pre-line;
  max-height: min(38vh, 320px);
  overflow: auto;
  overscroll-behavior: contain;
}

import { useEffect, useRef, useState } from 'react';
import Avatar from '../Avatar/Avatar';
import PhotoLightbox from '../PhotoLightbox/PhotoLightbox';
import { api } from '../../lib/api';
import { cleanMultilineDraft } from '../../lib/sanitize';
import './TrackReviews.scss';

/** One frame attached to a review. */
export interface ReviewPhoto {
  id: string;
  url: string;
  caption: string | null;
}

/** A rider's review of a venue, as `/tracks/:slug` returns it. */
export interface TrackReview {
  id: string;
  rating: number;
  body: string;
  createdAt: string;
  updatedAt: string;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
  photos: ReviewPhoto[];
}

/** The frame a review is opened on in the lightbox. */
interface Viewing {
  review: TrackReview;
  index: number;
}

const MAX_PHOTOS = 6;

/** The DOM id a review's card wears, so a link elsewhere in the app
 *  (`/tracks/:slug?review=<id>`) has something to scroll to. */
const reviewAnchorId = (reviewId: string) => `review-${reviewId}`;

/** Put a review's card in the middle of the screen — the landing a
 *  `?review=<id>` link asks for, one scroll of the window. */
function centreReview(reviewId: string) {
  document.getElementById(reviewAnchorId(reviewId))?.scrollIntoView({ block: 'center' });
}

/** Centre a card and keep it there while the page finishes laying out. The
 *  frames above a review arrive after the first scroll (a cold visit has them
 *  still to load), and every one that lands pushes the card down again. The
 *  observer watches the page's height rather than ticking on a timer, so a
 *  reader who scrolls away by hand is not dragged back. */
function holdOnReview(reviewId: string, ms = 2200) {
  centreReview(reviewId);
  const started = Date.now();
  const ro = new ResizeObserver(() => {
    if (Date.now() - started > ms) {
      ro.disconnect();
      return;
    }
    centreReview(reviewId);
  });
  ro.observe(document.documentElement);
  window.setTimeout(() => ro.disconnect(), ms + 50);
}

/** Five stars, the filled ones picking the rating. */
function Stars({ rating }: { rating: number }) {
  return (
    <span className="track-review-stars" aria-label={`${rating} out of 5`}>
      {[1, 2, 3, 4, 5].map((n) => (
        <span key={n} aria-hidden className={n <= rating ? 'on' : 'off'}>
          ★
        </span>
      ))}
    </span>
  );
}

/**
 * A review's own card inside the viewer: the rider, when they wrote it, the
 * stars they gave the place, and the account itself. It sits over the frame so
 * the picture and the words that belong to it are read together.
 */
function ReviewAside({ review }: { review: TrackReview }) {
  const edited = review.updatedAt !== review.createdAt;
  return (
    <div className="lightbox-review">
      <div className="lightbox-review-head">
        <Avatar src={review.riderAvatarUrl} name={review.riderName} className="lightbox-review-face" />
        <div className="lightbox-review-who">
          <b>{review.riderName}</b>
          <span className="tiny muted">
            {new Date(review.createdAt).toLocaleDateString()}
            {edited ? ' · edited' : ''}
          </span>
        </div>
        <Stars rating={review.rating} />
      </div>
      {review.body && <p className="lightbox-review-body">{review.body}</p>}
    </div>
  );
}

/** Read a picked file into a base64 data URL. */
function readFile(file: File): Promise<string> {
  return new Promise((resolve) => {
    const fr = new FileReader();
    fr.onload = () => resolve(String(fr.result));
    fr.onerror = () => resolve('');
    fr.readAsDataURL(file);
  });
}

/**
 * The riders' side of a venue's page: their reviews of the place — the account
 * they wrote, the stars they gave it, and the frames they shot there.
 *
 * This is the counterpart to the venue's own gallery above it: the gallery is
 * the owner's curated art, this is the crowd's considered account. A signed-in
 * rider writes **one** review per venue and then edits that same review — its
 * words, its stars, and the photos attached to it — from the same card. Everyone
 * else reads. The venue can pull a review from its own community page.
 */
export default function TrackReviews({
  trackId,
  trackName,
  reviews,
  onChange,
  onMessage,
  onRefresh,
  currentUserId,
  openReviewId,
}: {
  trackId: string;
  trackName: string;
  reviews: TrackReview[];
  onChange: (reviews: TrackReview[]) => void;
  /** A line for the page's notice. `ok` is true for a confirmation — it floats
   *  and retires on its own — and false (default) for a refusal, which the
   *  caller keeps up longer. */
  onMessage: (msg: string, ok?: boolean) => void;
  /** Re-read the page after an edit, so the frames and the counts agree with
   *  the server without the component rebuilding the whole review by hand. */
  onRefresh?: () => void | Promise<void>;
  /** The signed-in rider, when there is one — decides the form and the edit
   *  control on their own review. */
  currentUserId?: string;
  /** A review to land on, named by the link the reader followed (the rider's
   *  own profile passes `?review=<id>` through). */
  openReviewId?: string | null;
}) {
  const fileRef = useRef<HTMLInputElement>(null);
  const sheetRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [rating, setRating] = useState(5);
  const [body, setBody] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [keep, setKeep] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [viewing, setViewing] = useState<Viewing | null>(null);
  /* The card the reader was sent to, held under a ring for a moment after they
     land, so a review with no photos still shows where the link pointed. */
  const [flashId, setFlashId] = useState<string | null>(null);
  /* One landing per id: a re-render (an edit refreshing the list) must not
     re-open the viewer or re-scroll the page. */
  const landed = useRef<string | null>(null);

  const mine = reviews.find((r) => r.userId === currentUserId);

  /* The rider's own profile links here naming one review. The page fetches the
     venue first, so this waits for the review to arrive, centers that card, and
     raises the viewer when the review carries frames to show. Instant, not
     smooth: the viewer is about to take the screen, so a scroll still running
     underneath it would be interrupted half way. The frames above the card are
     still loading on a cold visit, so a words-only review (nothing to raise,
     so the scroll is the whole landing) is re-centred as the page settles. */
  useEffect(() => {
    if (!openReviewId || landed.current === openReviewId) return;
    const target = reviews.find((r) => r.id === openReviewId);
    if (!target) return;
    landed.current = openReviewId;
    holdOnReview(target.id);
    if (target.photos.length > 0) setViewing({ review: target, index: 0 });
    setFlashId(target.id);
    const timer = window.setTimeout(() => setFlashId(null), 2600);
    return () => window.clearTimeout(timer);
  }, [openReviewId, reviews]);

  // Open the composer pre-filled with the review this rider already wrote.
  useEffect(() => {
    if (!open) return;
    setRating(mine?.rating ?? 5);
    setBody(mine?.body ?? '');
    setFiles([]);
    setKeep(mine?.photos.map((p) => p.id) ?? []);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  /* The composer opens as a modal now: the panel takes focus once so the
     keyboard starts inside it, and Escape puts the whole thing away. A click on
     the backdrop does the same (on the backdrop, not the sheet). */
  useEffect(() => {
    if (!open) return;
    sheetRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open]);

  const pickFiles = (list: FileList | null) => {
    const next = Array.from(list ?? []);
    const room = MAX_PHOTOS - (mine ? keep.length : 0);
    setFiles(next.slice(0, Math.max(0, room)));
  };

  const save = async () => {
    const trimmed = body.trim();
    if (!trimmed && !files.length && !(mine && keep.length)) {
      onMessage('Write a few words or attach a photo before posting.');
      return;
    }
    setBusy(true);
    try {
      const dataUrls: string[] = [];
      for (const file of files) {
        const dataUrl = await readFile(file);
        if (!dataUrl) {
          onMessage('Could not read one of those files.');
          return;
        }
        dataUrls.push(dataUrl);
      }

      if (!mine) {
        const res = await api.post<{ review: TrackReview }>('/me/track-reviews', {
          trackId,
          rating,
          body: trimmed,
          dataUrls,
        });
        if (!res.success || !res.data?.review) {
          onMessage(res.message ?? 'Could not post your review.');
          return;
        }
        onChange([res.data.review, ...reviews]);
        setOpen(false);
        onMessage('Review posted.', true);
        return;
      }

      // An edit: the words and stars first, then the frames added and removed.
      const res = await api.patch<{ review: TrackReview }>(`/me/track-reviews/${mine.id}`, {
        rating,
        body: trimmed,
      });
      if (!res.success) {
        onMessage(res.message ?? 'Could not update your review.');
        return;
      }

      const removed = mine.photos.filter((p) => !keep.includes(p.id));
      for (const photo of removed) {
        const del = await api.del(`/me/track-reviews/${mine.id}/photos/${photo.id}`);
        if (!del.success) {
          onMessage(del.message ?? 'Could not remove one of your photos.');
          return;
        }
      }
      for (const dataUrl of dataUrls) {
        const add = await api.post(`/me/track-reviews/${mine.id}/photos`, { dataUrl });
        if (!add.success) {
          onMessage(add.message ?? 'Could not add one of your photos.');
          return;
        }
      }

      setOpen(false);
      onMessage('Review updated.', true);
      if (onRefresh) await onRefresh();
    } finally {
      setBusy(false);
      if (fileRef.current) fileRef.current.value = '';
    }
  };

  const allPhotos = (review: TrackReview) =>
    review.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption }));

  const cards = reviews.map((review) => {
    const isMine = currentUserId === review.userId;
    const edited = review.updatedAt !== review.createdAt;
    // Only a review with frames has something to raise into the viewer; one
    // that is words alone stays a card and opens nothing.
    const openable = review.photos.length > 0;
    return (
      <li
        key={review.id}
        id={reviewAnchorId(review.id)}
        className={`track-review-card${openable ? ' is-openable' : ''}${flashId === review.id && !isMine ? ' is-target' : ''}`}
        onClick={openable ? () => setViewing({ review, index: 0 }) : undefined}
        onKeyDown={
          openable
            ? (e) => {
                // Only the card itself, not the buttons inside it.
                if (e.target !== e.currentTarget) return;
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault();
                  setViewing({ review, index: 0 });
                }
              }
            : undefined
        }
        role={openable ? 'button' : undefined}
        tabIndex={openable ? 0 : undefined}
        aria-label={openable ? `Open ${review.riderName}'s review and photos` : undefined}
      >
        <div className="track-review-head">
          <Avatar src={review.riderAvatarUrl} name={review.riderName} className="track-review-face" />
          <div className="track-review-who">
            <b>{review.riderName}</b>
            <span className="tiny muted">
              {new Date(review.createdAt).toLocaleDateString()}
              {edited ? ' · edited' : ''}
            </span>
          </div>
          <Stars rating={review.rating} />
        </div>

        {review.body && <p className="track-review-body">{review.body}</p>}

        {review.photos.length > 0 && (
          <div className="track-review-shots">
            {review.photos.map((photo, i) => (
              <button
                key={photo.id}
                type="button"
                className="track-review-shot"
                onClick={(e) => {
                  // The frame opens on itself, not on the card's first frame.
                  e.stopPropagation();
                  setViewing({ review, index: i });
                }}
                aria-label={photo.caption || `Photo by ${review.riderName}`}
              >
                <img src={photo.url} alt={photo.caption || `${trackName} by ${review.riderName}`} loading="lazy" />
              </button>
            ))}
          </div>
        )}

      </li>
    );
  });

  return (
    <section className="card stack track-reviews">
      <div className="section-head">
        <h3>Reviews{reviews.length > 1 ? ` (${reviews.length})` : ''}</h3>
        {/* The rider's own review is edited from here, not from the card: the
            one review they get on this venue is a property of the section, and
            the card below stays pure reading. The composer itself is a modal. */}
        {currentUserId && mine && (
          <div className="section-tools">
            <button type="button" className="small" onClick={() => setOpen(true)}>
              Edit your review
            </button>
          </div>
        )}
      </div>

      {currentUserId && !mine && !open && (
        <div className="track-reviews-callout">
          <p className="small muted">Ridden here? Write the one review you get on this venue.</p>
          <button type="button" className="primary small" onClick={() => setOpen(true)}>
            Write a review
          </button>
        </div>
      )}

      {currentUserId && open && (
        <div className="sheet-backdrop" onClick={() => setOpen(false)}>
          <div
            className="sheet track-reviews-sheet"
            role="dialog"
            aria-modal="true"
            aria-labelledby="track-reviews-sheet-title"
            tabIndex={-1}
            ref={sheetRef}
            onClick={(e) => e.stopPropagation()}
          >
            <h4 className="sheet-title" id="track-reviews-sheet-title">
              {mine ? 'Edit your review' : 'Write a review'}
            </h4>
            <div className="track-reviews-form">
              <div className="track-reviews-rating">
                <span className="small muted">Your rating</span>
                <div className="track-reviews-stars" role="radiogroup" aria-label="Rating out of five">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button
                      key={n}
                      type="button"
                      role="radio"
                      aria-checked={rating === n}
                      aria-label={`${n} star${n === 1 ? '' : 's'}`}
                      className={n <= rating ? 'on' : 'off'}
                      onClick={() => setRating(n)}
                    >
                      ★
                    </button>
                  ))}
                </div>
              </div>

              <textarea
                className="track-reviews-body"
                value={body}
                onChange={(e) => setBody(cleanMultilineDraft(e.target.value, 2000))}
                placeholder="How was the track? Prep, layout, the crew, the day."
                maxLength={2000}
                rows={4}
                aria-label="Your review"
              />

              {mine && keep.length > 0 && (
                <div className="track-reviews-keep">
                  <span className="small muted">Photos on your review</span>
                  <div className="track-reviews-keep-row">
                    {mine.photos.map((photo) => (
                      <label key={photo.id} className={`track-reviews-keep-item${keep.includes(photo.id) ? '' : ' off'}`}>
                        <img src={photo.url} alt={photo.caption || 'Your photo'} />
                        <input
                          type="checkbox"
                          checked={keep.includes(photo.id)}
                          onChange={(e) =>
                            setKeep((prev) =>
                              e.target.checked ? [...prev, photo.id] : prev.filter((id) => id !== photo.id)
                            )
                          }
                        />
                        <span className="tiny">{keep.includes(photo.id) ? 'Keep' : 'Remove'}</span>
                      </label>
                    ))}
                  </div>
                </div>
              )}

              <div className="track-reviews-attach-row">
                <label className="track-reviews-pick">
                  <input
                    ref={fileRef}
                    type="file"
                    multiple
                    accept="image/png,image/jpeg,image/webp,image/gif,image/avif"
                    onChange={(e) => pickFiles(e.target.files)}
                  />
                  {files.length
                    ? `${files.length} photo${files.length === 1 ? '' : 's'} chosen`
                    : 'Attach photos'}
                </label>
                <span className="tiny muted">
                  {keep.length + files.length}/{MAX_PHOTOS} photos
                </span>
              </div>

              <div className="track-reviews-actions-row">
                <button type="button" className="primary small" onClick={save} disabled={busy}>
                  {busy ? 'Saving…' : mine ? 'Save changes' : 'Post review'}
                </button>
                <button type="button" className="small" onClick={() => setOpen(false)} disabled={busy}>
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {reviews.length === 0 ? (
        <div className="small muted">
          No rider reviews here yet.
          {currentUserId ? ' Yours would be the first.' : ' Sign in to write one from a day at the track.'}
        </div>
      ) : (
        <ul className="track-reviews-list">{cards}</ul>
      )}

      {viewing && (
        <PhotoLightbox
          photos={allPhotos(viewing.review)}
          name={trackName}
          index={viewing.index}
          onIndex={(i) => setViewing({ review: viewing.review, index: i })}
          onClose={() => {
            /* The viewer's scroll lock collapses the window's offset, and the
               viewer puts it back on the way out; centring the card afterwards
               is what makes the landing exact — the frames above it were still
               arriving when the first scroll ran. */
            const closingId = viewing.review.id;
            setViewing(null);
            requestAnimationFrame(() => holdOnReview(closingId));
          }}
          // Read the review off the current props, not the snapshot the card
          // opened on, so an edit made while the viewer is up shows through.
          aside={<ReviewAside review={reviews.find((r) => r.id === viewing.review.id) ?? viewing.review} />}
        />
      )}
    </section>
  );
}

import { useEffect, useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import { api } from '../lib/api';
import { useAuth } from '../lib/auth';

/**
 * The persistent upgrade path for a rider on the free (default) tier.
 *
 * The tier is not on `/auth/me` — the pass is its own read, and the shell needs
 * it on every route, so this asks `/me/pass` itself rather than threading the
 * pass through the auth context (which the account menu also fetches on open).
 * The read is keyed on the route: an in-app checkout lands on `/tracks` without
 * a full page load, and a stale read would leave the link up after an upgrade.
 * Staff and signed-out visitors never query it.
 */
export default function UpgradeLink() {
  const { user } = useAuth();
  const { pathname } = useLocation();
  const [free, setFree] = useState(false);

  const rider = user?.role === 'RIDER';

  useEffect(() => {
    if (!rider) {
      setFree(false);
      return;
    }
    let live = true;
    api
      .get<{ pass: { tier: { isDefault: boolean } } | null }>('/me/pass')
      .then((r) => {
        if (live) setFree(Boolean(r.data?.pass?.tier?.isDefault));
      });
    return () => {
      live = false;
    };
  }, [rider, pathname]);

  if (!rider || !free) return null;

  return (
    <NavLink to="/pricing" className="small upgrade-link">
      Upgrade
    </NavLink>
  );
}

/* UpgradeWelcome — the welcome a paid pass opens on the return trip from
   checkout. Styles owned by UpgradeWelcome.tsx: it reuses the app's sheet
   chrome and only widens it. Plain class names (this app uses no CSS modules);
   this sheet loads after styles/global.scss. */

/* Wider than the app's 420px default, so the two lines breathe. */
.upgrade-welcome {
  width: min(560px, 100%);
  padding: 22px;
}

.upgrade-welcome .sheet-title { margin: 0 0 9px; font-size: 19px; }

/* The one quiet line under the title: what the pass is valid through. */
.upgrade-meta {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.upgrade-meta strong { color: var(--text); font-weight: 600; }

/* The secondary link sits at the far left of the action row, the one control
   that moves the rider on at the right. */
.upgrade-actions {
  align-items: center;
  justify-content: space-between;
  margin-top: 22px;
}

import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { Link } from 'react-router-dom';
import './UpgradeWelcome.scss';

/** A long, unambiguous date; UTC so a late-evening return trip cannot land a
 *  day early. */
function longDate(d: string | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toLocaleDateString(undefined, {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

/**
 * The welcome a paid pass opens: shown once, on the return trip from checkout,
 * in place of the toast that used to carry the confirmation. Two lines only —
 * the name of the pass and the date it is valid through — with the perks link
 * and one action to move the rider on. The full terms live on the pass itself.
 *
 * Escape or a click on the backdrop closes it. Portalled to the body so the
 * header's backdrop-filter cannot trap it, and so it sits above the map panes
 * (the same reason PassQrSheet portals).
 */
export default function UpgradeWelcome({
  tierName,
  expiresAt,
  onClose,
}: {
  tierName: string;
  expiresAt: string | null;
  onClose: () => void;
}) {
  const panel = useRef<HTMLDivElement>(null);

  /* Focus lands on the panel once, when the sheet opens — its own effect, with
     no dependency. `onClose` is a fresh arrow every render of the page, so
     folding this into the listener below re-ran it on every keystroke and
     pulled the cursor back out to the panel: one character in, the rest of the
     typing went nowhere. */
  useEffect(() => {
    panel.current?.focus();
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return createPortal(
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet upgrade-welcome"
        role="dialog"
        aria-modal="true"
        aria-labelledby="upgrade-welcome-title"
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id="upgrade-welcome-title">
          Welcome to the {tierName}
        </h2>
        <p className="upgrade-meta">
          Pass valid through <strong>{longDate(expiresAt)}</strong>
        </p>

        <div className="sheet-actions upgrade-actions">
          <Link className="inline small" to="/tracks/perks" onClick={onClose}>
            See the perks on your pass
          </Link>
          <button className="primary" onClick={onClose}>
            Let's go
          </button>
        </div>
      </div>
    </div>,
    document.body,
  );
}

/* VenueLocation — styles owned by VenueLocation.tsx.
   Split out of styles/global.scss; imported once from VenueLocation.tsx and
   still plain global class names (this app uses no CSS modules). */

/* ---- Location & Hours on the venue profile --------------------------------
   The venue on a map, the week it runs beside it, and a narrow card of the ways
   to reach the place. No heading of its own — the map and the week answer for
   themselves. The town the venue is reached at opens that card, so the place
   sits with the ways in rather than under the map. The whole block is boxed: one
   hairline around all of it, with room inside the border on every side. */
.loc { border: 1px solid var(--line); border-radius: var(--radius-lg); padding: 24px; }

.loc-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: 24px;
}

/* The hours and the ways in share the right-hand column, stacked in one rail —
   the week over the contact card — so the map is the only thing beside them. */
.loc-side { display: grid; gap: 18px; align-content: start; }

/* Leaflet measures its container, so the map's box is the left column's own
   height: it takes whatever the rail beside it needs and keeps the two columns
   ending together, with a floor for the one-venue frame. The map's own material
   (tiles, controls, dark tile filter) comes from .map-dark. */
.loc-where { height: 100%; }

/* The contact card: a row per way in, a hairline between them, the row's icon
   on the right. */
.loc-card { display: grid; }

.loc-row { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 12px 0; }

.loc-row + .loc-row { border-top: 1px solid var(--line); }

.loc-row:first-child { padding-top: 0; }

.loc-row:last-child { padding-bottom: 0; }

.loc-link { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 600; color: var(--text); }

.loc-link:hover { text-decoration: underline; text-underline-offset: 3px; }

.loc-ico { display: inline-flex; color: var(--muted); }

.loc-sub { display: grid; gap: 3px; min-width: 0; }

.loc-label { font-size: 14px; font-weight: 700; color: var(--text); }

.loc-line { font-size: 13px; line-height: 1.45; color: var(--muted); }

/* The social row: bare marks, one per venue feed, since the marks are what a
   rider reads at 18px — the name stays on the anchor for a screen reader and
   as the tooltip. */
.loc-socials { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 14px; }

.loc-socials a { display: inline-flex; align-items: center; color: var(--muted); }

.loc-socials a:hover { color: var(--text); }

/* The directions row's control: copy the address. */
.loc-acts { display: flex; align-items: center; gap: 8px; }

.loc-ico-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.loc-ico-btn { color: var(--muted); cursor: pointer; }

.loc-ico-btn:hover { color: var(--text); border-color: var(--muted); }

.loc-ico-btn.is-copied { color: var(--ok); border-color: var(--ok); }

/* One column: the map, then the rail of ways in and hours under it, in a box
     that gives up some of its padding to the phone's width. */
@media (max-width: 760px) {
  .loc { padding: 16px 14px; }
}

@media (max-width: 760px) {
  .loc-grid { grid-template-columns: 1fr; gap: 18px; }
}

import { Suspense, lazy, useRef, useState } from 'react';
import Banner from '../Banner/Banner';
import HoursWeek from '../HoursWeek/HoursWeek';
import type { HoursWeek as Week } from '../../lib/hoursWeek';
import './VenueLocation.scss';

const VenueMap = lazy(() => import('../VenueMap'));

/**
 * The venue's Location & Hours block: where it is, when it runs, and the ways
 * to reach it — read off the fields the venue keeps on file and nothing else.
 *
 * Two columns: the venue on its map, then the ways to reach it with the week it
 * runs stacked beneath, so the contacts and the hours read as one rail beside
 * the map. Everything a rider reads off the venue (where it is, how to reach
 * it) is in one column.
 *
 * The directions row carries the venue's full published street address, with a
 * button that copies it — that pair is the whole point of the row, since a rider
 * on a phone wants the address in their maps app, not the venue's homepage. What
 * "on file and nothing else" means: the address is the venue's own published
 * line when the row has one and the city and region when it does not, the map is
 * drawn from the coordinates, and the card lists only the contacts that exist —
 * a venue with a website gets that row, one with a phone gets that row, and one
 * with neither gets neither rather than a blank line.
 */
export interface VenueLocationTrack {
  name: string;
  city: string | null;
  region: string | null;
  /** The venue's published street address, when it keeps one on file. */
  address: string | null;
  country?: string | null;
  lat: number | null;
  lng: number | null;
  website: string | null;
  instagram: string | null;
  facebook: string | null;
  youtube: string | null;
  tiktok: string | null;
  email: string | null;
  phone: string | null;
  status: string;
  hours: string | null;
  hoursWeek: Week | null;
}

/** The site without its scheme, so the row reads as the place's address online. */
function siteLabel(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return url.replace(/^https?:\/\//, '').replace(/\/+$/, '');
  }
}

function ExternalGlyph() {
  return (
    <svg width="14" height="14" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M5 3H3.5A1.5 1.5 0 0 0 2 4.5v4A1.5 1.5 0 0 0 3.5 10h4A1.5 1.5 0 0 0 9 8.5V7" />
      <path d="M7 2h3v3" />
      <path d="M6.2 5.8 10 2" />
    </svg>
  );
}

function PhoneGlyph() {
  return (
    <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M3 2.5h2.2l1.1 2.6-1.3 1a8.2 8.2 0 0 0 4.9 4.9l1-1.3 2.6 1.1V13a1 1 0 0 1-1.1 1A11.5 11.5 0 0 1 2 3.6 1 1 0 0 1 3 2.5Z" />
    </svg>
  );
}

function MailGlyph() {
  return (
    <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="2" y="3.5" width="12" height="9" rx="1.2" />
      <path d="m2.6 4.6 5.4 4 5.4-4" />
    </svg>
  );
}

/** Two offset sheets — the copy-the-address mark. */
function CopyGlyph() {
  return (
    <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="5.5" y="2.5" width="8" height="9" rx="1.2" />
      <path d="M10.5 13.5H3.7a1.2 1.2 0 0 1-1.2-1.2V5.5" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="m3.5 8.4 3 3 6-6.8" />
    </svg>
  );
}

/** How long the copy button says it copied for, in ms. */
const COPIED_MS = 1600;
/** How long the copy confirmation stays in the toast corner. A confirmation the
 *  reader has already seen on the button, so it retires at the stack's default. */
const COPY_TOAST_MS = 4000;

/** The social marks: same 1.7 stroke weight at 18px as the footer's row, so
 *  the card's ways out read at a glance next to the text rows above them. */
function InstagramGlyph() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <rect x="3.5" y="3.5" width="17" height="17" rx="5" stroke="currentColor" strokeWidth="1.7" />
      <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="1.7" />
      <circle cx="16.8" cy="7.2" r="1.1" fill="currentColor" />
    </svg>
  );
}

function FacebookGlyph() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      {/* Solid f — a stroked variant turned to mush at 18px. */}
      <path
        d="M15.6 8.3h2.2V5.6h-2.4c-2.3 0-3.7 1.4-3.7 3.6v1.8H9.4v2.7h2.3V21h2.9v-7.3h2.3l.4-2.7h-2.7V9.5c0-.8.4-1.2 1-1.2Z"
        fill="currentColor"
      />
    </svg>
  );
}

function YouTubeGlyph() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <rect x="2.8" y="6" width="18.4" height="12" rx="3.4" stroke="currentColor" strokeWidth="1.7" />
      <path d="M10.6 9.6 15 12l-4.4 2.4V9.6Z" fill="currentColor" />
    </svg>
  );
}

function TikTokGlyph() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path
        d="M14.3 3h2.3c.2 1.9 1.4 3.2 3.3 3.4v2.4a6.4 6.4 0 0 1-3.3-.9v5.7a4.9 4.9 0 1 1-4.9-4.9c.3 0 .5 0 .8.1v2.5a2.5 2.5 0 1 0 1.8 2.4V3Z"
        fill="currentColor"
      />
    </svg>
  );
}

/** One row per venue: the mark's name, its icon, and the field it reads. */
const SOCIALS: {
  key: keyof VenueLocationTrack;
  label: string;
  glyph: () => JSX.Element;
}[] = [
  { key: 'instagram', label: 'Instagram', glyph: InstagramGlyph },
  { key: 'facebook', label: 'Facebook', glyph: FacebookGlyph },
  { key: 'youtube', label: 'YouTube', glyph: YouTubeGlyph },
  { key: 'tiktok', label: 'TikTok', glyph: TikTokGlyph },
];

export default function VenueLocation({ track }: { track: VenueLocationTrack }) {
  const [copied, setCopied] = useState(false);
  /* The copy confirmation, floated in the toast corner. `id` counts the notices:
     copying twice says the same sentence twice, and the Banner keys on the id so
     the second one is a fresh toast rather than the retired first. */
  const noticeSeq = useRef(0);
  const [copyNote, setCopyNote] = useState<{ id: number; text: string } | null>(null);

  const where = [track.city, track.region].filter(Boolean).join(', ');
  const country = track.country && track.country !== 'US' ? track.country : '';
  // The full address the row prints and copies: the venue's own published line,
  // or the city and region it does keep on file. Never a made-up street.
  const fullAddress = track.address?.trim() || [where, country].filter(Boolean).join(' ');
  const hasFix = track.lat != null && track.lng != null;
  const socials = SOCIALS.map((s) => ({ ...s, url: track[s.key] })).filter(
    (s): s is typeof s & { url: string } => typeof s.url === 'string' && s.url.length > 0
  );

  /**
   * Copying goes through the async clipboard when the page has one. Served over
   * plain http (a phone on the tailnet, say) it does not, so the selection trick
   * is the fallback — the button has to work wherever the app is served from.
   */
  const copyAddress = async () => {
    try {
      await navigator.clipboard.writeText(fullAddress);
    } catch {
      const scratch = document.createElement('textarea');
      scratch.value = fullAddress;
      scratch.setAttribute('readonly', '');
      scratch.style.position = 'fixed';
      scratch.style.top = '-1000px';
      scratch.style.opacity = '0';
      document.body.appendChild(scratch);
      scratch.select();
      try {
        document.execCommand('copy');
      } catch {
        /* nothing else to try — the button simply reports nothing was copied */
      }
      document.body.removeChild(scratch);
    }
    setCopied(true);
    setCopyNote({ id: ++noticeSeq.current, text: 'Address copied to clipboard' });
    window.setTimeout(() => setCopied(false), COPIED_MS);
  };

  return (
    <section className="stack loc" aria-label="Location and hours">
      <div className="loc-grid">
        <div className="loc-where">
          {hasFix ? (
            <Suspense fallback={<div className="loc-map muted small" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>Loading map…</div>}>
              <VenueMap name={track.name} lat={track.lat as number} lng={track.lng as number} />
            </Suspense>
          ) : (
            <div className="loc-map loc-map-blank small muted">No coordinates on file</div>
          )}
        </div>

        {/* The contact card and the week share one column — the ways in sit over
            the hours, so only the map stands beside them. */}
        <div className="loc-side">
          <div className="card loc-card">
            {track.website && (
              <div className="loc-row">
                <a className="loc-link" href={track.website} target="_blank" rel="noopener noreferrer">
                  {siteLabel(track.website)}
                </a>
                <span className="loc-ico">
                  <ExternalGlyph />
                </span>
              </div>
            )}

            {track.phone && (
              <div className="loc-row">
                <a className="loc-link" href={`tel:${track.phone.replace(/[^\d+]/g, '')}`}>
                  {track.phone}
                </a>
                <span className="loc-ico">
                  <PhoneGlyph />
                </span>
              </div>
            )}

            {track.email && (
              <div className="loc-row">
                <a className="loc-link" href={`mailto:${track.email}`}>
                  {track.email}
                </a>
                <span className="loc-ico">
                  <MailGlyph />
                </span>
              </div>
            )}

            <div className="loc-row">
              <span className="loc-sub">
                <span className="loc-label">Get Directions</span>
                {fullAddress && <span className="loc-line">{fullAddress}</span>}
              </span>
              <span className="loc-acts">
                {fullAddress && (
                  <button
                    type="button"
                    className={copied ? 'loc-ico-btn is-copied' : 'loc-ico-btn'}
                    onClick={copyAddress}
                    title={copied ? 'Address copied' : 'Copy the address'}
                    aria-label={copied ? 'Address copied' : 'Copy the address'}
                  >
                    {copied ? <CheckGlyph /> : <CopyGlyph />}
                  </button>
                )}
              </span>
            </div>

            {socials.length > 0 && (
              <div className="loc-row">
                <span className="loc-socials">
                  {socials.map(({ label, url, glyph: Glyph }) => (
                    <a
                      key={label}
                      href={url}
                      target="_blank"
                      rel="noopener noreferrer"
                      title={label}
                      aria-label={`${track.name} on ${label}`}
                    >
                      <Glyph />
                    </a>
                  ))}
                </span>
              </div>
            )}

          </div>

          <div className="loc-week">
            <HoursWeek week={track.hoursWeek} summary={track.hours} status={track.status} />
          </div>
        </div>
      </div>

      {/* The copy's outcome, floated in the corner where every other confirmation
          lands. Keyed to the event so a second copy is a fresh toast. */}
      {copyNote && (
        <Banner key={copyNote.id} tone="ok" floating close ms={COPY_TOAST_MS}>
          {copyNote.text}
        </Banner>
      )}
    </section>
  );
}

import { useEffect, useRef } from 'react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { venuePin } from '../lib/trackAccess';
import { US_BOUNDS, US_MIN_ZOOM } from '../lib/usMap';

/**
 * One venue on a map of its own, for the profile's Location & Hours block: a
 * single dot in the venue's own colour, centred on the coordinates on file.
 *
 * There is no network and no rider pin here — the venue is the whole map — so it
 * opens close in rather than framing the country. The wheel is left to the page
 * (an embedded map that swallows the scroll is a trap); the drag, the zoom
 * buttons and the venue's name on hover all still work.
 */
export default function VenueMap({
  name,
  lat,
  lng,
}: {
  name: string;
  lat: number;
  lng: number;
}) {
  const el = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);

  useEffect(() => {
    if (!el.current || mapRef.current) return;
    const c = venuePin();
    const map = L.map(el.current, {
      center: [lat, lng],
      zoom: 12,
      minZoom: US_MIN_ZOOM,
      maxBounds: US_BOUNDS,
      maxBoundsViscosity: 1.0,
      scrollWheelZoom: false,
      attributionControl: true,
      zoomControl: true,
    });
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      subdomains: 'abc',
      referrerPolicy: 'origin',
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    }).addTo(map);

    // The same dot the network map draws, mixed to 85% the same way, so the
    // venue's colour is one read across both maps.
    const safe = name.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
    const mk = L.marker([lat, lng], {
      icon: L.divIcon({
        className: 'map-pin-wrap',
        html:
          `<span class="map-pin-dot" data-name="${safe}" ` +
          `style="background:color-mix(in srgb, ${c.bg} 85%, transparent)"></span>`,
        iconSize: [0, 0],
        iconAnchor: [0, 0],
      }),
      riseOnHover: true,
      alt: name,
    });
    mk.bindTooltip(name, { direction: 'top', offset: [0, -11], className: 'map-tip', opacity: 1 });
    mk.addTo(map);
    mapRef.current = map;

    const t = setTimeout(() => map.invalidateSize(), 200);
    return () => {
      clearTimeout(t);
      map.remove();
      mapRef.current = null;
    };
  }, [name, lat, lng]);

  return <div ref={el} className="map-dark loc-map" aria-label={`${name} on the map`} />;
}

/* WeekGrid — styles owned by WeekGrid.tsx.
   Split out of styles/global.scss; imported once from WeekGrid.tsx and
   still plain global class names (this app uses no CSS modules). */

/* ── The week grid (components/WeekGrid.tsx) ──────────────────────────────
   One surface: a day-head row, an all-day row, then the hours. Eight grid
   columns — the hours gutter and seven days — so a day column is the same
   width as the head above it and the all-day chip below it. A date is drawn
   where its own hours put it; a run across days reads in the all-day row.
   Kind colours are the only colour here, and none of them is the accent: an
   amber ride day must not read as a picked one. */
.wk {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--bg-2);
  overflow: hidden;
}

.wk-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 12px;
  border-bottom: 1px solid var(--line);
}

.wk-range { font-size: 13px; }

.wk-grid {
  display: grid;
  grid-template-columns: 62px repeat(7, minmax(0, 1fr));
}

/* The day head: the weekday over its number, the number filled when it is
   today. It is a button — picking a day is how the week's cards narrow. */
.wk-dow {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 4px 7px;
  background: none;
  border: 0;
  /* A head is a cell of the grid, not a control: the button base's radius would
     round the highlight's top corners off the column edge. */
  border-radius: 0;
  border-bottom: 1px solid var(--line);
  border-left: 1px solid var(--line);
  color: var(--muted);
  cursor: pointer;
}

.wk-dow:hover { color: var(--text); }

.wk-dow-name { font-size: 10px; letter-spacing: 0.06em; }

.wk-dow-num {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  border-radius: 50%;
  color: var(--text);
}

.wk-dow.has-event .wk-dow-num { background: var(--bg-3); }

/* Today is not a circle on the number: the head of the column carries the
   highlight, brighter than the tint that already runs down the day, with the
   accent on its top edge. */
.wk-dow.is-today {
  background-color: rgba(var(--accent-rgb), 0.1);
  box-shadow: inset 0 2px 0 var(--accent);
  color: var(--text);
}

/* A date's grey chip would read as the circle this replaced, so today's own
   number stays plain — the head is the mark. */
.wk-dow.is-today .wk-dow-num { background: none; }

.wk-dow.is-picked .wk-dow-num { box-shadow: 0 0 0 2px rgba(var(--accent-rgb), 0.45); }

.wk-corner { border-bottom: 1px solid var(--line); }

.wk-allday-label {
  padding: 8px 8px 0;
  font-size: 10px;
  letter-spacing: 0.06em;
  white-space: nowrap;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
}

.wk-allday-cell {
  display: grid;
  align-content: start;
  gap: 3px;
  min-height: 38px;
  padding: 5px 4px 6px;
  border-bottom: 1px solid var(--line);
  border-left: 1px solid var(--line);
}

/* The head's tint has to carry through the all-day row, or the highlight
   breaks in the middle of today's column. */
.wk-allday-cell.is-today { background-color: rgba(var(--accent-rgb), 0.03); }

/* An all-day date: a ring in its kind's colour, then the title. The ring is
   the whole point — the row has no hours to place it with. */
.wk-aday {
  --evk: var(--evk-practice);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 6px;
  border: 0;
  border-radius: 4px;
  background: rgba(var(--evk), 0.14);
  color: var(--text);
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  overflow: hidden;
}

.wk-aday:hover { background: rgba(var(--evk), 0.24); }

.wk-aday-ring {
  flex: none;
  width: 7px;
  height: 7px;
  border: 2px solid rgb(var(--evk));
  border-radius: 50%;
}

.wk-aday-title { min-width: 0; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.wk-aday-kind { flex: none; margin-left: auto; font-size: 10px; color: var(--muted); }

/* The hours gutter: a label a line, right-aligned against the day columns. */
.wk-times { position: relative; }

.wk-time {
  position: absolute;
  right: 8px;
  padding-top: 3px;
  font-size: 10px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

.wk-col {
  position: relative;
  border-left: 1px solid var(--line);
  /* One hairline an hour; the height is the hour and the count is the window,
     both handed in by the component so the two can never disagree. */
  background-image: linear-gradient(var(--line) 0 1px, transparent 1px);
  background-repeat: repeat-y;
}

.wk-col.is-today { background-color: rgba(var(--accent-rgb), 0.03); }

.wk-chip {
  --evk: var(--evk-practice);
  position: absolute;
  left: 2px;
  right: 5px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px 6px;
  border: 0;
  /* A date's kind rides its own left edge — the one bar the reference earns:
     a timed block needs a colour at its head to read as a kind, not a tint. */
  border-left: 3px solid rgb(var(--evk));
  border-radius: 4px;
  background: rgba(var(--evk), 0.16);
  color: var(--text);
  text-align: left;
  overflow: hidden;
  cursor: pointer;
}

.wk-chip:hover { background: rgba(var(--evk), 0.26); }

.wk-chip-title { font-size: 11.5px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.wk-chip-time { font-size: 10px; color: var(--muted); font-variant-numeric: tabular-nums; }

.wk-chip.is-hidden { opacity: 0.55; }

/* A slot marked on the week and not posted yet: the owner picks an empty hour,
   then moves the block — dragged by its body, ends dragged to set the hours. It
   is an outline, not a kind — nothing is on the calendar until the sheet is
   saved — so the accent here reads as "being written", which no date ever does. */
.wk-slot {
  position: absolute;
  left: 2px;
  right: 5px;
  z-index: 3;
  border: 1px dashed rgba(var(--accent-rgb), 0.7);
  border-left: 3px solid var(--accent);
  border-radius: 4px;
  background: rgba(var(--accent-rgb), 0.13);
}

.wk-slot.is-dragging {
  border-color: var(--accent);
  background: rgba(var(--accent-rgb), 0.2);
}

/* The crosshair over the column says the whole column is taking the mark. */
.wk-col.is-dragging { cursor: ns-resize; }

/* Carrying the block is the other gesture: the hand stays closed across the
   whole column, so the pointer never reads as though it were resizing. */
.wk-col.is-carrying { cursor: grabbing; }

.wk-slot-body {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
  /* Top-aligned like a date's own chip: the hours read beside the end of the
     block the owner just set, not in the middle of it. */
  padding: 5px 6px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--text);
  text-align: left;
  /* The body is the handle that carries the block, so it reads as grabbable and
     never lets the page scroll out from under the drag. */
  cursor: grab;
  touch-action: none;
  overflow: hidden;
}

.wk-slot.is-carrying .wk-slot-body { cursor: grabbing; }

.wk-slot-time {
  font-size: 10.5px;
  font-weight: 600;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.wk-slot-add { font-size: 10px; color: var(--muted); }

/* The two ends. Each sits a couple of pixels proud of the slot so the pointer
   finds it without covering the hours between; the bar is only drawn once the
   slot is under the pointer, so a marked hour stays quiet until it is worked. */
.wk-slot-grip {
  position: absolute;
  left: 0;
  right: 0;
  height: 9px;
  cursor: ns-resize;
  touch-action: none;
}

.wk-slot-grip.is-top { top: -4px; }

.wk-slot-grip.is-bottom { bottom: -4px; }

.wk-slot-grip::after {
  content: '';
  position: absolute;
  left: 50%;
  width: 18px;
  height: 3px;
  border-radius: 2px;
  background: var(--accent);
  transform: translateX(-50%);
  opacity: 0;
}

.wk-slot-grip.is-top::after { top: 3px; }

.wk-slot-grip.is-bottom::after { bottom: 3px; }

.wk-slot:hover .wk-slot-grip::after,
.wk-slot-grip:hover::after,
.wk-slot.is-dragging .wk-slot-grip::after { opacity: 1; }

.kind-practice { --evk: var(--evk-practice); }

.kind-race { --evk: var(--evk-race); }

.kind-clinic { --evk: var(--evk-clinic); }

.kind-ride_day { --evk: var(--evk-ride_day); }

.kind-other { --evk: var(--evk-other); }

/* Now: a hairline down today's own column with a dot on its head. It is the
   reader's clock, so it only draws when today is one of the days on screen. */
.wk-now {
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--accent);
  z-index: 2;
}

.wk-now::before {
  content: '';
  position: absolute;
  left: -3px;
  top: -3px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
}

/* Seven day columns cannot read on a phone, so the band scrolls sideways
     with the day heads and columns intact rather than crushing the chips. */
@media (max-width: 860px) {
  .wk { overflow-x: auto; }
}

@media (max-width: 860px) {
  .wk-grid { min-width: 660px; }
}

@media (max-width: 860px) {
  .wk-aday-kind { display: none; }
}

/* The venue on a chip, on its own line under the hours. A short gate clips it
   the same way the hours clip — the chip is a block on an hour grid, not a
   card that can grow. */
.wk-chip-venue { font-size: 10px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.wk-aday-venue { min-width: 0; font-size: 10px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

import { useEffect, useRef, useState } from 'react';
import type { ProfileEvent } from '../../lib/events';
import {
  EVENT_KIND_LABEL,
  ampmLabel,
  ampmTime,
  daysOf,
  isTimed,
  weekDays,
  weekStart,
} from '../../lib/events';
import './WeekGrid.scss';

/**
 * A week of the venue's season as a time grid: an all-day row over an hour
 * grid, one column a day, a date drawn where its own hours put it.
 *
 * It keeps no state of its own — whoever draws it owns the week it is showing,
 * the way `MonthGrid` owns its month — so the owner's calendar page is the only
 * thing that decides what "now" and "picked" mean. A chip is the control for
 * the date it draws — a click on one opens that date, never the day it sits
 * on — while the day header over a column is what picks a day for the page.
 *
 * Everything here is UTC about *days* (a date sits on the day its `startsAt`
 * falls on, so a Saturday never slides to Friday) and local about the *clock*
 * (the now-line is the reader's own time). Do not mix the two.
 *
 * It draws a read as readily as an edit: the page that writes hands in the
 * three slot controls, and a page that only reads leaves them off — nothing on
 * a column then takes a mark and no slot is ever drawn. `venueOf` names the
 * venue on every chip, for a week that holds more than one.
 *
 * A marked slot is worked three ways: the body dragged to move the whole block
 * — along its own day or onto another column, its length kept — and either end
 * dragged to change one time. A body that only took a click opens the sheet.
 */
const HOUR_H = 46;
const GUTTER_FROM = 8 * 60;
const GUTTER_TO = 20 * 60;

/** A slot is marked on the quarter hour, and never shorter than half of one. */
const SLOT_SNAP = 15;
const SLOT_MIN = 30;

/** The hours the owner has marked on the grid but not yet posted. */
export interface SlotDraft {
  day: string;
  start: number;
  end: number;
}

export type SlotEdge = 'start' | 'end';

/** The nearest quarter hour, so a drag lands on a time a venue would name. */
const snapTo = (minutes: number) => Math.round(minutes / SLOT_SNAP) * SLOT_SNAP;

interface Props {
  /** The venue's whole season — the grid picks the week's own dates out of it. */
  events: ProfileEvent[];
  /** Any day of the week on screen; its Monday is the column the week starts on. */
  anchor: string;
  today: string;
  picked: string | null;
  /**
   * The slot the owner has marked out, if any — a stretch of one day's clock
   * the page holds while the date is being written.
   */
  slot?: SlotDraft | null;
  onStep: (weeks: number) => void;
  onToday: () => void;
  onPickDay: (day: string) => void;
  /** A date's own chip was clicked: open that date, not the day under it. */
  onPickEvent: (ev: ProfileEvent) => void;
  /**
   * The venue a date belongs to, when a column can hold more than one — a
   * rider's calendar draws every track they follow, so a chip has to say where
   * it is. The owner's own page has one venue and nothing to say. */
  venueOf?: (ev: ProfileEvent) => string | null;
  /**
   * The three writing controls. Leave them off and the grid is a read: no hour
   * of a column takes a mark, and no slot is ever drawn — which is how the
   * rider's calendar reads the owner's own week without an editor behind it.
   */
  /** An empty hour of a column was clicked: mark that slot off. */
  onSelectSlot?: (day: string, start: number, end: number) => void;
  /** A slot's edge was dragged: the new minute it landed on, already clamped. */
  onResizeSlot?: (edge: SlotEdge, minutes: number) => void;
  /**
   * The slot's body was dragged: the day it landed on and the start it slid to,
   * its own length kept — the block moves as one, so the two times are never
   * named apart.
   */
  onMoveSlot?: (day: string, start: number, end: number) => void;
  /** The slot's own body was clicked: open the fields for it. */
  onOpenSlot?: () => void;
}

const rangeLabel = (monday: string, sunday: string) => {
  const a = new Date(`${monday}T12:00:00Z`);
  const b = new Date(`${sunday}T12:00:00Z`);
  const monthDay = (d: Date) =>
    d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', timeZone: 'UTC' });
  return `${monthDay(a)} – ${monthDay(b)}, ${b.getUTCFullYear()}`;
};

export default function WeekGrid({
  events,
  anchor,
  today,
  picked,
  slot = null,
  onStep,
  onToday,
  onPickDay,
  onPickEvent,
  venueOf,
  onSelectSlot,
  onResizeSlot,
  onMoveSlot,
  onOpenSlot,
}: Props) {
  const monday = (() => {
    return weekStart(anchor);
  })();
  const days = weekDays(monday);
  const week = days.map((d) => d.key);

  /** The week's dates, each on every day it covers, so a chip lands on its day. */
  const byDay = new Map<string, ProfileEvent[]>();
  for (const ev of events) {
    for (const k of daysOf(ev)) {
      if (!week.includes(k)) continue;
      const list = byDay.get(k);
      if (list) list.push(ev);
      else byDay.set(k, [ev]);
    }
  }
  const inWeek = [...new Set(week.flatMap((k) => byDay.get(k) ?? []))].sort((a, b) =>
    a.startsAt.localeCompare(b.startsAt)
  );

  // The window the grid draws: wide enough for the week's own hours, never
  // narrower than a working day, and never off the clock. A marked slot is
  // held inside it while it is dragged, so the window never moves under the
  // pointer mid-drag.
  const timed = inWeek.filter(isTimed);
  const from = Math.max(
    0,
    Math.min(GUTTER_FROM, ...timed.map((e) => Math.floor((e.startMinutes ?? 0) / 60) * 60))
  );
  const to = Math.min(
    24 * 60,
    Math.max(
      GUTTER_TO,
      ...timed.map((e) => Math.ceil((e.endMinutes ?? 0) / 60) * 60)
    )
  );
  const hours = Array.from({ length: (to - from) / 60 + 1 }, (_, i) => from + i * 60);

  const span = (to - from) / 60;
  const top = (minutes: number) => ((minutes - from) / 60) * HOUR_H;

  // The now-line is the reader's own clock, and it only appears when today is
  // one of the columns — a hairline with no column under it reads as a mistake.
  const now = new Date();
  const nowMin = now.getHours() * 60 + now.getMinutes();
  const nowOn = week.includes(today) && nowMin > from && nowMin < to;

  /**
   * The edge being dragged, with the column's own top and the far edge it has
   * to stay clear of — read once on the way down, so the mapping from the
   * pointer to a minute never shifts while the drag is running.
   */
  const [drag, setDrag] = useState<{ edge: SlotEdge; colTop: number; other: number } | null>(null);
  const resize = useRef(onResizeSlot);
  resize.current = onResizeSlot;

  /**
   * The marked block being carried, if any. Read once on the way down — the
   * columns it may land on, the gap between the pointer and the block's own
   * start, the length it keeps — so nothing about the mapping shifts under the
   * pointer while the drag is running.
   */
  const [move, setMove] = useState(false);
  const carrying = useRef<{
    day: string;
    colTop: number;
    cols: { day: string; left: number; right: number }[];
    offset: number;
    dur: number;
    downX: number;
    downY: number;
    moved: boolean;
  } | null>(null);
  const moveSlot = useRef(onMoveSlot);
  moveSlot.current = onMoveSlot;

  /**
   * When a grip was last taken hold of, or a block last carried. Lifting the
   * pointer off either can land the click on the column underneath, which would
   * mark a fresh slot where the gesture ended — so a click arriving on the
   * heels of one is ignored.
   */
  const gripAt = useRef(0);

  /**
   * When the block was last carried anywhere. A carry ends in a click on the
   * body it was carried by, which must not also open the sheet — only a body
   * that stayed where it was put is the control that opens the fields.
   */
  const carriedAt = useRef(0);

  useEffect(() => {
    if (!drag) return;
    const move = (e: PointerEvent) => {
      const raw = from + ((e.clientY - drag.colTop) / HOUR_H) * 60;
      const at = snapTo(raw);
      if (drag.edge === 'start') {
        resize.current?.('start', Math.max(from, Math.min(at, drag.other - SLOT_MIN)));
      } else {
        resize.current?.('end', Math.min(to, Math.max(at, drag.other + SLOT_MIN)));
      }
    };
    const up = () => setDrag(null);
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up);
    window.addEventListener('pointercancel', up);
    return () => {
      document.body.style.userSelect = '';
      window.removeEventListener('pointermove', move);
      window.removeEventListener('pointerup', up);
      window.removeEventListener('pointercancel', up);
    };
  }, [drag, from, to]);

  /**
   * Carrying the marked block. The minute under the pointer is read against the
   * column's own top, snapped to the quarter hour, and the block is held inside
   * the drawn window with its length kept; the column the pointer is over names
   * the day, so the block crosses to another day mid-drag. Nothing is handed
   * over until the pointer has actually travelled a few pixels, so a sloppy
   * click on the body still opens the sheet instead of nudging the slot.
   */
  useEffect(() => {
    if (!move) return;
    const at = (e: PointerEvent) => {
      const c = carrying.current;
      if (!c) return;
      if (!c.moved) {
        if (Math.abs(e.clientX - c.downX) + Math.abs(e.clientY - c.downY) < 4) return;
        c.moved = true;
      }
      const raw = from + ((e.clientY - c.colTop) / HOUR_H) * 60;
      const start = Math.max(from, Math.min(snapTo(raw - c.offset), Math.max(from, to - c.dur)));
      const over = c.cols.find((col) => e.clientX >= col.left && e.clientX < col.right);
      moveSlot.current?.(over?.day ?? c.day, start, start + c.dur);
    };
    const up = () => {
      // The gesture was a carry, not a click: the sheet stays shut.
      if (carrying.current?.moved) {
        carriedAt.current = Date.now();
        gripAt.current = Date.now();
      }
      carrying.current = null;
      setMove(false);
    };
    document.body.style.userSelect = 'none';
    window.addEventListener('pointermove', at);
    window.addEventListener('pointerup', up);
    window.addEventListener('pointercancel', up);
    return () => {
      document.body.style.userSelect = '';
      window.removeEventListener('pointermove', at);
      window.removeEventListener('pointerup', up);
      window.removeEventListener('pointercancel', up);
    };
  }, [move, from, to]);

  /** The column's empty hours are the control: a click marks off that hour —
   *  on a page that writes. A read-only week has no mark to take. */
  const selectAt = (e: React.MouseEvent<HTMLDivElement>, day: string) => {
    if (!onSelectSlot) return;
    // A date's own chip, or the slot already marked, answers its own clicks.
    if ((e.target as HTMLElement).closest('.wk-chip, .wk-slot, .wk-now')) return;
    if (Date.now() - gripAt.current < 300) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const at = snapTo(from + ((e.clientY - rect.top) / HOUR_H) * 60);
    const start = Math.max(from, Math.min(at, to - 60));
    onSelectSlot(day, start, Math.min(start + 60, to));
  };

  const beginDrag = (e: React.PointerEvent<HTMLSpanElement>, edge: SlotEdge) => {
    if (!slot) return;
    const col = e.currentTarget.closest('.wk-col') as HTMLElement | null;
    if (!col) return;
    e.preventDefault();
    e.stopPropagation();
    gripAt.current = Date.now();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setDrag({
      edge,
      colTop: col.getBoundingClientRect().top,
      other: edge === 'start' ? slot.end : slot.start,
    });
  };

  /**
   * The block itself was taken hold of. The pointer's own minute at the moment
   * down is what the block's start is measured against, so it never jumps under
   * the hand; the columns are read here, once, since none of them moves while
   * the block is being carried.
   */
  const beginMove = (e: React.PointerEvent<HTMLButtonElement>) => {
    if (!slot || !onMoveSlot) return;
    const block = e.currentTarget.closest('.wk-slot') as HTMLElement | null;
    const grid = block?.closest('.wk-grid') as HTMLElement | null;
    if (!block || !grid) return;
    e.preventDefault();
    e.stopPropagation();
    gripAt.current = Date.now();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    const colTop = grid.getBoundingClientRect().top;
    carrying.current = {
      day: slot.day,
      colTop,
      cols: ([...grid.querySelectorAll('.wk-col')] as HTMLElement[]).map((el, i) => {
        const r = el.getBoundingClientRect();
        return { day: week[i], left: r.left, right: r.right };
      }),
      offset: from + ((e.clientY - colTop) / HOUR_H) * 60 - slot.start,
      dur: slot.end - slot.start,
      downX: e.clientX,
      downY: e.clientY,
      moved: false,
    };
    setMove(true);
  };

  const slotTall = slot ? top(slot.end) - top(slot.start) >= 44 : false;

  return (
    <div className="wk">
      <div className="wk-bar">
        <button className="cal-nav" onClick={() => onStep(-1)} aria-label="Previous week">
          ‹
        </button>
        <b className="wk-range">{rangeLabel(monday, days[6].key)}</b>
        <button className="cal-nav" onClick={() => onStep(1)} aria-label="Next week">
          ›
        </button>
        <button className="ghost small wk-today" onClick={onToday}>
          Today
        </button>
      </div>

      <div className="wk-grid" style={{ ['--wk-hours' as string]: String(span) }}>
        <div className="wk-corner" aria-hidden="true" />

        {days.map(({ key, dow, d }) => (
          <button
            key={key}
            type="button"
            className={[
              'wk-dow',
              key === today ? 'is-today' : '',
              key === picked ? 'is-picked' : '',
              (byDay.get(key)?.length ?? 0) > 0 ? 'has-event' : '',
            ]
              .filter(Boolean)
              .join(' ')}
            aria-pressed={key === picked}
            onClick={() => onPickDay(key)}
          >
            <span className="wk-dow-name">{dow}</span>
            <span className="wk-dow-num">{d.getUTCDate()}</span>
          </button>
        ))}

        <div className="wk-allday-label">All day</div>
        {days.map(({ key }) => (
          <div key={key} className={`wk-allday-cell${key === today ? ' is-today' : ''}`}>
            {(byDay.get(key) ?? [])
              .filter((ev) => !isTimed(ev))
              .map((ev) => (
                <button
                  key={ev.id}
                  type="button"
                  className={`wk-aday kind-${ev.kind.toLowerCase()}`}
                  title={`${venueOf?.(ev) ? `${venueOf(ev)} — ` : ''}${ev.title}: ${EVENT_KIND_LABEL[ev.kind] ?? ev.kind}`}
                  onClick={() => onPickEvent(ev)}
                >
                  <span className="wk-aday-ring" aria-hidden="true" />
                  <span className="wk-aday-title">{ev.title}</span>
                  {venueOf?.(ev) && <span className="wk-aday-venue">{venueOf(ev)}</span>}
                  <span className="wk-aday-kind">{EVENT_KIND_LABEL[ev.kind] ?? ev.kind}</span>
                </button>
              ))}
          </div>
        ))}

        <div className="wk-times" style={{ height: span * HOUR_H }}>
          {hours.map((m) => (
            <span key={m} className="wk-time" style={{ top: top(m) }}>
              {ampmTime(m)}
            </span>
          ))}
        </div>

        {days.map(({ key }) => (
          <div
            key={key}
            className={`wk-col${key === today ? ' is-today' : ''}${
              (drag && slot?.day === key) || (move && slot?.day === key) ? ' is-dragging' : ''
            }${move && slot?.day === key ? ' is-carrying' : ''}`}
            style={{ height: span * HOUR_H, backgroundSize: `100% ${HOUR_H}px` }}
            onClick={(e) => selectAt(e, key)}
          >
            {key === today && nowOn && (
              <span className="wk-now" style={{ top: top(nowMin) }} aria-hidden="true" />
            )}
            {(byDay.get(key) ?? [])
              .filter(isTimed)
              .map((ev) => {
                const start = ev.startMinutes ?? from;
                const end = Math.max(ev.endMinutes ?? start + 30, start + 30);
                return (
                  <button
                    key={`${ev.id}-${key}`}
                    type="button"
                    className={`wk-chip kind-${ev.kind.toLowerCase()}${ev.isActive === false ? ' is-hidden' : ''}`}
                    style={{ top: top(start), height: Math.max(24, top(end) - top(start)) }}
                    title={`${venueOf?.(ev) ? `${venueOf(ev)} — ` : ''}${ev.title}: ${ampmLabel(ev) ?? ''}`}
                    onClick={() => onPickEvent(ev)}
                  >
                    <span className="wk-chip-title">{ev.title}</span>
                    <span className="wk-chip-time">{ampmLabel(ev)}</span>
                    {venueOf?.(ev) && <span className="wk-chip-venue">{venueOf(ev)}</span>}
                  </button>
                );
              })}

            {/* The slot marked off but not posted yet: an outline rather than a
                kind — nothing is on the calendar until the fields are saved —
                with a grip at either end to move its hours, and a body that
                carries the whole block to another hour or another day. */}
            {slot && slot.day === key && (
              <div
                className={`wk-slot${drag || move ? ' is-dragging' : ''}${move ? ' is-carrying' : ''}`}
                style={{ top: top(slot.start), height: top(slot.end) - top(slot.start) }}
              >
                <button
                  type="button"
                  className="wk-slot-body"
                  title={
                    onMoveSlot
                      ? 'Drag to another hour or day, or click to name this date'
                      : 'Name this date and add it to the calendar'
                  }
                  onPointerDown={beginMove}
                  onClick={() => {
                    // The click that ends a carry is not the control that opens
                    // the sheet: only a body left where it was put opens it.
                    if (Date.now() - carriedAt.current < 300) return;
                    onOpenSlot?.();
                  }}
                >
                  <span className="wk-slot-time">
                    {ampmTime(slot.start)}–{ampmTime(slot.end)}
                  </span>
                  {slotTall && <span className="wk-slot-add">Add event</span>}
                </button>
                <span
                  className="wk-slot-grip is-top"
                  role="separator"
                  aria-label="Drag to change the start time"
                  onPointerDown={(e) => beginDrag(e, 'start')}
                />
                <span
                  className="wk-slot-grip is-bottom"
                  role="separator"
                  aria-label="Drag to change the end time"
                  onPointerDown={(e) => beginDrag(e, 'end')}
                />
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

const BASE = '/api';

export interface ApiResult<T> {
  success: boolean;
  message: string;
  data?: T;
  pagination?: { page: number; limit: number; total: number; totalPages: number };
  errors?: unknown;
  /** The HTTP status behind the answer, so a caller can tell a refusal from a
      throttle (`429`) without reading the message. */
  status?: number;
  /** `Retry-After` from the server, in milliseconds, when it sent one. */
  retryAfterMs?: number;
}

async function request<T>(path: string, init: RequestInit = {}): Promise<ApiResult<T>> {
  const res = await fetch(`${BASE}${path}`, {
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...(init.headers ?? {}) },
    ...init,
  });
  const text = await res.text();
  let json: ApiResult<T>;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error(`Unexpected response (${res.status})`);
  }
  const retryAfter = Number(res.headers.get('retry-after') ?? '');
  const meta: ApiResult<T> = {
    ...json,
    status: res.status,
    ...(Number.isFinite(retryAfter) && retryAfter > 0 ? { retryAfterMs: retryAfter * 1000 } : {}),
  };
  if (!res.ok && json.success !== false) {
    return { ...meta, success: false, message: `Request failed (${res.status})` };
  }
  return meta;
}

export const api = {
  get: <T>(path: string) => request<T>(path),
  post: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'POST', body: body ? JSON.stringify(body) : undefined }),
  patch: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'PATCH', body: body ? JSON.stringify(body) : undefined }),
  put: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'PUT', body: body ? JSON.stringify(body) : undefined }),
  del: <T>(path: string, body?: unknown) =>
    request<T>(path, { method: 'DELETE', body: body ? JSON.stringify(body) : undefined }),
};

export function money(cents: number | null | undefined): string {
  if (cents == null) return '—';
  return `$${(cents / 100).toFixed(2)}`;
}

/** Integer cents → editable dollar string ("30000" → "300.00"). Null → ''. */
export function centsToInput(cents: number | null | undefined): string {
  return cents == null ? '' : (cents / 100).toFixed(2);
}

/** Editable dollar string → integer cents ("300.00" → 30000). Blank → null. */
export function inputToCents(value: string): number | null {
  return value.trim() === '' ? null : Math.round(Number(value) * 100);
}

export function dayStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toISOString().slice(0, 10);
}

export function dateTimeStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toLocaleString();
}

/** Clock time alone, 24-hour: `09:41` — the gate's read of a timestamp.
    `hourCycle` is pinned so the read never flips to AM/PM by locale. */
export function timeStr(d: string | Date | null | undefined): string {
  if (!d) return '—';
  return new Date(d).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, ReactNode } from 'react';
import { api } from './api';

export type Role = 'RIDER' | 'OPERATOR' | 'ADMIN';

export interface CurrentUser {
  id: string;
  name: string;
  email: string;
  role: Role;
  location: string | null;
  avatarUrl: string | null;
  operatorTrackId: string | null;
}

interface AuthState {
  user: CurrentUser | null;
  operatorTrack: { id: string; name: string; slug: string } | null;
  loading: boolean;
  refresh: () => Promise<void>;
  /** A refusal names its reason; `needsVerification` means the password was
      right and the address is still unconfirmed — the caller sends the rider to
      the confirm step instead of showing a dead end. */
  login: (email: string, password: string) => Promise<LoginResult>;
  /** Signing up does not sign in: it mails the link that makes the account a
      login. `devLink` is only present off production. */
  register: (
    name: string,
    email: string,
    password: string,
    phone?: string
  ) => Promise<RegisterResult>;
  /** Spend a confirmation link. On success the session is already set. */
  verifyEmail: (token: string) => Promise<string | null>;
  resendVerification: (email: string) => Promise<ResendResult>;
  logout: () => Promise<void>;
}

export interface LoginResult {
  error: string | null;
  needsVerification?: boolean;
  email?: string;
}

export interface RegisterResult {
  error: string | null;
  devLink?: string;
  /** The throttle window the just-mailed link opened, for the resend countdown. */
  cooldownMs?: number;
}

export interface ResendResult {
  error: string | null;
  message?: string;
  devLink?: string;
  /** How long the server's per-account throttle will refuse to mail again. */
  cooldownMs?: number;
  /** The answer was the network's ceiling, not the account's: the line is a
      wait, so the card shows it plain instead of as a send that worked. */
  wait?: boolean;
}

const AuthContext = createContext<AuthState | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<CurrentUser | null>(null);
  const [operatorTrack, setOperatorTrack] = useState<AuthState['operatorTrack']>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    const res = await api.get<{ user: CurrentUser | null; operatorTrack: AuthState['operatorTrack'] }>(
      '/auth/me'
    );
    setUser(res.data?.user ?? null);
    setOperatorTrack(res.data?.operatorTrack ?? null);
  }, []);

  useEffect(() => {
    refresh().finally(() => setLoading(false));
  }, [refresh]);

  const login = useCallback(
    async (email: string, password: string): Promise<LoginResult> => {
      const res = await api.post<{ needsVerification?: boolean; email?: string }>('/auth/login', {
        email,
        password,
      });
      if (!res.success) {
        return { error: res.message, needsVerification: res.data?.needsVerification };
      }
      await refresh();
      return { error: null };
    },
    [refresh]
  );

  const register = useCallback(
    async (
      name: string,
      email: string,
      password: string,
      phone?: string
    ): Promise<RegisterResult> => {
      // `phone` is optional on `registerSchema`; an untouched field sends
      // nothing rather than an empty string.
      const res = await api.post<{ devLink?: string; cooldownMs?: number }>('/auth/register', {
        name,
        email,
        password,
        phone: phone || undefined,
      });
      // No session comes back: the account is unverified until the mailed link
      // is opened, so there is nothing to refresh here.
      if (!res.success) return { error: res.message };
      return { error: null, devLink: res.data?.devLink, cooldownMs: res.data?.cooldownMs };
    },
    []
  );

  const verifyEmail = useCallback(
    async (token: string) => {
      const res = await api.post('/auth/verify-email', { token });
      if (!res.success) return res.message;
      // The route sets the session as it confirms, so this lands signed in.
      await refresh();
      return null;
    },
    [refresh]
  );

  const resendVerification = useCallback(async (email: string): Promise<ResendResult> => {
    const res = await api.post<{ devLink?: string; cooldownMs?: number }>(
      '/auth/verify-email/resend',
      { email }
    );
    // A throttle is a wait, not a refusal. The account's own brakes answer 200
    // with the same neutral copy, so a 429 here is the shared-network ceiling:
    // hand the button the server's `Retry-After` and say so plainly rather than
    // painting an error the rider cannot act on.
    if (!res.success && res.status === 429) {
      return {
        error: null,
        message: 'Too many requests from this network. Try again in a few minutes.',
        cooldownMs: res.retryAfterMs ?? 5 * 60_000,
        wait: true,
      };
    }
    if (!res.success) return { error: res.message };
    return {
      error: null,
      message: res.message,
      devLink: res.data?.devLink,
      cooldownMs: res.data?.cooldownMs,
    };
  }, []);

  const logout = useCallback(async () => {
    await api.post('/auth/logout');
    setUser(null);
    setOperatorTrack(null);
  }, []);

  const value = useMemo(
    () => ({
      user,
      operatorTrack,
      loading,
      refresh,
      login,
      register,
      verifyEmail,
      resendVerification,
      logout,
    }),
    [user, operatorTrack, loading, refresh, login, register, verifyEmail, resendVerification, logout]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthState {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used inside AuthProvider');
  return ctx;
}

export function homePathFor(role: Role | undefined): string {
  if (role === 'ADMIN') return '/admin';
  if (role === 'OPERATOR') return '/operator/dashboard';
  return '/tracks';
}

