          <h3>By track</h3>
          <span className="tiny muted">redemptions this season</span>
        </div>
        <div className="card" style={{ padding: 0 }}>
        <div className="table-scroll">
        <table>
          <thead>
            <tr>
              <SortTh sortKey="track" sort={sort} onSort={toggle}>Track</SortTh>
              <SortTh sortKey="redemptions" sort={sort} onSort={toggle} className="right">Redemptions</SortTh>
              <SortTh sortKey="free" sort={sort} onSort={toggle} className="right">Free</SortTh>
              <SortTh sortKey="discount" sort={sort} onSort={toggle} className="right">Discounted</SortTh>
              <SortTh sortKey="revenue" sort={sort} onSort={toggle} className="right">Track revenue</SortTh>
              <SortTh sortKey="share" sort={sort} onSort={toggle} style={{ width: 120 }}>Share</SortTh>
            </tr>
          </thead>
          <tbody>
            {sorted.map((t) => (
              <tr key={t.trackId}>
                <td>{t.trackName}</td>
                <td className="right">{t.redemptions}</td>
                <td className="right muted">{t.freeDays}</td>
                <td className="right muted">{t.discountDays}</td>
                <td className="right">{money(t.trackRevenueCents)}</td>
                <td>
                  <div className="bar">
                    <span style={{ width: `${(t.redemptions / maxRedemptions) * 100}%` }} />
                  </div>
                </td>
              </tr>
            ))}
            {!perTrack.length && (
              <tr>
                <td colSpan={7} className="muted small">
                  No redemptions this season.
                </td>
              </tr>
            )}
          </tbody>
        </table>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import Banner from '../../components/Banner/Banner';
import { api, money, centsToInput, inputToCents } from '../../lib/api';
import { cleanLine } from '../../lib/sanitize';
import { SortTh, useSorted } from '../../components/sortable';

interface Tier {
  id: string;
  slug: string;
  name: string;
  tagline: string | null;
  priceCents: number;
  earlyBirdPriceCents: number | null;
  twoYearPriceCents: number | null;
  extraDaysPerTrack: number;
  /** The monthly alternative to the annual price — display only. */
  monthlyPriceCents: number | null;
  isActive: boolean;
  sortOrder: number;
}

type MoneyDraft = { price: string; presale: string; twoYear: string; monthly: string };

export default function AdminTiers() {
  const [tiers, setTiers] = useState<Tier[]>([]);
  const [edit, setEdit] = useState<Tier | null>(null);
  const [draft, setDraft] = useState<MoneyDraft | null>(null);
  const [msg, setMsg] = useState<string | null>(null);
  const { sorted, sort, toggle } = useSorted(tiers, {
    tier: (t) => t.name,
    price: (t) => t.priceCents,
    early: (t) => t.earlyBirdPriceCents,
    twoyear: (t) => t.twoYearPriceCents,
    extra: (t) => t.extraDaysPerTrack,
    status: (t) => (t.isActive ? 1 : 0),
  });

  const load = () => api.get<{ tiers: Tier[] }>('/admin/tiers').then((r) => setTiers(r.data?.tiers ?? []));

  useEffect(() => {
    load();
  }, []);

  const openEdit = (t: Tier) => {
    setEdit({ ...t });
    setDraft({
      price: centsToInput(t.priceCents),
      presale: centsToInput(t.earlyBirdPriceCents),
      twoYear: centsToInput(t.twoYearPriceCents),
      monthly: centsToInput(t.monthlyPriceCents),
    });
  };

  const closeEdit = () => {
    setEdit(null);
    setDraft(null);
  };

  const save = async () => {
    if (!edit || !draft) return;
    const priceCents = inputToCents(draft.price);
    const earlyBirdPriceCents = inputToCents(draft.presale);
    const twoYearPriceCents = inputToCents(draft.twoYear);
    const monthlyPriceCents = inputToCents(draft.monthly);
    if (priceCents == null || Number.isNaN(priceCents) || priceCents < 0) {
      setMsg('Enter a price of 0.00 or more.');
      return;
    }
    if ([earlyBirdPriceCents, twoYearPriceCents, monthlyPriceCents].some((c) => c != null && (Number.isNaN(c) || c < 0))) {
      setMsg('Enter amounts of 0.00 or more, or leave the field blank.');
      return;
    }
    const res = await api.patch(`/admin/tiers/${edit.id}`, {
      name: cleanLine(edit.name, 80),
      tagline: cleanLine(edit.tagline ?? '', 200),
      priceCents,
      earlyBirdPriceCents,
      twoYearPriceCents,
      extraDaysPerTrack: Number(edit.extraDaysPerTrack),
      monthlyPriceCents,
      isActive: edit.isActive,
    });
    setMsg(res.message);
    closeEdit();
    load();
  };

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>Pass tiers</h1>
          <div className="small muted">
            Pricing and extra included days per tier.
          </div>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="tier" sort={sort} onSort={toggle}>Tier</SortTh>
              <SortTh sortKey="price" sort={sort} onSort={toggle} className="right">Price</SortTh>
              <SortTh sortKey="early" sort={sort} onSort={toggle} className="right">Presale</SortTh>
              <SortTh sortKey="twoyear" sort={sort} onSort={toggle} className="right">2-year</SortTh>
              <SortTh sortKey="extra" sort={sort} onSort={toggle} className="right">Extra days</SortTh>
              <SortTh sortKey="status" sort={sort} onSort={toggle}>Status</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((t) => (
              <tr key={t.id}>
                <td>
                  <div>
                    {t.name}
                  </div>
                  <div className="tiny muted">{t.tagline}</div>
                </td>
                <td className="right">{money(t.priceCents)}</td>
                <td className="right muted">{t.earlyBirdPriceCents ? money(t.earlyBirdPriceCents) : '—'}</td>
                <td className="right muted">{t.twoYearPriceCents ? money(t.twoYearPriceCents) : '—'}</td>
                <td className="right">+{t.extraDaysPerTrack}</td>
                <td>{!t.isActive && <span className="pill bad">hidden</span>}</td>
                <td className="right">
                  <button className="ghost small" onClick={() => openEdit(t)}>
                    Edit
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {edit && draft && (
        <div className="card stack">
          <div className="row spread">
            <h3 style={{ margin: 0 }}>Edit {edit.name}</h3>
            <button className="ghost small" onClick={closeEdit}>
              Close
            </button>
          </div>
          <div className="grid cols-4">
            <div>
              <label>Name</label>
              <input value={edit.name} onChange={(e) => setEdit({ ...edit, name: e.target.value })} />
            </div>
            <div>
              <label>Price (USD)</label>
              <input
                type="number"
                min="0"
                step="0.01"
                inputMode="decimal"
                placeholder="0.00"
                value={draft.price}
                onChange={(e) => setDraft({ ...draft, price: e.target.value })}
              />
            </div>
            <div>
              <label>Presale (USD)</label>
              <input
                type="number"
                min="0"
                step="0.01"
                inputMode="decimal"
                placeholder="Leave blank for none"
                value={draft.presale}
                onChange={(e) => setDraft({ ...draft, presale: e.target.value })}
              />
            </div>
            <div>
              <label>2-year (USD)</label>
              <input
                type="number"
                min="0"
                step="0.01"
                inputMode="decimal"
                placeholder="Leave blank for none"
                value={draft.twoYear}
                onChange={(e) => setDraft({ ...draft, twoYear: e.target.value })}
              />
            </div>
            <div>
              <label>Extra days per track</label>
              <input
                type="number"
                value={edit.extraDaysPerTrack}
                onChange={(e) => setEdit({ ...edit, extraDaysPerTrack: Number(e.target.value) })}
              />
            </div>
            <div>
              <label>Tagline</label>
              <input
                value={edit.tagline ?? ''}
                onChange={(e) => setEdit({ ...edit, tagline: e.target.value })}
              />
            </div>
            <div>
              <label>Monthly (USD)</label>
              <input
                type="number"
                min="0"
                step="0.01"
                inputMode="decimal"
                placeholder="Leave blank for none"
                value={draft.monthly}
                onChange={(e) => setDraft({ ...draft, monthly: e.target.value })}
              />
            </div>
            <div>
              <label>Visible</label>
              <select
                value={edit.isActive ? 'yes' : 'no'}
                onChange={(e) => setEdit({ ...edit, isActive: e.target.value === 'yes' })}
              >
                <option value="yes">Active</option>
                <option value="no">Hidden</option>
              </select>
            </div>
          </div>
          <div>
            <button className="primary" onClick={save}>
              Save tier
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

