interface TrackRow {
  id: string;
  name: string;
  slug: string;
  website: string | null;
  /** The venue's type — 'MX' (the network is motocross only). */
  category: string;
  isActive: boolean;
  contracts: Contract[];
  _count: { redemptions: number };
}

interface Season {
  id: string;
  year: number;
  isActive: boolean;
}

const blankContract = (seasonId: string): Contract => ({
  id: '',
  seasonId,
  includedDays: 2,
  discountDayEnabled: true,
  discountDayNumber: 3,
  discountRate: 0.5,
  discountDaysAllowed: 1,
  extraDayPriceCents: 4500,
  isActive: true,
  notes: '',
  season: { id: seasonId, year: new Date().getUTCFullYear() },
});

export default function AdminTracks() {
  const [tracks, setTracks] = useState<TrackRow[]>([]);
  const [seasons, setSeasons] = useState<Season[]>([]);
  const [seasonId, setSeasonId] = useState('');
  const [editing, setEditing] = useState<{ track: TrackRow; contract: Contract } | null>(null);
  /** The sticker price as typed, in dollars ("45.00"); saved back as cents. */
  const [priceDraft, setPriceDraft] = useState('');
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const load = async () => {
    const [t, s] = await Promise.all([
      api.get<{ tracks: TrackRow[] }>('/admin/tracks'),
      api.get<{ seasons: Season[] }>('/admin/seasons'),
    ]);
    setTracks(t.data?.tracks ?? []);
    const list = s.data?.seasons ?? [];
    setSeasons(list);
    setSeasonId((prev) => prev || list.find((x) => x.isActive)?.id || list[0]?.id || '');
    setLoading(false);
  };

  useEffect(() => {
    load();
  }, []);

  const openEditor = (track: TrackRow) => {
    const existing = track.contracts.find((c) => c.seasonId === seasonId);
    const contract = existing ? { ...existing } : blankContract(seasonId);
    setEditing({ track, contract });
    setPriceDraft(centsToInput(contract.extraDayPriceCents));
    setMsg(null);
  };

  const save = async () => {
    if (!editing) return;
    const c = editing.contract;
    const extraDayPriceCents = inputToCents(priceDraft);
    if (extraDayPriceCents == null || Number.isNaN(extraDayPriceCents) || extraDayPriceCents < 0) {
      setMsg('Enter an extra-day price of 0.00 or more.');
      return;
    }
    const res = await api.put(`/admin/tracks/${editing.track.id}/contract`, {
      seasonId,
      includedDays: Number(c.includedDays),
      discountDayEnabled: c.discountDayEnabled,
      discountDayNumber: Number(c.discountDayNumber),
      discountRate: Number(c.discountRate),
      discountDaysAllowed: Number(c.discountDaysAllowed),
      extraDayPriceCents,
      isActive: c.isActive,
      notes: cleanMultiline(c.notes ?? '', 1000) || undefined,
    });
    setMsg(res.message);
    if (res.success) {
      setEditing(null);
      load();
    }
  };

  const syncAllotments = async () => {
    const res = await api.post<{ updated: number }>(`/admin/seasons/${seasonId}/sync-allotments`);
    setMsg(res.success ? `Re-snapshotted ${res.data?.updated ?? 0} allotments.` : res.message);
  };

  const seasonYear = seasons.find((s) => s.id === seasonId)?.year ?? new Date().getUTCFullYear();

  const contractOf = (t: TrackRow) => t.contracts.find((x) => x.seasonId === seasonId);
  const { sorted, sort, toggle } = useSorted(tracks, {
    track: (t) => t.name,
    days: (t) => contractOf(t)?.includedDays ?? null,
    discount: (t) => (contractOf(t)?.discountDayEnabled ? contractOf(t)!.discountDayNumber : null),
    counts: (t) => t._count.redemptions,
  });

  if (loading) return <div className="muted">Loading tracks…</div>;

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>Tracks &amp; contracts</h1>
          <div className="small muted">
            Allotment and discount rate are set per track, per season.
          </div>
        </div>
        <div className="row wrap">
          <select value={seasonId} onChange={(e) => setSeasonId(e.target.value)} style={{ width: 130 }}>
            {seasons.map((s) => (
              <option key={s.id} value={s.id}>
                {s.year} season
              </option>
            ))}
          </select>
          <button className="ghost small" onClick={syncAllotments}>
            Re-snapshot allotments
          </button>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="track" sort={sort} onSort={toggle}>Track</SortTh>
              <SortTh sortKey="days" sort={sort} onSort={toggle} className="right">Included days</SortTh>
              <SortTh sortKey="discount" sort={sort} onSort={toggle}>Discounted day</SortTh>
              <SortTh sortKey="counts" sort={sort} onSort={toggle} className="right">Redemptions</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((t) => {
              const c = t.contracts.find((x) => x.seasonId === seasonId);
              return (
                <tr key={t.id}>
                  <td>
                    <div className="track-cell">
                      <TrackName name={t.name} website={t.website} />{' '}
                      {!t.isActive && <span className="pill bad">inactive</span>}
                    </div>
                    <div className="tiny muted">{t.slug}</div>
                  </td>
                  <td className="right">{c?.includedDays ?? <span className="muted">—</span>}</td>
                  <td className="small muted">
                    {c?.discountDayEnabled ? (
                      <>
                        day {c.discountDayNumber} · {Math.round(c.discountRate * 100)}% off ·{' '}
                        {money(Math.round(c.extraDayPriceCents * (1 - c.discountRate)))} (
                        {c.discountDaysAllowed} allowed)
                      </>
                    ) : (
                      'none'
                    )}
                  </td>
                  <td className="right muted small">{t._count.redemptions}</td>
                  <td className="right">
                    <button className="ghost small" onClick={() => openEditor(t)}>
                      {c ? 'Edit contract' : 'Set contract'}
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {editing && (
        <div className="card stack">
          <div className="row spread">
            <h3 style={{ margin: 0 }}>
              {editing.track.name} · {seasonYear} contract
            </h3>
            <button className="ghost small" onClick={() => setEditing(null)}>
              Close
            </button>
          </div>

          <div className="grid cols-4">
            <div>
              <label>Included days per pass</label>
              <input
                type="number"
                min={0}
                value={editing.contract.includedDays}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, includedDays: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discounted day number</label>
              <input
                type="number"
                min={1}
                value={editing.contract.discountDayNumber}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDayNumber: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discount rate (0–1, e.g. 0.5 = 50% off)</label>
              <input
                type="number"
                step="0.05"
                min={0}
                max={1}
                value={editing.contract.discountRate}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountRate: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Discounted days allowed</label>
              <input
                type="number"
                min={0}
                value={editing.contract.discountDaysAllowed}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDaysAllowed: Number(e.target.value) },
                  })
                }
              />
            </div>
            <div>
              <label>Sticker price, extra day (USD)</label>
              <input
                type="number"
                min={0}
                step="0.01"
                inputMode="decimal"
                placeholder="0.00"
                value={priceDraft}
                onChange={(e) => setPriceDraft(e.target.value)}
              />
            </div>
            <div>
              <label>Discounted day price</label>
              <input
                readOnly
                value={money(
                  Math.round((inputToCents(priceDraft) ?? 0) * (1 - editing.contract.discountRate))
                )}
              />
            </div>
            <div>
              <label>Discount day enabled</label>
              <select
                value={editing.contract.discountDayEnabled ? 'yes' : 'no'}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, discountDayEnabled: e.target.value === 'yes' },
                  })
                }
              >
                <option value="yes">Enabled</option>
                <option value="no">Disabled</option>
              </select>
            </div>
            <div>
              <label>Contract active</label>
              <select
                value={editing.contract.isActive ? 'yes' : 'no'}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, isActive: e.target.value === 'yes' },
                  })
                }
              >
                <option value="yes">Active</option>
                <option value="no">Inactive</option>
              </select>
            </div>
            <div style={{ gridColumn: 'span 2' }}>
              <label>Notes</label>
              <input
                value={editing.contract.notes ?? ''}
                onChange={(e) =>
                  setEditing({
                    ...editing,
                    contract: { ...editing.contract, notes: e.target.value },
                  })
                }
              />
            </div>
          </div>

          <div className="row wrap">
            <button className="primary" onClick={save}>
              Save contract
            </button>
            <span className="tiny muted">
              Existing allotments keep their snapshot. Use “Re-snapshot allotments” to push changes
              to riders already holding a pass.
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import Banner from '../../components/Banner/Banner';
import { api, dayStr } from '../../lib/api';
import { cleanLine } from '../../lib/sanitize';
import { SortTh, useSorted } from '../../components/sortable';

interface UserRow {
  id: string;
  name: string;
  email: string;
  role: string;
  isActive: boolean;
  operatorTrack: { id: string; name: string } | null;
  latestPass: {
    id: string;
    status: string;
    seasonYear: number;
    tierName: string;
    expiresAt: string;
  } | null;
}

export default function AdminUsers() {
  const [users, setUsers] = useState<UserRow[]>([]);
  const [search, setSearch] = useState('');
  const [role, setRole] = useState('');
  const [total, setTotal] = useState(0);
  const [msg, setMsg] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const { sorted, sort, toggle } = useSorted(users, {
    name: (u) => u.name,
    email: (u) => u.email,
    role: (u) => u.role,
    pass: (u) => u.latestPass?.tierName ?? null,
    expires: (u) => u.latestPass?.expiresAt ?? null,
    status: (u) => (u.isActive ? 1 : 0),
  });

  const load = async () => {
    setLoading(true);
    const q = new URLSearchParams();
    if (search) q.set('search', cleanLine(search, 120));
    if (role) q.set('role', role);
    const res = await api.get<UserRow[]>(`/admin/users?${q.toString()}`);
    setUsers(res.data ?? []);
    setTotal(res.pagination?.total ?? (res.data?.length ?? 0));
    setLoading(false);
  };

  useEffect(() => {
    const id = setTimeout(load, 250);
    return () => clearTimeout(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, role]);

  const setUserRole = async (u: UserRow, nextRole: string) => {
    const res = await api.patch(`/admin/users/${u.id}`, { role: nextRole });
    setMsg(res.message);
    load();
  };

  const toggleActive = async (u: UserRow) => {
    const res = await api.patch(`/admin/users/${u.id}`, { isActive: !u.isActive });
    setMsg(res.message);
    load();
  };

  return (
    <div className="stack">
      <div className="row spread wrap">
        <div>
          <h1>Users</h1>
          <div className="small muted">{total} accounts</div>
        </div>
        <div className="row wrap">
          <input
            placeholder="Search name or email"
            value={search}
            onChange={(e) => setSearch(cleanLine(e.target.value, 120))}
            style={{ width: 220 }}
          />
          <select value={role} onChange={(e) => setRole(e.target.value)} style={{ width: 150 }}>
            <option value="">All roles</option>
            <option value="RIDER">Riders</option>
            <option value="OPERATOR">Operators</option>
            <option value="ADMIN">Admins</option>
          </select>
        </div>
      </div>

      {msg && <Banner tone="ok" close>{msg}</Banner>}

      <div className="card" style={{ padding: 0 }}>
        <table>
          <thead>
            <tr>
              <SortTh sortKey="name" sort={sort} onSort={toggle}>Name</SortTh>
              <SortTh sortKey="email" sort={sort} onSort={toggle}>Email</SortTh>
              <SortTh sortKey="role" sort={sort} onSort={toggle}>Role</SortTh>
              <SortTh sortKey="pass" sort={sort} onSort={toggle}>Pass</SortTh>
              <SortTh sortKey="expires" sort={sort} onSort={toggle}>Expires</SortTh>
              <SortTh sortKey="status" sort={sort} onSort={toggle}>Status</SortTh>
              <th className="right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((u) => (
              <tr key={u.id}>
                <td>
                  {u.name}
                  {u.operatorTrack && <div className="tiny muted">at {u.operatorTrack.name}</div>}
                </td>
                <td className="small muted">{u.email}</td>
                <td>
                  <select
                    value={u.role}
                    onChange={(e) => setUserRole(u, e.target.value)}
                    style={{ width: 120, padding: '4px 6px' }}
                  >
                    <option value="RIDER">RIDER</option>
                    <option value="OPERATOR">OPERATOR</option>
                    <option value="ADMIN">ADMIN</option>
                  </select>
                </td>
                <td className="small">
                  {u.latestPass ? (
                    <>
                      <div>{u.latestPass.tierName}</div>
                      <div className="tiny muted">
                        {u.latestPass.seasonYear} · {u.latestPass.status}
                      </div>
                    </>
                  ) : (
                    <span className="muted">—</span>
                  )}
                </td>
                <td className="small muted">{u.latestPass ? dayStr(u.latestPass.expiresAt) : '—'}</td>
                <td>
                  {!u.isActive && <span className="pill bad">disabled</span>}
                </td>
                <td className="right">
                  <span className="row" style={{ justifyContent: 'flex-end' }}>
                    <button className="ghost small" onClick={() => toggleActive(u)}>
                      {u.isActive ? 'Disable' : 'Enable'}
                    </button>
                  </span>
                </td>
              </tr>
            ))}
            {!users.length && !loading && (
              <tr>
                <td colSpan={7} className="muted small">
                  No users match.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* AuthAstryx — styles owned by AuthAstryx.tsx (the `/login` and `/signup`
   pages while `enableAstryxUI` is on).

   Same rules as AstryxLanding.scss / PricingAstryx.scss: the register's tokens
   are declared scoped to `.axa-page`, never on `:root`, and every rule is
   written through that wrapper so it out-specifies global.scss's base layer
   (`input`, `label`, `button.primary`, `.card`). `Login.tsx` is untouched and
   comes back exactly when the flag flips. */

.axa-page {
  /* Surfaces, one step each. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* Moto Pass's own orange, on the register's accent / edge / on-accent trio. */
  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-ink: #0a1317;
  --ax-accent-tint: rgba(255, 138, 63, 0.18);
  /* Text on the accent, not the accent's own fill: light orange on a light
     ground sits at 3.1:1, so the light theme darkens it to the edge tone. */
  --ax-link: #ff8a3f;

  /* Notice tints. */
  --ax-ok-ink: #a5f690;
  --ax-ok-tint: rgba(36, 187, 94, 0.14);
  --ax-ok-line: rgba(36, 187, 94, 0.35);
  --ax-bad-ink: #fca5a5;
  --ax-bad-tint: rgba(239, 68, 68, 0.14);
  --ax-bad-line: rgba(239, 68, 68, 0.38);

  /* Radii, type ramp and spacing steps. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-pill: 999px;

  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;
  --ax-fs-base: 16px;
  --ax-fs-lg: 20px;
  --ax-fs-xl: 25px;
  --ax-fs-2xl: 31px;

  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;
  --ax-s-5: 30px;
  --ax-s-6: 36px;
  --ax-s-8: 48px;
  --ax-s-10: 60px;

  --ax-shadow: 0 26px 60px rgba(0, 0, 0, 0.5);
  --ax-e-fast: 100ms;

  /* Edge to edge out of <main>'s 1550px column; the foot cancels its 60px
     bottom padding so this page's ground meets the footer and the footer still
     begins one screen down (the band fills the fold, minus the header and
     <main>'s own 22px + 60px padding). */
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-bottom: -60px;

  min-height: calc(100svh - var(--header-h, 57px) - 82px);
  display: flex;
  align-items: flex-start;
  padding: var(--ax-s-10) var(--ax-s-6) var(--ax-s-8);

  background: var(--ax-body);
  color: var(--ax-ink);
  font-family: 'Figtree Variable', Figtree, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-base);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* The app's own light palette, restated for this page's surfaces. */
:root[data-theme='light'] .axa-page {
  --ax-body: #f1f4f7;
  --ax-surface: #ffffff;
  --ax-raised: #ffffff;
  --ax-line: rgba(5, 54, 89, 0.1);
  --ax-line-strong: #ccd3db;

  --ax-ink: #0a1317;
  --ax-ink-2: #4e606f;
  --ax-ink-3: #a4b0bc;

  --ax-accent: #eb6e00;
  --ax-accent-edge: #b34a01;
  --ax-accent-ink: #1a0d03;
  --ax-accent-tint: rgba(235, 110, 0, 0.14);
  --ax-link: #b34a01;

  --ax-ok-ink: #09441f;
  --ax-ok-tint: rgba(36, 187, 94, 0.16);
  --ax-ok-line: rgba(36, 187, 94, 0.42);
  --ax-bad-ink: #8f1d1d;
  --ax-bad-tint: rgba(239, 68, 68, 0.1);
  --ax-bad-line: rgba(239, 68, 68, 0.32);

  --ax-shadow: 0 4px 6px rgba(5, 54, 89, 0.08), 0 12px 24px rgba(5, 54, 89, 0.14);
}

.axa-page ::selection {
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
}

.axa-page :focus-visible {
  outline: 2px solid var(--ax-accent);
  outline-offset: 2px;
  border-radius: var(--ax-r-inner);
}

.axa-page h1,
.axa-page h2 {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.axa-page p {
  margin: 0;
}

/* ------------------------------------------------------------------ layout */

/* One column: the form is the whole page. */
.axa-wrap {
  width: 100%;
  max-width: 460px;
  margin-inline: auto;
}

.axa-col {
  min-width: 0;
}

/* ------------------------------------------------------------------ the card */

.axa-card {
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  padding: 28px;
  box-shadow: var(--ax-shadow);
}

.axa-head h1 {
  font-size: var(--ax-fs-xl);
}

.axa-head p {
  margin-top: var(--ax-s-1);
  font-size: var(--ax-fs-sm);
  color: var(--ax-ink-2);
}

/* Notices sit where the form's first field would, so nothing below shifts.
   The plain notice is a quiet grey board: the accent belongs to ok / bad and
   the links, not to the sentence a rider has just read.
   Scoped to .axa-page so it outranks the page-wide `p { margin: 0 }` below;
   without the extra class the top margin never lands. */
.axa-page .axa-alert {
  position: relative;
  margin-top: var(--ax-s-4);
  padding: 10px var(--ax-s-2);
  border: 1px solid rgba(242, 244, 246, 0.14);
  border-radius: var(--ax-r-inner);
  background: rgba(242, 244, 246, 0.035);
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-xs);
  line-height: 1.45;
  /* How far the breathing edge reaches; ok / bad dial it up below. */
  --ax-edge-a: 0.4;
}

:root[data-theme='light'] .axa-alert:not(.ok):not(.bad) {
  border-color: rgba(5, 54, 89, 0.16);
  background: rgba(5, 54, 89, 0.035);
}

/* A notice followed by the form closes up: 18px gap plus the submit's own 6px
   lands the button 24px under the board, the same 24px the foot leaves below
   it, so the button sits centred between the two rules rather than low. */
.axa-alert + .axa-form {
  margin-top: var(--ax-s-3);
}

/* A notice inside the form takes the column's gap, not its own margin on top
   of it (resend confirmation, expired-link copy). */
.axa-form .axa-alert {
  margin-top: 0;
}

.axa-alert.ok {
  background: var(--ax-ok-tint);
  border-color: var(--ax-ok-line);
  color: var(--ax-ok-ink);
  --ax-edge-a: 0.45;
}

.axa-alert.bad {
  background: var(--ax-bad-tint);
  border-color: var(--ax-bad-line);
  color: var(--ax-bad-ink);
  --ax-edge-a: 0.55;
}

/* The notice's edge breathes: a second 1px ring laid just outside the border,
   drawn in the notice's own ink and faded in and out. Only `opacity` animates,
   so the ring stays on the compositor — no layout, no repaint per frame, and
   the text inside never reflows. Paint-free by construction: the ring is a
   static pseudo-element, nothing is recoloured mid-flight. */
.axa-page .axa-alert::after {
  content: '';
  position: absolute;
  inset: -1px;
  border: 1px solid currentColor;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
  will-change: opacity;
  animation: axa-alert-edge 4.2s ease-in-out infinite;
}

@keyframes axa-alert-edge {
  0%,
  100% {
    opacity: 0;
  }
  50% {
    opacity: var(--ax-edge-a, 0.4);
  }
}

/* Motion off: the notice keeps its plain border, no ring at all. */
@media (prefers-reduced-motion: reduce) {
  .axa-page .axa-alert::after {
    animation: none;
    opacity: 0;
    will-change: auto;
  }
}

/* ------------------------------------------------------------------ the form */

.axa-form {
  display: flex;
  flex-direction: column;
  gap: var(--ax-s-3);
  margin-top: var(--ax-s-5);
}

.axa-field label {
  display: block;
  margin-bottom: var(--ax-s-1);
  font-size: var(--ax-fs-xs);
  font-weight: 500;
  color: var(--ax-ink-2);
}

.axa-field input {
  width: 100%;
  height: 44px;
  padding: 0 var(--ax-s-2);
  background: var(--ax-body);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-inner);
  color: var(--ax-ink);
  font-size: var(--ax-fs-sm);
  border-color: rgba(242, 244, 246, 0.16);
}

:root[data-theme='light'] .axa-field input {
  border-color: rgba(5, 54, 89, 0.18);
}

.axa-field input:focus {
  outline: none;
  border-color: var(--ax-accent);
  box-shadow: 0 0 0 3px var(--ax-accent-tint);
}

/* A field the notice blames wears the notice's own edge, so the mark is not
   screen-reader-only. Last in the block: it has to beat the plain field rule
   and the autofill repaint below keeps its own ground. */
.axa-field input[aria-invalid='true'] {
  border-color: var(--ax-bad-line);
}

.axa-field input[aria-invalid='true']:focus {
  border-color: var(--ax-bad-line);
  box-shadow: 0 0 0 3px var(--ax-bad-tint);
}

/* Chrome's autofill repaints the field: keep this page's own well under it. */
.axa-page .axa-field input:-webkit-autofill,
.axa-page .axa-field input:-webkit-autofill:hover,
.axa-page .axa-field input:-webkit-autofill:focus,
.axa-page .axa-field input:-webkit-autofill:active {
  -webkit-text-fill-color: var(--ax-ink);
  -webkit-box-shadow: 0 0 0 1000px var(--ax-body) inset;
  box-shadow: 0 0 0 1000px var(--ax-body) inset;
  caret-color: var(--ax-ink);
}

/* The consent line under the fields: a 16px box and one sentence, the two
   policy words carrying the accent link. */
.axa-consent {
  display: flex;
  align-items: flex-start;
  gap: var(--ax-s-2);
  font-size: var(--ax-fs-xs);
  line-height: 1.5;
  color: var(--ax-ink-2);
}

.axa-consent input {
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  margin: 2px 0 0;
  accent-color: var(--ax-accent);
  cursor: pointer;
}

.axa-consent label {
  margin: 0;
  font-size: inherit;
  font-weight: 400;
  color: inherit;
  cursor: pointer;
}

.axa-consent a {
  color: var(--ax-link);
  text-decoration: none;
}

.axa-consent a:hover {
  text-decoration: underline;
}

/* A field rule that stays put: the placeholder is gone the moment you type.
   `.axa-page p` zeroes every paragraph's margin, so this one carries the still
   class in its selector to keep its gap under the field. */
.axa-page .axa-hint {
  margin-top: 6px;
  font-size: var(--ax-fs-xs);
  line-height: 1.4;
  color: var(--ax-ink-2);
}

.axa-page .axa-hint.is-warn {
  color: var(--ax-bad-ink);
}

/* The password rule's tick: a small check on the left of the words that only
   shows once the field qualifies. Its 12px slot is reserved whether it is lit
   or not (`opacity`, not `display`), so the sentence never shifts as it fades
   in. `data-met` is absent until the password reaches the length. */
.axa-page .axa-hint.has-check {
  display: flex;
  align-items: center;
  gap: 5px;
}

.axa-page .axa-hint-check {
  flex: none;
  display: inline-flex;
  width: 12px;
  height: 12px;
  color: var(--ax-ok-ink);
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 120ms ease, transform 120ms ease;
}

.axa-page .axa-hint-check[data-met] {
  opacity: 1;
  transform: none;
}

.axa-page .axa-hint-check svg {
  width: 100%;
  height: 100%;
}

.axa-submit {
  width: 100%;
  height: 46px;
  margin-top: var(--ax-s-1);
  border: 0;
  border-radius: var(--ax-r-pill);
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
  font-family: inherit;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  cursor: pointer;
  transition: opacity var(--ax-e-fast) ease;
}

.axa-submit:hover:not(:disabled) {
  opacity: 0.85;
}

.axa-submit:disabled {
  opacity: 0.6;
  cursor: default;
}

.axa-foot {
  margin-top: var(--ax-s-4);
  padding-top: var(--ax-s-3);
  border-top: 1px solid var(--ax-line);
}

.axa-switch {
  border: 0;
  padding: 0;
  background: none;
  color: var(--ax-link);
  font-family: inherit;
  font-size: var(--ax-fs-sm);
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  /* The reset pages use this class on a router Link, not only a button. */
  text-decoration: none;
}

.axa-switch:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* The password field's label row: label left, "Forgot password?" right. */
.axa-label-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ax-s-2);
}

.axa-forgot {
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-xs);
  font-weight: 500;
  text-decoration: none;
}

.axa-forgot:hover {
  color: var(--ax-link);
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* A label-row note, not a link: the signup phone field is optional. */
.axa-optional {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

/* ------------------------------------------------------------------ demo accounts */

.axa-demo {
  margin-top: var(--ax-s-2);
  padding: var(--ax-s-3) var(--ax-s-4) var(--ax-s-4);
}

.axa-demo-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ax-s-2);
  margin-bottom: var(--ax-s-2);
}

.axa-demo-head h2 {
  font-size: var(--ax-fs-base);
}

.axa-demo-pw {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

.axa-demo-pw code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink);
}

/* One account a line: the label on the left, the email it signs in with on the
   right. Nothing truncates at this width. */
.axa-rows {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.axa-account {
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-inner);
  background: var(--ax-body);
  overflow: hidden;
}

.axa-account.is-open {
  border-color: var(--ax-accent-edge);
}

.axa-account-row {
  display: flex;
  align-items: stretch;
}

.axa-quick {
  flex: 1;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ax-s-2);
  min-width: 0;
  padding: 7px 10px;
  border: 0;
  border-radius: 0;
  background: none;
  font-family: inherit;
  text-align: left;
