}

.axa-quick-mail {
  overflow: hidden;
  max-width: 100%;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: var(--ax-ink-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.axa-info {
  display: flex;
  align-items: center;
  padding: 0 10px;
  border: 0;
  border-left: 1px solid var(--ax-line);
  border-radius: 0;
  background: none;
  color: var(--ax-ink-3);
  cursor: pointer;
}

.axa-account.is-open .axa-info {
  color: var(--ax-accent);
}

.axa-points {
  padding: 10px var(--ax-s-2) var(--ax-s-2);
  border-top: 1px solid var(--ax-line);
  font-size: var(--ax-fs-xs);
