}

/* ------------------------------------------------------------------ narrow */

@media (max-width: 980px) {
  .axa-page {
    align-items: flex-start;
    padding: var(--ax-s-4);
  }

  /* Phones stack the pair inside the row and keep the app's 44px tap floor. */
  .axa-quick {
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    padding: 10px var(--ax-s-2);
  }

  .axa-quick-label {
