import { FormEvent, useEffect, useState } from 'react';
import { Navigate, Link, useLocation, useNavigate } from 'react-router-dom';
// Self-hosted Figtree, as the landing and pricing pages do — never a Google Fonts link.
import '@fontsource-variable/figtree';
import { useAuth, homePathFor } from '../../lib/auth';
import { signupDemoAccounts } from '../../lib/demoAccounts';
import { cleanEmailDraft, cleanNameDraft, isEmail, isPhone } from '../../lib/sanitize';
import { formatPhoneInput } from '../../lib/phoneInput';
import PasswordField from '../../components/PasswordField/PasswordField';
import './AuthAstryx.scss';

/** The info glyph on a demo row: what differs about that account. */
function InfoIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
      <circle cx="8" cy="8" r="6.6" fill="none" stroke="currentColor" strokeWidth="1.3" />
      <circle cx="8" cy="5" r="0.9" fill="currentColor" />
      <rect x="7.3" y="6.8" width="1.4" height="4.4" rx="0.7" fill="currentColor" />
    </svg>
  );
}

export type AuthMode = 'login' | 'register';

/** The control a failure notice blames. `credentials` marks both sign-in
    fields, because the API never says which one was wrong. */
type ErrField = 'email' | 'password' | 'confirm' | 'agree' | 'credentials';

/** The refusal notice's own id: the fields point at it with
    `aria-describedby`, so a screen reader reads the reason off the field. */
const NOTICE_ID = 'auth-notice';

/** One wording for the address rule: the same sentence on submit and on a blur. */
const EMAIL_MESSAGE = 'Enter a valid email address.';

/** The rule's own line, under the field — the ids `aria-describedby` names. */
const EMAIL_HINT_ID = 'email-hint';

/** The phone's rule, said under its own field: optional, but a number that is
    written has to be a number the API will take. */
const PHONE_MESSAGE = 'Enter a phone number with 7 to 15 digits.';
const PHONE_HINT_ID = 'phone-hint';

/**
 * `/login` and `/signup` in the reference design system's register (Astryx),
 * chosen by `enableAstryxUI`. `Login.tsx` is still here in full — flip the flag
 * to `false` and the plain card pair comes back exactly as it was.
 *
 * Same behaviour as `Login.tsx`: the mode is the route's, not state; `?next=`
 * survives the switch; `?mode=register` still redirects to `/signup`; the demo
 * accounts ride the sign-in page only. What changes is the component language —
 * a spec column beside the form card, fields as inset wells, the CTA on the
 * accent — and the tokens to match. The ids (`#name` / `#email` / `#password`),
 * `form button.primary` and the switch's exact label are kept on purpose:
 * `verify-upgrade-welcome.cjs` drives the form by them.
 */
export default function AuthAstryx({ mode }: { mode: AuthMode }) {
  const [name, setName] = useState('');
  /** Optional, as `registerSchema` has it: the gate can find a rider by phone. */
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  /** The consent line is a gate, not decoration: registering needs it ticked. */
  const [agree, setAgree] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [errField, setErrField] = useState<ErrField | null>(null);
  /** The notice's own key: a live region only speaks when its node is inserted
      or its text changes, so a repeat of the same failure has to remount it. */
  const [errSeq, setErrSeq] = useState(0);
  /** Set once the reader leaves the email field: from then on an invalid
      address states itself instead of waiting for a submit. */
  const [emailTouched, setEmailTouched] = useState(false);
  /** The same for the optional phone: quiet until it is left, then its rule. */
  const [phoneTouched, setPhoneTouched] = useState(false);
  const [busy, setBusy] = useState(false);
  const [infoFor, setInfoFor] = useState<string | null>(null);
  const { login, register, user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation() as { state?: { from?: string } };

  const [redirect, setRedirect] = useState<string | null>(null);

  /**
   * `?next=` is how a banner deep-links back here (the returning Stripe
   * checkout is the one that needs it: its session id has to survive the
   * sign-in or the pass never activates). Only a same-origin path is honoured.
   */
  const nextParam = new URLSearchParams(window.location.search).get('next');
  const safeNext = nextParam && nextParam.startsWith('/') && !nextParam.startsWith('//') ? nextParam : null;
  const nextQuery = safeNext ? `?next=${encodeURIComponent(safeNext)}` : '';

  /** The return trip after a rider closes their account. */
  const deletedNotice = new URLSearchParams(window.location.search).get('deleted') === '1';

  /** The other half of the pair, carrying any deep link across. */
  const otherHref = mode === 'login' ? `/signup${nextQuery}` : `/login${nextQuery}`;

  // Old `?mode=register` links (pricing CTAs, bookmarks) predate `/signup`.
  const legacyRegister =
    mode === 'login' && new URLSearchParams(window.location.search).get('mode') === 'register';

  useEffect(() => {
    if (user) setRedirect(safeNext ?? homePathFor(user.role));
  }, [user, safeNext]);

  if (redirect) return <Navigate to={redirect} replace />;
  if (legacyRegister) return <Navigate to={`/signup${nextQuery}`} replace />;

  /**
   * One place to raise a failure, so the notice can never be silent or leave
   * the control it blames unmarked: the message goes into a `role="alert"`
   * node, and the field named here carries `aria-invalid` + `aria-describedby`.
   */
  const fail = (message: string, field: ErrField | null) => {
    setErr(message);
    setErrField(field);
    setErrSeq((n) => n + 1);
  };

  /** A cleared notice is a cleared blame — never a stale red field. */
  const clearErr = () => {
    setErr(null);
    setErrField(null);
  };

  /** Editing the field a notice blames puts the notice away. */
  const editedField = (...fields: ErrField[]) => {
    if (errField && fields.includes(errField)) clearErr();
  };

  /**
   * Signup is a gate, not a suggestion. Every rule the API enforces is read
   * here, on every keystroke: the CTA stays disabled and `submit()` refuses
   * until all of them hold. Phone is optional by design (`registerSchema`).
   */
  const emailOk = isEmail(email);
  /** Optional by design: blank is fine, anything written must be a number. */
  const phoneOk = isPhone(phone);
  const canSubmit =
    mode === 'login' ||
    (name.trim().length > 0 &&
      emailOk &&
      phoneOk &&
      password.length >= 8 &&
      confirm === password &&
      agree);

  /* The rule the field states under itself, as the password hints do, rather
     than in the card notice — that one stays for what the server said. */
  const emailRuleBad = emailTouched && email.length > 0 && !emailOk;
  const phoneRuleBad = phoneTouched && phone !== '' && !phoneOk;

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    clearErr();
    // The CTA is disabled while the form is incomplete; this is the backstop
    // for a submit that arrives anyway (implicit Enter, autofill, stale render).
    if (!canSubmit) return;
    // Sign-in's CTA stays live, so the address itself is refused here.
    // The rule reads under the field, so a submit only has to make sure it is
    // showing — the card notice stays for what the server said.
    if (!emailOk) {
      setEmailTouched(true);
      return;
    }
    // Same for the optional phone: a number that was written has to be one.
    if (!phoneOk) {
      setPhoneTouched(true);
      return;
    }
    // Registering states both rules while typing; these are the backstop for a
    // submit that never touched the hint (paste + Enter, autofill).
    if (mode !== 'login' && password.length < 8) {
      fail('Use at least 8 characters.', 'password');
      return;
    }
    // Registering types the password twice; a mismatch never reaches the API.
    if (mode !== 'login' && password !== confirm) {
      fail('Passwords do not match.', 'confirm');
      return;
    }
    // Consent is checked here, not by a native `required` tooltip, so the
    // answer lands in the card's own notice slot.
    if (mode !== 'login' && !agree) {
      fail('Agree to the Terms and Privacy policy to continue.', 'agree');
      return;
    }
    setBusy(true);
    if (isLogin) {
      const result = await login(email, password);
      setBusy(false);
      if (result.error) {
        // The password was right but the address is still unconfirmed: a step to
        // finish, not a refusal, so it goes to the step.
        if (result.needsVerification) {
          navigate(`/verify-email?email=${encodeURIComponent(email)}`);
          return;
        }
        // A refused sign-in blames both fields (the API does not say which),
        // while a refused registration stays a notice only: the server may
        // refuse for the name, the email or the password, and a wrong
        // `aria-invalid` is worse than a missing one.
        return fail(result.error, 'credentials');
      }
    } else {
      const result = await register(name, email, password, phone);
      setBusy(false);
      if (result.error) return fail(result.error, null);
      // Signing up is not signing in: the account waits on the mailed link.
      navigate(`/verify-email?email=${encodeURIComponent(email)}`, {
        state: { email, devLink: result.devLink, cooldownMs: result.cooldownMs },
      });
      return;
    }
    // A deep link wins; otherwise the role's own home takes over below.
    const from = location.state?.from ?? safeNext ?? undefined;
    if (from) navigate(from, { replace: true });
  };

  const quick = (e: string) => {
    setEmail(e);
    setPassword('dialed123');
    // The confirmation only appears once a password exists, so a demo fill has
    // to answer it too — otherwise the CTA stays refused behind a hidden field.
    setConfirm('dialed123');
    // A demo fill answers the notice, so it must not leave a field marked.
    clearErr();
  };

  const isLogin = mode === 'login';
  /* Registering only asks for the password twice once there is a password to
     repeat: the field stays out of the way (and out of the tab order) until the
     first character lands in the field above it. */
  const showConfirm = !isLogin && password.length > 0;

  /* The rule the API enforces (`registerSchema`: min 8) and the pair check, both
     read while typing rather than only at submit. The mismatch waits until the
     second field is at least as long as the first, so it does not shout at the
     first character of a matching password. */
  const tooShort = !isLogin && password.length > 0 && password.length < 8;
  const mismatch =
    !isLogin && confirm.length > 0 && confirm.length >= password.length && password !== confirm;

  /* The notice is the fields' description while it stands, so a reader who
     tabs back into the form hears why it refused. */
  const badEmail = errField === 'email' || errField === 'credentials' || emailRuleBad;
  const badPassword = errField === 'password' || errField === 'credentials';
  const badConfirm = errField === 'confirm';
  const badAgree = errField === 'agree';
  const described = (...ids: (string | null | undefined)[]) =>
    ids.filter(Boolean).join(' ') || undefined;

  return (
    <div className="axa-page">
      <div className="axa-wrap">
        <div className="axa-col">
          <section className="axa-card">
            <header className="axa-head">
              <h1>{isLogin ? 'Sign in' : 'Create account'}</h1>
              <p>{isLogin ? 'Your rider account.' : 'Free pass. No card.'}</p>
            </header>

            {deletedNotice && (
              <p className="axa-alert ok">Account deleted. The email is free to register again.</p>
            )}
            {err && (
              <p
                key={errSeq}
                id={NOTICE_ID}
                className="axa-alert bad"
                role="alert"
                aria-live="assertive"
                aria-atomic="true"
              >
                {err}
              </p>
            )}

            <form onSubmit={submit} className="axa-form">
              {!isLogin && (
                <div className="axa-field">
                  <label htmlFor="name">Name</label>
                  <input
                    id="name"
                    autoComplete="name"
                    placeholder="Riley"
                    value={name}
                    onChange={(e) => setName(cleanNameDraft(e.target.value, 80))}
                    required
                  />
                </div>
              )}
              <div className="axa-field">
                <label htmlFor="email">Email</label>
                <input
                  id="email"
                  type="email"
                  autoComplete="username"
                  placeholder="riley@example.com"
                  value={email}
                  maxLength={254}
                  onChange={(e) => {
                    setEmail(cleanEmailDraft(e.target.value));
                    editedField('email', 'credentials');
                  }}
                  onBlur={() => setEmailTouched(true)}
                  required
                  aria-invalid={badEmail || undefined}
                  aria-describedby={described(
                    emailRuleBad ? EMAIL_HINT_ID : null,
                    errField === 'email' || errField === 'credentials' ? NOTICE_ID : null,
                  )}
                />
                {emailRuleBad && (
                  <p id={EMAIL_HINT_ID} className="axa-hint is-warn" role="alert">
                    {EMAIL_MESSAGE}
                  </p>
                )}
              </div>
              {!isLogin && (
                <div className="axa-field">
                  <label htmlFor="phone">
                    Phone <span className="axa-optional">(Optional)</span>
                  </label>
                  <input
                    id="phone"
                    type="tel"
                    inputMode="tel"
                    autoComplete="tel"
                    placeholder="(828) 555-0142"
                    value={phone}
                    onChange={(e) => formatPhoneInput(e.target, setPhone)}
                    onBlur={() => setPhoneTouched(true)}
                    aria-invalid={phoneRuleBad || undefined}
                    aria-describedby={phoneRuleBad ? PHONE_HINT_ID : undefined}
                  />
                  {phoneRuleBad && (
                    <p id={PHONE_HINT_ID} className="axa-hint is-warn" role="alert">
                      {PHONE_MESSAGE}
                    </p>
                  )}
                </div>
              )}
              <div className="axa-field">
                <div className="axa-label-row">
                  <label htmlFor="password">Password</label>
                  {isLogin && (
                    <Link className="axa-forgot" to="/forgot-password">
                      Forgot password?
                    </Link>
                  )}
                </div>
                <PasswordField
                  id="password"
                  autoComplete={isLogin ? 'current-password' : 'new-password'}
                  placeholder="Your password"
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    // Emptying the field withdraws the confirmation with it, so
                    // a stale repeat can never ride along into the submit.
                    if (e.target.value === '') setConfirm('');
                    editedField('password', 'credentials');
                  }}
                  required
                  ariaInvalid={tooShort || badPassword}
                  ariaDescribedBy={described(
                    badPassword ? NOTICE_ID : null,
                    isLogin ? null : 'password-hint',
                  )}
                />
                {!isLogin && (
                  <p
                    id="password-hint"
                    className={`axa-hint has-check${tooShort ? ' is-warn' : ''}`}
                  >
                    <span
                      className="axa-hint-check"
                      data-met={password.length >= 8 || undefined}
                      aria-hidden="true"
                    >
                      <svg viewBox="0 0 20 20" fill="none" focusable="false">
                        <path
                          d="M4.5 10.6 8.2 14.3 15.5 6"
                          stroke="currentColor"
                          strokeWidth="2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </svg>
                    </span>
                    8 characters minimum.
                  </p>
                )}
              </div>
              {showConfirm && (
                <div className="axa-field">
                  <label htmlFor="confirm">Confirm password</label>
                  <PasswordField
                    id="confirm"
                    autoComplete="new-password"
                    placeholder="Repeat password"
                    value={confirm}
                    onChange={(e) => {
                      setConfirm(e.target.value);
                      editedField('confirm');
                    }}
                    required
                    ariaInvalid={mismatch || badConfirm}
                    ariaDescribedBy={described(
                      badConfirm ? NOTICE_ID : null,
                      mismatch ? 'confirm-hint' : null,
                    )}
                  />
                  {mismatch && (
                    <p id="confirm-hint" className="axa-hint is-warn" role="alert">
                      Passwords do not match.
                    </p>
                  )}
                </div>
              )}
              {!isLogin && (
                <div className="axa-consent">
                  <input
                    id="agree"
                    type="checkbox"
                    checked={agree}
                    onChange={(e) => {
                      setAgree(e.target.checked);
                      editedField('agree');
                    }}
                    aria-invalid={badAgree || undefined}
                    aria-describedby={badAgree ? NOTICE_ID : undefined}
                  />
                  <label htmlFor="agree">
                    By creating an account you agree to the{' '}
                    <Link to="/terms">Terms</Link> and <Link to="/privacy">Privacy policy</Link>
                  </label>
                </div>
              )}
              <button
                className="primary axa-submit"
                disabled={busy || !canSubmit}
              >
                {busy ? 'Working…' : isLogin ? 'Sign in' : 'Create account'}
              </button>
            </form>

            <div className="axa-foot">
              <button
                type="button"
                className="axa-switch"
                onClick={() => {
                  clearErr();
                  navigate(otherHref);
                }}
              >
                {isLogin ? 'Need an account? Register' : 'Already have an account? Sign in'}
              </button>
            </div>
          </section>

          {/* Demo accounts are sign-in aids, so they ride the sign-in page only. */}
          {isLogin && (
            <section className="axa-card axa-demo">
              <div className="axa-demo-head">
                <h2>Demo accounts</h2>
                <span className="axa-demo-pw">
                  password <code>dialed123</code>
                </span>
              </div>

              <div className="axa-rows">
                {signupDemoAccounts.map((acct) => {
                  const open = infoFor === acct.email;
                  return (
                    <div className={open ? 'axa-account is-open' : 'axa-account'} key={acct.email}>
                      <div className="axa-account-row">
                        <button
                          type="button"
                          className="axa-quick"
                          onClick={() => quick(acct.email)}
                          title={`Fill the form with ${acct.email}`}
                        >
                          <span className="axa-quick-label">{acct.label}</span>
                          <span className="axa-quick-mail">{acct.email}</span>
                        </button>
                        <button
                          type="button"
                          className="axa-info"
                          aria-label={`What differs about the ${acct.label} demo account`}
                          aria-expanded={open}
                          title="What differs about this account"
                          onClick={() => setInfoFor(open ? null : acct.email)}
                        >
                          <InfoIcon />
                        </button>
                      </div>
                      {open && (
                        <div className="axa-points">
                          <p>{acct.summary}</p>
                          <ul>
                            {acct.points.map((p) => (
                              <li key={p}>{p}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </div>
      </div>
    </div>
  );
}

import { FormEvent, useState } from 'react';
import { Link } from 'react-router-dom';
// Self-hosted Figtree, as the sign-in card beside it — never a Google Fonts link.
import '@fontsource-variable/figtree';
import { api } from '../../lib/api';
import { cleanEmailDraft, isEmail, EMAIL_MAX } from '../../lib/sanitize';
import './AuthAstryx.scss';

/**
 * `/forgot-password` — ask for a reset link. The card is the sign-in card's own
 * component language (AuthAstryx.scss), so the two read as one flow.
 *
 * The API answers the same way whether or not the address has an account, so
 * this page never learns which emails exist.
 */
export default function ForgotPassword() {
  const [email, setEmail] = useState('');
  /** Set when the reader leaves the field: a half-typed address is not called
      wrong, but one left behind that the rule refuses says so at once. */
  const [emailTouched, setEmailTouched] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState<{ message: string } | null>(null);

  // The address is read on every keystroke, so a malformed one never becomes a
  // request; the hint waits for a blur so a half-typed address is not wrong yet.
  const emailOk = isEmail(email);
  const badEmail = emailTouched && email.length > 0 && !emailOk;

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setErr(null);
    if (!emailOk) {
      setErr('Enter a valid email address.');
      setEmailTouched(true);
      return;
    }
    setBusy(true);
    try {
      const res = await api.post<{ devLink?: string }>('/auth/forgot-password', { email });
      if (!res.success) {
        setErr(res.message);
        return;
      }
      setSent({ message: res.message });
    } catch {
      setErr('Could not reach the server. Try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="axa-page">
      <div className="axa-wrap">
        <div className="axa-col">
          <section className="axa-card">
            <header className="axa-head">
              <h1>Forgot password</h1>
              <p>We email a link to set a new one.</p>
            </header>

            {err && <p className="axa-alert bad">{err}</p>}

            {sent ? (
              <>
                <p className="axa-alert ok">{sent.message}</p>
                <div className="axa-foot">
                  <Link className="axa-switch" to="/login">
                    Back to sign in
                  </Link>
                </div>
              </>
            ) : (
              <>
                <form onSubmit={submit} className="axa-form">
                  <div className="axa-field">
                    <label htmlFor="email">Email</label>
                    <input
                      id="email"
                      type="email"
                      autoComplete="username"
                      placeholder="riley@example.com"
                      value={email}
                      maxLength={EMAIL_MAX}
                      onChange={(e) => {
                        setEmail(cleanEmailDraft(e.target.value));
                        setErr(null);
                      }}
                      onBlur={() => setEmailTouched(true)}
                      required
                      aria-invalid={badEmail || undefined}
                      aria-describedby={badEmail ? 'email-hint' : undefined}
                    />
                    {badEmail && (
                      <p id="email-hint" className="axa-hint is-warn" role="alert">
                        Enter a valid email address.
                      </p>
                    )}
                  </div>
                  <button className="primary axa-submit" disabled={busy}>
                    {busy ? 'Sending…' : 'Send reset link'}
                  </button>
                </form>

                <div className="axa-foot">
                  <Link className="axa-switch" to="/login">
                    Back to sign in
                  </Link>
                </div>
              </>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

import { FormEvent, useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '@fontsource-variable/figtree';
import { api } from '../../lib/api';
import PasswordField from '../../components/PasswordField/PasswordField';
import './AuthAstryx.scss';

/**
 * `/reset-password?token=…` — the page a reset link lands on.
 *
 * The token is checked before the fields are drawn, so an expired link says so
 * instead of collecting a password it would then refuse. Spending the link signs
 * nothing in as a shortcut: the rider signs in afterwards with the new password
 * (the reset drops every existing session).
 */
export default function ResetPassword() {
  const navigate = useNavigate();
  const token = new URLSearchParams(window.location.search).get('token') ?? '';

  const [state, setState] = useState<'checking' | 'invalid' | 'form' | 'done'>('checking');
  const [email, setEmail] = useState<string | null>(null);
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let live = true;
    if (!token) {
      setState('invalid');
      return;
    }
    api
      .get<{ valid: boolean; email?: string }>(`/auth/reset-password/${encodeURIComponent(token)}`)
      .then((res) => {
        if (!live) return;
        if (res.success && res.data?.valid) {
          setEmail(res.data.email ?? null);
          setState('form');
        } else {
          setState('invalid');
        }
      })
      .catch(() => live && setState('invalid'));
    return () => {
      live = false;
    };
  }, [token]);

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setErr(null);
    if (password !== confirm) {
      setErr('Passwords do not match.');
      return;
    }
    setBusy(true);
    try {
      const res = await api.post('/auth/reset-password', { token, password });
      if (!res.success) {
        setErr(res.message);
        return;
      }
      setState('done');
      // Sign in on the new password; the reset cannot carry a session itself.
      setTimeout(() => navigate('/login', { replace: true }), 1600);
    } catch {
      setErr('Could not reach the server. Try again.');
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="axa-page">
      <div className="axa-wrap">
        <div className="axa-col">
          <section className="axa-card">
            <header className="axa-head">
              <h1>New password</h1>
              <p>{email ? `For ${email}.` : 'Set a new password for your account.'}</p>
            </header>

            {err && <p className="axa-alert bad">{err}</p>}

            {state === 'checking' && <p className="axa-alert">Checking the link…</p>}

            {state === 'invalid' && (
              <>
                <p className="axa-alert bad">
                  This reset link has expired or was already used.
                </p>
                <div className="axa-foot">
                  <Link className="axa-switch" to="/forgot-password">
                    Send a new link
                  </Link>
                </div>
              </>
            )}

            {state === 'done' && (
              <>
                <p className="axa-alert ok">Password updated. Sign in with the new one.</p>
                <div className="axa-foot">
                  <Link className="axa-switch" to="/login">
                    Back to sign in
                  </Link>
                </div>
              </>
            )}

            {state === 'form' && (
              <>
                <form onSubmit={submit} className="axa-form">
                  <div className="axa-field">
                    <label htmlFor="password">New password</label>
                    <PasswordField
                      id="password"
                      autoComplete="new-password"
                      placeholder="8+ characters"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      required
                    />
                  </div>
                  <div className="axa-field">
                    <label htmlFor="confirm">Confirm password</label>
                    <PasswordField
                      id="confirm"
                      autoComplete="new-password"
                      placeholder="Repeat password"
                      value={confirm}
                      onChange={(e) => setConfirm(e.target.value)}
                      required
                    />
                  </div>
                  <button className="primary axa-submit" disabled={busy}>
                    {busy ? 'Saving…' : 'Set password'}
                  </button>
                </form>

                <div className="axa-foot">
                  <Link className="axa-switch" to="/login">
                    Back to sign in
                  </Link>
                </div>
              </>
            )}
          </section>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import '@fontsource-variable/figtree';
import { useAuth, homePathFor } from '../../lib/auth';
import './AuthAstryx.scss';

/**
 * `/verify-email` — the step between signing up and signing in.
 *
 * Two shapes on one route:
 *   ?token=…   the link a rider opened from their inbox. The token is spent on
 *              mount; success sets the session server-side, so this page lands
 *              the rider on their own home rather than a sign-in form.
 *   no token   the card a fresh signup is sent to: the address it is waiting on
 *              and a resend button.
 */
/**
 * How long the card's resend button stays shut after a link was asked for.
 *
 * The server holds the real brake (a per-account gap plus a daily ceiling) and
 * answers a throttled request with the same copy as a sent one, so a button that
 * stayed live would just look broken: the rider clicks, reads "on its way", and
 * no mail arrives. This mirrors the window so the click cannot happen. It is
 * kept per address in localStorage, so a reload does not reopen it, and the
 * server's own `cooldownMs` overrides the default when the reply carries one.
 */
const RESEND_COOLDOWN_KEY = (email: string) => `motopass:verifyResend:${email.toLowerCase()}`;
const DEFAULT_COOLDOWN_MS = 70_000; // 1 min 10 s, matching the server's gap

/** Raw stored deadline for this address, `0` when none is stored or storage is blocked. */
function storedUntil(email: string | null): number {
  if (!email) return 0;
  try {
    const until = Number(window.localStorage.getItem(RESEND_COOLDOWN_KEY(email)) ?? 0);
    return Number.isFinite(until) ? until : 0;
  } catch {
    // A browser with storage blocked just loses the reload-proof part.
    return 0;
  }
}

/** Milliseconds left on the stored window for this address, `0` when it is open. */
function storedCooldown(email: string | null): number {
  const until = storedUntil(email);
  return until > Date.now() ? until - Date.now() : 0;
}

/** `m:ss` — the countdown on the button. */
function clock(ms: number): string {
  const total = Math.ceil(ms / 1000);
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}

export default function VerifyEmail() {
  const navigate = useNavigate();
  const location = useLocation() as {
    state?: { email?: string; cooldownMs?: number };
  };
  const { verifyEmail, resendVerification, user, loading } = useAuth();

  const token = new URLSearchParams(window.location.search).get('token') ?? '';
  /** The address the signup is waiting on: the query the auth page sent, or the
      state it carried, so the card can name it and the resend can reach it. */
  const email =
    new URLSearchParams(window.location.search).get('email') ?? location.state?.email ?? null;

  const [state, setState] = useState<'checking' | 'invalid' | 'waiting' | 'done'>(
    token ? 'checking' : 'waiting'
  );
  const [err, setErr] = useState<string | null>(null);
  const [resent, setResent] = useState<{ text: string; wait: boolean } | null>(null);
  const [busy, setBusy] = useState(false);
  /** Deadline held in memory, for the browsers where storage is blocked. */
  const memUntil = useRef(0);
  /** Milliseconds left before another link may be asked for, `0` when open. */
  const [cooldown, setCooldown] = useState(() => {
    const stored = storedCooldown(email);
    const seeded = location.state?.cooldownMs ?? 0;
    // A fresh signup arrives with the window the mail it just triggered opened.
    // History state outlives a reload, so it is spent once: seeding on top of a
    // window already on record would restart the countdown on every refresh.
    if (seeded > 0 && storedUntil(email) === 0) {
      memUntil.current = Date.now() + seeded;
      try {
        if (email) {
          window.localStorage.setItem(RESEND_COOLDOWN_KEY(email), String(memUntil.current));
        }
      } catch {
        // Storage blocked: the in-memory window still holds for this page.
      }
      return seeded;
    }
    return stored;
  });

  /** Tick the countdown; a `set` with an unchanged number does not re-render. */
  useEffect(() => {
    const id = setInterval(
      () => setCooldown(Math.max(storedCooldown(email), memUntil.current - Date.now(), 0)),
      1000
    );
    return () => clearInterval(id);
  }, [email]);

  /** Spend the seeded window out of history state: a reload must not open a new one. */
  useEffect(() => {
    if (!location.state?.cooldownMs) return;
    navigate(`${window.location.pathname}${window.location.search}`, {
      replace: true,
      state: { email: location.state.email },
    });
  }, [location.state, navigate]);

  /** The token is spent once, whatever the render count — a StrictMode double
      mount must not burn it twice. */
  const spent = useRef(false);

  useEffect(() => {
    if (!token || spent.current) return;
    spent.current = true;
    let live = true;
    verifyEmail(token)
      .then((error) => {
        if (!live) return;
        if (error) {
          setErr(error);
          setState('invalid');
        } else {
          setState('done');
        }
      })
      .catch(() => live && setState('invalid'));
    return () => {
      live = false;
    };
  }, [token, verifyEmail]);

  /** A confirmed link is a finished signup: the session is already set. */
  useEffect(() => {
    if (state !== 'done' || loading) return;
    const timer = setTimeout(() => navigate(user ? homePathFor(user.role) : '/login', { replace: true }), 1400);
    return () => clearTimeout(timer);
  }, [state, loading, user, navigate]);

  const resend = async () => {
    if (!email || busy || cooldown > 0) return;
    setErr(null);
    setResent(null);
    setBusy(true);
    const result = await resendVerification(email);
    setBusy(false);
    if (result.error) {
      setErr(result.error);
      return;
    }
    // The reply carries the window whether or not a mail actually went out, so
    // the button shuts either way: a throttled request then reads as "wait",
    // never as a send that silently did nothing.
    const waitMs = result.cooldownMs ?? DEFAULT_COOLDOWN_MS;
    memUntil.current = Date.now() + waitMs;
    try {
      window.localStorage.setItem(RESEND_COOLDOWN_KEY(email), String(memUntil.current));
    } catch {
      // Storage blocked: the in-memory window still holds for this page.
    }
    setCooldown(waitMs);
    setResent({
      text: result.message ?? 'A new link is on its way.',
      wait: result.wait === true,
    });
  };

  const resendLabel = busy
    ? 'Sending…'
    : cooldown > 0
      ? `Send a new link in ${clock(cooldown)}`
      : 'Send a new link';

  return (
    <div className="axa-page">
      <div className="axa-wrap">
        <div className="axa-col">
          <section className="axa-card">
            <header className="axa-head">
              <h1>Confirm your email</h1>
              <p>
                {email
                  ? `Waiting on ${email}.`
                  : 'Open the link we mailed you to finish setting up your account.'}
              </p>
            </header>

            {err && <p className="axa-alert bad">{err}</p>}

            {state === 'checking' && <p className="axa-alert">Confirming the link…</p>}

            {state === 'waiting' && (
              <>
                {/* A sent resend turns the standing notice green in place; the
                    reply's own copy would only repeat what the notice says. A
                    throttle is different copy, so it still prints below. */}
                <p className={resent && !resent.wait ? 'axa-alert ok' : 'axa-alert'}>
                  A verification email has been sent.
                  <br />
                  Open the link in the email to sign in.
                </p>
                {resent?.wait && <p className="axa-alert">{resent.text}</p>}
                <div className="axa-form">
                  <button
                    type="button"
                    className="primary axa-submit"
                    onClick={resend}
                    disabled={busy || !email || cooldown > 0}
                  >
                    {resendLabel}
                  </button>
                </div>
              </>
            )}

            {state === 'invalid' && (
              <>
                <p className="axa-alert bad">
                  This confirmation link has expired or was already used.
                </p>
                <div className="axa-form">
                  <button
                    type="button"
                    className="primary axa-submit"
                    onClick={resend}
                    disabled={busy || !email || cooldown > 0}
                  >
                    {resendLabel}
                  </button>
                  {resent && (
                    <p className={resent.wait ? 'axa-alert' : 'axa-alert ok'}>{resent.text}</p>
                  )}
                </div>
              </>
            )}

            {state === 'done' && (
              <p className="axa-alert ok">Email confirmed. You are signed in.</p>
            )}

            <div className="axa-foot">
              <Link className="axa-switch" to="/login">
                Back to sign in
              </Link>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

/* AstryxLanding — styles owned by AstryxLanding.tsx (the `/` page while
   `enableAstryxUI` is on).

   The page carries its own token block, scoped to `.ax-page`, so the register
   it borrows from the reference design system (surfaces, type ramp, radii,
   spacing steps) never leaks into the rest of the app. Nothing here writes to
   `:root` except the light-theme override, which is scoped to this page too.

   Every class is `ax-`prefixed for the same reason: global.scss already owns
   `.card`, `.pill`, `.row` and friends, and this page must not fight them. */

.ax-page {
  /* Surfaces — the reference system's dark values, one step each. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* The accent is Moto Pass's own orange, on the reference system's
     accent / on-accent / tint trio. */
  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-ink: #0a1317;
  /* The saving badge's ground on the billing segmented control. */
  --ax-accent-tint: rgba(242, 121, 2, 0.2);

  /* Live status tints. */
  --ax-ok-ink: #a5f690;
  --ax-ok-tint: rgba(36, 187, 94, 0.2);
  --ax-warn-ink: #fbce03;
  --ax-warn-tint: rgba(226, 164, 0, 0.22);

  /* Counts wear the house chip: stone ground, 4px radius. */
  --ax-chip-bg: #d6d3d1;
  --ax-chip-ink: #1c1917;

  /* Radii. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-page: 32px;
  --ax-r-pill: 999px;

  /* Type ramp. Each step is ≥1.25 over the last: 13 / 16 / 20 / 25 / 31 / 39 / 49. */
  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;
  --ax-fs-base: 16px;
  --ax-fs-lg: 20px;
  --ax-fs-xl: 25px;
  --ax-fs-2xl: 31px;
  --ax-fs-3xl: 39px;
  --ax-fs-4xl: 49px;

  /* Spacing steps (the reference system counts in 6s). */
  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;
  --ax-s-5: 30px;
  --ax-s-6: 36px;
  --ax-s-8: 48px;
  --ax-s-10: 60px;
  --ax-s-12: 72px;

  --ax-e-fast: 100ms;
  --ax-e-med: 250ms;
  /* Floating layers only. */
  --ax-shadow: 0 4px 6px rgba(0, 0, 0, 0.35), 0 12px 24px rgba(0, 0, 0, 0.45);

  /* Edge to edge, out of <main>'s 1550px column, and up over the header: the
     page cancels <main>'s 22px top padding and the sticky header's own height
     (measured into `--header-h` by client/index.html), and its foot cancels
     <main>'s 60px bottom padding so the last band meets the footer. */
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-top: calc(-22px - var(--header-h, 57px));
  margin-bottom: -60px;

  background: var(--ax-body);
  color: var(--ax-ink);
  font-family: 'Figtree Variable', Figtree, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-base);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  transition: background var(--ax-e-med) ease;
}

/* The app's own light palette, restated for this page's surfaces. */
:root[data-theme='light'] .ax-page {
  --ax-body: #f1f4f7;
  --ax-surface: #ffffff;
  --ax-raised: #ffffff;
  --ax-line: rgba(5, 54, 89, 0.1);
  --ax-line-strong: #ccd3db;

  --ax-ink: #0a1317;
  --ax-ink-2: #4e606f;
  --ax-ink-3: #a4b0bc;

  --ax-accent: #eb6e00;
  --ax-accent-edge: #b34a01;
  /* Dark ink on the burnt orange: white would sit at ~3:1 on this ground. */
  --ax-accent-ink: #1a0d03;
  --ax-accent-tint: rgba(235, 110, 0, 0.1);

  --ax-ok-ink: #09441f;
  --ax-ok-tint: rgba(36, 187, 94, 0.16);
  --ax-warn-ink: #753f07;
  --ax-warn-tint: rgba(226, 164, 0, 0.18);

  --ax-shadow: 0 4px 6px rgba(5, 54, 89, 0.08), 0 12px 24px rgba(5, 54, 89, 0.14);
}

.ax-page ::selection {
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
}

.ax-page :focus-visible {
  outline: 2px solid var(--ax-accent);
  outline-offset: 2px;
  border-radius: var(--ax-r-inner);
}

.ax-page h1,
.ax-page h2,
.ax-page h3 {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.ax-page p {
  margin: 0;
}

.ax-page img {
  display: block;
  max-width: 100%;
}

.ax-shell {
  width: 100%;
  max-width: 1240px;
  margin-inline: auto;
  padding-inline: var(--ax-s-6);
}

/* Only for the spoken ticket sentence — the visible "× 2" has no words. */
.ax-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ------------------------------------------------------------------ controls */

.ax-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ax-s-2);
  height: 40px;
  padding: 0 var(--ax-s-4);
  border: 0;
  border-radius: var(--ax-r-pill);
  font-family: inherit;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: opacity var(--ax-e-fast) ease, background-color var(--ax-e-fast) ease;
}

.ax-btn:hover {
  opacity: 0.85;
}

.ax-primary {
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
}

.ax-quiet {
  background: var(--ax-surface);
  color: var(--ax-ink);
  box-shadow: inset 0 0 0 1px var(--ax-line);
}

.ax-ghost {
  background: transparent;
  color: var(--ax-ink);
  box-shadow: inset 0 0 0 1px var(--ax-line-strong);
}

.ax-btn[aria-disabled='true'] {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ------------------------------------------------------------------- the badge */

/* The venue's live line, over the bottom-left corner of its own photograph. */
.ax-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 9px;
  border-radius: var(--ax-r-pill);
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
  /* Over a photograph, so the pill carries its own opaque ground rather than a
     tint the picture reads through. */
  background: rgba(15, 17, 20, 0.82);
}

.ax-badge i {
  width: 6px;
  height: 6px;
  border-radius: var(--ax-r-pill);
  background: currentColor;
  flex: none;
}

.ax-badge-open {
  color: #8ef2a4;
}

.ax-badge-hold {
  color: #ffd166;
}

.ax-badge-shut {
  color: #d5d9de;
}

/* --------------------------------------------------------------- the tickets */

.ax-tickets {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--ax-fs-xs);
  font-variant-numeric: tabular-nums;
  color: var(--ax-ink-2);
}

.ax-tickets .day-ticket {
  width: 15px;
  height: 15px;
  color: var(--ax-ink-2);
}

.ax-ticket-x {
  opacity: 0.75;
}

.ax-ticket-n {
  color: var(--ax-ink);
  font-weight: 600;
}

/* The same count as a badge on a tile's photograph: the live-line pill's own
   opaque ground and white ink, so the picture never reads through it. */
.ax-tickets-badge {
  gap: 2px;
  padding: 3px 9px;
  border-radius: var(--ax-r-pill);
  font-weight: 600;
  line-height: 1.4;
  color: var(--ax-ink);
  background: rgba(15, 17, 20, 0.82);
}

.ax-tickets-badge .day-ticket {
  width: 15px;
  height: 15px;
  color: var(--ax-ink);
}

.ax-tickets-badge .ax-ticket-x {
  opacity: 0.6;
}

/* --------------------------------------------------------------------- hero */

/* First screen: one photograph, edge to edge, the whole viewport tall. The
   page already starts at the viewport's top edge (see `.ax-page`), so the
   picture runs under the sticky header and down to the fold — the bar sits on
   the image rather than above it. */
.ax-hero {
  position: relative;
  display: grid;
  min-height: 100svh;
  isolation: isolate;
  overflow: hidden;
  background: #0d0e10;
}

/* The photograph, pinned to the band rather than laid out in it: the copy and
   the cards are what give the band its height, so the picture always fills
   whatever they need. */
.ax-hero-media {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.ax-hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 42%;
}

/* Ink over a photograph, in both themes: the scrim is painted here rather than
   borrowed from a surface token, and it darkens the left (the statement) and
   the foot (the cards) while leaving the riders over the middle readable. */
.ax-hero-scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      to bottom,
      rgba(9, 11, 13, 0.62) 0%,
      rgba(9, 11, 13, 0.18) 24%,
      rgba(9, 11, 13, 0.12) 46%,
      rgba(9, 11, 13, 0.72) 78%,
      rgba(9, 11, 13, 0.93) 100%
    ),
    linear-gradient(
      to right,
      rgba(9, 11, 13, 0.8) 0%,
      rgba(9, 11, 13, 0.5) 36%,
      rgba(9, 11, 13, 0.1) 64%,
      rgba(9, 11, 13, 0) 82%
    );
  pointer-events: none;
}

/* The band's own content: the statement on the left, the live cards along the
   photograph's foot on the right. */
.ax-hero-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  align-items: end;
  gap: var(--ax-s-8);
  min-height: 100svh;
  padding-top: calc(var(--header-h, 57px) + var(--ax-s-10));
  padding-bottom: var(--ax-s-10);
}

/* The floating cards are off (`enableAxFloats`, flag id `ax-floats`): the band
   keeps the statement and the photograph and drops the cards' column, so the
   statement is not held away from the middle by an empty 300px track. */
.ax-hero-no-floats .ax-hero-inner {
  grid-template-columns: minmax(0, 1fr);
}

/* The first screen is pinned, not scrolled away: the band holds at the viewport
   top while the sheet after it (.ax-flow) rides up and covers it, so the next
   elements overlap and hide the hero. Only above 720 — a band taller than the
   viewport would pin its own foot out of reach, so narrow screens scroll it as
   they always did. */
@media (min-width: 721px) {
  .ax-hero {
    position: sticky;
    top: 0;
    z-index: 0;
  }
}

/* Everything past the hero: one opaque sheet on the page ground. It is what
   hides the pinned hero — the rounded top edge cuts the hero off as it rises,
   and the ground behind the corners is the hero still sitting there. */
.ax-flow {
  position: relative;
  z-index: 1;
  background: var(--ax-body);
  border-radius: var(--ax-r-page) var(--ax-r-page) 0 0;
  /* Room under the last sheet so the closing band clears the footer by a band
     step, not a hairline. The close band's own 24px margin collapses out of the
     flow, so the padding here is what holds the page's foot open. */
  padding-bottom: var(--ax-s-12);
}

/* The statement sits on the photograph's left half, its own ink supplied here
   so neither theme's palette can wash it out. */
.ax-hero-copy {
  align-self: center;
  max-width: 620px;
}

.ax-hero h1 {
  max-width: 16ch;
  color: #ffffff;
  font-size: clamp(var(--ax-fs-3xl), 4.4vw, var(--ax-fs-4xl));
  text-shadow: 0 1px 24px rgba(0, 0, 0, 0.45);
  text-wrap: balance;
}

.ax-lede {
  max-width: 62ch;
  font-size: var(--ax-fs-lg);
  color: var(--ax-ink-2);
}

/* `.ax-page p` (0,1,1) beats a bare `.ax-lede` on specificity, so the hero's
   own lede has to carry its container to win a margin. It also hangs one step
   closer to the statement than the actions do, so the heading and its support
   line read as one block and the CTA row sits a step further out — equal 30px
   gaps above and below flattened that hierarchy. */
.ax-hero .ax-lede {
  margin: var(--ax-s-4) auto 0;
  color: rgba(255, 255, 255, 0.88);
  margin-inline: 0;
  text-shadow: 0 1px 14px rgba(0, 0, 0, 0.55);
}

.ax-acts {
  display: flex;
  gap: var(--ax-s-2);
  justify-content: flex-start;
  /* The pair stays on one line; when the column can't hold both pills they
     wrap, each at its own label width. */
  flex-wrap: wrap;
  margin-top: var(--ax-s-5);
}

/* Over the picture the quiet button is glass, not a themed surface: a solid
   card ground would read as a floating panel pasted on the photograph. */
.ax-hero .ax-quiet {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.32);
  backdrop-filter: blur(8px);
}

.ax-hero .ax-quiet:hover {
  background: rgba(255, 255, 255, 0.2);
  opacity: 1;
}

/* ------------------------------------------------------------- floating cards */

/* Dormant while `enableAxFloats` is off (flag id `ax-floats`): the markup is
   still here in `AstryxLanding.tsx`, so these rules are kept as they were and
   come back with the flag. */

/* The live read over the photograph's foot: one column at the right, floating
   layers by elevation rather than by edge. */
.ax-floats {
  display: flex;
  flex-direction: column;
  gap: var(--ax-s-2);
  align-items: stretch;
  justify-self: end;
  width: 100%;
}

.ax-float {
  display: grid;
  gap: 3px;
  background: var(--ax-surface);
  border-radius: var(--ax-r-container);
  box-shadow: var(--ax-shadow);
  padding: var(--ax-s-3);
  animation: ax-rise 600ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* A short window cannot hold three cards beside the statement without pushing
   the pinned hero past the fold: the venue's photograph goes first, then the
   events card, so the two figures that matter survive. */
@media (min-width: 1081px) and (max-height: 840px) {
  .ax-floats .ax-float-shot {
    display: none;
  }
}

@media (min-width: 1081px) and (max-height: 700px) {
  .ax-floats .ax-float-events {
    display: none;
  }
}

.ax-float-venue {
  animation-delay: 60ms;
}

.ax-float-days {
  animation-delay: 140ms;
}

.ax-float-events {
  animation-delay: 100ms;
}

@keyframes ax-rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ax-float {
    animation: none;
  }
}

.ax-float-shot {
  display: block;
  border-radius: var(--ax-r-element);
  overflow: hidden;
  aspect-ratio: 16 / 9;
  max-height: 137px;
  flex: 0 1 auto;
  min-height: 0;
  margin-bottom: var(--ax-s-1);
}

.ax-float-shot img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ax-float-title {
  font-size: var(--ax-fs-base);
  font-weight: 600;
}

.ax-float-sub {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

.ax-float-label {
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  color: var(--ax-ink-3);
}

.ax-float-row {
  display: flex;
  align-items: center;
  gap: var(--ax-s-2);
  margin-top: var(--ax-s-1);
  flex-wrap: wrap;
}

.ax-float-row.ax-between {
  justify-content: space-between;
  margin-top: 0;
}

.ax-float-note {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

.ax-mini-list {
  list-style: none;
  margin: var(--ax-s-1) 0 0;
  padding: 0;
  display: grid;
  gap: var(--ax-s-1);
}

.ax-mini-list li {
  display: grid;
  gap: 1px;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

.ax-mini-list b {
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  color: var(--ax-ink);
}

/* --------------------------------------------------------------------- bands */

.ax-band {
  padding: var(--ax-s-12) 0;
}

/* The hero's "Learn more" lands on the pass-includes band, clear of the
   sticky header. */
#pass-includes {
  scroll-margin-top: calc(var(--header-h, 57px) + var(--ax-s-4));
}

/* A page-radius surface on the body ground: the widest bands sit one step up
   from the page, so the page reads as a stack of sheets. The sheet is inset to
   the content column instead of bleeding to the viewport edges. */
.ax-band-surface {
  background: var(--ax-surface);
  border-radius: var(--ax-r-page);
  width: calc(100% - 2 * var(--ax-s-4));
  max-width: 1240px;
  margin: var(--ax-s-4) auto;
}

/* The network sheet keeps the full page width: it is the widest wall on the
   page, so it stays flush with the viewport rather than insetting. */
.ax-band-surface.ax-band-wide {
  width: 100%;
  max-width: none;
  margin: var(--ax-s-4) 0;
}

/* The close band is the last sheet on the page: it keeps the shared band
   padding so its bottom edge matches the other sheets. */
.ax-close-band {
  margin-bottom: var(--ax-s-10);
}

.ax-band-head {
  max-width: 720px;
}

.ax-band h2 {
  font-size: var(--ax-fs-3xl);
}

.ax-note {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

/* -------------------------------------------------------------- the wall */

.ax-wall {
  margin-top: var(--ax-s-8);
  display: grid;
  gap: var(--ax-s-3);
  grid-template-columns: repeat(auto-fill, minmax(212px, 1fr));
}

.ax-tile {
  display: block;
  color: inherit;
  text-decoration: none;
}

.ax-tile-shot {
  position: relative;
  display: block;
  border-radius: var(--ax-r-element);
  overflow: hidden;
  aspect-ratio: 16 / 9;
  background: var(--ax-body);
}

.ax-tile-shot img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* The venue's line and its day count sit as one row of badges on the
   photograph's bottom-left, not in the caption. */
.ax-tile-badges {
  position: absolute;
  left: 8px;
  bottom: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.ax-tile:hover .ax-tile-name {
  color: var(--ax-accent);
}

.ax-tile-cap {
  display: grid;
  gap: 3px;
  padding-top: var(--ax-s-2);
}

.ax-tile-name {
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  transition: color var(--ax-e-fast) ease;
}

.ax-tile-where {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ax-s-2);
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

.ax-tile-place {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* The presale wall's empty tile: the same photograph well and caption slot,
   with no venue behind them. It is a stand-in, so it carries no hover state
   and takes no pointer. */
.ax-tile-placeholder {
  cursor: default;
}

.ax-tile-placeholder .ax-tile-shot {
  background: var(--ax-surface);
  box-shadow: inset 0 0 0 1px var(--ax-line);
}

.ax-tile-placeholder .ax-tile-name {
  color: var(--ax-ink-3);
  font-weight: 500;
}

/* ------------------------------------------------------------ the held pass */

.ax-inside {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: var(--ax-s-10);
  align-items: start;
}

/* A glow under the badge, drifting a few pixels rather than travelling the
   border. It sits behind the card's own ground, so only what spills past the
   edge shows, and it is offset low so the light reads as coming from below. */
.ax-member {
  position: relative;
  align-self: center;
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  padding: var(--ax-s-5);
}

/* The broad pool: the light's body, swaying the width of the card's foot. */
.ax-member::before {
  content: '';
  position: absolute;
  inset: 12% -10px -20px;
  z-index: -1;
  border-radius: inherit;
  background:
    radial-gradient(54% 58% at 38% 84%, rgba(255, 138, 63, 0.6), transparent 72%),
    radial-gradient(42% 50% at 70% 96%, rgba(255, 138, 63, 0.4), transparent 74%);
  filter: blur(16px);
  opacity: 0.9;
  pointer-events: none;
  animation: ax-member-drift 9s ease-in-out infinite;
}

/* The hotspot: a tighter, brighter lamp under the card's foot that crosses the
   wide glow the other way, so the light visibly travels rather than breathing. */
.ax-member::after {
  content: '';
  position: absolute;
  inset: 46% -6px -12px;
  z-index: -1;
  border-radius: inherit;
  background: radial-gradient(34% 52% at 32% 78%, rgba(255, 176, 120, 0.55), transparent 70%);
  filter: blur(13px);
  opacity: 0.75;
  pointer-events: none;
  animation: ax-member-cross 7s ease-in-out infinite;
}

@keyframes ax-member-drift {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
  }
  25% {
    transform: translate3d(-30px, 8px, 0) scale(0.97);
  }
  50% {
    transform: translate3d(0, 0, 0) scale(1.01);
  }
  75% {
    transform: translate3d(30px, -8px, 0) scale(1.04);
  }
}

@keyframes ax-member-cross {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
  }
  25% {
    transform: translate3d(46px, 4px, 0) scale(1.06);
  }
  50% {
    transform: translate3d(0, 0, 0) scale(1.02);
  }
  75% {
    transform: translate3d(-46px, -2px, 0) scale(0.95);
  }
}

/* Still light: both layers hold where they are, under the card. */
@media (prefers-reduced-motion: reduce) {
  .ax-member::before,
  .ax-member::after {
    animation: none;
  }
}

.ax-member-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ax-s-3);
}

.ax-member-tier {
  font-size: var(--ax-fs-lg);
  font-weight: 600;
}

.ax-member-chip {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-pill);
  padding: 3px 10px;
}

/* The holder's identity row, under the card's own hairline. */
.ax-member-holder {
  display: flex;
  align-items: center;
  gap: var(--ax-s-3);
  margin-top: var(--ax-s-5);
  padding-top: var(--ax-s-5);
  border-top: 1px solid var(--ax-line);
}

.ax-member-avatar {
  flex: none;
  width: 88px;
  height: 88px;
  border-radius: var(--ax-r-pill);
  object-fit: cover;
  background: var(--ax-surface);
  box-shadow: inset 0 0 0 1px var(--ax-line);
}

.ax-member-id {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.ax-member-name {
  font-size: var(--ax-fs-xl);
  font-weight: 600;
}

.ax-member-where {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

.ax-list,
.ax-ticks {
  list-style: none;
  margin: var(--ax-s-4) 0 0;
  padding: 0;
  display: grid;
  gap: var(--ax-s-2);
}

.ax-list li,
.ax-ticks li {
  display: flex;
  gap: var(--ax-s-2);
  font-size: var(--ax-fs-base);
}

.ax-list svg,
.ax-ticks svg {
  flex: none;
  margin-top: 5px;
  color: var(--ax-accent);
}

.ax-ticks li {
  font-size: var(--ax-fs-sm);
}

.ax-ticks svg {
