export type AuthMode = 'login' | 'register';

/** The control a failure notice blames; `credentials` marks both sign-in
    fields, because the API never says which one was wrong. */
type ErrField = 'email' | 'password' | 'confirm' | 'agree' | 'credentials';

/** The refusal notice's own id — the same one `AuthAstryx` uses, since only one
    of the pair is mounted at a time. */
const NOTICE_ID = 'auth-notice';

