/** The phone's rule: optional, but a number that is written has to be a number
    the API will take (`zPhone`: 7 to 15 digits, spaces and + ( ) - . allowed). */
const PHONE_MESSAGE = 'Enter a phone number with 7 to 15 digits.';
const PHONE_HINT_ID = 'phone-hint';

/**
 * One auth page, mounted twice: `/login` (mode="login") and `/signup`
 * (mode="register"). The mode is the route's, not state — switching pages
 * changes the URL, so each form has its own address and the browser's back
 * button works between them.
 */
export default function Login({ mode }: { mode: AuthMode }) {
  const [name, setName] = useState('');
  /** Optional, as `registerSchema` has it: the gate can find a rider by phone. */
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  /** The consent line is a gate, not decoration: registering needs it ticked. */
  const [agree, setAgree] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [errField, setErrField] = useState<ErrField | null>(null);
  /** The notice's own key: a live region only speaks when its node is inserted
      or its text changes, so a repeat of the same failure has to remount it. */
  const [errSeq, setErrSeq] = useState(0);
  /** Set once the reader leaves the email field: from then on an invalid
      address states itself instead of waiting for a submit. */
  const [emailTouched, setEmailTouched] = useState(false);
  /** The same for the optional phone: quiet until it is left, then its rule. */
  const [phoneTouched, setPhoneTouched] = useState(false);
  const [busy, setBusy] = useState(false);
  const [infoFor, setInfoFor] = useState<string | null>(null);
  const { login, register, user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation() as { state?: { from?: string } };

  const [redirect, setRedirect] = useState<string | null>(null);

  /**
   * `?next=` is how a banner deep-links back here (the returning Stripe
   * checkout is the one that needs it: its session id has to survive the
   * sign-in or the pass never activates). Only a same-origin path is honoured.
   */
  const nextParam = new URLSearchParams(window.location.search).get('next');
  const safeNext = nextParam && nextParam.startsWith('/') && !nextParam.startsWith('//') ? nextParam : null;
  const nextQuery = safeNext ? `?next=${encodeURIComponent(safeNext)}` : '';

  /** The return trip after a rider closes their account. */
  const deletedNotice = new URLSearchParams(window.location.search).get('deleted') === '1';

  /** The other half of the pair, carrying any deep link across. */
  const otherHref = mode === 'login' ? `/signup${nextQuery}` : `/login${nextQuery}`;

  // Old `?mode=register` links (pricing CTAs, bookmarks) predate `/signup`.
  const legacyRegister =
    mode === 'login' && new URLSearchParams(window.location.search).get('mode') === 'register';

  useEffect(() => {
    if (user) setRedirect(safeNext ?? homePathFor(user.role));
  }, [user, safeNext]);

  if (redirect) return <Navigate to={redirect} replace />;
  if (legacyRegister) return <Navigate to={`/signup${nextQuery}`} replace />;

  /**
   * One place to raise a failure, so the notice can never be silent or leave
   * the control it blames unmarked: the message goes into an alerting Banner,
   * and the field named here carries `aria-invalid` + `aria-describedby`.
   */
  const fail = (message: string, field: ErrField | null) => {
    setErr(message);
    setErrField(field);
    setErrSeq((n) => n + 1);
  };

  /** A cleared notice is a cleared blame — never a stale red field. */
  const clearErr = () => {
    setErr(null);
    setErrField(null);
  };

  /** Editing the field a notice blames puts the notice away. */
  const editedField = (...fields: ErrField[]) => {
    if (errField && fields.includes(errField)) clearErr();
  };

  /**
   * Signup is a gate, not a suggestion. Every rule the API enforces is read
   * here, on every keystroke: the CTA stays disabled and `submit()` refuses
   * until all of them hold. Phone is optional by design (`registerSchema`).
   */
  const emailOk = isEmail(email);
  /** Optional by design: blank is fine, anything written must be a number. */
  const phoneOk = isPhone(phone);
  const canSubmit =
    mode === 'login' ||
    (name.trim().length > 0 &&
      emailOk &&
      phoneOk &&
      password.length >= 8 &&
      confirm === password &&
      agree);

  /* The rule the field states under itself, as the password hints do, rather
     than in the card notice — that one stays for what the server said. */
  const emailRuleBad = emailTouched && email.length > 0 && !emailOk;
  const phoneRuleBad = phoneTouched && phone !== '' && !phoneOk;

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    clearErr();
    // The CTA is disabled while the form is incomplete; this is the backstop
    // for a submit that arrives anyway (implicit Enter, autofill, stale render).
    if (!canSubmit) return;
    // The address is checked on both modes, so a malformed one never reaches the
    // API: sign-in sends whatever is typed even though its CTA stays live.
    // The rule reads under the field, so a submit only has to make sure it is
    // showing — the card notice stays for what the server said.
    if (!emailOk) {
      setEmailTouched(true);
      return;
    }
    // Same for the optional phone: a number that was written has to be one.
    if (!phoneOk) {
      setPhoneTouched(true);
      return;
    }
    // Registering states both rules while typing; these are the backstop for a
    // submit that never touched the hint (paste + Enter, autofill).
    if (mode !== 'login' && password.length < 8) {
      fail('Use at least 8 characters.', 'password');
      return;
    }
    // Registering types the password twice; a mismatch never reaches the API.
    if (mode !== 'login' && password !== confirm) {
      fail('Passwords do not match.', 'confirm');
      return;
    }
    // Consent is checked here, not by a native `required` tooltip, so the
    // answer lands in the card's own notice slot.
    if (mode !== 'login' && !agree) {
      fail('Agree to the Terms and Privacy policy to continue.', 'agree');
      return;
    }
    setBusy(true);
    if (mode === 'login') {
      const result = await login(email, password);
      setBusy(false);
      if (result.error) {
        // The password was right but the address is still unconfirmed: that is
        // a step to finish, not a refusal, so it goes to the step.
        if (result.needsVerification) {
          navigate(`/verify-email?email=${encodeURIComponent(email)}`);
          return;
        }
        // A refused sign-in blames both fields (the API does not say which); a
        // refused registration stays a notice only, since the server may refuse
        // for the name, the email or the password and a wrong mark is worse
        // than none.
        return fail(result.error, 'credentials');
      }
    } else {
      const result = await register(name, email, password, phone);
      setBusy(false);
      if (result.error) return fail(result.error, null);
      // Signing up is not signing in: the account waits on the mailed link.
      navigate(`/verify-email?email=${encodeURIComponent(email)}`, {
        state: { email, devLink: result.devLink, cooldownMs: result.cooldownMs },
      });
      return;
    }
    // A deep link wins; otherwise the role's own home takes over below
    // (an operator's is /scan, a rider's /tracks) — never a hardcoded path.
    const from = location.state?.from ?? safeNext ?? undefined;
    if (from) navigate(from, { replace: true });
  };

  const quick = (e: string) => {
    setEmail(e);
    setPassword('dialed123');
    // The confirmation only appears once a password exists, so a demo fill has
    // to answer it too — otherwise the CTA stays refused behind a hidden field.
    setConfirm('dialed123');
    // A demo fill answers the notice, so it must not leave a field marked.
    clearErr();
  };

  /* Registering only asks for the password twice once there is a password to
     repeat: the field stays out of the way (and out of the tab order) until the
     first character lands in the field above it. */
  const showConfirm = mode !== 'login' && password.length > 0;

  /* The rule the API enforces (`registerSchema`: min 8) and the pair check, both
     read while typing rather than only at submit. The mismatch waits until the
     second field is at least as long as the first. */
  const tooShort = mode !== 'login' && password.length > 0 && password.length < 8;
  const mismatch =
    mode !== 'login' && confirm.length > 0 && confirm.length >= password.length && password !== confirm;

  /* The notice is the fields' description while it stands, so a reader who
     tabs back into the form hears why it refused. */
  const badEmail = errField === 'email' || errField === 'credentials' || emailRuleBad;
  const badPassword = errField === 'password' || errField === 'credentials';
  const badConfirm = errField === 'confirm';
  const badAgree = errField === 'agree';
  const described = (...ids: (string | null | undefined)[]) =>
    ids.filter(Boolean).join(' ') || undefined;

  return (
    <div style={{ maxWidth: 520, margin: '0 auto' }} className="stack">
      <div className="card stack">
        <div>
          <h1 style={{ fontSize: 22 }}>{mode === 'login' ? 'Sign in' : 'Create account'}</h1>
        </div>

        {deletedNotice && <Banner tone="ok" close>Account deleted. The email is free to register again.</Banner>}
        {err && (
          <Banner key={errSeq} id={NOTICE_ID} tone="bad" close>
            {err}
          </Banner>
        )}

        <form onSubmit={submit} className="stack">
          {mode === 'register' && (
            <div>
              <label htmlFor="name">Name</label>
              <input
                id="name"
                autoComplete="name"
                placeholder="Riley"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />
            </div>
          )}
          <div>
            <label htmlFor="email">Email</label>
            <input
              id="email"
              type="email"
              autoComplete="username"
              placeholder="riley@example.com"
              value={email}
              maxLength={EMAIL_MAX}
              onChange={(e) => {
                setEmail(cleanEmailDraft(e.target.value));
                editedField('email', 'credentials');
              }}
              onBlur={() => setEmailTouched(true)}
              required
              aria-invalid={badEmail || undefined}
              aria-describedby={described(
                emailRuleBad ? EMAIL_HINT_ID : null,
                errField === 'email' || errField === 'credentials' ? NOTICE_ID : null,
              )}
            />
            {emailRuleBad && (
              <p id={EMAIL_HINT_ID} className="tiny bad" role="alert" style={{ marginTop: 6 }}>
                {EMAIL_MESSAGE}
              </p>
            )}
          </div>
          {mode === 'register' && (
            <div>
              <label htmlFor="phone">
                Phone <span className="tiny muted">(Optional)</span>
              </label>
              <input
                id="phone"
                type="tel"
                inputMode="tel"
                autoComplete="tel"
                placeholder="(828) 555-0142"
                value={phone}
                onChange={(e) => formatPhoneInput(e.target, setPhone)}
                onBlur={() => setPhoneTouched(true)}
                aria-invalid={phoneRuleBad || undefined}
                aria-describedby={phoneRuleBad ? PHONE_HINT_ID : undefined}
              />
              {phoneRuleBad && (
                <p id={PHONE_HINT_ID} className="tiny bad" role="alert" style={{ marginTop: 6 }}>
                  {PHONE_MESSAGE}
                </p>
              )}
            </div>
          )}
          <div>
            <div className="row spread">
              <label htmlFor="password">Password</label>
              {mode === 'login' && (
                <Link to="/forgot-password" className="tiny muted">
                  Forgot password?
                </Link>
              )}
            </div>
            <PasswordField
              id="password"
              autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
              placeholder="Your password"
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                // Emptying the field withdraws the confirmation with it, so a
                // stale repeat can never ride along into the submit.
                if (e.target.value === '') setConfirm('');
                editedField('password', 'credentials');
              }}
              required
              ariaInvalid={tooShort || badPassword}
              ariaDescribedBy={described(
                badPassword ? NOTICE_ID : null,
                mode === 'login' ? null : 'password-hint',
              )}
            />
            {mode === 'register' && (
              <p
                id="password-hint"
                className={`tiny ${tooShort ? 'bad' : 'muted'} hint-check-row`}
                style={{ marginTop: 6 }}
              >
                <span
                  className="hint-check"
                  data-met={password.length >= 8 || undefined}
                  aria-hidden="true"
                >
                  <svg viewBox="0 0 20 20" fill="none" focusable="false">
                    <path
                      d="M4.5 10.6 8.2 14.3 15.5 6"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                </span>
                8 characters minimum.
              </p>
            )}
          </div>
          {showConfirm && (
            <div>
              <label htmlFor="confirm">Confirm password</label>
              <PasswordField
                id="confirm"
                autoComplete="new-password"
                placeholder="Repeat password"
                value={confirm}
                onChange={(e) => {
                  setConfirm(e.target.value);
                  editedField('confirm');
                }}
                required
                ariaInvalid={mismatch || badConfirm}
                ariaDescribedBy={described(
                  badConfirm ? NOTICE_ID : null,
                  mismatch ? 'confirm-hint' : null,
                )}
              />
              {mismatch && (
                <p id="confirm-hint" className="tiny bad" role="alert" style={{ marginTop: 6 }}>
                  Passwords do not match.
                </p>
              )}
            </div>
          )}
          {mode === 'register' && (
            <div className="row" style={{ gap: 8, alignItems: 'flex-start' }}>
              <input
                id="agree"
                type="checkbox"
                checked={agree}
                onChange={(e) => {
                  setAgree(e.target.checked);
                  editedField('agree');
                }}
                aria-invalid={badAgree || undefined}
                aria-describedby={badAgree ? NOTICE_ID : undefined}
                style={{ width: 16, height: 16, margin: '3px 0 0', accentColor: 'var(--accent)' }}
              />
              <label htmlFor="agree" className="tiny muted" style={{ margin: 0 }}>
                By creating an account you agree to the{' '}
                <Link to="/terms">Terms</Link> and <Link to="/privacy">Privacy policy</Link>
              </label>
            </div>
          )}
          <button
            className="primary"
            disabled={busy || !canSubmit}
          >
            {busy ? 'Working…' : mode === 'login' ? 'Sign in' : 'Create account'}
          </button>
        </form>

        <button
          className="ghost small"
          onClick={() => {
            clearErr();
            navigate(otherHref);
          }}
        >
          {mode === 'login' ? 'Need an account? Register' : 'Already have an account? Sign in'}
        </button>
      </div>

      {/* Demo accounts are sign-in aids, so they ride the sign-in page only. */}
      {mode === 'login' && (
        <div className="card">
          <div className="row spread" style={{ marginBottom: 10 }}>
            <h3 style={{ margin: 0 }}>Demo accounts</h3>
            <span className="tiny muted">
              password <span className="mono">dialed123</span>
            </span>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
            {signupDemoAccounts.map((acct) => {
              const open = infoFor === acct.email;
              return (
                <div
                  key={acct.email}
                  style={{
                    border: `1px solid ${open ? 'var(--accent-2)' : 'var(--line)'}`,
                    borderRadius: 'var(--radius)',
                    background: 'var(--bg-3)',
                  }}
                >
                  <div className="row" style={{ gap: 4, alignItems: 'stretch' }}>
                    <button
                      className="ghost small"
                      style={{ flex: 1, textAlign: 'left', border: 0, padding: '8px 10px' }}
                      onClick={() => quick(acct.email)}
                      title={`Fill the form with ${acct.email}`}
                    >
                      <div>{acct.label}</div>
                      <div className="tiny muted mono">{acct.email}</div>
                    </button>
                    <button
                      className="ghost"
                      style={{ border: 0, padding: '8px 10px', color: open ? 'var(--accent-2)' : 'var(--muted)' }}
                      aria-label={`What differs about the ${acct.label} demo account`}
                      aria-expanded={open}
                      title="What differs about this account"
                      onClick={() => setInfoFor(open ? null : acct.email)}
                    >
                      <InfoIcon />
                    </button>
                  </div>
                  {open && (
                    <div
                      style={{
                        padding: '8px 10px 10px',
                        borderTop: '1px solid var(--line)',
                      }}
                    >
                      <div className="tiny" style={{ color: 'var(--text)' }}>
                        {acct.summary}
                      </div>
                      <ul
                        className="tiny muted"
                        style={{ margin: '6px 0 0', paddingLeft: 15, listStyleType: 'disc' }}
                      >
                        {acct.points.map((p) => (
                          <li key={p} style={{ marginTop: 3 }}>
                            {p}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

/* OperatorCalendar — styles owned by OperatorCalendar.tsx.
   Split out of styles/global.scss; imported once from OperatorCalendar.tsx and
   still plain global class names (this app uses no CSS modules). */

/* What a date only sometimes carries — its kind, a run past the day — reads a
   shade back from the three the sentence above them answers. */
.ev-label-quiet { color: var(--muted); }

.ev-control {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
  background: none;
  border: 0;
  padding: 10px 0;
  color: var(--text);
}

.ev-control::placeholder { color: var(--muted); }

.ev-icon { flex: 0 0 auto; color: var(--muted); }

/* The well's glyph is the picker: the browser's own mark would be a second one
   in the same corner, and the field is one line of text without it. */
.ev-control::-webkit-calendar-picker-indicator { display: none; }

/* The name row carries a control of its own, so the field gives it the room. */
.ev-desc-add {
  flex: 0 0 auto;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 7px 12px;
  white-space: nowrap;
}

/* A drop-down keeps the well's own edges — the chevrons beside it are its mark. */
.ev-well-select select { appearance: none; -webkit-appearance: none; padding-right: 4px; }

@media (max-width: 640px) {
  .ev-control { font-size: 16px; }
}

import { ReactNode, MouseEvent as ReactMouseEvent, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import Banner from '../../../components/Banner/Banner';
import ConfirmSheet from '../../../components/ConfirmSheet/ConfirmSheet';
import WeekGrid, { SlotDraft, SlotEdge } from '../../../components/WeekGrid/WeekGrid';
import { api } from '../../../lib/api';
import { cleanLine, cleanMultiline } from '../../../lib/sanitize';
import { useAuth } from '../../../lib/auth';
import CalendarSkeleton from '../../../components/CalendarSkeleton/CalendarSkeleton';
import {
  EVENT_KINDS,
  EVENT_KIND_OPTION,
  ampmLabel,
  ampmTime,
  clockTime,
  dayKey,
  dayRange,
  daysOf,
  minutesOf,
  stepWeek,
  timeValue,
  weekStart,
} from '../../../lib/events';
import './OperatorCalendar.scss';

/**
 * The owner's calendar page — where a venue's season is actually written.
 *
 * The profile page reads the schedule; this page edits it, and it reads as a
 * week: an all-day row over an hour grid, a date drawn where its own hours put
 * it, and that week's dates as cards underneath — each card a line of text that
 * opens the fields in a sheet when it is clicked. The calendar used to be a
 * month grid, so the page kept a month of dates in front of the owner; a week
 * is what an owner actually looks at when a weekend is what they are filling.
 *
 * The owner is the OPERATOR pinned to the venue, so the page reads and writes
 * only that track; an ADMIN has no pinned track, so it gets a venue picker and
 * edits on the venue's behalf through `?trackId=` — the same shape as the
 * profile console.
 */
interface TrackEvent {
  id: string;
  title: string;
  description: string | null;
  kind: string;
  startsAt: string;
  endsAt: string | null;
  startMinutes: number | null;
  endMinutes: number | null;
  isActive: boolean;
}

interface OwnerTrack {
  id: string;
  slug: string;
  name: string;
  events: TrackEvent[];
}

/** A new date opens a week out, and reads as a gate day until it is timed. */
const blankEvent = () => ({
  title: '',
  kind: 'PRACTICE',
  startsAt: new Date(Date.now() + 6048e5).toISOString().slice(0, 10),
  endsAt: '',
  startTime: '09:00',
  endTime: '16:00',
  description: '',
  isActive: true,
});

const dayValue = (iso: string | null) => (iso ? iso.slice(0, 10) : '');

/**
 * The fields Save posts, normalised the way the API reads them. Two events
 * with the same shape send the same request, so comparing the shapes is how
 * the Edit sheet knows the owner has actually changed something.
 */
const eventShape = (e: TrackEvent) =>
  JSON.stringify({
    title: e.title,
    kind: e.kind,
    startsAt: dayValue(e.startsAt),
    endsAt: e.endsAt ? dayValue(e.endsAt) : '',
    startMinutes: e.startMinutes ?? null,
    endMinutes: e.endMinutes ?? null,
    description: e.description ?? '',
    isActive: e.isActive,
  });

/**
 * The Add sheet's fields, normalised the same way, so "the owner typed
 * something" is a comparison against the state the sheet opened on.
 */
const addShape = (e: ReturnType<typeof blankEvent>) =>
  JSON.stringify({
    title: e.title,
    kind: e.kind,
    startsAt: e.startsAt,
    endsAt: e.endsAt,
    startTime: e.startTime,
    endTime: e.endTime,
    description: e.description,
    isActive: e.isActive,
  });

/* ---- The sheet's own furniture ---------------------------------------- */

/** `3h 45m`, `45m`, `2h` — how long a gate runs, the short way. */
function spanLabel(minutes: number) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return [h ? `${h}h` : '', m ? `${m}m` : ''].filter(Boolean).join(' ');
}

/** The length a pair of hours adds up to, or `null` when it carries none. */
function eventSpan(from: number | null, to: number | null) {
  return from != null && to != null && to > from ? to - from : null;
}

/**
 * What the description toggle reads — one action, named for the state the field
 * is in: a note that is out is put away, a note that only lives on the date is
 * called up, and an empty one is asked for.
 */
function descToggleLabel(open: boolean, hasText: boolean) {
  if (open) return 'Hide description';
  return hasText ? 'Show description' : 'Add description';
}

/** `May 15, 2023` — a day as the sheet's own sentence names it. */
function longDay(day: string) {
  return new Date(`${day}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

/**
 * The fields read back as one sentence — the owner's own words for what the
 * date, the hour and the length add up to, so a wrong duration is visible
 * before it posts rather than on the calendar afterwards.
 */
function eventSentence(day: string, through: string, from: number | null, to: number | null) {
  if (!day) return 'Pick a date to put this event on the calendar.';
  if (through && through > day) {
    return (
      <>
        This event runs from <b>{longDay(day)}</b> until <b>{longDay(through)}</b>
        {from != null && to != null && to > from ? (
          <>
            , <b>{ampmTime(from)}–{ampmTime(to)}</b>
          </>
        ) : null}
        .
      </>
    );
  }
  if (from == null || to == null) {
    return (
      <>
        This event will take place on <b>{longDay(day)}</b>, all day.
      </>
    );
  }
  return (
    <>
      This event will take place on <b>{longDay(day)}</b> from <b>{ampmTime(from)}</b> until{' '}
      <b>{ampmTime(to)}</b>.
    </>
  );
}

/** One 16px grid for the sheet's glyphs — the app's own icon set, drawn out. */
function FormIcon({ children }: { children: ReactNode }) {
  return (
    <svg
      className="ev-icon"
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

/** The Date field's mark. */
