  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.axn-page .axn-hero-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(9, 10, 11, 0.92) 0%,
    rgba(9, 10, 11, 0.7) 46%,
    rgba(9, 10, 11, 0.32) 100%
  );
}

.axn-page .axn-hero-inner {
  position: relative;
  width: 100%;
  padding: var(--ax-s-6);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--ax-s-2);
}

.axn-page .axn-hero h1 {
  margin: 0;
  max-width: 22ch;
  font-size: var(--ax-fs-3xl);
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.1;
  color: #f4f6f8;
}

.axn-page .axn-hero-lede {
  margin: 0;
  max-width: 58ch;
  font-size: var(--ax-fs-base);
  line-height: 1.6;
  color: rgba(244, 246, 248, 0.8);
}

.axn-page .axn-hero-acts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--ax-s-3);
  margin-top: var(--ax-s-2);
}

/* ---- The terms row ------------------------------------------------------ */
.axn-page .axn-terms {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
