.axn-page .axn-terms li {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: var(--ax-s-4) var(--ax-s-5);
}

.axn-page .axn-terms li + li {
  border-left: 1px solid var(--ax-line);
}

.axn-page .axn-terms-figure {
  font-size: var(--ax-fs-xl);
  font-weight: 600;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.axn-page .axn-terms-label {
  font-size: var(--ax-fs-sm);
  color: var(--ax-ink-2);
}

/* ---- Section heads ------------------------------------------------------ */
.axn-page .axn-head {
  margin-bottom: var(--ax-s-4);
}

.axn-page .axn-head h2 {
  margin: 0;
  font-size: var(--ax-fs-2xl);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.15;
}

.axn-page .axn-head-lede {
  margin: var(--ax-s-1) 0 0;
