/* Pricing — styles owned by Pricing.tsx.
   Split out of styles/global.scss; imported once from Pricing.tsx and
   still plain global class names (this app uses no CSS modules). */

/* A hover names its track; a click opens the rail panel. */
/* ---- Pricing ------------------------------------------------------------
   A headed band carrying a small audience toggle, then either the plan
   columns (riders) or the partner notes (tracks). */
.pricing-band {
  background: var(--bg-3);
  border-radius: 12px;
  padding: 30px 22px 26px;
  text-align: center;
}

.pricing-band h1 { font-size: 30px; letter-spacing: -0.03em; }

.pricing-band .lede {
  font-size: 13px;
  color: var(--muted);
  margin: 10px auto 0;
  max-width: 62ch;
}

/* The billing term is a switch, not a pill row: one label either side of a
   track, the thumb resting on the term in force. The two labels are the real
   controls (`aria-pressed`); the track between them only reports which one is
   on, so it takes no pointer events of its own. */
.billing-toggle.billing-switch {
  display: flex;
  width: fit-content;
  margin-inline: auto;
  align-items: center;
  gap: 12px;
}

.billing-switch .bs-opt {
  padding: 4px 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
}

.billing-switch .bs-opt:hover:not(:disabled) { opacity: 1; color: var(--text); }

/* The term in force reads in body ink, the other stays a quiet label — the
   switch's own read of the raised thumb, so the pair never looks like two
   pressable chips. */
.billing-switch .bs-opt[aria-pressed='true'] { color: var(--text); font-weight: 700; }

.billing-switch .bs-opt .pill-save {
  margin-left: 8px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
  color: var(--accent);
}

.billing-switch .bs-opt:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 2px; }

.billing-switch .bs-track {
  position: relative;
  display: block;
  width: 44px;
  height: 22px;
  padding: 0;
  background: var(--bg-3);
  border: 1px solid var(--pill-line);
  border-radius: 999px;
}

/* The track is live: it is the switch, so it takes the pointer and answers the
   keyboard like the labels do. Hover keeps the track's own weight rather than
   dimming the whole control. */
.billing-switch .bs-track:hover:not(:disabled) { opacity: 1; border-color: var(--muted); }

.billing-switch .bs-track:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 2px; }

/* The thumb is placed, not laid out: the two terms are two positions of one
   element, so the change between them is a slide rather than a jump. 22px is
   the track's inner width (44 − 2 × 1px border − 2 × 2px inset) less the 16px
   thumb. */
.billing-switch .bs-thumb {
  position: absolute;
  top: 50%;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--pill-thumb);
  box-shadow: var(--pill-thumb-shadow);
  transform: translateY(-50%);
  transition: transform 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.billing-switch .bs-track[data-side='annual'] .bs-thumb { transform: translate(22px, -50%); }

/* The labels move with it: the term in force takes the body ink as the thumb
   arrives, the one it left fades back to a quiet label. */
.billing-switch .bs-opt { transition: color 0.2s ease; }

@media (prefers-reduced-motion: reduce) {
  .billing-switch .bs-thumb { transition: none; }
}

/* Partner sheet: contract levers, the server's scan order, and what a track
   gets — as labelled lists rather than another column of cards. */
.track-sheet { padding: 22px; }

.track-sheet .sheet-lead {
  font-size: 13px;
  color: var(--muted);
  margin: 0 0 22px;
  max-width: 78ch;
}

.track-sheet .sheet-cols { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }

.track-sheet .sheet-cols > * { min-width: 0; }

.track-sheet .sheet-cols > * + * {
  border-left: 1px solid var(--line);
  margin-left: 30px;
  padding-left: 30px;
}

.track-sheet .sheet-col section + section {
  border-top: 1px solid var(--line);
  margin-top: 22px;
  padding-top: 18px;
}

.track-sheet h2 { font-size: 14px; margin: 0 0 10px; }

.track-sheet .note { font-size: 12px; color: var(--muted); margin: 0 0 12px; max-width: 48ch; }

.spec-list { margin: 0; }

.spec-list > div { display: grid; grid-template-columns: minmax(0, 176px) minmax(0, 1fr); gap: 16px; padding: 7px 0; }

.spec-list > div + div { border-top: 1px solid var(--line); }

.spec-list dt { font-size: 13px; font-weight: 600; }

.spec-list dd { margin: 0; font-size: 13px; color: var(--muted); max-width: 72ch; }

.step-list { list-style: none; margin: 0; padding: 0; }

.step-list li {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 8px;
  padding: 8px 0;
  font-size: 13px;
}

.step-list li + li { border-top: 1px solid var(--line); }

.step-list .n {
  color: var(--accent);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* The plan row, after the reference layout: a level card on the left and the
   pass you buy raised on the right. `.pricing-grid` keeps the room the raised
   card takes above the row, and the two cards sit at their own heights rather
   than stretching to match — the overhang is the whole point of the pair. */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  max-width: 1000px;
  margin-inline: auto;
  padding-top: var(--tier-lift, 28px);
  align-items: start;
}

.tier-card {
  display: flex;
  flex-direction: column;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

/* The free tier is the level one: it recedes onto its own dull surface, keeps
   its hairline and takes no shadow, so it never competes with the pass. Its
   figure is a step down from the paid card's too — the same hierarchy the
   reference draws between the two plans. */
.tier-card.free { background: var(--tier-level-bg); }

.tier-card.free .tier-price .amount { font-size: 34px; }

/* The paid pass is the raised one — it reaches up out of the row, runs past the
   level card's foot, and sits on a real shadow. The accent edge stays. */
.tier-card.popular {
  margin-top: calc(var(--tier-lift, 28px) * -1);
  padding-bottom: var(--tier-lift, 28px);
  border-color: var(--accent);
  box-shadow: var(--shadow-card);
}

.tier-body { display: flex; flex-direction: column; gap: 14px; padding: 24px; flex: 1; }

.tier-head { text-align: left; }

.tier-head h2 { font-size: 18px; margin: 0; text-align: left; letter-spacing: -0.01em; }

.tier-price { text-align: left; }

/* The price and its term read as one line, the term small beside the figure. */
.tier-price .price-row { display: flex; align-items: baseline; gap: 8px; }

.tier-price .amount {
  font-size: 38px;
  font-weight: 700;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

/* A price the card has replaced — the presale's list price. Struck, muted and
   a step down, so the figure a rider pays reads first and the drop beside it
   still has something to be measured against. */
.tier-price .amount.was {
  font-size: 22px;
  font-weight: 600;
  color: var(--muted);
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}

.tier-price .unit { font-size: 11px; color: var(--muted); margin-top: 2px; }

/* The card's one action spans the card, as the reference's does, and the pass's
   own CTA carries the lift the raised card does. */
.tier-card .tier-cta { width: 100%; padding: 10px 14px; }

.tier-card.popular .tier-cta.primary { box-shadow: var(--shadow-cta); }

.tier-card.free .tier-cta { background: var(--bg-3); }

/* The hairline between the action and the list: the button belongs to the price
   above it, the bullets to the label below it. */
.tier-rule { height: 1px; background: var(--line); margin: 6px 0 0; }

.tier-includes { font-size: 12.5px; font-weight: 500; color: var(--muted); }

.tier-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }

.tier-list li { display: flex; gap: 11px; align-items: flex-start; font-size: 13px; }

/* The mark is a ringed tick, as the reference draws it: the check reads inside
   its own circle rather than loose in the row. */
.tier-list .tick {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  margin-top: 1px;
  color: var(--accent);
}

.tier-list .tick svg { width: 16px; height: 16px; display: block; }

/* The compare table: one column per plan, one row per capability, so the
   differences and the shared ground read at one glance. Row labels are the
   only words; the plan columns carry the mark, the value, or a quiet dash. */
.compare-block { display: flex; flex-direction: column; gap: 10px; }

.compare-table thead th { padding: 0 10px 8px; }

.compare-table tbody th,
.compare-table td {
  padding: 10px;
  border-top: 1px solid var(--line);
}

.compare-table th:first-child,
.compare-table td:first-child { padding-left: 0; }

.compare-table th:last-child,
.compare-table td:last-child { padding-right: 0; }

.compare-table thead th:not(:first-child) { text-align: center; color: var(--text); }

.compare-table tbody th {
  text-transform: none;
  letter-spacing: 0;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
}

.compare-table td {
  text-align: center;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.compare-table td svg { color: var(--accent); }

.compare-table .cmp-none { color: var(--muted); }

/* Stacked, the pair sits level again: no room to reach into, nothing to
     overhang. */
@media (max-width: 860px) {
  .pricing-grid { grid-template-columns: 1fr; --tier-lift: 0px; }
}

/* A rider on the free pass is not choosing it: on a phone the card drops to one
   quiet line that says the rider keeps it, so the paid pass owns the screen.
   The line is the only child of the card that survives this breakpoint. */
.tier-current { display: none; }

@media (max-width: 860px) {
  .tier-card.free.is-current .tier-body {
    gap: 0;
    padding: 12px 16px;
    justify-content: center;
  }

  .tier-card.free.is-current .tier-body > *:not(.tier-current) { display: none; }

  .tier-current {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 4px 8px;
  }

  .tier-current b { font-size: 13px; font-weight: 600; }

  .tier-current span { font-size: 12px; color: var(--muted); }
}

@media (max-width: 860px) {
  .track-sheet .sheet-cols { grid-template-columns: 1fr; }
}

@media (max-width: 860px) {
  .track-sheet .sheet-cols > * + * {
    border-left: 0;
    margin-left: 0;
    padding-left: 0;
    border-top: 1px solid var(--line);
    margin-top: 22px;
    padding-top: 20px;
  }
}

@media (max-width: 860px) {
  .spec-list > div { grid-template-columns: 1fr; gap: 4px; }
}

import { useEffect, useMemo, useState } from 'react';
import Banner from '../../components/Banner/Banner';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
import { api, money } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import { enablePartnerAudience } from '../../lib/featureFlags';
import { presaleSentence } from '../../lib/tierCopy';
import './Pricing.scss';

interface Tier {
  id: string;
  slug: string;
  name: string;
  tagline: string | null;
  description: string | null;
  priceCents: number;
  /** The monthly alternative to the annual price — display only. */
  monthlyPriceCents: number | null;
  earlyBirdPriceCents: number | null;
  earlyBirdStartsAt: string | null;
  earlyBirdEndsAt: string | null;
  twoYearPriceCents: number | null;
  extraDaysPerTrack: number;
  /** The free default a new account lands on. */
  isDefault: boolean;
}

interface TrackLite {
  includedDays: number;
  discountDayEnabled: boolean;
  discountRate: number | null;
}

type Audience = 'riders' | 'tracks';

/** Whole-dollar label for the headline price; falls back to cents when needed. */
function priceLabel(cents: number): string {
  return Number.isInteger(cents / 100) ? `$${cents / 100}` : money(cents);
}

function Check() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />
    </svg>
  );
}

/** Bullets each tier adds on top of the one below it. */
const ADDED: Record<string, string[]> = {
  free: [
    'Every partner track, with its live status and hours',
    'Follow the tracks you ride, and unfollow any time',
    'Upgrade mid-season, with the days applying right away',
  ],
  base: [
    '2 included days at every partner track',
    'An extra day at half price',
    'Walk-up entry at every venue in the network',
  ],
};

/** The levers a partner track sets in its own contract. */
const CONTROLS: { term: string; def: string }[] = [
  { term: 'Included days per pass', def: 'Per contract, per season.' },
  { term: 'Discounted extra day', def: 'Which day, and the rate.' },
  { term: 'Extra-day price', def: 'Your sticker price before discount.' },
];

/** The checks the server walks, in order, on every scan. */
const SCAN_ORDER = [
  'Code signature valid',
  'Code not expired',
  'Pass belongs to the rider',
  'Pass active and in season',
  'Not already redeemed here today',
  'Your track participates',
  'Free day, then discounted, then out of days',
];

export default function Pricing() {
  const [tiers, setTiers] = useState<Tier[]>([]);
  const [tracks, setTracks] = useState<TrackLite[]>([]);
  // `?for=tracks` opens straight on the partner sheet, so a track arriving from
  // the landing page's invitation doesn't land on the rider tiers first.
  const [params, setParams] = useSearchParams();
  const [audience, setAudience] = useState<Audience>(
    params.get('for') === 'tracks' ? 'tracks' : 'riders',
  );
  // Annual or monthly headline price on the rider cards; annual is the saving.
  const [billing, setBilling] = useState<'annual' | 'monthly'>('annual');
  const [busy, setBusy] = useState<string | null>(null);
  // Stripe's cancel_url lands here with `?checkout=cancelled`; the reader is told
  // nothing was charged, once, before the param is retired.
  const [note, setNote] = useState<string | null>(
    params.get('checkout') === 'cancelled' ? 'Checkout cancelled — nothing was charged.' : null,
  );
  const { user } = useAuth();
  const navigate = useNavigate();
  /**
   * The rider's own pass. Without it the page kept selling a card the account
   * already holds — a rider on the Moto Pass could press Buy pass again and be
   * charged for a second one.
   */
  const [myPass, setMyPass] = useState<{ tier: { id: string }; status: string } | null>(null);

  useEffect(() => {
    if (!user || user.role !== 'RIDER') {
      setMyPass(null);
      return;
    }
    let live = true;
    api
      .get<{ pass: { tier: { id: string }; status: string } | null }>('/me/pass')
      .then((r) => {
        if (live) setMyPass(r.data?.pass ?? null);
      });
    return () => {
      live = false;
    };
  }, [user]);

  useEffect(() => {
    api.get<{ tiers: Tier[] }>('/tiers').then((r) => setTiers(r.data?.tiers ?? []));
    // `terms=public`: this page's figures are the anonymous marketing copy, so
    // a free-tier rider reading it still sees the full day totals.
    api.get<{ tracks: TrackLite[] }>('/tracks?terms=public').then((r) => setTracks(r.data?.tracks ?? []));
  }, []);

  // Read the cancel word once, then retire the param: a refresh or a back-click
  // must not replay it.
  useEffect(() => {
    if (!params.has('checkout')) return;
    const next = new URLSearchParams(params);
    next.delete('checkout');
    setParams(next, { replace: true });
  }, [params, setParams]);

  const buy = async (tier: Tier) => {
    // The free tier is granted at sign-up, never bought.
    if (tier.isDefault) return navigate(user ? '/tracks' : '/signup');
    // Already held: send them to the pass rather than selling it twice.
    if (myPass?.status === 'ACTIVE' && myPass.tier.id === tier.id) return navigate('/tracks');
    // Signed out: no account to buy with, so open the register form (not the
    // sign-in fields) and come back here once the account exists.
    if (!user) return navigate('/signup', { state: { from: '/pricing' } });
    setBusy(tier.id);
    setNote(null);
    const res = await api.post<{
      url?: string;
      devMode?: boolean;
      paymentId?: string;
      message?: string;
    }>('/payments/checkout', { tierId: tier.id });
    setBusy(null);
    if (!res.success) return setNote(res.message);
    const d = res.data;
    if (d?.url) {
      window.location.href = d.url;
      return;
    }
    if (d?.devMode && d.paymentId) {
      const sim = await api.post(`/payments/dev/simulate/${d.paymentId}`);
      if (sim.success) {
        // Same return trip the real redirect takes, minus the session id, so the
        // confirmation and the pass re-read are exercised locally too.
        navigate('/tracks?checkout=success');
        return;
      }
      setNote(sim.message);
      return;
    }
    setNote(res.message);
  };

  const sellable = tiers;

  /**
   * Rideable days for one tier: the sum of the included days at every partner
   * track, plus its extra days at each of them.
   */
  const daysFor = (t: Tier) =>
    tracks.reduce((sum, x) => sum + (x.includedDays ?? 0), 0) + t.extraDaysPerTrack * tracks.length;

  /** Whether the presale rate is live right now. */
  const presaleActive = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    (!t.earlyBirdStartsAt || new Date(t.earlyBirdStartsAt) <= new Date()) &&
    (!t.earlyBirdEndsAt || new Date(t.earlyBirdEndsAt) > new Date());

  /** Whether the presale is announced but not open yet. */
  const presaleUpcoming = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    t.earlyBirdStartsAt != null &&
    new Date(t.earlyBirdStartsAt) > new Date();

  /**
   * The headline annual price a rider pays now — the presale rate while it runs,
   * and the same rate once the presale opens, so the card, the compare table and
   * the switch all quote one figure.
   */
  const annualPrice = (t: Tier) =>
    presaleActive(t) || presaleUpcoming(t) ? t.earlyBirdPriceCents! : t.priceCents;

  /**
   * What the billing pill names on its Annual side: the saving the annual price
   * carries against twelve monthly payments, counted off the one paid tier that
   * sells monthly (never hard-coded — the pill follows the contracts).
   */
  const annualSavePct = (() => {
    const t = sellable.find((x) => !x.isDefault && x.monthlyPriceCents != null);
    if (!t) return 0;
    const year = t.monthlyPriceCents! * 12;
    const pct = Math.round((1 - annualPrice(t) / year) * 100);
    return pct > 0 ? pct : 0;
  })();

  /**
   * One row per capability, one column per plan — every capability that differs
   * between the plans and every one they share, so the table is the whole pass
   * model rather than a highlights reel. `true` draws the mark, `false` the
   * quiet dash, a string is the value the plan actually carries. Listed in the
   * order the table reads below: shared rows first, then the deltas.
   */
  const compareRows: { label: string; cell: (t: Tier) => boolean | string }[] = [
    { label: 'Price per year', cell: (t) => (t.isDefault ? '$0' : priceLabel(annualPrice(t))) },
    { label: 'Rideable days across the network', cell: (t) => (t.isDefault ? '0' : String(daysFor(t))) },
    { label: 'Included days at every track', cell: (t) => !t.isDefault },
    { label: 'Member price on extra days', cell: (t) => !t.isDefault },
    {
      label: 'Extra days at every track',
      cell: (t) => (t.extraDaysPerTrack > 0 ? `+${t.extraDaysPerTrack}` : false),
    },
    { label: 'Live venue status and hours', cell: () => true },
    { label: 'Follow the tracks you ride', cell: () => true },
  ];

  /**
   * The rows every plan carries a mark on lead the table: what the pass always
   * gives sits above what the higher plans add. Derived from the live plans and
   * the capabilities themselves, so it holds when either changes.
   */
  const markedByEveryPlan = (row: { cell: (t: Tier) => boolean | string }) =>
    sellable.length > 0 && sellable.every((t) => row.cell(t) === true);
  const orderedCompareRows = [
    ...compareRows.filter(markedByEveryPlan),
    ...compareRows.filter((row) => !markedByEveryPlan(row)),
  ];

  /** Live figures quoted in the partner notes — never hard-coded. */
  const network = useMemo(() => {
    const count = tracks.length;
    const days = tracks.map((t) => t.includedDays);
    const rates = tracks
      .filter((t) => t.discountDayEnabled && t.discountRate != null)
      .map((t) => Math.round((t.discountRate ?? 0) * 100));
    return {
      count,
      dayMin: count ? Math.min(...days) : null,
      dayMax: count ? Math.max(...days) : null,
      rateMin: rates.length ? Math.min(...rates) : null,
      rateMax: rates.length ? Math.max(...rates) : null,
    };
  }, [tracks]);

  const controlRows = CONTROLS.map((row) => {
    if (row.term === 'Included days per pass' && network.dayMin != null) {
      return {
        ...row,
        def: `${row.def} ${network.dayMin} to ${network.dayMax} across the network.`,
      };
    }
    if (row.term === 'Discounted extra day' && network.rateMin != null) {
      const range =
        network.rateMin === network.rateMax
          ? `${network.rateMin}%`
          : `${network.rateMin}% to ${network.rateMax}%`;
      return { ...row, def: `${row.def} ${range} off today.` };
    }
    return row;
  });

  const gives: { term: string; def: string }[] = [
    { term: 'Gate station', def: "Scan, today's check-ins, and the attempt log." },
    { term: 'Reporting', def: 'Per-track redemptions and revenue; QuickBooks CSV or JSON.' },
    { term: 'Frozen counts', def: 'Rider days snapshot at activation; changes need a re-snapshot.' },
  ];

  const forTracks = audience === 'tracks';

  return (
    <div className="stack">
      <section className="pricing-band">
        <h1>{forTracks ? 'For partner tracks' : 'Upgrade your pass'}</h1>
        <p className="lede">
          {forTracks
            ? 'Brings riders to your gate, on terms you set.'
            : 'The Moto Pass adds included days and member pricing.'}
        </p>

        {enablePartnerAudience && (
          <div className="pill-toggle" role="group" aria-label="Who this page is for">
            <button aria-pressed={!forTracks} onClick={() => setAudience('riders')}>
              Riders
            </button>
            <button aria-pressed={forTracks} onClick={() => setAudience('tracks')}>
              Tracks
            </button>
          </div>
        )}
      </section>

      {forTracks ? (
        <>
          <section className="card track-sheet">
            <p className="sheet-lead">You collect the member price at the window.</p>

            <div className="sheet-cols">
              <div className="sheet-col">
                <section>
                  <h2>What you control</h2>
                  <dl className="spec-list">
                    {controlRows.map((row) => (
                      <div key={row.term}>
                        <dt>{row.term}</dt>
                        <dd>{row.def}</dd>
                      </div>
                    ))}
                  </dl>
                </section>

                <section>
                  <h2>What you get</h2>
                  <dl className="spec-list">
                    {gives.map((row) => (
                      <div key={row.term}>
                        <dt>{row.term}</dt>
                        <dd>{row.def}</dd>
                      </div>
                    ))}
                  </dl>
                </section>
              </div>

              <section>
                <h2>What the station checks</h2>
                <p className="note">In this order, every scan.</p>
                <ol className="step-list">
                  {SCAN_ORDER.map((step, i) => (
                    <li key={step}>
                      <span className="n" aria-hidden="true">
                        {i + 1}
                      </span>
                      {step}
                    </li>
                  ))}
                </ol>
              </section>
            </div>
          </section>

          <div className="row wrap">
            <Link to="/tracks">
              <button className="ghost">See the network</button>
            </Link>
            <Link to="/login">
              <button className="ghost">Operator sign in</button>
            </Link>
          </div>
        </>
      ) : (
        <>
          {/* The billing term reads as a switch: one label either side of a
              track, the thumb sitting on the term in force. Annual leads on the
              right because it is the default and the saving. */}
          <div className="billing-toggle billing-switch" role="group" aria-label="Billing period">
            <button
              className="bs-opt"
              aria-pressed={billing === 'monthly'}
              onClick={() => setBilling('monthly')}
            >
              <span className="pill-label">Monthly</span>
            </button>
            {/* The track is a real control too: a switch that flips the term,
                so pointing at the thing that *shows* the state also moves it. */}
            <button
              type="button"
              className="bs-track"
              role="switch"
              aria-checked={billing === 'annual'}
              aria-label="Bill annually"
              data-side={billing}
              onClick={() => setBilling(billing === 'annual' ? 'monthly' : 'annual')}
            >
              <span className="bs-thumb" aria-hidden="true" />
            </button>
            <button
              className="bs-opt"
              aria-pressed={billing === 'annual'}
              onClick={() => setBilling('annual')}
            >
              <span className="pill-label">Annual</span>
              {annualSavePct > 0 && <span className="pill-save">Save {annualSavePct}%</span>}
            </button>
          </div>

          <div className="pricing-grid">
            {sellable.map((t) => {
              const earlyActive = presaleActive(t);
              const upcoming = presaleUpcoming(t);
              const popular = t.slug === 'base';
              const monthly = billing === 'monthly' && !t.isDefault && t.monthlyPriceCents != null;
              /**
               * A presale rate on the annual term — live now, or announced and
               * yet to open. Either way the card sells the reduced figure and
               * names the list price it replaces.
               */
              const presale =
                !t.isDefault && !monthly && t.earlyBirdPriceCents != null && (earlyActive || upcoming);
              /** The struck list price the presale rate comes off. */
              const priceOffCents = presale ? t.priceCents - t.earlyBirdPriceCents! : 0;
              /** The presale sentence, in the wording the landing prints too. */
              const presaleLine = presaleSentence(priceLabel(priceOffCents));
              const priceCents = monthly ? t.monthlyPriceCents! : annualPrice(t);
              /** The paid card folds the free tier in as its first line. */
              const added = t.isDefault
                ? ADDED[t.slug] ?? []
                : ['All free pass attributes', ...(ADDED[t.slug] ?? [])];
              const freeTier = t.isDefault;
              /** This account already holds this card, so it is not for sale. */
              const held = !freeTier && myPass?.status === 'ACTIVE' && myPass.tier.id === t.id;
              /**
               * A signed-in rider always holds the free pass, since it is granted
               * at sign-up. On a phone that card is not a choice, so it collapses
               * to a line saying the rider keeps it and the paid pass leads.
               */
              const freeHeld = freeTier && user?.role === 'RIDER';

              return (
                <div
                  className={
                    popular
                      ? 'tier-card popular'
                      : freeHeld
                        ? 'tier-card free is-current'
                        : freeTier
                          ? 'tier-card free'
                          : 'tier-card'
                  }
                  key={t.id}
                >
                  <div className="tier-body">
                    {/* The only part of the free card a phone shows. */}
                    {freeHeld && (
                      <div className="tier-current">
                        <b>{t.name}</b>
                        <span>Your current pass.</span>
                      </div>
                    )}

                    <div className="tier-head">
                      <h2>{t.name}</h2>
                    </div>

                    <div className="tier-price">
                      <div className="price-row">
                        {priceOffCents > 0 && (
                          <s className="amount was">{priceLabel(t.priceCents)}</s>
                        )}
                        <span className="amount">{freeTier ? '$0' : priceLabel(priceCents)}</span>
                        <span className="unit">{monthly ? 'per month' : 'per year'}</span>
                      </div>
                      {priceOffCents > 0 && (
                        <div className="unit price-off">
                          {presaleLine.lead}
                          <span className="ok">{presaleLine.amount}</span>
                          {presaleLine.tail}
                        </div>
                      )}
                    </div>

                    <button
                      className={popular && !freeTier ? 'primary tier-cta' : 'ghost tier-cta'}
                      disabled={busy === t.id}
                      onClick={() => buy(t)}
                    >
                      {busy === t.id
                        ? 'Starting checkout…'
                        : held
                          ? 'Go to my pass'
                          : freeTier
                            ? user && user.role === 'RIDER'
                              ? 'Go to my pass'
                              : 'Create free account'
                            : 'Buy pass'}
                    </button>

                    {/* The rule the reference draws between the action and the
                        list: the button belongs to the price above it, the
                        bullets to the label below it. */}
                    <div className="tier-rule" aria-hidden="true" />

                    <div className="tier-includes">Includes:</div>

                    <ul className="tier-list">
                      {added.map((item) => (
                        <li key={item}>
                          <span className="tick" aria-hidden="true">
                            <Check />
                          </span>
                          <span>{item}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              );
            })}
          </div>

          <section className="compare-block">
            <h2>Compare</h2>
            <div className="table-scroll">
              <table className="compare-table">
                <thead>
                  <tr>
                    <th scope="col">Capability</th>
                    {sellable.map((t) => (
                      <th scope="col" key={t.id}>
                        {t.name}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {orderedCompareRows.map((row) => (
                    <tr key={row.label}>
                      <th scope="row">{row.label}</th>
                      {sellable.map((t) => {
                        const v = row.cell(t);
                        return (
                          <td key={t.id}>
                            {v === true ? (
                              <Check />
                            ) : v === false ? (
                              <span className="cmp-none" aria-label="Not included">
                                —
                              </span>
                            ) : (
                              <span className="cmp-val">{v}</span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          {note && <Banner tone="warn" close>{note}</Banner>}
        </>
      )}
    </div>
  );
}

/* PricingAstryx — styles owned by PricingAstryx.tsx (the `/pricing` page while
   `enableAstryxUI` is on).

   Same rules as AstryxLanding.scss: the register's tokens are declared scoped to
   `.axp-page`, never on `:root`, and every override is written through that
   wrapper so it out-specifies Pricing.scss's plain `.tier-card` / `.bs-opt`
   rules and global.scss's `.card` / `.primary` / `.ghost` base layer. The class
   hooks the pricing suite reads (`.tier-card`, `.amount`, `.price-off`,
   `.compare-table`, `.track-sheet` …) are kept from the previous page on
   purpose — this is a restyle, and the suite guards the restyle. */

.axp-page {
  /* Surfaces, one step each: page ground, band, raised card, and the dull
     surface the level (free) card sits on. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-level: #1a1b1d;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* Moto Pass's own orange, on the register's accent / edge / on-accent trio. */
  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-tint: rgba(242, 121, 2, 0.2);
  --ax-accent-ink: #0a1317;

  /* The amount saved is green, as it is on the shipped page. */
  --ax-ok: #4ade80;

  /* Radii, type ramp and spacing steps. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-page: 32px;
  --ax-r-pill: 999px;

  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;
  --ax-fs-base: 16px;
  --ax-fs-lg: 20px;
  --ax-fs-xl: 25px;
  --ax-fs-2xl: 31px;
  --ax-fs-3xl: 39px;

  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;
  --ax-s-5: 30px;
  --ax-s-6: 36px;

  --ax-shadow-card: 0 26px 60px rgba(0, 0, 0, 0.5);
  --ax-shadow-cta: 0 6px 16px rgba(0, 0, 0, 0.35);
  --ax-e-med: 250ms;

  /* The raised card's lift out of the row, as the shipped page draws it. */
  --tier-lift: 28px;

  color: var(--ax-ink);
  font-family: 'Figtree Variable', 'Figtree', system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-base);
  line-height: 1.5;
}

/* The page column. 1240 is the cap the landing's shell uses, so both pages of
   the register land on the same measure. */
.axp-page .axp-stack {
  display: flex;
  flex-direction: column;
  gap: var(--ax-s-6);
  max-width: 1240px;
  margin-inline: auto;
  padding-bottom: var(--ax-s-6);
}

/* ---- Section: the header band ------------------------------------------ */
.axp-page .axp-section {
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-page);
  padding: var(--ax-s-5) var(--ax-s-4) var(--ax-s-4);
  text-align: center;
}

.axp-page .axp-section h1 {
  margin: 0;
  font-size: var(--ax-fs-2xl);
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1.15;
}

.axp-page .axp-section .lede {
  margin: 10px auto 0;
  max-width: 62ch;
  font-size: var(--ax-fs-base);
  color: var(--ax-ink-2);
}

/* ---- Segmented Control: the billing term ------------------------------- */
/* The container is the pill; the segment in force is the raised thumb. The two
   segments are the real controls (`aria-pressed`), so the state is read off the
   button rather than a decorative track. */
.axp-page .billing-switch {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  width: fit-content;
  margin-inline: auto;
  padding: 3px;
  background: var(--ax-body);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-pill);
}

.axp-page .billing-switch .bs-opt {
  display: inline-flex;
  align-items: center;
  gap: var(--ax-s-1);
  height: 30px;
  padding: 0 var(--ax-s-3);
  background: transparent;
  border: 0;
  border-radius: var(--ax-r-pill);
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-sm);
  font-weight: 500;
  transition:
    background var(--ax-e-med),
    color var(--ax-e-med);
}

.axp-page .billing-switch .bs-opt:hover:not(:disabled) {
  opacity: 1;
  color: var(--ax-ink);
}

.axp-page .billing-switch .bs-opt[aria-pressed='true'] {
  background: #3a3c40;
  color: var(--ax-ink);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}

.axp-page .billing-switch .bs-opt:focus-visible {
  outline: 2px solid var(--ax-accent);
  outline-offset: 2px;
}

/* The saving rides inside the segment it belongs to, as a Badge. */
.axp-page .billing-switch .pill-save {
  display: inline-flex;
  align-items: center;
  height: 18px;
  padding: 0 7px;
  margin-left: 0;
  background: var(--ax-accent-tint);
  color: var(--ax-accent);
  border-radius: var(--ax-r-pill);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-transform: none;
  white-space: nowrap;
}

/* ---- Cards: one level, one raised -------------------------------------- */
.axp-page .pricing-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  width: 100%;
  max-width: 1000px;
  margin-inline: auto;
  padding-top: var(--tier-lift);
  align-items: start;
}

.axp-page .tier-card {
  display: flex;
  flex-direction: column;
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  overflow: hidden;
}

/* The free tier is the level one: it recedes onto its own dull surface and
   takes no shadow, so it never competes with the pass. */
.axp-page .tier-card.free {
  background: var(--ax-level);
}

/* The paid pass is the raised one — it reaches up out of the row, runs past the
   level card's foot and sits on a real shadow. The accent edge stays. */
.axp-page .tier-card.popular {
  margin-top: calc(var(--tier-lift) * -1);
  padding-bottom: var(--tier-lift);
  background: var(--ax-raised);
  border-color: var(--ax-accent);
  box-shadow: var(--ax-shadow-card);
}

.axp-page .tier-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 14px;
  padding: var(--ax-s-4);
}

.axp-page .tier-head h2 {
  margin: 0;
  font-size: var(--ax-fs-lg);
  font-weight: 600;
  letter-spacing: -0.01em;
  text-align: left;
}

/* Price and term read as one line, the term small beside the figure. */
.axp-page .tier-price .price-row {
  display: flex;
  align-items: baseline;
  gap: var(--ax-s-1);
}

.axp-page .tier-price .amount {
  font-size: var(--ax-fs-3xl);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
}

.axp-page .tier-card.free .tier-price .amount {
  font-size: 34px;
}

/* A price the card has replaced: struck, muted and a step down, so the figure
   a rider pays reads first. */
.axp-page .tier-price .amount.was {
  font-size: 22px;
  font-weight: 600;
  color: var(--ax-ink-2);
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}

.axp-page .tier-price .unit {
  margin-top: 2px;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

/* The presale line names the drop and its window; the amount is green. */
.axp-page .tier-price .price-off .ok {
  color: var(--ax-ok);
  font-weight: 600;
}

/* The card's one action spans the card. */
.axp-page .tier-card .tier-cta {
  width: 100%;
  height: 40px;
  padding: 0 var(--ax-s-2);
  border-radius: var(--ax-r-pill);
  font-family: inherit;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
}

.axp-page .tier-card .tier-cta.primary {
  background: var(--ax-accent);
  border: 1px solid transparent;
  color: var(--ax-accent-ink);
}

.axp-page .tier-card .tier-cta.primary:hover:not(:disabled) {
  background: var(--ax-accent-edge);
}

.axp-page .tier-card.popular .tier-cta.primary {
  box-shadow: var(--ax-shadow-cta);
}

.axp-page .tier-card .tier-cta.ghost {
  background: #2b2d30;
  border: 1px solid var(--ax-line-strong);
  color: var(--ax-ink);
}

.axp-page .tier-card .tier-cta.ghost:hover:not(:disabled) {
  background: rgba(242, 244, 246, 0.06);
}

/* The Divider between the action and the list. */
.axp-page .tier-rule {
  height: 1px;
  margin: var(--ax-s-1) 0 0;
  background: var(--ax-line);
}

.axp-page .tier-includes {
  font-size: var(--ax-fs-xs);
  font-weight: 500;
  color: var(--ax-ink-3);
}

.axp-page .tier-list {
  display: grid;
  gap: var(--ax-s-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.axp-page .tier-list li {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

/* A bare check glyph, filling its 16px box — no ring, as the shipped page. */
.axp-page .tier-list .tick {
  flex: 0 0 16px;
  height: 16px;
  margin-top: 2px;
  color: var(--ax-accent);
  border: 0;
}

.axp-page .tier-list .tick svg {
  display: block;
  width: 16px;
  height: 16px;
}

/* The "this is your pass" line a phone shows in place of the free card. */
.axp-page .tier-current {
  display: flex;
  align-items: baseline;
  gap: var(--ax-s-1);
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

/* ---- Table: the compare block ------------------------------------------ */
.axp-page .compare-block {
  width: 100%;
  max-width: 1000px;
  margin-inline: auto;
}

.axp-page .compare-block h2 {
  margin: 0 0 var(--ax-s-2);
  font-size: var(--ax-fs-lg);
  font-weight: 600;
  letter-spacing: -0.01em;
}

/* Fixed layout keeps the two plan columns a real width instead of letting the
   label column eat the row: 55 / 22.5 / 22.5 across the 1000px cap. */
.axp-page .compare-table {
  table-layout: fixed;
  border-collapse: collapse;
}

.axp-page .compare-table thead th:first-child {
  width: 55%;
}

.axp-page .compare-table th,
.axp-page .compare-table td {
  padding: 13px var(--ax-s-2);
  font-size: var(--ax-fs-xs);
  text-align: left;
  border-bottom: 1px solid var(--ax-line);
}

.axp-page .compare-table thead th {
  font-size: 12px;
  font-weight: 600;
  color: var(--ax-ink-2);
  letter-spacing: 0.01em;
  border-bottom: 1px solid var(--ax-line-strong);
}

.axp-page .compare-table tbody th {
  font-weight: 500;
  color: var(--ax-ink-2);
}

.axp-page .compare-table td {
  color: var(--ax-ink);
  font-variant-numeric: tabular-nums;
}

/* The plan columns hold the marks, so they read centred under their header. */
.axp-page .compare-table thead th:not(:first-child),
.axp-page .compare-table td {
  width: 22.5%;
  text-align: center;
}

.axp-page .compare-table td svg {
  display: block;
  width: 16px;
  height: 16px;
  margin-inline: auto;
  color: var(--ax-accent);
}

.axp-page .compare-table .cmp-none {
  color: var(--ax-ink-3);
}

.axp-page .compare-table tbody tr:hover {
  background: rgba(242, 244, 246, 0.02);
}

/* ---- Partner sheet ------------------------------------------------------ */
.axp-page .track-sheet {
  max-width: 1000px;
  width: 100%;
  margin-inline: auto;
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  padding: var(--ax-s-4);
}

.axp-page .track-sheet .sheet-lead {
  margin: 0 0 var(--ax-s-4);
  font-size: var(--ax-fs-base);
  color: var(--ax-ink-2);
}

.axp-page .track-sheet .sheet-cols {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--ax-s-5);
}

.axp-page .track-sheet .sheet-cols > * {
  min-width: 0;
}

.axp-page .track-sheet h2 {
  margin: 0 0 var(--ax-s-2);
  font-size: var(--ax-fs-base);
  font-weight: 600;
}

.axp-page .track-sheet h2 + h2 {
  margin-top: var(--ax-s-5);
}

.axp-page .track-sheet .note {
  margin: 0 0 var(--ax-s-2);
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

.axp-page .track-sheet .spec-list {
  margin: 0;
}

.axp-page .track-sheet .spec-list > div {
  display: grid;
  grid-template-columns: minmax(0, 176px) minmax(0, 1fr);
  gap: var(--ax-s-2);
  padding: 9px 0;
}

.axp-page .track-sheet .spec-list > div + div {
  border-top: 1px solid var(--ax-line);
}

.axp-page .track-sheet .spec-list dt {
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  color: var(--ax-ink);
}

.axp-page .track-sheet .spec-list dd {
  margin: 0;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

/* The scan order, numbered — a ruled list rather than a stack of cards. */
.axp-page .track-sheet .step-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.axp-page .track-sheet .step-list li {
  display: grid;
  grid-template-columns: 26px minmax(0, 1fr);
  gap: var(--ax-s-2);
  padding: 9px 0;
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
  border-top: 1px solid var(--ax-line);
}

.axp-page .track-sheet .step-list li:first-child {
  border-top: 0;
}

.axp-page .track-sheet .step-list .n {
  font-size: 11px;
  font-weight: 700;
  color: var(--ax-accent);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

.axp-page .axp-actions {
  display: flex;
  justify-content: center;
  gap: var(--ax-s-2);
}

.axp-page .axp-actions button.ghost {
  height: 40px;
  padding: 0 var(--ax-s-4);
  border-radius: var(--ax-r-pill);
  border: 1px solid var(--ax-line-strong);
  background: transparent;
  color: var(--ax-ink);
  font-family: inherit;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
}

/* ---- Mobile ------------------------------------------------------------ */
@media (max-width: 860px) {
  .axp-page .axp-stack {
    gap: var(--ax-s-4);
  }

  .axp-page .axp-section {
    border-radius: var(--ax-r-container);
    padding: var(--ax-s-4) var(--ax-s-3);
  }

  .axp-page .axp-section h1 {
    font-size: var(--ax-fs-xl);
  }

  /* One card per row, and the pass leads: the lift comes off so the stacked
     pair has no phantom gap above the free card. */
  .axp-page .pricing-grid {
    grid-template-columns: minmax(0, 1fr);
    padding-top: 0;
  }

  .axp-page .tier-card.popular {
    margin-top: 0;
    padding-bottom: 0;
  }

  .axp-page .track-sheet .sheet-cols {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ax-s-4);
  }

  .axp-page .track-sheet .spec-list > div {
    grid-template-columns: minmax(0, 1fr);
    gap: 2px;
  }
}

import { useEffect, useMemo, useState } from 'react';
import Banner from '../../components/Banner/Banner';
import { Link, useNavigate, useSearchParams } from 'react-router-dom';
// Self-hosted Figtree, as the landing does — never a Google Fonts link.
import '@fontsource-variable/figtree';
import { api, money } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import { enablePartnerAudience } from '../../lib/featureFlags';
import { presaleSentence, tierBullets } from '../../lib/tierCopy';
import './PricingAstryx.scss';

/**
 * `/pricing` in the reference design system's register (Astryx), chosen by
 * `enableAstryxUI`. `Pricing.tsx` is still here in full and untouched — flip the
 * flag to `false` and the previous page comes back exactly as it was.
 *
 * This is a MIRROR, not a rethink: the order, the copy, the card model (level
 * free card beside a raised paid card) and every figure are the shipped page's.
 * What changes is the component language — Section, Segmented Control, Badge,
 * Card, Button, Divider, List + Check Indicator, Table — and the tokens to
 * match. The class hooks the pricing suite reads (`.tier-card`, `.amount`,
 * `.price-off`, `.compare-table`, `.track-sheet` …) are kept on purpose so
 * `verify:pricing` guards this page the same way it guarded the last one.
 */

interface Tier {
  id: string;
  slug: string;
  name: string;
  tagline: string | null;
  description: string | null;
  priceCents: number;
  /** The monthly alternative to the annual price — display only. */
  monthlyPriceCents: number | null;
  earlyBirdPriceCents: number | null;
  earlyBirdStartsAt: string | null;
  earlyBirdEndsAt: string | null;
  twoYearPriceCents: number | null;
  extraDaysPerTrack: number;
  /** The free default a new account lands on. */
  isDefault: boolean;
}

interface TrackLite {
  includedDays: number;
  discountDayEnabled: boolean;
  discountRate: number | null;
}

type Audience = 'riders' | 'tracks';

/** Whole-dollar label for the headline price; falls back to cents when needed. */
function priceLabel(cents: number): string {
  return Number.isInteger(cents / 100) ? `$${cents / 100}` : money(cents);
}

/** The check indicator: a bare glyph, drawn rather than typed. */
function Check() {
  return (
    <svg
      width="16"
      height="16"
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />
    </svg>
  );
}

/** The levers a partner track sets in its own contract. */
const CONTROLS: { term: string; def: string }[] = [
  { term: 'Included days per pass', def: 'Per contract, per season.' },
  { term: 'Discounted extra day', def: 'Which day, and the rate.' },
  { term: 'Extra-day price', def: 'Your sticker price before discount.' },
];

/** The checks the server walks, in order, on every scan. */
const SCAN_ORDER = [
  'Code signature valid',
  'Code not expired',
  'Pass belongs to the rider',
  'Pass active and in season',
  'Not already redeemed here today',
  'Your track participates',
  'Free day, then discounted, then out of days',
];

export default function PricingAstryx() {
  const [tiers, setTiers] = useState<Tier[]>([]);
  const [tracks, setTracks] = useState<TrackLite[]>([]);
  const [params, setParams] = useSearchParams();
  // `?for=tracks` opens straight on the partner sheet, so a track arriving from
  // the landing page's invitation doesn't land on the rider tiers first.
  const [audience, setAudience] = useState<Audience>(
    params.get('for') === 'tracks' ? 'tracks' : 'riders',
  );
  // Annual or monthly headline price on the rider cards; annual is the saving.
  const [billing, setBilling] = useState<'annual' | 'monthly'>('annual');
  const [busy, setBusy] = useState<string | null>(null);
  // Stripe's cancel_url lands here with `?checkout=cancelled`; the reader is told
  // nothing was charged, once, before the param is retired.
  const [note, setNote] = useState<string | null>(
    params.get('checkout') === 'cancelled' ? 'Checkout cancelled — nothing was charged.' : null,
  );
  const { user } = useAuth();
  const navigate = useNavigate();
  // The rider's own pass: without it the page kept selling a card the account
  // already holds, so buying again would charge for a second one.
  const [myPass, setMyPass] = useState<{ tier: { id: string }; status: string } | null>(null);

  useEffect(() => {
    if (!user || user.role !== 'RIDER') {
      setMyPass(null);
      return;
    }
    let live = true;
    api
      .get<{ pass: { tier: { id: string }; status: string } | null }>('/me/pass')
      .then((r) => {
        if (live) setMyPass(r.data?.pass ?? null);
      });
    return () => {
      live = false;
    };
  }, [user]);

  useEffect(() => {
    api.get<{ tiers: Tier[] }>('/tiers').then((r) => setTiers(r.data?.tiers ?? []));
    // `terms=public`: this page's figures are the anonymous marketing copy, so
    // a free-tier rider reading it still sees the full day totals.
    api.get<{ tracks: TrackLite[] }>('/tracks?terms=public').then((r) => setTracks(r.data?.tracks ?? []));
  }, []);

  // Read the cancel word once, then retire the param: a refresh or a back-click
  // must not replay it.
  useEffect(() => {
    if (!params.has('checkout')) return;
    const next = new URLSearchParams(params);
    next.delete('checkout');
    setParams(next, { replace: true });
  }, [params, setParams]);

  const buy = async (tier: Tier) => {
    // The free tier is granted at sign-up, never bought.
    if (tier.isDefault) return navigate(user ? '/tracks' : '/signup');
    // Already held: send them to the pass rather than selling it twice.
    if (myPass?.status === 'ACTIVE' && myPass.tier.id === tier.id) return navigate('/tracks');
    // Signed out: no account to buy with, so open the register form (not the
    // sign-in fields) and come back here once the account exists.
    if (!user) return navigate('/signup', { state: { from: '/pricing' } });
    setBusy(tier.id);
    setNote(null);
    const res = await api.post<{
      url?: string;
      devMode?: boolean;
      paymentId?: string;
      message?: string;
    }>('/payments/checkout', { tierId: tier.id });
    setBusy(null);
    if (!res.success) return setNote(res.message);
    const d = res.data;
    if (d?.url) {
      window.location.href = d.url;
      return;
    }
    if (d?.devMode && d.paymentId) {
      const sim = await api.post(`/payments/dev/simulate/${d.paymentId}`);
      if (sim.success) {
        // Same return trip the real redirect takes, minus the session id, so the
        // confirmation and the pass re-read are exercised locally too.
        navigate('/tracks?checkout=success');
        return;
      }
      setNote(sim.message);
      return;
    }
    setNote(res.message);
  };

  const sellable = tiers;

  /**
   * Rideable days for one tier: the sum of the included days at every partner
   * track, plus its extra days at each of them.
   */
  const daysFor = (t: Tier) =>
    tracks.reduce((sum, x) => sum + (x.includedDays ?? 0), 0) + t.extraDaysPerTrack * tracks.length;

  /** Whether the presale rate is live right now. */
  const presaleActive = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    (!t.earlyBirdStartsAt || new Date(t.earlyBirdStartsAt) <= new Date()) &&
    (!t.earlyBirdEndsAt || new Date(t.earlyBirdEndsAt) > new Date());

  /** Whether the presale is announced but not open yet. */
  const presaleUpcoming = (t: Tier) =>
    t.earlyBirdPriceCents != null &&
    t.earlyBirdStartsAt != null &&
    new Date(t.earlyBirdStartsAt) > new Date();

  /**
   * The headline annual price a rider pays now — the presale rate while it runs,
   * and the same rate once the presale opens, so the card, the compare table and
   * the switch all quote one figure.
   */
  const annualPrice = (t: Tier) =>
    presaleActive(t) || presaleUpcoming(t) ? t.earlyBirdPriceCents! : t.priceCents;

  /**
   * What the switch's Annual side names. While a presale runs the badge names the
   * drop off the list price — the same figure the card prints beside it, so the
   * two numbers on the screen can never disagree ($400 to $300 reads 25%). With
   * no presale it falls back to the annual saving against twelve monthly
   * payments. Counted from the contracts either way, never typed in.
   */
  const annualSavePct = (() => {
    const paid = sellable.find((x) => !x.isDefault);
    if (!paid) return 0;
    if (presaleActive(paid) || presaleUpcoming(paid)) {
      const pct = Math.round((1 - paid.earlyBirdPriceCents! / paid.priceCents) * 100);
      return pct > 0 ? pct : 0;
    }
    if (paid.monthlyPriceCents == null) return 0;
    const pct = Math.round((1 - paid.priceCents / (paid.monthlyPriceCents * 12)) * 100);
    return pct > 0 ? pct : 0;
  })();

  /**
   * One row per capability, one column per plan — every capability that differs
   * between the plans and every one they share. `true` draws the mark, `false`
   * the quiet dash, a string is the value the plan actually carries.
   */
  const compareRows: { label: string; cell: (t: Tier) => boolean | string }[] = [
    { label: 'Price per year', cell: (t) => (t.isDefault ? '$0' : priceLabel(annualPrice(t))) },
    { label: 'Rideable days across the network', cell: (t) => (t.isDefault ? '0' : String(daysFor(t))) },
    { label: 'Included days at every track', cell: (t) => !t.isDefault },
    { label: 'Member price on extra days', cell: (t) => !t.isDefault },
    {
      label: 'Extra days at every track',
      cell: (t) => (t.extraDaysPerTrack > 0 ? `+${t.extraDaysPerTrack}` : false),
    },
    { label: 'Live venue status and hours', cell: () => true },
    { label: 'Follow the tracks you ride', cell: () => true },
  ];

  // The rows every plan marks lead the table; the deltas follow.
  const markedByEveryPlan = (row: { cell: (t: Tier) => boolean | string }) =>
    sellable.length > 0 && sellable.every((t) => row.cell(t) === true);
  const orderedCompareRows = [
    ...compareRows.filter(markedByEveryPlan),
    ...compareRows.filter((row) => !markedByEveryPlan(row)),
  ];

  /** Live figures quoted in the partner notes — never hard-coded. */
  const network = useMemo(() => {
    const count = tracks.length;
    const days = tracks.map((t) => t.includedDays);
    const rates = tracks
      .filter((t) => t.discountDayEnabled && t.discountRate != null)
      .map((t) => Math.round((t.discountRate ?? 0) * 100));
    return {
      count,
      dayMin: count ? Math.min(...days) : null,
      dayMax: count ? Math.max(...days) : null,
      rateMin: rates.length ? Math.min(...rates) : null,
      rateMax: rates.length ? Math.max(...rates) : null,
    };
  }, [tracks]);

  const controlRows = CONTROLS.map((row) => {
    if (row.term === 'Included days per pass' && network.dayMin != null) {
      return {
        ...row,
        def: `${row.def} ${network.dayMin} to ${network.dayMax} across the network.`,
      };
    }
    if (row.term === 'Discounted extra day' && network.rateMin != null) {
      const range =
        network.rateMin === network.rateMax
          ? `${network.rateMin}%`
          : `${network.rateMin}% to ${network.rateMax}%`;
      return { ...row, def: `${row.def} ${range} off today.` };
    }
    return row;
  });

  const gives: { term: string; def: string }[] = [
    { term: 'Gate station', def: "Scan, today's check-ins, and the attempt log." },
    { term: 'Reporting', def: 'Per-track redemptions and revenue; QuickBooks CSV or JSON.' },
    { term: 'Frozen counts', def: 'Rider days snapshot at activation; changes need a re-snapshot.' },
  ];

  const forTracks = audience === 'tracks';

  return (
    <div className="axp-page">
      <div className="axp-stack">
        {/* Section: the page's own header band. */}
        <section className="axp-section">
          <h1>{forTracks ? 'For partner tracks' : 'Upgrade your pass'}</h1>
          <p className="lede">
            {forTracks
              ? 'Brings riders to your gate, on terms you set.'
              : 'The Moto Pass adds included days and member pricing.'}
          </p>

          {enablePartnerAudience && (
            <div className="pill-toggle" role="group" aria-label="Who this page is for">
              <button aria-pressed={!forTracks} onClick={() => setAudience('riders')}>
                Riders
              </button>
              <button aria-pressed={forTracks} onClick={() => setAudience('tracks')}>
                Tracks
              </button>
            </div>
          )}
        </section>

        {forTracks ? (
          <>
            <section className="card track-sheet">
              <p className="sheet-lead">You collect the member price at the window.</p>

              <div className="sheet-cols">
                <div className="sheet-col">
                  <section>
                    <h2>What you control</h2>
                    <dl className="spec-list">
                      {controlRows.map((row) => (
                        <div key={row.term}>
                          <dt>{row.term}</dt>
                          <dd>{row.def}</dd>
                        </div>
                      ))}
                    </dl>
                  </section>

                  <section>
                    <h2>What you get</h2>
                    <dl className="spec-list">
                      {gives.map((row) => (
                        <div key={row.term}>
                          <dt>{row.term}</dt>
                          <dd>{row.def}</dd>
                        </div>
                      ))}
                    </dl>
                  </section>
                </div>

                <section>
                  <h2>What the station checks</h2>
                  <p className="note">In this order, every scan.</p>
                  <ol className="step-list">
                    {SCAN_ORDER.map((step, i) => (
                      <li key={step}>
                        <span className="n" aria-hidden="true">
                          {i + 1}
                        </span>
                        {step}
                      </li>
                    ))}
                  </ol>
                </section>
              </div>
            </section>

            <div className="axp-actions">
              <Link to="/tracks">
                <button className="ghost">See the network</button>
              </Link>
              <Link to="/login">
                <button className="ghost">Operator sign in</button>
              </Link>
            </div>
          </>
        ) : (
          <>
            {/* Segmented Control: the billing term. Two segments, the one in force
                raised and carrying the saving. */}
            <div className="billing-switch axp-seg" role="group" aria-label="Billing period">
              <button
                type="button"
                className="bs-opt"
                aria-pressed={billing === 'monthly'}
                onClick={() => setBilling('monthly')}
              >
                <span className="pill-label">Monthly</span>
              </button>
              <button
                type="button"
                className="bs-opt"
                aria-pressed={billing === 'annual'}
                onClick={() => setBilling('annual')}
              >
                <span className="pill-label">Annual</span>
                {annualSavePct > 0 && <span className="pill-save">Save {annualSavePct}%</span>}
              </button>
            </div>

            <div className="pricing-grid">
              {sellable.map((t) => {
                const earlyActive = presaleActive(t);
                const upcoming = presaleUpcoming(t);
                const popular = t.slug === 'base';
                const monthly = billing === 'monthly' && !t.isDefault && t.monthlyPriceCents != null;
                /**
                 * A presale rate on the annual term — live now, or announced and
                 * yet to open. Either way the card sells the reduced figure and
                 * names the list price it replaces.
                 */
                const presale =
                  !t.isDefault && !monthly && t.earlyBirdPriceCents != null && (earlyActive || upcoming);
                /** The struck list price the presale rate comes off. */
                const priceOffCents = presale ? t.priceCents - t.earlyBirdPriceCents! : 0;
                /** The presale sentence, in the wording the landing prints too. */
                const presaleLine = presaleSentence(priceLabel(priceOffCents));
                const priceCents = monthly ? t.monthlyPriceCents! : annualPrice(t);
                const freeTier = t.isDefault;
                /** The paid card folds the free tier in as its first line. */
                const added = tierBullets(t.slug, freeTier);
                /** This account already holds this card, so it is not for sale. */
                const held = !freeTier && myPass?.status === 'ACTIVE' && myPass.tier.id === t.id;
                /**
                 * A signed-in rider always holds the free pass, since it is granted
                 * at sign-up. On a phone that card is not a choice, so it collapses
                 * to a line saying the rider keeps it and the paid pass leads.
                 */
                const freeHeld = freeTier && user?.role === 'RIDER';

                return (
                  <div
                    className={
                      popular
                        ? 'tier-card popular'
                        : freeHeld
                          ? 'tier-card free is-current'
                          : freeTier
                            ? 'tier-card free'
                            : 'tier-card'
                    }
                    key={t.id}
                  >
                    <div className="tier-body">
                      {/* The only part of the free card a phone shows. */}
                      {freeHeld && (
                        <div className="tier-current">
                          <b>{t.name}</b>
                          <span>Your current pass.</span>
                        </div>
                      )}

                      <div className="tier-head">
                        <h2>{t.name}</h2>
                      </div>

                      <div className="tier-price">
                        <div className="price-row">
                          {priceOffCents > 0 && (
                            <s className="amount was">{priceLabel(t.priceCents)}</s>
                          )}
                          <span className="amount">{freeTier ? '$0' : priceLabel(priceCents)}</span>
                          <span className="unit">{monthly ? 'per month' : 'per year'}</span>
                        </div>
                        {priceOffCents > 0 && (
                          <div className="unit price-off">
                            {presaleLine.lead}
                            <span className="ok">{presaleLine.amount}</span>
                            {presaleLine.tail}
                          </div>
                        )}
                      </div>

                      <button
                        className={popular && !freeTier ? 'primary tier-cta' : 'ghost tier-cta'}
                        disabled={busy === t.id}
                        onClick={() => buy(t)}
                      >
                        {busy === t.id
                          ? 'Starting checkout…'
                          : held
                            ? 'Go to my pass'
                            : freeTier
                              ? user && user.role === 'RIDER'
                                ? 'Go to my pass'
                                : 'Create free account'
                              : 'Buy pass'}
                      </button>

                      {/* The Divider between the action and the list: the button
                          belongs to the price above it, the bullets to the label
                          below it. */}
                      <div className="tier-rule" aria-hidden="true" />

                      <div className="tier-includes">Includes:</div>

                      <ul className="tier-list">
                        {added.map((item) => (
                          <li key={item}>
                            <span className="tick" aria-hidden="true">
                              <Check />
                            </span>
                            <span>{item}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                );
              })}
            </div>

            <section className="compare-block">
              <h2>Compare</h2>
              <div className="table-scroll">
                <table className="compare-table">
                  <thead>
                    <tr>
                      <th scope="col">Capability</th>
                      {sellable.map((t) => (
                        <th scope="col" key={t.id}>
                          {t.name}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {orderedCompareRows.map((row) => (
                      <tr key={row.label}>
                        <th scope="row">{row.label}</th>
                        {sellable.map((t) => {
                          const v = row.cell(t);
                          return (
                            <td key={t.id}>
                              {v === true ? (
                                <Check />
                              ) : v === false ? (
                                <span className="cmp-none" aria-label="Not included">
                                  —
                                </span>
                              ) : (
                                <span className="cmp-val">{v}</span>
                              )}
                            </td>
                          );
                        })}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>

            {note && <Banner tone="warn" close>{note}</Banner>}
          </>
        )}
      </div>
    </div>
  );
}

/* RiderCalendar — styles owned by RiderCalendar.tsx.
   Split out of styles/global.scss; imported once from RiderCalendar.tsx and
   still plain global class names (this app uses no CSS modules). */

/* ---- The rider's calendar --------------------------------------------- */
/* The rider reads the owner's calendar: the same week grid, the same hour
   grid and the same date cards under the same month heading. What is missing
   is the editor — no Add Event, no sheet behind a card, no empty hour that
   takes a mark — so the card drops the pointer it has for an owner. The one
   addition is the venue: a rider's week holds every track they follow, so a
   card and a chip both have to say which venue a date is at. */
.rider-cal .event-edit-row.is-read { cursor: default; }

.rider-cal .event-edit-row.is-read:hover { background: var(--bg-2); }

/* The venue line sits under the title, not on a row of its own at the top of
   the card: a small muted line with the pin to its left, tightened up under
   the title so the three lines read as one block. */
.rider-cal .event-card-venue {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: -4px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1.3;
  color: var(--muted);
  text-decoration: none;
  align-self: flex-start;
  position: relative;
  z-index: 2;
}

.rider-cal .event-card-venue svg {
  width: 13px;
  height: 13px;
  flex: none;
  stroke-width: 2.2;
  opacity: 0.85;
}

.rider-cal .event-card-venue:hover { color: var(--accent); }

/* The track filter sits in the column it narrows and takes its width — the
   fields already read `width: 100%`, so nothing overrides the select here. */

/* The empty state before a rider follows anything: a line of copy and the one
   control that fills it. */
.rider-cal-empty { display: grid; gap: 8px; justify-items: start; max-width: 520px; }

.rider-cal-empty p { margin: 0; }

.rider-cal .event-edit-row.is-read { cursor: pointer; }

.rider-cal .event-edit-row.is-read:hover { background: var(--bg-3); }

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../../../lib/api';
import type { ProfileEvent } from '../../../lib/events';
import { ampmLabel, dayKey, dayRange, daysOf, stepWeek, weekStart } from '../../../lib/events';
import WeekGrid from '../../../components/WeekGrid/WeekGrid';
import EventReadSheet from '../../../components/EventReadSheet/EventReadSheet';
import CalendarSkeleton from '../../../components/CalendarSkeleton/CalendarSkeleton';
import './RiderCalendar.scss';

/** A track the account follows, as `/me/calendar` serves it. */
interface FollowLite {
  trackId: string;
  slug: string;
  name: string;
  city: string | null;
  region: string | null;
  status: string;
  statusNote: string | null;
  hours: string | null;
  nextEvent: string | null;
  followedAt: string;
}

/** A date at a followed track — the venue rides on it, so a week of several
 *  tracks still reads which venue each date is at. */
interface RiderEvent extends ProfileEvent {
  trackId: string;
  trackSlug: string;
  trackName: string;
  trackCategory: string | null;
  /** The venue's photo, so the read sheet can carry its profile banner. */
  trackImageUrl: string | null;
  /** The venue's place — the banner names it under the track. */
  trackCity: string | null;
  trackRegion: string | null;
}

const DAY_FMT: Intl.DateTimeFormatOptions = {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
};

/**
 * The rider's calendar: the dates at the tracks this account follows, read as
 * the venue's own week.
 *
 * It reads exactly the way the owner's calendar page reads — the same week,
 * the same hour grid, the same cards under the same month heading — and it is
 * the same shell deliberately: what a rider sees of a season should not be a
 * second design. What it does not carry is the editor: no Add Event, no sheet
 * behind a card, no hour of the week that takes a mark. Following is the whole
 * of a free-tier account's surface, so this page comes with the free tier.
 *
 * A week here holds more than one venue, so every chip and every card names
 * the track it is at.
 */
export default function RiderCalendar() {
  const [follows, setFollows] = useState<FollowLite[]>([]);
  const [events, setEvents] = useState<RiderEvent[]>([]);
  const [loading, setLoading] = useState(true);
  /** The track filter, when there is more than one to filter between. */
  const [trackId, setTrackId] = useState('');

  useEffect(() => {
    let live = true;
    api
      .get<{ follows: FollowLite[]; events: RiderEvent[] }>('/me/calendar')
      .then((r) => {
        if (!live) return;
        setFollows(r.data?.follows ?? []);
        setEvents(r.data?.events ?? []);
      })
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, []);

  const shown = useMemo(
    () => (trackId ? events.filter((e) => e.trackId === trackId) : events),
    [events, trackId]
  );

  // The page's own frame stands in while the season loads: a rider's week has
  // no bar above it and its track filter only exists once the follows are in,
  // so nothing beyond the editor is drawn.
  if (loading) return <CalendarSkeleton />;

  return (
    <div className="stack cal-page rider-cal">
      {/* The week is the page, so it is drawn whether or not a date lands on
          it: a rider who follows nothing still reads a season, with the prompt
          to fill it in the column beside it. The filter is a different
          calendar, not a narrower list — `key` re-opens the week on the next
          date of what it is now showing. The filter itself sits in that same
          column, over the cards it narrows. */}
      <RiderWeek
        key={trackId || 'all'}
        events={shown}
        empty={follows.length === 0}
        follows={follows}
        trackId={trackId}
        onTrackChange={setTrackId}
      />
    </div>
  );
}

/** The location mark — a map pin, drawn on the 24 grid so the head keeps its
 *  curve; the card's CSS scales the box down and the stroke with it. */
function PinGlyph() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 21s7-6.1 7-11a7 7 0 0 0-14 0c0 4.9 7 11 7 11z" />
        <circle cx="12" cy="10" r="2.4" />
      </g>
    </svg>
  );
}

/**
 * One week of the read, with that month's dates beside it — the owner's page
 * with the editor taken out. It keeps the week, the page's own month and the
 * picked day, and nothing else: the week cannot be written, so there is no
 * slot to hold — every chip and every card only opens the date it draws, as a
 * read.
 *
 * It draws even with nothing in it — an account that follows no track still
 * gets the month, the week and the column, and the column carries the one
 * control that fills them (`empty`).
 */
function RiderWeek({
  events,
  empty = false,
  follows,
  trackId,
  onTrackChange,
}: {
  events: RiderEvent[];
  empty?: boolean;
  follows: FollowLite[];
  trackId: string;
  onTrackChange: (trackId: string) => void;
}) {
  const today = dayKey(new Date().toISOString());

  // Open on the week of the next date ahead — the week a rider is most likely
  // to be looking at — or on this one when the tracks have nothing coming.
  const open = useMemo(() => {
    const next = events.find((e) => dayKey(e.startsAt) >= today);
    return dayKey(next ? next.startsAt : new Date().toISOString());
  }, [events, today]);

  const [anchor, setAnchor] = useState(open);
  const [picked, setPicked] = useState<string | null>(null);
  const [focusId, setFocusId] = useState<string | null>(null);
  /** The date whose sheet is open, read-only: a rider reads, and nothing here
   *  writes, so the sheet behind a card is the owner's with the editor gone. */
  const [openEvent, setOpenEvent] = useState<RiderEvent | null>(null);

  /** Every day the season covers, so a run that began last week still marks
   *  its days on this week's grid. */
  const byDay = useMemo(() => {
    const map = new Map<string, RiderEvent[]>();
    for (const ev of events) {
      for (const k of daysOf(ev)) {
        const list = map.get(k);
        if (list) list.push(ev);
        else map.set(k, [ev]);
      }
    }
    return map;
  }, [events]);

  const monday = weekStart(anchor);
  const month = anchor.slice(0, 7);
  const inMonth = useMemo(
    () => events.filter((e) => dayKey(e.startsAt).startsWith(month)),
    [events, month]
  );
  /** A picked day narrows the cards to the dates that cover it — read off
   *  every date, not the month's. */
  const shown = useMemo(
    () => (picked ? events.filter((e) => daysOf(e).includes(picked)) : inMonth),
    [picked, events, inMonth]
  );

  const monthLabel = new Date(`${anchor}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
  const pickedLabel = picked ? new Date(`${picked}T12:00:00Z`).toLocaleDateString(undefined, DAY_FMT) : '';

  const step = (weeks: number) => {
    setAnchor((a) => stepWeek(a, weeks));
    setPicked(null);
    setFocusId(null);
  };

  const goToday = () => {
    setAnchor(today);
    setPicked(null);
    setFocusId(null);
  };

  /** A second pick on the same day puts it down again; a day pick rings the
   *  first card on it, the way the owner's own page does. */
  function pickDay(day: string) {
    if (day === picked) {
      setPicked(null);
      setFocusId(null);
      return;
    }
    setPicked(day);
    setFocusId((byDay.get(day) ?? [])[0]?.id ?? null);
  }

  /** A chip is the date it draws, so a click opens that date's own read —
   *  the same sheet the card's cover opens — and the month's cards stay put,
   *  exactly as they read on the owner's own calendar. The chip carries the
   *  shared shape, not this page's row, so the id lookup is what keeps the
   *  sheet on a card the page knows (and the venue the sheet names). */
  const pickEvent = (ev: ProfileEvent) => {
    const full = events.find((e) => e.id === ev.id);
    if (full) setOpenEvent(full);
  };

  return (
    <div className="cal-editor" data-week={monday} data-month={month}>
      {/* The month's dates on the left, the week they sit in on the right —
          the two read together, exactly as they do for the venue's owner. */}
      <div className="stack event-editor">
        <div className="row spread wrap event-list-head">
          <span className="row event-list-title">
            <b className="small">{monthLabel}</b>
            {!picked && <span className="tiny muted">{shown.length} dates</span>}
          </span>
          {picked && (
            <div className="event-filter">
              <span className="small event-filter-day">{pickedLabel}</span>
              <button
                className="ghost small"
                onClick={() => {
                  setPicked(null);
                  setFocusId(null);
                }}
              >
                Show all events
              </button>
            </div>
          )}
        </div>

        {/* The track filter belongs to the column it narrows: a rider reading
            a month of cards narrows them where they are, not from a bar above
            the week. One follow needs no picker. */}
        {follows.length > 1 && (
          <select
            className="cal-track-filter"
            value={trackId}
            onChange={(e) => onTrackChange(e.target.value)}
            aria-label="Which followed tracks to show"
          >
            <option value="">All tracks</option>
            {follows.map((f) => (
              <option key={f.trackId} value={f.trackId}>
                {f.name}
              </option>
            ))}
          </select>
        )}

        {/* Nothing to list is not nothing to say: an account that follows no
            track gets the prompt to follow one, in the column it would
            otherwise fill with cards. */}
        {shown.length === 0 &&
          (empty ? (
            <div className="rider-cal-empty">
              <b>No tracks followed yet</b>
              <p className="small muted">
                Follow a track on the network page and its dates land here.
              </p>
              <Link to="/tracks">
                <button className="primary small">Browse the network</button>
              </Link>
            </div>
          ) : (
            <div className="small muted">
              {picked
                ? 'Nothing from your tracks on this date. Show all events puts the month back.'
                : 'Nothing from your tracks this month.'}
            </div>
          ))}

        {shown.map((ev) => {
          const hours = ampmLabel(ev);
          return (
            <div
              key={ev.id}
              className={['event-edit-row', 'is-read', focusId === ev.id ? 'is-focused' : '']
                .filter(Boolean)
                .join(' ')}
            >
              {/* The card is what is on, then the venue it is at, then when.
                  The card is the control: where the owner's card opens the
                  editor, this one opens the same sheet with nothing left to
                  write. The venue keeps its own way out to the track. */}
              <button
                type="button"
                className="event-open"
                aria-label={`View ${ev.title}`}
                onClick={() => setOpenEvent(ev)}
              />
              <div className="row wrap event-title-row">
                <h4 className="event-card-title">{ev.title}</h4>
              </div>
              <Link className="row event-card-venue" to={`/tracks/${ev.trackSlug}`}>
                <PinGlyph />
                {ev.trackName}
              </Link>
              <div className="small muted event-card-when">
                {dayRange(ev)}
                {hours && <span className="event-card-hours"> · {hours}</span>}
              </div>
            </div>
          );
        })}
      </div>

      <WeekGrid
        events={events}
        anchor={anchor}
        today={today}
        picked={picked}
        onStep={step}
        onToday={goToday}
        onPickDay={pickDay}
        onPickEvent={pickEvent}
        venueOf={(ev) => (ev as RiderEvent).trackName}
      />

      {/* The date a rider opened, read-only — the owner's sheet, without the
          editor: no field posts from here, so the sheet is all read. */}
      {openEvent && (
        <EventReadSheet
          event={openEvent}
          banner={{
            name: openEvent.trackName,
            slug: openEvent.trackSlug,
            where: [openEvent.trackCity, openEvent.trackRegion].filter(Boolean).join(', '),
            photo: openEvent.trackImageUrl,
          }}
          onClose={() => setOpenEvent(null)}
        />
      )}
    </div>
  );
}

/* RiderCalendarAstryx — styles owned by RiderCalendarAstryx.tsx (the rider's
   calendar while `enableAstryxUI` is on).

   Same rules as AstryxLanding.scss / PricingAstryx.scss: the register's tokens
   are declared scoped to `.axc-page`, never on `:root`, and every override is
   written through that wrapper so it out-specifies global.scss's
   `.event-edit-row` / `.cal-nav` base layer and WeekGrid.scss's own `.wk*`
   rules (the week grid is reused as-is — this is a restyle of it, not a second
   grid). The class hooks `verify:calendar` reads are kept on purpose, exactly
   as `PricingAstryx` kept the pricing hooks.

   Where the card rules also meet RiderCalendar.scss's `.rider-cal ...` block
   (same specificity) they are written as `.axc-page.rider-cal ...` so the
   register always wins regardless of module load order. */

.axc-page {
  /* Surfaces, one step each. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* Moto Pass's own orange on the register's accent / edge / tint / on-accent
     quartet. */
  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-tint: rgba(242, 121, 2, 0.35);
  --ax-accent-ink: #0a1317;
  /* The wash today's column sits on — the accent at a breath. */
  --ax-accent-wash: rgba(242, 121, 2, 0.06);

  /* Counts wear the house chip: stone ground, 4px radius. */
  --ax-chip-bg: #d6d3d1;
  --ax-chip-ink: #1c1917;

  /* Radii. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-pill: 999px;

  /* Type ramp — only the steps this page uses. */
  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;
  --ax-fs-base: 16px;
  --ax-fs-lg: 20px;

  /* Spacing steps (the register counts in 6s). */
  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;
  --ax-s-5: 30px;

  --ax-e-fast: 100ms;
  --ax-e-med: 250ms;

  font-family: 'Figtree Variable', Figtree, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-xs);
  line-height: 1.45;
  color: var(--ax-ink);
  -webkit-font-smoothing: antialiased;
}

/* The app's own light palette, restated for this page's surfaces. */
:root[data-theme='light'] .axc-page {
  --ax-body: #f1f4f7;
  --ax-surface: #ffffff;
  --ax-raised: #f4f6f9;
  --ax-line: rgba(5, 54, 89, 0.14);
  --ax-line-strong: #c3ccd6;

  --ax-ink: #0a1317;
  --ax-ink-2: #4e606f;
  --ax-ink-3: #8a97a4;

  --ax-accent: #eb6e00;
  --ax-accent-edge: #b34a01;
  --ax-accent-ink: #fff8f2;
  --ax-accent-wash: rgba(235, 110, 0, 0.05);

  --ax-chip-bg: #e7e2df;
  --ax-chip-ink: #1c1917;
}

/* ---- The page: the owner's two columns, one card each ------------------ */
/* `cal-editor` is the shipped grid (340px of dates beside the week); the
   catalogue's gap goes one step tighter than the shell's 22px. */
.axc-page .cal-editor {
  grid-template-columns: minmax(0, 340px) minmax(0, 1fr);
  gap: var(--ax-s-3);
}

/* ---- The month column -------------------------------------------------- */
.axc-page .event-editor {
  display: flex;
  flex-direction: column;
  gap: var(--ax-s-2);
  max-width: none;
  padding: var(--ax-s-2);
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  /* The month's dates scroll inside their card: a 340px column that ran the
     whole season would stand twice as tall as the week beside it, and the two
     are meant to be read as a pair. The head and the filter stay put. */
  max-height: calc(100svh - var(--header-h, 57px) - 48px);
  overflow: hidden;
}

/* The card list is the part that scrolls. */
.axc-page .axc-cards {
  display: grid;
  align-content: start;
  gap: var(--ax-s-2);
  padding-right: 2px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  min-height: 0;
}

.axc-page .event-list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ax-s-1);
  min-height: 22px;
  padding: 2px 2px 0;
}

.axc-page .event-list-title {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.axc-page .axc-month-label {
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  letter-spacing: -0.005em;
  color: var(--ax-ink);
  white-space: nowrap;
}

/* The count chip: the register's stone ground with 4px corners. */
.axc-page .axc-chip {
  flex: none;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--ax-chip-bg);
  color: var(--ax-chip-ink);
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* A picked day, and the way back to the month: the read's own filter strip. */
.axc-page .axc-picked {
  display: flex;
  align-items: baseline;
  gap: var(--ax-s-1);
}

.axc-page .axc-picked-day {
  font-size: 12px;
  font-weight: 600;
  color: var(--ax-ink);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.axc-page .axc-quiet {
  padding: 0;
  min-height: 0;
  height: auto;
  background: none;
  border: 0;
  color: var(--ax-ink-2);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: color var(--ax-e-fast) ease;
}

.axc-page .axc-quiet:hover { color: var(--ax-ink); }

.axc-page .axc-quiet:focus-visible {
  outline: 2px solid var(--ax-accent);
  outline-offset: 2px;
  border-radius: 3px;
}

/* The track filter — a field of the register: the page's ground, a hairline,
   the element radius. It keeps its width: it narrows the column it sits in. */
.axc-page .axc-field .cal-track-filter {
  width: 100%;
  height: 34px;
  padding: 0 10px;
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-element);
  background: var(--ax-body);
  color: var(--ax-ink);
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
  transition: border-color var(--ax-e-fast) ease, background var(--ax-e-fast) ease;
}

.axc-page .axc-field .cal-track-filter:hover { border-color: var(--ax-line-strong); }

.axc-page .axc-field .cal-track-filter:focus-visible {
  outline: 2px solid var(--ax-accent-tint);
  outline-offset: 1px;
  border-color: var(--ax-accent);
}

/* ---- A date in the column ---------------------------------------------- */
/* The owner's card material with the editor gone: what is on, the venue it is
   at, then when. The card is the control — `.event-open` still covers it. */
.axc-page .axc-card {
  position: relative;
  display: grid;
  gap: 2px;
  padding: 11px 13px 12px;
  background: var(--ax-body);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-element);
  cursor: pointer;
  transition: background var(--ax-e-fast) ease, border-color var(--ax-e-fast) ease;
}

.axc-page .axc-card:hover {
  background: var(--ax-raised);
  border-color: var(--ax-line-strong);
}

.axc-page .axc-card.is-focused {
  border-color: var(--ax-accent-edge);
  box-shadow: 0 0 0 3px var(--ax-accent-tint);
}

.axc-page .axc-card .event-card-title {
  margin: 0;
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  letter-spacing: -0.005em;
  line-height: 1.35;
  color: var(--ax-ink);
}

/* The venue sits under the title with its pin, one click from its profile —
   above the cover, so the track stays reachable. */
.axc-page.rider-cal .event-card-venue {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 5px;
  align-self: flex-start;
  margin-top: 1px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.3;
  color: var(--ax-ink-2);
  text-decoration: none;
  transition: color var(--ax-e-fast) ease;
}

.axc-page.rider-cal .event-card-venue svg {
  width: 13px;
  height: 13px;
  flex: none;
  stroke-width: 2.2;
  opacity: 0.9;
}

.axc-page.rider-cal .event-card-venue:hover { color: var(--ax-accent); }

.axc-page .axc-card .event-card-when {
  font-size: 12px;
  color: var(--ax-ink-2);
  font-variant-numeric: tabular-nums;
}

.axc-page .axc-card .event-card-hours { color: var(--ax-ink-2); }

/* The column's own quiet lines. */
.axc-page .axc-note {
  margin: 0;
  padding: 2px;
  font-size: 12.5px;
  color: var(--ax-ink-3);
}

/* The cavity before a rider follows anything: the prompt, in the column it
   would otherwise fill. */
.axc-page .axc-empty {
  display: grid;
  gap: var(--ax-s-1);
  justify-items: start;
  max-width: 520px;
  padding: 4px 2px 6px;
}

.axc-page .axc-empty b {
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  color: var(--ax-ink);
}

.axc-page .axc-empty p {
  margin: 0;
  font-size: 12.5px;
  color: var(--ax-ink-2);
}

/* The one action in the column: a filled pill, the register's accent trio. */
.axc-page .axc-cta {
  display: inline-flex;
  align-items: center;
  height: 32px;
  margin-top: 4px;
  padding: 0 14px;
  border-radius: var(--ax-r-pill);
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
  font-size: 12.5px;
  font-weight: 600;
