  box-shadow: inset 0 2px 0 var(--ax-accent);
  color: var(--ax-ink);
}

.axc-page .wk-dow.is-today .wk-dow-num {
  background: var(--ax-accent);
  color: var(--ax-accent-ink);
}

.axc-page .wk-dow.is-picked .wk-dow-num {
  box-shadow: 0 0 0 2px var(--ax-accent-tint), 0 0 0 1px var(--ax-accent);
}

.axc-page .wk-allday-label {
  padding: 8px 8px 0;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: var(--ax-ink-3);
}

.axc-page .wk-allday-cell {
  min-height: 38px;
  padding: 5px 5px 6px;
}

.axc-page .wk-allday-cell.is-today { background-color: var(--ax-accent-wash); }

/* An all-day date: the register's inner radius on the kind's tint, the ring
   kept — the row has no hours to place it with. */
.axc-page .wk-aday {
  border-radius: var(--ax-r-inner);
  padding: 4px 7px;
  font-size: 11px;
  color: var(--ax-ink);
}

.axc-page .wk-aday-title { font-weight: 600; }

.axc-page .wk-aday-kind { font-size: 10px; color: var(--ax-ink-3); }

.axc-page .wk-aday-venue { font-size: 10px; color: var(--ax-ink-3); }

/* The hours gutter. */
.axc-page .wk-time {
  font-size: 10.5px;
  color: var(--ax-ink-3);
  font-variant-numeric: tabular-nums;
}

/* A day column: one hairline an hour, the accent at a breath on today. */
.axc-page .wk-col {
  border-left: 1px solid var(--ax-line);
  background-image: linear-gradient(var(--ax-line) 0 1px, transparent 1px);
}

.axc-page .wk-col.is-today { background-color: var(--ax-accent-wash); }

/* A timed date: a block on its hour, the kind down its left edge. */
.axc-page .wk-chip {
  left: 3px;
  right: 6px;
  padding: 5px 7px;
  border-radius: var(--ax-r-inner);
  color: var(--ax-ink);
}

.axc-page .wk-chip-title { font-size: 11.5px; font-weight: 600; }

.axc-page .wk-chip-time {
  font-size: 10px;
  color: var(--ax-ink-3);
  font-variant-numeric: tabular-nums;
}

.axc-page .wk-chip-venue { font-size: 10px; color: var(--ax-ink-3); }

.axc-page .wk-now { background: var(--ax-accent); }

.axc-page .wk-now::before { background: var(--ax-accent); }

/* ---- Phone: the columns stack, the week first -------------------------- */
@media (max-width: 860px) {
  .axc-page .cal-editor { grid-template-columns: minmax(0, 1fr); gap: var(--ax-s-2); }

  /* Stacked, the month column runs its own length again — a capped card above
     the week would hide dates behind a scroll for no reason. */
  .axc-page .event-editor { max-height: none; }

  .axc-page .axc-cards { overflow: visible; }

  /* A stacked week keeps the day heads and the columns intact and scrolls
     sideways rather than crushing the chips. */
  .axc-page .wk { overflow-x: auto; }

  .axc-page .wk-grid { min-width: 660px; }
}

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
// Self-hosted Figtree, as the landing and the pricing mirror do — never a CDN.
import '@fontsource-variable/figtree';
import { api } from '../../../lib/api';
import type { ProfileEvent } from '../../../lib/events';
import { ampmLabel, dayKey, dayRange, daysOf, stepWeek, weekStart } from '../../../lib/events';
import WeekGrid from '../../../components/WeekGrid/WeekGrid';
import EventReadSheet from '../../../components/EventReadSheet/EventReadSheet';
import CalendarSkeleton from '../../../components/CalendarSkeleton/CalendarSkeleton';
import './RiderCalendarAstryx.scss';

/**
 * `/tracks/calendar` in the reference design system's register (Astryx),
 * chosen by `enableAstryxUI`. `RiderCalendar` is still here in full and
 * untouched — flip the flag to `false` and the previous page comes back
 * exactly as it was.
 *
 * This is a MIRROR, not a rethink. Same read, same data (`/me/calendar`), same
 * two-column shape (a 340px column of the month's dates beside the venue's own
 * week), same week grid (`components/WeekGrid`, handed none of its writing
 * controls), same read sheet. What changes is the register: Figtree, the
 * system's surfaces, radii and spacing steps, the month column as one Card, a
 * count in the house chip, pill controls in the week's toolbar, today as a
 * filled accent day.
 *
 * The class hooks `verify:calendar` reads (`.cal-editor[data-week][data-month]`,
 * `.event-editor`, `.event-list-head`, `.cal-track-filter`, `.wk`, `.wk-grid`,
 * `.wk-dow`, `.wk-allday-label`, `.wk-times`, `.wk-col`) are kept on purpose,
 * exactly as `PricingAstryx` kept the pricing hooks: the suite guards the
 * restyle. Its rider-only checks still hold — no `.cal-top`, no `.wk-slot`
 * that takes a mark.
 */

/** A track the account follows, as `/me/calendar` serves it. */
interface FollowLite {
  trackId: string;
  slug: string;
  name: string;
  city: string | null;
  region: string | null;
  status: string;
  statusNote: string | null;
  hours: string | null;
  nextEvent: string | null;
  followedAt: string;
}

/** A date at a followed track — the venue rides on it, so a week of several
 *  tracks still reads which venue each date is at. */
interface RiderEvent extends ProfileEvent {
  trackId: string;
  trackSlug: string;
  trackName: string;
  trackCategory: string | null;
  /** The venue's photo, so the read sheet can carry its profile banner. */
  trackImageUrl: string | null;
  /** The venue's place — the banner names it under the track. */
  trackCity: string | null;
  trackRegion: string | null;
}

const DAY_FMT: Intl.DateTimeFormatOptions = {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
};

export default function RiderCalendarAstryx() {
  const [follows, setFollows] = useState<FollowLite[]>([]);
  const [events, setEvents] = useState<RiderEvent[]>([]);
  const [loading, setLoading] = useState(true);
  /** The track filter, when there is more than one to filter between. */
  const [trackId, setTrackId] = useState('');

  useEffect(() => {
    let live = true;
    api
      .get<{ follows: FollowLite[]; events: RiderEvent[] }>('/me/calendar')
      .then((r) => {
        if (!live) return;
        setFollows(r.data?.follows ?? []);
        setEvents(r.data?.events ?? []);
      })
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, []);

  const shown = useMemo(
    () => (trackId ? events.filter((e) => e.trackId === trackId) : events),
    [events, trackId]
  );

  // The page's own frame stands in while the season loads: the frame is the
  // same two-column shape this page draws, so nothing jumps when it lands.
  if (loading) return <CalendarSkeleton />;

  return (
    <div className="stack cal-page axc-page rider-cal">
      {/* The week is the page, so it is drawn whether or not a date lands on
          it: a rider who follows nothing still reads a season, with the prompt
          to fill it in the column beside it. The filter is a different
          calendar, not a narrower list — `key` re-opens the week on the next
          date of what it is now showing. */}
      <RiderWeek
        key={trackId || 'all'}
        events={shown}
        empty={follows.length === 0}
        follows={follows}
        trackId={trackId}
        onTrackChange={setTrackId}
      />
    </div>
  );
}

/** The location mark — a map pin, drawn on the 24 grid so the head keeps its
 *  curve; the card's CSS scales the box down and the stroke with it. */
function PinGlyph() {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 21s7-6.1 7-11a7 7 0 0 0-14 0c0 4.9 7 11 7 11z" />
        <circle cx="12" cy="10" r="2.4" />
      </g>
    </svg>
  );
}

/**
 * One week of the read, with that month's dates beside it — the same week the
 * owner's page draws, with the editor taken out. It keeps the week, the page's
 * own month and the picked day, and nothing else: the week cannot be written,
 * so no hour of a column takes a mark and every chip opens the date it draws,
 * as a read.
 */
function RiderWeek({
  events,
  empty = false,
  follows,
  trackId,
  onTrackChange,
}: {
  events: RiderEvent[];
  empty?: boolean;
  follows: FollowLite[];
  trackId: string;
  onTrackChange: (trackId: string) => void;
}) {
  const today = dayKey(new Date().toISOString());

  // Open on the week of the next date ahead — the week a rider is most likely
  // to be looking at — or on this one when the tracks have nothing coming.
  const open = useMemo(() => {
    const next = events.find((e) => dayKey(e.startsAt) >= today);
    return dayKey(next ? next.startsAt : new Date().toISOString());
  }, [events, today]);

  const [anchor, setAnchor] = useState(open);
  const [picked, setPicked] = useState<string | null>(null);
  const [focusId, setFocusId] = useState<string | null>(null);
  /** The date whose sheet is open, read-only. */
  const [openEvent, setOpenEvent] = useState<RiderEvent | null>(null);

  /** Every day the season covers, so a run that began last week still marks
   *  its days on this week's grid. */
  const byDay = useMemo(() => {
    const map = new Map<string, RiderEvent[]>();
    for (const ev of events) {
      for (const k of daysOf(ev)) {
        const list = map.get(k);
        if (list) list.push(ev);
        else map.set(k, [ev]);
      }
    }
    return map;
  }, [events]);

  const monday = weekStart(anchor);
  const month = anchor.slice(0, 7);
  const inMonth = useMemo(
    () => events.filter((e) => dayKey(e.startsAt).startsWith(month)),
    [events, month]
  );
  /** A picked day narrows the cards to the dates that cover it — read off
   *  every date, not the month's. */
  const shown = useMemo(
    () => (picked ? events.filter((e) => daysOf(e).includes(picked)) : inMonth),
    [picked, events, inMonth]
  );

  const monthLabel = new Date(`${anchor}T12:00:00Z`).toLocaleDateString(undefined, {
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
  const pickedLabel = picked ? new Date(`${picked}T12:00:00Z`).toLocaleDateString(undefined, DAY_FMT) : '';

  const step = (weeks: number) => {
    setAnchor((a) => stepWeek(a, weeks));
    setPicked(null);
    setFocusId(null);
  };

  const goToday = () => {
    setAnchor(today);
    setPicked(null);
    setFocusId(null);
  };

  /** A second pick on the same day puts it down again; a day pick rings the
   *  first card on it. */
  function pickDay(day: string) {
    if (day === picked) {
      setPicked(null);
      setFocusId(null);
      return;
    }
    setPicked(day);
    setFocusId((byDay.get(day) ?? [])[0]?.id ?? null);
  }

  /** A chip is the date it draws, so a click opens that date's own read — the
   *  same sheet the card's cover opens. */
  const pickEvent = (ev: ProfileEvent) => {
    const full = events.find((e) => e.id === ev.id);
    if (full) setOpenEvent(full);
  };

  return (
    <div className="cal-editor" data-week={monday} data-month={month}>
      {/* The month's dates in one Card on the left, the week they sit in on
          the right. */}
      <div className="axc-panel event-editor">
        <div className="axc-panel-head event-list-head">
          <span className="axc-month event-list-title">
            <b className="axc-month-label">{monthLabel}</b>
            {!picked && <span className="axc-chip">{shown.length} dates</span>}
          </span>
          {picked && (
            <span className="event-filter axc-picked">
              <span className="axc-picked-day">{pickedLabel}</span>
              <button
                className="ghost small axc-quiet"
                onClick={() => {
                  setPicked(null);
                  setFocusId(null);
                }}
              >
                Show all events
              </button>
            </span>
          )}
        </div>

        {/* The track filter belongs to the column it narrows: a rider reading
            a month of cards narrows them where they are. One follow needs no
            picker. */}
        {follows.length > 1 && (
          <div className="axc-field">
            <select
              className="cal-track-filter"
              value={trackId}
              onChange={(e) => onTrackChange(e.target.value)}
              aria-label="Which followed tracks to show"
            >
              <option value="">All tracks</option>
              {follows.map((f) => (
                <option key={f.trackId} value={f.trackId}>
                  {f.name}
                </option>
              ))}
            </select>
          </div>
        )}

        {/* Nothing to list is not nothing to say: an account that follows no
            track gets the prompt to follow one, in the column it would
            otherwise fill with cards. */}
        <div className="axc-cards">
          {shown.length === 0 &&
            (empty ? (
              <div className="axc-empty rider-cal-empty">
                <b>No tracks followed yet</b>
                <p>
                  Follow a track on the network page and its dates land here.
                </p>
                <Link className="axc-cta" to="/tracks">
                  Browse the network
                </Link>
              </div>
            ) : (
              <p className="axc-note">
                {picked ? 'Nothing from your tracks on this date.' : 'Nothing from your tracks this month.'}
              </p>
            ))}

          {shown.map((ev) => {
            const hours = ampmLabel(ev);
            return (
              <div
                key={ev.id}
                className={['axc-card', 'event-edit-row', 'is-read', focusId === ev.id ? 'is-focused' : '']
                  .filter(Boolean)
                  .join(' ')}
              >
                {/* The card is what is on, then the venue it is at, then when.
                    The card is the control: it opens the sheet with nothing
                    left to write. The venue keeps its own way out to the
                    track. */}
                <button
                  type="button"
                  className="event-open"
                  aria-label={`View ${ev.title}`}
                  onClick={() => setOpenEvent(ev)}
                />
                <h4 className="event-card-title">{ev.title}</h4>
                <Link className="event-card-venue" to={`/tracks/${ev.trackSlug}`}>
                  <PinGlyph />
                  {ev.trackName}
                </Link>
                <div className="event-card-when">
                  {dayRange(ev)}
                  {hours && <span className="event-card-hours"> · {hours}</span>}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="axc-week">
        <WeekGrid
          events={events}
          anchor={anchor}
          today={today}
          picked={picked}
          onStep={step}
          onToday={goToday}
          onPickDay={pickDay}
          onPickEvent={pickEvent}
          venueOf={(ev) => (ev as RiderEvent).trackName}
        />
      </div>

      {/* The date a rider opened, read-only — the owner's sheet, without the
          editor: no field posts from here. */}
      {openEvent && (
        <EventReadSheet
          event={openEvent}
          banner={{
            name: openEvent.trackName,
            slug: openEvent.trackSlug,
            where: [openEvent.trackCity, openEvent.trackRegion].filter(Boolean).join(', '),
            photo: openEvent.trackImageUrl,
          }}
          onClose={() => setOpenEvent(null)}
        />
      )}
    </div>
  );
}

