import RecentScans from '../../../components/RecentScans/RecentScans';
import './RiderDashboard.scss';

/**
 * The rider's dashboard — the signed-in rider's landing page. Reached from the
 * header's brand link; behind `enableRiderDashboard` in `lib/featureFlags.ts`.
 * The pass status, day meter and follows modules land here next; the scan-in
