 */
export default function RiderDashboard() {
  return (
    <div className="stack rider-dashboard">
      <div>
        <h1>Dashboard</h1>
        <div className="small muted">Your pass, days and activity at a glance.</div>
      </div>

      <RecentScans />
    </div>
  );
}

/* RiderHome — styles owned by RiderHome.tsx.
   Split out of styles/global.scss; imported once from RiderHome.tsx and
   still plain global class names (this app uses no CSS modules). */

/* ---- Pass layout --------------------------------------------------------
   My Pass is an ID card. The pass itself is a tall card hugging the right of
   the page, sticky so it behaves like a physical pass you hold; every
   supporting figure lives outside it in the left column, never on the card. */
.pass-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 328px;
  gap: 26px;
  align-items: start;
}

.pass-aux { grid-column: 1; grid-row: 1; min-width: 0; }

.pass-page.stack { --page-h: calc(100svh - var(--header-h, 57px)); min-height: var(--page-h); }

.pass-layout.with-map { display: block; }

.pass-map {
  --float-gap: 16px;
  --rail-w: 384px;
  --venue-w: 356px;
  position: relative;
  /* The page's own frame: the band is the page root's own height, so the canvas
     is the whole screen and the footer waits below the fold. */
  height: var(--page-h);
  min-height: 560px;
}

.pass-map .map-pane {
  position: absolute;
  inset: 0;
  height: 100%;
  min-height: 0;
  /* The canvas is the screen, not a card laid on it: the generic `.map-pane`
     material (hairline + 6px corners) comes off, so the map reaches the window's
     own edges square. The floats above it keep theirs — they are cards. */
  border: 0;
  border-radius: 0;
}

/* The rail: who is reading and what the pass leaves them, the one control that
   slices the list, then the list itself — the only part of it that scrolls. */
.pass-aux {
  position: absolute;
  top: var(--float-gap);
  left: var(--float-gap);
  bottom: var(--float-gap);
  width: var(--rail-w);
  /* Above Leaflet's controls (1000), below the shell's own layers (the sticky
     header and its dropdowns at 1050, toasts 1100, sheets 1200) — the floats
     are part of the page, not chrome over it. */
  z-index: 1030;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
}

.rail-pass-name { font-size: 13.5px; font-weight: 600; }

.pass-aux .day-rail { display: flex; flex-direction: column; flex: 1; min-height: 0; }

.pass-aux .day-grid {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  grid-template-columns: 1fr;
  gap: 0;
  align-content: start;
  border-radius: 0 0 calc(var(--radius-lg) - 1px) calc(var(--radius-lg) - 1px);
}

.pass-aux .day-empty { padding: 12px 13px; }

/* The two float scrollers sit on the app's hairline material rather than the
   platform's light default, which reads as a stripe on the dark ground. */
.pass-aux .day-grid,
.venue-float .track-panel {
  scrollbar-width: thin;
  scrollbar-color: var(--line) transparent;
}

/* The picked venue, attached to the map's right edge: the same facts the rail
   used to swap itself for, over the map, with the list still beside them. */
.venue-float {
  position: absolute;
  top: var(--float-gap);
  right: var(--float-gap);
  /* The rail's own frame, mirrored: the two floats hang off the same top and
     foot lines, so the inspector reads as tall as the list beside it rather
     than as a card that stops wherever its content does. */
  bottom: var(--float-gap);
  width: var(--venue-w);
  z-index: 1030;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
}

.pass-map.picked .map-chrome {
  /* A pick opens the inspector over the map's right edge, so the chrome keeps
     its right-hand anchor and only steps left far enough to clear the panel:
     same float gap from the panel's edge as it keeps from the canvas edge. */
  right: calc(var(--venue-w) + var(--float-gap) * 2);
  transform: none;
}

/* Both bottom corners are spoken for by the floats, so the zoom bar and the
   attribution start right of the rail's column instead. They sit on one line at
   the rail's own foot gap, so the +/- buttons read as part of the same frame
   the list hangs on rather than a leaflet default 10px off the canvas edge. */
.pass-map .leaflet-bottom.leaflet-left {
  left: calc(var(--rail-w) + var(--float-gap) * 1.5);
  bottom: var(--float-gap);
  display: flex;
  align-items: flex-end;
  gap: 12px;
}

.pass-map .leaflet-bottom.leaflet-left .leaflet-control { margin: 0; }

@media (max-width: 900px) {
  .pass-layout { grid-template-columns: 1fr; }
}

/* Stacked: the map keeps the top of the screen, and the two surfaces that
     floated over it run under it in reading order — the rail, then the picked
     venue's inspector. */
@media (max-width: 900px) {
  .pass-map { height: auto; min-height: 0; }
}

/* The seam row only exists where the two surfaces stack: on the canvas the map
   and the list sit side by side and there is no seam between them. Its single
   button folds the list away or brings it back — no drag. */
.rail-toggle-row {
  display: none;
  align-items: center;
  justify-content: center;
  /* The gap between the map and the card below it. */
  height: 26px;
}

.rail-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 20px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg-2);
  color: var(--muted);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.rail-toggle:hover,
.rail-toggle:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
}

.rail-toggle:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* The chevron: up while the list is collapsed (click opens it), down while it
   is open (click folds it away). */
.rail-toggle-caret {
  width: 7px;
  height: 7px;
  border-left: 1.5px solid currentColor;
  border-top: 1.5px solid currentColor;
  transform: translateY(2px) rotate(45deg);
  transition: transform 120ms ease;
}

.rail-toggle-caret.down {
  transform: translateY(-2px) rotate(225deg);
}

@media (max-width: 900px) {
  .rail-toggle-row { display: flex; }
}

/* Collapsed: the row's button leaves the list peeking at half the screen, and
   the map takes the rest. The two heights are written by the button's state
   (`--stack-rail-h` and `--stack-map-h`), so this block only keeps the pair's
   floor from arguing with them. */
@media (max-width: 900px) {
  .pass-map.rail-collapsed .pass-aux,
  .pass-map.rail-collapsed .venue-float {
    min-height: 0;
  }
}

/* A pick gives the list's seat to the inspector, and the boundary it shared
   with the map goes with it — see the inspector's own frame below. */

/* Still the chrome's own frame, so the position control anchors to the map
     rather than to the whole stacked page. */
@media (max-width: 900px) {
  /* The split, as two shares of one column. The map is the index, the list is
     the work: the default hands the list the larger half (42svh of map), and a
     pick — the venue's inspector in the list's seat — hands it more again
     (30svh), so an opened track reads its facts instead of a map it already
     found. Both shares are read off `--stack-map-split`, so the pair can never
     disagree about where the seam is. */
  .pass-map {
    --stack-map-split: 42svh;
    /* The map pane's height: the split, capped so the list's own floor always
       fits under it — a phone on its side would otherwise push the list below
       the fold — and floored at the strip of map a collapsed row keeps. */
    --stack-map-h-now: var(--stack-map-h, clamp(120px, var(--stack-map-split), calc(var(--page-h) - 194px)));
    /* Whatever the map does not take, less the seam row: the list's height. */
    --stack-rail-h-now: var(--stack-rail-h, calc(var(--page-h) - var(--stack-map-h-now) - 26px));
  }

  .pass-map.picked { --stack-map-split: 30svh; }

  .pass-map .map-pane {
    position: relative;
    inset: auto;
    height: var(--stack-map-h-now);
    min-height: 0;
  }
}

@media (max-width: 900px) {
  .pass-map .map-chrome,
  .pass-map.picked .map-chrome {
    top: auto;
    bottom: 12px;
    right: auto;
    left: 50%;
    transform: translateX(-50%);
  }
}

@media (max-width: 900px) {
  .pass-map .leaflet-bottom.leaflet-left { left: 0; }

  /* Stacked, the rail no longer sits left of the bar, so the bar goes back to
     the canvas edge — inset by the same step the chrome keeps from it. */
  .pass-map .leaflet-bottom.leaflet-left .leaflet-control { margin-left: 12px; }
}

@media (max-width: 900px) {
  .pass-aux {
    position: static;
    width: auto;
    /* The handle above it is the gap, and the list takes the rest of the screen
       — whatever the map's share leaves, off the same pair of vars. */
    margin-top: 0;
    height: var(--stack-rail-h-now);
    /* The floor the split itself enforces, so a short window still owes the
       panel a readable seat rather than squeezing it to a sliver. */
    min-height: 168px;
  }
}

/* The list is its own scroller here: the panel has a fixed height the splitter
     owns, so a long network scrolls inside the card rather than growing the
     page past the screen. */
@media (max-width: 900px) {
  .pass-aux .day-grid { max-height: none; min-height: 0; }
}

/* The picked venue takes the list's seat under the same handle, so it wears the
   same frame the list does: the split writes its height, and the panel is the
   scroller inside it rather than a card that runs as long as its facts. */
@media (max-width: 900px) {
  .venue-float {
    position: static;
    width: auto;
    inset: auto;
    margin-top: 0;
    height: var(--stack-rail-h-now);
    min-height: 168px;
  }
}

/* A pick on a phone has nowhere to put the inspector beside the list, so it
   takes the list's place: the rail goes away and the panel opens in its seat
   under the map, with the panel's back arrow returning to the list. */
@media (max-width: 900px) {
  .pass-map.picked .pass-aux { display: none; }
}

.venue-float .track-panel > * + * { margin-top: 0; }

/* The panel itself is the scroller inside that frame: it takes whatever height
   the rail keeps, and its foot is pinned to the frame's bottom. */
.venue-float .track-panel {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.venue-float .track-panel-photo {
  aspect-ratio: auto;
  /* The full-height panel spends some of its extra room on the photograph —
     and keeps it: the panel is a flex column, so the photo must not be the
     item that hands the height back when the body runs long. */
  flex: 0 0 auto;
  height: 224px;
  border-radius: 0;
  border-bottom: 1px solid var(--line);
}

/* The body's own frame: 13px of head above the venue's name, and a deeper
   foot below the last row so the block does not sit flush on the actions'
   border — the panel's bottom edge reads as air, not as a cut. */
.venue-float .track-panel-body { padding: 13px 14px 22px; }

.venue-float .track-panel-body h2 { font-size: 17px; }

/* The ways out rest on the frame's foot when the panel is short, and follow
   the body when it runs past the frame. */
.venue-float .track-panel-actions {
  margin-top: auto;
  padding: 13px 14px 14px;
  background: var(--bg-2);
  border-top: 1px solid var(--line);
}

/* The panel keeps its own scroller here too — the frame is the splitter's, and
   the body scrolls inside it — but the photograph hands height back first, so a
   panel dragged small still shows the venue's name and its actions. */
@media (max-width: 900px) {
  .venue-float .track-panel-photo { aspect-ratio: 16 / 9; height: auto; max-height: 45%; }
}

import { Suspense, lazy, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { CSSProperties } from 'react';
import Banner from '../../../components/Banner/Banner';
import { Link, useSearchParams } from 'react-router-dom';
import { api } from '../../../lib/api';
import { useAuth } from '../../../lib/auth';
import DaysByTrack, { type Entitlement, type RailView } from '../../../components/DaysByTrack/DaysByTrack';
import TrackPanel from '../../../components/TrackPanel/TrackPanel';
import NetworkSkeleton from '../../../components/NetworkSkeleton/NetworkSkeleton';
import UpgradeWelcome from '../../../components/UpgradeWelcome/UpgradeWelcome';
import type { TrackPerk } from '../../../lib/trackOffers';
import type { Entitlement as MapEntitlement, MapTrack } from '../../../lib/trackAccess';
import { enableAstryxUI } from '../../../lib/featureFlags';
import '@fontsource-variable/figtree';
import './RiderHome.scss';
import './RiderHomeAstryx.scss';

/** Leaflet is heavy: load it with the map it belongs to. */
const RiderTrackMap = lazy(() => import('../../../components/RiderTrackMap/RiderTrackMap'));

/**
 * The warn notice floats over the network as a toast and retires itself after
 * this; its × dismisses it sooner. Long enough to read the two links it offers.
 */
const WARN_TOAST_MS = 8000;

/**
 * The stacked layout's collapse row, in px. Below 900px the map and the venue
 * list stack into one column: the row between them carries a single button
 * whose chevron points up while the list is collapsed (click to open it) and
 * down while it is open (click to fold it away and give the map the screen).
 */
const STACK_HANDLE_H = 26;

interface PassInfo {
  id: string;
  status: string;
  seasonYear: number;
  tier: { name: string; slug: string; isDefault: boolean };
  activatedAt: string | null;
  expiresAt: string;
  daysUntilExpiry: number;
  /** True on the free tier: the network, the statuses and the follows list. */
  gated: boolean;
}

/**
 * The network page, at `/tracks`, for everyone. The map and the rail of every
 * partner track are public — a visitor reads each venue's live status — while
 * the pass's own terms (days left, discounts, offers) are what a signed-in
 * rider adds to them. Following is the signed-in-only part.
 *
 * The map owns the viewport: the rail of venues floats over its left edge and
 * never unmounts, and a pick — from a row or from a pin — opens the venue's
 * inspector over its right edge, so inspecting a venue never costs the reader
 * the list they were reading it in.
 */
export default function RiderHome() {
  const { user, loading: authLoading } = useAuth();
  const [params, setParams] = useSearchParams();
  const [pass, setPass] = useState<PassInfo | null>(null);
  /** The word the return trip leaves when the payment has not confirmed yet —
   *  an upgrade's welcome is the modal below, so this only carries a notice. */
  const [paidNote, setPaidNote] = useState<string | null>(null);
  /** The upgrade's welcome, raised once the pass and its days are re-read. */
  const [welcome, setWelcome] = useState(false);
  /** Set when the Stripe return trip arrives without a signed-in rider. */
  const [needsSignIn, setNeedsSignIn] = useState(false);
  const [ents, setEnts] = useState<Entitlement[]>([]);
  const [perks, setPerks] = useState<TrackPerk[]>([]);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState<string | null>(null);
  /** The venue whose inspector is open over the map; null leaves the map bare. */
  const [selectedId, setSelectedId] = useState<string | null>(null);
  /** Which slice of the network the rail lists: all of it, only the venues the
   *  pass includes, or the ones this rider follows. One state, two surfaces —
   *  the map dashes only what the rail leaves out. */
  const [view, setView] = useState<RailView>('all');
  /** The pill has been clicked: the opening slice is a default, not a fixture,
   *  so a rider's own choice outranks it from then on. */
  const slicePicked = useRef(false);
  /** Whether the stacked venue list is folded away under the map. Only the
   *  mobile column has the row that toggles it; the canvas never collapses. */
  const [railCollapsed, setRailCollapsed] = useState(false);
  /** The partner network: the map and the rail read this one copy. */
  const [tracks, setTracks] = useState<MapTrack[]>([]);
  const [networkLoading, setNetworkLoading] = useState(true);
  /** Set when the network read failed twice: the page still lands, with a
   *  notice that offers the read again instead of a frame that never fills. */
  const [netErr, setNetErr] = useState<string | null>(null);

  /** The track picked in the rail — what the inspector over the map shows. */
  const picked = selectedId ? tracks.find((t) => t.id === selectedId) : undefined;

  /**
   * The network read, in one place so a retry re-runs exactly it.
   *
   * This read used to have no error path at all: the promise had a `.then` and
   * nothing else, so a single failed or aborted request left `networkLoading`
   * true for the life of the tab — the page sat on its skeleton, empty, until
   * the reader reloaded and the read went out again. One quiet retry covers the
   * dropped connection that is usually the whole story; a second failure lands
   * the page with a notice that offers the read once more.
   */
  const loadNetwork = useCallback(async () => {
    setNetworkLoading(true);
    setNetErr(null);
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const t = await api.get<{ tracks: MapTrack[] }>('/tracks');
        if (!t.success) throw new Error(t.message);
        setTracks(t.data?.tracks ?? []);
        setNetworkLoading(false);
        return;
      } catch (e) {
        if (attempt === 1) {
          setNetErr(
            e instanceof Error && e.message
              ? `The network did not load (${e.message}).`
              : 'The network did not load.'
          );
        } else {
          await new Promise((resolve) => setTimeout(resolve, 800));
        }
      }
    }
    setNetworkLoading(false);
  }, []);

  useEffect(() => {
    if (authLoading) return;
    let live = true;
    // The network is public, so it lands for a visitor too.
    void loadNetwork();
    (async () => {
      try {
        // The pass is this account's own.
        if (user) {
          const p = await api.get<{ pass: PassInfo | null; entitlements: Entitlement[] }>('/me/pass');
          if (!live) return;
          if (!p.success) setErr(p.message);
          setPass(p.data?.pass ?? null);
          setEnts(p.data?.entitlements ?? []);
          // Offers are a pass's own: nothing to ask for until someone is signed in.
          const k = await api.get<{ perks: TrackPerk[] }>('/me/perks');
          if (!live) return;
          setPerks((k.data?.perks ?? []).filter((x) => x.trackId));
        } else {
          setPass(null);
          setEnts([]);
          setPerks([]);
        }
      } catch {
        // A failed pass read is the notice's own business (`err`); the network
        // still lands, and `finally` is what keeps the frame from hanging.
        if (live && user) setErr('Your pass did not load. Reload to try again.');
      } finally {
        if (live) setLoading(false);
      }
    })();
    return () => {
      live = false;
    };
  }, [user, authLoading, loadNetwork]);

  /**
   * Stripe's success_url comes back with the session id. Confirm that session
   * server-side — the webhook may still be in flight — then re-read the pass and
   * its offers so the page leaves the free-tier read without a reload. The
   * params are retired once handled, so a back-click cannot replay it.
   */
  useEffect(() => {
    if (params.get('checkout') !== 'success') return;
    // A visitor who paid but is not signed in used to land here and see
    // nothing at all: the confirm call needs the rider's cookie. Say so
    // instead, and hand them a sign-in that keeps the session id.
    if (!user) {
      setNeedsSignIn(true);
      return;
    }
    setNeedsSignIn(false);
    const sessionId = params.get('session_id');
    const next = new URLSearchParams(params);
    next.delete('checkout');
    next.delete('session_id');
    next.delete('pass');
    let live = true;
    (async () => {
      // No session id is the dev-simulator path: the payment is already
      // completed server-side, so it is confirmed without a round trip.
      let confirmed = true;
      let word = 'Purchase complete. Your pass is active — your included days are on the network.';
      if (sessionId) {
        const c = await api.get<{ paid: boolean }>(`/payments/checkout/${sessionId}`);
        if (!live) return;
        if (c.success) {
          confirmed = Boolean(c.data?.paid);
          word = confirmed
            ? 'Payment received. Your pass is active — your included days are on the network.'
            : c.message;
        } else {
          // The confirm call itself failed: the webhook may still be settling,
          // so say that rather than claim a pass the rider cannot see yet.
          confirmed = false;
          word = c.message;
        }
      }
      // A payment that has not confirmed leaves a notice; a confirmed one earns
      // the welcome, which waits for the pass's own read so its figures are the
      // rider's, not the marketing copy's.
      if (!confirmed) setPaidNote(word);
      const p = await api.get<{ pass: PassInfo | null; entitlements: Entitlement[] }>('/me/pass');
      if (!live) return;
      if (p.success) {
        const fresh = p.data?.pass ?? null;
        setPass(fresh);
        setEnts(p.data?.entitlements ?? []);
        if (fresh?.status === 'ACTIVE' && !fresh.tier.isDefault) setWelcome(true);
      }
      const k = await api.get<{ perks: TrackPerk[] }>('/me/perks');
      if (!live) return;
      setPerks((k.data?.perks ?? []).filter((x) => x.trackId));
      setParams(next, { replace: true });
    })();
    return () => {
      live = false;
    };
  }, [user, params, setParams]);

  // The map keys its badges by trackId, the same shape the pass endpoint returns.
  const entMap = useMemo(() => {
    const map: Record<string, MapEntitlement> = {};
    for (const e of ents) map[e.trackId] = e;
    return map;
  }, [ents]);

  /** The pass's terms per track, keyed the same way — what the inspector reads. */
  const entById = useMemo(() => {
    const map: Record<string, Entitlement> = {};
    for (const e of ents) map[e.trackId] = e;
    return map;
  }, [ents]);

  /**
   * A venue profile's "On the map" hands its own track over as `?track=<slug>`:
   * the rail opens on that venue's inspector and its pin stays lit, the same
   * pick a click in the list makes.
   */
  useEffect(() => {
    const wanted = params.get('track');
    if (!wanted || selectedId) return;
    const t = tracks.find((x) => x.slug === wanted);
    if (t) setSelectedId(t.id);
  }, [params, tracks, selectedId]);

  /**
   * A follow control — in the rail or in the inspector — moves the network
   * itself: the flag is held on the track, so every row, the slice pills and
   * the map beside them agree the moment one is clicked rather than on the next
   * load.
   */
  const setFollow = useCallback((trackId: string, following: boolean) => {
    setTracks((prev) => prev.map((t) => (t.id === trackId ? { ...t, following } : t)));
  }, []);

  /**
   * Put the inspector away. A pick that arrived on `?track=<slug>` also has to
   * retire that param, or the effect above reopens the same venue the moment it
   * comes back.
   */
  const closePick = useCallback(() => {
    setSelectedId(null);
    if (!params.has('track')) return;
    const next = new URLSearchParams(params);
    next.delete('track');
    setParams(next, { replace: true });
  }, [params, setParams]);

  /**
   * A row's overlay or a pin: one click means one pick, and a second click on
   * the same venue puts the inspector away again. A bare click on the map is the
   * third way out: the map asks for `closePick` itself, which puts the inspector
   * away and lets the map come back out to the whole network.
   */
  const pick = useCallback(
    (trackId: string) => {
      if (trackId === selectedId) {
        closePick();
        return;
      }
      // A pin tapped on the collapsed map opens the list back up with it: the
      // inspector it selects has nowhere to show while the row is folded away.
      setRailCollapsed(false);
      setSelectedId(trackId);
    },
    [selectedId, closePick]
  );

  /**
   * Whether the rail can be narrowed to what the pass carries at all: only a
   * running pass leaves a venue out. A visitor, the free tier and a lapsed pass
   * read every venue as live status rather than as terms, so the slice would
   * have nothing to say.
   */
  const canCover = pass?.status === 'ACTIVE' && !Boolean(pass?.tier.isDefault) && tracks.some((t) => !entMap[t.id]);

  /**
   * The rail opens on Included — the venues the pass carries — because that is
   * the slice a rider's pass actually speaks to. Only a running pass that
   * leaves venues out has one, and that is not known until the pass lands, so
   * the default is applied on that first arrival; a click on the pill retires
   * it, and a visitor or the free tier keeps the whole network.
   */
  useEffect(() => {
    if (slicePicked.current || !canCover) return;
    setView('covered');
  }, [canCover]);

  /**
   * The slice's one control fires this. A venue the covered slice leaves out
   * loses its pin, so an inspector open on one of them would outlive the thing
   * it belongs to: the pick is dropped with it rather than left standing on
   * nothing.
   */
  const setSlice = useCallback(
    (v: RailView) => {
      slicePicked.current = true;
      setView(v);
      if (v === 'covered' && selectedId && !entMap[selectedId]) setSelectedId(null);
    },
    [selectedId, entMap]
  );

  /**
   * The stacked column's one control: it folds the venue list away under the
   * map, and brings it back. The chevron points up while the list is hidden and
   * down while it is open, so the button always reads as the move it makes.
   */
  const toggleRail = useCallback(() => setRailCollapsed((v) => !v), []);

  // The frame is the page: the canvas and the rail arrive in their own places
  // rather than under a line of text. Only what this reader will get is drawn
  // in it — the rail's slice control is a rider's own (the Following slice),
  // and a venue line's day read belongs to a running paid pass, so a visitor,
  // the free tier and a lapsed pass get a frame without either.
  if (loading || authLoading || networkLoading) {
    return (
      <NetworkSkeleton
        filter={user?.role === 'RIDER'}
        terms={Boolean(pass?.status === 'ACTIVE' && !pass.tier.isDefault)}
      />
    );
  }

  const active = pass?.status === 'ACTIVE';
  const free = Boolean(pass?.tier.isDefault);
  /** A pass is on the account but not running — expired, or never activated. */
  const lapsed = Boolean(pass) && !active && !free;
  /**
   * Nothing to count: a visitor, an account with no pass, the free tier, or a
   * lapsed pass. All four read the same network — each venue's live status —
   * so a rider whose pass has run out is not left with the whole page greyed
   * out; the notice above says why the terms are missing.
   */
  const gated = !pass || free || lapsed;
  /** The slice the rail is listing is the covered one — and only while a
   *  running pass leaves venues out, so the map's pins follow it. */
  const hiding = canCover && view === 'covered';

  return (
    <div className={`stack pass-page${enableAstryxUI ? ' axt-page' : ''}`}>
      {err && <Banner tone="bad" close>{err}</Banner>}

      {netErr && (
        <Banner tone="bad" close>
          {netErr}{' '}
          <button type="button" className="ghost" onClick={() => void loadNetwork()}>
            Try again
          </button>
        </Banner>
      )}

      {needsSignIn && (
        <Banner tone="warn" close>
          Your payment went through. Sign in as the rider who bought the pass and it activates
          here.{' '}
          <Link
            className="inline"
            to={`/login?next=${encodeURIComponent(
              window.location.pathname + window.location.search
            )}`}
          >
            Sign in
          </Link>
          .
        </Banner>
      )}

      {/* A payment that has not confirmed yet leaves a notice; a confirmed one
          opens the welcome over the network, which is the upgrade's own read. */}
      {paidNote && (
        <Banner tone="warn" close floating ms={WARN_TOAST_MS}>
          {paidNote}
        </Banner>
      )}

      {welcome && pass && (
        <UpgradeWelcome
          tierName={pass.tier.name}
          expiresAt={pass.expiresAt}
          onClose={() => setWelcome(false)}
        />
      )}

      {free && (
        <Banner tone="warn" close floating ms={WARN_TOAST_MS}>
          You&apos;re on the free pass.{' '}
          <Link className="inline" to="/pricing">
            Upgrade
          </Link>{' '}
          for access to all these tracks and more.
        </Banner>
      )}

      {pass && !active && !free && (
        <Banner tone="warn" close floating ms={WARN_TOAST_MS}>
          No active pass on this account, so the network is listed without terms.{' '}
          <Link className="inline" to="/pricing">
            See pass tiers
          </Link>
          .
        </Banner>
      )}

      <section className="pass-layout with-map">
        <div
          className={`pass-map${picked ? ' picked' : ''}${railCollapsed ? ' rail-collapsed' : ''}`}
          style={
            /* Two seats on a phone, as shares of the screen: the list peeks at
               50% while collapsed and covers 85% once opened. The map takes
               whatever the row leaves, so the pair always adds up to the page. */
            {
              '--stack-rail-h': railCollapsed ? '50svh' : '85svh',
              '--stack-map-h': `calc(var(--page-h) - ${
                railCollapsed ? '50svh' : '85svh'
              } - ${STACK_HANDLE_H}px)`,
            } as CSSProperties
          }
        >
          <Suspense fallback={<div className="muted" style={{ padding: 16 }}>Loading map…</div>}>
            <RiderTrackMap
              tracks={tracks}
              ents={entMap}
              gated={gated}
              hideUncovered={hiding}
              selectedId={selectedId}
              onSelect={pick}
              onClear={closePick}
            />
          </Suspense>

          {/* The stacked column's only control: a button on the seam between
              the map and the list. The chevron points up while the list is
              collapsed (click opens it) and down while it is open (click folds
              it away), so its direction always names the move it makes. The
              row is display:none where the two float side by side. */}
          <div className="rail-toggle-row">
            <button
              type="button"
              className="rail-toggle"
              aria-expanded={!railCollapsed}
              aria-controls="pass-rail"
              aria-label={`${railCollapsed ? 'Open' : 'Collapse'} the ${
                picked ? 'venue details' : 'venue list'
              }`}
              onClick={toggleRail}
            >
              <span className={`rail-toggle-caret${railCollapsed ? '' : ' down'}`} aria-hidden="true" />
            </button>
          </div>

          {/* The rail lists the whole network for everyone — a visitor and a
              free rider read each venue's live status, a paid rider the days
              the pass leaves. It floats over the map's left edge and stays
              put: a pick opens the inspector, never a swap. */}
          <aside className="pass-aux" id="pass-rail">
            {/* The rail's head names who is reading and carries the list's own
                two controls in the same row — the filter and the sort ride
                inside DaysByTrack, so the head is one band, not two. */}
            <DaysByTrack
              identity={
                <span className="rail-pass-name">
                  {pass ? `${user?.name ?? 'Rider'} · ${pass.tier.name}` : 'The network'}
                </span>
              }
              ents={ents}
              tracks={tracks}
              gated={gated}
              view={view}
              onView={setSlice}
              canCover={canCover}
              selectedId={selectedId}
              onSelect={pick}
            />
          </aside>

          {/* The picked venue, attached to the map's right edge: the same facts
              the rail used to swap itself for, without giving up the list. */}
          {picked && (
            <aside className="venue-float" aria-label={`${picked.name}: venue details`}>
              <TrackPanel
                track={picked}
                ent={entById[picked.id]}
                perks={entById[picked.id] ? perks.filter((p) => p.trackId === entById[picked.id]?.trackId) : []}
                active={active}
                gated={gated}
                lapsed={lapsed}
                onClose={closePick}
                onFollow={setFollow}
              />
            </aside>
          )}
        </div>
      </section>
    </div>
  );
}

/* RiderHomeAstryx — the network canvas in the Astryx register, for `/tracks`
   while `enableAstryxUI` is on.

   This is a SKIN, not a second page: `RiderHome` renders the same markup, the
   same data and the same behaviour, and its root gains `.axt-page` when the
   flag is on. Every rule below is written through that wrapper, so the shipped
   `.pass-aux` / `.day-row` / `.venue-float` / `.track-panel` rules in
   RiderHome.scss, DaysByTrack.scss and TrackPanel.scss still own the page the
   moment the flag flips off — nothing was deleted to make room for this.

   The class hooks `verify:map` drives (`.pass-map`, `.pass-aux`, `.day-row`,
   `.day-open`, `.day-name`, `.venue-float`, `.track-close`, `.track-links-btn`)
   are all kept for the same reason.

   Tokens are the same `--ax-*` set AstryxLanding.scss and PricingAstryx.scss
   declare, scoped here rather than on `:root`. */

.axt-page {
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-tint: rgba(242, 121, 2, 0.2);

  --ax-ok: #4ade80;
  --ax-warn: #f5b544;
  --ax-bad: #f87171;

  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-pill: 999px;

  --ax-fs-xs: 13px;
  --ax-fs-sm: 14px;
  --ax-fs-base: 16px;
  --ax-fs-lg: 20px;

  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;

  --ax-shadow-card: 0 26px 60px rgba(0, 0, 0, 0.55);
  --ax-e-med: 250ms;

  background: var(--ax-body);
  color: var(--ax-ink);
  font-family: 'Figtree Variable', 'Figtree', system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-base);
  line-height: 1.5;
}

/* The app is dark by default; the light palette keeps the register readable
   rather than leaving a dark island on a light page. The map's own tile
   inversion is toggled by the theme script in index.html, not here. */
:root[data-theme='light'] .axt-page {
  --ax-body: #f5f6f8;
  --ax-surface: #ffffff;
  --ax-raised: #eef0f3;
  --ax-line: rgba(16, 19, 26, 0.12);
  --ax-line-strong: #c3c9d2;

  --ax-ink: #10131a;
  --ax-ink-2: #4a5260;
  --ax-ink-3: #6a7280;

  --ax-accent-tint: rgba(242, 121, 2, 0.12);
  --ax-shadow-card: 0 20px 44px rgba(16, 19, 26, 0.16);
}

/* ---- The two floats -----------------------------------------------------
   Floating layers carry the shadow, not a hairline as well: the shipped cards
   wear `--bg-2` + 1px `--line`; here the frame is the register's surface with
   the container radius, and the border comes off. Same geometry, same z-index
   ladder (1030, above Leaflet's 1000 controls and below the shell's 1050). */
.axt-page .pass-aux,
.axt-page .venue-float {
  background: var(--ax-surface);
  border: 0;
  border-radius: var(--ax-r-container);
  box-shadow: var(--ax-shadow-card);
}

/* The rail clips its own head radius; a popover still has to be able to drop
   past the card's edge, so the radius lives on the head and the list instead. */
.axt-page .pass-aux { overflow: visible; }
.axt-page .rail-pass {
  border-radius: var(--ax-r-container) var(--ax-r-container) 0 0;
}
.axt-page .pass-aux .day-grid {
  border-radius: 0 0 var(--ax-r-container) var(--ax-r-container);
}

/* ---- Rail head: title, count, sort ------------------------------------- */
.axt-page .rail-pass {
  gap: var(--ax-s-2);
  padding: var(--ax-s-2) var(--ax-s-3) 10px;
  background: transparent;
  border-bottom: 1px solid var(--ax-line);
}

/* Identity and its count sit side by side on one line; the controls keep the
   right edge, which the auto margin on `.rail-tools` already owns. */
.axt-page .rail-pass-id {
  grid-auto-flow: column;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.axt-page .rail-pass-name {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--ax-ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.axt-page .rail-follow {
  gap: var(--ax-s-1);
  height: 28px;
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-xs);
  font-weight: 500;
}

.axt-page .rail-follow input {
  width: 15px;
  height: 15px;
  accent-color: var(--ax-accent);
}

.axt-page .rail-follow:has(input:checked) { color: var(--ax-ink); }

/* The sort is a ghost pill, matching the count chip's height on the row. */
.axt-page .day-sort {
  display: inline-flex;
  align-items: center;
  gap: var(--ax-s-1);
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-pill);
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-xs);
  font-weight: 500;
}

.axt-page .day-sort:hover {
  color: var(--ax-ink);
  border-color: var(--ax-line-strong);
  text-decoration: none;
}

.axt-page .day-sort svg { opacity: 1; color: currentColor; }

.axt-page .day-sort-pop {
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-element);
  box-shadow: var(--ax-shadow-card);
}

/* ---- Rail list ---------------------------------------------------------
   One hairline list, not a stack of cards: the rows share the panel's surface
   and are separated by the rule alone. */
.axt-page .pass-aux .day-grid { background: transparent; }

.axt-page .day-row {
  border-bottom: 1px solid var(--ax-line);
  transition: background-color var(--ax-e-med) ease;
}

.axt-page .day-row.selectable:hover { background: rgba(242, 244, 246, 0.035); }

.axt-page .day-body {
  padding: 10px var(--ax-s-3) 11px;
  gap: 2px 10px;
}

.axt-page .day-name {
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.005em;
  color: var(--ax-ink);
}

.axt-page .day-sub {
  font-size: 12px;
  color: var(--ax-ink-3);
}

.axt-page .day-row.spent .day-name,
.axt-page .day-row.not-covered .day-name { color: var(--ax-ink-2); }

/* One signal for the picked row: an accent outline inset inside the row plus
   the accent tint. The shipped `inset 2px 0 0` bar is a coloured bar, which
   the house rules ban — a border-colour change says the same thing cleanly. */
.axt-page .day-row.selectable.selected {
  background: var(--ax-accent-tint);
  box-shadow: none;
  outline: 1px solid var(--ax-accent);
  outline-offset: -1px;
  border-radius: var(--ax-r-inner);
  border-bottom-color: transparent;
}

.axt-page .day-light-dot { width: 8px; height: 8px; }
.axt-page .day-light.is-open .day-light-dot { background: var(--ax-ok); }
.axt-page .day-light.is-caution .day-light-dot { background: var(--ax-warn); }
.axt-page .day-light.is-closed .day-light-dot { background: var(--ax-bad); }

.axt-page .day-light-tip {
  background: var(--ax-raised);
  border-color: var(--ax-line);
  border-radius: var(--ax-r-inner);
}

.axt-page .pass-aux .day-grid,
.axt-page .venue-float .track-panel {
  scrollbar-color: var(--ax-line-strong) transparent;
}

/* ---- Inspector ---------------------------------------------------------
   The photograph is the card's masthead at a fixed height (the frame, not the
   content, decides how tall the card is), then one info block on a single pair
   of edges, then the footer. */
.axt-page .venue-float { background: var(--ax-surface); }

.axt-page .track-panel-photo {
  flex: 0 0 auto;
  width: 100%;
  height: 208px;
  aspect-ratio: auto;
  border-radius: 0;
  background: var(--ax-raised);
}

.axt-page .track-panel-body {
  gap: 0;
  padding: var(--ax-s-2) var(--ax-s-3) var(--ax-s-3);
}

.axt-page .track-panel-body > * + * { margin-top: 8px; }

/* The head: the venue on the left, its live gate read on the right, both on
   one optical line. `align-items: center` is the fix — the pill centres on the
   name's first line instead of hanging off the top of a wrapped title. */
.axt-page .track-panel-head {
  align-items: center;
  gap: 10px;
}

.axt-page .track-panel-head h2 {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  font-size: var(--ax-fs-lg);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.axt-page .track-name-link {
  color: var(--ax-ink);
  text-decoration-color: transparent;
}

.axt-page .track-name-link:hover {
  color: var(--ax-accent);
  text-decoration-color: transparent;
}

/* The gate pill now sits with the info block, under the place line on the same
   left edge, so the head row is the venue's name and the follow control only. */
.axt-page .track-panel-body > .track-panel-status { margin-top: 6px; }

/* The gate read as the register's Badge: an outlined pill with a dot, not the
   shipped ice chip. The dot carries the state; the word is always the ink. */
.axt-page .status-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--ax-line-strong);
  border-radius: var(--ax-r-pill);
  color: var(--ax-ink);
  font-size: 11.5px;
  font-weight: 600;
}

.axt-page .status-pill::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ax-ok);
}

.axt-page .status-pill.status-hold::before,
.axt-page .status-pill.status-weather_hold::before { background: var(--ax-warn); }
.axt-page .status-pill.status-closed::before { background: var(--ax-ink-3); }

.axt-page .status-pill.status-hold,
.axt-page .status-pill.status-weather_hold,
.axt-page .status-pill.status-closed { border-color: var(--ax-line-strong); }

/* Where the venue is: the second line of the same block, on the same left
   edge as the name and the hour rows. */
.axt-page .track-panel-body > .small.muted {
  font-size: var(--ax-fs-xs);
  line-height: 1.35;
  color: var(--ax-ink-3);
  margin-top: 2px;
}

.axt-page .operator-message {
  padding: 10px var(--ax-s-2);
  border-radius: var(--ax-r-inner);
  background: var(--ax-raised);
}

/* The week: a hairline rule above it, the label small and quiet, then the
   day column and the value column sharing the block's own two edges. */
.axt-page .track-panel-hours {
  margin-top: var(--ax-s-2);
  padding-top: var(--ax-s-2);
  border-top: 1px solid var(--ax-line);
}

.axt-page .track-panel-hours h3 {
  margin: 0 0 2px;
  font-size: var(--ax-fs-xs);
  font-weight: 500;
  letter-spacing: 0;
  color: var(--ax-ink-3);
}

.axt-page .track-panel-hours .hours-row th,
.axt-page .track-panel-hours .hours-row td {
  padding: 7px 0;
  border-bottom: 1px solid var(--ax-line);
  font-size: var(--ax-fs-xs);
}

.axt-page .track-panel-hours .hours-row th {
  width: auto;
  text-align: left;
  font-weight: 400;
  color: var(--ax-ink-2);
}

.axt-page .track-panel-hours .hours-row td {
  text-align: right;
  color: var(--ax-ink);
  font-variant-numeric: tabular-nums;
}

.axt-page .track-panel-hours .hours-row:last-child th,
.axt-page .track-panel-hours .hours-row:last-child td { border-bottom: 0; }

.axt-page .track-panel-hours .hours-row td.is-closed { color: var(--ax-ink-3); }

.axt-page .track-panel-hours .hours-date { color: var(--ax-ink-3); }

/* Today is marked on the DAY, not on the value: a closed Tuesday still reads
   as closed while the row says which day the reader is on. */
.axt-page .track-panel-hours .hours-row.is-today th,
.axt-page .track-panel-hours .hours-row.is-today .hours-date {
  color: var(--ax-accent);
  font-weight: 600;
}

.axt-page .track-panel-hours .hours-row.is-today td { font-weight: 600; }
.axt-page .track-panel-hours .hours-row.is-today td.is-closed { color: var(--ax-ink-2); }

/* ---- Footer ------------------------------------------------------------
   The one text button starts the line, the venue's feeds end it: the row is
   justified, so the profile control sits left and the glyph frames stay right
   however many feeds a venue carries. */
.axt-page .track-panel-actions {
  gap: 0;
  padding: var(--ax-s-2) var(--ax-s-3);
  border-top: 1px solid var(--ax-line);
}

.axt-page .track-panel-links {
  justify-content: space-between;
  gap: 8px;
  width: 100%;
}

.axt-page .track-links-btn {
  height: 34px;
  padding: 0 16px;
  border: 1px solid var(--ax-line-strong);
  border-radius: var(--ax-r-element);
  color: var(--ax-ink);
  font-size: var(--ax-fs-sm);
  font-weight: 500;
}

.axt-page .track-links-btn:hover { border-color: var(--ax-ink-3); }

.axt-page .track-links-btn.track-links-icon {
  width: 34px;
  height: 34px;
  /* The text button's horizontal padding must not reach the glyph frame: with
     `border-box` and 16px of padding a side, the content box is 0px and the
     flex item shrinks the svg to nothing — an empty square. */
  padding: 0;
  color: var(--ax-ink-2);
}

.axt-page .track-links-btn.track-links-icon svg { flex: 0 0 auto; }

.axt-page .track-links-btn.track-links-icon:hover { color: var(--ax-ink); }

.axt-page .track-panel-socials { margin-left: auto; gap: 8px; }

/* The way out, on the photograph's corner: a round ghost over the picture. */
.axt-page .track-close,
.axt-page .track-back {
  top: 10px;
  right: 10px;
  border: 0;
  border-radius: var(--ax-r-pill);
  background: rgba(17, 17, 18, 0.72);
  color: #f2f4f6;
}

.axt-page .track-close { width: 30px; height: 30px; }
.axt-page .track-back { width: 32px; height: 32px; }

.axt-page .track-close:hover,
.axt-page .track-back:hover { background: rgba(17, 17, 18, 0.9); opacity: 1; }

/* ---- Map chrome --------------------------------------------------------
   The zoom bar and the locate control read as the register's icon frames; the
   attribution keeps its own quiet line. */
.axt-page .leaflet-control-zoom {
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-inner);
  overflow: hidden;
  box-shadow: var(--ax-shadow-card);
}

.axt-page .leaflet-control-zoom a {
  width: 32px;
  height: 30px;
  line-height: 30px;
  background: var(--ax-surface);
  border-bottom: 1px solid var(--ax-line);
  color: var(--ax-ink-2);
  font-size: 16px;
}

.axt-page .leaflet-control-zoom a:last-child { border-bottom: 0; }
.axt-page .leaflet-control-zoom a:hover { background: var(--ax-raised); color: var(--ax-ink); }

.axt-page .leaflet-control-attribution { color: var(--ax-ink-3); }

/* ---- Phone -------------------------------------------------------------
   The stacked column keeps the app's own split and collapse; only the card
   material follows the register. A shorter masthead keeps the name, the hours
   and the actions inside the panel the pick was given. */
@media (max-width: 900px) {
  .axt-page .track-panel-photo {
    height: auto;
    aspect-ratio: 16 / 9;
    max-height: 45%;
  }

  .axt-page .track-panel-socials { margin-left: auto; }
}

import PerksSection from '../../components/PerksSection/PerksSection';

/** Standalone route; the My Pass page carries the same section. */
export default function RiderPerks() {
  return (
    <PerksSection
      titleAs="h1"
      blurb="Offers attached to your pass. Most work at any partner business in the network."
    />
  );
}

/* TrackProfile — styles owned by TrackProfile.tsx.
   Split out of styles/global.scss; imported once from TrackProfile.tsx and
   still plain global class names (this app uses no CSS modules). */

.profile-back { display: inline-block; }

/* The head's blocks hang from its top: the venue's name is what the spread is
   about, so it must sit level with the first line the eye lands on rather than
   ride the middle of the row the mark and the actions set. */
.profile-head { display: flex; align-items: flex-start; gap: 24px; flex-wrap: wrap; }

.profile-head-text { flex: 1; min-width: 220px; }

/* The venue's name is the page's own headline, set well above the 26px the rest
   of the app's h1s carry — it is the one thing the spread is about. */
.profile-head-text h1 { margin: 0; font-size: 46px; line-height: 1.05; letter-spacing: -0.03em; font-weight: 600; }

@media (max-width: 640px) {
  .profile-head-text h1 { font-size: 30px; }
}

/* The status/location line sits under the name, with the air a 46px headline
   needs — the app's `.stack` rhythm is inert here (its `:where()` selector
   carries no specificity), so the space is set on the rule itself. */
.profile-meta { gap: 8px; align-items: center; margin-top: 14px; }

.profile-head-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

.profile-head-actions .track-links-btn { cursor: pointer; }

/* The head's buttons share one height: the site's icon button sits beside the
   "On the map" text button, and a glyph square a pixel off the text's own box
   reads as a mistake rather than a pair. */
.profile-head-actions .track-links-btn { height: 32px; }

.profile-head-actions .track-links-btn.track-links-icon { width: 32px; padding: 0; }

.profile-main { min-width: 0; }

/* The lede and the Location & Hours block under it read in one column, so the
   calendar beneath them gets its own air above; the app's `.stack` rhythm is
   too tight for a section break. */
.profile-main > .profile-wide { margin-top: 40px; }

/* The venue's own words, ahead of the facts beneath them — set as the lede they
   are, with the air above them the `.stack` rhythm cannot give (see
   `.profile-meta`). */
.profile-desc { margin: 26px 0 0; font-size: 17px; line-height: 1.62; color: var(--text); max-width: 46ch; }

/* Where the venue is and when it runs, under the venue's own words. */
.profile-loc { margin-top: 40px; }

/* Under the lede the block is no box: the column is one run of hairlines, so
   the map, the address it is reached at, the ways in and the week sit in the
   block's own two-column grid, with the map given the height the rail beside it
   asks for. The utilities (the directions row, the copy button, the site row)
   are the existing ones, unchanged. */
.profile-loc .loc { border: 0; border-radius: 0; padding: 0; }

/* The ways in keep their card material here: a hairline, a little padding, the
   app's small radius and a shadow soft enough to lift the card without turning
   the block back into a box. The edge is the app's own hairline token, the same
   weight as the dividers inside it — a shade lighter than that and the card's
   outline reads as a drawn box rather than the surface ending. */
.profile-loc .loc-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 2px 8px rgba(0, 0, 0, 0.05);
}

.profile-loc .loc-map { min-height: 300px; }

import { useEffect, useRef, useState } from 'react';
import { Link, useParams, useSearchParams } from 'react-router-dom';
import { api } from '../../lib/api';
import { useAuth } from '../../lib/auth';
import { TRACK_STATUS_CLASS, statusLabel } from '../../lib/trackAccess';
import FollowButton from '../../components/FollowButton/FollowButton';
import TrackLogo from '../../components/TrackLogo/TrackLogo';
import TrackName from '../../components/TrackName/TrackName';
import TrackGallery, { type GalleryPhoto } from '../../components/TrackGallery/TrackGallery';
import TrackReviews, { type TrackReview } from '../../components/TrackReviews/TrackReviews';
import Banner from '../../components/Banner/Banner';
import EventCalendar from '../../components/EventCalendar/EventCalendar';
import EventReadSheet from '../../components/EventReadSheet/EventReadSheet';
import VenueLocation from '../../components/VenueLocation/VenueLocation';
import type { HoursWeek as Week } from '../../lib/hoursWeek';
import type { DayStatus, ProfileEvent } from '../../lib/events';
import './TrackProfile.scss';

/** The link mark — two interlocking chain links, the panel's glyph for a venue's site. */
function LinkGlyph() {
  return (
    /* Drawn on a 24 grid so the two link arcs keep their curves; the button CSS
       scales the box to 16px and strokeWidth 2 reads as 1.4 there. */
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <g fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" />
        <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" />
      </g>
    </svg>
  );
}

/**
 * A partner track's own page — the venue as its owner keeps it: banner, mark,
 * what it is running, and the way out to the venue's own site. The pass's terms
 * for the track live on the network page's panel, not here.
 */
interface ProfileTrack {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  city: string | null;
  region: string | null;
  address: string | null;
  country: string | null;
  /** The venue's own point — what the Location block's map is drawn from. */
  lat: number | null;
  lng: number | null;
  website: string | null;
  instagram: string | null;
  facebook: string | null;
  youtube: string | null;
  tiktok: string | null;
  email: string | null;
  phone: string | null;
  imageUrl: string | null;
  bannerUrl: string | null;
  logoUrl: string | null;
  category: string;
  status: string;
  statusNote: string | null;
  /** The operator's own message to riders, when they left one — null otherwise. */
  riderMessage: string | null;
  /** Tomorrow's posted gate read, when the operator has scheduled one. */
  tomorrowStatus?: { day: string; status: string; statusNote: string | null } | null;
  /** Every scheduled day from today on — what the calendar paints. */
  dayStatuses?: DayStatus[];
  hours: string | null;
  /** The venue's week — null when it keeps none on file. */
  hoursWeek: Week | null;
  nextEvent: string | null;
  events: ProfileEvent[];
  photos: GalleryPhoto[];
  /** What riders have written about the venue — the community wall under the schedule. */
  reviews: TrackReview[];
  includedDays: number | null;
  discountDayEnabled: boolean;
  discountDayNumber: number | null;
  discountRate: number | null;
  discountDaysAllowed: number | null;
  extraDayPriceCents: number | null;
}

export default function TrackProfile() {
  const { slug = '' } = useParams();
  /* The rider's own profile lists the reviews they wrote, and each row links
     back here at `?review=<id>` — the review the reader came for. */
  const [searchParams] = useSearchParams();
  const openReviewId = searchParams.get('review');
  const { user } = useAuth();
  const [track, setTrack] = useState<ProfileTrack | null>(null);
  const [following, setFollowing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [missing, setMissing] = useState(false);
  const [reviews, setReviews] = useState<TrackReview[]>([]);
  /** The date a visitor opened — the schedule is read here, so its sheet has
   *  no editor in it: the venue's own page never owns a date. */
  const [readEvent, setReadEvent] = useState<ProfileEvent | null>(null);
  /* A rider's review notice, floated over the page rather than dropped into the
     flow: the wall under it is the receipt, so the line does not need to hold a
     band open while it is up. `ok` picks the tone — a posted review confirms
     itself, a refusal is the venue saying no. `id` counts the notices: posting
     twice says the same sentence twice, and the Banner keys on the id so the
     second one is a fresh toast rather than the retired first. */
  const noticeSeq = useRef(0);
  const [msg, setMsg] = useState<{ id: number; ok: boolean; text: string } | null>(null);
  /* A confirmation has done its job after a glance; a refusal names something to
     fix, so it stays twice as long before retiring itself. */
  const OK_NOTICE_MS = 4000;
  const BAD_NOTICE_MS = 8000;

  /** Re-read the venue after an edit, so the frames and the count agree with the
   *  server without rebuilding the whole review by hand. */
  const refresh = async () => {
    const r = await api.get<{ track: ProfileTrack; following: boolean }>(`/tracks/${slug}`);
    if (!r.success || !r.data?.track) return;
    setTrack(r.data.track);
    setReviews(r.data.track.reviews ?? []);
    setFollowing(Boolean(r.data.following));
  };

  useEffect(() => {
    setLoading(true);
    setMissing(false);
    api
      .get<{ track: ProfileTrack; following: boolean }>(`/tracks/${slug}`)
      .then((r) => {
        if (!r.success || !r.data?.track) {
          setMissing(true);
          return;
        }
        setTrack(r.data.track);
        setReviews(r.data.track.reviews ?? []);
        setFollowing(Boolean(r.data.following));
      })
      .finally(() => setLoading(false));
  }, [slug]);

  if (loading) return <div className="muted">Loading track…</div>;
  if (missing || !track) {
    return (
      <div className="stack">
        <h1>Track not found</h1>
        <div className="small muted">
          No partner track sits at that address.{' '}
          <Link className="inline" to="/tracks">
            See the whole network
          </Link>
          .
        </div>
      </div>
    );
  }

  const where = [track.city, track.region].filter(Boolean).join(', ');
  const banner = track.bannerUrl || track.imageUrl;
  /* The schedule card is only worth a heading when the venue has something on
     it: a date, or a posted gate read (tomorrow's read rides a day status, so
     this covers it). A venue with neither carries no card at all. */
  const hasSchedule = track.events.length > 0 || (track.dayStatuses?.length ?? 0) > 0;

  return (
    <div className="stack profile">
      <Link className="small muted profile-back" to="/tracks">
        ← All tracks
      </Link>

      {/* The gallery the owner keeps, when they have shot the venue; the single
          banner photo is the fallback for one they have not. */}
      {track.photos?.length > 0 ? (
        <TrackGallery name={track.name} photos={track.photos} />
      ) : (
        <div className="profile-banner">
          {banner ? (
            <img src={banner} alt={`${track.name} track`} />
          ) : (
            <div className="profile-banner-fallback" aria-hidden="true" />
          )}
        </div>
      )}

      {/* One column: the venue's own words, then every hard fact — where it is,
          the week it runs, the ways in — beneath them, in the same column. The
          calendar runs full width under both. */}
      <div className="stack profile-main">
        <div className="stack profile-lead">
          <div className="profile-head">
            <TrackLogo name={track.name} logoUrl={track.logoUrl} size={72} />
            <div className="stack profile-head-text">
              <h1>
                <TrackName name={track.name} />
              </h1>
              <div className="row wrap profile-meta">
                <span className={`status-pill status-${track.status.toLowerCase()}`}>
                  {statusLabel(track.status)}
                </span>
                {where && <span className="small muted">{where}</span>}
              </div>
            </div>
            <div className="profile-head-actions">
              {/* Following is a rider action — an operator owns a venue
                  rather than following it. */}
              {user && user.role === 'RIDER' && (
                <FollowButton
                  trackId={track.id}
                  name={track.name}
                  following={following}
                  onChange={setFollowing}
                />
              )}
              {/* The venue's own site rides as an icon button beside the map
                  link, the same height as it: the name is the headline, so the
                  way out to their site sits with the page's other actions. */}
              {track.website && (
                <a
                  className="track-links-btn track-links-icon"
                  href={track.website}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={`${track.name}: website`}
                  title={`${track.name}: website`}
                >
                  <LinkGlyph />
                </a>
              )}
              <Link className="track-links-btn" to={`/tracks?track=${track.slug}`}>
                On the map
              </Link>
            </div>
          </div>

          {/* What the venue keeps as its own words about the place — the lede. */}
          {track.description && <p className="profile-desc">{track.description}</p>}

          {/* The operator's standing note to riders, under the venue's own
              words: the same block the network panel prints on a pick. */}
          {track.riderMessage && (
            <div className="operator-message">
              <span className="muted">From the operator</span>
              <p className="small">{track.riderMessage}</p>
            </div>
          )}

          {/* Where the venue is and when it runs, under its own words. */}
          <div className="profile-loc">
            <VenueLocation
              track={{
                name: track.name,
                city: track.city,
                region: track.region,
                address: track.address,
                country: track.country,
                lat: track.lat,
                lng: track.lng,
                website: track.website,
                instagram: track.instagram,
                facebook: track.facebook,
                youtube: track.youtube,
                tiktok: track.tiktok,
                email: track.email,
                phone: track.phone,
                status: track.status,
                hours: track.hours,
                hoursWeek: track.hoursWeek,
              }}
            />
          </div>
        </div>

        {/* The venue's own calendar: a month at a time, past or future, with
            that month's dates alongside it. The operator's posted gate reads
            paint onto their dates; tomorrow's read also heads the card. A venue
            with nothing posted carries no card at all. */}
        {hasSchedule && (
          <section className="card stack profile-wide">
            <div className="section-head">
              <h3>Schedule</h3>
              {track.tomorrowStatus && (
                <span className={`status-pill ${TRACK_STATUS_CLASS[track.tomorrowStatus.status] ?? 'status-open'}`}>
                  Tomorrow · {statusLabel(track.tomorrowStatus.status)}
                </span>
              )}
            </div>
            <EventCalendar
              key={track.id}
              events={track.events}
              dayStatuses={track.dayStatuses ?? []}
              onOpen={setReadEvent}
            />
          </section>
        )}

        {/* The riders' own side of the venue: what they wrote about it, and —
            for a signed-in rider — the way to write or edit theirs. The notice
            floats over the page, keyed to the event so a second post is a fresh
            toast. */}
        {msg && (
          <Banner
            key={msg.id}
            tone={msg.ok ? 'ok' : 'bad'}
            floating
            close
            ms={msg.ok ? OK_NOTICE_MS : BAD_NOTICE_MS}
          >
            {msg.text}
          </Banner>
        )}
        <TrackReviews
          trackId={track.id}
          trackName={track.name}
          reviews={reviews}
          onChange={setReviews}
          onRefresh={refresh}
          onMessage={(text, ok) => setMsg({ id: ++noticeSeq.current, ok: Boolean(ok), text })}
          currentUserId={user?.role === 'RIDER' ? user.id : undefined}
          openReviewId={openReviewId}
        />
      </div>

      {/* The date itself, read-only: a visitor reads the schedule, and the
          sheet behind a date says everything the owner's sheet says. */}
      {readEvent && (
        <EventReadSheet
          event={readEvent}
          banner={{ name: track.name, slug: track.slug, where: where || null, photo: banner }}
          onClose={() => setReadEvent(null)}
        />
      )}
    </div>
  );
}

/* UserProfile — styles owned by UserProfile.tsx.
   Split out of styles/global.scss; imported once from UserProfile.tsx and
   still plain global class names (this app uses no CSS modules). */

/* The rider's own profile page (/user). It is a private page: the portrait and
   the name are all of it another rider ever sees, so the identity sits in a
   fixed left rail with the pass facts, and the forms and activity fill the
   column beside it. */
.profile-page {
  /* The same measure the calendar page carries (.cal-page, 1320px), centred in
     the shell — the two pages read as one width. */
  max-width: 1320px;
  margin-inline: auto;
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 32px;
  align-items: start;
}

/* The rail: identity, the pass the account is attached to, and the way out.
   Sticky, so the pass state stays in view while a long ride list scrolls. */
.profile-rail {
  position: sticky;
  top: 24px;
  display: grid;
  align-content: start;
  min-width: 0;
}

.profile-identity {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding-bottom: 16px;
}

.profile-identity-photo {
  width: 72px;
  height: 72px;
  flex: none;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--bg-3);
  object-fit: cover;
}

.profile-identity-text {
  display: grid;
  gap: 4px;
  min-width: 0;
  /* Fill the rail beside the portrait, so the name row reaches the rail's far
     edge and the edit square lands on the panel's top-right corner rather than
     wherever the name happens to end. */
  flex: 1;
}

.profile-identity-text h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.25;
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
}

/* The name row: the rider's name, and the edit square at the far right of the
   rail's top block. */
.profile-identity-name {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.profile-identity-name h1 {
  flex: 1;
  min-width: 0;
}

/* The way into the account's own fields, on the identity it edits: a quiet
   square the height of the name's own line, muted until it is pointed at. */
.profile-edit {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  color: var(--muted);
  background: transparent;
}

.profile-edit:hover:not(:disabled) {
  color: var(--text);
  border-color: var(--muted);
  opacity: 1;
}

/* The rider's home town under the name; the email keeps the last line. */
.profile-identity-location {
  display: flex;
  align-items: center;
  gap: 4px;
}

.profile-identity-location svg {
  flex: none;
  opacity: 0.7;
}

/* Each rail block is separated by a hairline, not a card: the rail is one
   surface, and cards inside it would read as cards within a card. */
.profile-rail-block {
  display: grid;
  gap: 8px;
  padding: 16px 0;
  border-top: 1px solid var(--line);
}

.profile-fact {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
}

.profile-fact b {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.profile-cancel {
  justify-self: start;
  margin-top: 4px;
}

/* The account-closing action closes the column: the one thing on this page
   that cannot be undone. It is a card like the sections above it, read as one
   row — the heading and its copy on the left, the action at the far right. */
.profile-danger {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.profile-danger-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
  max-width: 60ch;
}

.profile-danger h3 {
  margin: 0;
  font-size: 14px;
  color: var(--bad);
}

.profile-danger p {
  margin: 0;
  line-height: 1.45;
}

.profile-danger button {
  flex: none;
}

/* The column beside the rail: the form first, then what the rider has done. */
.profile-main {
  display: grid;
  gap: 16px;
  min-width: 0;
}

/* The password form's way in: small and muted, so it reads as a way into the
   form rather than as the page's own primary action. The details form is
   opened from the rail's edit square, on the identity it edits. */
.profile-actions .profile-action {
  color: var(--muted);
}

/* The label lifts to body ink on hover — the global button fade is turned off,
   so the ink shift is the whole signal. */
.profile-actions .profile-action:hover:not(:disabled) {
  color: var(--text);
  opacity: 1;
}

/* The form's own sheet: a touch wider than the plain sheet, since it carries a
   label/field pair rather than one line of copy. */
.profile-sheet {
  width: min(480px, 100%);
}

/* A field's complaint sits under the input it belongs to; the input keeps its
   border and takes the bad ink, so the pair reads as one control. */
.profile-sheet input[aria-invalid='true'] {
  border-color: var(--bad);
}

.profile-field-error {
  margin-top: 4px;
  font-size: 11px;
  line-height: 1.35;
  color: var(--bad);
}

.profile-empty {
  margin: 0;
}

/* Each activity card's head is one row: the heading, then its own tools — the
   time-order words and, on the rides card, the way to the full ledger. */
.profile-card-tools {
  gap: 12px;
}

/* The head is the card's toggle: the title is a bare button, the arrow beside
   it points right while the card is shut and down while it is open. Only the
   rotation and the arrow's ink change — the title keeps its own h3 register. */
.profile-fold-title {
  margin: 0;
  font: inherit;
}

.profile-fold-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0;
  background: none;
  border: 0;
  font: inherit;
  color: inherit;
}

/* The global button fade is off on this one: hover lifts the title to body ink
   and leaves the surface alone. */
.profile-fold-head:hover:not(:disabled) {
  opacity: 1;
  color: var(--text);
}

.profile-fold-arrow {
  flex: none;
  color: var(--muted);
  transition: transform 160ms ease-out, color 140ms ease-out;
}

.profile-fold[data-open='true'] .profile-fold-arrow {
  color: var(--accent);
  transform: rotate(90deg);
}

/* The time-order options are plain words, not a slider: the order the card is
   reading in carries body ink, the other stays muted, and neither paints a
   surface of its own. */
.time-order {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.time-order button {
  background: none;
  border: 0;
  padding: 0;
  font-size: 12px;
  line-height: 1.2;
  color: var(--muted);
}

.time-order button[aria-pressed='true'] {
  color: var(--text);
}

/* The global button fade is off here: hover lifts the option you can still pick
   to body ink and leaves the pressed one where it is. */
.time-order button:hover:not(:disabled) {
  opacity: 1;
}

.time-order button:hover:not(:disabled):not([aria-pressed='true']) {
  color: var(--text);
}

/* The rider's follow list on /user: the venues they keep an eye on, one row
   each, with the follow control to drop one. The row carries the venue and the
   control and nothing else — the venue's own page is where its live status is
   read. */
.follow-list { display: grid; gap: 2px; }

.follow-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.follow-list .follow-row:first-child { border-top: none; }

.follow-who { display: grid; gap: 2px; min-width: 0; }

.follow-who b { font-weight: 600; }

.follow-who:hover b { color: var(--accent); }

/* The rider's rides on /user: the whole ledger, one page at a time, one row
   each — the venue and the kind on the left, the ride day right-aligned so
   the column reads down. */
.ride-list { display: grid; gap: 2px; }

.ride-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: baseline;
  gap: 12px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.ride-list .ride-row:first-child { border-top: none; }

.ride-what { display: grid; gap: 2px; min-width: 0; }

.ride-what b { font-weight: 600; }

.ride-when {
  font-size: 12px;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* The pager under the rides list: Prev, the range, Next — the same read the
   dashboard's Recent scan-ins uses. */
.ride-pager {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 12px;
}

.ride-pager button { padding: 4px 10px; }

.ride-range { font-variant-numeric: tabular-nums; }

/* The reviews the rider has written: the venue, its location and when, the
   words they wrote, and the stars to the right — one row per review. */
.review-list { display: grid; gap: 2px; }

.review-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: start;
  gap: 16px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  /* The row is the link, so it carries no anchor ink of its own. */
  color: inherit;
  text-decoration: none;
  cursor: pointer;
}

.review-list .review-row:first-child { border-top: none; }

.review-what { display: grid; gap: 4px; min-width: 0; }

.review-who { display: inline-block; min-width: 0; font-weight: 600; }

.review-row:hover .review-who { color: var(--accent); }

/* Two lines of the account; the full review lives on the track's page. */
.review-body {
  margin: 2px 0 0;
  font-size: 13px;
  line-height: 1.45;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.review-side {
  display: grid;
  gap: 4px;
  justify-items: end;
  text-align: right;
}

/* A fixed five-star width, so every row's rating ends on the same edge. */
.review-stars {
  display: inline-flex;
  justify-content: space-between;
  width: 64px;
  font-size: 12px;
}

.review-stars .on { color: var(--accent); }

.review-stars .off { color: var(--line); }

/* Under 900px the rail stops floating and leads the column: identity, pass
   facts, then the form — nothing sits side by side, so nothing is sticky. The
   identity block spans the shell here, so the edit square hugs the name it
   edits instead of flying out to the far edge of the page. */
@media (max-width: 900px) {
  .profile-page {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  .profile-rail {
    position: static;
  }

  .profile-identity-text {
    flex: 0 1 auto;
  }
}

import { ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { NavLink } from 'react-router-dom';
import Banner from '../../../components/Banner/Banner';
import Avatar from '../../../components/Avatar/Avatar';
import FollowButton from '../../../components/FollowButton/FollowButton';
import ConfirmSheet from '../../../components/ConfirmSheet/ConfirmSheet';
import PasswordField from '../../../components/PasswordField/PasswordField';
import AvatarPicker from '../../../components/AvatarPicker/AvatarPicker';
import { api, dayStr, money } from '../../../lib/api';
import { cleanLine, cleanNameDraft } from '../../../lib/sanitize';
import { useAuth } from '../../../lib/auth';
import './UserProfile.scss';

interface PassInfo {
  status: string;
  seasonYear: number;
  tier: { name: string; slug: string; isDefault: boolean };
  expiresAt: string;
  daysUntilExpiry: number;
}

/** One row of the rider's own follow list, as `GET /me/follows` returns it. */
interface FollowItem {
  trackId: string;
  slug: string;
  name: string;
  city: string | null;
  region: string | null;
  status: string;
  statusNote: string | null;
  hours: string | null;
  nextEvent: string | null;
}

/** One redeemed day, as `GET /me/history` returns it. */
interface RideItem {
  id: string;
  trackName: string;
  kind: string;
  day: string;
  redeemedAt: string;
  amountChargedCents: number | null;
}

/** One review the rider wrote, as `GET /me/track-reviews` returns it. */
interface ReviewItem {
  id: string;
  rating: number;
  body: string;
  createdAt: string;
  updatedAt: string;
  photos: { id: string; url: string; caption: string | null }[];
  track: { id: string; slug: string; name: string; city: string | null; region: string | null };
}

/** The rides card pages the whole ledger here — there is no separate history page. */
const RIDES_PER_PAGE = 10;

/** The two activity cards sort by time; newest leads unless the rider flips it. */
type SortOrder = 'newest' | 'oldest';

/**
 * One card's time-order control: the two options as plain words, newest first.
 * The order the card below it reads in is the one carrying body ink.
 */
function TimeOrderToggle({
  order,
  onChange,
  label,
}: {
  order: SortOrder;
  onChange: (next: SortOrder) => void;
  /** What this control sorts, for the group's own name. */
  label: string;
}) {
  return (
    <div className="time-order" role="group" aria-label={`Sort ${label} by time`}>
      <button aria-pressed={order === 'newest'} onClick={() => onChange('newest')}>
        Newest
      </button>
      <button aria-pressed={order === 'oldest'} onClick={() => onChange('oldest')}>
        Oldest
      </button>
    </div>
  );
}

/** Field rules, the same ones `PATCH /auth/me` enforces (`auth.controller.ts`). */
const NAME_MIN = 2;
const LOCATION_MAX = 80;
const PASSWORD_MIN = 8;

/**
 * One activity card's head: its title is the toggle, an arrow beside it points
 * right while the card is shut and down while it is open. The card's own tools
 * (the time-order words) ride in the same row, and only while it is open — a
 * shut card is one line.
 */
function FoldHead({
  title,
  open,
  onToggle,
  tools,
}: {
  title: string;
  open: boolean;
  onToggle: () => void;
  tools?: ReactNode;
}) {
  return (
    <div className="row spread profile-card-head">
      <h3 className="profile-fold-title">
        <button
          type="button"
          className="profile-fold-head"
          aria-expanded={open}
          onClick={onToggle}
        >
          {title}
          <svg
            className="profile-fold-arrow"
            width="13"
            height="13"
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="M6 3.5 10.5 8 6 12.5" />
          </svg>
        </button>
      </h3>
      {tools ? <div className="row wrap profile-card-tools">{tools}</div> : null}
    </div>
  );
}

/** One field's complaint, or null when it passes. */
function fieldError(field: 'name' | 'location', value: string): string | null {
  const v = value.trim();
  if (field === 'name') return v.length < NAME_MIN ? `At least ${NAME_MIN} characters.` : null;
  return v.length > LOCATION_MAX ? `Keep it under ${LOCATION_MAX} characters.` : null;
}

/** `Nov 8`, with the year only once the day is from another season. */
function shortDay(iso: string): string {
  const d = new Date(iso);
  const label = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  return d.getFullYear() === new Date().getFullYear() ? label : `${label}, ${d.getFullYear()}`;
}

/** `Nov 8, 2025` — a review's date always names its year. */
function reviewDay(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
}

/** The redemption kind in the rider's words, the same pair the gate card uses. */
function rideKind(kind: string): string {
  return kind === 'DISCOUNT' ? 'Extra day' : 'Included day';
}

/**
 * One of the profile's two forms, opened over the page. It wears the app's
 * sheet chrome, so it reads as a layer over the profile rather than a second
 * kind of dialog. Escape and a click on the backdrop both put it away; the
 * form's own action (Save profile / Update password) is what submits it.
 *
 * A sheet is not a `.stack`, so the fields inside carry their own rhythm (one
 * `.grid`, 16px, plus the `.sheet-actions` row) — nothing spaces them for us.
 */
function ProfileSheet({
  id,
  title,
  onClose,
  children,
}: {
  /** Also the panel's own id, so a verify suite can read the open form. */
  id: string;
  title: string;
  onClose: () => void;
  children: ReactNode;
}) {
  const panel = useRef<HTMLDivElement>(null);

  /* Focus lands on the panel once, when the sheet opens — its own effect, with
     no dependency. `onClose` is a fresh arrow every render of the page, so
     folding this into the listener effect below re-ran it on every keystroke
     and pulled the cursor back out to the panel: one character in, the rest
     of the typing went nowhere. */
  useEffect(() => {
    panel.current?.focus();
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet profile-sheet"
        id={id}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${id}-title`}
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id={`${id}-title`}>
          {title}
        </h2>
        {children}
      </div>
    </div>
  );
}

/**
 * The rider's own profile, at `/user` — the same identity the account menu
 * shows in miniature (portrait, name, tier), at full width, with the fields a
 * rider keeps current themselves and the pass they are attached to. Operators
 * and admins have their own profile pages (`/operator/profile`, `/admin`); the
 * account menu's identity card links each role to the matching one.
 *
 * The page is private: the portrait and the name are all of it another rider
 * would ever see, so the identity sits in a fixed left rail together with the
 * pass facts a rider checks often, and the forms and activity fill the column
 * beside it. The rail is `position: sticky`, so the pass state stays in view
 * while a long ride list scrolls.
 */
export default function UserProfile() {
  const { user, refresh } = useAuth();
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [pass, setPass] = useState<PassInfo | null>(null);
  const [follows, setFollows] = useState<FollowItem[]>([]);
  const [rides, setRides] = useState<RideItem[]>([]);
  const [rideTotal, setRideTotal] = useState(0);
  const [ridePage, setRidePage] = useState(1);
  const [reviews, setReviews] = useState<ReviewItem[]>([]);
  /* The three activity cards start folded: each head is its own toggle, so the
     column opens as identity, actions and three one-line headings. */
  const [ridesOpen, setRidesOpen] = useState(false);
  const [reviewsOpen, setReviewsOpen] = useState(false);
  const [followingOpen, setFollowingOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  /** A field shows its complaint only after the rider has left it once. */
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  /** The unsubscribe question, open while the rider decides. */
  const [confirmCancel, setConfirmCancel] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  /** The delete-account question, open while the rider decides. */
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deletePassword, setDeletePassword] = useState('');
  const [deleting, setDeleting] = useState(false);
  const [deleteErr, setDeleteErr] = useState<string | null>(null);
  /** The reset-password section: the three fields it owns and its own state. */
  const [currentPwd, setCurrentPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [confirmPwd, setConfirmPwd] = useState('');
  const [pwdTouched, setPwdTouched] = useState<Record<string, boolean>>({});
  const [pwdSaving, setPwdSaving] = useState(false);
  const [pwdErr, setPwdErr] = useState<string | null>(null);
  /** Which of the two forms the page has open over it, if either. */
  const [openSheet, setOpenSheet] = useState<'details' | 'password' | null>(null);
  /** The order each of the two activity cards reads in. Newest leads. */
  const [rideOrder, setRideOrder] = useState<SortOrder>('newest');
  const [reviewOrder, setReviewOrder] = useState<SortOrder>('newest');

  useEffect(() => {
    if (!user) return;
    setName(user.name);
    setLocation(user.location ?? '');
  }, [user]);

  useEffect(() => {
    api.get<{ pass: PassInfo | null }>('/me/pass').then((r) => setPass(r.data?.pass ?? null));
    api.get<{ follows: FollowItem[] }>('/me/follows').then((r) => setFollows(r.data?.follows ?? []));
    api
      .get<{ reviews: ReviewItem[] }>('/me/track-reviews')
      .then((r) => setReviews(r.data?.reviews ?? []));
  }, []);

  /** Every ride, one page at a time. The order is the server's, so flipping the
      pill reads the ledger from the other end (and the pager restarts at 1),
      rather than reversing the page already on screen. */
  useEffect(() => {
    let live = true;
    api
      .get<{ redemptions: RideItem[]; total: number }>(
        `/me/history?page=${ridePage}&perPage=${RIDES_PER_PAGE}&order=${rideOrder === 'newest' ? 'desc' : 'asc'}`
      )
      .then((r) => {
        if (!live) return;
        setRides(r.data?.redemptions ?? []);
        setRideTotal(r.data?.total ?? 0);
      });
    return () => {
      live = false;
    };
  }, [rideOrder, ridePage]);

  /** The rider's own reviews, in the order they asked for. The endpoint hands
      back every one of them, so this sorts the whole set. */
  const sortedReviews = useMemo(() => {
    const rows = reviews.slice();
    rows.sort((a, b) => {
      const cmp = a.createdAt.localeCompare(b.createdAt);
      return reviewOrder === 'newest' ? -cmp : cmp;
    });
    return rows;
  }, [reviews, reviewOrder]);

  const rideTotalPages = Math.max(1, Math.ceil(rideTotal / RIDES_PER_PAGE));
  const rideFrom = rideTotal ? (ridePage - 1) * RIDES_PER_PAGE + 1 : 0;
  const rideTo = Math.min(ridePage * RIDES_PER_PAGE, rideTotal);

  if (!user) return null;

  /* Dirty means a field differs from what is on file; whitespace alone is not a change. */
  const nameErr = fieldError('name', name);
  const locationErr = fieldError('location', location);
  const dirty =
    name.trim() !== user.name.trim() ||
    location.trim() !== (user.location ?? '').trim();
  const valid = !nameErr && !locationErr;
  const canSave = dirty && valid && !saving;

  /* The reset form needs the current password, a long-enough new one, and the
     same new one typed twice. */
  const newPwdErr =
    newPwd.length > 0 && newPwd.length < PASSWORD_MIN
      ? `At least ${PASSWORD_MIN} characters.`
      : null;
  const confirmErr =
    confirmPwd.length > 0 && confirmPwd !== newPwd ? 'Passwords do not match.' : null;
  const canReset =
    Boolean(currentPwd) &&
    newPwd.length >= PASSWORD_MIN &&
    confirmPwd === newPwd &&
    !pwdSaving;

  const save = async () => {
    if (!canSave) return;
    setSaving(true);
    setMsg(null);
    setErr(null);
    const body: Record<string, string> = { name: name.trim(), location: location.trim() };
    const res = await api.patch('/auth/me', body);
    setSaving(false);
    if (!res.success) {
      setErr(res.message || 'Could not save your profile.');
      return;
    }
    setTouched({});
    await refresh();
    setMsg('Profile saved.');
    setOpenSheet(null);
  };

  /**
   * Reset the password: the account's current password proves it is the rider,
   * then the new one replaces the hash. The session survives, so nothing on the
   * page has to be re-read.
   */
  const resetPassword = async () => {
    if (!canReset) return;
    setPwdSaving(true);
    setPwdErr(null);
    setMsg(null);
    const res = await api.patch('/auth/me', { password: newPwd, currentPassword: currentPwd });
    setPwdSaving(false);
    if (!res.success) {
      setPwdErr(res.message || 'Could not update your password.');
      return;
    }
    setCurrentPwd('');
    setNewPwd('');
    setConfirmPwd('');
    setPwdTouched({});
    setMsg('Password updated.');
    setOpenSheet(null);
  };

  /** Unsubscribe: retire the paid pass, then re-read what is left on the account. */
  const cancelPass = async () => {
    setCancelling(true);
    setMsg(null);
    setErr(null);
    const res = await api.post('/me/pass/cancel');
    setCancelling(false);
    setConfirmCancel(false);
    if (!res.success) {
      setErr(res.message || 'Could not cancel your pass.');
      return;
    }
    const next = await api.get<{ pass: PassInfo | null }>('/me/pass');
    setPass(next.data?.pass ?? null);
    await refresh();
    setMsg(res.message || 'Pass cancelled.');
  };

  /** Close the account for good: password first, then the session is gone. */
  const deleteAccount = async () => {
    setDeleting(true);
    setDeleteErr(null);
    const res = await api.del('/auth/me', { password: deletePassword });
    setDeleting(false);
    if (!res.success) {
      setDeleteErr(res.message || 'Could not delete your account.');
      return;
    }
    setConfirmDelete(false);
    // A full load: the session cookie is gone, so the app re-reads /auth/me as
    // signed out and the sign-in page can say the account was closed.
    window.location.assign('/login?deleted=1');
  };

  /**
   * The rail's pass block is the paid pass and nothing else: the free tier is
   * the account's default state, already named under the name, so a rider
   * without a paid pass gets no facts block at all. The account-closing action
   * lives at the foot of the right column instead, as one row.
   */
  const paidPass = pass && !pass.tier.isDefault ? pass : null;

  /** Only a running paid pass can be cancelled; the free tier is where it lands. */
  const cancellable = Boolean(paidPass) && paidPass!.status === 'ACTIVE';

  return (
    <div className="stack">
      {msg && <Banner tone="ok" close>{msg}</Banner>}
      {err && <Banner tone="bad" close>{err}</Banner>}

      <div className="profile-page">
        <aside className="profile-rail">
          <div className="profile-identity">
            <Avatar src={user.avatarUrl} name={user.name} className="profile-identity-photo" />
            <div className="profile-identity-text">
              {/* The name reads with the way into the account's own fields
                  beside it: editing your name and home town is an identity
                  action, so it sits on the identity, not in the column of
                  cards. The same sheet the old Details button opened. */}
              <div className="profile-identity-name">
                <h1>{user.name}</h1>
                <button
                  id="open-profile-details"
                  className="profile-edit"
                  aria-haspopup="dialog"
                  aria-label="Edit profile"
                  title="Edit profile"
                  onClick={() => setOpenSheet('details')}
                >
                  <svg
                    width="15"
                    height="15"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    aria-hidden="true"
                  >
                    <path d="M4 20h4L18.5 9.5a2.83 2.83 0 0 0-4-4L4 16v4z" />
                    <path d="M13.5 6.5l4 4" />
                  </svg>
                </button>
              </div>
              {user.location && (
                <div className="small muted profile-identity-location">
                  <svg
                    width="12"
                    height="12"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    aria-hidden="true"
                  >
                    <path d="M12 21s7-6.3 7-11a7 7 0 1 0-14 0c0 4.7 7 11 7 11z" />
                    <circle cx="12" cy="10" r="2.5" />
                  </svg>
                  {user.location}
                </div>
              )}
              <div className="small muted">{user.email}</div>
            </div>
          </div>

          {paidPass && (
            <div className="profile-rail-block">
              <div className="profile-fact">
                <span className="muted">Status</span>
                <b>{paidPass.status.toLowerCase()}</b>
              </div>
              {cancellable && (
                <div className="profile-fact">
                  <span className="muted">Days left</span>
                  <b>{paidPass.daysUntilExpiry}</b>
                </div>
              )}
              <div className="profile-fact">
                <span className="muted">Valid through</span>
                <b>{dayStr(paidPass.expiresAt)}</b>
              </div>
              {cancellable && (
                <button
                  className="ghost small danger profile-cancel"
                  onClick={() => setConfirmCancel(true)}
                >
                  Cancel pass
                </button>
              )}
            </div>
          )}
        </aside>

        <div className="profile-main">
          {/* The password form opens from here; the details form is opened
              from the identity rail's edit button. Each opens over the page in
              its own sheet, instead of a card the reader scrolls past. */}
          <div className="row wrap profile-actions">
            <button
              id="open-profile-reset-password"
              className="ghost small profile-action"
              aria-haspopup="dialog"
              onClick={() => setOpenSheet('password')}
            >
              Reset password
            </button>
          </div>

          <section className="card stack profile-fold" data-open={ridesOpen}>
            <FoldHead
              title="Rides"
              open={ridesOpen}
              onToggle={() => setRidesOpen((v) => !v)}
              tools={
                ridesOpen && (
                  <TimeOrderToggle
                    order={rideOrder}
                    onChange={(next) => {
                      setRideOrder(next);
                      setRidePage(1);
                    }}
                    label="rides"
                  />
                )
              }
            />
            {ridesOpen &&
              (rides.length === 0 ? (
                <p className="small muted profile-empty">
                  No rides yet.
                </p>
              ) : (
                <>
                  <div className="ride-list">
                    {rides.map((r) => (
                      <div className="ride-row" key={r.id}>
                        <div className="ride-what">
                          <b>{r.trackName}</b>
                          <span className="small muted">
                            {rideKind(r.kind)}
                            {r.amountChargedCents ? ` · ${money(r.amountChargedCents)}` : ''}
                          </span>
                        </div>
                        <span className="ride-when">{shortDay(r.day)}</span>
                      </div>
                    ))}
                  </div>
                  {rideTotalPages > 1 && (
                    <div className="ride-pager">
                      <button
                        type="button"
                        className="ghost small"
                        onClick={() => setRidePage((p) => Math.max(1, p - 1))}
                        disabled={ridePage === 1}
                      >
                        Prev
                      </button>
                      <span className="tiny muted ride-range">
                        {rideFrom}–{rideTo} of {rideTotal}
                      </span>
                      <button
                        type="button"
                        className="ghost small"
                        onClick={() => setRidePage((p) => Math.min(rideTotalPages, p + 1))}
                        disabled={ridePage === rideTotalPages}
                      >
                        Next
                      </button>
                    </div>
                  )}
                </>
              ))}
          </section>

          <section className="card stack profile-fold" data-open={reviewsOpen}>
            <FoldHead
              title="My reviews"
              open={reviewsOpen}
              onToggle={() => setReviewsOpen((v) => !v)}
              tools={
                reviewsOpen && (
                  <TimeOrderToggle order={reviewOrder} onChange={setReviewOrder} label="reviews" />
                )
              }
            />
            {reviewsOpen &&
              (reviews.length === 0 ? (
                <p className="small muted profile-empty">
                  No reviews yet.
                </p>
              ) : (
                <div className="review-list">
                  {sortedReviews.map((r) => {
                    const edited = r.updatedAt !== r.createdAt;
                    return (
                      /* The whole row opens the review where it lives: the venue's
                         page, scrolled to that card and — when it carries frames —
                         with the viewer up on it. */
                      <NavLink
                        to={`/tracks/${r.track.slug}?review=${r.id}`}
                        className="review-row"
                        key={r.id}
                      >
                        <div className="review-what">
                          <b className="review-who">{r.track.name}</b>
                          <span className="small muted">
                            {[r.track.city, r.track.region].filter(Boolean).join(', ') || '—'}
                            {` · ${reviewDay(r.createdAt)}${edited ? ' · edited' : ''}`}
                          </span>
                          {r.body && <p className="review-body">{r.body}</p>}
                        </div>
                        <div className="review-side">
                          <span className="review-stars" aria-label={`${r.rating} out of 5`}>
                            {[1, 2, 3, 4, 5].map((n) => (
                              <span key={n} className={n <= r.rating ? 'on' : 'off'} aria-hidden>
                                ★
                              </span>
                            ))}
                          </span>
                          {r.photos.length > 0 && (
                            <span className="tiny muted">
                              {r.photos.length} photo{r.photos.length === 1 ? '' : 's'}
                            </span>
                          )}
                        </div>
                      </NavLink>
                    );
                  })}
                </div>
              ))}
          </section>

          <section className="card stack profile-fold" data-open={followingOpen}>
            <FoldHead
              title="Following"
              open={followingOpen}
              onToggle={() => setFollowingOpen((v) => !v)}
            />
            {followingOpen &&
              (follows.length === 0 ? (
                <p className="small muted profile-empty">
                  No tracks followed yet.
                </p>
              ) : (
                <div className="follow-list">
                  {follows.map((f) => (
                    <div className="follow-row" key={f.trackId}>
                      <NavLink to={`/tracks/${f.slug}`} className="follow-who">
                        <b>{f.name}</b>
                        <span className="small muted">
                          {[f.city, f.region].filter(Boolean).join(', ') || '—'}
                        </span>
                      </NavLink>
                      {/* Dropping a follow leaves the row in place, its control
                          now reading Follow, so a mis-click is one click to undo;
                          the row is gone the next time the page is loaded, since
                          the list is re-read from the server (`/me/follows`). */}
                      <FollowButton trackId={f.trackId} name={f.name} following compact />
                    </div>
                  ))}
                </div>
              ))}
          </section>

          <section className="card profile-danger">
            <div className="profile-danger-copy">
              <h3>Danger Zone</h3>
              <p className="small muted">
                Closing the account removes your name, email, follows and pass. Receipts and scan
                history stay with the operator reports, and the email can be used to register again.
              </p>
            </div>
            <button
              className="ghost small danger"
              onClick={() => {
                setDeletePassword('');
                setDeleteErr(null);
                setConfirmDelete(true);
              }}
            >
              Delete account
            </button>
          </section>
        </div>
      </div>

      {/* The two forms, each opened by its own control: the identity rail's
          edit button for the details, the column's button for the password.
          One at a time: `openSheet` holds which. */}
      {openSheet === 'details' && (
        <ProfileSheet id="profile-details" title="Details" onClose={() => setOpenSheet(null)}>
          {/* The rider's own photo, saved on its own (it is not part of the
              name/location draft below). */}
          <AvatarPicker />
          <div className="grid">
            <div>
              <label htmlFor="profile-name">Name</label>
              <input
                id="profile-name"
                value={name}
                onChange={(e) => setName(cleanNameDraft(e.target.value, 80))}
                onBlur={() => setTouched((t) => ({ ...t, name: true }))}
                aria-invalid={touched.name && nameErr ? true : undefined}
                aria-describedby={touched.name && nameErr ? 'profile-name-error' : undefined}
              />
              {touched.name && nameErr && (
                <div className="profile-field-error" id="profile-name-error" role="alert">
                  {nameErr}
                </div>
              )}
            </div>
            <div>
              <label htmlFor="profile-location">Location</label>
              <input
                id="profile-location"
                value={location}
                onChange={(e) => setLocation(cleanLine(e.target.value, 80))}
                onBlur={() => setTouched((t) => ({ ...t, location: true }))}
                placeholder="Where you ride from"
                aria-invalid={touched.location && locationErr ? true : undefined}
                aria-describedby={touched.location && locationErr ? 'profile-location-error' : undefined}
              />
              {touched.location && locationErr && (
                <div className="profile-field-error" id="profile-location-error" role="alert">
                  {locationErr}
                </div>
              )}
            </div>
          </div>
          <div className="sheet-actions">
            <button className="ghost small" onClick={() => setOpenSheet(null)}>
              Close
            </button>
            <button className="primary small" onClick={save} disabled={!canSave}>
              {saving ? 'Saving…' : 'Save profile'}
            </button>
          </div>
        </ProfileSheet>
      )}

      {openSheet === 'password' && (
        <ProfileSheet
          id="profile-reset-password"
          title="Reset password"
          onClose={() => setOpenSheet(null)}
        >
          <div className="grid">
            <div>
              <label htmlFor="profile-current-password">Current password</label>
              <PasswordField
                id="profile-current-password"
                value={currentPwd}
                onChange={(e) => setCurrentPwd(e.target.value)}
                autoComplete="current-password"
              />
            </div>
            <div>
              <label htmlFor="profile-new-password">New password</label>
              <PasswordField
                id="profile-new-password"
                value={newPwd}
                onChange={(e) => setNewPwd(e.target.value)}
                onBlur={() => setPwdTouched((t) => ({ ...t, next: true }))}
                autoComplete="new-password"
                ariaInvalid={pwdTouched.next && !!newPwdErr}
                ariaDescribedBy={
                  pwdTouched.next && newPwdErr ? 'profile-new-password-error' : undefined
                }
              />
              {pwdTouched.next && newPwdErr && (
                <div className="profile-field-error" id="profile-new-password-error" role="alert">
                  {newPwdErr}
                </div>
              )}
            </div>
            <div>
              <label htmlFor="profile-confirm-password">Confirm new password</label>
              <PasswordField
                id="profile-confirm-password"
                value={confirmPwd}
                onChange={(e) => setConfirmPwd(e.target.value)}
                onBlur={() => setPwdTouched((t) => ({ ...t, confirm: true }))}
                autoComplete="new-password"
                ariaInvalid={pwdTouched.confirm && !!confirmErr}
                ariaDescribedBy={
                  pwdTouched.confirm && confirmErr ? 'profile-confirm-password-error' : undefined
                }
              />
              {pwdTouched.confirm && confirmErr && (
                <div className="profile-field-error" id="profile-confirm-password-error" role="alert">
                  {confirmErr}
                </div>
              )}
            </div>
          </div>
          <div className="sheet-actions">
            <button className="ghost small" onClick={() => setOpenSheet(null)}>
              Close
            </button>
            <button className="primary small" onClick={resetPassword} disabled={!canReset}>
              {pwdSaving ? 'Updating…' : 'Update password'}
            </button>
          </div>
          {/* The server's own answer — a wrong current password lands here. */}
          {pwdErr && (
            <div className="profile-field-error" role="alert">
              {pwdErr}
            </div>
          )}
        </ProfileSheet>
      )}

      {confirmCancel && pass && (
        <ConfirmSheet
          id="cancel-pass"
          title={`Cancel ${pass.tier.name}?`}
          copy={`The pass ends today and the account returns to the free pass. The ${pass.daysUntilExpiry} day${pass.daysUntilExpiry === 1 ? '' : 's'} left on it are forfeited. Ride history and receipts stay.`}
          confirmLabel={cancelling ? 'Cancelling…' : 'Cancel pass'}
          cancelLabel="Keep pass"
          onConfirm={cancelPass}
          onCancel={() => setConfirmCancel(false)}
        />
      )}

      {confirmDelete && (
        <ConfirmSheet
          id="delete-account"
          title="Delete your account?"
          copy="This closes the account. Your details and follows are removed, the pass is cancelled, and the email is freed for a new account."
          confirmLabel={deleting ? 'Deleting…' : 'Delete account'}
          cancelLabel="Keep account"
          confirmDisabled={deleting || !deletePassword}
          onConfirm={deleteAccount}
          onCancel={() => setConfirmDelete(false)}
        >
          <div>
            <label htmlFor="delete-account-password">Password</label>
            <PasswordField
              id="delete-account-password"
              value={deletePassword}
              onChange={(e) => setDeletePassword(e.target.value)}
              placeholder="Confirm your password"
              autoComplete="current-password"
            />
          </div>
          {deleteErr && <Banner tone="bad" close>{deleteErr}</Banner>}
        </ConfirmSheet>
      )}
    </div>
  );
}

/* UserProfileAstryx — styles owned by UserProfileAstryx.tsx (the `/user` page
   while `enableAstryxUI` is on).

   Same rules as PricingAstryx.scss and AstryxLanding.scss: the register's
   tokens are declared scoped to `.axu-page`, never on `:root`, and every
   override is written through that wrapper so it out-specifies UserProfile.scss's
   plain `.profile-*` rules and global.scss's `.card` / `.primary` / `.ghost`
   base layer.

   Two things this sheet does that the other register sheets do not:

   1. It remaps the app's base tokens inside the page (`--bg-2`, `--line`,
      `--text`, `--muted`, `--accent`, `--radius` …) so the shared components the
      page reuses unchanged — Banner, Avatar, FollowButton, PasswordField,
      ConfirmSheet — sit in the register without a rule each.
   2. It keeps UserProfile.scss's geometry rather than restating it: the rail,
      the two-column grid and the row lists are already there and this page
      inherits them. What it overrides is the material (surfaces, radii, ink,
      the pill segment) and the fold chrome.

   The class hooks `verify-profile.cjs` reads (`.profile-rail`,
   `.profile-identity .profile-edit`, `#open-profile-details`,
   `.profile-actions .profile-action`, `.profile-fold*`, `.profile-card-head h3`,
   `.ride-*`, `.review-*`, `.follow-*`, `.time-order`, the sheet ids) are kept
   from the previous page on purpose — this is a restyle, and the suite guards
   the restyle. */

.axu-page {
  /* Surfaces, one step each: page ground, band, raised card. */
  --ax-body: #111112;
  --ax-surface: #1f1f22;
  --ax-raised: #28292c;
  --ax-line: rgba(242, 244, 246, 0.1);
  --ax-line-strong: #494d53;

  /* Ink. */
  --ax-ink: #e7eaed;
  --ax-ink-2: #aaafb5;
  --ax-ink-3: #6f747c;

  /* Moto Pass's own orange, on the register's accent / edge / tint trio. */
  --ax-accent: #ff8a3f;
  --ax-accent-edge: #eb6e00;
  --ax-accent-tint: rgba(242, 121, 2, 0.2);
  --ax-accent-ink: #0a1317;

  /* The two tones the page still needs: the saved/ok green and the bad red. */
  --ax-ok: #4ade80;
  --ax-bad: #f87171;

  /* Radii, type ramp and spacing steps. */
  --ax-r-inner: 8px;
  --ax-r-element: 12px;
  --ax-r-container: 16px;
  --ax-r-page: 24px;
  --ax-r-pill: 999px;

  --ax-fs-xs: 12px;
  --ax-fs-sm: 13px;
  --ax-fs-base: 15px;
  --ax-fs-lg: 18px;
  --ax-fs-xl: 22px;

  --ax-s-1: 6px;
  --ax-s-2: 12px;
  --ax-s-3: 18px;
  --ax-s-4: 24px;

  --ax-e-med: 200ms;

  /* The base tokens, remapped so the shared components follow the register. */
  --bg: var(--ax-body);
  --bg-2: var(--ax-surface);
  --bg-3: var(--ax-raised);
  --line: var(--ax-line);
  --text: var(--ax-ink);
  --muted: var(--ax-ink-2);
  --dim: var(--ax-ink-3);
  --accent: var(--ax-accent);
  --accent-rgb: 255, 138, 63;
  --ok: var(--ax-ok);
  --bad: var(--ax-bad);
  --radius: var(--ax-r-inner);
  --radius-lg: var(--ax-r-element);

  color: var(--ax-ink);
  font-family: 'Figtree Variable', 'Figtree', system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: var(--ax-fs-base);
  line-height: 1.5;
}

.axu-page .axu-stack {
  display: flex;
  flex-direction: column;
  gap: var(--ax-s-3);
  max-width: 1320px;
  margin-inline: auto;
  padding-bottom: var(--ax-s-4);
}

/* The two-column page: the rail that holds the identity, and the column of
   cards beside it. UserProfile.scss owns this grid; the register only sets the
   rail's width and the gap between the two. */
.axu-page .profile-page {
  grid-template-columns: 296px minmax(0, 1fr);
  gap: var(--ax-s-4);
}

/* ---- Panel: the band every block on this page sits on ------------------- */
.axu-page .axu-panel {
  background: var(--ax-surface);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-container);
  padding: var(--ax-s-3);
}

/* The rail is one tall band, so it takes the page radius and its blocks are
   separated by hairlines rather than by gaps. */
.axu-page .axu-rail {
  border-radius: var(--ax-r-page);
  padding: var(--ax-s-4) var(--ax-s-3);
}

.axu-page .axu-rail .profile-identity {
  padding-bottom: var(--ax-s-3);
}

.axu-page .axu-rail .profile-identity-text h1 {
  font-size: var(--ax-fs-xl);
  font-weight: 600;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.axu-page .axu-rail .profile-identity-photo {
  width: 64px;
  height: 64px;
  border: 1px solid var(--ax-line);
  border-radius: 50%;
}

.axu-page .axu-identity-email {
  color: var(--ax-ink-3);
  font-size: var(--ax-fs-xs);
}

/* The way into the details form: a quiet square on the identity it edits. */
.axu-page .profile-edit {
  width: 28px;
  height: 28px;
  border: 1px solid transparent;
  border-radius: var(--ax-r-inner);
  color: var(--ax-ink-3);
  background: transparent;
  transition:
    color var(--ax-e-med),
    border-color var(--ax-e-med);
}

.axu-page .profile-edit:hover:not(:disabled) {
  color: var(--ax-ink);
  border-color: var(--ax-line-strong);
  background: transparent;
}

/* ---- Rail blocks: the pass, then the account's quiet action ------------- */
.axu-page .axu-rail .profile-rail-block {
  gap: var(--ax-s-1);
  padding: var(--ax-s-2) 0;
  border-top: 1px solid var(--ax-line);
}

.axu-page .axu-rail .profile-rail-block:last-child {
  padding-bottom: 0;
}

.axu-page .axu-pass-name {
  display: flex;
  align-items: center;
  gap: var(--ax-s-1);
  margin-bottom: var(--ax-s-1);
}

/* The tier, as the register's Badge: the accent at a fifth, on its own edge. */
.axu-page .axu-badge {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 9px;
  border: 1px solid rgba(255, 138, 63, 0.38);
  border-radius: var(--ax-r-pill);
  background: var(--ax-accent-tint);
  color: var(--ax-accent);
  font-size: var(--ax-fs-xs);
  font-weight: 600;
  letter-spacing: 0.01em;
}

.axu-page .axu-pass-status {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-3);
}

/* A running pass says so in green; anything else stays neutral. */
.axu-page .axu-pass-status.is-active {
  color: var(--ax-ok);
}

.axu-page .axu-rail .profile-fact {
  font-size: var(--ax-fs-sm);
  color: var(--ax-ink-2);
}

.axu-page .axu-rail .profile-fact b {
  color: var(--ax-ink);
}

.axu-page .axu-rail .profile-cancel {
  justify-self: start;
  margin-top: var(--ax-s-2);
  color: var(--ax-bad);
  border-color: rgba(248, 113, 113, 0.32);
  border-radius: var(--ax-r-inner);
}

.axu-page .axu-rail .profile-cancel:hover:not(:disabled) {
  border-color: var(--ax-bad);
}

/* The password form's way in, at the foot of the rail: a quiet button sized to
   its label, on the same left guide as the pass action above it. */
.axu-page .profile-actions {
  display: flex;
}

.axu-page .profile-actions .profile-action {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  width: auto;
  height: 30px;
  padding: 0 var(--ax-s-2);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-inner);
  background: transparent;
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-sm);
  text-align: left;
}

.axu-page .profile-actions .profile-action:hover:not(:disabled) {
  color: var(--ax-ink);
  border-color: var(--ax-line-strong);
  background: transparent;
  opacity: 1;
}

/* ---- The main column ---------------------------------------------------- */
.axu-page .axu-main {
  gap: var(--ax-s-2);
}

.axu-page .profile-fold {
  padding: var(--ax-s-2) var(--ax-s-3);
}

.axu-page .profile-fold[data-open='true'] {
  padding-bottom: var(--ax-s-2);
}

/* A fold's head is one row: the title as its own toggle, the card's tools at
   the far end. Shut, it is the card's only line. */
.axu-page .axu-fold-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ax-s-2);
  min-height: 32px;
}

.axu-page .profile-card-head h3 {
  margin: 0;
  font-size: var(--ax-fs-base);
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
}

/* The title owns the row's free width, so a shut card's arrow sits at the far
   end of its own line and the whole row is the toggle. With tools beside it,
   the title takes only what it needs and the arrow keeps close to the label. */
.axu-page .axu-fold-head .profile-fold-title {
  flex: 1;
  min-width: 0;
}

.axu-page .profile-fold-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--ax-s-1);
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  text-align: left;
  color: var(--ax-ink);
}

.axu-page .axu-fold-head:has(.axu-fold-tools) .profile-fold-head {
  width: auto;
  justify-content: flex-start;
}

.axu-page .profile-fold-head:hover:not(:disabled) {
  color: var(--ax-ink);
  opacity: 1;
}

.axu-page .profile-fold-arrow {
  flex: none;
  color: var(--ax-ink-3);
  transition:
    transform var(--ax-e-med) ease-out,
    color var(--ax-e-med) ease-out;
}

.axu-page .profile-fold[data-open='true'] .profile-fold-arrow {
  color: var(--ax-accent);
  transform: rotate(90deg);
}

/* The Segmented Control: the time order of a card. The track is the sunken
   ground, the segment in force is the raised thumb. The two segments are the
   real controls (`aria-pressed`), so the state is read off the button. */
.axu-page .time-order {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-pill);
  background: var(--ax-body);
}

.axu-page .time-order button {
  height: 24px;
  padding: 0 var(--ax-s-2);
  border: 0;
  border-radius: var(--ax-r-pill);
  background: transparent;
  color: var(--ax-ink-3);
  font-size: var(--ax-fs-xs);
  font-weight: 500;
  line-height: 1.2;
  transition:
    background var(--ax-e-med),
    color var(--ax-e-med);
}

.axu-page .time-order button[aria-pressed='true'] {
  background: var(--ax-raised);
  color: var(--ax-ink);
  box-shadow: inset 0 0 0 1px var(--ax-line);
}

.axu-page .time-order button:hover:not(:disabled) {
  opacity: 1;
  color: var(--ax-ink-2);
}

.axu-page .time-order button[aria-pressed='true']:hover:not(:disabled) {
  color: var(--ax-ink);
}

/* ---- Rows: rides, reviews, follows -------------------------------------- */
.axu-page .ride-list,
.axu-page .review-list,
.axu-page .follow-list {
  margin-top: var(--ax-s-1);
}

.axu-page .ride-row,
.axu-page .follow-row {
  padding: 10px 0;
  border-top: 1px solid var(--ax-line);
}

.axu-page .review-row {
  padding: 12px 0;
  border-top: 1px solid var(--ax-line);
}

.axu-page .ride-what b,
.axu-page .follow-who b,
.axu-page .review-who {
  font-weight: 600;
}

.axu-page .ride-when {
  font-size: var(--ax-fs-xs);
  color: var(--ax-ink-2);
}

.axu-page .review-what .small,
.axu-page .follow-who .small,
.axu-page .ride-what .small {
  color: var(--ax-ink-3);
}

.axu-page .review-body {
  margin-top: var(--ax-s-1);
  font-size: var(--ax-fs-sm);
  color: var(--ax-ink-2);
}

.axu-page .review-stars {
  width: 62px;
  font-size: var(--ax-fs-xs);
}

.axu-page .review-stars .on {
  color: var(--ax-accent);
}

.axu-page .review-stars .off {
  color: var(--ax-line-strong);
}

.axu-page .review-row:hover .review-who,
.axu-page .follow-who:hover b {
  color: var(--ax-accent);
}

.axu-page .profile-empty {
  margin: var(--ax-s-1) 0 0;
  color: var(--ax-ink-2);
}

/* The pager is one quiet row under the ledger. */
.axu-page .ride-pager {
  gap: var(--ax-s-2);
  margin-top: var(--ax-s-2);
}

.axu-page .ride-pager button {
  height: 28px;
  padding: 0 var(--ax-s-2);
  border: 1px solid var(--ax-line);
  border-radius: var(--ax-r-inner);
  background: transparent;
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-sm);
}

.axu-page .ride-pager button:hover:not(:disabled) {
  color: var(--ax-ink);
  border-color: var(--ax-line-strong);
  opacity: 1;
}

.axu-page .ride-range {
  color: var(--ax-ink-3);
}

/* ---- Danger zone: the one thing on the page that cannot be undone ------- */
.axu-page .profile-danger {
  align-items: center;
  gap: var(--ax-s-4);
  border-color: rgba(248, 113, 113, 0.24);
}

.axu-page .profile-danger h3 {
  font-size: var(--ax-fs-sm);
  font-weight: 600;
  color: var(--ax-bad);
}

.axu-page .profile-danger p {
  color: var(--ax-ink-2);
  font-size: var(--ax-fs-sm);
}

.axu-page .profile-danger button {
  height: 32px;
  padding: 0 var(--ax-s-2);
  border: 1px solid rgba(248, 113, 113, 0.32);
  border-radius: var(--ax-r-inner);
  background: transparent;
  color: var(--ax-bad);
  font-size: var(--ax-fs-sm);
}

.axu-page .profile-danger button:hover:not(:disabled) {
  border-color: var(--ax-bad);
  background: rgba(248, 113, 113, 0.08);
  opacity: 1;
}

/* ---- The two forms over the page --------------------------------------- */
.axu-page .profile-sheet {
  width: min(460px, 100%);
  padding: var(--ax-s-3);
  border: 1px solid var(--ax-line);
