import { ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { NavLink } from 'react-router-dom';
// Self-hosted Figtree, as the landing and the pricing page do — never a Google
// Fonts link.
import '@fontsource-variable/figtree';
import Banner from '../../../components/Banner/Banner';
import Avatar from '../../../components/Avatar/Avatar';
import FollowButton from '../../../components/FollowButton/FollowButton';
import ConfirmSheet from '../../../components/ConfirmSheet/ConfirmSheet';
import PasswordField from '../../../components/PasswordField/PasswordField';
import AvatarPicker from '../../../components/AvatarPicker/AvatarPicker';
import { api, dayStr, money } from '../../../lib/api';
import { cleanLine, cleanNameDraft } from '../../../lib/sanitize';
import { useAuth } from '../../../lib/auth';
import './UserProfileAstryx.scss';

/**
 * `/user` in the reference design system's register (Astryx), chosen by
 * `enableAstryxUI`. `UserProfile.tsx` is still here in full and untouched —
 * flip the flag to `false` and the previous page comes back exactly as it was.
 *
 * This is a MIRROR of the shipped profile, not a rethink of it: the same reads,
 * the same two forms, the same three folded cards, the same copy. What changes
 * is the register — page-radius bands instead of plain cards, the type ramp,
 * the pill-segment time control, and the account's two forms opened from the
 * rail the identity sits on. The class hooks `verify-profile.cjs` reads
 * (`.profile-rail`, `.profile-identity .profile-edit`, `#open-profile-details`,
 * `.profile-actions .profile-action`, `.profile-fold*`, `.profile-card-head
 * h3`, `.ride-*`, `.review-*`, `.follow-*`, `.time-order`, the sheet ids) are
 * kept on purpose, so the suite guards this page the same way it guarded the
 * last one.
 */

interface PassInfo {
  status: string;
  seasonYear: number;
  tier: { name: string; slug: string; isDefault: boolean };
  expiresAt: string;
  daysUntilExpiry: number;
}

/** One row of the rider's own follow list, as `GET /me/follows` returns it. */
interface FollowItem {
  trackId: string;
  slug: string;
  name: string;
  city: string | null;
  region: string | null;
  status: string;
  statusNote: string | null;
  hours: string | null;
  nextEvent: string | null;
}

/** One redeemed day, as `GET /me/history` returns it. */
interface RideItem {
  id: string;
  trackName: string;
  kind: string;
  day: string;
  redeemedAt: string;
  amountChargedCents: number | null;
}

/** One review the rider wrote, as `GET /me/track-reviews` returns it. */
interface ReviewItem {
  id: string;
  rating: number;
  body: string;
  createdAt: string;
  updatedAt: string;
  photos: { id: string; url: string; caption: string | null }[];
  track: { id: string; slug: string; name: string; city: string | null; region: string | null };
}

/** The rides card pages the whole ledger here — there is no separate history page. */
const RIDES_PER_PAGE = 10;

/** The two activity cards sort by time; newest leads unless the rider flips it. */
type SortOrder = 'newest' | 'oldest';

/**
 * The register's Segmented Control, wearing the hooks the previous page's time
 * control carried: `.time-order` named for what it sorts, and one `aria-pressed`
 * button per order, newest first.
 */
function TimeOrderToggle({
  order,
  onChange,
  label,
}: {
  order: SortOrder;
  onChange: (next: SortOrder) => void;
  /** What this control sorts, for the group's own name. */
  label: string;
}) {
  return (
    <div className="time-order" role="group" aria-label={`Sort ${label} by time`}>
      <button aria-pressed={order === 'newest'} onClick={() => onChange('newest')}>
        Newest
      </button>
      <button aria-pressed={order === 'oldest'} onClick={() => onChange('oldest')}>
        Oldest
      </button>
    </div>
  );
}

/** Field rules, the same ones `PATCH /auth/me` enforces (`auth.controller.ts`). */
const NAME_MIN = 2;
const LOCATION_MAX = 80;
const PASSWORD_MIN = 8;

/**
 * A fold's head: the title is the toggle, an arrow beside it points right while
 * the card is shut and down while it is open. The card's own tools (the
 * time-order segment) ride in the same row, and only while it is open — a shut
 * card is one line.
 */
function FoldHead({
  title,
  open,
  onToggle,
  tools,
}: {
  title: string;
  open: boolean;
  onToggle: () => void;
  tools?: ReactNode;
}) {
  return (
    <div className="profile-card-head axu-fold-head">
      <h3 className="profile-fold-title">
        <button type="button" className="profile-fold-head" aria-expanded={open} onClick={onToggle}>
          {title}
          <svg
            className="profile-fold-arrow"
            width="13"
            height="13"
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.6"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <path d="M6 3.5 10.5 8 6 12.5" />
          </svg>
        </button>
      </h3>
      {tools ? <div className="profile-card-tools axu-fold-tools">{tools}</div> : null}
    </div>
  );
}

/** One field's complaint, or null when it passes. */
function fieldError(field: 'name' | 'location', value: string): string | null {
  const v = value.trim();
  if (field === 'name') return v.length < NAME_MIN ? `At least ${NAME_MIN} characters.` : null;
  return v.length > LOCATION_MAX ? `Keep it under ${LOCATION_MAX} characters.` : null;
}

/** `Nov 8`, with the year only once the day is from another season. */
function shortDay(iso: string): string {
  const d = new Date(iso);
  const label = d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  return d.getFullYear() === new Date().getFullYear() ? label : `${label}, ${d.getFullYear()}`;
}

/** `Nov 8, 2025` — a review's date always names its year. */
function reviewDay(iso: string): string {
  const d = new Date(iso);
  return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
}

/** The redemption kind in the rider's words, the same pair the gate card uses. */
function rideKind(kind: string): string {
  return kind === 'DISCOUNT' ? 'Extra day' : 'Included day';
}

/**
 * One of the profile's two forms, opened over the page. Same sheet chrome the
 * app uses everywhere (`.sheet-backdrop` + `.sheet`), so it reads as a layer
 * over the profile rather than a second kind of dialog; the register only
 * changes its surface and radius. Escape and a click on the backdrop both put
 * it away; the form's own action (Save profile / Update password) submits it.
 */
function ProfileSheet({
  id,
  title,
  onClose,
  children,
}: {
  /** Also the panel's own id, so a verify suite can read the open form. */
  id: string;
  title: string;
  onClose: () => void;
  children: ReactNode;
}) {
  const panel = useRef<HTMLDivElement>(null);

  /* Focus lands on the panel once, when the sheet opens — its own effect, with
     no dependency. `onClose` is a fresh arrow every render of the page, so
     folding this into the listener effect below re-ran it on every keystroke
     and pulled the cursor back out to the panel. */
  useEffect(() => {
    panel.current?.focus();
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return (
    <div className="sheet-backdrop" onClick={onClose}>
      <div
        className="sheet profile-sheet"
        id={id}
        role="dialog"
        aria-modal="true"
        aria-labelledby={`${id}-title`}
        tabIndex={-1}
        ref={panel}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 className="sheet-title" id={`${id}-title`}>
          {title}
        </h2>
        {children}
      </div>
    </div>
  );
}

/**
 * The rider's own profile, at `/user`, in the Astryx register: the identity sits
 * in a sticky rail together with the pass facts and the way into the account's
 * own fields, while the rider's rides, reviews and follows fill the column
 * beside it. Operators and admins have their own profile pages
 * (`/operator/profile`, `/admin`).
 */
export default function UserProfileAstryx() {
  const { user, refresh } = useAuth();
  const [name, setName] = useState('');
  const [location, setLocation] = useState('');
  const [pass, setPass] = useState<PassInfo | null>(null);
  const [follows, setFollows] = useState<FollowItem[]>([]);
  const [rides, setRides] = useState<RideItem[]>([]);
  const [rideTotal, setRideTotal] = useState(0);
  const [ridePage, setRidePage] = useState(1);
  const [reviews, setReviews] = useState<ReviewItem[]>([]);
  /* The three activity cards start folded: each head is its own toggle, so the
     column opens as three one-line headings. */
  const [ridesOpen, setRidesOpen] = useState(false);
  const [reviewsOpen, setReviewsOpen] = useState(false);
  const [followingOpen, setFollowingOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  /** A field shows its complaint only after the rider has left it once. */
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  /** The unsubscribe question, open while the rider decides. */
  const [confirmCancel, setConfirmCancel] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  /** The delete-account question, open while the rider decides. */
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [deletePassword, setDeletePassword] = useState('');
  const [deleting, setDeleting] = useState(false);
  const [deleteErr, setDeleteErr] = useState<string | null>(null);
  /** The reset-password form: the three fields it owns and its own state. */
  const [currentPwd, setCurrentPwd] = useState('');
  const [newPwd, setNewPwd] = useState('');
  const [confirmPwd, setConfirmPwd] = useState('');
  const [pwdTouched, setPwdTouched] = useState<Record<string, boolean>>({});
  const [pwdSaving, setPwdSaving] = useState(false);
  const [pwdErr, setPwdErr] = useState<string | null>(null);
  /** Which of the two forms the page has open over it, if either. */
  const [openSheet, setOpenSheet] = useState<'details' | 'password' | null>(null);
  /** The order each of the two activity cards reads in. Newest leads. */
  const [rideOrder, setRideOrder] = useState<SortOrder>('newest');
  const [reviewOrder, setReviewOrder] = useState<SortOrder>('newest');

  useEffect(() => {
    if (!user) return;
    setName(user.name);
    setLocation(user.location ?? '');
  }, [user]);

  useEffect(() => {
    api.get<{ pass: PassInfo | null }>('/me/pass').then((r) => setPass(r.data?.pass ?? null));
    api.get<{ follows: FollowItem[] }>('/me/follows').then((r) => setFollows(r.data?.follows ?? []));
    api
      .get<{ reviews: ReviewItem[] }>('/me/track-reviews')
      .then((r) => setReviews(r.data?.reviews ?? []));
  }, []);

  /** Every ride, one page at a time. The order is the server's, so flipping the
      segment reads the ledger from the other end (and the pager restarts at 1),
      rather than reversing the page already on screen. */
  useEffect(() => {
    let live = true;
    api
      .get<{ redemptions: RideItem[]; total: number }>(
        `/me/history?page=${ridePage}&perPage=${RIDES_PER_PAGE}&order=${rideOrder === 'newest' ? 'desc' : 'asc'}`
      )
      .then((r) => {
        if (!live) return;
        setRides(r.data?.redemptions ?? []);
        setRideTotal(r.data?.total ?? 0);
      });
    return () => {
      live = false;
    };
  }, [rideOrder, ridePage]);

  /** The rider's own reviews, in the order they asked for. The endpoint hands
      back every one of them, so this sorts the whole set. */
  const sortedReviews = useMemo(() => {
    const rows = reviews.slice();
    rows.sort((a, b) => {
      const cmp = a.createdAt.localeCompare(b.createdAt);
      return reviewOrder === 'newest' ? -cmp : cmp;
    });
    return rows;
  }, [reviews, reviewOrder]);

  const rideTotalPages = Math.max(1, Math.ceil(rideTotal / RIDES_PER_PAGE));
  const rideFrom = rideTotal ? (ridePage - 1) * RIDES_PER_PAGE + 1 : 0;
  const rideTo = Math.min(ridePage * RIDES_PER_PAGE, rideTotal);

  if (!user) return null;

  /* Dirty means a field differs from what is on file; whitespace alone is not a change. */
  const nameErr = fieldError('name', name);
  const locationErr = fieldError('location', location);
  const dirty =
    name.trim() !== user.name.trim() ||
    location.trim() !== (user.location ?? '').trim();
  const valid = !nameErr && !locationErr;
  const canSave = dirty && valid && !saving;

  /* The reset form needs the current password, a long-enough new one, and the
     same new one typed twice. */
  const newPwdErr =
    newPwd.length > 0 && newPwd.length < PASSWORD_MIN
      ? `At least ${PASSWORD_MIN} characters.`
      : null;
  const confirmErr =
    confirmPwd.length > 0 && confirmPwd !== newPwd ? 'Passwords do not match.' : null;
  const canReset =
    Boolean(currentPwd) &&
    newPwd.length >= PASSWORD_MIN &&
    confirmPwd === newPwd &&
    !pwdSaving;

  const save = async () => {
    if (!canSave) return;
    setSaving(true);
    setMsg(null);
    setErr(null);
    const body: Record<string, string> = { name: name.trim(), location: location.trim() };
    const res = await api.patch('/auth/me', body);
    setSaving(false);
    if (!res.success) {
      setErr(res.message || 'Could not save your profile.');
      return;
    }
    setTouched({});
    await refresh();
    setMsg('Profile saved.');
    setOpenSheet(null);
  };

  /**
   * Reset the password: the account's current password proves it is the rider,
   * then the new one replaces the hash. The session survives, so nothing on the
   * page has to be re-read.
   */
  const resetPassword = async () => {
    if (!canReset) return;
    setPwdSaving(true);
    setPwdErr(null);
    setMsg(null);
    const res = await api.patch('/auth/me', { password: newPwd, currentPassword: currentPwd });
    setPwdSaving(false);
    if (!res.success) {
      setPwdErr(res.message || 'Could not update your password.');
      return;
    }
    setCurrentPwd('');
    setNewPwd('');
    setConfirmPwd('');
    setPwdTouched({});
    setMsg('Password updated.');
    setOpenSheet(null);
  };

  /** Unsubscribe: retire the paid pass, then re-read what is left on the account. */
  const cancelPass = async () => {
    setCancelling(true);
    setMsg(null);
    setErr(null);
    const res = await api.post('/me/pass/cancel');
    setCancelling(false);
    setConfirmCancel(false);
    if (!res.success) {
      setErr(res.message || 'Could not cancel your pass.');
      return;
    }
    const next = await api.get<{ pass: PassInfo | null }>('/me/pass');
    setPass(next.data?.pass ?? null);
    await refresh();
    setMsg(res.message || 'Pass cancelled.');
  };

  /** Close the account for good: password first, then the session is gone. */
  const deleteAccount = async () => {
    setDeleting(true);
    setDeleteErr(null);
    const res = await api.del('/auth/me', { password: deletePassword });
    setDeleting(false);
    if (!res.success) {
      setDeleteErr(res.message || 'Could not delete your account.');
      return;
    }
    setConfirmDelete(false);
    // A full load: the session cookie is gone, so the app re-reads /auth/me as
    // signed out and the sign-in page can say the account was closed.
    window.location.assign('/login?deleted=1');
  };

  /**
   * The rail names the paid pass and nothing else: the free tier is the
   * account's default state, already named under the name, so a rider without a
   * paid pass gets no pass block at all.
   */
  const paidPass = pass && !pass.tier.isDefault ? pass : null;

  /** Only a running paid pass can be cancelled; the free tier is where it lands. */
  const cancellable = Boolean(paidPass) && paidPass!.status === 'ACTIVE';

  return (
    <div className="axu-page">
      <div className="axu-stack">
        {msg && <Banner tone="ok" close>{msg}</Banner>}
        {err && <Banner tone="bad" close>{err}</Banner>}

        <div className="profile-page axu-grid">
          <aside className="profile-rail">
            <div className="axu-panel axu-rail">
              <div className="profile-identity">
                <Avatar
                  src={user.avatarUrl}
                  name={user.name}
                  className="profile-identity-photo"
                />
                <div className="profile-identity-text">
                  {/* The name reads with the way into the account's own fields
                      beside it: editing your name and home town is an identity
                      action, so it sits on the identity, not in a card. */}
                  <div className="profile-identity-name">
                    <h1>{user.name}</h1>
                    <button
                      id="open-profile-details"
                      className="profile-edit"
                      aria-haspopup="dialog"
                      aria-label="Edit profile"
                      title="Edit profile"
                      onClick={() => setOpenSheet('details')}
                    >
                      <svg
                        width="15"
                        height="15"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M4 20h4L18.5 9.5a2.83 2.83 0 0 0-4-4L4 16v4z" />
                        <path d="M13.5 6.5l4 4" />
                      </svg>
                    </button>
                  </div>
                  {user.location && (
                    <div className="small muted profile-identity-location">
                      <svg
                        width="12"
                        height="12"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="2"
                        aria-hidden="true"
                      >
                        <path d="M12 21s7-6.3 7-11a7 7 0 1 0-14 0c0 4.7 7 11 7 11z" />
                        <circle cx="12" cy="10" r="2.5" />
                      </svg>
                      {user.location}
                    </div>
                  )}
                  <div className="small muted axu-identity-email">{user.email}</div>
                </div>
              </div>

              {paidPass && (
                <div className="profile-rail-block">
                  <div className="axu-pass-name">
                    <span className="axu-badge">{paidPass.tier.name}</span>
                    <span className={cancellable ? 'axu-pass-status is-active' : 'axu-pass-status'}>
                      {paidPass.status.toLowerCase()}
                    </span>
                  </div>
                  <div className="profile-fact">
                    <span className="muted">Valid through</span>
                    <b>{dayStr(paidPass.expiresAt)}</b>
                  </div>
                  {cancellable && (
                    <div className="profile-fact">
                      <span className="muted">Days left</span>
                      <b>{paidPass.daysUntilExpiry}</b>
                    </div>
                  )}
                  {cancellable && (
                    <button
                      className="ghost small danger profile-cancel"
                      onClick={() => setConfirmCancel(true)}
                    >
                      Cancel pass
                    </button>
                  )}
                </div>
              )}

              {/* The password form's way in. It edits the account rather than the
                  identity, so it closes the rail under its own hairline. */}
              <div className="profile-rail-block">
                <div className="profile-actions">
                  <button
                    id="open-profile-reset-password"
                    className="ghost small profile-action"
                    aria-haspopup="dialog"
                    onClick={() => setOpenSheet('password')}
                  >
                    Reset password
                  </button>
                </div>
              </div>
            </div>
          </aside>

          <div className="profile-main axu-main">
            <section className="axu-panel profile-fold" data-open={ridesOpen}>
              <FoldHead
                title="Rides"
                open={ridesOpen}
                onToggle={() => setRidesOpen((v) => !v)}
                tools={
                  ridesOpen && (
                    <TimeOrderToggle
                      order={rideOrder}
                      onChange={(next) => {
                        setRideOrder(next);
                        setRidePage(1);
                      }}
                      label="rides"
                    />
                  )
                }
              />
              {ridesOpen &&
                (rides.length === 0 ? (
                  <p className="small muted profile-empty">No rides yet.</p>
                ) : (
                  <>
                    <div className="ride-list">
                      {rides.map((r) => (
                        <div className="ride-row" key={r.id}>
                          <div className="ride-what">
                            <b>{r.trackName}</b>
                            <span className="small muted">
                              {rideKind(r.kind)}
                              {r.amountChargedCents ? ` · ${money(r.amountChargedCents)}` : ''}
                            </span>
                          </div>
                          <span className="ride-when">{shortDay(r.day)}</span>
                        </div>
                      ))}
                    </div>
                    {rideTotalPages > 1 && (
                      <div className="ride-pager">
                        <button
                          type="button"
                          className="ghost small"
                          onClick={() => setRidePage((p) => Math.max(1, p - 1))}
                          disabled={ridePage === 1}
                        >
                          Prev
                        </button>
                        <span className="tiny muted ride-range">
                          {rideFrom}–{rideTo} of {rideTotal}
                        </span>
                        <button
                          type="button"
                          className="ghost small"
                          onClick={() => setRidePage((p) => Math.min(rideTotalPages, p + 1))}
                          disabled={ridePage === rideTotalPages}
                        >
                          Next
                        </button>
                      </div>
                    )}
                  </>
                ))}
            </section>

            <section className="axu-panel profile-fold" data-open={reviewsOpen}>
              <FoldHead
                title="My reviews"
                open={reviewsOpen}
                onToggle={() => setReviewsOpen((v) => !v)}
                tools={
                  reviewsOpen && (
                    <TimeOrderToggle order={reviewOrder} onChange={setReviewOrder} label="reviews" />
                  )
                }
              />
              {reviewsOpen &&
                (reviews.length === 0 ? (
                  <p className="small muted profile-empty">No reviews yet.</p>
                ) : (
                  <div className="review-list">
                    {sortedReviews.map((r) => {
                      const edited = r.updatedAt !== r.createdAt;
                      return (
                        /* The whole row opens the review where it lives: the
                           venue's page, scrolled to that card and — when it
                           carries frames — with the viewer up on it. */
                        <NavLink
                          to={`/tracks/${r.track.slug}?review=${r.id}`}
                          className="review-row"
                          key={r.id}
                        >
                          <div className="review-what">
                            <b className="review-who">{r.track.name}</b>
                            <span className="small muted">
                              {[r.track.city, r.track.region].filter(Boolean).join(', ') || '—'}
                              {` · ${reviewDay(r.createdAt)}${edited ? ' · edited' : ''}`}
                            </span>
                            {r.body && <p className="review-body">{r.body}</p>}
                          </div>
                          <div className="review-side">
                            <span className="review-stars" aria-label={`${r.rating} out of 5`}>
                              {[1, 2, 3, 4, 5].map((n) => (
                                <span key={n} className={n <= r.rating ? 'on' : 'off'} aria-hidden>
                                  ★
                                </span>
                              ))}
                            </span>
                            {r.photos.length > 0 && (
                              <span className="tiny muted">
                                {r.photos.length} photo{r.photos.length === 1 ? '' : 's'}
                              </span>
                            )}
                          </div>
                        </NavLink>
                      );
                    })}
                  </div>
                ))}
            </section>

            <section className="axu-panel profile-fold" data-open={followingOpen}>
              <FoldHead
                title="Following"
                open={followingOpen}
                onToggle={() => setFollowingOpen((v) => !v)}
              />
              {followingOpen &&
                (follows.length === 0 ? (
                  <p className="small muted profile-empty">No tracks followed yet.</p>
                ) : (
                  <div className="follow-list">
                    {follows.map((f) => (
                      <div className="follow-row" key={f.trackId}>
                        <NavLink to={`/tracks/${f.slug}`} className="follow-who">
                          <b>{f.name}</b>
                          <span className="small muted">
                            {[f.city, f.region].filter(Boolean).join(', ') || '—'}
                          </span>
                        </NavLink>
                        {/* Dropping a follow leaves the row in place, its control
                            now reading Follow, so a mis-click is one click to
                            undo; the row is gone the next time the page is
                            loaded, since the list is re-read from the server. */}
                        <FollowButton trackId={f.trackId} name={f.name} following compact />
                      </div>
                    ))}
                  </div>
                ))}
            </section>

            <section className="axu-panel profile-danger">
              <div className="profile-danger-copy">
                <h3>Danger Zone</h3>
                <p className="small muted">
                  Closing the account removes your name, email, follows and pass. Receipts and scan
                  history stay with the operator reports, and the email can be used to register again.
                </p>
              </div>
              <button
                className="ghost small danger"
                onClick={() => {
                  setDeletePassword('');
                  setDeleteErr(null);
                  setConfirmDelete(true);
                }}
              >
                Delete account
              </button>
            </section>
          </div>
        </div>
      </div>

      {/* The two forms, each opened by its own control: the rail's edit square
          for the details, the rail's quiet button for the password. One at a
          time: `openSheet` holds which. */}
      {openSheet === 'details' && (
        <ProfileSheet id="profile-details" title="Details" onClose={() => setOpenSheet(null)}>
          {/* The photo saves on its own, outside the name/location draft. */}
          <AvatarPicker />
          <div className="grid">
            <div>
              <label htmlFor="profile-name">Name</label>
              <input
                id="profile-name"
                value={name}
                onChange={(e) => setName(cleanNameDraft(e.target.value, 80))}
                onBlur={() => setTouched((t) => ({ ...t, name: true }))}
                aria-invalid={touched.name && nameErr ? true : undefined}
                aria-describedby={touched.name && nameErr ? 'profile-name-error' : undefined}
              />
              {touched.name && nameErr && (
                <div className="profile-field-error" id="profile-name-error" role="alert">
                  {nameErr}
                </div>
              )}
            </div>
            <div>
              <label htmlFor="profile-location">Location</label>
              <input
                id="profile-location"
                value={location}
                onChange={(e) => setLocation(cleanLine(e.target.value, 80))}
                onBlur={() => setTouched((t) => ({ ...t, location: true }))}
                placeholder="Where you ride from"
                aria-invalid={touched.location && locationErr ? true : undefined}
                aria-describedby={touched.location && locationErr ? 'profile-location-error' : undefined}
              />
              {touched.location && locationErr && (
                <div className="profile-field-error" id="profile-location-error" role="alert">
                  {locationErr}
                </div>
              )}
            </div>
          </div>
          <div className="sheet-actions">
            <button className="ghost small" onClick={() => setOpenSheet(null)}>
              Close
            </button>
            <button className="primary small" onClick={save} disabled={!canSave}>
              {saving ? 'Saving…' : 'Save profile'}
            </button>
          </div>
        </ProfileSheet>
      )}

      {openSheet === 'password' && (
        <ProfileSheet
          id="profile-reset-password"
          title="Reset password"
          onClose={() => setOpenSheet(null)}
        >
          <div className="grid">
            <div>
              <label htmlFor="profile-current-password">Current password</label>
              <PasswordField
                id="profile-current-password"
                value={currentPwd}
                onChange={(e) => setCurrentPwd(e.target.value)}
                autoComplete="current-password"
              />
            </div>
            <div>
              <label htmlFor="profile-new-password">New password</label>
              <PasswordField
                id="profile-new-password"
                value={newPwd}
                onChange={(e) => setNewPwd(e.target.value)}
                onBlur={() => setPwdTouched((t) => ({ ...t, next: true }))}
                autoComplete="new-password"
                ariaInvalid={pwdTouched.next && !!newPwdErr}
                ariaDescribedBy={
                  pwdTouched.next && newPwdErr ? 'profile-new-password-error' : undefined
                }
              />
              {pwdTouched.next && newPwdErr && (
                <div className="profile-field-error" id="profile-new-password-error" role="alert">
                  {newPwdErr}
                </div>
              )}
            </div>
            <div>
              <label htmlFor="profile-confirm-password">Confirm new password</label>
              <PasswordField
                id="profile-confirm-password"
                value={confirmPwd}
                onChange={(e) => setConfirmPwd(e.target.value)}
                onBlur={() => setPwdTouched((t) => ({ ...t, confirm: true }))}
                autoComplete="new-password"
                ariaInvalid={pwdTouched.confirm && !!confirmErr}
                ariaDescribedBy={
                  pwdTouched.confirm && confirmErr ? 'profile-confirm-password-error' : undefined
                }
              />
              {pwdTouched.confirm && confirmErr && (
                <div className="profile-field-error" id="profile-confirm-password-error" role="alert">
                  {confirmErr}
                </div>
              )}
            </div>
          </div>
          <div className="sheet-actions">
            <button className="ghost small" onClick={() => setOpenSheet(null)}>
              Close
            </button>
            <button className="primary small" onClick={resetPassword} disabled={!canReset}>
              {pwdSaving ? 'Updating…' : 'Update password'}
            </button>
          </div>
          {/* The server's own answer — a wrong current password lands here. */}
          {pwdErr && (
            <div className="profile-field-error" role="alert">
              {pwdErr}
            </div>
          )}
        </ProfileSheet>
      )}

      {confirmCancel && pass && (
        <ConfirmSheet
          id="cancel-pass"
          title={`Cancel ${pass.tier.name}?`}
          copy={`The pass ends today and the account returns to the free pass. The ${pass.daysUntilExpiry} day${pass.daysUntilExpiry === 1 ? '' : 's'} left on it are forfeited. Ride history and receipts stay.`}
          confirmLabel={cancelling ? 'Cancelling…' : 'Cancel pass'}
          cancelLabel="Keep pass"
          onConfirm={cancelPass}
          onCancel={() => setConfirmCancel(false)}
        />
      )}

      {confirmDelete && (
        <ConfirmSheet
          id="delete-account"
          title="Delete your account?"
          copy="This closes the account. Your details and follows are removed, the pass is cancelled, and the email is freed for a new account."
          confirmLabel={deleting ? 'Deleting…' : 'Delete account'}
          cancelLabel="Keep account"
          confirmDisabled={deleting || !deletePassword}
          onConfirm={deleteAccount}
          onCancel={() => setConfirmDelete(false)}
        >
          <div>
            <label htmlFor="delete-account-password">Password</label>
            <PasswordField
              id="delete-account-password"
              value={deletePassword}
              onChange={(e) => setDeletePassword(e.target.value)}
              placeholder="Confirm your password"
              autoComplete="current-password"
            />
          </div>
          {deleteErr && <Banner tone="bad" close>{deleteErr}</Banner>}
        </ConfirmSheet>
      )}
    </div>
  );
}

/* The site cursor's two layers — see components/CanvasCursor.tsx for the drawing.
 *
 * It lives in its own partial rather than the foot of global.scss because it is
 * one component's own chrome: it is imported by the component that owns both
 * nodes, so the styles and the code that drives them travel together. */

/* The pointer keeps its native arrow; these two layers ride under it. The canvas
   is the drawn part (a 6px accent square and its tail); the square below it is
   the state read: it desaturates whatever it is over and presses hollow. Both
   are paint only, so neither takes a click, and both sit above everything —
   sheets and toasts included — exactly as the reference has it. */
.canvas-cursor {
  position: fixed;
  inset: 0;
  /* The backing store is the viewport times the device pixel ratio, and a
     replaced element with `width: auto` keeps its *intrinsic* size — so without
     this the canvas would lay out at dpr times the viewport and everything
     painted would sit dpr times too far from the top-left corner. */
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 2147483600;
}

.canvas-cursor-hover {
  position: fixed;
  top: 0;
  left: 0;
  width: 2rem;
  height: 2rem;
  box-sizing: border-box;
  transform-origin: center;
  pointer-events: none;
  z-index: 2147483601;
  opacity: 0;
  will-change: transform, opacity;
  /* A flat grey under `saturation` drops the colour out of what it covers. */
  background: #8a8a8a;
  mix-blend-mode: saturation;
  border: 1.25px solid transparent;
  transition: background-color 120ms ease, border-color 120ms ease;
}

/* The press: the fill goes, the hairline takes a shade of the accent, and the
   square is smaller than its hover size as it snaps in. */
.canvas-cursor-hover.pressed {
  background-color: transparent;
  mix-blend-mode: normal;
  border-color: var(--cursor-ink-soft, var(--accent));
}

/* Global sheet — the app's base layer.

   Tokens, element resets, the utility classes and the shared chrome (pills,
   sheets, banners, tables, the map's Leaflet skin) live here. Everything that
   belongs to one component now sits beside it — src/components/<Name>/<Name>.scss
   and src/pages/<role>/<Name>/<Name>.scss, imported from that component's own
   .tsx. This sheet loads first (see main.tsx), so a component sheet wins a
   specificity tie against a base rule. */

:root {
  --bg: #0d0f12;
  --bg-2: #14171c;
  --bg-3: #1b1f26;
  --line: #262b34;
  --text: #e8eaed;
  --muted: #8b93a1;
  /* Accent: orange (the chosen preset). `--accent-rgb` is the same colour as
     an r,g,b triple so soft tints (borders, glows) follow it. */
  --accent: #ff8a3f;
  --accent-rgb: 255, 138, 63;
  --accent-2: #3fd0ff;
  /* Event kinds, as r,g,b triples so a chip's fill and its bar tint from the
     same hue. The owner's calendar is the only surface that colours a date, and
     it colours it by kind — practice neutral, race red, clinic blue, ride day
     amber. Nothing here is the accent: a kind must not read as "selected". */
  --evk-practice: 156, 164, 178;
  --evk-race: 255, 107, 94;
  --evk-clinic: 96, 168, 255;
  --evk-ride_day: 240, 178, 74;
  --evk-other: 186, 143, 255;
  /* The 'ice' colourway: a fixed, neutral grey pair for the small status chrome
     (status pills, the day tag, the pill toggle) that must NOT follow the
     temporary accent switcher. */
  --ice: #e8eaed;
  --ice-rgb: 232, 234, 237;
  /* The hairline outline on a map dot, and on the legend's swatches. The dot
     fills are the accent pair at 85% opacity (RiderTrackMap), so this is the
     accent's own rim, a shade back from the fill. */
  --pin-edge: rgba(var(--accent-rgb), 0.5);
  /* The ink that sits on an ice fill. The ice pair inverts with the theme (a
     near-white chip on the dark ground, a near-black chip on the light one), so
     its label has to flip with it. */
  --on-ice: #10130a;
  /* The pill toggle's own material: a sunken dark track with a raised, mid-grey
     thumb carrying the pressed option. It is its own pair rather than `--ice`,
     which stays the status chips' near-white; a pressed option here is a grey
     lift off the track, not a light chip on it. The thumb's shadow is a token
     too, because the light theme needs a soft one under a white thumb where the
     dark one needs it under a grey one. */
  --pill-line: #353c46;
  --pill-thumb: #4b515a;
  --pill-thumb-ink: #ffffff;
  --pill-thumb-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
  --ok: #4ade80;
  --warn: #fbbf24;
  --bad: #f87171;
  /* The spent mark: a day meter at zero, whose ticket is a step off the hairline
     (`--line`) but still short of `--muted` — read as used, not as a hairline. */
  --dim: #4f5764;
  /* The day-meter ticket's own ink, a touch lighter than `--muted` / `--dim` so
     the outline mark stays quiet next to the count. Its own tokens because the
     mark, not the body copy, is what the user asked to lighten. */
  --ticket: #9da5b2;
  --ticket-spent: #656e7c;
  --radius: 4px;
  --radius-lg: 6px;
  /* Floating layers only — the sheet, a toast. */
  --shadow: 0 18px 44px rgba(0, 0, 0, 0.55);
  /* The pricing row's own lift: the raised plan card stands off the page, and
     its CTA stands off the card. Separate from `--shadow` (which belongs to
     layers that float over the page) so the light theme can go soft. */
  --shadow-card: 0 26px 60px rgba(0, 0, 0, 0.5);
  --shadow-cta: 0 6px 16px rgba(0, 0, 0, 0.35);
  /* The level plan card's surface on the pricing row: a shade under the raised
     card's `--bg-2`, so the plan you buy is the one that stands forward. Its
     own token because "recessed" reads lighter in the dark theme and darker in
     the light one — the surfaces cannot share a value. */
  --tier-level-bg: #101318;
  /* Translucent chrome that sits over the page or over a photograph: the app
     header, the map attribution, the gallery lightbox arrows. */
  --scrim: rgba(13, 15, 18, 0.92);
  --scrim-soft: rgba(13, 15, 18, 0.8);
  /* The scrolled app header's own chrome: the surface at half opacity, so the
     page reads through the blur instead of being blanked out. */
  --scrim-half: rgba(13, 15, 18, 0.5);
  /* ...and the same chrome, plus the hairline under it, while the header rides
     over a photograph (the landing hero) — dark in *both* themes, because the
     ink has to answer the picture rather than the palette. See `.app-header`. */
  --scrim-photo: rgba(13, 15, 18, 0.5);
  --scrim-photo-line: rgba(242, 244, 246, 0.16);
  /* The header's own ink. Both resolve against the element's --text / --muted,
     so the light theme follows along; `.app-header.over-photo` overrides them
     to the light pair for the hero. */
  --header-ink: var(--text);
  --header-ink-muted: var(--muted);
  /* The header's controls draw their own hairline from this — it follows the
     ink above, so the header's quiet action (Sign in) keeps its edge over the
     landing hero's photograph. See `.header-signin`. */
  --header-line: var(--line);
  /* Barely-there row hover tints. A white tint only reads on a dark surface,
     so it flips to a black tint in the light theme. */
  --tint: rgba(255, 255, 255, 0.02);
  --tint-strong: rgba(255, 255, 255, 0.05);
  /* A success toast's bubble: a subtle bluish grey, not the green tint the
     inline banner carries. Over the map the green fill read as a badge; the
     words already say "approved", so the material stays quiet and the ink
     (`.ok`) keeps the green. */
  --ok-bubble-bg: #1a212b;
  --ok-bubble-line: #39434f;
  /* A tone toast reads through the map: the banner's tint is translucent, so
     the floating warn / bad notices composite their tint over the card
     material and stay opaque. Pre-mixed against --bg-2 (#14171c). */
  --warn-bubble-bg: #26241c;
  --warn-bubble-line: rgba(251, 191, 36, 0.5);
  --bad-bubble-bg: #261e23;
  --bad-bubble-line: rgba(248, 113, 113, 0.5);
  /* OpenStreetMap ships light raster tiles. The dark theme inverts the tile
     pane (CARTO's keyless dark basemap needs an API key); the light theme
     takes the tiles as they come. Applied to .leaflet-tile-pane only, so
     markers and popups are untouched either way. */
  --map-tile-filter: invert(1) hue-rotate(180deg) brightness(0.93) contrast(0.9) saturate(0.75);
}

/* Light theme — the same token contract, inverted surfaces. Set on <html> by
   ThemeToggle (and by the pre-paint script in index.html, so a stored choice
   never flashes the dark palette first). Nothing else in the app knows about
   it: every surface reads these tokens. */
:root[data-theme='light'] {
  --bg: #f5f6f8;
  --bg-2: #ffffff;
  --bg-3: #eceef2;
  --line: #d7dbe2;
  --text: #14171c;
  --muted: #5c6472;
  /* Accent stays the chosen orange; only the soft-tint triple is unchanged
     because it is the same colour either way. */
  --evk-practice: 92, 100, 114;
  --evk-race: 198, 56, 48;
  --evk-clinic: 36, 96, 224;
  --evk-ride_day: 168, 106, 8;
  --evk-other: 122, 56, 232;
  --ice: #2b3038;
  --ice-rgb: 43, 48, 56;
  --on-ice: #f5f6f8;
  /* The pill toggle inverts with the theme: a light track with a white thumb
     and dark ink, the same "raised" read the dark ground gets from a grey one. */
  --pill-line: #cbd2db;
  --pill-thumb: #ffffff;
  --pill-thumb-ink: #14171c;
  --pill-thumb-shadow: 0 1px 2px rgba(23, 26, 31, 0.14);
  --ok: #15803d;
  --warn: #b45309;
  --bad: #b91c1c;
  --dim: #98a1ae;
  --ticket: #727a87;
  --ticket-spent: #a9b1bd;
  --accent-2: #0b7fa8;
  --shadow: 0 18px 44px rgba(23, 26, 31, 0.18);
  --shadow-card: 0 24px 56px rgba(23, 26, 31, 0.16);
  --shadow-cta: 0 6px 16px rgba(23, 26, 31, 0.18);
  --tier-level-bg: #eceef2;
  --scrim: rgba(255, 255, 255, 0.88);
  --scrim-soft: rgba(255, 255, 255, 0.82);
  --scrim-half: rgba(255, 255, 255, 0.5);
  --tint: rgba(20, 23, 28, 0.03);
  --tint-strong: rgba(20, 23, 28, 0.06);
  /* The success toast's bubble on the light surface: the same bluish grey a
     step under the card, with a hairline that carries the cast. */
  --ok-bubble-bg: #eef1f5;
  --ok-bubble-line: #ccd4de;
  /* Same opaqueness on the light surface: the tint composited over #ffffff. */
  --warn-bubble-bg: #fffaed;
  --warn-bubble-line: rgba(251, 191, 36, 0.7);
  --bad-bubble-bg: #fef4f4;
  --bad-bubble-line: rgba(248, 113, 113, 0.7);
  --map-tile-filter: none;
}

* { box-sizing: border-box; }

/* The landing hero bleeds to 100vw, which includes the classic scrollbar's
   width; clip the overflow instead of letting it open a horizontal scroll. */
html { overflow-x: clip; }

html, body, #root { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }

a.inline { text-decoration: underline; text-underline-offset: 2px; }

h1 { font-size: 26px; margin: 0 0 4px; letter-spacing: -0.02em; }

h2 { font-size: 16px; margin: 0 0 10px; font-weight: 600; }

h3 { font-size: 12px; margin: 0 0 8px; font-weight: 600; color: var(--muted); }

button, input, select, textarea { font: inherit; touch-action: manipulation; }

button {
  background: var(--bg-3);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 8px 14px;
  cursor: pointer;
  transition: opacity 0.12s ease, border-color 0.12s ease;
}

button:hover:not(:disabled) { opacity: 0.8; }

button:disabled { opacity: 0.4; cursor: not-allowed; }

button.primary { background: var(--accent); color: #10130a; border-color: var(--accent); font-weight: 600; }

button.ghost { background: transparent; }

button.danger { color: var(--bad); }

input, select, textarea {
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--text);
  padding: 8px 10px;
  width: 100%;
}

input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent-2); }

/* Chrome's autofill (the suggestion list under the rider-search keys, above all)
   repaints the field it populated with its own palette — pale blue on the light
   theme, a flat tint on the dark one — for as long as the value counts as
   autofilled, and it blacks out the text on a dark surface. Keep the app's own
   field: an inset shadow of --bg-2 covers the fill colour, the text-fill colour
   keeps the ink readable. (No background transition here: the inset does the
   covering, and a long transition would freeze the palette on a theme switch.) */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active,
select:-webkit-autofill,
textarea:-webkit-autofill {
  -webkit-text-fill-color: var(--text);
  -webkit-box-shadow: 0 0 0 1000px var(--bg-2) inset;
  box-shadow: 0 0 0 1000px var(--bg-2) inset;
  caret-color: var(--text);
}

label { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; }

.card {
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 16px;
}

.grid { display: grid; gap: 16px; }

.cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }

.cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }

.cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }

@media (max-width: 860px) {
  .cols-2, .cols-3, .cols-4 { grid-template-columns: 1fr; }
}

.row { display: flex; gap: 10px; align-items: center; }

.row.wrap { flex-wrap: wrap; }

.spread { justify-content: space-between; }

.muted { color: var(--muted); }

.small { font-size: 12px; }

.tiny { font-size: 11px; }

/* A rule hint with a leading check slot (the fallback auth form's password
   rule): the tick fades in once the field qualifies while its width is
   reserved either way, so the words never shift. */
.hint-check-row {
  display: flex;
  align-items: center;
  gap: 5px;
}

.hint-check {
  flex: none;
  display: inline-flex;
  width: 12px;
  height: 12px;
  color: var(--ok);
  opacity: 0;
  transform: scale(0.7);
  transition: opacity 120ms ease, transform 120ms ease;
}

.hint-check[data-met] {
  opacity: 1;
  transform: none;
}

.hint-check svg {
  width: 100%;
  height: 100%;
}

.mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }

.ok { color: var(--ok); }

.bad { color: var(--bad); }

.warn { color: var(--warn); }

.right { text-align: right; }

/* The rhythm runs between the blocks that are *in* the page. A fixed overlay
   (the toast, a sheet, the lightbox) sits outside the flow: it takes no
   rhythm of its own, and the block after it must not read it as a predecessor
   — otherwise the stack's first real block opens a gap at the top of the page
   while the overlay is on screen. */
.stack > :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) + :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) { margin-top: 10px; }

/* Inside a card the rhythm stays tight: 10px between top-level sections,
   12px between the blocks that make one up. */
.card.stack > :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) + :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) { margin-top: 12px; }

table { width: 100%; border-collapse: collapse; font-size: 13px; }

/* Wide tables scroll inside their card instead of dragging the page sideways. */
.table-scroll { overflow-x: auto; }

/* A table's name belongs outside the table: top-left, above the card, with a
   small gap rather than the card's own padding. */
.table-block { display: flex; flex-direction: column; gap: 8px; }

.table-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }

.table-head h3 { margin: 0; }

/* The tab toggle rides in a heading row here, where the pill's own top margin
   would push it off the heading's baseline. */
.table-head .pill-toggle { margin-top: 0; }

th { text-align: left; color: var(--muted); font-weight: 500; font-size: 11px; letter-spacing: 0.05em; padding: 8px 10px; border-bottom: 1px solid var(--line); }

/* Sortable header: the button inherits the header's own type, so the cell only
   gains a hit target and a drawn indicator. */
.sort-btn {
  background: none;
  border: 0;
  padding: 0;
  margin: 0;
  font: inherit;
  letter-spacing: inherit;
  text-transform: inherit;
  color: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.sort-btn:hover { color: var(--text); }

.sort-btn svg { opacity: 0.4; flex: 0 0 auto; }

th[aria-sort='ascending'] .sort-btn,
th[aria-sort='descending'] .sort-btn { color: var(--text); }

th[aria-sort='ascending'] .sort-btn svg,
th[aria-sort='descending'] .sort-btn svg { opacity: 1; color: var(--accent); }

.right .sort-btn { flex-direction: row-reverse; }

td { padding: 9px 10px; border-bottom: 1px solid var(--line); }

tbody tr:hover { background: var(--tint); }

.pill {
  display: inline-block;
  font-size: 11px;
  padding: 2px 7px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  color: var(--muted);
}

.pill.ok { color: var(--ok); border-color: rgba(74, 222, 128, 0.4); }

.pill.bad { color: var(--bad); border-color: rgba(248, 113, 113, 0.4); }

.pill.warn { color: var(--warn); border-color: rgba(251, 191, 36, 0.4); }

/* Live venue status. Only Open reads as rideable; a hold or a closed gate greys
   out rather than shouting, because it is the weather talking, not the venue. */
.status-pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  white-space: nowrap;
}

/* Open reads the fixed ice colourway, not the accent: the switcher must not
   repaint the live-status chrome. */
.status-pill.status-open { color: var(--ice); border-color: rgba(var(--ice-rgb), 0.45); }

/* `status-hold` is the class TRACK_STATUS_CLASS actually emits for a weather
   hold; the older `status-weather_hold` spelling is kept for the map popups. */
.status-pill.status-hold,
.status-pill.status-weather_hold { color: var(--warn); border-color: rgba(251, 191, 36, 0.45); }

.status-pill.status-closed { color: var(--muted); }

.status-cell { white-space: nowrap; }

.status-cell .status-line {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--muted);
  white-space: normal;
}

.map-popup b.status-open { color: var(--accent); }

.map-popup b.status-weather_hold { color: var(--warn); }

/* A floating notice: the same banner carried in the bottom-right toast layer,
   on card material — a tone tint is translucent, and the map would read
   through it. Sits above Leaflet's panes and controls, under the sheet. */
.toast {
  position: fixed;
  right: 18px;
  bottom: 18px;
  /* The stack rhythm already skips a fixed overlay; kept as a guard so the
   toast can never be nudged off the viewport edge. */
  margin: 0;
  z-index: 1100;
  width: min(360px, calc(100vw - 36px));
  animation: toast-in 0.18s ease-out;
}

.toast > .banner { background-color: var(--bg-2); box-shadow: var(--shadow); }

/* A success toast takes the bluish-grey bubble rather than the banner's green
   one: it floats over the map, where a green fill reads as a badge, and the
   sentence already carries the approval. Only the material moves — the green
   ink comes from the `ok` utility class and stays. */
.toast > .banner.ok,
.toast-stack .banner.ok {
  background-color: var(--ok-bubble-bg);
  border-color: var(--ok-bubble-line);
}

/* Same treatment for the tone notices: the warn / bad tints are translucent,
   so over the map the free-pass and lapsed-pass notices read through. The
   floating copy takes a pre-mixed solid bubble instead; the ink is unchanged. */
.toast > .banner.warn,
.toast-stack .banner.warn {
  background-color: var(--warn-bubble-bg);
  border-color: var(--warn-bubble-line);
}

.toast > .banner.bad,
.toast-stack .banner.bad {
  background-color: var(--bad-bubble-bg);
  border-color: var(--bad-bubble-line);
}

/* The exit: the entrance backwards, so a notice that clears itself (or is
   closed) fades down and away instead of blinking out of the corner. The row is
   only cut from the stack once this has run (`EXIT_MS` in ToastStack/Banner). */
.toast.leaving,
.toast-item.leaving { animation: toast-out 0.18s ease-in forwards; }

.toast.leaving { pointer-events: none; }

@keyframes toast-out {
  to { opacity: 0; transform: translateY(6px); }
}

@media (prefers-reduced-motion: reduce) {
  .toast,
  .toast-item { animation: none; }
}

@media (prefers-reduced-motion: reduce) {
  .toast.leaving,
  .toast-item.leaving { animation: none; opacity: 0; }
}

/* The network page is a canvas, not a column: the map owns the viewport and the
   two surfaces that read it float over its edges — the rail of partner venues on
   the left, the picked venue's inspector on the right. Nothing stacks and
   nothing swaps, so inspecting a venue never costs the reader the list they were
   reading it in. Three tokens size the whole arrangement: the two float widths
   and the gap they keep from the canvas' edges. */
.pass-page.stack > :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) + :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) { margin-top: 32px; }

/* The page root owns the viewport: everything the header leaves is the canvas'
   to fill, nav edge to nav edge, however short the rail runs. `--page-h` is
   that one measurement, declared here and read by the map below it.
   The shell comes off entirely on this route: main's gutters and its 1550px
   reading measure exist to hold a column of text off the screen edges, and a
   map is not one — it runs the full width of the window. Both live in an inline
   style on <main> in Layout.tsx, so !important is the only thing a stylesheet
   can out-rank them with. */
main:has(> .stack.pass-page) { padding: 0 !important; max-width: none !important; }

/* The compact profile at the foot of the rail: the picked track's name, the
   follow control, and whether it is open today. Three lines, one card — the
   venue at a glance without opening the full panel. */
.profile-mini {
  display: grid;
  gap: 9px;
  padding: 12px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
}

.profile-mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.profile-mini-name {
  font-size: 15px;
  font-weight: 700;
  min-width: 0;
}

.profile-mini-hours {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
}

.profile-mini-hours b { font-weight: 600; }

/* Perk sheet — how to redeem one offer. */
.sheet-backdrop {
  position: fixed;
  inset: 0;
  /* The stack rhythm already skips a fixed overlay; kept as a guard so the
     backdrop always spans the viewport. */
  margin: 0;
  /* Above Leaflet: its panes (.leaflet-pane 400, controls 1000) are positioned
     with a z-index but the map pane is not a stacking context, so they compete
     here at the root — a sheet at 60 got painted under the tiles. */
  z-index: 1200;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(6, 8, 11, 0.66);
}

.sheet {
  width: min(420px, 100%);
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  padding: 18px;
  background: var(--bg-2);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
}

.sheet:focus { outline: none; }

.sheet-title { font-size: 17px; margin: 0 0 8px; letter-spacing: -0.01em; }

.sheet-copy { margin: 0 0 14px; font-size: 13px; color: var(--muted); }

.sheet-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 18px; }

/* Labelled facts — the pass's own fields, one per line. */
.fact-list { margin: 0; display: grid; }

.fact-list > div {
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr);
  gap: 14px;
  padding: 7px 0;
  align-items: baseline;
}

.fact-list > div + div { border-top: 1px solid var(--line); }

.fact-list dt { font-size: 12px; color: var(--muted); }

.fact-list dd { margin: 0; font-size: 13px; }

/* Inline figure line — counts that used to be a row of stat cards. */
.figures { display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px 0; }

.figures > div { display: flex; align-items: baseline; gap: 8px; padding: 0 24px 0 0; }

.figures > div + div { border-left: 1px solid var(--line); padding-left: 24px; }

.figures .fig-value { font-size: 20px; font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }

.figures .fig-label { font-size: 12px; color: var(--muted); }

/* The operator's message to riders: a standing note, marked by the accent rule
   on its left so it reads as the venue speaking rather than as more copy. One
   block, two homes — the network page's inspector and the venue profile. */
.operator-message {
  display: grid;
  gap: 3px;
  padding: 8px 0 8px 10px;
  border-left: 2px solid var(--accent);
}

.operator-message span {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.operator-message p { margin: 0; white-space: pre-line; }

.track-links-btn {
  display: inline-flex;
  align-items: center;
  padding: 7px 12px;
  font-size: 12px;
  background: transparent;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  transition: border-color 0.12s ease;
}

.track-links-btn:hover { border-color: var(--muted); }

.track-links-btn.track-links-icon {
  width: 31px;
  height: 31px;
  padding: 0;
  justify-content: center;
  color: var(--muted);
}

.track-links-btn.track-links-icon svg { width: 16px; height: 16px; display: block; }

.track-links-btn.track-links-icon:hover { border-color: var(--muted); color: var(--ink); }

/* ---- Leaflet, dark theme -------------------------------------------------
   OpenStreetMap raster tiles are light. CARTO's keyless dark basemap now
   requires an API key, so invert the OSM tile pane instead: the filter is
   applied to .leaflet-tile-pane only, so markers and popups are untouched. */
/* Leaflet's own `.leaflet-container` sets `background: #ddd` at the same
   specificity, and its stylesheet loads with the lazy map chunk — i.e. AFTER
   this one — so it wins and paints a light-grey flash until tiles arrive.
   Match it with a two-class selector to keep the container dark from frame one. */
.map-dark,
.map-dark.leaflet-container { background: var(--bg); }

.map-dark .leaflet-tile-pane {
  filter: var(--map-tile-filter);
}

/* The zoom bar is the map's only control: a two-button stack. Leaflet's own
   sheet loads after this one and paints every state light — #fff at rest,
   #f4f4f4 on hover/focus, and a grey #f4f4f4/#bbb pair once a button is
   disabled (zoom-out at the country floor) — so each state is spelled out here.
   The bar's own 2px black border and 2px corner radii come from Leaflet's
   `.leaflet-touch` variants; `.leaflet-control` on the bar (the class set
   Leaflet gives the zoom control) lifts these rules past them, which otherwise
   tie on specificity and win by load order. */
.map-dark .leaflet-bar.leaflet-control {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
}

/* Rest and the pressed/keyboard states all sit on the same themed fill; only
   hover lifts. */
.map-dark .leaflet-bar a,
.map-dark .leaflet-bar a:active,
.map-dark .leaflet-bar a:focus {
  background: var(--bg-3);
  color: var(--text);
  border-bottom-color: var(--line);
  outline: none;
}

.map-dark .leaflet-bar a:hover { background: var(--bg-2); color: var(--accent); }

.map-dark .leaflet-bar a:focus-visible {
  outline: 2px solid var(--accent-2);
  outline-offset: -2px;
}

/* A button at its limit keeps the themed fill and steps back with the app's own
   disabled opacity, rather than reverting to Leaflet's light-grey pair. */
.map-dark .leaflet-bar a.leaflet-disabled,
.map-dark .leaflet-bar a.leaflet-disabled:hover,
.map-dark .leaflet-bar a.leaflet-disabled:focus,
.map-dark .leaflet-bar a.leaflet-disabled:active {
  background: var(--bg-3);
  color: var(--text);
  opacity: 0.4;
  cursor: default;
}

/* Leaflet's own rule is `.leaflet-container .leaflet-control-attribution` (two
   classes, shipped later in the bundle), so this needs three to win — without it
   the attribution reads as a white box on the dark map. */
.map-dark.leaflet-container .leaflet-control-attribution {
  background: var(--scrim-soft);
  color: var(--muted);
}

.map-dark .leaflet-control-attribution a { color: var(--muted); text-decoration: underline; }

.map-dark .leaflet-popup-content-wrapper,
.map-dark .leaflet-popup-tip {
  background: var(--bg-2);
  color: var(--text);
  border: 1px solid var(--line);
  box-shadow: none;
}

.map-dark .leaflet-popup-content { margin: 10px 12px; line-height: 1.4; }

.map-dark a.leaflet-popup-close-button { color: var(--muted); }

/* The venue's name on hover, drawn on the app's own card material so it reads as
   chrome over the dark tiles rather than a second map label. Leaflet's own
   tooltip is a white bubble with an arrow; both are overridden — no arrow. */
.map-dark .leaflet-tooltip.map-tip {
  padding: 3px 8px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: var(--bg-2);
  color: var(--text);
  font: 500 11px/1.3 system-ui, sans-serif;
  letter-spacing: -0.01em;
  white-space: nowrap;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
}

.map-dark .leaflet-tooltip.map-tip::before { display: none; }

.pill-toggle {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-top: 18px;
  padding: 3px;
  background: var(--bg);
  border: 1px solid var(--pill-line);
  border-radius: 999px;
}

.pill-toggle button {
  background: transparent;
  border: 0;
  border-radius: 999px;
  padding: 6px 15px;
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.2;
  color: var(--muted);
}

/* Hover feedback belongs on the option you can still pick: the selected pill
   keeps its white label on the grey thumb, so the two never collide. */
.pill-toggle button:hover:not(:disabled) { opacity: 1; }

.pill-toggle button:hover:not(:disabled):not([aria-pressed='true']) { color: var(--text); }

/* The pressed pill is a raised thumb off the track, not a light chip on it — a
   mid-grey fill carrying a bold white label. It reads its own `--pill-*` pair
   (frozen against the accent switcher, like the status chips) so the option
   under the pointer never looks like the accent was applied to it. */
.pill-toggle button[aria-pressed='true'] {
  background: var(--pill-thumb);
  color: var(--pill-thumb-ink);
  font-weight: 700;
  box-shadow: var(--pill-thumb-shadow);
}

/* The saving the pressed option carries, where the pill has one to name (the
   pricing page's billing pill): the same bold ink as the label, set off by a
   gap rather than a second chip. */
.pill-toggle .pill-save {
  margin-left: 9px;
  font-weight: 700;
}

.pill-toggle button:focus-visible { outline: 2px solid var(--accent-2); outline-offset: 1px; }

/* My Pass: the All / Following filter rides in the list's heading row beside the
   sort control, so narrowing and reordering the stack read as one cluster
   instead of a control row of their own. */
.day-filter {
  padding: 2px;
}

.day-filter button {
  padding: 4px 12px;
  font-size: 11px;
}

/* The name is the internal link on the directory; the venue's own site keeps
   the external glyph beside it. */
.track-name-link { text-decoration: underline; text-underline-offset: 3px; text-decoration-color: rgba(139, 147, 161, 0.4); }

.track-name-link:hover { color: var(--text); text-decoration-color: currentColor; }

.profile-banner {
  position: relative;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-2);
  aspect-ratio: 16 / 5;
  max-height: 320px;
}

.profile-banner img { width: 100%; height: 100%; object-fit: cover; display: block; }

/* No banner on file: the venue's own ink on a quiet panel, no drawn art. */
.profile-banner-fallback {
  width: 100%;
  height: 100%;
  background:
    radial-gradient(120% 160% at 12% 0%, rgba(var(--accent-rgb), 0.08), transparent 60%),
    var(--bg-3);
}

.profile-banner.small { aspect-ratio: 16 / 6; max-height: 120px; }

@media (max-width: 860px) {
  .profile-banner { aspect-ratio: 16 / 7; }
}

/* The dated half of the profile: one row per event, the date in its own column
   so the titles line up down the list. */
.event-list { list-style: none; margin: 0; padding: 0; display: grid; }

.event-row { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 14px; padding: 12px 0; }

.event-row + .event-row { border-top: 1px solid var(--line); }

.event-date {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 6px 0;
  background: var(--bg-3);
}

.event-month { font-size: 10px; letter-spacing: 0.06em; color: var(--muted); }

.event-day { font-size: 17px; font-weight: 700; font-variant-numeric: tabular-nums; line-height: 1.1; }

.event-title-row { gap: 8px; align-items: center; }

.cal-nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  font-size: 15px;
  line-height: 1;
  color: var(--muted);
  background: none;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  cursor: pointer;
}

.cal-nav:hover:not(:disabled) { color: var(--text); border-color: var(--muted); }

.cal-nav:disabled { opacity: 0.4; cursor: default; }

.image-picker-controls { gap: 8px; }

.image-url { font-size: 12px; flex: 1; min-width: 180px; }

/* The date list reads as cards, so it keeps a readable measure instead of
   stretching to the page's full width; the month grid stays put beside it. */
.event-editor { gap: 14px; max-width: 760px; }

.event-edit-row { position: relative; display: grid; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: var(--radius); background: var(--bg-2); cursor: pointer; transition: background-color 0.12s ease; }

.event-edit-row:hover { background: var(--bg-3); }

.event-edit-row.new { background: var(--bg-3); }

.event-edit-row h4 { margin: 0; font-size: 13px; }

.event-edit-row label { display: block; }

/* The date card reads as text now — a heading row (title, kind pill) over the
   date range and note — and the card itself is the control: `event-open` is the
   button that covers it, so a click anywhere opens the sheet while the card
   keeps its own markup. */
.event-title-row { min-width: 0; }

.event-card-title { font-size: 14px; }

.event-open {
  position: absolute;
  inset: 0;
  z-index: 1;
  padding: 0;
  background: none;
  border: 0;
  border-radius: inherit;
  cursor: pointer;
}

.event-open:hover { opacity: 1; }

.event-open:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* A date the owner has taken off the page reads dimmed, so a hidden date is not
   mistaken for a live one; the row an Edit hand-off landed on carries a ring. */
.event-edit-row.is-hidden { opacity: 0.72; }

.event-edit-row.is-focused { box-shadow: 0 0 0 2px rgba(var(--accent-rgb), 0.22); }

/* The week's cards: the same measure the date list always kept, under the
   grid rather than beside it. */
.event-list-head { align-items: center; gap: 10px; }

/* The heading of the month's cards: the month, its date count beside it. */
.event-list-title { align-items: baseline; gap: 8px; }

/* A week's seven columns want the room a month grid never did, so the page
   carries a wider measure and `margin-inline: auto` centres it in the shell
   rather than leaving it pinned to the left edge. */
.cal-page { max-width: 1320px; margin-inline: auto; }

.cal-top { align-items: flex-start; }

.cal-title-spacer { flex: 1 1 auto; }

/* The owner's calendar: the month's dates on the left, the week they sit in on
   the right. The list keeps a narrow column — a card is a line of text, not a
   table — and the week takes what is left, because seven day columns need the
   room. `align-items: start` keeps the short column its own height. */
.cal-editor { display: grid; grid-template-columns: minmax(0, 340px) minmax(0, 1fr); gap: 22px; align-items: start; }

/* The cards fill their own column rather than the readable measure they carried
   when they spanned the page. */
.cal-editor .event-editor { max-width: none; }

/* One column under this width, and the week leads: on a phone the grid is the
     thing being read, with the month's dates behind it. `minmax(0, 1fr)`, never
     a bare `1fr`, so the cards' own content cannot set the column's minimum. */
@media (max-width: 980px) {
  .cal-editor { grid-template-columns: minmax(0, 1fr); }
}

@media (max-width: 980px) {
  .cal-editor .wk { order: -1; }
}

/* The date the calendar page's list is narrowed to, and the way back to the
   month: the date reads as text, with its control beside it. */
.event-filter { display: flex; align-items: center; gap: 10px; }

.event-filter-day { color: var(--text); font-variant-numeric: tabular-nums; }

/* A read row that offers a hand-off: the date and the copy keep their columns
   and the control rides the row's right edge. */
.event-row.has-action { grid-template-columns: 52px minmax(0, 1fr) auto; }

.event-actions { align-self: start; display: flex; align-items: center; gap: 6px; }

/* A card heading that carries its own control: the title sets the left edge and
   the tools push right — `margin-left: auto` keeps them there when the row wraps
   on a phone, where `space-between` alone would not. */
.section-head { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }

.section-head h3 { margin: 0; }

.loc-map { height: 100%; min-height: 260px; border: 1px solid var(--line); border-radius: var(--radius-lg); overflow: hidden; }

@media (max-width: 760px) {
  .loc-map { height: 240px; }
}

/* ---- Landing ------------------------------------------------------------
   The signed-out front door. A hero band, the live network drawn as the real
   venue photographs, the pass model, then the tier band — which reuses the
   pricing page's own card material so the two pages read as one product. */
/* This page is read top to bottom rather than scanned, so it runs on a wider
   rhythm than the app's 20px: seven bands at 20px read as one crammed column.
   Scoped to `.landing` — no other page's stack moves. Overlay exclusions match
   the base rule's, in case one is ever mounted inside this stack. */
.landing > :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) + :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) { margin-top: 60px; }

/* The wider rhythm survives the fold, just quieter: 60px of air between
     bands reads as broken on a 390px column. */
@media (max-width: 860px) {
  .landing > :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) + :not(:where(.toast, .axt-stack, .sheet-backdrop, .lightbox)) { margin-top: 44px; }
}

/* The event sheets — the calendar's Add and Edit forms. One shape for both:
   every field is a label over a filled well with its own glyph at the right
   edge, and the three the owner came for — the day, the hour, the length —
   sit in one row with the fields read back as a sentence underneath. */
.event-sheet { width: min(720px, 100%); }

.event-sheet .sheet-title { margin-bottom: 14px; }

.ev-form { display: grid; gap: 14px; }

.ev-row-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }

/* A field is a grid item, so its own minimum is what its track would size
   itself from — the input's intrinsic width, on a phone, which pushed the
   whole sheet sideways. Freed here, the wells shrink to the sheet's width. */
.ev-field { min-width: 0; }

.ev-label { font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 6px; }

.ev-well {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  padding: 0 10px;
  background: var(--bg-3);
  border: 1px solid transparent;
  border-radius: var(--radius-lg);
}

/* The well is the field's own outline, so focus lands on it. */
.ev-well:focus-within { border-color: var(--accent-2); }

/* The fields said back as a sentence, with the length they add up to at the
   other end of the same line: the one line that answers them all, and the one
   figure the sheet works out rather than asks for. */
.ev-readback { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }

.ev-note { margin: 0; font-size: 12.5px; color: var(--muted); }

.ev-note b { color: var(--text); font-weight: 500; }

.ev-span { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }

@media (max-width: 860px) {
  .ev-row-3 { grid-template-columns: 1fr; }
}

@media (max-width: 860px) {
  .event-sheet .row .primary { white-space: nowrap; }
}

/* The hours on a date card read alongside its day, a shade back from it. */
.event-card-hours { color: var(--muted); font-variant-numeric: tabular-nums; }

.community-wall-grid,
.track-reviews-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
}

.community-wall-card,
.track-review-card {
  display: grid;
  gap: 8px;
  align-content: start;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg-2);
  padding: 12px;
}

.community-wall-head,
.track-review-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.community-wall-who,
.track-review-who {
  display: grid;
  min-width: 0;
}

.community-wall-who b,
.track-review-who b { font-size: 0.9rem; }

.community-wall-who .tiny,
.track-review-who .tiny {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.community-wall-face,
.track-review-face {
  width: 28px;
  height: 28px;
  border-radius: 6px;
  object-fit: cover;
  flex: 0 0 auto;
}

/* Five stars, the filled ones the rating — read-only on a card. */
.community-stars,
.track-review-stars {
  margin-left: auto;
  flex: 0 0 auto;
  letter-spacing: 1px;
  font-size: 0.8rem;
}

.community-stars .on,
.track-review-stars .on { color: var(--accent); }

.community-stars .off,
.track-review-stars .off { color: var(--line); }

.community-wall-body,
.track-review-body {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.45;
  white-space: pre-line;
}

/* The frames under the account — thumbnails, the lightbox is the full size. */
.community-wall-shots,
.track-review-shots {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.community-wall-shot,
.track-review-shot {
  display: block;
  width: 100%;
  padding: 0;
  border: 0;
  background: none;
  border-radius: 6px;
  overflow: hidden;
  cursor: zoom-in;
}

.community-wall-shot img,
.track-review-shot img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
}

.community-wall-by {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

button.primary.small.danger {
  background: var(--bad);
  border-color: var(--bad);
  color: var(--bg);
  font-weight: 600;
}

/* A date a non-operator may read is a control, the way the owner's own card is
   — `event-open` is the button that covers it. On the venue profile the row
   keeps its hairline list shape and takes the click; on the rider's card the
   venue name sits above the cover, so the track stays one click away. */
.event-row.has-open { position: relative; cursor: pointer; transition: background-color 0.12s ease; }

.event-row.has-open:hover { background: var(--tint); }

import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5180,
    // Reachable over the tailnet via `tailscale serve` (Host = <node>.ts.net).
    // The bare tailnet IP is allowed too: MagicDNS is not configured on every
    // machine that opens the app, and the IP needs no name resolution.
    allowedHosts: ['.ts.net', 'localhost', '127.0.0.1', '100.85.63.86'],
    proxy: {
      '/api': {
        // The dev API the app talks to. Overridable so a second dev server can
        // be pointed at a throwaway API (a different port, different env) without
        // restarting the shared one — e.g. checking the presale gate against an
        // API started with LAUNCH_PRESALE_ENDS_AT set.
        target: process.env.API_PROXY_TARGET || 'http://127.0.0.1:4010',
        changeOrigin: true,
      },
    },
  },
})

{
  "name": "moto-pass",
  "version": "1.0.0",
  "private": true,
  "description": "Repo root. No dependencies: this file exists so the buildpack always has a default start command. The real server lives in server/ (see app.yaml, whose run_command is the primary).",
  "scripts": {
    "start": "node server/dist/index.js"
  }
}

// Moto Pass — Prisma schema (PostgreSQL)
// One annual pass, many partner tracks, per-track contract terms.
// NOTE: every "enum" field is a String validated in the app layer
// (see src/types/enums.ts) rather than a native PG enum, so adding a value
// never needs a migration and the API contracts stay JSON-identical.

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// ---------------------------------------------------------------------------
// Seasons
// ---------------------------------------------------------------------------

model Season {
  id        String   @id @default(uuid())
  year      Int      @unique
  startsAt  DateTime
  endsAt    DateTime
  isActive  Boolean  @default(true)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  contracts  TrackContract[]
  passes     Pass[]
  allotments Allotment[]

  @@map("seasons")
}

// ---------------------------------------------------------------------------
// Users & sessions
// ---------------------------------------------------------------------------

model User {
  id           String   @id @default(uuid())
  email        String   @unique
  name         String
  passwordHash String
  role         String   @default("RIDER")
  phone        String?
  location     String?
  avatarUrl    String?
  isActive     Boolean  @default(true)
  // Set the moment the rider spends the link mailed at sign-up. Until then the
  // account exists but cannot sign in (see auth.controller `login`), so a
  // mistyped address never becomes a usable login. Staff and seeded accounts
  // are stamped at creation — there is no inbox to prove.
  emailVerifiedAt DateTime?

  operatorTrackId String?
  operatorTrack   Track?  @relation("TrackOperators", fields: [operatorTrackId], references: [id], onDelete: SetNull)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  sessions     Session[]
  passes       Pass[]
  redemptions  Redemption[]
  perkUses     PerkRedemption[]
  follows      TrackFollow[]
  reviews      TrackReview[]
  payments     Payment[]
  allotments   Allotment[]
  auditLogs    AuditLog[]
  passwordResets PasswordReset[]
  emailVerifications EmailVerification[]

  @@index([role])
  @@map("users")
}

model Session {
  id        String   @id @default(uuid())
  userId    String
  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  tokenHash String   @unique
  userAgent String?
  ip        String?
  expiresAt DateTime
  createdAt DateTime @default(now())

  @@index([userId])
  @@map("sessions")
}

// ---------------------------------------------------------------------------
// Password resets
// ---------------------------------------------------------------------------

// One row per issued reset link. Only the SHA-256 of the token is stored, so a
// read of the table cannot mint a working link. `usedAt` retires a token the
// moment the password it set is written; `expiresAt` bounds its life either way.
model PasswordReset {
  id        String    @id @default(uuid())
  userId    String
  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  tokenHash String    @unique
  expiresAt DateTime
  usedAt    DateTime?
  createdAt DateTime  @default(now())

  @@index([userId])
  @@map("password_resets")
}

// ---------------------------------------------------------------------------
// Email verification
// ---------------------------------------------------------------------------

// One row per link mailed at sign-up, and per link re-sent afterwards. Only the
// SHA-256 of the token is stored, as the reset table does, so a read of the
// table cannot mint a working link. Issuing a new link retires the older unused
// rows; spending one stamps `User.emailVerifiedAt` and retires the lot.
model EmailVerification {
  id        String    @id @default(uuid())
  userId    String
  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  tokenHash String    @unique
  expiresAt DateTime
  usedAt    DateTime?
  createdAt DateTime  @default(now())

  @@index([userId])
  @@map("email_verifications")
}

// ---------------------------------------------------------------------------
// Pass tiers & passes
// ---------------------------------------------------------------------------

model PassTier {
  id     String  @id @default(uuid())
  slug   String  @unique
  name   String
  tagline     String?
  description String?

  priceCents          Int      @default(0)
  // The monthly alternative to `priceCents` (annual). Display only — checkout
  // always sells the annual pass; the pricing card's Annual/Monthly toggle
  // switches which figure it shows.
  monthlyPriceCents   Int?
  earlyBirdPriceCents Int?
  // The presale window: the reduced annual price applies from `earlyBirdStartsAt`
  // until `earlyBirdEndsAt`, after which the full price runs.
  earlyBirdStartsAt   DateTime?
  earlyBirdEndsAt     DateTime?
  twoYearPriceCents   Int?

  extraDaysPerTrack Int @default(0)

  stripePriceId String?
  // The free tier: the default a new account lands on. It carries no included
  // days and no member discount, so activatePass snapshots no allotments for it.
  isDefault     Boolean @default(false)
  isActive      Boolean @default(true)
  sortOrder     Int     @default(0)

  perks    Perk[]
  passes   Pass[]
  payments Payment[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@map("pass_tiers")
}

model Pass {
  id         String @id @default(uuid())
  userId     String
  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  tierId     String
  tier       PassTier @relation(fields: [tierId], references: [id])

  seasonId   String
  season     Season @relation(fields: [seasonId], references: [id])
  seasonYear Int

  status   String  @default("PENDING")

  purchasedAt DateTime  @default(now())
  activatedAt DateTime?
  expiresAt   DateTime
  cancelledAt DateTime?

  stripeCustomerId     String?
  stripeSessionId      String? @unique
  stripeSubscriptionId String?

  redemptions  Redemption[]
  allotments   Allotment[]
  payments     Payment[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId, status])
  @@map("passes")
}

// Per user / per track / per season entitlement ledger. Contract terms are
// snapshotted here at activation so a later contract edit does not silently
// rewrite a rider's remaining days.
model Allotment {
  id         String @id @default(uuid())
  userId     String
  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  trackId    String
  track      Track  @relation(fields: [trackId], references: [id], onDelete: Cascade)
  passId     String
  pass       Pass   @relation(fields: [passId], references: [id], onDelete: Cascade)
  seasonId   String
  season     Season @relation(fields: [seasonId], references: [id])
  seasonYear Int

  includedDays        Int     @default(0)
  discountDayEnabled  Boolean @default(false)
  discountDayNumber   Int     @default(3)
  discountRate        Float   @default(0.5)
  discountDaysAllowed Int     @default(1)
  extraDayPriceCents  Int     @default(0)

  freeDaysUsed     Int @default(0)
  discountDaysUsed Int @default(0)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([userId, trackId, seasonYear])
  @@index([trackId])
  @@map("allotments")
}

// ---------------------------------------------------------------------------
// Tracks & contracts
// ---------------------------------------------------------------------------

model Track {
  id          String  @id @default(uuid())
  slug        String  @unique
  name        String
  description String?
  city        String?
  region      String?
  // The venue's published street address ("2621 US-221, Union Mills, NC 28167")
  // — what the profile's Get Directions row prints and copies. Sourced from each
  // venue's own site; the owner edits it in the console. A venue with none on
  // file shows only its city and region.
  address     String?
  country     String  @default("US")
  lat         Float?
  lng         Float?
  website     String?
  instagram   String?
  facebook    String?
  youtube     String?
  tiktok      String?
  email       String?
  phone       String?
  // The venue's own profile art: a wide banner and a square logo (the avatar in
  // the profile header). `imageUrl` stays the card/panel photo and is used as
  // the banner fallback when the owner has not set one. All three are URLs —
  // either pasted by the owner or a path under /api/uploads from the console.
  bannerUrl   String?
  logoUrl     String?
  imageUrl    String?
  // The venue's type — 'MX' (the network is motocross only).
  category    String  @default("MX")
  // Live riding status for the free-tier directory: OPEN | WEATHER_HOLD | CLOSED
  // (see src/types/enums.ts TrackStatus). Operational data, not a contract term.
  status      String  @default("OPEN")
  statusNote  String?
  // The operator's own message to riders for this venue ("Gate closes at 5, no
  // riding after"). Free text, set in the console, cleared by sending ''. Read
  // in the network page's inspector; null keeps the panel's note off entirely.
  riderMessage String?
  // `hours` is the one-line summary the network rail and panel read ("Practice
  // 9am–4pm"). `hoursWeek` is the venue's whole week behind it, stored as JSON
  // (`{"mon":"Practice 9am–4pm", …}` for Mon..Sun, `Closed` on a day it does not
  // run) — what the venue profile's Hours card lays out. Null = no week on file.
  hours       String?
  hoursWeek   String?
  nextEvent   String?
  isActive    Boolean @default(true)

  operators    User[]          @relation("TrackOperators")
  contracts    TrackContract[]
  events       TrackEvent[]
  dayStatuses  TrackDayStatus[]
  stations     ScanStation[]
  redemptions  Redemption[]
  scanEvents   ScanEvent[]
  allotments   Allotment[]
  perks        Perk[]
  followers    TrackFollow[]
  photos       TrackPhoto[]
  reviews      TrackReview[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@map("tracks")
}

// One photograph of a partner venue for the profile gallery. Seeded per venue
// from `seed/trackPhotos.ts` (real photographs off each venue's own site — see
// client/public/tracks/CREDITS.md); an owner adds more, or drops one, from the
// console. `sortOrder` is the gallery order and `category` is the owner's own
// label (TRACK | FACILITY | RACE_DAY) — the public page shows the grid, the
// category only rides along into the lightbox.
model TrackPhoto {
  id        String   @id @default(uuid())
  trackId   String
  track     Track    @relation(fields: [trackId], references: [id], onDelete: Cascade)
  url       String
  caption   String?
  category  String   @default("TRACK")
  sortOrder Int      @default(0)
  createdAt DateTime @default(now())

  @@index([trackId])
  @@map("track_photos")
}

// A rider's review of a partner venue: the account they wrote of riding there,
// the stars they gave it, and the frames they attached to it. One review per
// rider per venue (the unique below) — a review is a considered account of the
// place, not a feed, so once it is written the rider edits that same review
// rather than posting another. Not the owner's gallery: the gallery is the
// venue's own art (curated, ordered, 24 max). A rider edits their own; the venue
// may pull any review from its community page.
model TrackReview {
  id        String             @id @default(uuid())
  trackId   String
  track     Track              @relation(fields: [trackId], references: [id], onDelete: Cascade)
  userId    String
  user      User               @relation(fields: [userId], references: [id], onDelete: Cascade)
  rating    Int                @default(5)
  body      String
  createdAt DateTime           @default(now())
  updatedAt DateTime           @updatedAt
  photos    TrackReviewPhoto[]

  @@unique([userId, trackId])
  @@index([trackId, createdAt])
  @@index([userId])
  @@map("track_reviews")
}

// A frame attached to a review — the photos the rider shared with their account
// of the venue. Ordered by the rider's arrangement, capped at six, and removed
// with the review. Seeded frames point at the venue's own photographs; uploaded
// ones live under /api/uploads.
model TrackReviewPhoto {
  id        String      @id @default(uuid())
  reviewId  String
  review    TrackReview @relation(fields: [reviewId], references: [id], onDelete: Cascade)
  url       String
  caption   String?
  sortOrder Int         @default(0)
  createdAt DateTime    @default(now())

  @@index([reviewId, sortOrder])
  @@map("track_review_photos")
}

// A free-tier rider following a partner track — the follows list on My Pass.
// Following is what a free account can do; riding needs a paid pass.
model TrackFollow {
  id        String   @id @default(uuid())
  userId    String
  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  trackId   String
  track     Track    @relation(fields: [trackId], references: [id], onDelete: Cascade)
  createdAt DateTime @default(now())

  @@unique([userId, trackId])
  @@index([trackId])
  @@map("track_follows")
}

// What a track runs: the dated schedule its owner keeps on the venue profile.
// Gone-off events stay in the table (isActive) so the owner can reuse them.
model TrackEvent {
  id          String    @id @default(uuid())
  trackId     String
  track       Track     @relation(fields: [trackId], references: [id], onDelete: Cascade)
  title       String
  description String?
  // 'PRACTICE' | 'RACE' | 'CLINIC' | 'RIDE_DAY' | 'OTHER' — see src/types/enums.ts.
  kind        String    @default("PRACTICE")
  startsAt    DateTime
  endsAt      DateTime?
  // The hours a date runs, as minutes past midnight on its own day (venue-local,
  // no timezone in the way). `null` on either end is an all-day date — it reads
  // in the calendar's all-day row instead of the hour grid.
  startMinutes Int?
  endMinutes   Int?
  isActive    Boolean   @default(true)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([trackId, startsAt])
  @@map("track_events")
}

// One day's gate read for a partner track: OPEN | WEATHER_HOLD | CLOSED,
// stored at noon UTC so the date round-trips exactly (the same shape as
// TrackEvent's bare days — see the owner controller's `toDate`).
//
// Scheduling, not a snapshot: when the day arrives the venue's live line
// (`Track.status`/`statusNote`) takes this value, so an operator posts
// tomorrow's caution today and the gate flips itself overnight. A day with
// no row reads the live line as-is. The note rides per day too — tomorrow's
// reason is not today's.
model TrackDayStatus {
  id      String @id @default(uuid())
  trackId String
  track   Track  @relation(fields: [trackId], references: [id], onDelete: Cascade)
  // The day this reads for, at noon UTC.
  day        DateTime
  // OPEN | WEATHER_HOLD | CLOSED — see src/types/enums.ts TrackStatus.
  status     String  @default("OPEN")
  statusNote String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([trackId, day])
  @@index([trackId, day])
  @@map("track_day_statuses")
}

model TrackContract {
  id       String @id @default(uuid())
  trackId  String
  track    Track  @relation(fields: [trackId], references: [id], onDelete: Cascade)
  seasonId String
  season   Season @relation(fields: [seasonId], references: [id], onDelete: Cascade)

  includedDays        Int     @default(2)
  discountDayEnabled  Boolean @default(true)
  discountDayNumber   Int     @default(3)
  discountRate        Float   @default(0.5)
  extraDayPriceCents  Int     @default(4500)
  discountDaysAllowed Int     @default(1)

  isActive Boolean @default(true)
  notes    String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([trackId, seasonId])
  @@map("track_contracts")
}

model ScanStation {
  id       String  @id @default(uuid())
  trackId  String
  track    Track   @relation(fields: [trackId], references: [id], onDelete: Cascade)
  name     String
  apiKey   String  @unique
  isActive Boolean @default(true)

  events      ScanEvent[]
  redemptions Redemption[]
  perkUses    PerkRedemption[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@map("scan_stations")
}

// ---------------------------------------------------------------------------
// Redemptions
// ---------------------------------------------------------------------------

model Redemption {
  id        String @id @default(uuid())
  userId    String
  user      User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  passId    String
  pass      Pass   @relation(fields: [passId], references: [id], onDelete: Cascade)
  trackId   String
  track     Track  @relation(fields: [trackId], references: [id], onDelete: Cascade)
  stationId String?
  station   ScanStation? @relation(fields: [stationId], references: [id], onDelete: SetNull)

  kind               String   @default("FREE")
  day                DateTime
  redeemedAt         DateTime @default(now())
  amountChargedCents Int      @default(0)
  operatorId         String?

  createdAt DateTime @default(now())

  // One row per rider, per track, per day, per kind.
  @@unique([userId, trackId, day, kind])
  @@index([trackId, day])
  @@map("redemptions")
}

model ScanEvent {
  id        String @id @default(uuid())
  trackId   String
  track     Track  @relation(fields: [trackId], references: [id], onDelete: Cascade)
  stationId String?
  station   ScanStation? @relation(fields: [stationId], references: [id], onDelete: SetNull)

  passId    String?
  userId    String?
  riderName String?

  result             String
  reason             String?
  reasonCode         String?
  kind               String?
  remainingFreeDays  Int?
  amountChargedCents Int @default(0)

  operatorId String?
  createdAt  DateTime @default(now())

  @@index([trackId, createdAt])
  @@map("scan_events")
}

// ---------------------------------------------------------------------------
// Perks
// ---------------------------------------------------------------------------

model Perk {
  id           String  @id @default(uuid())
  code         String  @unique
  title        String
  description  String?
  discountType String  @default("PERCENT")
  value        Float   @default(0)

  trackId String?
  track   Track?  @relation(fields: [trackId], references: [id], onDelete: SetNull)
  tierId  String?
  tier    PassTier? @relation(fields: [tierId], references: [id], onDelete: SetNull)

  validFrom DateTime?
  validTo   DateTime?
  isActive  Boolean   @default(true)
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt

  redemptions PerkRedemption[]

  @@map("perks")
}

model PerkRedemption {
  id        String @id @default(uuid())
  perkId    String
  perk      Perk   @relation(fields: [perkId], references: [id], onDelete: Cascade)
  userId    String
  user      User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  stationId String?
  station   ScanStation? @relation(fields: [stationId], references: [id], onDelete: SetNull)
  redeemedAt DateTime @default(now())

  @@index([userId])
  @@map("perk_redemptions")
}

// ---------------------------------------------------------------------------
// Payments
// ---------------------------------------------------------------------------

model Payment {
  id     String @id @default(uuid())
  userId String
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  passId String?
  pass   Pass?  @relation(fields: [passId], references: [id], onDelete: SetNull)
  tierId String?
  tier   PassTier? @relation(fields: [tierId], references: [id], onDelete: SetNull)

  amountCents Int
  currency    String @default("usd")
  status      String @default("PENDING")

  stripeSessionId       String? @unique
  stripePaymentIntentId String?
  stripeCustomerId      String?
  stripeEventId         String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status])
  @@map("payments")
}

// ---------------------------------------------------------------------------
// Audit log (meta stored as a JSON string — SQLite has no Json column type)
// ---------------------------------------------------------------------------

model AuditLog {
  id        String   @id @default(uuid())
  actorId   String?
  actor     User?    @relation(fields: [actorId], references: [id], onDelete: SetNull)
  action    String
  entity    String
  entityId  String?
  meta      String?
  createdAt DateTime @default(now())

  @@index([entity, entityId])
  @@map("audit_logs")
}

import { PassStatus, PaymentStatus, Role } from '../src/types/enums';
import { hashPassword } from '../src/utils/password';
import { activatePass } from '../src/services/pass.service';
import { prisma, seasonBounds, SEASON_YEAR, daysAhead } from './seed/helpers';
import { trackSeed } from './seed/tracks';
import { hoursWeekSeed } from './seed/hoursWeek';
import { hoursFor, trackEventSeed } from './seed/trackProfiles';
import { trackPhotoSeed } from './seed/trackPhotos';
import { trackReviewSeed } from './seed/trackReviews';
import { tierSeed, userSeed, perkSeed, followSeed } from './seed/people';
import { seedActivity } from './seed/activity';

const DEFAULT_PASSWORD = process.env.SEED_DEFAULT_PASSWORD || 'dialed123';

async function wipe() {
  // FK-safe order: children before parents.
  await prisma.auditLog.deleteMany();
  await prisma.perkRedemption.deleteMany();
  await prisma.perk.deleteMany();
  await prisma.trackFollow.deleteMany();
  await prisma.trackReviewPhoto.deleteMany();
  await prisma.trackReview.deleteMany();
  await prisma.scanEvent.deleteMany();
  await prisma.redemption.deleteMany();
  await prisma.payment.deleteMany();
  await prisma.allotment.deleteMany();
  await prisma.pass.deleteMany();
  await prisma.passTier.deleteMany();
  await prisma.scanStation.deleteMany();
  await prisma.trackContract.deleteMany();
  await prisma.trackEvent.deleteMany();
  await prisma.trackPhoto.deleteMany();
  await prisma.track.deleteMany();
  await prisma.season.deleteMany();
  await prisma.session.deleteMany();
  await prisma.user.deleteMany();
}

async function main() {
  console.log('Wiping existing data...');
  await wipe();

  // ---- Season ----
  const season = await prisma.season.create({
    data: { year: SEASON_YEAR, ...seasonBounds, isActive: true },
  });

  // ---- Tiers ----
  const tiers: Record<string, { id: string; priceCents: number; extraDaysPerTrack: number }> = {};
  for (const t of tierSeed) {
    const tier = await prisma.passTier.create({ data: t });
    tiers[t.slug] = { id: tier.id, priceCents: tier.priceCents, extraDaysPerTrack: tier.extraDaysPerTrack };
  }

  // ---- Tracks + contracts + stations ----
  const tracks: Record<string, { id: string; name: string }> = {};
  const stations: Record<string, string> = {};
  for (const t of trackSeed) {
    const { contract, ...trackData } = t;
    const track = await prisma.track.create({
      data: {
        ...trackData,
        // The venue's week, as JSON — see seed/hoursWeek.ts. A venue with no
        // week on file keeps `hoursWeek` null and its profile shows the single
        // summary line instead of a week.
        hoursWeek: hoursWeekSeed[t.slug] ? JSON.stringify(hoursWeekSeed[t.slug]) : null,
        contracts: { create: { seasonId: season.id, ...contract } },
        stations: {
          create: { name: 'Ticket Window', apiKey: `stn_${t.slug.replace(/[^a-z0-9]+/g, '_')}_ticket` },
        },
      },
      include: { stations: true },
    });
    tracks[t.slug] = { id: track.id, name: track.name };
    stations[t.slug] = track.stations[0].id;

    // The venue's gallery — the photographs its profile page opens with. An
    // owner adds or reorders from the console; these are just the starting set.
    const photos = trackPhotoSeed[t.slug] ?? [];
    for (const [i, p] of photos.entries()) {
      await prisma.trackPhoto.create({
        data: {
          trackId: track.id,
          url: `/tracks/photos/${t.slug}/${p.file}`,
          category: p.category,
          caption: p.caption ?? null,
          sortOrder: i,
        },
      });
    }
  }

  // ---- Track profile events ----
  // The dated half of a venue profile. Only the venues with a seeded schedule
  // get rows; the rest show the empty state until their owner adds one.
  // Stored at noon UTC so the day never slips across a timezone; the hours a
  // date runs are kept separately as minutes past midnight on that day, so a
  // date is timed or all-day without either reading the other's clock.
  const atNoon = (d: Date) => new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 12));
  for (const e of trackEventSeed) {
    const track = tracks[e.trackSlug];
    if (!track) continue;
    const hours = hoursFor(e);
    await prisma.trackEvent.create({
      data: {
        trackId: track.id,
        title: e.title,
        description: e.description ?? null,
        kind: e.kind,
        startsAt: atNoon(daysAhead(e.inDays)),
        endsAt: e.days ? atNoon(daysAhead(e.inDays + e.days - 1)) : null,
        ...hours,
      },
    });
  }

  // ---- Users ----
  const passwordHash = await hashPassword(DEFAULT_PASSWORD);
  const users: Record<string, { id: string; name: string }> = {};
  for (const u of userSeed) {
    const user = await prisma.user.create({
      data: {
        name: u.name,
        email: u.email,
        role: u.role,
        passwordHash,
        location: u.location ?? null,
        phone: u.phone ?? null,
        avatarUrl: `/avatars/${u.key}.svg`,
        operatorTrackId: u.trackSlug ? tracks[u.trackSlug].id : null,
        // Seeded accounts are demo logins, not signups: there is no inbox to
        // confirm, and `login` refuses an unverified account.
        emailVerifiedAt: new Date(),
      },
    });
    users[u.key] = { id: user.id, name: user.name };
  }

  // ---- Passes ----
  const passes: Record<string, { id: string; expiresAt: Date }> = {};
  for (const u of userSeed) {
    if (u.role !== Role.RIDER) continue;
    const tier = tiers[u.tier!];

    if (u.expired) {
      // A previous-season pass, already expired.
      const prevYear = SEASON_YEAR - 1;
      const pass = await prisma.pass.create({
        data: {
          userId: users[u.key].id,
          tierId: tier.id,
          seasonId: season.id,
          seasonYear: prevYear,
          status: PassStatus.EXPIRED,
          activatedAt: new Date(Date.UTC(prevYear, 0, 15)),
          expiresAt: new Date(Date.UTC(prevYear, 11, 31, 23, 59, 59)),
        },
      });
      passes[u.key] = { id: pass.id, expiresAt: pass.expiresAt };
      await prisma.payment.create({
        data: {
          userId: users[u.key].id,
          passId: pass.id,
          tierId: tier.id,
          amountCents: tier.priceCents,
          status: PaymentStatus.PAID,
          createdAt: new Date(Date.UTC(prevYear, 0, 15)),
        },
      });
      continue;
    }

    const pass = await prisma.pass.create({
      data: {
        userId: users[u.key].id,
        tierId: tier.id,
        seasonId: season.id,
        seasonYear: SEASON_YEAR,
        status: PassStatus.PENDING,
        expiresAt: seasonBounds.endsAt,
      },
    });
    await prisma.payment.create({
      data: {
        userId: users[u.key].id,
        passId: pass.id,
        tierId: tier.id,
        amountCents: tier.priceCents,
        status: PaymentStatus.PAID,
      },
    });
    const activated = await activatePass(pass.id);
    passes[u.key] = { id: activated.id, expiresAt: activated.expiresAt };

    // A rider who rode last season still carries that ledger: the pass is
    // retired, not deleted, so the days and the receipts stay with the account
    // while the network reads the pass they hold now. The demo's free account
    // (quinn) has one, which is what its ride history reads from — the days
    // themselves are in seed/activity.ts, under `pass: 'quinn-prior'`.
    if (u.priorSeason) {
      const prevYear = SEASON_YEAR - 1;
      const priorTier = tiers[u.priorSeason];
      const prior = await prisma.pass.create({
        data: {
          userId: users[u.key].id,
          tierId: priorTier.id,
          seasonId: season.id,
          seasonYear: prevYear,
          status: PassStatus.EXPIRED,
          activatedAt: new Date(Date.UTC(prevYear, 0, 15)),
          expiresAt: new Date(Date.UTC(prevYear, 11, 31, 23, 59, 59)),
        },
      });
      passes[`${u.key}-prior`] = { id: prior.id, expiresAt: prior.expiresAt };
      await prisma.payment.create({
        data: {
          userId: users[u.key].id,
          passId: prior.id,
          tierId: priorTier.id,
          amountCents: priorTier.priceCents,
          status: PaymentStatus.PAID,
          createdAt: new Date(Date.UTC(prevYear, 0, 15)),
        },
      });
    }
  }

  // ---- Perks ----
  for (const p of perkSeed) {
    const { tierSlug, ...rest } = p;
    await prisma.perk.create({
      data: { ...rest, tierId: tierSlug ? tiers[tierSlug].id : null },
    });
  }

  // ---- Riders' reviews (the venue pages' community wall) ----
  // The venue's own photos above stand in as the frame each rider attached, so
  // the wall is not empty on a fresh seed. One review per rider per venue — the
  // seed must not repeat a userKey for the same trackSlug. See
  // seed/trackReviews.ts.
  for (const r of trackReviewSeed) {
    const track = tracks[r.trackSlug];
    const user = users[r.userKey];
    const file = trackPhotoSeed[r.trackSlug]?.[r.photoIndex]?.file;
    if (!track || !user || !file) continue;
    // Written on different days back through the season, so the wall does not
    // read as one batch created by the seed run.
    const writtenAt = new Date(Date.now() - r.daysAgo * 24 * 60 * 60 * 1000);
    await prisma.trackReview.create({
      data: {
        trackId: track.id,
        userId: user.id,
        rating: r.rating,
        body: r.body,
        createdAt: writtenAt,
        updatedAt: writtenAt,
        photos: {
          create: [{ url: `/tracks/photos/${r.trackSlug}/${file}`, sortOrder: 0 }],
        },
      },
    });
  }

  // ---- Follows (the free tier's surface) ----
  for (const f of followSeed) {
    await prisma.trackFollow.create({
      data: { userId: users[f.key].id, trackId: tracks[f.trackSlug].id },
    });
  }

  // ---- Activity ----
  await seedActivity({
    prisma,
    seasonId: season.id,
    seasonYear: SEASON_YEAR,
    tracks,
    stations,
    users,
    passes,
  });

  // ---- Summary ----
  const counts = {
    season: await prisma.season.count(),
    tracks: await prisma.track.count(),
    contracts: await prisma.trackContract.count(),
    photos: await prisma.trackPhoto.count(),
    reviews: await prisma.trackReview.count(),
    tiers: await prisma.passTier.count(),
    users: await prisma.user.count(),
    passes: await prisma.pass.count(),
    allotments: await prisma.allotment.count(),
    follows: await prisma.trackFollow.count(),
    redemptions: await prisma.redemption.count(),
    scanEvents: await prisma.scanEvent.count(),
    perks: await prisma.perk.count(),
    payments: await prisma.payment.count(),
  };
  console.log('Seed complete:', counts);
  console.log(`\nAll seeded accounts use the password: ${DEFAULT_PASSWORD}`);
  console.log('  Rider   : quinn@example.com (Free — follows three tracks, rode last season)');
  console.log('  Rider   : alex@example.com (Moto Pass)');
  console.log('  Rider   : jordan@example.com (Moto Pass — mid-season)');
  console.log('  Rider   : sam@example.com (Moto Pass — out of days at 221 MX)');
  console.log('  Rider   : riley@example.com (Moto Pass)');
  console.log('  Rider   : taylor@example.com (Moto Pass)');
  console.log('  Rider   : casey@example.com (Moto Pass)');
  console.log('  Rider   : morgan@example.com (Expired pass)');
  console.log('  Operator: ops@221mx.example.com');
  console.log('  Operator: ops@eastbend.example.com');
  console.log('  Operator: ops@sobmx.example.com');
  console.log('  Admin   : admin@motopass.example.com');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import { PrismaClient } from '@prisma/client';
import { RedemptionKind, ScanResult } from '../../src/types/enums';
import { dayKey, daysAgo, daysAhead } from './helpers';

interface Ctx {
  prisma: PrismaClient;
  seasonId: string;
  seasonYear: number;
  tracks: Record<string, { id: string; name: string }>;
  stations: Record<string, string>; // trackSlug -> stationId
  users: Record<string, { id: string; name: string }>;
  passes: Record<string, { id: string; expiresAt: Date }>;
}

/** A gate entry at `hour` on the given day. The operator's hourly read and the
    activity log both print on the venue's own clock, so the seed builds the
    timestamp in local time and the two agree. Riders arrive in the morning, so
    the ledger carries a real hour rather than midnight. */
function at(day: Date, hour: number): Date {
  return new Date(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), hour, 0, 0, 0);
}

/** A day in the season before this one (`month` is 0-indexed), as UTC midnight.
    The retired pass a rider rode last season is dated off the season year, not
    off "today", so its ledger can never drift into the current season. */
function priorSeasonDay(seasonYear: number, month: number, day: number): Date {
  return new Date(Date.UTC(seasonYear - 1, month, day));
}

