 * booked-out venue is: shut all day, not on a schedule.
 */
export const KIND_HOURS: Record<TrackEventKind, [string, string] | null> = {
  PRACTICE: ['09:00', '16:00'],
  RACE: ['07:00', '17:00'],
  CLINIC: ['10:00', '14:00'],
  RIDE_DAY: ['09:00', '15:00'],
  OTHER: null,
};

/** `HH:MM` as minutes past midnight — how a date's hours are stored. */
export function toMinutes(hhmm: string) {
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

/** The window a seeded date runs: its own hours, else its kind's, else all-day. */
export function hoursFor(e: { kind: TrackEventKind; from?: string; to?: string }) {
  const own = e.from && e.to ? ([e.from, e.to] as [string, string]) : KIND_HOURS[e.kind];
  return own
    ? { startMinutes: toMinutes(own[0]), endMinutes: toMinutes(own[1]) }
    : { startMinutes: null, endMinutes: null };
}

/**
 * One-off: stamp every account that predates the email-confirmation step as
 * verified.
 *
 * `login` already grandfathers those accounts (see `lib/verificationCutoff.ts`)
 * and stamps them on their next sign-in; this script does the whole set at once,
 * so the rows match the accounts' real state before anyone signs in. It only
 * touches accounts created before the cut-off, so a signup that still owes a
 * confirmation is left alone — safe to run at any time, and safe to run twice.
 *
 * Run after `prisma db push`:  cd server && npx tsx scripts/backfill-email-verified.ts
 */
import { prisma } from '../src/utils/prisma';
import { VERIFICATION_REQUIRED_FROM } from '../src/lib/verificationCutoff';

async function main() {
  console.log(`Cut-off: ${VERIFICATION_REQUIRED_FROM.toISOString()} (accounts older than this are grandfathered)`);

  const stale = await prisma.user.findMany({
    where: { emailVerifiedAt: null, createdAt: { lt: VERIFICATION_REQUIRED_FROM } },
    select: { id: true, email: true, role: true, createdAt: true },
    orderBy: { createdAt: 'asc' },
  });

  if (stale.length === 0) {
    console.log('No account predates the cut-off. Nothing to do.');
    return;
  }

  console.log(`${stale.length} account(s) predate the step:`);
  for (const u of stale) {
    console.log(`  ${u.createdAt.toISOString()}  ${u.role.padEnd(8)} ${u.email}`);
  }

  const { count } = await prisma.user.updateMany({
    where: { emailVerifiedAt: null, createdAt: { lt: VERIFICATION_REQUIRED_FROM } },
    data: { emailVerifiedAt: new Date() },
  });
  console.log(`Stamped ${count} account(s) as verified.`);
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

/**
 * Build client/public/assets/moto-pass-logo.png — the lockup the mail bodies
 * point at, from the same `/assets/moto-pass-logo.svg` the app header draws.
 *
 *   cd server && node scripts/make-email-logo.mjs
 *
 * Why a second file: Gmail, Outlook and most webmail strip <svg> from a message
 * body, and a data: URI is stripped by Gmail too, so the logo has to be a
 * raster PNG at an absolute URL. The PNG is committed, so a deploy does not
 * need this script — re-run it only when the artwork changes.
 *
 * The SVG fills with `currentColor`, which nothing supplies to an <img> or a
 * rasteriser (it would come out black). The ink is substituted here: white, so
 * the lockup reads as the brand mark on the dark card the messages use.
 *
 * Sizing: the file is 3x the 62 x 40 CSS px the message displays it at, so it
 * stays sharp on a retina screen without being a large attachment to fetch.
 */
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../..');
const src = path.join(root, 'client/public/assets/moto-pass-logo.svg');
const out = path.join(root, 'client/public/assets/moto-pass-logo.png');

const INK = '#ffffff'; // white, so the lockup reads as the plain brand mark on the dark card
const WIDTH = 186; // 62 CSS px x 3

const svg = (await readFile(src, 'utf8')).replaceAll('currentColor', INK);

// density is what librsvg uses to pick a raster grid before the resize, so a
// high value keeps the curves clean instead of upscaling a 72dpi render.
const png = await sharp(Buffer.from(svg), { density: 600 })
  .resize({ width: WIDTH, fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
  .png({ compressionLevel: 9, palette: false })
  .toBuffer();

await writeFile(out, png);
const meta = await sharp(png).metadata();
console.log(`wrote client/public/assets/moto-pass-logo.png (${meta.width}x${meta.height}, ${png.length} bytes)`);

/**
 * Proves the EMAIL fields are sanitised at the boundary, not just refused.
 *
 * Two write paths carry an email:
 *   POST /api/auth/register        the rider's own address (unique key)
 *   PATCH /api/owner/track         an operator's public contact address
 *
 * Each is sent a value with a control character, a zero-width space, a bidi
 * override and ragged whitespace — then read back with Prisma and compared to
 * what was meant to be stored. A malformed address must be a 400 that names the
 * field, and it must leave no row behind.
 *
 * Run with the API up:  cd server && npx tsx scripts/probe-email.ts
 */
import { prisma } from '../src/utils/prisma';

const API = process.env.API_BASE ?? 'http://127.0.0.1:4010/api';
const RIDER_EMAIL = 'probe-email@example.invalid';
const CLEAN_RIDER_EMAIL = 'Probe.Email+tag@Example.COM';
const COOKIE_JAR: Record<string, string> = {};

function cookieHeader() {
  return Object.entries(COOKIE_JAR).map(([k, v]) => `${k}=${v}`).join('; ');
}

async function call(path: string, init: RequestInit = {}) {
  const res = await fetch(`${API}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(Object.keys(COOKIE_JAR).length ? { cookie: cookieHeader() } : {}),
      ...(init.headers ?? {}),
    },
  });
  for (const raw of res.headers.getSetCookie?.() ?? []) {
    const [pair] = raw.split(';');
    const [name, ...rest] = pair.split('=');
    COOKIE_JAR[name] = rest.join('=');
  }
  const body = await res.json().catch(() => ({}));
  return { status: res.status, body: body as Record<string, any> };
}

function check(label: string, ok: boolean, detail: unknown) {
  console.log(`${ok ? 'PASS' : 'FAIL'} | ${label.padEnd(52)} | ${JSON.stringify(detail)}`);
  if (!ok) process.exitCode = 1;
}

async function main() {
  await prisma.user.deleteMany({ where: { email: { in: [RIDER_EMAIL, CLEAN_RIDER_EMAIL, CLEAN_RIDER_EMAIL.toLowerCase()] } } });

  // 1. A rider address carrying controls, a zero-width space, a bidi override
  //    and ragged whitespace must be stored as plain text.
  const dirty = ` \u0000${CLEAN_RIDER_EMAIL}\u200B\u202E  `;
  const reg = await call('/auth/register', {
    method: 'POST',
    body: JSON.stringify({ name: 'Probe Email', email: dirty, password: 'dialed123' }),
  });
  check('register with a dirty address answers 201', reg.status === 201, reg.status);

  // An account address is stored lowercased (zAccountEmail), so the row is
  // keyed by the typed address in lower case.
  const row = await prisma.user.findUnique({ where: { email: CLEAN_RIDER_EMAIL.toLowerCase() } });
  check(
    'stored rider email equals the typed address, lowercased',
    row?.email === CLEAN_RIDER_EMAIL.toLowerCase(),
    row?.email ?? null
  );

  // 1b. Sign-in in a different case reaches the same account (403 = found but
  //     unconfirmed; 401 would mean the case mismatch missed the row).
  const mixed = await call('/auth/login', {
    method: 'POST',
    body: JSON.stringify({ email: CLEAN_RIDER_EMAIL.toUpperCase(), password: 'dialed123' }),
  });
  check('login in another case finds the account', mixed.status === 403, mixed.status);

  // 2. A malformed address is a 400 naming the field, and writes nothing.
  for (const bad of ['ops@@example.com', 'no-at-sign.example.com', 'rider@example', 'rider@.com', `${'a'.repeat(250)}@example.com`]) {
    const res = await call('/auth/register', {
      method: 'POST',
      body: JSON.stringify({ name: 'Probe Bad', email: bad, password: 'dialed123' }),
    });
    const field = res.body?.errors?.[0]?.field;
    check(`register refuses ${JSON.stringify(bad.slice(0, 30))}`, res.status === 400 && field === 'email', `${res.status} ${field ?? ''}`);
  }

  // 3. The operator's public contact address: a malformed one is refused, a
  //    dirty one is stored cleaned, and blank clears it.
  const login = await call('/auth/login', {
    method: 'POST',
    body: JSON.stringify({ email: 'ops@221mx.example.com', password: 'dialed123' }),
  });
  check('operator signs in', login.status === 200, login.status);
  const trackId = login.body?.data?.user?.operatorTrackId as string | undefined;

  const before = await prisma.track.findUnique({
    where: { id: trackId ?? '' },
    select: { email: true },
  });
  const previous = before?.email ?? null;
  try {
    const bad = await call('/owner/track', {
      method: 'PATCH',
      body: JSON.stringify({ email: 'gate@221mx' }),
    });
    check('owner PATCH refuses a malformed contact email', bad.status === 400, `${bad.status} ${bad.body?.message ?? ''}`);

    const ok = await call('/owner/track', {
      method: 'PATCH',
      body: JSON.stringify({ email: `gate\u200B@221mx.example.com\u202E ` }),
    });
    check('owner PATCH accepts a dirty but valid address', ok.status === 200, ok.status);

    const after = await prisma.track.findUnique({ where: { id: trackId ?? '' }, select: { email: true } });
    check('stored track email is cleaned', after?.email === 'gate@221mx.example.com', after?.email ?? null);

    const cleared = await call('/owner/track', { method: 'PATCH', body: JSON.stringify({ email: '' }) });
    const blank = await prisma.track.findUnique({ where: { id: trackId ?? '' }, select: { email: true } });
    // '' clears the address; the column stores it as NULL, which is the same
    // answer on the public page.
    check('blank clears the contact address', cleared.status === 200 && !blank?.email, blank?.email ?? null);
  } finally {
    // Put the seeded value back whatever happened above.
    await prisma.track.update({ where: { id: trackId ?? '' }, data: { email: previous } });
  }

  await prisma.user.deleteMany({ where: { email: { in: [RIDER_EMAIL, CLEAN_RIDER_EMAIL, CLEAN_RIDER_EMAIL.toLowerCase()] } } });
  const leftover = await prisma.user.count({ where: { email: { in: [RIDER_EMAIL, CLEAN_RIDER_EMAIL, CLEAN_RIDER_EMAIL.toLowerCase()] } } });
  check('probe rows removed', leftover === 0, leftover);

  await prisma.$disconnect();
}

main().catch(async (err) => {
  console.error(err);
  await prisma.$disconnect();
  process.exit(1);
});

/**
 * Sends one real message through the app's own mail path and reports what the
 * provider said. Use it the moment a key is issued — it is the only check that
 * proves the key, the from-domain and the API agree, and it names the failure
 * instead of leaving a rider to wonder why no mail arrived.
 *
 *   cd server && npx tsx scripts/probe-mail.ts you@example.com
 *
 * The key path follows NODE_ENV, same as the server: development reads
 * RESEND_API_KEY_DEV, production reads RESEND_API_KEY_PROD. To exercise the live
 * path from this box, lead with the variable — dotenv does not overwrite it:
 *
 *   NODE_ENV=production npx tsx scripts/probe-mail.ts you@example.com
 *
 * With Resend it first lists the account's domains: a `from` on a domain that
 * is not verified there is the one mistake this setup invites, and it comes
 * back as a flat 403 on send.
 */
import '../src/config'; // loads server/.env before the mail service reads it
import {
  mailProvider,
  mailEnv,
  mailConfigured,
  mailFrom,
  resendKey,
  sendMail,
  appUrl,
} from '../src/services/mail.service';

const TO = process.argv[2];
const FROM = mailFrom;
const RESEND_API_KEY = resendKey;
const KEY_VAR = mailEnv === 'prod' ? 'RESEND_API_KEY_PROD' : 'RESEND_API_KEY_DEV';

async function reportResendDomains() {
  try {
    const res = await fetch('https://api.resend.com/domains', {
      headers: { Authorization: `Bearer ${RESEND_API_KEY}` },
    });
    if (!res.ok) {
      const body = await res.text().catch(() => '');
      // A send-only key cannot list domains; that is a valid setup, not a fault.
      if (/restricted_api_key|restricted to only send/i.test(body)) {
        console.log(`domains  | skipped: ${KEY_VAR} is send-only, so it cannot list domains`);
        console.log('domains  | verify the from-domain in the Resend dashboard instead');
        return;
      }
      console.log(`domains  | request failed: ${res.status} ${body}`);
      return;
    }
    const body = (await res.json()) as { data?: Array<{ name: string; status: string }> };
    const domains = body.data ?? [];
    if (!domains.length) {
      console.log('domains  | none on this account — verify one before sending');
      return;
    }
    for (const d of domains) console.log(`domains  | ${d.name} — ${d.status}`);
    const fromDomain = FROM.match(/@([^>\s]+)/)?.[1]?.toLowerCase();
    const match = domains.find((d) => d.name.toLowerCase() === fromDomain);
    console.log(
      `domains  | from-domain ${fromDomain} ` +
        `is ${match ? `${match.status}${match.status === 'verified' ? '' : ' (sends will be refused)'}` : 'NOT on this account'}`
    );
  } catch (err) {
    console.log(`domains  | unreachable: ${(err as Error).message}`);
  }
}

async function main() {
  console.log(
    `provider | ${mailProvider}` +
      (mailProvider === 'resend' ? ` (${mailEnv} path, ${KEY_VAR})` : '') +
      (mailConfigured ? '' : ' (nothing configured — messages print to the log)')
  );
  console.log(`from     | ${FROM}`);
  // Confirm/reset links are built from this origin, so a probe that only checks
  // the sender still leaves the message pointing at the wrong host.
  console.log(
    `links    | ${appUrl()} (${mailEnv === 'prod' ? 'APP_PUBLIC_URL_PROD' : 'APP_PUBLIC_URL_DEV'})`
  );
  if (mailProvider === 'resend') await reportResendDomains();

  if (!TO) {
    console.log('\nNo recipient given. Re-run as: npx tsx scripts/probe-mail.ts you@example.com');
    return;
  }

  const result = await sendMail({
    to: TO,
    subject: 'Moto Pass mail test',
    text: [
      'This is a test message from the Moto Pass server.',
      '',
      `Provider: ${mailProvider}${mailProvider === 'resend' ? ` (${mailEnv})` : ''}`,
      `Sent at:  ${new Date().toISOString()}`,
      '',
      'If you are reading it, signups and password resets will reach riders too.',
    ].join('\n'),
    html: `<!doctype html>
<html><body style="margin:0;padding:24px;background:#0d0f12;color:#e8eaed;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;">
  <div style="max-width:520px;margin:0 auto;background:#171a1f;border:1px solid #2a2f36;border-radius:12px;padding:28px;">
    <p style="margin:0 0 18px;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#ff8a3f;">Moto Pass</p>
    <h1 style="margin:0 0 14px;font-size:20px;font-weight:600;">Mail test</h1>
    <p style="margin:0 0 12px;color:#b6bcc6;line-height:1.55;">This is a test message from the Moto Pass server.</p>
    <p style="margin:0;color:#7d848f;font-size:12px;line-height:1.6;">Provider: ${mailProvider}<br>Sent at: ${new Date().toISOString()}</p>
  </div>
</body></html>`,
  });

  console.log(`\nsend     | ${result.delivered ? 'DELIVERED' : 'NOT DELIVERED'}`);
  if (result.id) console.log(`id       | ${result.id}`);
  if (result.reason) console.log(`reason   | ${result.reason}`);
  if (!result.delivered) process.exitCode = 1;
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * Proves the write paths store SANITISED text, not just answer 400s.
 *
 * Creates a throwaway rider through the real HTTP API, sends a name, a phone,
 * a location and a review body carrying control characters, zero-width joiners,
 * bidi overrides and ragged whitespace, then reads the rows back with Prisma and
 * prints what was actually stored. Deletes everything it made at the end.
 *
 * Run with the API up:  cd server && npx tsx scripts/probe-sanitize.ts
 */
import { prisma } from '../src/utils/prisma';

const API = process.env.API_BASE ?? 'http://127.0.0.1:4010/api';
const EMAIL = 'probe-sanitize@example.invalid';
const PASSWORD = 'dialed123';

let cookie = '';

async function call(path: string, init: RequestInit = {}) {
  const res = await fetch(`${API}${path}`, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(cookie ? { cookie } : {}),
      ...(init.headers ?? {}),
    },
  });
  const set = res.headers.getSetCookie?.() ?? (res.headers.get('set-cookie') ? [res.headers.get('set-cookie')!] : []);
  if (set.length) cookie = set.map((c) => c.split(';')[0]).join('; ');
  const body = await res.json().catch(() => ({}));
  return { status: res.status, body: body as Record<string, unknown> };
}

function line(label: string, value: unknown) {
  console.log(`${label.padEnd(28)} ${JSON.stringify(value)}`);
}

async function main() {
  await prisma.user.deleteMany({ where: { email: EMAIL } });

  // Name: zero-width space inside, a bidi override, a BEL, double spaces, padding.
  const rawName = '  Ri\u200bley\u202e  Chen\u0007 ';
  const rawLocation = 'Charlotte\u200b,  NC\u0000 ';
  const registered = await call('/auth/register', {
    method: 'POST',
    body: JSON.stringify({
      name: rawName,
      email: EMAIL,
      password: PASSWORD,
      phone: ' 828 555 0199 ',
    }),
  });
  console.log('register status             ', registered.status);
  if (registered.status !== 201) {
    console.log(JSON.stringify(registered.body));
    return;
  }

  // The account is unverified, so registering sets no session. Spending the
  // confirmation link the API hands back (non-production) is what signs in.
  const devLink = String((registered.body.data as { devLink?: string })?.devLink ?? '');
  const token = devLink.split('token=')[1] ?? '';
  const confirmed = await call('/auth/verify-email', {
    method: 'POST',
    body: JSON.stringify({ token }),
  });
  console.log('confirm status              ', confirmed.status);

  const profile = await call('/auth/me', {
    method: 'PATCH',
    body: JSON.stringify({ location: rawLocation }),
  });
  console.log('profile patch status        ', profile.status);

  const tracks = await call('/tracks');
  const tracksData = (tracks.body.data ?? {}) as { tracks?: { id: string; slug: string }[] };
  const track = tracksData.tracks?.find((t) => t.slug === '221-mx');
  if (!track) throw new Error('221 MX is not seeded.');

  const body = 'Great track\u0000 — prep was  perfect\n\n\n\nLoved it\u200b\u202e';
  const review = await call('/me/track-reviews', {
    method: 'POST',
    body: JSON.stringify({ trackId: track.id, rating: 5, body }),
  });
  console.log('review post status          ', review.status);

  const user = await prisma.user.findUnique({ where: { email: EMAIL } });
  console.log('--- sent / stored ---');
  line('name sent', rawName);
  line('name stored', user?.name);
  line('phone stored', user?.phone);
  line('location sent', rawLocation);
  line('location stored', user?.location);

  const storedReview = user
    ? await prisma.trackReview.findFirst({ where: { userId: user.id }, select: { body: true } })
    : null;
  line('review body sent', body);
  line('review body stored', storedReview?.body);

  const clean =
    user?.name === 'Riley Chen' &&
    user?.phone === '+18285550199' &&
    user?.location === 'Charlotte, NC' &&
    storedReview?.body === 'Great track — prep was  perfect\n\nLoved it';
  console.log(clean ? '\nOK: every field stored cleaned.' : '\nFAIL: a field stored something raw.');

  if (user) {
    await prisma.trackReview.deleteMany({ where: { userId: user.id } });
    await prisma.trackFollow.deleteMany({ where: { userId: user.id } });
    await prisma.session.deleteMany({ where: { userId: user.id } });
    await prisma.allotment.deleteMany({ where: { userId: user.id } });
    await prisma.pass.deleteMany({ where: { userId: user.id } });
    await prisma.user.delete({ where: { id: user.id } });
    console.log('probe account removed.');
  }
  await prisma.$disconnect();
}

main().catch(async (err) => {
  console.error(err);
  await prisma.$disconnect();
  process.exit(1);
});

/**
 * Live Spaces round trip, against whatever bucket this process is configured for.
 *
 *   npx tsx scripts/probe-spaces.ts
 *
 * Uploads a tiny real PNG, reads it back over the public base, deletes it, and
 * confirms it is gone. This is the check the unit suite cannot make — it needs
 * bucket-scoped credentials and network access. It never prints a secret.
 * Exits non-zero on the first failed step.
 */
import { randomUUID } from 'node:crypto';
import sharp from 'sharp';
import { config } from '../src/config';
import { MediaStore } from '../src/services/media.service';

const step = (label: string, detail = '') => console.log(`  ${label}${detail ? ` — ${detail}` : ''}`);

async function main() {
  if (config.spaces.provider !== 'spaces') {
    throw new Error('MEDIA_STORAGE is not spaces — nothing live to probe.');
  }
  const store = new MediaStore({ spaces: config.spaces, uploads: config.uploads });
  console.log(`\nbucket ${config.spaces.bucket} · region ${config.spaces.region} · base ${config.spaces.publicBase}\n`);

  const trackId = randomUUID();
  const png = await sharp({
    create: { width: 16, height: 12, channels: 3, background: '#ca4133' },
  }).png().toBuffer();

  step('uploading a 16x12 PNG to the gallery slot');
  const stored = await store.storeDataUrl(
    trackId,
    'photo',
    `data:image/png;base64,${png.toString('base64')}`
  );
  if ('status' in stored) throw new Error(`upload refused: HTTP ${stored.status} ${stored.message}`);
  step('stored reference', stored.url);

  const publicUrl = store.resolveMediaUrl(stored.url);
  if (!publicUrl) throw new Error('the stored reference does not resolve to a public URL');
  step('public URL', publicUrl);

  const read = await fetch(publicUrl, { method: 'GET' });
  step('anonymous GET', `HTTP ${read.status} · ${read.headers.get('content-type') ?? 'no type'} · ${read.headers.get('content-length') ?? '?'} bytes`);
  if (read.status !== 200) throw new Error('the object is not publicly readable through the configured base');
  const body = Buffer.from(await read.arrayBuffer());
  if (body.length !== png.length) throw new Error(`served ${body.length} bytes, uploaded ${png.length}`);

  await store.deleteManagedFile(stored.url);
  step('deleted the object');

  const after = await fetch(publicUrl, { method: 'GET', cache: 'no-store' });
  step('anonymous GET after delete', `HTTP ${after.status}`);
  if (after.status === 200) throw new Error('the object is still readable after delete');

  console.log('\nLive Spaces round trip passed: put, public read, delete.\n');
}

main().catch((err: unknown) => {
  console.error(`\nFAILED — ${err instanceof Error ? err.message : String(err)}\n`);
  process.exitCode = 1;
});

/**
 * Checks the cut-off rule: an account that predates email confirmation signs in
 * without one and is stamped; an account created after it cannot.
 */
import { prisma } from '../src/utils/prisma';
import { hashPassword } from '../src/utils/password';
import { VERIFICATION_REQUIRED_FROM } from '../src/lib/verificationCutoff';

const API = 'http://127.0.0.1:4010/api';
const PASSWORD = 'dialed123';
const OLD = 'cutoff.old@example.invalid';
const NEW = 'cutoff.new@example.invalid';

async function call(path: string, body: unknown) {
  const res = await fetch(`${API}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: (await res.json()) as any };
}

function check(label: string, ok: boolean, detail: unknown) {
  console.log(`${ok ? 'PASS' : 'FAIL'} | ${label.padEnd(56)} | ${JSON.stringify(detail)}`);
  if (!ok) process.exitCode = 1;
}

async function main() {
  await prisma.user.deleteMany({ where: { email: { in: [OLD, NEW] } } });
  const passwordHash = await hashPassword(PASSWORD);

  // An account from before the step: unverified, created a day earlier.
  await prisma.user.create({
    data: {
      email: OLD,
      name: 'Before The Step',
      passwordHash,
      createdAt: new Date(VERIFICATION_REQUIRED_FROM.getTime() - 86_400_000),
    },
  });
  // And one from after it, left unconfirmed.
  await prisma.user.create({
    data: {
      email: NEW,
      name: 'After The Step',
      passwordHash,
      createdAt: new Date(VERIFICATION_REQUIRED_FROM.getTime() + 60_000),
    },
  });

  const old = await call('/auth/login', { email: OLD, password: PASSWORD });
  check('an account older than the step still signs in', old.status === 200, old.body.message);
  const oldRow = await prisma.user.findUnique({ where: { email: OLD } });
  check('and is stamped verified on that sign-in', Boolean(oldRow?.emailVerifiedAt), oldRow?.emailVerifiedAt);

  const fresh = await call('/auth/login', { email: NEW, password: PASSWORD });
  check(
    'an account created after the step is held at the confirm screen',
    fresh.status === 403 && fresh.body.data?.needsVerification === true,
    `${fresh.status} ${fresh.body.message}`
  );

  await prisma.user.deleteMany({ where: { email: { in: [OLD, NEW] } } });
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());

/**
 * First-deploy seed guard, run by the App Platform PRE_DEPLOY job.
 *
 * `npm run seed` wipes every table and rebuilds the demo, which is right for a
 * fresh managed database and wrong for every deploy after it. This counts the
 * partner tracks first and only seeds when the schema came up empty, so a
 * redeploy keeps whatever sessions and redemptions the demo has collected.
 *
 *   npx tsx scripts/seed-if-empty.ts
 *
 * Must run after `prisma db push`, or the count itself throws.
 */
import { prisma } from '../src/utils/prisma';
import { spawnSync } from 'child_process';
import path from 'path';

async function main() {
  const tracks = await prisma.track.count();
  if (tracks > 0) {
    console.log(`[seed-if-empty] ${tracks} tracks present, skipping seed.`);
    return;
  }

  console.log('[seed-if-empty] empty database, running the demo seed.');
  const res = spawnSync('npx', ['tsx', 'prisma/seed.ts'], {
    cwd: path.resolve(__dirname, '..'),
    stdio: 'inherit',
    env: process.env,
  });
  if (res.status !== 0) {
    throw new Error(`seed exited with ${res.status}`);
  }
}

main()
  .catch((err) => {
    console.error(err);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

