import sharp from 'sharp';

const BASE = 'http://localhost:4010/api';
const PASSWORD = 'dialed123';
const SEEDED = '/avatars/quinn.svg';

let passCount = 0;
let failCount = 0;
function check(label: string, ok: boolean, detail = '') {
  if (ok) {
    passCount++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    failCount++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
}

class Client {
  cookie = '';
  async call<T = any>(path: string, method = 'GET', body?: unknown): Promise<{ status: number; json: T }> {
    const res = await fetch(`${BASE}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(this.cookie ? { Cookie: this.cookie } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    for (const c of res.headers.getSetCookie?.() ?? []) {
      const [pair] = c.split(';');
      if (pair.startsWith('moto_sid=')) this.cookie = pair;
    }
    return { status: res.status, json: (await res.json()) as T };
  }
}

async function png(background: string): Promise<string> {
  const bytes = await sharp({ create: { width: 40, height: 40, channels: 3, background } })
    .png()
    .toBuffer();
  return `data:image/png;base64,${bytes.toString('base64')}`;
}

/** Follow the managed reference to whatever it serves (302 → bucket, or disk). */
async function serves(url: string): Promise<number> {
  const res = await fetch(`http://localhost:4010${url}`, { redirect: 'follow' });
  return res.status;
}

async function main() {
  console.log('\n=== Moto Pass — rider avatar ===\n');

  const rider = new Client();
  const anon = new Client();
  await rider.call('/auth/login', 'POST', { email: 'quinn@example.com', password: PASSWORD });

  const before = await rider.call('/auth/me');
  check('the seeded avatar is a shipped file, not a managed one', before.json.data?.user?.avatarUrl === SEEDED, before.json.data?.user?.avatarUrl);

  const first = await rider.call('/auth/me/avatar', 'POST', { dataUrl: await png('#1d7a4b') });
  const firstUrl: string = first.json.data?.url ?? '';
  check('an upload answers a managed reference', firstUrl.startsWith('/api/media/users/'), firstUrl || first.json.message);
  check('the reference lives under the user, not a track', /\/users\/[0-9a-f-]{36}\/avatar\/[0-9a-f-]{36}\.png$/.test(firstUrl), firstUrl);
  check('the stored photo serves', (await serves(firstUrl)) === 200);
  const me = await rider.call('/auth/me');
  check('the account now carries that photo', me.json.data?.user?.avatarUrl === firstUrl, me.json.data?.user?.avatarUrl);

  const second = await rider.call('/auth/me/avatar', 'POST', { dataUrl: await png('#b3402c') });
  const secondUrl: string = second.json.data?.url ?? '';
  check('a second upload replaces it', second.status === 201 && secondUrl !== firstUrl, secondUrl);
  check('the replaced file is retired', (await serves(firstUrl)) === 403, `GET ${firstUrl}`);
  check('the new file serves', (await serves(secondUrl)) === 200);

  const cleared = await rider.call('/auth/me', 'PATCH', { avatarUrl: '' });
  check('clearing the photo empties the field', cleared.json.data?.user?.avatarUrl === null, String(cleared.json.data?.user?.avatarUrl));
  check('the cleared file is retired', (await serves(secondUrl)) === 403, `GET ${secondUrl}`);

  const garbage = await rider.call('/auth/me/avatar', 'POST', { dataUrl: 'data:image/png;base64,aGk=' });
  check('bytes that are not an image are refused', garbage.status === 400, `HTTP ${garbage.status}`);
  const svg = await rider.call('/auth/me/avatar', 'POST', {
    dataUrl: `data:image/svg+xml;base64,${Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>').toString('base64')}`,
  });
  check('SVG is refused', svg.status === 400, `HTTP ${svg.status}`);
  const anonymous = await anon.call('/auth/me/avatar', 'POST', { dataUrl: await png('#123456') });
  check('an anonymous upload is refused', anonymous.status === 401, `HTTP ${anonymous.status}`);

  // Leave the demo account as seeded.
  await rider.call('/auth/me', 'PATCH', { avatarUrl: SEEDED });
  const restored = await rider.call('/auth/me');
  check('the seeded avatar is back', restored.json.data?.user?.avatarUrl === SEEDED, restored.json.data?.user?.avatarUrl);

  console.log(`\n=== ${passCount} passed, ${failCount} failed ===\n`);
  if (failCount) process.exitCode = 1;
}

