/** Execute: npx tsx scripts/verify-media-storage.ts
 * Local files are real; every S3 operation below is MOCKED, never live verification.
 * No credentials, network access, DB or existing uploads are needed/touched.
 */
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';
import { DeleteObjectCommand, PutObjectCommand } from '@aws-sdk/client-s3';
import type { MediaStoreResult, MediaStoreSettings, MediaS3Sender } from '../src/services/media.service';

const TRACK = 'd7c48992-bc1f-46d5-9c31-2c75cb36ee61';
const REVIEW = 'f1b24594-8402-44de-ac0e-1470c180de49';
const MAX_BYTES = 5 * 1024 * 1024;
const dataUrl = (bytes: Buffer, mime = 'png') => `data:image/${mime};base64,${bytes.toString('base64')}`;
function saved(result: MediaStoreResult): string {
  assert.ok('url' in result, JSON.stringify(result));
  return result.url;
}
function rejected(result: MediaStoreResult, status: number): void {
  assert.ok('status' in result, JSON.stringify(result));
  assert.equal(result.status, status);
}

async function main() {
  // Keep the module's default singleton local even if a developer's .env selects
  // Spaces; constructor tests below explicitly exercise fail-closed Spaces setup.
  process.env.MEDIA_STORAGE = 'local';
  const { MediaStore, isManagedMediaKey } = await import('../src/services/media.service');
  const scratch = process.env.TMPDIR || path.resolve(__dirname, '../.media-verify-tmp');
  await fs.mkdir(scratch, { recursive: true });
  const root = await fs.mkdtemp(path.join(scratch, 'moto-media-'));
  const warnings: string[] = [];
  const settings: MediaStoreSettings = {
    spaces: { provider: 'local', region: 'nyc3', bucket: '', publicBase: '', key: '', secret: '' },
    uploads: { dir: path.join(root, 'uploads'), publicPath: '/api/uploads', maxBytes: MAX_BYTES },
  };
  const logger = { warn: (message: string) => { warnings.push(message); } };
  const local = new MediaStore(settings, { logger });
  const fixture = await sharp({ create: { width: 16, height: 12, channels: 3, background: '#ca4133' } })
    .png().toBuffer();
  const fixtureUrl = dataUrl(fixture);
  const localPath = (url: string) => path.join(settings.uploads.dir, url.slice('/api/uploads/'.length));
  let passed = 0;
  const check = async (name: string, fn: () => void | Promise<void>) => {
    await fn();
    passed++;
    console.log(`PASS ${name}`);
  };
  const s3Settings = (base = 'https://motopass-media-dev.nyc3.digitaloceanspaces.com'): MediaStoreSettings => ({
    spaces: {
      provider: 'spaces', region: 'nyc3', bucket: 'motopass-media-dev', publicBase: base,
      key: 'MOCK-ACCESS-KEY', secret: 'MOCK-SECRET-DO-NOT-LOG',
    },
    uploads: { ...settings.uploads },
  });
  const commands: Array<PutObjectCommand | DeleteObjectCommand> = [];
  const fakeS3: MediaS3Sender = { async send(command) { commands.push(command); return {}; } };
  const remote = new MediaStore(s3Settings(), { s3: fakeS3, logger });
  let remoteUrl = '';
  try {
    await check('local: real put/read/delete, immutable UUID path, no prefix deletion', async () => {
      const first = saved(await local.storeDataUrl(TRACK, 'banner', fixtureUrl));
      const second = saved(await local.storeDataUrl(TRACK, 'banner', fixtureUrl));
      assert.match(first, new RegExp(`^/api/uploads/tracks/${TRACK}/banner/[0-9a-f-]{36}\\.png$`));
      assert.notEqual(first, second);
      assert.ok(isManagedMediaKey(first.slice('/api/uploads/'.length)));
      assert.equal((await sharp(await fs.readFile(localPath(first))).metadata()).format, 'png');
      assert.equal((await sharp(await fs.readFile(localPath(second))).metadata()).width, 16);
      await local.removeUploadedFile(first);
      await assert.rejects(fs.access(localPath(first)), { code: 'ENOENT' });
      await fs.access(localPath(second));
      await local.removeUploadedFile(first); // Idempotent exact cleanup.
    });
    await check('local: logo, gallery and preallocated review UUID paths', async () => {
      for (const [kind, slot] of [['logo', 'logo'], ['photo', 'gallery'], ['review', `reviews/${REVIEW}`]] as const) {
        const url = saved(await local.storeDataUrl(TRACK, kind, fixtureUrl, kind === 'review' ? REVIEW : undefined));
        assert.ok(url.startsWith(`/api/uploads/tracks/${TRACK}/${slot}/`));
        await fs.access(localPath(url));
        await local.removeUploadedFile(url);
        await assert.rejects(fs.access(localPath(url)), { code: 'ENOENT' });
      }
    });
    await check('local: avatar lives under the user UUID, not a track', async () => {
      const url = saved(await local.storeDataUrl(REVIEW, 'avatar', fixtureUrl));
      assert.match(url, new RegExp(`^/api/uploads/users/${REVIEW}/avatar/[0-9a-f-]{36}\\.png$`));
      assert.ok(isManagedMediaKey(url.slice('/api/uploads/'.length)));
      await fs.access(localPath(url));
      await local.removeUploadedFile(url);
      await assert.rejects(fs.access(localPath(url)), { code: 'ENOENT' });
      // An avatar kind still demands a UUID scope, and still needs no review id.
      rejected(await local.storeDataUrl('rider-a', 'avatar', fixtureUrl), 400);
    });
    await check('validation: reject malformed UUID scopes, kinds and missing review IDs', async () => {
      for (const scope of ['track-slug', '../private', TRACK + '/extra', '']) {
        rejected(await local.storeDataUrl(scope, 'photo', fixtureUrl), 400);
      }
      rejected(await local.storeDataUrl(TRACK, 'review', fixtureUrl), 400);
      rejected(await local.storeDataUrl(TRACK, 'review', fixtureUrl, '../escape'), 400);
      rejected(await local.storeDataUrl(TRACK, 'bogus' as 'photo', fixtureUrl), 400);
    });
    await check('validation: malformed, noncanonical base64 and forbidden SVG', async () => {
      for (const value of [
        '', 'https://example.com/image.png', 'data:image/png;base64,',
        'data:image/png;base64,%%%%', 'data:image/png;base64,AAAA=A==',
        'data:image/png;base64,A', 'data:image/png;base64,AB==',
        'data:image/png;base64,YQ==\n',
        dataUrl(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg"/>'), 'svg+xml'),
        dataUrl(Buffer.from('not a decodable image')),
      ]) rejected(await local.storeDataUrl(TRACK, 'photo', value), 400);
    });
    await check('validation: actual type must match declared MIME, SVG cannot pose as PNG', async () => {
      rejected(await local.storeDataUrl(TRACK, 'photo', dataUrl(fixture, 'jpeg')), 400);
      rejected(await local.storeDataUrl(TRACK, 'photo', dataUrl(Buffer.from('<svg xmlns="http://www.w3.org/2000/svg" width="4" height="4"/>'))), 400);
      rejected(await local.storeDataUrl(TRACK, 'photo', dataUrl(fixture.subarray(0, Math.floor(fixture.length / 2)))), 400);
    });
    await check('validation: oversized base64 rejected before decoding; decoded byte ceiling enforced', async () => {
      const maxEncoded = 4 * Math.ceil(MAX_BYTES / 3);
      rejected(await local.storeDataUrl(TRACK, 'photo', 'data:image/png;base64,' + 'A'.repeat(maxEncoded + 4)), 413);
      // Same encoded length as an exactly-at-limit payload, but one byte too big.
      rejected(await local.storeDataUrl(TRACK, 'photo', dataUrl(Buffer.alloc(MAX_BYTES + 1))), 413);
    });
    await check('validation: compressed images exceeding 40 million pixels rejected', async () => {
      const huge = await sharp({ create: { width: 6400, height: 6400, channels: 3, background: '#fff' } }).png().toBuffer();
      assert.ok(huge.length < MAX_BYTES);
      rejected(await local.storeDataUrl(TRACK, 'photo', dataUrl(huge)), 400);
    });
    await check('local: strip EXIF/ICC metadata, retain format and original dimensions', async () => {
      const original = await sharp(fixture).jpeg().withMetadata({
        exif: { IFD0: { Copyright: 'Private owner information' } },
      }).toBuffer();
      assert.ok((await sharp(original).metadata()).exif);
      const url = saved(await local.storeDataUrl(TRACK, 'photo', dataUrl(original, 'jpeg')));
      assert.ok(url.endsWith('.jpg'));
      const metadata = await sharp(await fs.readFile(localPath(url))).metadata();
      assert.equal(metadata.format, 'jpeg');
      assert.equal(metadata.width, 16);
      assert.equal(metadata.height, 12);
      assert.equal(metadata.exif, undefined);
      assert.equal(metadata.icc, undefined);
    });
    await check('local: PNG/JPG/JPEG/WebP/GIF/AVIF preserved without conversion or resize', async () => {
      for (const format of ['png', 'jpeg', 'webp', 'gif', 'avif'] as const) {
        const input = await sharp(fixture).toFormat(format).toBuffer();
        const url = saved(await local.storeDataUrl(TRACK, 'photo', dataUrl(input, format)));
        assert.ok(url.endsWith(format === 'jpeg' ? '.jpg' : `.${format}`));
        const result = await sharp(await fs.readFile(localPath(url))).metadata();
        assert.equal(result.format, format === 'avif' ? 'heif' : format);
        assert.equal(result.width, 16);
        assert.equal(result.height, 12);
        if (format === 'jpeg') saved(await local.storeDataUrl(TRACK, 'photo', dataUrl(input, 'jpg')));
      }
    });
    await check('local: animated GIF/WebP frame count and delays survive re-encoding', async () => {
      const pixels = Buffer.from([255, 0, 0, 0, 255, 0]);
      for (const format of ['gif', 'webp'] as const) {
        const input = await sharp(pixels, { raw: { width: 1, height: 2, channels: 3, pageHeight: 1 } })
          .toFormat(format, { delay: [100, 200], loop: 0 }).toBuffer();
        const before = await sharp(input, { animated: true }).metadata();
        assert.equal(before.pages, 2);
        const url = saved(await local.storeDataUrl(TRACK, 'photo', dataUrl(input, format)));
        const after = await sharp(await fs.readFile(localPath(url)), { animated: true }).metadata();
        assert.equal(after.format, format);
        assert.equal(after.pages, before.pages);
        assert.equal(after.pageHeight, before.pageHeight);
        assert.deepEqual(after.delay, before.delay);
        assert.equal(after.loop, before.loop);
      }
    });
    await check('local: legacy flat generated files remain deletable; seed assets do not', async () => {
      const legacy = 'cedar-ridge-mx-banner-abc123ef.jpg';
      await fs.writeFile(path.join(settings.uploads.dir, legacy), fixture);
      await local.removeUploadedFile(`/api/uploads/${legacy}`);
      await assert.rejects(fs.access(path.join(settings.uploads.dir, legacy)), { code: 'ENOENT' });
      await fs.writeFile(path.join(settings.uploads.dir, 'seed-banner.jpg'), fixture);
      await local.removeUploadedFile('/api/uploads/seed-banner.jpg');
      await fs.access(path.join(settings.uploads.dir, 'seed-banner.jpg'));
    });
    await check('ownership: external URLs, seed assets, bare keys and traversal are not deleted', async () => {
      const url = saved(await local.storeDataUrl(TRACK, 'photo', fixtureUrl));
      const key = url.slice('/api/uploads/'.length);
      const before = commands.length;
      for (const reference of [
        `https://example.com${url}`, `//example.com${url}`, key, '/images/seed.jpg',
        `/api/uploads/../${key}`, `/api/uploads/%2e%2e/${key}`, `/api/uploads/${key}?x=1`,
        `/api/uploads/${key}#fragment`, `/api/uploads/${key.replaceAll('/', '\\')}`,
        `/api/uploads/${key.replace('tracks/', 'tracks//')}`, '/api/uploads/', '/api/media/',
        `https://motopass-media-dev.nyc3.digitaloceanspaces.com/${key}`,
      ]) {
        await local.removeUploadedFile(reference);
        await remote.removeUploadedFile(reference);
      }
      await fs.access(localPath(url));
      assert.equal(commands.length, before);
    });
    await check('local: symlinked directories cannot escape the configured uploads root', async () => {
      const otherTrack = randomUUID();
      const outside = path.join(root, 'private');
      const name = `${randomUUID()}.png`;
      await fs.mkdir(path.join(outside, 'gallery'), { recursive: true });
      await fs.writeFile(path.join(outside, 'gallery', name), fixture);
      await fs.symlink(outside, path.join(settings.uploads.dir, 'tracks', otherTrack));
      const reference = `/api/uploads/tracks/${otherTrack}/gallery/${name}`;
      await assert.rejects(local.deleteManagedFile(reference), /Unsafe media directory/);
      await local.removeUploadedFile(reference); // Best effort must not throw.
      await fs.access(path.join(outside, 'gallery', name));
      rejected(await local.storeDataUrl(otherTrack, 'photo', fixtureUrl), 503);
    });
    await check('Spaces MOCKED: immutable PutObject payload and stable relative DB reference', async () => {
      remoteUrl = saved(await remote.storeDataUrl(TRACK, 'photo', fixtureUrl));
      assert.ok(remoteUrl.startsWith(`/api/media/tracks/${TRACK}/gallery/`));
      assert.ok(!remoteUrl.includes('digitaloceanspaces'));
      const command = commands.at(-1);
      assert.ok(command instanceof PutObjectCommand);
      assert.equal(command.input.Bucket, 'motopass-media-dev');
      assert.equal(command.input.Key, remoteUrl.slice('/api/media/'.length));
      assert.equal(command.input.ACL, 'public-read');
      assert.equal(command.input.ContentType, 'image/png');
      assert.equal(command.input.CacheControl, 'public, max-age=86400');
      assert.ok(Buffer.isBuffer(command.input.Body));
      assert.equal((await sharp(command.input.Body as Buffer).metadata()).format, 'png');
      const count = commands.length;
      const next = saved(await remote.storeDataUrl(TRACK, 'photo', fixtureUrl));
      assert.notEqual(next, remoteUrl);
      assert.equal(commands.length, count + 1); // No DeleteObject/prefix/list operation.
      assert.ok(commands.at(-1) instanceof PutObjectCommand);
    });
    await check('Spaces MOCKED: exact DeleteObject payload, no deletion of pasted CDN URLs', async () => {
      const count = commands.length;
      await remote.removeUploadedFile(remote.resolveMediaUrl(remoteUrl)!);
      assert.equal(commands.length, count);
      await remote.removeUploadedFile(remoteUrl);
      assert.equal(commands.length, count + 1);
      const command = commands.at(-1);
      assert.ok(command instanceof DeleteObjectCommand);
      assert.deepEqual(command.input, { Bucket: 'motopass-media-dev', Key: remoteUrl.slice('/api/media/'.length) });
    });
    await check('Spaces MOCKED: stable references survive public base/CDN remapping', async () => {
      const key = remoteUrl.slice('/api/media/'.length);
      assert.equal(remote.resolveMediaUrl(key), `https://motopass-media-dev.nyc3.digitaloceanspaces.com/${key}`);
      assert.equal(remote.resolveMediaUrl(remoteUrl), remote.resolveMediaUrl(key));
      const remapped = new MediaStore(s3Settings('https://cdn.example.com/media/'), { s3: fakeS3, logger });
      assert.equal(remapped.resolveMediaUrl(remoteUrl), `https://cdn.example.com/media/${key}`);
      for (const invalid of ['../private', key + '?x=1', '/api/media/../' + key, '/api/media/%2f' + key,
        'https://cdn.example.com/' + key, '/api/uploads/' + key, key.replace('/gallery/', '/secret/')]) {
        assert.equal(remapped.resolveMediaUrl(invalid), null);
      }
      assert.equal(local.resolveMediaUrl(key), null);
      const bucketOnly = { ...settings, spaces: { ...settings.spaces, bucket: 'test-bucket' } };
      assert.equal(new MediaStore(bucketOnly).resolveMediaUrl(key), null);
      const baseOnly = { ...settings, spaces: { ...settings.spaces, publicBase: 'https://cdn.example.com' } };
      assert.equal(new MediaStore(baseOnly).resolveMediaUrl(key), null);
    });
    await check('Spaces MOCKED: missing credentials/settings fail closed, no local fallback', async () => {
      for (const field of ['region', 'bucket', 'publicBase', 'key', 'secret'] as const) {
        const bad = s3Settings();
        bad.spaces[field] = '';
        assert.throws(() => new MediaStore(bad, { s3: fakeS3, logger }), /Spaces media storage requires/);
      }
      for (const publicBase of ['http://cdn.example.com', 'https://user:secret@example.com',
        'https://cdn.example.com/?secret=1', 'javascript:alert(1)', 'not-a-url']) {
        const bad = s3Settings(publicBase);
        assert.throws(() => new MediaStore(bad, { s3: fakeS3, logger }), /Spaces media storage requires/);
      }
    });
    await check('Spaces MOCKED: validation failures never send storage requests', async () => {
      const before = commands.length;
      rejected(await remote.storeDataUrl(TRACK, 'photo', dataUrl(fixture, 'gif')), 400);
      rejected(await remote.storeDataUrl('../escape', 'photo', fixtureUrl), 400);
      assert.equal(commands.length, before);
    });
    await check('Spaces MOCKED: upload errors sanitized, cleanup failures never escape', async () => {
      const failing = new MediaStore(s3Settings(), {
        s3: { async send() { throw new Error('MOCK-SECRET-DO-NOT-LOG signed https://private.example.com'); } }, logger,
      });
      rejected(await failing.storeDataUrl(TRACK, 'banner', fixtureUrl), 503);
      await assert.rejects(failing.deleteManagedFile(remoteUrl), /MOCK-SECRET/);
      await failing.removeUploadedFile(remoteUrl);
      const brokenLogger = new MediaStore(s3Settings(), {
        s3: { async send() { throw new Error('storage error'); } },
        logger: { warn() { throw new Error('logger error'); } },
      });
      await brokenLogger.removeUploadedFile(remoteUrl);
      assert.ok(warnings.some((warning) => warning === 'Media cleanup failed (spaces).'));
      assert.ok(warnings.every((warning) => !warning.includes('MOCK-SECRET') && !warning.includes('https:')));
    });
    console.log(`\n${passed} media storage checks passed. Local filesystem exercised; Spaces is MOCKED (no live bucket verification).`);
  } finally {
    await fs.rm(root, { recursive: true, force: true });
    if (!process.env.TMPDIR) await fs.rmdir(scratch).catch(() => undefined);
  }
}

main().catch((err) => { console.error(err); process.exitCode = 1; });

/* eslint-disable no-console */
import sharp from 'sharp';
/**
 * API checks for the track-owner console (localhost:4010).
 *
 * The profile page and the console UI are covered by `client/scripts/verify-profile.cjs`.
 * What that cannot reach is the ownership model underneath, which is the part
 * worth pinning: who may write a venue's profile, and that a WRITE is scoped to
 * the caller's own track rather than to whatever id the client sent.
 *
 * Runs against the seeded demo DB and leaves it as it found it (it only edits
 * fields it puts back, and removes every event it adds).
 */
const BASE = 'http://localhost:4010/api';
const PASSWORD = 'dialed123';

let passCount = 0;
let failCount = 0;

function check(label: string, ok: boolean, detail = '') {
  if (ok) {
    passCount++;
    console.log(`  PASS  ${label}${detail ? ` — ${detail}` : ''}`);
  } else {
    failCount++;
    console.log(`  FAIL  ${label}${detail ? ` — ${detail}` : ''}`);
  }
}

class Client {
  cookie = '';
  async call<T = any>(path: string, method = 'GET', body?: unknown): Promise<{ status: number; json: T }> {
    const res = await fetch(`${BASE}${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        ...(this.cookie ? { Cookie: this.cookie } : {}),
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    for (const c of res.headers.getSetCookie?.() ?? []) {
      const [pair] = c.split(';');
      if (pair.startsWith('moto_sid=')) this.cookie = pair;
    }
    return { status: res.status, json: (await res.json()) as T };
  }
  get<T = any>(path: string) {
    return this.call<T>(path);
  }
  async login(email: string) {
    const r = await this.call('/auth/login', 'POST', { email, password: PASSWORD });
    if (!r.json.success) throw new Error(`login failed for ${email}: ${r.json.message}`);
  }
}

/** A real, complete PNG. The old 1x1 constant carried a valid header but broken
 *  pixel data, which the storage layer now correctly refuses. */
async function pngFixture(): Promise<string> {
  const bytes = await sharp({
    create: { width: 16, height: 12, channels: 3, background: '#ca4133' },
  }).png().toBuffer();
  return `data:image/png;base64,${bytes.toString('base64')}`;
}

async function main() {
  console.log('\n=== Moto Pass — track-owner console ===\n');
  const PNG = await pngFixture();

  const anon = new Client();
  const rider = new Client();
  const mx221Op = new Client();
  const eastBendOp = new Client();
  const admin = new Client();

  await rider.login('quinn@example.com');
  await mx221Op.login('ops@221mx.example.com');
  await eastBendOp.login('ops@eastbend.example.com');
  await admin.login('admin@motopass.example.com');

  // ---- Who may touch the console at all ---------------------------------
  const anonRead = await anon.get('/owner/track');
  check('anonymous cannot read the console', anonRead.status === 401, `HTTP ${anonRead.status}`);
  const riderRead = await rider.get('/owner/track');
  check('a rider cannot read the console', riderRead.status === 403, `HTTP ${riderRead.status}`);
  const riderWrite = await rider.call('/owner/track', 'PATCH', { hours: 'never' });
  check('a rider cannot write a profile', riderWrite.status === 403, `HTTP ${riderWrite.status}`);

  // ---- An operator resolves to its own pinned venue ---------------------
  const mine = await mx221Op.get('/owner/track');
  check('an operator reads its own venue', mine.json.data?.track?.slug === '221-mx', mine.json.data?.track?.slug);
  check(
    'the console payload carries the profile fields',
    ['bannerUrl', 'logoUrl', 'youtube', 'tiktok', 'email', 'phone'].every((k) => k in (mine.json.data?.track ?? {}))
  );

  // A rider's own pass terms are not in this payload — it is the owner's view.
  const riderProfile = await rider.get('/tracks/221-mx');
  check(
    'a free rider reads the profile without the pass terms',
    riderProfile.json.data?.track?.includedDays === null && riderProfile.json.data?.gated === true
  );

  // ---- A write is scoped to the caller's track, whatever id was sent -----
  const eastBendBefore = await eastBendOp.get('/owner/track');
  const eastBendId = eastBendBefore.json.data.track.id;
  const bx = await mx221Op.call('/owner/track', 'PATCH', {
    description: 'scoped write check',
    trackId: eastBendId,
  });
  check('the write succeeds', bx.json.success === true, bx.json.message);
  const eastBendAfter = await eastBendOp.get('/owner/track');
  check(
    'an operator cannot write another venue by naming its id',
    eastBendAfter.json.data.track.description !== 'scoped write check',
    eastBendAfter.json.data.track.description
  );
  check('the write landed on the caller’s own venue', bx.json.data.track.slug === '221-mx', bx.json.data.track.slug);

  // Put it back.
  await mx221Op.call('/owner/track', 'PATCH', { description: mine.json.data.track.description ?? '' });
  const restored = await mx221Op.get('/owner/track');
  check('the profile copy is back as seeded', restored.json.data.track.description === mine.json.data.track.description);

  // ---- An empty string clears a field; status never clears --------------
  await mx221Op.call('/owner/track', 'PATCH', { statusNote: 'clear me' });
  let now = await mx221Op.get('/owner/track');
  check('a status note can be set', now.json.data.track.statusNote === 'clear me');
  await mx221Op.call('/owner/track', 'PATCH', { statusNote: '' });
  now = await mx221Op.get('/owner/track');
  check('an empty status note clears to null', now.json.data.track.statusNote === null, String(now.json.data.track.statusNote));
  const badStatus = await mx221Op.call('/owner/track', 'PATCH', { status: 'MELTED' });
  check('an unknown status is refused', badStatus.status === 400, `HTTP ${badStatus.status}`);

  // ---- Asset upload -----------------------------------------------------
  const upload = await mx221Op.call('/owner/track/assets', 'POST', { kind: 'logo', dataUrl: PNG });
  const url: string = upload.json.data?.url ?? '';
  // Spaces installs commit a relative /api/media/<key>; local disk commits /api/uploads/<key>.
  check(
    'an image upload returns a managed reference',
    url.startsWith('/api/media/') || url.startsWith('/api/uploads/'),
    url || upload.json.message
  );
  const served = await fetch(`http://localhost:4010${url}`, { redirect: 'manual' });
  // A Spaces object answers a 302 to the bucket; a local file is served directly.
  check(
    'the uploaded image resolves',
    served.status === 200 || served.status === 302,
    `HTTP ${served.status}`
  );
  const notImage = await mx221Op.call('/owner/track/assets', 'POST', { kind: 'logo', dataUrl: 'data:text/plain;base64,aGk=' });
  check('a non-image upload is refused', notImage.status === 400, notImage.json.message);
  await mx221Op.call('/owner/track', 'PATCH', { logoUrl: '' });

  // ---- Gallery photos are scoped the same way ---------------------------
  const seeded = await mx221Op.get('/owner/track');
  const seededPhotos: { id: string; sortOrder: number }[] = seeded.json.data?.track?.photos ?? [];
  check('the owner reads its own venue gallery', seededPhotos.length >= 5, `${seededPhotos.length} photos`);
  check(
    'the gallery comes back in the owner\u2019s order',
    seededPhotos.every((p, i) => p.sortOrder === i),
    seededPhotos.map((p) => p.sortOrder).join(',')
  );

  const anonPhoto = await anon.call('/owner/track/photos', 'POST', { url: '/tracks/221-mx.jpg' });
  check('an anonymous visitor cannot add a photo', anonPhoto.status === 401, `HTTP ${anonPhoto.status}`);
  const riderPhoto = await rider.call('/owner/track/photos', 'POST', { url: '/tracks/221-mx.jpg' });
  check('a rider cannot add a photo', riderPhoto.status === 403, `HTTP ${riderPhoto.status}`);

  const addedPhoto = await mx221Op.call('/owner/track/photos', 'POST', {
    url: '/tracks/photos/221-mx/01.jpg',
    category: 'RACE_DAY',
  });
  const photoId: string = addedPhoto.json.data?.photo?.id ?? '';
  check('an operator adds a photo', Boolean(photoId), addedPhoto.json.message);
  check(
    'a new photo lands at the end of the gallery',
    addedPhoto.json.data?.photo?.sortOrder === seededPhotos.length,
    String(addedPhoto.json.data?.photo?.sortOrder)
  );
  const badCategory = await mx221Op.call('/owner/track/photos', 'POST', { url: '/x.jpg', category: 'NOPE' });
  check('an unknown photo category is refused', badCategory.status === 400, `HTTP ${badCategory.status}`);

  const crossPhotoEdit = await eastBendOp.call(`/owner/track/photos/${photoId}`, 'PATCH', { caption: 'hijacked' });
  check('another operator cannot edit a photo', crossPhotoEdit.status === 404, `HTTP ${crossPhotoEdit.status}`);
  const crossPhotoDelete = await eastBendOp.call(`/owner/track/photos/${photoId}`, 'DELETE');
  check('another operator cannot delete a photo', crossPhotoDelete.status === 404, `HTTP ${crossPhotoDelete.status}`);

  const captioned = await mx221Op.call(`/owner/track/photos/${photoId}`, 'PATCH', {
    caption: 'Ownership check',
    category: 'FACILITY',
  });
  check(
    'the owner labels its own photo',
    captioned.json.data?.photo?.caption === 'Ownership check' && captioned.json.data?.photo?.category === 'FACILITY'
  );
  const clearedCaption = await mx221Op.call(`/owner/track/photos/${photoId}`, 'PATCH', { caption: '' });
  check('an empty caption clears to nothing', clearedCaption.json.data?.photo?.caption === null);

  const halfOrder = await mx221Op.call('/owner/track/photos/reorder', 'POST', {
    ids: [...seededPhotos.map((p) => p.id), photoId].reverse().slice(1),
  });
  check('a reorder must name the whole gallery', halfOrder.status === 400, `HTTP ${halfOrder.status}`);

  const reversed = [...seededPhotos.map((p) => p.id), photoId].reverse();
  const reordered = await mx221Op.call('/owner/track/photos/reorder', 'POST', { ids: reversed });
  check(
    'reordering rewrites the gallery order',
    (reordered.json.data?.photos ?? []).map((p: { id: string }) => p.id).join(',') === reversed.join(',')
  );
  const publicOrder = await anon.get('/tracks/221-mx');
  check(
    'the public page reads the gallery in that order',
    (publicOrder.json.data?.track?.photos ?? []).map((p: { id: string }) => p.id).join(',') === reversed.join(',')
  );
  const restoredOrder = await mx221Op.call('/owner/track/photos/reorder', 'POST', {
    ids: [...seededPhotos.map((p) => p.id), photoId],
  });
  check('the gallery order goes back', restoredOrder.json.success === true);

  const removedPhoto = await mx221Op.call(`/owner/track/photos/${photoId}`, 'DELETE');
  check('the owner removes its own photo', removedPhoto.json.success === true, removedPhoto.json.message);
  const publicAfterPhoto = await anon.get('/tracks/221-mx');
  check(
    'the removed photo is off the public page',
    (publicAfterPhoto.json.data?.track?.photos ?? []).length === seededPhotos.length
  );

  // ---- Events are scoped the same way ----------------------------------
  const addRes = await mx221Op.call('/owner/track/events', 'POST', { title: 'Ownership check', startsAt: '2030-01-05' });
  const eventId: string = addRes.json.data?.event?.id ?? '';
  check('an operator adds an event', Boolean(eventId), addRes.json.message);
  check(
    'a bare date is stored once, at noon UTC',
    (addRes.json.data?.event?.startsAt ?? '').includes('T12:00:00'),
    addRes.json.data?.event?.startsAt
  );

  const crossDelete = await eastBendOp.call(`/owner/track/events/${eventId}`, 'DELETE');
  check('another operator cannot delete it', crossDelete.status === 404, `HTTP ${crossDelete.status}`);
  const crossEdit = await eastBendOp.call(`/owner/track/events/${eventId}`, 'PATCH', { title: 'hijacked' });
  check('another operator cannot edit it', crossEdit.status === 404, `HTTP ${crossEdit.status}`);

  const badOrder = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startsAt: '2030-03-01',
    endsAt: '2030-02-01',
  });
  check('an event cannot end before it starts', badOrder.status === 400, badOrder.json.message);

  // ---- The hours a date runs -------------------------------------------
  // Hours travel as minutes past midnight and are written as a pair, so a date
  // is timed or all-day — the owner's week grid draws one or the other.
  const timed = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: 540,
    endMinutes: 960,
  });
  check(
    'a date can be given its own hours',
    timed.json.success === true &&
      timed.json.data.event.startMinutes === 540 &&
      timed.json.data.event.endMinutes === 960,
    JSON.stringify([timed.json.data?.event?.startMinutes, timed.json.data?.event?.endMinutes])
  );
  const publicTimed = await fetch(`${BASE}/tracks/221-mx`).then((r) => r.json());
  const servedHours = (publicTimed.data.track.events ?? []).find((e: { id: string }) => e.id === eventId);
  check(
    'the hours reach the public profile',
    servedHours?.startMinutes === 540 && servedHours?.endMinutes === 960,
    JSON.stringify([servedHours?.startMinutes, servedHours?.endMinutes])
  );
  const crossedHours = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: 960,
    endMinutes: 540,
  });
  check('a date cannot end before it starts its own day', crossedHours.status === 400, crossedHours.json.message);
  const allDay = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', {
    startMinutes: null,
    endMinutes: null,
  });
  check(
    'clearing the pair makes it all-day',
    allDay.json.success === true && allDay.json.data.event.startMinutes === null && allDay.json.data.event.endMinutes === null,
    JSON.stringify([allDay.json.data?.event?.startMinutes, allDay.json.data?.event?.endMinutes])
  );

  const hidden = await mx221Op.call(`/owner/track/events/${eventId}`, 'PATCH', { isActive: false });
  check('an event can be hidden', hidden.json.success === true && hidden.json.data.event.isActive === false);
  const publicAfter = await fetch(`${BASE}/tracks/221-mx`).then((r) => r.json());
  check(
    'a hidden event is off the public profile',
    !(publicAfter.data.track.events ?? []).some((e: { id: string }) => e.id === eventId)
  );

  const removed = await mx221Op.call(`/owner/track/events/${eventId}`, 'DELETE');
  check('the owner removes its own event', removed.json.success === true, removed.json.message);

  // ---- Admin parity ----------------------------------------------------
  const adminNoTrack = await admin.get('/owner/track');
  check('an admin must name a venue', adminNoTrack.status === 400, `HTTP ${adminNoTrack.status}`);
  const adminPicks = await admin.get(`/owner/track?trackId=${eastBendId}`);
  check('an admin can open any venue', adminPicks.json.data?.track?.slug === 'east-bend-motorsports', adminPicks.json.data?.track?.slug);

  // ---- Public read -----------------------------------------------------
  const list = await anon.get('/tracks');
  check(
    'the directory payload carries the new profile fields',
    (list.json.data.tracks ?? []).every((t: Record<string, unknown>) => 'bannerUrl' in t && 'logoUrl' in t && 'youtube' in t)
  );
  const missing = await anon.get('/tracks/nope-not-a-track');
  check('an unknown slug 404s', missing.status === 404, `HTTP ${missing.status}`);

  console.log(`\n=== ${passCount} passed, ${failCount} failed ===`);
  process.exit(failCount === 0 ? 0 : 1);
}

main().catch((e) => {
  console.error('harness error:', e);
  process.exit(1);
});

import express from 'express';
import fs from 'fs';
import path from 'path';
import helmet from 'helmet';
import cors from 'cors';
import compression from 'compression';
import morgan from 'morgan';
import cookieParser from 'cookie-parser';
import rateLimit from 'express-rate-limit';

import config from './config';
import { apiRoutes } from './routes';
import { attachUser } from './middleware/auth';
import { errorHandler } from './middleware/errorHandler';
import { stripeWebhook } from './controllers/payments.controller';
import { resolveMediaUrl } from './services/media.service';
import logger from './utils/logger';

export function createApp() {
  const app = express();

  app.set('trust proxy', 1);
  // Helmet's default CSP is img-src 'self' data:, which is correct for every
  // photo we ship but silently blanks the Leaflet basemap: the tiles come from
  // tile.openstreetmap.org, so the browser refuses them and the map renders as
  // an empty dark surface with only its zoom controls and attribution. Keep the
  // defaults and widen img-src for the tile hosts (and blob:, which the client
  // uses for local image previews).
  app.use(
    helmet({
      crossOriginResourcePolicy: false,
      contentSecurityPolicy: {
        directives: {
          ...helmet.contentSecurityPolicy.getDefaultDirectives(),
          'img-src': [
            "'self'",
            'data:',
            'blob:',
            'https://tile.openstreetmap.org',
            'https://*.tile.openstreetmap.org',
            ...(config.spaces.publicBase ? [new URL(config.spaces.publicBase).origin] : []),
          ],
        },
      },
    })
  );
  app.use(cors({ origin: config.corsOrigin, credentials: true }));
  app.use(compression());
  if (!config.isProd) app.use(morgan('dev'));

  // Stripe webhook MUST get the raw body for signature verification —
  // register it before the JSON body parser.
  app.post(
    '/api/payments/webhook',
    express.raw({ type: 'application/json' }),
    stripeWebhook
  );

  // Upload parsers must precede the general parser or its 1 MB ceiling wins.
  app.use('/api/owner/track/assets', express.json({ limit: '8mb' }));
  app.use('/api/owner/track/photos', express.json({ limit: '8mb' }));
  app.use('/api/auth/me/avatar', express.json({ limit: '8mb' }));
  // Six 5 MB photos plus base64 expansion and JSON overhead fit in 42 MB.
  app.use('/api/me/track-reviews', express.json({ limit: '42mb' }));
  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ extended: true }));
  app.use(cookieParser());

  // Banner/logo files the owner console writes. Mounted under /api so the dev
  // proxy (and the tailnet origin) reach them without a second origin.
  fs.mkdirSync(config.uploads.dir, { recursive: true });
  app.use(config.uploads.publicPath, express.static(config.uploads.dir, { maxAge: '1h' }));

  // Keep bucket/CDN addresses out of stored records. Never cache the redirect,
  // so changing PUBLIC_BASE takes effect without rewriting database URLs.
  app.get('/api/media/*', (req, res) => {
    const key = String((req.params as Record<string, unknown>)[0] ?? '');
    const url = resolveMediaUrl(key);
    if (!url) return res.status(404).json({ success: false, message: 'Image not found.' });
    res.set('Cache-Control', 'no-store');
    res.redirect(302, url);
  });

  app.use(
    '/api',
    rateLimit({
      windowMs: 60_000,
      limit: 300,
      standardHeaders: true,
      legacyHeaders: false,
      // Never throttle the QR scan endpoint — operators need instant feedback.
      skip: (req) => req.path.startsWith('/operator/scan'),
    })
  );

  app.use(attachUser);
  app.use('/api', apiRoutes);

  // Production serves the built SPA from the same origin as /api, so cookies
  // and the relative fetch('/api') in client/src/lib/api.ts work with no CORS and
  // no second host. Dev keeps using the Vite server on :5180.
  if (config.isProd) {
    const dist = path.resolve(__dirname, '../../client/dist');
    // redirect: false keeps the photo folders in dist/tracks from answering the
    // client route /tracks with a 301 to a trailing slash.
    app.use(express.static(dist, { index: false, redirect: false, maxAge: '1h' }));
    // A build's hashed files are the one thing that must never fall back to the
    // shell. After a deploy the previous hashes are gone, and answering a missing
    // /assets/* read with index.html (200, text/html) makes the browser refuse the
    // module on MIME grounds and paint a blank page instead of saying what broke.
    // A 404 here is honest, and the reload that follows gets the new build.
    app.get(/^\/assets\//, (_req, res) => {
      res.status(404).type('text/plain').send('Asset not found.');
    });
    // Every other non-/api GET falls back to index.html so client routes deep-link.
    app.get(/^\/(?!api\/).*/, (_req, res) => res.sendFile(path.join(dist, 'index.html')));
  }

  app.use((_req, res) => {
    res.status(404).json({ success: false, message: 'Not found.' });
  });

  app.use(errorHandler);

  logger.info(`CORS origin: ${config.corsOrigin}`);
  return app;
}

import dotenv from 'dotenv';
import path from 'path';

dotenv.config({ path: path.resolve(__dirname, '../../.env') });

const num = (v: string | undefined, fallback: number) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

/** An ISO timestamp, or null. A malformed value is treated as unset rather
    than as `Invalid Date`, so a typo opens the site instead of closing it. */
const dateOrNull = (v: string | undefined) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d;
};

const mediaProvider = process.env.MEDIA_STORAGE || 'local';
if (mediaProvider !== 'local' && mediaProvider !== 'spaces') {
  throw new Error('MEDIA_STORAGE must be local or spaces.');
}
// Production never inherits the development bucket, URL or credentials.
const spacesPrefix = process.env.NODE_ENV === 'production' ? 'SPACES_PROD' : 'SPACES_DEV';

export const config = {
  env: process.env.NODE_ENV || 'development',
  isProd: process.env.NODE_ENV === 'production',
  // The dev simulator completes a purchase without a Stripe account. It is
  // sealed in production by default so a live deployment cannot hand out paid
  // passes; a demo deployment that has no Stripe key opts back in with
  // ALLOW_DEV_SIMULATE=true, because its paid CTA still starts a checkout.
  allowDevSimulate:
    process.env.NODE_ENV !== 'production' || process.env.ALLOW_DEV_SIMULATE === 'true',
  // Loopback by default: the app is published to the tailnet via `tailscale
  // serve`, never by binding a LAN-reachable interface.
  host: process.env.HOST || '127.0.0.1',
  port: num(process.env.PORT, 4010),
  corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:5180',
  // Where Stripe sends the browser back after paying. Separate from CORS_ORIGIN
  // on purpose: the API is reached same-origin through the web server's /api
  // proxy, so CORS must stay the dev origin while a checkout opened over the
  // tailnet (or a deployed host) still returns to the host the rider is on.
  // CHECKOUT_ORIGIN takes a comma-separated list; the request's own Origin wins
  // when it is one of these.
  checkoutOrigin:
    process.env.CHECKOUT_ORIGIN || process.env.CORS_ORIGIN || 'http://localhost:5180',
  checkoutOrigins: [
    process.env.CORS_ORIGIN || 'http://localhost:5180',
    ...(process.env.CHECKOUT_ORIGIN || '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean),
  ],

  session: {
    secret: process.env.SESSION_SECRET || 'dev_session_secret_change_me',
    ttlDays: num(process.env.SESSION_TTL_DAYS, 30),
    cookieName: 'moto_sid',
  },

  qr: {
    signingSecret: process.env.QR_SIGNING_SECRET || 'dev_qr_signing_secret_change_me',
    ttlSeconds: num(process.env.QR_TOKEN_TTL_SECONDS, 60),
  },

  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY || '',
    webhookSecret: process.env.STRIPE_WEBHOOK_SECRET || '',
    priceIds: {
      base: process.env.STRIPE_BASE_PRICE_ID || '',
      pro: process.env.STRIPE_PRO_PRICE_ID || '',
    },
    enabled: Boolean(process.env.STRIPE_SECRET_KEY && !process.env.STRIPE_SECRET_KEY.includes('placeholder')),
  },

  seedDefaultPassword: process.env.SEED_DEFAULT_PASSWORD || 'dialed123',

  // ---- Launch window ----
  // The site opens in two phases: a presale, then the full network. Both ends
  // are timestamps, not a "days since launch" count, so the date is one value
  // to move. Unset `presaleEndsAt` means the presale is not armed at all: the
  // phase is OPEN and nothing gates, which is what dev, the suites and an
  // unconfigured deploy run on. `presaleStartsAt` is optional; unset means the
  // window is already open. The window is the server's own read — a client flag
  // cannot close or open the gate (see lib/launchPhase.ts).
  launch: {
    presaleStartsAt: dateOrNull(process.env.LAUNCH_PRESALE_STARTS_AT),
    presaleEndsAt: dateOrNull(process.env.LAUNCH_PRESALE_ENDS_AT),
  },

  // One active backend per process; environment-specific settings prevent dev/prod mixing.
  spaces: {
    provider: mediaProvider as 'local' | 'spaces',
    region: process.env.SPACES_REGION || 'nyc3',
    bucket: process.env[`${spacesPrefix}_BUCKET`] || '',
    publicBase: process.env[`${spacesPrefix}_PUBLIC_BASE`] || '',
    key: process.env[`${spacesPrefix}_KEY`] || '',
    secret: process.env[`${spacesPrefix}_SECRET`] || '',
  },

  // Legacy uploads and the explicit local-development backend remain served here.
  uploads: {
    dir: process.env.UPLOADS_DIR || path.resolve(__dirname, '../../uploads'),
    publicPath: '/api/uploads',
    // A single upload's decoded size ceiling.
    maxBytes: 5 * 1024 * 1024,
  },
};

export default config;

