export const adminListUsers = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const page = clampInt(req.query.page, 1, 1, 100_000);
    const limit = clampInt(req.query.limit, 25, 1, 200);
    const search = cleanLine(req.query.search, 120) || undefined;
    // A role is a closed vocabulary: an unknown one is refused, not ignored.
    const roleCheck = z.enum(ROLE_VALUES).safeParse(req.query.role);
    if (req.query.role !== undefined && !roleCheck.success) {
      return res.status(400).json(error(`role must be one of ${ROLE_VALUES.join(', ')}.`));
    }
    const role = roleCheck.success ? roleCheck.data : undefined;

    const where = {
      ...(role ? { role } : {}),
      ...(search
        ? {
            OR: [
              { name: { contains: search, mode: 'insensitive' as const } },
              { email: { contains: search, mode: 'insensitive' as const } },
            ],
          }
        : {}),
    };

    const [users, total] = await Promise.all([
      prisma.user.findMany({
        where,
        include: {
          passes: { orderBy: { seasonYear: 'desc' }, take: 1, include: { tier: true } },
          operatorTrack: { select: { id: true, name: true } },
        },
        orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      prisma.user.count({ where }),
    ]);

    res.json(
      paginated(
        users.map((u) => ({
          id: u.id,
          name: u.name,
          email: u.email,
          role: u.role,
          isActive: u.isActive,
          operatorTrack: u.operatorTrack,
          latestPass: u.passes[0]
            ? {
                id: u.passes[0].id,
                status: u.passes[0].status,
                seasonYear: u.passes[0].seasonYear,
                tierName: u.passes[0].tier.name,
                expiresAt: u.passes[0].expiresAt,
              }
            : null,
        })),
        total,
        page,
        limit
      )
    );
  } catch (err) {
    next(err);
  }
};

export const adminCreateUser = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z
      .object({
        name: zName(2, 80),
        email: zAccountEmail(),
        password: zPassword(8),
        role: z.enum(ROLE_VALUES).optional(),
        operatorTrackId: z.string().uuid().nullable().optional(),
      })
      .parse(req.body);
    const { hashPassword } = await import('../utils/password');
    const user = await prisma.user.create({
      data: {
        name: body.name,
        email: body.email,
        passwordHash: await hashPassword(body.password),
        role: body.role ?? Role.RIDER,
        operatorTrackId: body.operatorTrackId ?? null,
        // An admin creates the account and sets the password, so there is no
        // inbox round trip to run: it is usable at once.
        emailVerifiedAt: new Date(),
      },
    });
    res.status(201).json(success({ user: { id: user.id, email: user.email, role: user.role } }, 'User created.'));
  } catch (err) {
    next(err);
  }
};

