import crypto from 'crypto';
import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { PassStatus, Role } from '../types/enums';
import { prisma } from '../utils/prisma';
import { hashPassword, comparePassword } from '../utils/password';
import {
  createSession,
  destroySession,
  setSessionCookie,
  clearSessionCookie,
} from '../services/session.service';
import { AuthRequest } from '../types';
import { success, error } from '../utils/apiResponse';
import config from '../config';
import { grantDefaultTier } from '../services/pass.service';
import { sendResetLink, findReset, resetIsUsable } from '../services/passwordReset.service';
import {
  sendVerificationLink,
  findVerification,
  verificationIsUsable,
  resendWaitMs,
  VERIFY_RESEND_GAP_MS,
} from '../services/emailVerification.service';
import { normalizePhone } from '../utils/lookupInput';
import { storeDataUrl } from '../services/media.service';
import { cleanupOrphanedMedia } from '../services/mediaCleanup.service';
import { mustConfirmEmail } from '../lib/verificationCutoff';
import { zAccountEmail, zDataImageUrl, zLine, zName, zPassword, zPhone, zUrl } from '../utils/sanitize';
import logger from '../utils/logger';

/**
 * Run a job that issues a link and mails it.
 *
 * Production: the reply does not wait. A known address and an unknown one then
 * answer in the same time (an awaited provider call would make the forgot and
 * resend routes an account oracle by timing), and a slow provider never holds
 * the request open. Failures are logged by the mail service and here.
 *
 * Off production: awaited, because the reply carries the link as `devLink`.
 */
async function dispatchLink(
  job: () => Promise<{ link: string }>,
  label: string
): Promise<{ devLink?: string }> {
  if (!config.isProd) return { devLink: (await job()).link };
  job().catch((err) => logger.error(`[mail] ${label} job failed: ${(err as Error).message}`));
  return {};
}

export const registerSchema = z.object({
  name: zName(2, 80),
  email: zAccountEmail(),
  password: zPassword(8),
  phone: zPhone().optional(),
});

export const loginSchema = z.object({
  email: zAccountEmail(),
  password: z.string().min(1, 'Password is required').max(200),
});

function publicUser(u: {
  id: string;
  name: string;
  email: string;
  role: string;
  location: string | null;
  avatarUrl: string | null;
  operatorTrackId: string | null;
  emailVerifiedAt?: Date | null;
}) {
  return {
    id: u.id,
    name: u.name,
    email: u.email,
    role: u.role as Role,
    location: u.location,
    avatarUrl: u.avatarUrl,
    operatorTrackId: u.operatorTrackId,
    emailVerified: Boolean(u.emailVerifiedAt),
  };
}

/**
 * Create the account, then mail the link that makes it a login.
 *
 * No session is set here on purpose: signing up is not signing in. The account
 * sits unverified until the rider opens the link, and `login` refuses it until
 * then, so a mistyped address cannot become a usable login.
 */
export const register = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { name, email, password, phone } = registerSchema.parse(req.body);
    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) return res.status(409).json(error('An account with that email already exists.'));

    const user = await prisma.user.create({
      data: {
        name,
        email,
        phone: normalizePhone(phone),
        passwordHash: await hashPassword(password),
        role: Role.RIDER,
      },
    });

    // Every new rider lands on the default (free) tier: the network, the track
    // statuses and the follows list — no included days and no member discount.
    await grantDefaultTier(user.id);

    const dev = await dispatchLink(
      () => sendVerificationLink({ id: user.id, email: user.email, name: user.name }),
      'signup link'
    );

    // Off production the link comes back in the response, so the flow can be
    // walked end to end on a box with no mail account — the same courtesy the
    // reset route pays.
    res.status(201).json(
      success(
        {
          user: publicUser(user),
          verificationSent: true,
          // The freshly mailed link starts this account's throttle window; the
          // client turns it into its resend countdown so the card's button does
          // not open on a click that would be silently dropped.
          cooldownMs: VERIFY_RESEND_GAP_MS,
          ...dev,
        },
        'Account created. Check your email to confirm the address.'
      )
    );
  } catch (err) {
    next(err);
  }
};

export const login = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { email, password } = loginSchema.parse(req.body);
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !user.isActive) {
      return res.status(401).json(error('Invalid email or password.'));
    }
    const ok = await comparePassword(password, user.passwordHash);
    if (!ok) return res.status(401).json(error('Invalid email or password.'));

    // The password is right but the address was never confirmed: the account is
    // not a login yet. `needsVerification` is what the client reads to send the
    // rider to the confirm-email step instead of a dead-end refusal.
    //
    // Accounts that predate the step are exempt — they were created while a
    // signup was a login and no link was ever mailed to them. The first sign-in
    // stamps them, so the exemption is a one-time read.
    if (mustConfirmEmail(user)) {
      return res.status(403).json({
        ...error('Confirm your email address before signing in.'),
        // `data` is where the client already reads; `needsVerification` is what
        // sends the rider to the confirm-email step instead of a dead end.
        data: { needsVerification: true, email: user.email },
      });
    }
    if (!user.emailVerifiedAt) {
      // Grandfathered account: record the exemption so the row matches the
      // account's state from here on.
      user.emailVerifiedAt = new Date();
      await prisma.user.update({
        where: { id: user.id },
        data: { emailVerifiedAt: user.emailVerifiedAt },
      });
    }

    const { token, expiresAt } = await createSession(user.id, {
      userAgent: req.headers['user-agent'],
      ip: req.ip,
    });
    setSessionCookie(res, token, expiresAt);
    res.json(success({ user: publicUser(user) }, 'Signed in.'));
  } catch (err) {
    next(err);
  }
};

export const logout = async (req: Request, res: Response, next: NextFunction) => {
  try {
    await destroySession(req.cookies?.[config.session.cookieName]);
    clearSessionCookie(res);
    res.json(success(null, 'Signed out.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Email verification
// ---------------------------------------------------------------------------

/** The same shape `resetPasswordSchema` enforces: one base64url-ish token. */
export const verifyEmailSchema = z.object({
  token: z.preprocess(
    (v) => String(v ?? '').trim(),
    z
      .string()
      .min(16, 'That confirmation link is not valid.')
      .max(128, 'That confirmation link is not valid.')
      .regex(/^[A-Za-z0-9_-]+$/, 'That confirmation link is not valid.')
  ),
});

export const resendVerificationSchema = z.object({
  email: zAccountEmail(),
});

const RESEND_COPY = 'Verification email sent';

/**
 * Spend a confirmation link: stamp the address as verified, retire every link on
 * the account, and sign the rider in. They proved control of the inbox and set
 * the password at sign-up, so the step finishes the signup rather than handing
 * them back a form.
 */
export const verifyEmail = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { token } = verifyEmailSchema.parse(req.body);
    const row = await findVerification(token);
    if (!row || !verificationIsUsable(row)) {
      return res
        .status(400)
        .json(error('That confirmation link has expired or was already used. Ask for a new one.'));
    }

    const verifiedAt = new Date();
    const [user] = await prisma.$transaction([
      prisma.user.update({
        where: { id: row.userId },
        data: { emailVerifiedAt: verifiedAt },
      }),
      prisma.emailVerification.update({ where: { id: row.id }, data: { usedAt: verifiedAt } }),
      // Every other outstanding link for this account dies with it.
      prisma.emailVerification.deleteMany({ where: { userId: row.userId, usedAt: null } }),
      prisma.auditLog.create({
        data: {
          actorId: row.userId,
          action: 'VERIFY_EMAIL',
          entity: 'User',
          entityId: row.userId,
        },
      }),
    ]);

    const { token: sessionToken, expiresAt } = await createSession(row.userId, {
      userAgent: req.headers['user-agent'],
      ip: req.ip,
    });
    setSessionCookie(res, sessionToken, expiresAt);
    res.json(success({ user: publicUser(user) }, 'Email confirmed. You are signed in.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Ask for a fresh link. The answer is the same whether or not the address is
 * waiting on a confirmation — an unechoed error would make this a way to read
 * which addresses have accounts.
 *
 * It is also the same when the account is inside its throttle window, so the
 * brakes (a gap between links, a daily ceiling, both per account) cannot be
 * read either. `cooldownMs` is a constant, not the remaining wait, for the same
 * reason: it tells the client how long to disable its button without saying
 * whether this address was recently mailed.
 */
export const resendVerification = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { email } = resendVerificationSchema.parse(req.body);
    const user = await prisma.user.findUnique({ where: { email } });
    // A verified account has nothing to confirm, and an unknown address has no
    // inbox to reach: both answer the same copy.
    if (!user || !user.isActive || user.emailVerifiedAt) {
      return res.json(success({ cooldownMs: VERIFY_RESEND_GAP_MS }, RESEND_COPY));
    }

    const waitMs = await resendWaitMs(user.id);
    if (waitMs > 0) return res.json(success({ cooldownMs: VERIFY_RESEND_GAP_MS }, RESEND_COPY));

    const dev = await dispatchLink(
      () => sendVerificationLink({ id: user.id, email: user.email, name: user.name }),
      'signup link resend'
    );
    res.json(success({ cooldownMs: VERIFY_RESEND_GAP_MS, ...dev }, RESEND_COPY));
  } catch (err) {
    next(err);
  }
};

export const me = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (!req.user) return res.json(success({ user: null }));
    const user = await prisma.user.findUnique({
      where: { id: req.user.id },
      include: { operatorTrack: true },
    });
    if (!user) return res.json(success({ user: null }));
    res.json(
      success({
        user: publicUser(user),
        operatorTrack: user.operatorTrack
          ? { id: user.operatorTrack.id, name: user.operatorTrack.name, slug: user.operatorTrack.slug }
          : null,
      })
    );
  } catch (err) {
    next(err);
  }
};

export const updateProfile = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const schema = z.object({
      name: zName(2, 80).optional(),
      phone: zPhone().optional(),
      location: zLine(80).optional(),
      avatarUrl: zUrl(300).optional(),
      password: zPassword(8).optional(),
      // Sent beside a new password by the profile's reset section: the account's
      // current password has to match before the hash is replaced.
      currentPassword: z.string().min(1).max(200).optional(),
    });
    const body = schema.parse(req.body);
    const data: Record<string, unknown> = {};
    if (body.name) data.name = body.name;
    if (body.phone !== undefined) data.phone = normalizePhone(body.phone);
    if (body.location !== undefined) data.location = body.location || null;
    if (body.avatarUrl !== undefined) data.avatarUrl = body.avatarUrl || null;
    if (body.password) {
      if (!body.currentPassword) {
        return res.status(400).json(error('Enter your current password.'));
      }
      const current = await prisma.user.findUnique({ where: { id: req.user!.id } });
      const matches =
        current ? await comparePassword(body.currentPassword, current.passwordHash) : false;
      if (!matches) return res.status(401).json(error('That password is not correct.'));
      data.passwordHash = await hashPassword(body.password);
    }

    const previous = body.avatarUrl !== undefined
      ? await prisma.user.findUnique({ where: { id: req.user!.id }, select: { avatarUrl: true } })
      : null;
    const user = await prisma.user.update({ where: { id: req.user!.id }, data });
    // A replaced or cleared avatar is retired only after the row holds the new
    // value, and only if no other account points at the same image.
    if (previous) await cleanupOrphanedMedia(previous.avatarUrl);
    res.json(success({ user: publicUser(user) }, 'Profile updated.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Rider profile photo.
 *
 * Same contract as every other upload: a data URL in the JSON body, a 5 MB
 * decoded ceiling, real bytes verified, and an immutable `users/<id>/avatar/`
 * key. The reply carries the managed reference the client keeps, which is what
 * `/auth/me` returns from then on. The previous file is removed only after the
 * new reference is committed.
 */
export const uploadAvatar = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ dataUrl: zDataImageUrl() }).parse(req.body);
    const saved = await storeDataUrl(req.user!.id, 'avatar', body.dataUrl);
    if ('status' in saved) return res.status(saved.status).json(error(saved.message));

    const previous = await prisma.user.findUnique({
      where: { id: req.user!.id },
      select: { avatarUrl: true },
    });
    const user = await prisma.user.update({
      where: { id: req.user!.id },
      data: { avatarUrl: saved.url },
    });
    await cleanupOrphanedMedia(previous?.avatarUrl);
    res.status(201).json(success({ url: saved.url, user: publicUser(user) }, 'Photo updated.'));
  } catch (err) {
    next(err);
  }
};

export const deleteAccountSchema = z.object({
  password: z.string().min(1, 'Password is required').max(200),
});

// ---------------------------------------------------------------------------
// Password reset
// ---------------------------------------------------------------------------

export const forgotPasswordSchema = z.object({
  email: zAccountEmail(),
});

export const resetPasswordSchema = z.object({
  token: z.preprocess(
    (v) => String(v ?? '').trim(),
    z
      .string()
      .min(16, 'That reset link is not valid.')
      .max(128, 'That reset link is not valid.')
      .regex(/^[A-Za-z0-9_-]+$/, 'That reset link is not valid.')
  ),
  password: zPassword(8),
});

/**
 * One live request per address per minute, kept in memory. The route also
 * carries an IP limiter; this one is per-target, so a shared IP cannot mail-bomb
 * one rider. A restart clears it, which is fine — it is a courtesy brake.
 */
const recentRequests = new Map<string, number>();
const REQUEST_GAP_MS = 60_000;

const FORGOT_COPY =
  'If that email has an account, a reset link is on its way. It expires in 30 minutes.';

/**
 * Ask for a reset link. The answer is the same whether or not the address has an
 * account — an unechoed error here would turn this route into an account oracle.
 */
export const forgotPassword = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { email } = forgotPasswordSchema.parse(req.body);
    const key = email.toLowerCase();
    const now = Date.now();
    const last = recentRequests.get(key);
    if (last && now - last < REQUEST_GAP_MS) {
      return res.json(success({}, FORGOT_COPY));
    }
    recentRequests.set(key, now);

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !user.isActive) return res.json(success({}, FORGOT_COPY));

    const dev = await dispatchLink(
      () => sendResetLink({ id: user.id, email: user.email, name: user.name }),
      'reset link'
    );

    // Off production the link comes back in the response, so the flow can be
    // walked end to end on a box with no mail account. Production answers with
    // the generic copy alone, before the mail goes out.
    res.json(success(dev, FORGOT_COPY));
  } catch (err) {
    next(err);
  }
};

/** Is this link still good? The reset page asks before drawing its fields. */
export const checkResetToken = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const token = typeof req.params.token === 'string' ? req.params.token : '';
    // Shape first: a token that is not one cannot match a hash, and there is no
    // reason to hand it to the database.
    const row = /^[A-Za-z0-9_-]{16,128}$/.test(token) ? await findReset(token) : null;
    if (!row || !resetIsUsable(row)) {
      return res.json(success({ valid: false }, 'This reset link has expired.'));
    }
    res.json(success({ valid: true, email: maskEmail(row.user.email) }, 'Link is valid.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Spend a reset link: set the new password, retire the token, and drop every
 * session on the account so whoever else was signed in is out.
 */
export const resetPassword = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const { token, password } = resetPasswordSchema.parse(req.body);
    const row = await findReset(token);
    if (!row || !resetIsUsable(row)) {
      return res
        .status(400)
        .json(error('That reset link has expired or was already used. Ask for a new one.'));
    }

    await prisma.$transaction([
      prisma.user.update({
        where: { id: row.userId },
        data: { passwordHash: await hashPassword(password) },
      }),
      prisma.passwordReset.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
      // Every other outstanding link for this account dies with it.
      prisma.passwordReset.deleteMany({ where: { userId: row.userId, usedAt: null } }),
      prisma.session.deleteMany({ where: { userId: row.userId } }),
      prisma.auditLog.create({
        data: {
          actorId: row.userId,
          action: 'RESET_PASSWORD',
          entity: 'User',
          entityId: row.userId,
        },
      }),
    ]);

    clearSessionCookie(res);
    res.json(success(null, 'Password updated. Sign in with the new one.'));
  } catch (err) {
    next(err);
  }
};

/** `riley@example.com` → `r•••@example.com` — enough to confirm whose link it is. */
function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!domain) return '•••';
  const head = local.slice(0, 1);
  return `${head}${'•'.repeat(Math.max(3, Math.min(local.length - 1, 8)))}@${domain}`;
}

/**
 * A rider closing their own account. The row stays so the pass, scan and
 * payment records that point at it still add up for the operator reports, but
 * every personal field is blanked, the sessions are dropped and the account is
 * switched off. The email is released, so the same address can register again.
 */
export const deleteAccount = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const { password } = deleteAccountSchema.parse(req.body);
    const user = await prisma.user.findUnique({ where: { id: req.user!.id } });
    if (!user) return res.status(404).json(error('Account not found.'));
    if (user.role !== Role.RIDER) {
      return res.status(403).json(error('Staff accounts cannot be deleted from here.'));
    }

    const ok = await comparePassword(password, user.passwordHash);
    if (!ok) return res.status(401).json(error('That password is not correct.'));

    const cancelledAt = new Date();
    await prisma.$transaction([
      prisma.user.update({
        where: { id: user.id },
        data: {
          isActive: false,
          name: 'Deleted rider',
          email: `deleted-${user.id}@deleted.invalid`,
          phone: null,
          location: null,
          avatarUrl: null,
          // Nothing should ever match this hash, so a stray login attempt fails
          // on the password as well as on the switched-off account.
          passwordHash: crypto.randomBytes(32).toString('hex'),
        },
      }),
      prisma.session.deleteMany({ where: { userId: user.id } }),
      prisma.trackFollow.deleteMany({ where: { userId: user.id } }),
      prisma.pass.updateMany({
        where: { userId: user.id, status: PassStatus.ACTIVE },
        data: { status: PassStatus.CANCELLED, cancelledAt },
      }),
      prisma.auditLog.create({
        data: { actorId: user.id, action: 'DELETE_ACCOUNT', entity: 'User', entityId: user.id },
      }),
    ]);

    clearSessionCookie(res);
    res.json(success(null, 'Account deleted.'));
  } catch (err) {
    next(err);
  }
};

import { Prisma } from '@prisma/client';
import { NextFunction, Response } from 'express';
import { z } from 'zod';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { Role } from '../types/enums';
import { storeDataUrl } from '../services/media.service';
import { cleanupOrphanedMedia } from '../services/mediaCleanup.service';
import { randomUUID } from 'crypto';
import { zDataImageUrl, zLine, zMultiline, zUuid } from '../utils/sanitize';

/**
 * Riders' reviews of a venue.
 *
 * The owner's gallery is the venue's curated art: ordered, categorised, 24 max.
 * A review is the other half of the same idea — a rider's considered account of
 * riding there: a body of text, a 1–5 rating, and up to six frames they shot.
 *
 * One review per rider per venue, enforced by the unique index and checked here
 * so the refusal reads as a sentence. A rider **edits** that same review after
 * the fact — the body, the rating, the frames — but cannot post a second one.
 * The venue may pull any review from its community page, an admin may pull any.
 *
 * Uploads reuse the owner console's store — a base64 data URL written into the
 * uploads dir and served back under /api/uploads — so there is one storage path
 * and one size ceiling for every image in the app.
 */

/** One review may carry this many frames. */
const MAX_PHOTOS = 6;
/** A review's body is an account, not an essay. */
const MAX_BODY = 2000;

/** A frame arrives as an image data URL, and nothing else does. */
const imageDataUrl = zDataImageUrl();

const createSchema = z.object({
  trackId: zUuid('Pick a track.'),
  rating: z.number().int().min(1).max(5),
  body: zMultiline(MAX_BODY),
  dataUrls: z.array(imageDataUrl).max(MAX_PHOTOS).optional(),
});

const updateSchema = z.object({
  rating: z.number().int().min(1).max(5).optional(),
  body: zMultiline(MAX_BODY).optional(),
});

const photoSchema = z.object({
  dataUrl: imageDataUrl,
  caption: zLine(140).optional(),
});

/** The shape both the public page and the community console read. */
export interface ReviewPhotoRead {
  id: string;
  url: string;
  caption: string | null;
}

export interface TrackReviewRead {
  id: string;
  rating: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  userId: string;
  riderName: string;
  riderAvatarUrl: string | null;
  photos: ReviewPhotoRead[];
}

/** The relation both reads use — newest review first, frames in the rider's order. */
export const reviewSelect = Prisma.validator<Prisma.TrackReviewSelect>()({
  id: true,
  rating: true,
  body: true,
  createdAt: true,
  updatedAt: true,
  userId: true,
  user: { select: { name: true, avatarUrl: true } },
  photos: {
    orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
    select: { id: true, url: true, caption: true },
  },
});

/** Flatten a joined review row into the read above. */
export function toTrackReviewRead(r: {
  id: string;
  rating: number;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  userId: string;
  user: { name: string; avatarUrl: string | null };
  photos: { id: string; url: string; caption: string | null }[];
}): TrackReviewRead {
  return {
    id: r.id,
    rating: r.rating,
    body: r.body,
    createdAt: r.createdAt,
    updatedAt: r.updatedAt,
    userId: r.userId,
    riderName: r.user.name,
    riderAvatarUrl: r.user.avatarUrl,
    photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
  };
}

/** Store a review batch, rolling back already uploaded frames if any write fails. */
async function storeAll(
  trackId: string,
  reviewId: string,
  dataUrls: string[]
): Promise<{ urls: string[] } | { status: number; message: string }> {
  const urls: string[] = [];
  try {
    for (const dataUrl of dataUrls) {
      const saved = await storeDataUrl(trackId, 'review', dataUrl, reviewId);
      if ('status' in saved) {
        for (const url of urls) await cleanupOrphanedMedia(url);
        return saved;
      }
      urls.push(saved.url);
    }
    return { urls };
  } catch (err) {
    for (const url of urls) await cleanupOrphanedMedia(url);
    throw err;
  }
}

/** Rider: every review this rider has written, newest first — the read behind
 *  the "My reviews" section on their own profile. The venue comes with each
 *  row so the list can name and link the track without a second request. */
export const myReviews = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const reviews = await prisma.trackReview.findMany({
      where: { userId: req.user!.id },
      orderBy: { createdAt: 'desc' },
      select: {
        ...reviewSelect,
        track: { select: { id: true, slug: true, name: true, city: true, region: true } },
      },
    });
    res.json(
      success({
        reviews: reviews.map((r) => ({ ...toTrackReviewRead(r), track: r.track })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: write the one review they are allowed on this venue. A second attempt
 *  is refused — the rider updates the review they already have. */
export const addReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  let uploadedUrls: string[] = [];
  try {
    const body = createSchema.parse(req.body);
    const track = await prisma.track.findUnique({
      where: { id: body.trackId },
      select: { id: true, slug: true, name: true, isActive: true },
    });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const mine = await prisma.trackReview.findUnique({
      where: { userId_trackId: { userId: req.user!.id, trackId: track.id } },
      select: { id: true },
    });
    if (mine) {
      return res
        .status(409)
        .json(error('You have already reviewed this track — update your review instead.'));
    }

    const dataUrls = body.dataUrls ?? [];
    const reviewId = randomUUID();
    const stored = await storeAll(track.id, reviewId, dataUrls);
    if ('status' in stored) return res.status(stored.status).json(error(stored.message));
    uploadedUrls = stored.urls;

    const review = await prisma.trackReview.create({
      data: {
        id: reviewId,
        trackId: track.id,
        userId: req.user!.id,
        rating: body.rating,
        body: body.body.trim(),
        photos: {
          create: stored.urls.map((url, i) => ({ url, sortOrder: i })),
        },
      },
      select: reviewSelect,
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackReview', entityId: review.id },
    });
    res.status(201).json(success({ review: toTrackReviewRead(review) }, 'Review posted.'));
  } catch (err) {
    for (const url of uploadedUrls) await cleanupOrphanedMedia(url);
    next(err);
  }
};

/** Rider: update the review they already wrote — its words and its stars. The
 *  frames are added and removed through their own routes below. */
export const updateOwnReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const body = updateSchema.parse(req.body);
    const mine = await prisma.trackReview.findFirst({
      where: { id, userId: req.user!.id },
      select: { id: true },
    });
    if (!mine) return res.status(404).json(error('Review not found.'));

    const review = await prisma.trackReview.update({
      where: { id: mine.id },
      data: {
        ...(body.rating !== undefined ? { rating: body.rating } : {}),
        ...(body.body !== undefined ? { body: body.body.trim() } : {}),
      },
      select: reviewSelect,
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'UPDATE', entity: 'TrackReview', entityId: review.id },
    });
    res.json(success({ review: toTrackReviewRead(review) }, 'Review updated.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: attach one more frame to their review. */
export const addReviewPhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const id = req.params.id as string;
    const body = photoSchema.parse(req.body);
    const mine = await prisma.trackReview.findFirst({
      where: { id, userId: req.user!.id },
      select: { id: true, trackId: true, _count: { select: { photos: true } } },
    });
    if (!mine) return res.status(404).json(error('Review not found.'));
    if (mine._count.photos >= MAX_PHOTOS) {
      return res
        .status(400)
        .json(error(`A review carries ${MAX_PHOTOS} photos — remove one first.`));
    }

    const saved = await storeDataUrl(mine.trackId, 'review', body.dataUrl, mine.id);
    if ('status' in saved) return res.status(saved.status).json(error(saved.message));

    const photo = await prisma.trackReviewPhoto.create({
      data: {
        reviewId: mine.id,
        url: saved.url,
        caption: body.caption?.trim() || null,
        sortOrder: mine._count.photos,
      },
      select: { id: true, url: true, caption: true },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackReviewPhoto', entityId: photo.id },
    });
    res.status(201).json(success({ photo }, 'Photo added to your review.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: take one frame off their own review. The review itself stays. */
export const deleteOwnReviewPhoto = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const reviewId = req.params.id as string;
    const photoId = req.params.photoId as string;
    const photo = await prisma.trackReviewPhoto.findFirst({
      where: { id: photoId, reviewId, review: { userId: req.user!.id } },
      select: { id: true, url: true },
    });
    if (!photo) return res.status(404).json(error('Photo not found.'));

    await prisma.trackReviewPhoto.delete({ where: { id: photo.id } });
    await cleanupOrphanedMedia(photo.url);
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'DELETE', entity: 'TrackReviewPhoto', entityId: photoId },
    });
    res.json(success({ id: photoId }, 'Photo removed from your review.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Venue: pull any review from its own community page.
 *
 * Resolves the venue the way the rest of the console does — an operator is
 * pinned to its track, an admin names one — so an operator cannot reach into
 * another venue's reviews by guessing an id. Every uploaded frame goes with it;
 * seeded frames are left alone (`removeUploadedFile` only touches /api/uploads).
 */
export const ownerDeleteReview = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const user = req.user!;
    const trackId =
      user.role === Role.ADMIN
        ? (req.query.trackId as string | undefined) ?? user.operatorTrackId ?? null
        : user.operatorTrackId ?? null;
    if (!trackId) return res.status(400).json(error('No track is pinned to this account.'));

    const id = req.params.id as string;
    const review = await prisma.trackReview.findFirst({
      where: { id, trackId },
      select: { id: true, photos: { select: { url: true } } },
    });
    if (!review) return res.status(404).json(error('Review not found.'));

    await prisma.trackReview.delete({ where: { id: review.id } });
    for (const p of review.photos) await cleanupOrphanedMedia(p.url);
    await prisma.auditLog.create({
      data: { actorId: user.id, action: 'DELETE', entity: 'TrackReview', entityId: id },
    });
    res.json(success({ id }, 'Review removed.'));
  } catch (err) {
    next(err);
  }
};

import { Response } from 'express';
import { AuthRequest } from '../types';
import { Role } from '../types/enums';
import { success } from '../utils/apiResponse';
import { gateIsOpenFor, launchWindow, setPreviewPhase } from '../lib/launchPhase';

/**
 * The public read of the launch window: which phase the site is in, when the
 * presale ends, and — for the caller asking — whether the gate is open to them.
 *
 * `gateOpen` is answered with the same rule the middleware applies, so the
 * client's nav and redirects follow the API instead of re-deriving permission
 * from a role name. It is the *only* thing the client is trusted with; the
 * gate itself is enforced on the gated reads, never here.
 */
export async function readLaunch(req: AuthRequest, res: Response) {
  const win = launchWindow();
  return res.json(
    success({
      phase: win.phase,
      presaleStartsAt: win.presaleStartsAt ? win.presaleStartsAt.toISOString() : null,
      presaleEndsAt: win.presaleEndsAt ? win.presaleEndsAt.toISOString() : null,
      gateOpen: await gateIsOpenFor(req.user),
    })
  );
}

/**
 * The preview switch's other half: put the *server* in the phase the client is
 * displaying, so the gate, `/launch` and the gated reads agree with what is on
 * screen. `{ phase: 'OPEN' }` opens the network for everyone, `{ phase:
 * 'PRESALE' }` closes it, `{ phase: null }` follows `LAUNCH_PRESALE_ENDS_AT`
 * again. The override is in memory (see `lib/launchPhase.ts`), so a restart
 * puts the configured window back.
 *
 * This opens a real gate, so it is not open to the public: production answers
 * only an ADMIN, unless `LAUNCH_ALLOW_PREVIEW=true` is set there deliberately.
 * Dev and the suites run with NODE_ENV unset, where the switch is the point.
 */
export async function setPreviewView(req: AuthRequest, res: Response) {
  const allowed =
    process.env.NODE_ENV !== 'production' ||
    process.env.LAUNCH_ALLOW_PREVIEW === 'true' ||
    req.user?.role === Role.ADMIN;
  if (!allowed) {
    return res.status(403).json({
      success: false,
      message: 'The preview switch is off in production.',
    });
  }

  const phase = req.body?.phase;
  if (phase !== null && phase !== undefined && phase !== 'PRESALE' && phase !== 'OPEN') {
    return res.status(400).json({ success: false, message: 'phase is PRESALE, OPEN or null.' });
  }

  setPreviewPhase(phase ?? null);
  return readLaunch(req, res);
}

import { NextFunction, Response } from 'express';
import { z } from 'zod';
import { randomUUID } from 'crypto';
import {
  PassStatus,
  TrackEventKind,
  TrackPhotoCategory,
  TrackStatus,
  Role,
  TRACK_EVENT_KIND_VALUES,
  TRACK_PHOTO_CATEGORY_VALUES,
} from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { storeDataUrl } from '../services/media.service';
import { cleanupOrphanedMedia } from '../services/mediaCleanup.service';
import { hoursWeekSchema } from '../lib/hoursWeek';
import {
  isDayString,
  uuidParam,
  zDataImageUrl,
  zDateish,
  zDay,
  zEmailOptional,
  zLine,
  zMultiline,
  zPhone,
  zUrl,
} from '../utils/sanitize';
import { dayKey, todayKey } from '../utils/dates';

/**
 * Track-owner console.
 *
 * The owner of a partner track is the OPERATOR account pinned to it
 * (`User.operatorTrackId`), so every handler resolves "my track" from the
 * session rather than trusting a track id from the client. An ADMIN may act on
 * any track by naming it (`?trackId=` on reads, `trackId` in the body on
 * writes) — the org console has no per-track profile editor of its own.
 *
 * What an owner may edit is cut deliberately: the profile copy and links, the
 * live status line, and the events. `name`, `slug`, `lat`/`lng`, `category` and
 * `isActive` stay admin-only — the slug is load-bearing across the seed and the
 * verify scripts.
 */

/** The track this caller is editing, or null when nothing is pinned and no id was given. */
function resolveTrackId(req: AuthRequest): string | null {
  const user = req.user!;
  if (user.role === Role.ADMIN) {
    const fromQuery = req.query.trackId ? uuidParam(req.query.trackId, 'trackId') : undefined;
    const fromBody = req.body?.trackId !== undefined ? uuidParam(req.body.trackId, 'trackId') : undefined;
    return fromQuery || fromBody || null;
  }
  return user.operatorTrackId ?? null;
}

async function loadOwnedTrack(req: AuthRequest, res: Response) {
  const trackId = resolveTrackId(req);
  if (!trackId) {
    res.status(400).json(error('No track is pinned to this account.'));
    return null;
  }
  const track = await prisma.track.findUnique({
    where: { id: trackId },
    include: {
      events: { orderBy: { startsAt: 'asc' } },
      dayStatuses: { orderBy: { day: 'asc' } },
      photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
      contracts: { include: { season: true }, orderBy: { season: { year: 'desc' } } },
    },
  });
  if (!track) {
    res.status(404).json(error('Track not found.'));
    return null;
  }
  return track;
}

/** The profile fields an owner (or an admin acting for them) may set. */
const profileSchema = z.object({
  description: zMultiline(2000).optional(),
  city: zLine(120).optional(),
  region: zLine(60).optional(),
  address: zLine(200).optional(),
  country: zLine(60).optional(),
  website: zUrl(600).optional(),
  instagram: zUrl(600).optional(),
  facebook: zUrl(600).optional(),
  youtube: zUrl(600).optional(),
  tiktok: zUrl(600).optional(),
  email: zEmailOptional(200).optional(),
  phone: zPhone(60).optional(),
  bannerUrl: zUrl(600).optional(),
  logoUrl: zUrl(600).optional(),
  imageUrl: zUrl(600).optional(),
  hours: zLine(200).optional(),
  /** The venue's week as JSON — `{"mon":"Practice 9am–4pm", …}`; '' clears it. */
  hoursWeek: hoursWeekSchema.optional(),
  status: z.enum(['OPEN', 'WEATHER_HOLD', 'CLOSED']).optional(),
  statusNote: zLine(200).optional(),
  /** The operator's own message to riders — read in the network panel. */
  riderMessage: zLine(500).optional(),
  nextEvent: zLine(200).optional(),
});

/** An empty string clears an optional text field; any other value is written as
    it was validated (the week's hours are an object, not text). */
function orNull<T>(v: T): T | null | undefined {
  if (v === undefined) return undefined;
  if (typeof v !== 'string') return v;
  return (v.trim() === '' ? null : v.trim()) as T;
}

export const ownerGetTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    res.json(success({ track }));
  } catch (err) {
    next(err);
  }
};

export const ownerUpdateTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const existing = await loadOwnedTrack(req, res);
    if (!existing) return;
    const body = profileSchema.parse(req.body);

    const data: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(body)) {
      if (value === undefined) continue;
      // status is a non-null enum; everything else clears to null on ''.
      data[key] = key === 'status' ? value : orNull(value);
    }

    const track = await prisma.track.update({
      where: { id: existing.id },
      data,
      include: {
        events: { orderBy: { startsAt: 'asc' } },
        dayStatuses: { orderBy: { day: 'asc' } },
        photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
      },
    });
    // Single-slot art is retired only after the new reference is committed.
    for (const field of ['bannerUrl', 'logoUrl', 'imageUrl'] as const) {
      if (body[field] !== undefined && existing[field] !== track[field]) {
        await cleanupOrphanedMedia(existing[field]);
      }
    }
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'UPDATE_PROFILE',
        entity: 'Track',
        entityId: track.id,
        meta: JSON.stringify(Object.keys(data)),
      },
    });
    res.json(success({ track }, 'Profile saved.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Day statuses — the gate per date
// ---------------------------------------------------------------------------

const dayStatusSchema = z.object({
  /** Bare day (`YYYY-MM-DD`) — lands at noon UTC so it never slips a date. */
  day: zDay(),
  status: z.enum(['OPEN', 'WEATHER_HOLD', 'CLOSED']),
  statusNote: zLine(200).optional(),
});

/**
 * One day's gate read: post caution for tomorrow, close for the weekend, or
 * mark today open. An upsert — a day holds one read, and posting it again
 * replaces it.
 *
 * When the day arrives its read becomes the venue's live line: the operator
 * posts tomorrow's gate today and the page flips itself overnight.
 */
export const ownerUpsertDayStatus = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = dayStatusSchema.parse(req.body);
    const day = toDate(body.day);
    const note = body.statusNote === undefined ? undefined : orNull(body.statusNote);

    const row = await prisma.trackDayStatus.upsert({
      where: { trackId_day: { trackId: track.id, day } },
      update: { status: body.status, ...(note !== undefined ? { statusNote: note } : {}) },
      create: { trackId: track.id, day, status: body.status, statusNote: note ?? null },
    });

    // A day that has arrived IS the gate: its read becomes the live line, so
    // the network page, the map and the venue profile flip with it. Compared
    // by calendar day — a row sits at noon UTC, midnight keys at 00:00.
    if (dayKey(day).getTime() <= todayKey().getTime()) {
      await prisma.track.update({
        where: { id: track.id },
        data: { status: body.status, ...(note !== undefined ? { statusNote: note } : {}) },
      });
    }
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'SET_DAY_STATUS',
        entity: 'TrackDayStatus',
        entityId: row.id,
        meta: JSON.stringify({ trackId: track.id, day: body.day, status: body.status }),
      },
    });
    res.status(201).json(success({ dayStatus: row }, 'Day status saved.'));
  } catch (err) {
    next(err);
  }
};

/** A day with no read follows the live line — clearing drops its row. */
export const ownerClearDayStatus = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const day = typeof req.query.day === 'string' ? req.query.day.trim() : '';
    if (!isDayString(day)) {
      return res.status(400).json(error('Pick a date.'));
    }
    await prisma.trackDayStatus.deleteMany({
      where: { trackId: track.id, day: toDate(day) },
    });
    await prisma.auditLog.create({
      data: {
        actorId: req.user!.id,
        action: 'CLEAR_DAY_STATUS',
        entity: 'TrackDayStatus',
        entityId: track.id,
        meta: JSON.stringify({ trackId: track.id, day }),
      },
    });
    res.json(success({ day }, 'Day status cleared.'));
  } catch (err) {
    next(err);
  }
};

// ---------------------------------------------------------------------------
// Events
// ---------------------------------------------------------------------------

const eventSchema = z.object({
  title: zLine(160, 2),
  description: zMultiline(1000).optional(),
  kind: z.enum(TRACK_EVENT_KIND_VALUES).default(TrackEventKind.PRACTICE),
  /** ISO date or datetime; a bare day lands at local noon so it never slips a date. */
  startsAt: zDateish(),
  endsAt: zDateish().optional().nullable(),
  /**
   * The hours a date runs, in minutes past midnight on that date's own day
   * (venue-local — no zone in the way). Both ends move together: a date is
   * either timed or all-day, never half of each.
   */
  startMinutes: z.number().int().min(0).max(1439).nullable().optional(),
  endMinutes: z.number().int().min(0).max(1439).nullable().optional(),
  isActive: z.boolean().optional(),
});

/**
 * A bare calendar day is stored at noon UTC. An event is a day, not an instant:
 * pinning it to midday keeps the stored date the same one whichever timezone
 * reads it back, so the console's date input round-trips exactly.
 */
function toDate(value: string) {
  const bare = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (bare) return new Date(Date.UTC(Number(bare[1]), Number(bare[2]) - 1, Number(bare[3]), 12));
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new Error(`Invalid date: ${value}`);
  return d;
}

/** An event cannot end before it starts — the console can otherwise leave the
 *  two date inputs crossed after a start date is moved forward. */
function orderError(startsAt: Date, endsAt: Date | null): string | null {
  return endsAt && endsAt.getTime() < startsAt.getTime()
    ? 'An event cannot end before it starts.'
    : null;
}

/**
 * The hours of a date are one choice, so they arrive together and are written
 * together: a single-day date that ends before it starts is refused, and a
 * multi-day run's hours belong to its first day, so the end is left alone.
 */
function hoursError(
  start: number | null,
  end: number | null,
  singleDay: boolean
): string | null {
  if (start === null || end === null) return null;
  if (!singleDay) return null;
  return end <= start ? 'A date cannot end before it starts.' : null;
}

/** The hours a write leaves behind, both ends or neither. */
function hoursOf(body: { startMinutes?: number | null; endMinutes?: number | null }) {
  if (body.startMinutes === null || body.endMinutes === null) {
    return { startMinutes: null, endMinutes: null };
  }
  return { startMinutes: body.startMinutes ?? null, endMinutes: body.endMinutes ?? null };
}

export const ownerCreateEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const body = eventSchema.parse(req.body);
    const startsAt = toDate(body.startsAt);
    const endsAt = body.endsAt ? toDate(body.endsAt) : null;
    const outOfOrder = orderError(startsAt, endsAt);
    if (outOfOrder) return res.status(400).json(error(outOfOrder));
    const hours = hoursOf(body);
    const badHours = hoursError(
      hours.startMinutes ?? null,
      hours.endMinutes ?? null,
      endsAt === null || endsAt.getTime() === startsAt.getTime()
    );
    if (badHours) return res.status(400).json(error(badHours));
    const event = await prisma.trackEvent.create({
      data: {
        trackId: track.id,
        title: body.title,
        description: body.description ?? null,
        kind: body.kind,
        startsAt,
        endsAt,
        ...hours,
        isActive: body.isActive ?? true,
      },
    });
    await prisma.auditLog.create({
      data: { actorId: req.user!.id, action: 'CREATE', entity: 'TrackEvent', entityId: event.id },
    });
    res.status(201).json(success({ event }, 'Event added.'));
  } catch (err) {
    next(err);
  }
};

export const ownerUpdateEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const track = await loadOwnedTrack(req, res);
    if (!track) return;
    const id = uuidParam(req.params.id, 'id');
    const existing = await prisma.trackEvent.findUnique({ where: { id } });
    if (!existing || existing.trackId !== track.id) {
      return res.status(404).json(error('Event not found.'));
    }
    const body = eventSchema.partial().parse(req.body);
    const nextStart = body.startsAt ? toDate(body.startsAt) : existing.startsAt;
    const nextEnd =
      body.endsAt !== undefined ? (body.endsAt ? toDate(body.endsAt) : null) : existing.endsAt;
    const outOfOrder = orderError(nextStart, nextEnd);
    if (outOfOrder) return res.status(400).json(error(outOfOrder));
    const nextHours = hoursOf({
      startMinutes: body.startMinutes !== undefined ? body.startMinutes : existing.startMinutes,
      endMinutes: body.endMinutes !== undefined ? body.endMinutes : existing.endMinutes,
    });
    const badHours = hoursError(
      nextHours.startMinutes ?? null,
      nextHours.endMinutes ?? null,
      nextEnd === null || nextEnd.getTime() === nextStart.getTime()
    );
    if (badHours) return res.status(400).json(error(badHours));
    const event = await prisma.trackEvent.update({
      where: { id },
      data: {
        ...(body.title !== undefined ? { title: body.title } : {}),
        ...(body.description !== undefined ? { description: body.description || null } : {}),
        ...(body.kind !== undefined ? { kind: body.kind } : {}),
        ...(body.startsAt ? { startsAt: nextStart } : {}),
        ...(body.endsAt !== undefined ? { endsAt: nextEnd } : {}),
        ...(body.startMinutes !== undefined || body.endMinutes !== undefined ? nextHours : {}),
        ...(body.isActive !== undefined ? { isActive: body.isActive } : {}),
      },
    });
    res.json(success({ event }, 'Event saved.'));
  } catch (err) {
    next(err);
  }
};

export const ownerDeleteEvent = async (req: AuthRequest, res: Response, next: NextFunction) => {
