// Followers
// ---------------------------------------------------------------------------

const DAY_MS = 864e5;

/**
 * The operator's audience: every account following the venue, the pass each one
 * holds, and how much it has actually ridden here.
 *
 * Following is the one thing a free account can do, so this list is the venue's
 * soft pipeline — riders watching the gate before they buy beside members who
 * are already through it every weekend. Read-only: a follow is the rider's to
 * give and to take, so there is no control here, only the read.
 *
 * The pass is picked the way `getCurrentPass` picks it (a paid active pass beats
 * the free default, then any active, then the latest), so a follower's badge
 * here agrees with the badge on their own profile.
 */
export const ownerFollowers = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId = resolveTrackId(req);
    if (!trackId) {
      return res.status(400).json(error('No track is pinned to this account.'));
    }
    const track = await prisma.track.findUnique({
      where: { id: trackId },
      select: { id: true, name: true, slug: true },
    });
    if (!track) return res.status(404).json(error('Track not found.'));

    const follows = await prisma.trackFollow.findMany({
      where: { trackId },
      include: {
        user: { select: { id: true, name: true, email: true, location: true, avatarUrl: true } },
      },
      orderBy: { createdAt: 'desc' },
    });
    const userIds = follows.map((f) => f.userId);

    // Two reads for the whole page rather than one per follower: every pass the
    // audience holds, and how many days each of them has ridden at this venue.
    const passes = userIds.length
      ? await prisma.pass.findMany({
          where: { userId: { in: userIds } },
          include: { tier: true },
          orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
        })
      : [];
    const rides = userIds.length
      ? await prisma.redemption.groupBy({
          by: ['userId'],
          where: { trackId, userId: { in: userIds } },
          _count: { _all: true },
          _max: { day: true },
        })
      : [];

    const passFor = (userId: string) => {
      const mine = passes.filter((p) => p.userId === userId);
      const active = mine.filter((p) => p.status === PassStatus.ACTIVE);
      const paid = active
        .filter((p) => !p.tier.isDefault)
        .sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0];
      return paid ?? active[0] ?? mine[0] ?? null;
    };

    const followers = follows.map((f) => {
      const pass = passFor(f.userId);
      const ride = rides.find((r) => r.userId === f.userId);
      return {
        id: f.id,
        userId: f.userId,
        name: f.user.name,
        email: f.user.email,
        location: f.user.location,
        avatarUrl: f.user.avatarUrl,
        followedAt: f.createdAt,
        tierName: pass?.tier.name ?? null,
        // Paying means an active pass that is not the free tier — a lapsed or
        // still-pending pass counts alongside a free account here.
        paid: Boolean(pass && pass.status === PassStatus.ACTIVE && !pass.tier.isDefault),
        passStatus: pass?.status ?? null,
        visits: ride?._count._all ?? 0,
        lastRideDay: ride?._max.day ?? null,
      };
    });

    // What the community has written about the venue. A third read for the whole
    // page: the riders' reviews, newest first, with who wrote each and the frames
    // they attached. One per rider, so this list is bounded by the audience.
    const reviews = await prisma.trackReview.findMany({
      where: { trackId },
      orderBy: { createdAt: 'desc' },
      select: {
        id: true,
        rating: true,
        body: true,
        createdAt: true,
        updatedAt: true,
        userId: true,
        user: { select: { name: true, avatarUrl: true } },
        photos: {
          orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
          select: { id: true, url: true, caption: true },
        },
      },
    });

    const since = new Date(Date.now() - 30 * DAY_MS);
    res.json(
      success({
        track,
        summary: {
          total: followers.length,
          newLast30: followers.filter((f) => f.followedAt >= since).length,
          paying: followers.filter((f) => f.paid).length,
          free: followers.filter((f) => !f.paid).length,
          riddenHere: followers.filter((f) => f.visits > 0).length,
          reviews: reviews.length,
        },
        followers,
        reviews: reviews.map((r) => ({
          id: r.id,
          rating: r.rating,
          body: r.body,
          createdAt: r.createdAt,
          updatedAt: r.updatedAt,
          userId: r.userId,
          riderName: r.user.name,
          riderAvatarUrl: r.user.avatarUrl,
          photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** The status values a profile may be set to — exported for the admin route's schema. */
export const TRACK_STATUS_VALUES = [TrackStatus.OPEN, TrackStatus.WEATHER_HOLD, TrackStatus.CLOSED] as const;

import { Response, NextFunction } from 'express';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { getCurrentPass, getEntitlements, grantDefaultTier } from '../services/pass.service';
import { issueQrToken } from '../utils/qr';
import { PassStatus, Role } from '../types/enums';
import { clampInt, uuidParam } from '../utils/sanitize';

/** Rider: current pass summary + expiry + tier. */
export const myPass = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const seasonYear = req.query.seasonYear
      ? clampInt(req.query.seasonYear, new Date().getUTCFullYear(), 2000, 2200)
      : undefined;
    const pass = await getCurrentPass(req.user!.id, seasonYear);
    if (!pass) return res.json(success({ pass: null, entitlements: [] }));

    const entitlements = await getEntitlements(req.user!.id, pass.id);
    res.json(
      success({
        pass: {
          id: pass.id,
          status: pass.status,
          seasonYear: pass.seasonYear,
          tier: {
            id: pass.tier.id,
            name: pass.tier.name,
            slug: pass.tier.slug,
            isDefault: pass.tier.isDefault,
          },
          /** True on the free tier: no included days, no member discount. */
          gated: pass.tier.isDefault,
          purchasedAt: pass.purchasedAt,
          activatedAt: pass.activatedAt,
          expiresAt: pass.expiresAt,
          daysUntilExpiry: Math.max(
            Math.ceil((pass.expiresAt.getTime() - Date.now()) / 86_400_000),
            0
          ),
        },
        entitlements,
      })
    );
  } catch (err) {
    next(err);
  }
};

/**
 * Rider: cancel a paid pass — the self-service unsubscribe.
 *
 * The pass is retired, not deleted: its ledger, receipts and redemptions stay
 * on the record, and the account falls back to the free pass because
 * `getCurrentPass` only counts ACTIVE passes and prefers a paid one. No Stripe
 * call is needed: checkout is a one-time payment (`mode: 'payment'`), so there
 * is no subscription to stop and nothing renews automatically.
 */
export const cancelPass = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const pass = await getCurrentPass(req.user!.id);
    if (!pass) return res.status(404).json(error('No pass on this account.'));
    if (pass.tier.isDefault) {
      return res.status(400).json(error('The free pass cannot be cancelled.'));
    }
    if (pass.status !== PassStatus.ACTIVE) {
      return res
        .status(409)
        .json(error(`Pass is ${pass.status.toLowerCase()}. There is nothing to cancel.`));
    }

    const cancelledAt = new Date();
    await prisma.$transaction([
      prisma.pass.update({
        where: { id: pass.id },
        data: { status: PassStatus.CANCELLED, cancelledAt },
      }),
      prisma.auditLog.create({
        data: {
          actorId: req.user!.id,
          action: 'CANCEL_PASS',
          entity: 'Pass',
          entityId: pass.id,
          meta: JSON.stringify({ tierId: pass.tierId, seasonYear: pass.seasonYear }),
        },
      }),
    ]);

    // A seeded paid rider may carry no free pass at all, and a cancelled pass is
    // not what the account should read as afterwards. Grant the default tier for
    // the running season unless a free pass is already running.
    const freeRunning = await prisma.pass.findFirst({
      where: { userId: req.user!.id, status: PassStatus.ACTIVE, tier: { isDefault: true } },
    });
    if (!freeRunning) await grantDefaultTier(req.user!.id);

    res.json(
      success(
        { passId: pass.id, cancelledAt },
        'Pass cancelled. The account is back on the free pass.'
      )
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: short-lived, signed QR token (rotates to prevent screenshot replay). */
export const qrToken = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const pass = await getCurrentPass(req.user!.id);
    if (!pass) return res.status(404).json(error('No pass found for this account.'));
    if (pass.status !== PassStatus.ACTIVE) {
      return res
        .status(409)
        .json(error(`Pass is ${pass.status.toLowerCase()} — a QR code is not available.`));
    }
    const { token, expiresAt, nonce } = issueQrToken(pass.id, req.user!.id);
    res.json(success({ token, expiresAt, nonce, passId: pass.id }));
  } catch (err) {
    next(err);
  }
};

/** Rider: scan / redemption history. Newest first unless `?order=asc`, which
    sorts by time the other way so a windowed read (`perPage=10` on the profile)
    can hold the earliest rides instead of the latest. `?page=&perPage=`
    narrows the read; with neither the endpoint keeps handing back the
    latest 100 rows. The profile's Rides card pages it 10 at a time. */
export const myHistory = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const page = clampInt(req.query.page, 1, 1, 100_000);
    const perPage = clampInt(req.query.perPage, 100, 1, 100);
    const order = req.query.order === 'asc' ? 'asc' : 'desc';
    const where = { userId: req.user!.id };
    const [total, redemptions] = await Promise.all([
      prisma.redemption.count({ where }),
      prisma.redemption.findMany({
        where,
        include: { track: true },
        orderBy: { redeemedAt: order },
        skip: (page - 1) * perPage,
        take: perPage,
      }),
    ]);
    res.json(
      success({
        redemptions: redemptions.map((r) => ({
          id: r.id,
          trackName: r.track.name,
          trackWebsite: r.track.website,
          kind: r.kind,
          day: r.day,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
        total,
        page,
        perPage,
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: denied scan attempts (so they can see why a scan failed). */
export const myDeniedScans = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const events = await prisma.scanEvent.findMany({
      where: { userId: req.user!.id, result: 'DENIED' },
      include: { track: true },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
    res.json(
      success({
        events: events.map((e) => ({
          id: e.id,
          trackName: e.track.name,
          trackWebsite: e.track.website,
          reasonCode: e.reasonCode,
          reason: e.reason,
          createdAt: e.createdAt,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: perks & discount codes attached to the pass. */
export const myPerks = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const pass = await getCurrentPass(req.user!.id);
    const now = new Date();
    const perks = await prisma.perk.findMany({
      where: {
        isActive: true,
        OR: [{ tierId: null }, ...(pass ? [{ tierId: pass.tierId }] : [])],
        AND: [
          { OR: [{ validFrom: null }, { validFrom: { lte: now } }] },
          { OR: [{ validTo: null }, { validTo: { gte: now } }] },
        ],
      },
      include: { track: true },
      orderBy: { title: 'asc' },
    });
    const used = await prisma.perkRedemption.findMany({
      where: { userId: req.user!.id },
      select: { perkId: true },
    });
    const usedSet = new Set(used.map((u) => u.perkId));
    res.json(
      success({
        perks: perks.map((p) => ({
          id: p.id,
          code: p.code,
          title: p.title,
          description: p.description,
          discountType: p.discountType,
          value: p.value,
          trackId: p.trackId,
          trackName: p.track?.name ?? null,
          trackWebsite: p.track?.website ?? null,
          redeemed: usedSet.has(p.id),
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Rider: redeem a perk code (validated server-side). */
export const redeemPerk = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const code = String(req.params.code || '').toUpperCase();
    // A code is short and plain: letters, digits, spaces, hyphens, underscores.
    if (!/^[A-Z0-9][A-Z0-9 _-]{0,39}$/.test(code)) {
      return res.status(400).json(error('That code is not valid.'));
    }
    const perk = await prisma.perk.findUnique({ where: { code } });
    if (!perk || !perk.isActive) return res.status(404).json(error('That code is not valid.'));

    const already = await prisma.perkRedemption.findFirst({
      where: { perkId: perk.id, userId: req.user!.id },
    });
    if (already) return res.status(409).json(error('You have already redeemed this offer.'));

    const now = new Date();
    if (perk.validFrom && perk.validFrom > now) {
      return res.status(400).json(error('This offer is not active yet.'));
    }
    if (perk.validTo && perk.validTo < now) {
      return res.status(400).json(error('This offer has expired.'));
    }

    await prisma.perkRedemption.create({ data: { perkId: perk.id, userId: req.user!.id } });
    res.json(success({ perk: { code: perk.code, title: perk.title } }, 'Offer redeemed.'));
  } catch (err) {
    next(err);
  }
};

