function publicFollow(f: {
  trackId: string;
  createdAt: Date;
  track: {
    slug: string;
    name: string;
    city: string | null;
    region: string | null;
    status: string;
    statusNote: string | null;
    hours: string | null;
    nextEvent: string | null;
  };
}) {
  return {
    trackId: f.trackId,
    slug: f.track.slug,
    name: f.track.name,
    city: f.track.city,
    region: f.track.region,
    status: f.track.status,
    statusNote: f.track.statusNote,
    hours: f.track.hours,
    nextEvent: f.track.nextEvent,
    followedAt: f.createdAt,
  };
}

/** Rider: the tracks this account follows. Operators cannot follow — they own
 *  a venue and read its audience on the followers page instead. */
export const myFollows = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const rows = await prisma.trackFollow.findMany({
      where: { userId: req.user!.id },
      include: { track: true },
      orderBy: { createdAt: 'desc' },
    });
    res.json(success({ follows: rows.map(publicFollow) }));
  } catch (err) {
    next(err);
  }
};

/** Rider: follow a track. Idempotent — following twice is not an error.
 *  Operators cannot follow: an operator account owns a venue rather than
 *  following it. */
export const followTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const trackId = uuidParam(req.params.trackId, 'trackId');
    const track = await prisma.track.findUnique({ where: { id: trackId } });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const row = await prisma.trackFollow.upsert({
      where: { userId_trackId: { userId: req.user!.id, trackId } },
      create: { userId: req.user!.id, trackId },
      update: {},
      include: { track: true },
    });
    res.json(success({ following: true, follow: publicFollow(row) }, `Following ${track.name}.`));
  } catch (err) {
    next(err);
  }
};

/** Rider: stop following a track. Operators cannot follow, like the follow itself. */
export const unfollowTrack = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const trackId = uuidParam(req.params.trackId, 'trackId');
    await prisma.trackFollow.deleteMany({ where: { userId: req.user!.id, trackId } });
    res.json(success({ following: false }, 'No longer following that track.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Rider: the calendar — every active date at the tracks this account follows,
 * each one carrying the venue it belongs to.
 *
 * It is the follows list read as a schedule, so it comes and goes with the same
 * control: a rider on any tier (free included) gets their own calendar, and a
 * track they stop following leaves it. `?trackId=` narrows the read to one of
 * the tracks they follow, which is what the page's track filter asks for.
 */
export const myCalendar = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    if (req.user!.role === Role.OPERATOR) {
      return res.status(403).json(error('Operator accounts cannot follow tracks.'));
    }
    const asked = req.query.trackId ? uuidParam(req.query.trackId, 'trackId') : null;
    const rows = await prisma.trackFollow.findMany({
      where: { userId: req.user!.id, ...(asked ? { trackId: asked } : {}) },
      include: { track: true },
      orderBy: { createdAt: 'desc' },
    });
    const follows = rows.map(publicFollow);
    const events = rows.length
      ? await prisma.trackEvent.findMany({
          where: { isActive: true, trackId: { in: rows.map((r) => r.trackId) } },
          orderBy: { startsAt: 'asc' },
        })
      : [];
    // The venue rides on the date: a calendar of several tracks has to name the
    // track each date belongs to, and the page reads the slug for the link and
    // the category for the badge.
    const byId = new Map(rows.map((r) => [r.trackId, r.track]));
    res.json(
      success({
        follows,
        events: events.map((e) => {
          const t = byId.get(e.trackId);
          return {
            id: e.id,
            title: e.title,
            description: e.description,
            kind: e.kind,
            startsAt: e.startsAt,
            endsAt: e.endsAt,
            startMinutes: e.startMinutes,
            endMinutes: e.endMinutes,
            trackId: e.trackId,
            trackSlug: t?.slug ?? '',
            trackName: t?.name ?? '',
            trackCategory: t?.category ?? null,
            // The venue's photo and place ride along so the read sheet can
            // carry the track's profile banner under the date.
            trackImageUrl: t?.imageUrl ?? null,
            trackCity: t?.city ?? null,
            trackRegion: t?.region ?? null,
          };
        }),
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import Stripe from 'stripe';
import { PassStatus, PaymentStatus } from '../types/enums';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import config from '../config';
import { activatePass } from '../services/pass.service';
import logger from '../utils/logger';
import { uuidParam } from '../utils/sanitize';

const stripe = config.stripe.secretKey && !config.stripe.secretKey.includes('placeholder')
  ? new Stripe(config.stripe.secretKey, { apiVersion: '2024-12-18.acacia' as Stripe.LatestApiVersion })
  : null;

/**
 * Create a checkout session for a pass tier.
 * Creates a PENDING pass + PENDING payment first, then a Stripe Checkout
 * Session pointing at it. The pass is only activated by the webhook.
 */
export const createCheckout = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ tierId: z.string().uuid() }).parse(req.body);

    const tier = await prisma.passTier.findUnique({ where: { id: body.tierId } });
    if (!tier || !tier.isActive) return res.status(404).json(error('That pass tier is unavailable.'));

    const season = await prisma.season.findFirst({
      where: { isActive: true },
      orderBy: { year: 'desc' },
    });
    if (!season) return res.status(400).json(error('No active season is configured.'));

    // Idempotent by intent: a second click (or a back-then-buy-again) reuses the
    // PENDING pair the first click left behind instead of orphaning it. Only a
    // PENDING pass younger than a day is reused — an older one is abandoned, so
    // someone who walked away can still buy cleanly.
    const reuseAfter = new Date(Date.now() - 24 * 60 * 60 * 1000);
    let pass = await prisma.pass.findFirst({
      where: {
        userId: req.user!.id,
        tierId: tier.id,
        seasonId: season.id,
        status: PassStatus.PENDING,
        createdAt: { gte: reuseAfter },
      },
      orderBy: { createdAt: 'desc' },
    });

    if (!pass) {
      pass = await prisma.pass.create({
        data: {
          userId: req.user!.id,
          tierId: tier.id,
          seasonId: season.id,
          seasonYear: season.year,
          status: PassStatus.PENDING,
          expiresAt: season.endsAt,
        },
      });
    }

    // Early-bird pricing wins while it is still in effect.
    const earlyBirdActive =
      tier.earlyBirdPriceCents != null && (!tier.earlyBirdEndsAt || tier.earlyBirdEndsAt > new Date());
    const amountCents = earlyBirdActive ? tier.earlyBirdPriceCents! : tier.priceCents;

    let payment = await prisma.payment.findFirst({
      where: { passId: pass.id, status: PaymentStatus.PENDING },
      orderBy: { createdAt: 'desc' },
    });
    if (payment && payment.amountCents !== amountCents) {
      // The presale ended (or started) between clicks: keep the row in step
      // with what the card actually says.
      payment = await prisma.payment.update({
        where: { id: payment.id },
        data: { amountCents },
      });
    }
    if (!payment) {
      payment = await prisma.payment.create({
        data: {
          userId: req.user!.id,
          passId: pass.id,
          tierId: tier.id,
          amountCents,
          status: PaymentStatus.PENDING,
        },
      });
    }

    if (!stripe) {
      // Dev mode: no real keys. Return the session id so the dev-simulate
      // endpoint (or a real webhook once keys are set) can complete it.
      return res.json(
        success(
          {
            devMode: true,
            passId: pass.id,
            paymentId: payment.id,
            sessionId: `dev_session_${payment.id}`,
            amountCents,
            message:
              'Stripe keys are placeholders — use the dev simulator to complete this purchase, or set real keys in .env.',
          },
          'Checkout created (dev mode).'
        )
      );
    }

    // Return to the host the rider is actually on. The browser sends its own
    // Origin with this POST, so a checkout started on the tailnet returns to the
    // tailnet while a localhost one keeps returning to localhost. Anything not
    // on the allow-list falls back to the configured origin.
    const reqOrigin = req.get('origin');
    const origin =
      reqOrigin && config.checkoutOrigins.includes(reqOrigin) ? reqOrigin : config.checkoutOrigin;
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      customer_email: req.user!.email,
      line_items: [
        {
          quantity: 1,
          price_data: {
            currency: 'usd',
            unit_amount: amountCents,
            product_data: {
              name: `${tier.name} — ${season.year} Annual Pass`,
              description: tier.tagline ?? undefined,
            },
          },
        },
      ],
      metadata: { passId: pass.id, paymentId: payment.id, userId: req.user!.id, tierId: tier.id },
      // Stripe fills {CHECKOUT_SESSION_ID} in, so the return trip can ask the
      // server to confirm the session itself (a lost webhook is then a delay,
      // not a lost purchase).
      success_url: `${origin}/tracks?checkout=success&session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${origin}/pricing?checkout=cancelled`,
      // Half an hour is enough to pay with a card; after that the session
      // expires and its webhook retires the PENDING pair.
      expires_at: Math.floor(Date.now() / 1000) + 30 * 60,
    });

    await prisma.pass.update({ where: { id: pass.id }, data: { stripeSessionId: session.id } });
    await prisma.payment.update({
      where: { id: payment.id },
      data: { stripeSessionId: session.id },
    });

    res.json(success({ url: session.url, sessionId: session.id, passId: pass.id, amountCents }));
  } catch (err) {
    next(err);
  }
};

/** Shared completion logic used by both the webhook and the dev simulator. */
export async function completePayment(args: {
  passId: string;
  paymentId: string;
  stripeSessionId?: string;
  stripePaymentIntentId?: string;
  stripeCustomerId?: string;
  stripeEventId?: string;
}) {
  const existing = await prisma.payment.findUnique({ where: { id: args.paymentId } });
  if (!existing) throw Object.assign(new Error('Payment not found'), { status: 404 });
  // Both the webhook and the return-trip confirm can land, in either order.
  // Activating twice would snapshot the allotments twice, so the second call
  // reads the pass back instead of running the activation again.
  if (existing.status === PaymentStatus.PAID) {
    return prisma.pass.findUniqueOrThrow({ where: { id: args.passId } });
  }

  await prisma.payment.update({
    where: { id: args.paymentId },
    data: {
      status: PaymentStatus.PAID,
      stripeSessionId: args.stripeSessionId,
      stripePaymentIntentId: args.stripePaymentIntentId,
      stripeCustomerId: args.stripeCustomerId,
      stripeEventId: args.stripeEventId,
    },
  });
  await prisma.pass.update({
    where: { id: args.passId },
    data: {
      stripeSessionId: args.stripeSessionId,
      stripeCustomerId: args.stripeCustomerId,
      // One-time payment: there is no subscription on this purchase, so the
      // intent id stays on the Payment row where it belongs.
    },
  });
  const activated = await activatePass(args.passId);
  logger.info(`Pass activated via payment: ${activated.id}`);
  return activated;
}

/**
 * The return trip: the browser comes back with the session id, and this reads
 * that session from Stripe to finish the purchase if the webhook has not landed
 * yet. Ownership is checked against the Payment row, never the metadata alone.
 */
export const confirmCheckout = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const sessionId = typeof req.params.sessionId === 'string' ? req.params.sessionId.trim() : '';
    // A Stripe session id is `cs_test_…` / `cs_live_…`; anything else cannot be
    // one, so it never reaches the database.
    if (!/^[A-Za-z0-9_]{8,255}$/.test(sessionId)) {
      return res.status(404).json(error('Checkout session not found.'));
    }
    const payment = await prisma.payment.findUnique({ where: { stripeSessionId: sessionId } });
    if (!payment) return res.status(404).json(error('Checkout session not found.'));
    if (payment.userId !== req.user!.id && req.user!.role === 'RIDER') {
      return res.status(403).json(error('Not your checkout.'));
    }
    if (payment.status === PaymentStatus.PAID) {
      return res.json(success({ paid: true, paymentId: payment.id }, 'That purchase is already complete.'));
    }
    if (!stripe) {
      return res
        .status(400)
        .json(error('Stripe is not configured on this server — use the dev simulator to complete it.'));
    }

    const session = await stripe.checkout.sessions.retrieve(sessionId);
    if (session.payment_status !== 'paid') {
      return res.json(
        success({ paid: false, paymentId: payment.id }, 'Stripe has not settled this checkout yet.')
      );
    }

    await completePayment({
      passId: session.metadata?.passId ?? payment.passId!,
      paymentId: payment.id,
      stripeSessionId: session.id,
      stripePaymentIntentId: String(session.payment_intent ?? ''),
      stripeCustomerId: String(session.customer ?? ''),
      stripeEventId: `confirm_${session.id}`,
    });
    res.json(success({ paid: true, paymentId: payment.id }, 'Purchase confirmed — your pass is active.'));
  } catch (err) {
    next(err);
  }
};

/**
 * Stripe webhook. Mounted with express.raw so the signature can be verified.
 */
export const stripeWebhook = async (req: Request, res: Response) => {
  const signature = req.headers['stripe-signature'] as string | undefined;

  if (!stripe || !config.stripe.webhookSecret || config.stripe.webhookSecret.includes('placeholder')) {
    logger.warn('Stripe webhook received but Stripe is not configured.');
    return res.status(503).json(error('Stripe is not configured.'));
  }
  if (!signature) return res.status(400).json(error('Missing Stripe signature.'));

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(req.body, signature, config.stripe.webhookSecret);
  } catch (err: any) {
    logger.warn(`Stripe webhook signature verification failed: ${err.message}`);
    return res.status(400).json(error(`Webhook signature verification failed.`));
  }

  try {
    switch (event.type) {
      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session;
        const md = session.metadata ?? {};
        if (md.passId && md.paymentId) {
          await completePayment({
            passId: md.passId,
            paymentId: md.paymentId,
            stripeSessionId: session.id,
            stripePaymentIntentId: String(session.payment_intent ?? ''),
            stripeCustomerId: String(session.customer ?? ''),
            stripeEventId: event.id,
          });
        }
        break;
      }
      case 'checkout.session.expired': {
        const session = event.data.object as Stripe.Checkout.Session;
        const md = session.metadata ?? {};
        if (md.paymentId) {
          const payment = await prisma.payment.findUnique({ where: { id: md.paymentId } });
          // A rider who comes back and starts a fresh session reuses the pair;
          // only the session the pair is currently pointing at may retire it,
          // or an early abandonment would cancel the retry.
          if (!payment || payment.stripeSessionId !== session.id) break;
          if (payment.status === PaymentStatus.PENDING) {
            await prisma.payment.update({
              where: { id: md.paymentId },
              data: { status: PaymentStatus.FAILED },
            });
            await prisma.pass.update({ where: { id: md.passId }, data: { status: PassStatus.CANCELLED } });
          }
        }
        break;
      }
      case 'charge.refunded': {
        const charge = event.data.object as Stripe.Charge;
        await prisma.payment.updateMany({
          where: { stripePaymentIntentId: charge.payment_intent as string },
          data: { status: PaymentStatus.REFUNDED },
        });
        break;
      }
      default:
        logger.debug(`Unhandled Stripe event: ${event.type}`);
    }
    res.json({ received: true });
  } catch (err: any) {
    logger.error(`Stripe webhook handling failed: ${err.message}`);
    res.status(500).json(error('Webhook handling failed.'));
  }
};

/**
 * Dev-only simulator: drives the same completion path as the webhook so the
 * purchase → activation round trip can be verified without live Stripe keys.
 */
export const devSimulatePayment = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    // Sealed unless the deployment opts in (ALLOW_DEV_SIMULATE=true): the demo
    // deploy has no Stripe key, so its paid CTA creates a dev-mode checkout and
    // then calls this endpoint — a bare isProd guard 404s that flow.
    if (!config.allowDevSimulate) return res.status(404).json(error('Not found.'));

    const paymentId = uuidParam(req.params.paymentId, 'paymentId');
    const payment = await prisma.payment.findUnique({ where: { id: paymentId } });
    if (!payment || !payment.passId) return res.status(404).json(error('Payment not found.'));
    if (payment.status === PaymentStatus.PAID) {
      return res.status(409).json(error('That payment is already complete.'));
    }
    if (payment.userId !== req.user!.id && req.user!.role === 'RIDER') {
      return res.status(403).json(error('Not your payment.'));
    }
    const pass = await completePayment({
      passId: payment.passId,
      paymentId: payment.id,
      stripeSessionId: payment.stripeSessionId ?? `dev_session_${payment.id}`,
      stripeEventId: `dev_evt_${payment.id}`,
    });
    res.json(success({ pass }, 'Payment completed (dev simulator) — pass activated.'));
  } catch (err) {
    next(err);
  }
};

/** Rider: my payment history. */
export const myPayments = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const payments = await prisma.payment.findMany({
      where: { userId: req.user!.id },
      include: { tier: true },
      orderBy: { createdAt: 'desc' },
    });
    res.json(
      success({
        payments: payments.map((p) => ({
          id: p.id,
          tierName: p.tier?.name ?? null,
          amountCents: p.amountCents,
          currency: p.currency,
          status: p.status,
          createdAt: p.createdAt,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Renew: start a checkout for next season. */
export const renewPass = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ passId: z.string().uuid() }).parse(req.body);
    const prev = await prisma.pass.findUnique({ where: { id: body.passId } });
    if (!prev || prev.userId !== req.user!.id) {
      return res.status(404).json(error('Pass not found.'));
    }
    req.body = { tierId: prev.tierId };
    return createCheckout(req, res, next);
  } catch (err) {
    next(err);
  }
};

import { Response, NextFunction } from 'express';
import { z } from 'zod';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { toCsv } from '../utils/csv';
import { formatDay } from '../utils/dates';

/**
 * QuickBooks integration layer.
 *
 * Exports users, subscriptions (passes) and payments in shapes that map to
 * QuickBooks Online import templates (Customers, Invoices, Sales Receipts).
 * Structured so a live API sync can be layered on later: each row carries the
 * QuickBooks-facing field names plus an external key for reconciliation.
 */

type ExportKind = 'customers' | 'subscriptions' | 'payments';

async function buildCustomers() {
  const users = await prisma.user.findMany({ orderBy: { createdAt: 'asc' } });
  return users.map((u) => ({
    'Customer Name': u.name,
    Company: '',
    'Display Name': u.name,
    'Primary Email': u.email,
    'Primary Phone': u.phone ?? '',
    'External Key': u.id,
    'Notes / Role': u.role,
    Active: u.isActive ? 'Yes' : 'No',
  }));
}

async function buildSubscriptions() {
  const passes = await prisma.pass.findMany({
    include: { user: true, tier: true, season: true },
    orderBy: { purchasedAt: 'asc' },
  });
  return passes.map((p) => ({
    'Customer Name': p.user.name,
    'Primary Email': p.user.email,
    'Product/Service': `${p.tier.name} Annual Pass`,
    'Season': String(p.seasonYear),
    'Subscription Status': p.status,
    'Start Date': formatDay(p.activatedAt ?? p.purchasedAt),
    'End Date': formatDay(p.expiresAt),
    'Qty': '1',
    'Rate': (p.tier.priceCents / 100).toFixed(2),
    'Amount': (p.tier.priceCents / 100).toFixed(2),
    'External Key': p.id,
    'Tier': p.tier.slug,
  }));
}

async function buildPayments() {
  const payments = await prisma.payment.findMany({
    include: { user: true, tier: true },
    orderBy: { createdAt: 'asc' },
  });
  return payments.map((p) => ({
    'Customer Name': p.user.name,
    'Primary Email': p.user.email,
    'Transaction Date': formatDay(p.createdAt),
    'Payment Method': 'Stripe',
    'Reference #': p.stripePaymentIntentId ?? p.stripeSessionId ?? p.id,
    'Memo': p.tier ? `${p.tier.name} Annual Pass` : 'Pass purchase',
    'Amount': (p.amountCents / 100).toFixed(2),
    'Status': p.status,
    'External Key': p.id,
  }));
}

const builders: Record<ExportKind, () => Promise<Record<string, string>[]>> = {
  customers: buildCustomers,
  subscriptions: buildSubscriptions,
  payments: buildPayments,
};

export const quickbooksExport = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    // Both query params are closed vocabularies: an unknown one is a 400, not a
    // silent fall back to a different export.
    const { type: kind, format } = z
      .object({
        type: z.enum(['customers', 'subscriptions', 'payments']).default('customers'),
        format: z.enum(['json', 'csv']).default('json'),
      })
      .parse(req.query);
    if (!builders[kind]) {
      return res.status(400).json(error('type must be one of customers, subscriptions, payments.'));
    }

    const rows = await builders[kind]();

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv; charset=utf-8');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="quickbooks-${kind}-${formatDay(new Date())}.csv"`
      );
      return res.send(toCsv(rows));
    }

    res.json(
      success({
        export: kind,
        generatedAt: new Date().toISOString(),
        rowCount: rows.length,
        columns: rows[0] ? Object.keys(rows[0]) : [],
        rows,
      })
    );
  } catch (err) {
    next(err);
  }
};

/** A single manifest describing every available export. */
export const quickbooksManifest = async (_req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const [customers, subscriptions, payments] = await Promise.all([
      buildCustomers(),
      buildSubscriptions(),
      buildPayments(),
    ]);
    res.json(
      success({
        generatedAt: new Date().toISOString(),
        exports: [
          { kind: 'customers', label: 'Customers', rowCount: customers.length, columns: Object.keys(customers[0] ?? {}) },
          { kind: 'subscriptions', label: 'Subscriptions (Invoices)', rowCount: subscriptions.length, columns: Object.keys(subscriptions[0] ?? {}) },
          { kind: 'payments', label: 'Payments (Sales Receipts)', rowCount: payments.length, columns: Object.keys(payments[0] ?? {}) },
        ],
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Response, NextFunction } from 'express';
import { z } from 'zod';
import { AuthRequest } from '../types';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { validateScan, completeReentry, gateDecision, gateStanding } from '../services/scan.service';
import { getCurrentPass } from '../services/pass.service';
import { issueQrToken } from '../utils/qr';
import { dayKey, addDays, todayKey, seasonBounds } from '../utils/dates';
import { checkAnyLookupText, checkLookupInput, lookupQuerySchema } from '../utils/lookupInput';
import { clampInt, uuidParam } from '../utils/sanitize';

/** How many of a rider's past redeemed days the gate view lists. */
const HISTORY_LIMIT = 6;

const scanSchema = z
  .object({
    token: z.string().min(10, 'Pass code is required').max(4096, 'That pass code is not valid.').optional(),
    /** The other way in: the gate finds the rider and redeems their pass. */
    riderId: z.string().uuid().optional(),
    stationId: z.string().uuid().optional(),
  })
  .refine((b) => Boolean(b.token) || Boolean(b.riderId), {
    message: 'A pass code or a rider is required',
    path: ['token'],
  });

/**
 * Resolve which track + station this scan belongs to.
 * Operators are pinned to their own track; admins may target any station.
 */
async function resolveStation(req: AuthRequest, stationId?: string) {
  if (stationId) {
    const station = await prisma.scanStation.findUnique({
      where: { id: stationId },
      include: { track: true },
    });
    if (!station || !station.isActive) return null;
    if (req.user!.role === 'OPERATOR' && req.user!.operatorTrackId !== station.trackId) {
      return null;
    }
    return station;
  }
  if (req.user!.role === 'OPERATOR' && req.user!.operatorTrackId) {
    const station = await prisma.scanStation.findFirst({
      where: { trackId: req.user!.operatorTrackId, isActive: true },
      include: { track: true },
    });
    if (station) return station;
    // Operator without a configured station still scans for their track.
    const track = await prisma.track.findUnique({ where: { id: req.user!.operatorTrackId } });
    if (!track) return null;
    return { id: null, trackId: track.id, name: 'Ticket window', track } as any;
  }
  return null;
}

export const scanValidate = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = scanSchema.parse(req.body);
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }

    // The gate has two ways in: a scanned QR code, or a rider the operator
    // found by phone / email / id. A lookup mints the same short-lived signed
    // token the rider's own portal would, so both paths run the one validator
    // and every rule below (same day, allotment) is shared.
    let token = body.token;
    if (!token && body.riderId) {
      const [pass, rider] = await Promise.all([
        getCurrentPass(body.riderId),
        prisma.user.findUnique({ where: { id: body.riderId }, select: { name: true } }),
      ]);
      if (!pass) {
        // A rider with no pass on the account is a gate event too — keep it in
        // the ledger the operator reads back.
        await prisma.scanEvent.create({
          data: {
            trackId: station.trackId,
            stationId: station.id,
            userId: body.riderId,
            riderName: rider?.name ?? null,
            result: 'DENIED',
            reasonCode: 'NO_PASS',
            reason: 'This rider has no pass on their account.',
            operatorId: req.user!.id ?? null,
          },
        });
        const outcome = {
          result: 'DENIED' as const,
          reasonCode: 'NO_PASS',
          reason: 'This rider has no pass on their account.',
          approved: false,
          rider: rider ? { id: body.riderId, name: rider.name, email: '' } : undefined,
          track: { id: station.trackId, name: station.track.name },
        };
        return res.json(success(outcome));
      }
      token = issueQrToken(pass.id, pass.userId).token;
    }

    const outcome = await validateScan({
      token: token as string,
      trackId: station.trackId,
      stationId: station.id,
      operatorId: req.user!.id,
    });

    res.status(outcome.approved ? 200 : 200).json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * TEST ONLY — mock a successful scan.
 *
 * The station's real doors both need a rider in hand: a phone to scan, or a
 * name to look up. This one skips both and answers with an approved outcome
 * built from a random rider who really holds a paying pass at this track, so
 * the outcome band, the rider block and the day counters can be walked with
 * nobody at the window.
 *
 * It writes nothing: no redemption, no allotment move, no scan event. That is
 * deliberate — the seed's day ledger is exactly what the demo accounts are
 * built on (who is out of days, who already rode today at 221 MX), and a mock
 * that spent days would rot those states after a handful of taps. The reason
 * line says so, so a reader can never mistake it for a real check-in.
 */
export const mockScan = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z.object({ stationId: z.string().uuid().optional() }).parse(req.body ?? {});
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }

    const now = Date.now();
    const allotments = await prisma.allotment.findMany({
      where: { trackId: station.trackId },
      include: { pass: { include: { tier: true, user: true } } },
      take: 500,
    });
    // A paying pass only — the free tier has no days to hand over.
    const pool = allotments.filter(
      (a) => a.pass.status === 'ACTIVE' && a.pass.expiresAt.getTime() > now && !a.pass.tier.isDefault
    );
    if (pool.length === 0) {
      return res.status(409).json(error('No rider holds a paying pass at this track. Reseed the demo data.'));
    }

    const pick = pool[Math.floor(Math.random() * pool.length)];
    const { pass } = pick;
    const freeRemaining = Math.max(pick.includedDays - pick.freeDaysUsed, 0);
    const outcome = {
      result: 'APPROVED' as const,
      approved: true,
      reasonCode: 'APPROVED',
      reason: 'Mock approval — no day was recorded.',
      kind: 'FREE' as const,
      amountChargedCents: 0,
      rider: { id: pass.user.id, name: pass.user.name, email: pass.user.email },
      track: { id: station.trackId, name: station.track.name },
      pass: {
        id: pass.id,
        status: pass.status,
        seasonYear: pass.seasonYear,
        expiresAt: pass.expiresAt.toISOString(),
        tierName: pass.tier.name,
      },
      includedDays: pick.includedDays,
      remainingFreeDays: freeRemaining,
      discountDaysRemaining: Math.max(pick.discountDaysAllowed - pick.discountDaysUsed, 0),
      mock: true,
    };
    res.json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * Operator: let a rider back through today's gate. The day is already spent,
 * so this is a logged pass-through only — no allotment moves, nothing is owed.
 * It reads the same station the scan does, so an operator can only re-enter at
 * their own track.
 */
export const reenterRider = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const body = z
      .object({ riderId: z.string().uuid(), stationId: z.string().uuid().optional() })
      .parse(req.body);
    const station = await resolveStation(req, body.stationId);
    if (!station) {
      return res
        .status(400)
        .json(error('No scanning station is configured for your account. Ask an admin to assign one.'));
    }
    const outcome = await completeReentry({
      riderId: body.riderId,
      trackId: station.trackId,
      stationId: station.id,
      operatorId: req.user!.id,
    });
    res.json(success(outcome));
  } catch (err) {
    next(err);
  }
};

/**
 * Operator: find a rider at the gate. Phone, name, email or account id — the
 * things a rider can be asked at the window. The gate's search sends one
 * `field` per search, so an email search never returns a name match; with no
 * `field` it falls back to any of them. Only riders who hold a pass are worth
 * listing, so each hit carries the pass's standing at this track.
 */
export const searchRiders = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const query = lookupQuerySchema.parse(req.query);
    const field = query.field;
    /* The panel runs the same rules before it sends. A key that still arrives
       malformed is refused here, so no bad text ever reaches the query: an
       empty one is simply no rows, a bad one is a 400. */
    const check = field ? checkLookupInput(field, query.q) : checkAnyLookupText(query.q);
    const q = check.text;
    if (!check.ok) {
      return q.length === 0
        ? res.json(success({ q, riders: [] }))
        : res.status(400).json(error(check.message, [{ field: 'q', message: check.message }]));
    }
    const trackId = query.trackId || req.user!.operatorTrackId || undefined;

    // Phone numbers are stored as digits, so a query typed with dashes still
    // matches once its own digits are pulled out. Text matches are
    // case-insensitive explicitly: SQLite's LIKE ignored case for ASCII, and
    // PostgreSQL's does not, so without `mode` a gate typing "Ops@..." or "amy"
    // would stop finding the rider it used to.
    const digits = q.replace(/\D/g, '');
    const where: Record<string, unknown>[] =
      field === 'email'
        ? [{ email: { contains: q, mode: 'insensitive' } }]
        : field === 'name'
          ? [{ name: { contains: q, mode: 'insensitive' } }]
          : field === 'phone'
            ? [{ phone: { contains: digits } }]
            : [
                { email: { contains: q, mode: 'insensitive' } },
                { name: { contains: q, mode: 'insensitive' } },
                { id: q },
                ...(digits.length >= 3 ? [{ phone: { contains: digits } }] : []),
              ];
    if (where.length === 0) return res.json(success({ q, riders: [] }));

    const users = await prisma.user.findMany({
      where: { role: 'RIDER', isActive: true, OR: where },
      select: { id: true, name: true, email: true, phone: true, avatarUrl: true },
      orderBy: { name: 'asc' },
      take: 8,
    });
    const ids = users.map((u) => u.id);
    const today = todayKey();

    const [passes, allotments, track, redeemedToday] = await Promise.all([
      ids.length
        ? prisma.pass.findMany({
            where: { userId: { in: ids } },
            include: { tier: true },
            orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
          })
        : Promise.resolve([]),
      ids.length && trackId
        ? prisma.allotment.findMany({ where: { userId: { in: ids }, trackId } })
        : Promise.resolve([]),
      trackId
        ? prisma.track.findUnique({ where: { id: trackId }, select: { name: true } })
        : Promise.resolve(null),
      // The same-day rule, read up front so the panel can say what would
      // stop a redeem before the operator taps.
      ids.length && trackId
        ? prisma.redemption.findMany({
            where: { userId: { in: ids }, trackId, day: today },
            select: { userId: true, kind: true, redeemedAt: true },
          })
        : Promise.resolve([]),
    ]);

    /* The redeemed days behind the standing: the operator sees what the rider
       has already spent here without leaving the gate view. Six most recent
       per rider, plus the whole-season count. Scoped to this track, because
       the day count beside it is this track's allotment — an account-wide list
       would read as days spent against a balance it never touched. */
    const historyWhere = (userId: string) => ({
      userId,
      ...(trackId ? { trackId } : {}),
    });
    const histories = await Promise.all(
      users.map(async (u) => ({
        userId: u.id,
        rows: await prisma.redemption.findMany({
          where: historyWhere(u.id),
          include: { track: { select: { name: true } } },
          orderBy: [{ day: 'desc' }, { redeemedAt: 'desc' }],
          take: HISTORY_LIMIT,
        }),
        total: await prisma.redemption.count({ where: historyWhere(u.id) }),
      }))
    );

    const riders = users.map((u) => {
      const mine = passes.filter((p) => p.userId === u.id);
      const active = mine.filter((p) => p.status === 'ACTIVE');
      // Same preference as getCurrentPass: an active paid pass wins over the
      // default (free) one, so the gate sees the pass the rider bought.
      const pass =
        active.filter((p) => !p.tier.isDefault).sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0] ??
        active[0] ??
        mine[0] ??
        null;
      const allotment = allotments.find(
        (a) => a.userId === u.id && a.seasonYear === (pass?.seasonYear ?? -1)
      );
      const redemption = redeemedToday.find((r) => r.userId === u.id) ?? null;

      // One verdict, from the scan's own rules — the panel and the window can
      // never disagree about whether this rider gets in.
      const decision = gateDecision({
        pass: pass ? { status: pass.status, expiresAt: pass.expiresAt } : null,
        trackName: track?.name ?? 'this track',
        redeemedToday: Boolean(redemption),
        allotment: allotment ?? null,
      });
      const standing = gateStanding(decision, {
        redeemedTodayAt: redemption?.redeemedAt ?? null,
        redeemedTodayKind: redemption?.kind ?? null,
        allotment: allotment ?? null,
      });

      return {
        id: u.id,
        name: u.name,
        email: u.email,
        phone: u.phone,
        avatarUrl: u.avatarUrl,
        pass: pass
          ? {
              tierName: pass.tier.name,
              // The default (free) tier carries no allotments, so it has no
              // days to redeem anywhere; the panel reads this instead of the
              // TRACK_NOT_PARTICIPATING denial it would otherwise show.
              freeTier: pass.tier.isDefault,
              status: pass.status,
              seasonYear: pass.seasonYear,
              expiresAt: pass.expiresAt.toISOString(),
            }
          : null,
        includedDays: allotment?.includedDays ?? null,
        remainingFreeDays: allotment
          ? Math.max(allotment.includedDays - allotment.freeDaysUsed, 0)
          : null,
        standing,
        /* The days already spent, newest first, with the season's own count so
           a capped list never reads as the whole story. */
        history: (histories.find((h) => h.userId === u.id)?.rows ?? []).map((r) => ({
          id: r.id,
          day: r.day.toISOString(),
          trackName: r.track.name,
          kind: r.kind,
          amountChargedCents: r.amountChargedCents,
          redeemedAt: r.redeemedAt.toISOString(),
        })),
        historyCount: histories.find((h) => h.userId === u.id)?.total ?? 0,
      };
    });

    res.json(success({ q, riders }));
  } catch (err) {
    next(err);
  }
};

/** Operator: today's check-ins at their track. */
export const todayCheckins = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId =
      (req.query.trackId ? uuidParam(req.query.trackId, 'trackId') : null) ||
      req.user!.operatorTrackId ||
      undefined;
    if (!trackId) return res.status(400).json(error('No track specified.'));

    const today = todayKey();
    const redemptions = await prisma.redemption.findMany({
      where: { trackId, day: today },
      include: { user: { select: { name: true, email: true } } },
      orderBy: { redeemedAt: 'desc' },
    });
    const denied = await prisma.scanEvent.findMany({
      where: { trackId, result: 'DENIED', createdAt: { gte: today } },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
    res.json(
      success({
        date: today,
        checkins: redemptions.map((r) => ({
          id: r.id,
          riderName: r.user.name,
          riderEmail: r.user.email,
          kind: r.kind,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
        deniedCount: denied.length,
        denied: denied.map((d) => ({
          id: d.id,
          riderName: d.riderName,
          reasonCode: d.reasonCode,
          reason: d.reason,
          createdAt: d.createdAt,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Operator/admin: full redemption + scan log with filters. */
export const redemptionLog = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId =
      (req.query.trackId ? uuidParam(req.query.trackId, 'trackId') : null) ||
      req.user!.operatorTrackId ||
      undefined;
    const limit = clampInt(req.query.limit, 100, 1, 500);

    const [redemptions, scans] = await Promise.all([
      prisma.redemption.findMany({
        where: trackId ? { trackId } : {},
        include: { track: true, user: { select: { name: true, email: true } } },
        orderBy: { redeemedAt: 'desc' },
        take: limit,
      }),
      prisma.scanEvent.findMany({
        where: trackId ? { trackId } : {},
        include: { track: true },
        orderBy: { createdAt: 'desc' },
        take: limit,
      }),
    ]);

    res.json(
      success({
        // The server's own day key, so the dashboard's Today scope lines up
        // with the ledgers it is filtering.
        date: todayKey(),
        redemptions: redemptions.map((r) => ({
          id: r.id,
          riderName: r.user.name,
          riderEmail: r.user.email,
          trackName: r.track.name,
          trackWebsite: r.track.website,
          kind: r.kind,
          day: r.day,
          redeemedAt: r.redeemedAt,
          amountChargedCents: r.amountChargedCents,
        })),
        scans: scans.map((s) => ({
          id: s.id,
          riderName: s.riderName,
          trackName: s.track.name,
          trackWebsite: s.track.website,
          result: s.result,
          reasonCode: s.reasonCode,
          reason: s.reason,
          kind: s.kind,
          createdAt: s.createdAt,
        })),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Operator/admin: list stations available to the caller. */
export const myStations = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const where =
      req.user!.role === 'OPERATOR' && req.user!.operatorTrackId
        ? { trackId: req.user!.operatorTrackId }
        : {};
    const stations = await prisma.scanStation.findMany({
      where: { ...where, isActive: true },
      include: { track: { select: { id: true, name: true, slug: true } } },
    });
    res.json(success({ stations }));
  } catch (err) {
    next(err);
  }
};

const WEEKDAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const STAT_WINDOW_DAYS = 30;
/** The longest day run worth drawing as columns; a season is read as a
    summary, not a bar per day. */
const STAT_MAX_DAY_RUN = 31;

/** The reads the operator's timeframe pill offers: the gate today, the
    trailing month, the season to date. */
type StatRange = 'today' | 'window' | 'season';

const RANGE_LABEL: Record<StatRange, string> = {
  today: 'Today',
  window: 'Last 30 days',
  season: 'Season to date',
};

function readRange(raw: unknown): StatRange {
  return raw === 'today' || raw === 'window' || raw === 'season' ? raw : 'season';
}

type StatRedemption = {
  userId: string;
  day: Date;
  kind: string;
  amountChargedCents: number;
  redeemedAt: Date;
  user: { name: string };
};

type StatScan = {
  result: string;
  reasonCode: string | null;
  reason: string | null;
  createdAt: Date;
};

/**
 * Every figure for one slice of the ledgers. The timeframe pill picks the
 * slice; this builds the whole read off the same rows, so the summary, the day
 * run, the weekday bars, the hour bars and the rider list can never disagree
 * with each other. `firstVisit` carries each rider's first season visit so
 * "first time here" stays true for a short range.
 */
function summarise(
  redemptions: StatRedemption[],
  scans: StatScan[],
  firstVisit: Map<string, number>,
  fromMs: number
) {
  const ridesByRider = new Map<string, number>();
  const collectedByRider = new Map<string, number>();
  const ridesByDay = new Map<number, number>();
  const byKind: Record<string, number> = { FREE: 0, DISCOUNT: 0 };
  const weekday = WEEKDAY_LABELS.map((label) => ({ label, checkins: 0 }));
  const hours = Array.from({ length: 24 }, (_, hour) => ({ hour, checkins: 0 }));
  let collectedCents = 0;

  for (const r of redemptions) {
    const t = r.day.getTime();
    ridesByRider.set(r.userId, (ridesByRider.get(r.userId) ?? 0) + 1);
    ridesByDay.set(t, (ridesByDay.get(t) ?? 0) + 1);
    if (r.amountChargedCents) {
      collectedCents += r.amountChargedCents;
      collectedByRider.set(r.userId, (collectedByRider.get(r.userId) ?? 0) + r.amountChargedCents);
    }
    if (byKind[r.kind] != null) byKind[r.kind] += 1;
    weekday[r.day.getUTCDay()].checkins += 1;
    // Hours are bucketed on the venue's own clock — the same frame the day keys
    // and the activity log's timestamps read — so a rider's bar hour matches the
    // time printed beside it.
    hours[r.redeemedAt.getHours()].checkins += 1;
  }

  const checkins = redemptions.length;
  const riders = ridesByRider.size;
  const rideDays = ridesByDay.size;
  const repeatRiders = [...ridesByRider.values()].filter((n) => n > 1).length;
  const approved = scans.filter((s) => s.result === 'APPROVED').length;
  const round1 = (n: number) => Math.round(n * 10) / 10;

  const topRiders = [...ridesByRider.entries()]
    .map(([userId, visits]) => {
      const row = redemptions.find((r) => r.userId === userId);
      return {
        name: row?.user.name ?? 'Rider',
        visits,
        paidCents: collectedByRider.get(userId) ?? 0,
      };
    })
    .sort((a, b) => b.visits - a.visits || b.paidCents - a.paidCents)
    .slice(0, 5);

  const denials = new Map<string, { code: string | null; reason: string | null; count: number }>();
  for (const s of scans) {
    if (s.result !== 'DENIED') continue;
    const key = s.reasonCode || s.reason || 'OTHER';
    const hit = denials.get(key) ?? { code: s.reasonCode, reason: s.reason, count: 0 };
    hit.count += 1;
    denials.set(key, hit);
  }

  return {
    summary: {
      checkins,
      riders,
      collectedCents,
      rideDays,
      perRideDay: rideDays ? round1(checkins / rideDays) : 0,
      repeatRiders,
      repeatRate: riders ? Math.round((repeatRiders / riders) * 100) : 0,
      newRiders: [...firstVisit.values()].filter((t) => t >= fromMs).length,
      avgVisits: riders ? round1(checkins / riders) : 0,
      scans: scans.length,
      approved,
      denied: scans.length - approved,
      approvalRate: scans.length ? Math.round((approved / scans.length) * 100) : null,
    },
    kinds: byKind,
    weekday,
    hours,
    topRiders,
    denials: [...denials.values()].sort((a, b) => b.count - a.count).slice(0, 5),
    ridesByDay,
  };
}

/**
 * Operator/admin: the venue's operating read — the gate today, the trailing
 * month, or the season to date, chosen by the timeframe pill; when riders
 * actually turn up; and who they are. Every figure is counted off the
 * redemption + scan ledgers at request time; nothing here is stored.
 */
export const trackStats = async (req: AuthRequest, res: Response, next: NextFunction) => {
  try {
    const trackId =
      (req.query.trackId ? uuidParam(req.query.trackId, 'trackId') : null) ||
      req.user!.operatorTrackId ||
      undefined;
    if (!trackId) return res.status(400).json(error('No track specified.'));
    const range = readRange(req.query.range);

    const track = await prisma.track.findUnique({
      where: { id: trackId },
      select: { id: true, name: true, slug: true },
    });
    if (!track) return res.status(404).json(error('Track not found.'));

    const today = todayKey();
    const seasonYear = new Date().getUTCFullYear();
    const { startsAt: seasonStart } = seasonBounds(seasonYear);

    // The whole season is read once — a range is a slice of it, and the
    // season-long rows are what tell "first time here" apart from "been here".
    const [redemptions, scans, followers, upcoming] = await Promise.all([
      prisma.redemption.findMany({
        where: { trackId, day: { gte: seasonStart, lte: today } },
        select: {
          userId: true,
          day: true,
          kind: true,
          amountChargedCents: true,
          redeemedAt: true,
          user: { select: { name: true } },
        },
      }),
      prisma.scanEvent.findMany({
        where: { trackId, createdAt: { gte: seasonStart } },
        select: { result: true, reasonCode: true, reason: true, createdAt: true },
      }),
      prisma.trackFollow.count({ where: { trackId } }),
      prisma.trackEvent.findMany({
        where: { trackId, isActive: true, startsAt: { gte: today } },
        orderBy: { startsAt: 'asc' },
        take: 12,
        select: { title: true, kind: true, startsAt: true, startMinutes: true, endMinutes: true },
      }),
    ]);

    const firstVisit = new Map<string, number>();
    for (const r of redemptions) {
      const t = r.day.getTime();
      const seen = firstVisit.get(r.userId);
      if (seen == null || t < seen) firstVisit.set(r.userId, t);
    }

    const windowStart = addDays(today, -(STAT_WINDOW_DAYS - 1));
    const from = range === 'today' ? today : range === 'window' ? windowStart : seasonStart;
    const fromMs = from.getTime();
    const fromDay = from.toISOString().slice(0, 10);
    const todayIso = today.toISOString().slice(0, 10);

    const rangeReds = redemptions.filter((r) => r.day >= from);
    const rangeScans = scans.filter((s) => s.createdAt >= from);
    const read = summarise(rangeReds, rangeScans, firstVisit, fromMs);

    // A day-by-day run is only drawn for a range short enough to read as
    // columns; the season answers in figures instead.
    const span = Math.round((today.getTime() - fromMs) / 86400000) + 1;
    const days =
      span <= STAT_MAX_DAY_RUN
        ? Array.from({ length: span }, (_, i) => {
            const d = addDays(from, i);
            return {
              day: d.toISOString().slice(0, 10),
              checkins: read.ridesByDay.get(d.getTime()) ?? 0,
            };
          })
        : [];

    const next = upcoming[0] ?? null;
    res.json(
      success({
        trackId: track.id,
        trackName: track.name,
        trackSlug: track.slug,
        seasonYear,
        asOf: todayIso,
        range: {
          key: range,
          label: RANGE_LABEL[range],
          from: fromDay,
          to: todayIso,
        },
        summary: read.summary,
        kinds: read.kinds,
        days,
        weekday: read.weekday,
        hours: read.hours,
        topRiders: read.topRiders,
        denials: read.denials,
        audience: {
          followers,
          upcoming: upcoming.length,
          nextEvent: next
            ? {
                title: next.title,
                kind: next.kind,
                day: next.startsAt.toISOString().slice(0, 10),
                startMinutes: next.startMinutes,
                endMinutes: next.endMinutes,
              }
            : null,
        },
      })
    );
  } catch (err) {
    next(err);
  }
};

import { Request, Response, NextFunction } from 'express';
import { prisma } from '../utils/prisma';
import { success, error } from '../utils/apiResponse';
import { PassStatus, Role, TrackEventKind } from '../types/enums';
import { AuthRequest } from '../types';
import { getCurrentPass } from '../services/pass.service';
import { parseHoursWeek } from '../lib/hoursWeek';
import { addDays, dayKey, todayKey } from '../utils/dates';

/** A posted day read, as the public API serves it. */
export interface DayStatusRead {
  day: string;
  status: string;
  statusNote: string | null;
}

const toRead = (r: { day: Date; status: string; statusNote: string | null }): DayStatusRead => ({
  day: r.day.toISOString().slice(0, 10),
  status: r.status,
  statusNote: r.statusNote,
});

/**
 * The gate a rider reads: today's posted read when the operator set one,
 * else the venue's live line. Tomorrow's caution stays scheduled — it flips
 * the live line when the day arrives (see the owner controller), so the
 * network reads today and nothing else.
 */
function effectiveStatus(
  live: { status: string; statusNote: string | null },
  rows: { day: Date; status: string; statusNote: string | null }[]
): { status: string; statusNote: string | null } {
  const today = todayKey().getTime();
  const row = rows.find((r) => dayKey(r.day).getTime() === today);
  return row ? { status: row.status, statusNote: row.statusNote } : live;
}

/** The posted read `daysAhead` days out, or null when none is scheduled. */
function dayAfterRead(
  rows: { day: Date; status: string; statusNote: string | null }[],
  daysAhead: number
): DayStatusRead | null {
  const want = addDays(todayKey(), daysAhead).getTime();
  const row = rows.find((r) => dayKey(r.day).getTime() === want);
  return row ? toRead(row) : null;
}

/** A venue's next race, as the network serves it — the inspector's callout. */
export interface NextRaceRead {
  title: string;
  /** The race's own day, `YYYY-MM-DD` (events sit at noon UTC, so it round-trips). */
  day: string;
  startMinutes: number | null;
  endMinutes: number | null;
}

const toRaceRead = (r: {
  title: string;
  startsAt: Date;
  startMinutes: number | null;
  endMinutes: number | null;
}): NextRaceRead => ({
  title: r.title,
  day: r.startsAt.toISOString().slice(0, 10),
  startMinutes: r.startMinutes,
  endMinutes: r.endMinutes,
});

/**
 * The overnight flip, run on every public read: a scheduled day that has
 * arrived writes itself onto the venue's live line, so the network, the map
 * and the profile agree even when nobody posted today by hand. Capped — one
 * venue, one write — and only past rows the live line has not caught yet.
 */
async function promoteArrivedDayStatuses(): Promise<void> {
  // Everything before tomorrow midnight — all rows up to and including today
  // (rows sit at noon UTC, so `<= today at 00:00` would miss today's own row).
  const rows = await prisma.trackDayStatus.findMany({
    where: { day: { lt: addDays(todayKey(), 1) } },
    include: { track: { select: { id: true, status: true, statusNote: true } } },
    orderBy: { day: 'desc' },
  });
  const today = todayKey().getTime();
  const seen = new Set<string>();
  for (const r of rows) {
    if (dayKey(r.day).getTime() > today) continue;
    if (seen.has(r.trackId)) continue;
    seen.add(r.trackId);
    if (r.track.status === r.status && r.track.statusNote === r.statusNote) continue;
    await prisma.track.update({
      where: { id: r.trackId },
      data: { status: r.status, statusNote: r.statusNote },
    });
  }
}

/**
 * Whether this viewer is a rider on the free tier (or with no live pass at all).
 * A free account gets the directory — the venue, where it is and what it is
 * doing — but not the pass's own terms, so the included days and the member
 * discount are withheld from the response rather than merely hidden in the UI.
 * Anonymous visitors and paying riders see the full contract terms.
 *
 * `?terms=public` opts out of the gate. It exists for the pricing page, whose
 * figures *are* the anonymous marketing copy: a free rider reading it is being
 * sold the pass, so withholding the day totals there would only break the pitch.
 */
async function viewerGated(req: Request) {
  if (req.query.terms === 'public') return false;
  const user = (req as AuthRequest).user;
  if (!user || user.role !== Role.RIDER) return false;
  const pass = await getCurrentPass(user.id);
  return !pass || pass.status !== PassStatus.ACTIVE || pass.tier.isDefault;
}

/** Public: list active tracks — venue status for everyone, contract terms for
 *  anyone but a free-tier rider. */
export const listTracks = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const season = await prisma.season.findFirst({ where: { isActive: true }, orderBy: { year: 'desc' } });
    await promoteArrivedDayStatuses();
    const tracks = await prisma.track.findMany({
      where: { isActive: true },
      include: {
        contracts: season ? { where: { seasonId: season.id, isActive: true } } : false,
        dayStatuses: {
          where: { day: { gte: todayKey() } },
          orderBy: { day: 'asc' },
        },
      },
      orderBy: { name: 'asc' },
    });
    const user = (req as AuthRequest).user;
    const gated = await viewerGated(req);
    // Each venue's next race, in one read: the rail's inspector calls it out,
    // while the venue profile's own schedule stays the long view.
    const raceRows = await prisma.trackEvent.findMany({
      where: { isActive: true, kind: TrackEventKind.RACE, startsAt: { gte: todayKey() } },
      orderBy: { startsAt: 'asc' },
      select: { trackId: true, title: true, startsAt: true, startMinutes: true, endMinutes: true },
    });
    const nextRace = new Map<string, (typeof raceRows)[number]>();
    for (const r of raceRows) if (!nextRace.has(r.trackId)) nextRace.set(r.trackId, r);
    // Following is not an operator action, so only everyone else's follows
    // land on the payload — an operator reads every flag as false.
    const follows = user && user.role !== Role.OPERATOR
      ? new Set((await prisma.trackFollow.findMany({ where: { userId: user.id } })).map((f) => f.trackId))
      : new Set<string>();
    res.json(
      success({
        seasonYear: season?.year ?? null,
        gated,
        tracks: tracks.map((t) => {
          const c = t.contracts[0];
          const gate = effectiveStatus(t, t.dayStatuses);
          return {
            id: t.id,
            slug: t.slug,
            name: t.name,
            description: t.description,
            city: t.city,
            region: t.region,
            address: t.address,
            lat: t.lat,
            lng: t.lng,
            website: t.website,
            instagram: t.instagram,
            facebook: t.facebook,
            youtube: t.youtube,
            tiktok: t.tiktok,
            imageUrl: t.imageUrl,
            bannerUrl: t.bannerUrl,
            logoUrl: t.logoUrl,
            category: t.category,
            status: gate.status,
            statusNote: gate.statusNote,
            // The operator's own message to riders, when they left one — the
            // panel's note above the facts. Null keeps it off the panel.
            riderMessage: t.riderMessage,
            // Tomorrow's posted read, when the operator has scheduled one —
            // the network lists today, and this is the heads-up beside it.
            tomorrowStatus: dayAfterRead(t.dayStatuses, 1),
            hours: t.hours,
            // The venue's week behind that line — null when none is on file.
            hoursWeek: parseHoursWeek(t.hoursWeek),
            nextEvent: t.nextEvent,
            // The venue's next race on file, when one is coming — null for a
            // venue whose owner keeps no schedule.
            nextRace: nextRace.has(t.id) ? toRaceRead(nextRace.get(t.id)!) : null,
            gated,
            following: follows.has(t.id),
            // Withheld for free-tier riders — the pass's own terms.
            includedDays: gated ? null : c?.includedDays ?? 0,
            discountDayEnabled: gated ? false : c?.discountDayEnabled ?? false,
            discountDayNumber: gated ? null : c?.discountDayNumber ?? null,
            discountRate: gated ? null : c?.discountRate ?? null,
            discountDaysAllowed: gated ? null : c?.discountDaysAllowed ?? null,
            extraDayPriceCents: gated ? null : c?.extraDayPriceCents ?? null,
          };
        }),
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Public: one partner track's venue profile — its own art, hours, links and
 *  events, plus the pass's terms there for anyone but a free-tier rider. */
export const getTrack = async (req: Request, res: Response, next: NextFunction) => {
  try {
    const slug = typeof req.params.slug === 'string' ? req.params.slug.trim().toLowerCase() : '';
    // A slug is lowercase letters, digits and hyphens; anything else cannot be a
    // venue, so it is a 404 before the database is touched.
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) {
      return res.status(404).json(error('Track not found.'));
    }
    const season = await prisma.season.findFirst({ where: { isActive: true }, orderBy: { year: 'desc' } });
    await promoteArrivedDayStatuses();
    const track = await prisma.track.findUnique({
      where: { slug },
      include: {
        events: { where: { isActive: true }, orderBy: { startsAt: 'asc' } },
        photos: { orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }] },
        reviews: {
          orderBy: { createdAt: 'desc' },
          select: {
            id: true,
            rating: true,
            body: true,
            createdAt: true,
            updatedAt: true,
            userId: true,
            user: { select: { name: true, avatarUrl: true } },
            photos: {
              orderBy: [{ sortOrder: 'asc' }, { createdAt: 'asc' }],
              select: { id: true, url: true, caption: true },
            },
          },
        },
        contracts: season ? { where: { seasonId: season.id, isActive: true } } : false,
        dayStatuses: {
          where: { day: { gte: todayKey() } },
          orderBy: { day: 'asc' },
        },
      },
    });
    if (!track || !track.isActive) return res.status(404).json(error('Track not found.'));

    const user = (req as AuthRequest).user;
    const gated = await viewerGated(req);
    const c = track.contracts[0];
    const gate = effectiveStatus(track, track.dayStatuses);
    const following = user && user.role !== Role.OPERATOR
      ? Boolean(await prisma.trackFollow.findUnique({ where: { userId_trackId: { userId: user.id, trackId: track.id } } }))
      : false;

    res.json(
      success({
        seasonYear: season?.year ?? null,
        gated,
        following,
        track: {
          id: track.id,
          slug: track.slug,
          name: track.name,
          description: track.description,
          city: track.city,
          region: track.region,
          address: track.address,
          country: track.country,
          lat: track.lat,
          lng: track.lng,
          website: track.website,
          instagram: track.instagram,
          facebook: track.facebook,
          youtube: track.youtube,
          tiktok: track.tiktok,
          email: track.email,
          phone: track.phone,
          imageUrl: track.imageUrl,
          bannerUrl: track.bannerUrl,
          logoUrl: track.logoUrl,
          category: track.category,
          status: gate.status,
          statusNote: gate.statusNote,
          // The operator's own message to riders, when they left one.
          riderMessage: track.riderMessage,
          // Tomorrow's posted read, when the operator has scheduled one.
          tomorrowStatus: dayAfterRead(track.dayStatuses, 1),
          // Every scheduled day from today on — what the profile's calendar
          // paints onto its dates.
          dayStatuses: track.dayStatuses.map(toRead),
          hours: track.hours,
          hoursWeek: parseHoursWeek(track.hoursWeek),
          nextEvent: track.nextEvent,
          events: track.events.map((e) => ({
            id: e.id,
            title: e.title,
            description: e.description,
            kind: e.kind,
            startsAt: e.startsAt,
            endsAt: e.endsAt,
            // Minutes past midnight on the date's own day, or null for an
            // all-day date — the profile shows the hours, the calendar draws them.
            startMinutes: e.startMinutes,
            endMinutes: e.endMinutes,
          })),
          // The venue's gallery, in the owner's order. The profile page opens
          // on the first frame, so an empty list is the only "no photos" state.
          photos: track.photos.map((p) => ({
            id: p.id,
            url: p.url,
            caption: p.caption,
            category: p.category,
          })),
          // What riders have written about the venue, newest first — the venue
          // page's community wall. Public: it is not a pass term.
          reviews: track.reviews.map((r) => ({
            id: r.id,
            rating: r.rating,
            body: r.body,
            createdAt: r.createdAt,
            updatedAt: r.updatedAt,
            userId: r.userId,
            riderName: r.user.name,
            riderAvatarUrl: r.user.avatarUrl,
            photos: r.photos.map((p) => ({ id: p.id, url: p.url, caption: p.caption })),
          })),
          // The pass's own terms — withheld from a free-tier rider, like /tracks.
          includedDays: gated ? null : c?.includedDays ?? 0,
          discountDayEnabled: gated ? false : c?.discountDayEnabled ?? false,
          discountDayNumber: gated ? null : c?.discountDayNumber ?? null,
          discountRate: gated ? null : c?.discountRate ?? null,
          discountDaysAllowed: gated ? null : c?.discountDaysAllowed ?? null,
          extraDayPriceCents: gated ? null : c?.extraDayPriceCents ?? null,
        },
      })
    );
  } catch (err) {
    next(err);
  }
};

/** Public: pass tiers + pricing. */
export const listTiers = async (_req: Request, res: Response, next: NextFunction) => {
  try {
    const tiers = await prisma.passTier.findMany({
