import { createApp } from './app';
import config from './config';
import { prisma } from './utils/prisma';
import logger from './utils/logger';
import { mailProvider, mailSummary, mailFrom, appUrl } from './services/mail.service';

async function main() {
  const app = createApp();

  const server = app.listen(config.port, config.host, () => {
    logger.info(`Moto Pass API listening on http://${config.host}:${config.port}`);
    // One line at boot so a deploy's log answers "is mail live?" without a
    // signup. `none` means every message is printed instead of sent, and the
    // `resend:dev` / `resend:prod` suffix names which key path it found.
    logger.info(
      mailProvider === 'none'
        ? '[mail] no provider configured — messages print to this log'
        : `[mail] provider ${mailSummary}, from ${mailFrom}`
    );
    // The origin every mailed link opens. Logged beside the provider so a wrong
    // host (a tailnet URL in a deploy, a prod URL on a laptop) shows up here
    // instead of in a rider's inbox.
    logger.info(`[mail] links point at ${appUrl()}`);
  });

  const shutdown = async (signal: string) => {
    logger.info(`${signal} received — shutting down.`);
    server.close(async () => {
      await prisma.$disconnect();
      process.exit(0);
    });
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

main().catch((err) => {
  logger.error('Fatal startup error', err);
  process.exit(1);
});

/**
 * The venue week: one shape, read by the API, written by the owner console.
 *
 * Stored on `Track.hoursWeek` as JSON (`{"mon":"Practice 9am–4pm", …}`) so the
 * seven days travel as one column; parsed here so no caller has to know that.
 * Keys are always Mon..Sun in that order, and a day the venue does not run
 * reads `Closed` rather than blank.
 */
import { z } from 'zod';

export const HOURS_WEEK_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] as const;
export type HoursWeekKey = (typeof HOURS_WEEK_KEYS)[number];
export type HoursWeek = Record<HoursWeekKey, string>;

/** A week off a track row — null when the venue has none on file (or it is junk). */
export function parseHoursWeek(raw: string | null | undefined): HoursWeek | null {
  if (!raw) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const src = parsed as Record<string, unknown>;
  const week = {} as HoursWeek;
  for (const key of HOURS_WEEK_KEYS) {
    const value = src[key];
    if (typeof value !== 'string') return null;
    week[key] = value.trim() === '' ? 'Closed' : value.trim();
  }
  return week;
}

/** What the console posts: the JSON string for a week, or null when it clears one. */
export const hoursWeekSchema = z
  .string()
  .max(1200)
  .refine((v) => v.trim() === '' || parseHoursWeek(v) !== null, 'hoursWeek must be a Mon–Sun map');

/**
 * The launch window: which phase the site is in, and who is let through while
 * the presale runs.
 *
 * The window is computed here, on every read, from `LAUNCH_PRESALE_ENDS_AT`
 * (server/.env). There is no cron and no redeploy to end it: the phase flips by
 * date comparison the first time anything asks after the timestamp passes.
 *
 * The client's `enablePresaleIsActive` flag only decides which home page is
 * rendered. It cannot open or close the gate — this file is the only authority,
 * and the gate is applied in middleware/presaleGate.ts on the API, so a hidden
 * link in the router is not what keeps a venue's page private.
 */
import config from '../config';
import { PassStatus, Role } from '../types/enums';
import { prisma } from '../utils/prisma';

export type LaunchPhase = 'PRESALE' | 'OPEN';

/**
 * The phase the preview switch (POST /api/launch/view) last put the server in,
 * or null to follow the configured window. In memory on purpose: a restart, a
 * redeploy or the next `tsx watch` reload drops it, so it can never outlive the
 * session that set it. `launchWindow` is the only reader, which puts the gate,
 * `/launch` and every gated read on the same answer.
 */
let previewPhase: LaunchPhase | null = null;

export function setPreviewPhase(phase: LaunchPhase | null) {
  previewPhase = phase;
}

export function previewPhaseIsSet() {
  return previewPhase != null;
}


export interface LaunchWindow {
  phase: LaunchPhase;
  presaleStartsAt: Date | null;
  presaleEndsAt: Date | null;
}

/**
 * PRESALE while the window is running, OPEN otherwise.
 *
 * `presaleEndsAt` unset means the presale was never armed — OPEN. That default
 * is deliberate: dev servers, the verify suites and a deploy nobody configured
 * must behave exactly as they did before this feature existed.
 */
export function launchWindow(now: Date = new Date()): LaunchWindow {
  const { presaleStartsAt, presaleEndsAt } = config.launch;
  const started = presaleStartsAt == null || presaleStartsAt <= now;
  const running = presaleEndsAt != null && presaleEndsAt > now && started;
  return {
    phase: previewPhase ?? (running ? 'PRESALE' : 'OPEN'),
    presaleStartsAt,
    presaleEndsAt,
  };
}

export const presaleIsRunning = (now: Date = new Date()) => launchWindow(now).phase === 'PRESALE';

/**
 * A pass that gets its rider through the presale gate: paid (not the default
 * free tier), ACTIVE (a PENDING row is a checkout nobody finished) and not
 * expired. Reading it off the pass row rather than the session means a rider
 * who buys during the presale is through on their next request.
 */
export async function hasRidingPass(userId: string): Promise<boolean> {
  const pass = await prisma.pass.findFirst({
    where: {
      userId,
      status: PassStatus.ACTIVE,
      expiresAt: { gt: new Date() },
      tier: { isDefault: false },
    },
    select: { id: true },
  });
  return pass != null;
}

/**
 * Whether this caller reads the gated surfaces: the site is open, or they are
 * staff, or they hold a paid pass. The client is told the same answer by
 * GET /launch so its nav and its redirects agree with the API instead of
 * guessing.
 */
export async function gateIsOpenFor(user?: { id: string; role: Role }): Promise<boolean> {
  const win = launchWindow();
  if (win.phase !== 'PRESALE') return true;
  if (!user) return false;
  if (user.role === Role.ADMIN || user.role === Role.OPERATOR) return true;
  try {
    return await hasRidingPass(user.id);
  } catch {
    // A read failure answers closed: the gate is the one place a database
    // wobble must not be mistaken for permission.
    return false;
  }
}

/**
 * The moment email confirmation shipped.
 *
 * An account created before it was made while signing up *was* signing in, and
 * no confirmation link was ever mailed to it. Demanding one now would lock out
 * every rider, operator and admin who joined before this step, so those
 * accounts are grandfathered: the first sign-in after the change stamps them
 * verified and nothing else asks again.
 *
 * `VERIFICATION_REQUIRED_FROM` (an ISO date) moves the line without a code
 * change. It is read once, at boot.
 */
export const VERIFICATION_REQUIRED_FROM = new Date(
  process.env.VERIFICATION_REQUIRED_FROM || '2026-11-12T05:00:00Z'
);

/** Does this account have to confirm its address before it can sign in? */
export const mustConfirmEmail = (user: { emailVerifiedAt: Date | null; createdAt: Date }) =>
  !user.emailVerifiedAt && user.createdAt.getTime() >= VERIFICATION_REQUIRED_FROM.getTime();

import { NextFunction, Response } from 'express';
import { Role } from '../types/enums';
import { AuthRequest } from '../types';
import { resolveSession } from '../services/session.service';
import config from '../config';
import { error } from '../utils/apiResponse';

/** Attach req.user when a valid session cookie is present. Never blocks. */
export async function attachUser(req: AuthRequest, _res: Response, next: NextFunction) {
  try {
    const token = req.cookies?.[config.session.cookieName];
    const session = await resolveSession(token);
    if (session) {
      req.user = {
        id: session.user.id,
        email: session.user.email,
        name: session.user.name,
        role: session.user.role as Role,
        operatorTrackId: session.user.operatorTrackId,
      };
    }
  } catch {
    // ignore — treated as anonymous
  }
  next();
}

export function authenticate(req: AuthRequest, res: Response, next: NextFunction) {
  if (!req.user) return res.status(401).json(error('Authentication required.'));
  next();
}

export function authorize(...roles: Role[]) {
  return (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) return res.status(401).json(error('Authentication required.'));
    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json(error('You do not have permission to do that.'));
    }
    next();
  };
}

import { NextFunction, Request, Response } from 'express';
import { ZodError } from 'zod';
import { Prisma } from '@prisma/client';
import logger from '../utils/logger';
import config from '../config';
import { error } from '../utils/apiResponse';

// eslint-disable-next-line @typescript-eslint/no-unused-vars
export function errorHandler(err: any, _req: Request, res: Response, _next: NextFunction) {
  let status = 500;
  let message = 'Something went wrong.';
  let errors: unknown;

  if (err instanceof ZodError) {
    status = 400;
    message = 'Validation failed.';
    errors = err.issues.map((i) => ({ field: i.path.join('.'), message: i.message }));
  } else if (err instanceof Prisma.PrismaClientKnownRequestError) {
    if (err.code === 'P2002') {
      status = 409;
      message = 'That record already exists.';
    } else if (err.code === 'P2025') {
      status = 404;
      message = 'Record not found.';
    } else if (err.code === 'P2003' || err.code === 'P2014') {
      status = 400;
      message = 'Related record constraint failed.';
    }
  } else if (err?.name === 'JsonWebTokenError' || err?.name === 'TokenExpiredError') {
    status = 401;
    message = 'Invalid or expired token.';
  } else if (typeof err?.status === 'number') {
    status = err.status;
    message = err.message || message;
  }

  if (status >= 500) logger.error(`Unhandled error: ${err?.message}`, err);
  else logger.warn(`Request error (${status}): ${err?.message}`);

  res.status(status).json(
    error(message, errors ?? (config.isProd ? undefined : { detail: String(err?.message || err) }))
  );
}

import { NextFunction, Response } from 'express';
import { AuthRequest } from '../types';
import { gateIsOpenFor, launchWindow } from '../lib/launchPhase';

/**
 * Closes the gated surfaces while the presale runs.
 *
 * Mounted on the reads that make the site feel live — the network list, a venue
 * page, the season read, a rider's calendar, a pass's perks. A signed-out
 * visitor and a free-tier account get 403 with `code: 'PRESALE_GATED'`; staff
 * and anyone holding an active paid pass read straight through, so a presale
 * buyer is not locked out of what they just bought.
 *
 * This is the gate. Hiding a link in the router is not: a venue page is
 * shareable, indexable and reachable by URL, and the API answers the same
 * question either way.
 *
 * `attachUser` runs before every API route, so `req.user` is already the
 * session's account (or undefined) by the time this runs.
 */
export async function presaleGate(req: AuthRequest, res: Response, next: NextFunction) {
  if (await gateIsOpenFor(req.user)) return next();

  const win = launchWindow();
  return res.status(403).json({
    success: false,
    code: 'PRESALE_GATED',
    message: 'The network opens when the presale ends.',
    data: {
      phase: win.phase,
      presaleEndsAt: win.presaleEndsAt ? win.presaleEndsAt.toISOString() : null,
    },
  });
}

import { NextFunction, Request, Response } from 'express';
import { AnyZodObject, ZodError } from 'zod';
import { error } from '../utils/apiResponse';

function handle(err: unknown, res: Response, next: NextFunction) {
  if (err instanceof ZodError) {
    return res.status(400).json(
      error(
        'Validation failed.',
        err.issues.map((i) => ({ field: i.path.join('.'), message: i.message }))
      )
    );
  }
  next(err);
}

/** Validate + coerce req.body against a Zod schema (mutates req.body). */
export function validate(schema: AnyZodObject) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      req.body = schema.parse(req.body);
      next();
    } catch (err) {
      handle(err, res, next);
    }
  };
}

/** Validate + coerce req.query against a Zod schema (mutates req.query). */
export function validateQuery(schema: AnyZodObject) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      const parsed = schema.parse(req.query);
      Object.assign(req.query, parsed);
      next();
    } catch (err) {
      handle(err, res, next);
    }
  };
}

