// ---- Public ----
// `mail` names the live provider ('resend:dev' | 'resend:prod' | 'smtp' | 'none'),
// so a deploy whose signups cannot confirm shows it here instead of looking
// healthy, and the suffix says which key path answered. Informational only: the
// platform health check reads the 200, not this field.
apiRoutes.get('/health', (_req, res) => res.json({ success: true, message: 'ok', mail: mailSummary }));
// The launch window. Never gated: it is the read that tells a client which
// phase it is in and whether the presale gate lets this caller through.
apiRoutes.get('/launch', launch.readLaunch);
// The preview switch drives the server too: it sets the phase the gate reads
// until the next restart. Not gated, but closed to the public in production.
apiRoutes.post('/launch/view', launch.setPreviewView);
// The network and the venue pages are gated during the presale: 403 for a
// visitor or a free-tier account, straight through for staff and paid passes.
// `/tiers` stays open — the pricing page and the presale page both sell from it.
apiRoutes.get('/tracks', presaleGate, tracks.listTracks);
apiRoutes.get('/tracks/:slug', presaleGate, tracks.getTrack);
apiRoutes.get('/tiers', tracks.listTiers);
apiRoutes.get('/season', presaleGate, tracks.currentSeason);

// ---- Auth ----
apiRoutes.post('/auth/register', validate(auth.registerSchema), auth.register);
apiRoutes.post('/auth/login', validate(auth.loginSchema), auth.login);
// The step between the two: a new account is not a login until the address is
// confirmed.
//
// Spending a link is one-shot by construction — the row is retired the moment it
// works, so a second click on the same mail is refused, not re-run. The IP
// limiter only has to stop a host walking tokens, so it stays roomy enough for
// the suites (which sign up and confirm from one address).
const verifyLimiter = rateLimit({
  windowMs: 15 * 60_000,
  limit: 30,
  standardHeaders: true,
  legacyHeaders: false,
  message: { success: false, message: 'Too many requests. Try again in a few minutes.' },
});
//
// Asking for another link costs an email, so it carries three brakes: this IP
// limiter, plus a per-account gap and a per-account daily ceiling inside the
// handler. None of them is visible to the caller.
//
// The per-account pair is what actually bounds the mail budget: one inbox gets
// five links a day, one minute ten seconds apart. The IP ceiling is a coarse
// guard against a host walking many addresses, so it has to stay loose enough
// that riders sharing one address never spend each other's allowance — a
// carrier NAT, an office, the dev box's own test runs. At six per window, one
// click was already being refused because someone else on the same address had
// used the bucket.
const resendLimiter = rateLimit({
  windowMs: 15 * 60_000,
  limit: 30,
  standardHeaders: true,
  legacyHeaders: false,
  message: { success: false, message: 'Too many requests. Try again in a few minutes.' },
});
apiRoutes.post(
  '/auth/verify-email',
  verifyLimiter,
  validate(auth.verifyEmailSchema),
  auth.verifyEmail
);
apiRoutes.post(
  '/auth/verify-email/resend',
  resendLimiter,
  validate(auth.resendVerificationSchema),
  auth.resendVerification
);
// A rider who cannot sign in: ask for a reset link, then spend it. All three are
// public, and the token is the only credential the reset needs.
// Throttled well below the app-wide limiter: a reset request costs an email.
const resetLimiter = rateLimit({
  windowMs: 15 * 60_000,
  limit: 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: { success: false, message: 'Too many reset requests. Try again in a few minutes.' },
});
apiRoutes.post(
  '/auth/forgot-password',
  resetLimiter,
  validate(auth.forgotPasswordSchema),
  auth.forgotPassword
);
apiRoutes.get('/auth/reset-password/:token', auth.checkResetToken);
apiRoutes.post(
  '/auth/reset-password',
  resetLimiter,
  validate(auth.resetPasswordSchema),
  auth.resetPassword
);
apiRoutes.post('/auth/logout', auth.logout);
apiRoutes.get('/auth/me', auth.me);
apiRoutes.patch('/auth/me', authenticate, auth.updateProfile);
// The rider's own photo. A data URL in, a managed reference out; 5 MB decoded.
