// ---- Rider ----
const rider = Router();
rider.use(authenticate);
rider.get('/pass', pass.myPass);
// A paid rider's own unsubscribe: retires the pass and falls back to free.
rider.post('/pass/cancel', authorize(Role.RIDER, Role.ADMIN), pass.cancelPass);
rider.get('/qr-token', pass.qrToken);
rider.get('/history', pass.myHistory);
rider.get('/denied-scans', pass.myDeniedScans);
// The three reads that are the network seen from a rider's seat — the venue
