import crypto from 'crypto';
import { prisma } from '../utils/prisma';
import { appUrl, sendVerificationEmail } from './mail.service';

/**
 * The sign-up link. Same shape as `passwordReset.service`: 32 random bytes are
 * handed to the rider once, only the SHA-256 is stored, and one live token per
 * account — issuing another retires the older unused rows.
 *
 * A link lives longer than a reset (a rider signs up and reads their mail
 * later), so the TTL is hours, not minutes.
 */

const TTL_HOURS = Number(process.env.VERIFY_TOKEN_TTL_HOURS || 24);

/**
 * How long one account waits between links.
 *
 * The route limiter counts requests per IP; this counts links per inbox, so a
 * rider reloading the card (or a shared IP, or a second device) cannot mail
 * themselves repeatedly. It reads the newest row rather than a `Map`, so a
 * restart does not hand back the allowance, and the client shows the same
 * number as its countdown. Default: 1 min 10 s.
 */
export const VERIFY_RESEND_GAP_MS = Number(process.env.VERIFY_RESEND_GAP_SEC || 70) * 1_000;

/**
 * Links one account may be sent per rolling day. Counted from the audit trail,
 * because issuing a token deletes the unused rows behind it — the cap has to
 * outlive the rows it counts.
 */
export const VERIFY_RESEND_DAILY_CAP = Number(process.env.VERIFY_RESEND_DAILY_CAP || 5);

/** What to tell a rider who is still inside the daily cap's shadow. */
const CAP_WAIT_MS = 15 * 60_000;

export const hashVerifyToken = (token: string) =>
  crypto.createHash('sha256').update(token).digest('hex');

export const verifyLinkFor = (token: string) =>
  `${appUrl()}/verify-email?token=${encodeURIComponent(token)}`;

export async function issueVerificationToken(
  userId: string
): Promise<{ token: string; expiresAt: Date }> {
  // A rider who asks twice gets the newest link and the older one stops working.
  await prisma.emailVerification.deleteMany({ where: { userId, usedAt: null } });

  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + TTL_HOURS * 3_600_000);
  await prisma.emailVerification.create({
    data: { userId, tokenHash: hashVerifyToken(token), expiresAt },
  });
  return { token, expiresAt };
}

/** The row behind a raw token, with its user — `null` when it is unknown. */
export async function findVerification(rawToken: string) {
  if (!rawToken || rawToken.length < 16) return null;
  return prisma.emailVerification.findUnique({
    where: { tokenHash: hashVerifyToken(rawToken) },
    include: { user: true },
  });
}

export function verificationIsUsable(row: {
  usedAt: Date | null;
  expiresAt: Date;
  user: { isActive: boolean; emailVerifiedAt: Date | null };
}): boolean {
  return !row.usedAt && row.expiresAt.getTime() > Date.now() && row.user.isActive;
}

/** Issue a token and mail the link. The caller decides what to tell the browser. */
export async function sendVerificationLink(user: { id: string; email: string; name: string }) {
  const { token, expiresAt } = await issueVerificationToken(user.id);
  const link = verifyLinkFor(token);
  const result = await sendVerificationEmail({
    to: user.email,
    name: user.name,
    link,
    expiresAt,
  });
  // One row per link mailed: `resendWaitMs` counts these for the daily cap, and
  // the trail survives the row deletes that issuing another token performs.
  await prisma.auditLog
    .create({
      data: {
        actorId: user.id,
        action: 'VERIFY_EMAIL_SENT',
        entity: 'User',
        entityId: user.id,
        meta: JSON.stringify({ delivered: result.delivered }),
      },
    })
    .catch(() => undefined);
  return { link, expiresAt, delivered: result.delivered, reason: result.reason };
}

/**
 * May this account be mailed another link right now? Returns the wait in ms —
 * `0` means send it — so the caller can say "not yet" without touching the mail
 * service and can hand the rider a countdown.
 *
 * Two brakes, both keyed on the account rather than the caller's IP: the gap
 * between links, and a rolling daily ceiling. A resend that lands inside either
 * one is answered with the same copy as one that was sent, so this never
 * becomes a way to probe an address.
 */
export async function resendWaitMs(userId: string): Promise<number> {
  const newest = await prisma.emailVerification.findFirst({
    where: { userId },
    orderBy: { createdAt: 'desc' },
    select: { createdAt: true },
  });
  if (newest) {
    const gapLeft = newest.createdAt.getTime() + VERIFY_RESEND_GAP_MS - Date.now();
    if (gapLeft > 0) return gapLeft;
  }

  const sentToday = await prisma.auditLog.count({
    where: {
      actorId: userId,
      action: 'VERIFY_EMAIL_SENT',
      createdAt: { gte: new Date(Date.now() - 24 * 3_600_000) },
    },
  });
  return sentToday >= VERIFY_RESEND_DAILY_CAP ? CAP_WAIT_MS : 0;
}

import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import nodemailer, { Transporter } from 'nodemailer';
import logger from '../utils/logger';

/**
 * Outbound mail. One transport, lazily built from the environment, with a
 * console fallback so the reset flow is exercisable on a box with no mail
 * account: when neither a Resend key nor `SMTP_HOST` is set the message is
 * printed instead of sent and `delivered` comes back `false` (the controller
 * then hands the link back to the browser in non-production, which is what
 * makes the flow testable).
 *
 * Two providers, picked from the environment in this order:
 *   RESEND_API_KEY_DEV   in development, RESEND_API_KEY_PROD in production —
 *                   Resend's HTTP API (https://api.resend.com/emails). The key
 *                   is enough: no host, port or user. The `from` domain must be
 *                   verified on that key's account or every send is refused 403.
 *                   A process reads only its own environment's key: a laptop
 *                   cannot send with the live key and a deploy never falls back
 *                   to the dev one. `RESEND_API_KEY` (no suffix) is still read in
 *                   development only, so an older checkout keeps sending.
 *   SMTP_HOST       Plain SMTP through nodemailer (Resend's own SMTP endpoint
 *                   works here too: smtp.resend.com, user `resend`, pass = key;
 *                   on App Platform use port 2465 or 2587 — 25/465/587 are blocked).
 * Anything else prints to the log.
 *
 * Read from `process.env` rather than `config` on purpose — `config/index.ts` is
 * read by every process and its keys are grouped by subsystem; mail is one
 * consumer.
 */

const env = (key: string) => (process.env[key] || '').trim();

const IS_PROD = env('NODE_ENV') === 'production';
/** Which key path this process is on. Read by the health line and the probe. */
export const mailEnv: 'dev' | 'prod' = IS_PROD ? 'prod' : 'dev';
const RESEND_KEY_VAR = IS_PROD ? 'RESEND_API_KEY_PROD' : 'RESEND_API_KEY_DEV';
const RESEND_API_KEY = env(RESEND_KEY_VAR) || (IS_PROD ? '' : env('RESEND_API_KEY'));
const RESEND_ENDPOINT = 'https://api.resend.com/emails';
/** Per attempt. Node's fetch has no deadline of its own, so a stalled provider
    would otherwise hold the send for minutes. */
const RESEND_TIMEOUT_MS = 10_000;
/** Wait before the single retry (429, 5xx, network error or timeout only). */
const RESEND_RETRY_DELAY_MS = 1_000;

/** The dev key, exported for scripts/probe-mail.ts, which lists the account's
    domains before it sends. Nothing else should read it, and it is never logged. */
export const resendKey = RESEND_API_KEY;

// Two misconfigurations worth one line each at boot, because both look healthy
// from the outside: a dev box on the legacy variable name, and a deploy that has
// only the dev key (which it will not use, so every send prints instead).
if (IS_PROD && !RESEND_API_KEY && env('RESEND_API_KEY_DEV')) {
  logger.warn('[mail] RESEND_API_KEY_PROD is unset — the dev key is not used in production');
} else if (!IS_PROD && !env('RESEND_API_KEY_DEV') && RESEND_API_KEY) {
  logger.warn('[mail] reading legacy RESEND_API_KEY — rename it to RESEND_API_KEY_DEV');
}
// Same shape for the link origin: a deploy with only the dev URL would build
// every confirm/reset link against a host the rider cannot reach.
if (IS_PROD && !env('APP_PUBLIC_URL_PROD') && env('APP_PUBLIC_URL_DEV')) {
  logger.warn('[mail] APP_PUBLIC_URL_PROD is unset — the dev origin is not used in production');
}

const SMTP_HOST = env('SMTP_HOST');
const SMTP_PORT = Number(env('SMTP_PORT') || 587);
const SMTP_SECURE = env('SMTP_SECURE') === 'true' || SMTP_PORT === 465;
const SMTP_USER = env('SMTP_USER');
const SMTP_PASS = env('SMTP_PASS');
/** The envelope sender. Per-environment when a box has its own verified domain:
    `MAIL_FROM_DEV` / `MAIL_FROM_PROD` win over `MAIL_FROM`. */
const MAIL_FROM =
  env(`MAIL_FROM_${IS_PROD ? 'PROD' : 'DEV'}`) ||
  env('MAIL_FROM') ||
  'Moto Pass <no-reply@motopass.example.com>';
/** Optional: one reply-to for every message, when replies should reach a person. */
const MAIL_REPLY_TO = env('MAIL_REPLY_TO');
/** The envelope sender every message leaves as. `MAIL_FROM` must be on a domain
    verified with the provider, or the send is refused. */
export const mailFrom = MAIL_FROM;

/** The public origin every absolute link is built from — the confirm and reset
    links in mail today, anything else that needs a host later. Per-environment
    like the mail keys: `APP_PUBLIC_URL_DEV` in development, `APP_PUBLIC_URL_PROD`
    in production. A deploy never reads the dev origin, so a tailnet or localhost
    URL cannot leak into a live message. The unsuffixed `APP_PUBLIC_URL` is a
    development-only fallback, so an older checkout keeps linking correctly. */
const APP_PUBLIC_URL_VAR = IS_PROD ? 'APP_PUBLIC_URL_PROD' : 'APP_PUBLIC_URL_DEV';
const APP_PUBLIC_URL = env(APP_PUBLIC_URL_VAR) || (IS_PROD ? '' : env('APP_PUBLIC_URL'));

/** The public origin a reset link points at — where the rider's browser lands. */
export const appUrl = (): string =>
  (APP_PUBLIC_URL || env('CORS_ORIGIN') || 'http://localhost:5180').replace(/\/+$/, '');

export const mailConfigured = Boolean(RESEND_API_KEY || SMTP_HOST);
/** Which provider a send would use — read by the diagnostics script and health logs. */
export const mailProvider: 'resend' | 'smtp' | 'none' = RESEND_API_KEY
  ? 'resend'
  : SMTP_HOST
    ? 'smtp'
    : 'none';
/** `resend:dev` / `resend:prod` — the provider plus the key path in use, for the
    health payload and boot log. SMTP and the printed fallback carry no path. */
export const mailSummary = mailProvider === 'resend' ? `resend:${mailEnv}` : mailProvider;

/** HTML-escape a value placed into a message body or attribute. */
const HTML_ESCAPES: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};
const esc = (value: string): string => value.replace(/[&<>"']/g, (ch) => HTML_ESCAPES[ch]);

/** The brand lockup carried in a message header — an inline part, not a URL.
 *
 *  A remote image is the obvious build and it does not work here. The dev
 *  origin is a `*.ts.net` host, reachable only from the tailnet, and the image
 *  is fetched by the recipient's client or its proxy (Gmail's), never by the
 *  rider's browser: a tailnet host answers nothing to Google, so the header
 *  arrives as a broken image. An inline `cid:` part travels inside the message
 *  and needs no route to this box at all, on any provider.
 *
 *  The bytes come from the same PNG the app serves (`make-email-logo.mjs`
 *  writes it from `/assets/moto-pass-logo.svg`), read once at boot. Read off
 *  `__dirname` because App Platform runs `node server/dist/index.js` from the
 *  repo root: `dist/services` and `src/services` are both three levels down.
 *
 *  A PNG rather than the SVG because webmail strips `<svg>` from a body and
 *  Gmail strips `data:` URIs; the ink is baked in because the source SVG fills
 *  with `currentColor`, which nothing supplies to an `<img>`. When the file
 *  cannot be read the header falls back to a public URL, so a broken deploy
 *  loses the picture, not the mail. */
const LOGO_FILE = path.join(__dirname, '../../../client/public/assets/moto-pass-logo.png');
const LOGO_CID = 'motopass-logo@getmotopass';
const logoBase64 = ((): string => {
  try {
    return fs.readFileSync(LOGO_FILE).toString('base64');
  } catch {
    logger.warn(`[mail] logo not readable at ${LOGO_FILE} — headers fall back to a URL`);
    return '';
  }
})();

export interface MailAttachment {
  filename: string;
  /** base64, no data: prefix — both providers take it in this form. */
  content: string;
  contentType: string;
  /** The `cid:` a body part points at. */
  contentId: string;
}

/** The header markup plus the attachment that fills it. */
function mailLogo(): { html: string; attachments: MailAttachment[] } {
  const style =
    'display:block;width:62px;height:40px;border:0;outline:none;text-decoration:none;margin:0 0 18px;';
  if (!logoBase64) {
    return {
      html: `<img src="${esc(`${appUrl()}/assets/moto-pass-logo.png`)}" alt="Moto Pass" width="62" height="40" style="${style}">`,
      attachments: [],
    };
  }
  return {
    // alt is the wordmark the image stands for, so a client that hides
    // attachments still shows "Moto Pass" in that spot.
    html: `<img src="cid:${LOGO_CID}" alt="Moto Pass" width="62" height="40" style="${style}">`,
    attachments: [
      {
        filename: 'moto-pass-logo.png',
        content: logoBase64,
        contentType: 'image/png',
        contentId: LOGO_CID,
      },
    ],
  };
}

export interface MailMessage {
  to: string;
  subject: string;
  text: string;
  html: string;
  /** Inline images the HTML points at by `cid:`. */
  attachments?: MailAttachment[];
}

let transport: Transporter | null = null;

function getTransport(): Transporter | null {
  if (mailProvider !== 'smtp') return null;
  if (!transport) {
    transport = nodemailer.createTransport({
      host: SMTP_HOST,
      port: SMTP_PORT,
      secure: SMTP_SECURE,
      auth: SMTP_USER ? { user: SMTP_USER, pass: SMTP_PASS } : undefined,
      connectionTimeout: 10_000, // fail fast on a blocked port instead of hanging
      greetingTimeout: 10_000,
      socketTimeout: 15_000,
    });
  }
  return transport;
}

/** Resend's error body is `{ statusCode, name, message }`; surface `message`. */
async function describeResendFailure(res: Response): Promise<string> {
  const body = await res.text().catch(() => '');
  try {
    const parsed = JSON.parse(body) as { message?: string; name?: string };
    const detail = parsed.message || parsed.name;
    if (detail) return `${res.status} ${detail}`;
  } catch {
    /* not JSON — fall through to the raw body */
  }
  return `${res.status} ${body.slice(0, 300) || res.statusText}`.trim();
}

async function sendViaResend(message: MailMessage): Promise<MailResult> {
  const payload: Record<string, unknown> = {
    from: MAIL_FROM,
    to: [message.to],
    subject: message.subject,
    text: message.text,
    html: message.html,
  };
  if (MAIL_REPLY_TO) payload.reply_to = MAIL_REPLY_TO;
  // Inline parts: `content_id` is what makes Resend bind the part to the body's
  // `cid:` reference instead of listing it as a download.
  if (message.attachments?.length) {
    payload.attachments = message.attachments.map((a) => ({
      filename: a.filename,
      content: a.content,
      content_type: a.contentType,
      content_id: a.contentId,
    }));
  }
  // The same key rides on the retry, so Resend sends at most one copy.
  const idempotencyKey = crypto.randomUUID();

  let reason = 'unknown';
  for (let attempt = 1; attempt <= 2; attempt++) {
    let retryable = false;
    try {
      const res = await fetch(RESEND_ENDPOINT, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${RESEND_API_KEY}`,
          'Content-Type': 'application/json',
          'Idempotency-Key': idempotencyKey,
        },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(RESEND_TIMEOUT_MS), // per-attempt deadline
      });
      if (res.ok) {
        const sent = (await res.json().catch(() => ({}))) as { id?: string };
        logger.info(`[mail] resend(${mailEnv}) accepted ${message.to} (${sent.id ?? 'no id'})`);
        return { delivered: true, id: sent.id };
      }
      reason = await describeResendFailure(res);
      retryable = res.status === 429 || res.status >= 500; // other 4xx will not change on retry
    } catch (err) {
      // Network/DNS/TLS/timeout — the message did not leave the box.
      const e = err as Error;
      reason = e.name === 'TimeoutError' ? `timed out after ${RESEND_TIMEOUT_MS} ms` : e.message;
      retryable = true;
    }
    if (!retryable || attempt === 2) break;
    logger.warn(`[mail] resend(${mailEnv}) attempt ${attempt} for ${message.to} failed (${reason}); retrying`);
    await new Promise((resolve) => setTimeout(resolve, RESEND_RETRY_DELAY_MS));
  }

  logger.error(`[mail] resend(${mailEnv}) rejected ${message.to}: ${reason}`);
  return { delivered: false, reason: `resend: ${reason}` };
}

export interface MailResult {
  delivered: boolean;
  reason?: string;
  /** The provider's message id, when it hands one back. */
  id?: string;
}

export async function sendMail(message: MailMessage): Promise<MailResult> {
  if (mailProvider === 'resend') return sendViaResend(message);

  const t = getTransport();
  if (!t) {
    // Console fallback. Off production the whole message prints so the link can
    // be copied out of the API log. In production the body is withheld: it
    // carries a live confirm or reset link, and the log has more readers than
    // the inbox it was meant for.
    logger.warn(
      `[mail] no mail provider configured — printing instead of sending\n` +
        `  to:      ${message.to}\n` +
        `  subject: ${message.subject}\n` +
        (IS_PROD
          ? '  (body withheld in production: it carries a live link)'
          : message.text.replace(/^/gm, '  '))
    );
    return { delivered: false, reason: 'no-provider' };
  }

  try {
    // nodemailer takes the bytes, not base64: `cid` is the token the body's
    // `cid:` reference resolves to, and it must match the content id emitted
    // in the HTML.
    const attachments = message.attachments?.map((a) => ({
      filename: a.filename,
      content: Buffer.from(a.content, 'base64'),
      contentType: a.contentType,
      cid: a.contentId,
    }));
    const info = await t.sendMail({ from: MAIL_FROM, ...message, attachments });
    return { delivered: true, id: info.messageId };
  } catch (err) {
    logger.error(`[mail] send failed for ${message.to}: ${(err as Error).message}`);
    return { delivered: false, reason: 'send-failed' };
  }
}

/** The password-reset message. Plain text first — it is what most clients show. */
export async function sendPasswordResetEmail(opts: {
  to: string;
  name: string;
  link: string;
  expiresAt: Date;
}): Promise<MailResult> {
  const minutes = Math.max(1, Math.round((opts.expiresAt.getTime() - Date.now()) / 60_000));
  const text = [
    `Hi ${opts.name},`,
    '',
    'Use this link to set a new password on your Moto Pass account:',
    opts.link,
    '',
    `The link works once and expires in ${minutes} minutes.`,
    'If you did not ask for it, ignore this email — your password stays as it is.',
    '',
    'Moto Pass',
  ].join('\n');

  const name = esc(opts.name); // escaped for the HTML part only; the text part stays raw
  const link = esc(opts.link);
  const html = `<!doctype html>
<html><body style="margin:0;padding:24px;background:#0d0f12;color:#e8eaed;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;">
  <div style="max-width:520px;margin:0 auto;background:#171a1f;border:1px solid #2a2f36;border-radius:12px;padding:28px;">
    <p style="margin:0 0 18px;font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#ff8a3f;">Moto Pass</p>
    <h1 style="margin:0 0 14px;font-size:20px;font-weight:600;">Set a new password</h1>
    <p style="margin:0 0 20px;color:#b6bcc6;line-height:1.55;">Hi ${name}, use the button below to choose a new password for your account.</p>
    <p style="margin:0 0 20px;"><a href="${link}" style="display:inline-block;background:#ff8a3f;color:#12140f;text-decoration:none;font-weight:600;padding:12px 20px;border-radius:8px;">Choose a new password</a></p>
    <p style="margin:0 0 8px;color:#b6bcc6;line-height:1.55;">The link works once and expires in ${minutes} minutes.</p>
    <p style="margin:0 0 20px;color:#b6bcc6;line-height:1.55;">If you did not ask for it, ignore this email — your password stays as it is.</p>
    <p style="margin:0;font-size:12px;color:#7d848f;word-break:break-all;">${link}</p>
  </div>
</body></html>`;

  return sendMail({ to: opts.to, subject: 'Set a new password on Moto Pass', text, html });
}

/** The sign-up message: the one link that turns a new account into a login. */
export async function sendVerificationEmail(opts: {
  to: string;
  name: string;
  link: string;
  expiresAt: Date;
}): Promise<MailResult> {
  const hours = Math.max(1, Math.round((opts.expiresAt.getTime() - Date.now()) / 3_600_000));
  const text = [
    `Hi ${opts.name},`,
    '',
    'Confirm this address to finish setting up your Moto Pass account:',
    opts.link,
    '',
    `The link expires in ${hours} ${hours === 1 ? 'hour' : 'hours'}.`,
    'If you did not sign up, ignore this email and the account stays unused.',
    '',
    'Moto Pass',
  ].join('\n');

  const name = esc(opts.name); // escaped for the HTML part only; the text part stays raw
  const link = esc(opts.link);
  const logo = mailLogo(); // once: the markup and the part it points at
  const html = `<!doctype html>
<html><body style="margin:0;padding:24px;background:#0d0f12;color:#e8eaed;font-family:system-ui,-apple-system,'Segoe UI',sans-serif;">
  <div style="max-width:520px;margin:0 auto;background:#171a1f;border:1px solid #2a2f36;border-radius:12px;padding:28px;">
    ${logo.html}
    <h1 style="margin:0 0 14px;font-size:20px;font-weight:600;">Confirm your email</h1>
    <p style="margin:0 0 20px;color:#b6bcc6;line-height:1.55;">Hi ${name}, click the button below to confirm your email.</p>
    <p style="margin:0 0 20px;"><a href="${link}" style="display:inline-block;background:#ff8a3f;color:#12140f;text-decoration:none;font-weight:600;padding:12px 20px;border-radius:8px;">Confirm email</a></p>
    <p style="margin:0 0 8px;color:#b6bcc6;line-height:1.55;">The link expires in ${hours} ${hours === 1 ? 'hour' : 'hours'}.</p>
    <p style="margin:0 0 20px;color:#b6bcc6;line-height:1.55;">If you did not sign up, ignore this email and the account stays unused.</p>
    <p style="margin:0;font-size:12px;color:#7d848f;word-break:break-all;">${link}</p>
  </div>
</body></html>`;

  return sendMail({
    to: opts.to,
    subject: 'Confirm your email on Moto Pass',
    text,
    html,
    attachments: logo.attachments,
  });
}

import { randomUUID } from 'node:crypto';
import { constants } from 'node:fs';
import fs from 'node:fs/promises';
import path from 'node:path';
import { DeleteObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import sharp from 'sharp';
import { config } from '../config';

export interface MediaStoreSettings {
  spaces: {
    provider: 'local' | 'spaces';
    region: string;
    bucket: string;
    publicBase: string;
    key: string;
    secret: string;
  };
  uploads: { dir: string; publicPath: string; maxBytes: number };
}

/** Inject a sender in tests; it does not constitute live Spaces verification. */
export interface MediaS3Sender {
  send(command: PutObjectCommand | DeleteObjectCommand): Promise<unknown>;
}

export interface MediaStoreDependencies {
  s3?: MediaS3Sender;
  logger?: { warn(message: string): void };
}

export type MediaKind = 'banner' | 'logo' | 'photo' | 'review' | 'avatar';
export type MediaStoreResult = { url: string } | { status: number; message: string };

const UUID_SOURCE = '[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
const UUID = new RegExp(`^${UUID_SOURCE}$`, 'i');
const MANAGED_KEY = new RegExp(
  `^tracks/${UUID_SOURCE}/(?:banner|logo|gallery|reviews/${UUID_SOURCE})/${UUID_SOURCE}\\.(?:png|jpg|webp|gif|avif)$`,
  'i'
);
// A rider avatar hangs off the user UUID. `\u002e` is a literal dot, written this
// way so the pattern survives edits that would otherwise mangle backslashes.
const AVATAR_KEY = new RegExp(
  `^users/${UUID_SOURCE}/avatar/${UUID_SOURCE}\\u002e(?:png|jpg|webp|gif|avif)$`,
  'i'
);
// Names emitted by the former owner.controller storage helper, not arbitrary assets.
const LEGACY_FILE = /^[a-z0-9][a-z0-9-]*-(?:banner|logo|photo|review)-[0-9a-f]{8}\.(?:png|jpe?g|webp|gif|avif)$/i;
const MEDIA_PREFIX = '/api/media/';
const MAX_INPUT_PIXELS = 40_000_000;
const MIME_FORMAT: Record<string, 'png' | 'jpeg' | 'webp' | 'gif' | 'avif'> = {
  png: 'png', jpg: 'jpeg', jpeg: 'jpeg', webp: 'webp', gif: 'gif', avif: 'avif',
};
const FORMAT_EXT: Record<string, string> = {
  png: 'png', jpeg: 'jpg', webp: 'webp', gif: 'gif', avif: 'avif',
};

export function isManagedMediaKey(key: string): boolean {
  return typeof key === 'string' && key.length <= 300 && (MANAGED_KEY.test(key) || AVATAR_KEY.test(key));
}

/** An exact managed reference only: never infer ownership from an external CDN URL. */
function referenceKey(reference: string, prefix: string, allowLegacy = false): string | null {
  if (typeof reference !== 'string' || !reference.startsWith(prefix)) return null;
  const key = reference.slice(prefix.length);
  return isManagedMediaKey(key) || (allowLegacy && LEGACY_FILE.test(key)) ? key : null;
}

export class MediaStore {
  private readonly settings: MediaStoreSettings;
  private readonly s3?: MediaS3Sender;
  private readonly logger: { warn(message: string): void };
  private readonly publicBase: string | null;

  constructor(settings: MediaStoreSettings, dependencies: MediaStoreDependencies = {}) {
    // Snapshot config so the active provider/credentials cannot change mid-operation.
    this.settings = { spaces: { ...settings.spaces }, uploads: { ...settings.uploads } };
    this.logger = dependencies.logger ?? console;
    const { spaces, uploads } = this.settings;
    if (spaces.provider !== 'local' && spaces.provider !== 'spaces') {
      throw new Error('Invalid media storage provider.');
    }
    if (!Number.isSafeInteger(uploads.maxBytes) || uploads.maxBytes <= 0 || !uploads.dir
      || uploads.publicPath !== '/api/uploads') {
      throw new Error('Invalid local media storage settings.');
    }
    this.publicBase = this.validatePublicBase(spaces.publicBase);
    if (spaces.provider === 'spaces') {
      if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(spaces.region)
        || !/^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$/.test(spaces.bucket)
        || !this.publicBase || !spaces.key.trim() || !spaces.secret.trim()) {
        throw new Error('Spaces media storage requires region, bucket, public base URL, key and secret.');
      }
      this.s3 = dependencies.s3 ?? new S3Client({
        region: spaces.region,
        endpoint: `https://${spaces.region}.digitaloceanspaces.com`,
        credentials: { accessKeyId: spaces.key, secretAccessKey: spaces.secret },
        maxAttempts: 3,
        requestHandler: { connectionTimeout: 5_000, requestTimeout: 15_000 },
      });
    }
  }

  private validatePublicBase(value: string): string | null {
    if (!value) return null;
    try {
      const url = new URL(value);
      if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash
        || /[\s\\]/.test(value)) return null;
      return value.replace(/\/+$/, '');
    } catch {
      return null;
    }
  }

  /** Resolve old references using today's bucket/CDN base, without rewriting DB rows.
   * Returns null while a bucket/base is not configured, even on local installs. */
  resolveMediaUrl(referenceOrKey: string): string | null {
    if (!this.settings.spaces.bucket || !this.publicBase) return null;
    const key = isManagedMediaKey(referenceOrKey)
      ? referenceOrKey : referenceKey(referenceOrKey, MEDIA_PREFIX);
    return key ? `${this.publicBase}/${key}` : null;
  }

  async storeDataUrl(scope: string, kind: MediaKind, dataUrl: string, reviewId?: string): Promise<MediaStoreResult> {
    if (!UUID.test(scope) || !['banner', 'logo', 'photo', 'review', 'avatar'].includes(kind)
      || (kind === 'review' && (!reviewId || !UUID.test(reviewId)))) {
      return { status: 400, message: 'Invalid media scope.' };
    }
    const decoded = await this.decodeImage(dataUrl);
    if ('status' in decoded) return decoded;
    const slot = kind === 'photo' ? 'gallery' : kind === 'review' ? `reviews/${reviewId}` : kind;
    // A rider avatar hangs off the user, not a track; both are immutable UUID paths.
    const key = kind === 'avatar'
      ? `users/${scope}/avatar/${randomUUID()}.${decoded.ext}`
      : `tracks/${scope}/${slot}/${randomUUID()}.${decoded.ext}`;
    try {
      if (this.settings.spaces.provider === 'spaces') {
        await this.s3!.send(new PutObjectCommand({
          Bucket: this.settings.spaces.bucket,
          Key: key,
          Body: decoded.bytes,
          ACL: 'public-read',
          ContentType: decoded.contentType,
          CacheControl: 'public, max-age=86400',
        }));
        return { url: `${MEDIA_PREFIX}${key}` };
      }
      const parent = await this.localParent(key, true);
      if (!parent) throw new Error('Media directory unavailable.');
      // Immutable full-UUID names; never remove a previous slot or prefix here.
      const file = await fs.open(path.join(parent, path.basename(key)),
        constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW, 0o644);
      try {
        await file.writeFile(decoded.bytes);
      } finally {
        await file.close();
      }
      return { url: `${this.settings.uploads.publicPath}/${key}` };
    } catch {
      this.warn('upload');
      return { status: 503, message: 'Image storage is unavailable. Please try again.' };
    }
  }

  private async decodeImage(dataUrl: string): Promise<
    { bytes: Buffer; ext: string; contentType: string } | { status: number; message: string }
  > {
    const invalid = { status: 400, message: 'Upload a valid PNG, JPG, WEBP, GIF or AVIF image.' };
    const tooLarge = { status: 413, message: 'That image is too large — keep it under 5 MB.' };
    if (typeof dataUrl !== 'string') return invalid;
    const comma = dataUrl.indexOf(',');
    if (comma < 0 || comma > 40) return invalid;
    const header = /^data:image\/(png|jpe?g|webp|gif|avif);base64$/i.exec(dataUrl.slice(0, comma));
    if (!header) return invalid;
    const maxEncoded = 4 * Math.ceil(this.settings.uploads.maxBytes / 3);
    // Before slicing the body, running a large regex, or allocating decoded bytes.
    if (dataUrl.length - comma - 1 > maxEncoded) return tooLarge;
    const body = dataUrl.slice(comma + 1);
    if (!body || body.length % 4 !== 0
      || !/^[A-Za-z0-9+/]*={0,2}$/.test(body)) return invalid;
    const size = body.length / 4 * 3 - (body.endsWith('==') ? 2 : body.endsWith('=') ? 1 : 0);
    if (size > this.settings.uploads.maxBytes) return tooLarge;
    const input = Buffer.from(body, 'base64');
    if (input.toString('base64') !== body) return invalid;
    const expected = MIME_FORMAT[header[1].toLowerCase()];
    try {
      const pipeline = sharp(input, { limitInputPixels: MAX_INPUT_PIXELS, animated: true, failOn: 'warning' });
      const metadata = await pipeline.metadata();
      // libvips reports AVIF as HEIF: only the AV1 variant is permitted, not HEIC.
      const actual = metadata.format === 'heif' && metadata.compression === 'av1' ? 'avif' : metadata.format;
      if (actual !== expected || !metadata.width || !metadata.height
        || metadata.width * metadata.height > MAX_INPUT_PIXELS) return invalid;
      // Re-encode to the SAME format (including animation). Sharp strips EXIF/XMP/ICC
      // by default. Decoding all pixels here also rejects truncated/spoofed bodies.
      // AVIF cannot be written losslessly by every libvips build, so use its encoder
      // defaults; do not silently convert it (or any other input) into WebP.
      const bytes = await pipeline.toFormat(expected).toBuffer();
      if (bytes.length > this.settings.uploads.maxBytes) return tooLarge;
      return { bytes, ext: FORMAT_EXT[expected], contentType: `image/${expected}` };
    } catch {
      return invalid;
    }
  }

  /** Walk only safe directories below the configured root; reject symlink parents. */
  private async localParent(key: string, create: boolean): Promise<string | null> {
    if (create) await fs.mkdir(this.settings.uploads.dir, { recursive: true });
    let current: string;
    try {
      current = await fs.realpath(this.settings.uploads.dir);
    } catch (err) {
      if (!create && (err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
    for (const segment of key.split('/').slice(0, -1)) {
      current = path.join(current, segment);
      if (create) {
        try { await fs.mkdir(current); } catch (err) {
          if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err;
        }
      }
      let entry;
      try { entry = await fs.lstat(current); } catch (err) {
        if (!create && (err as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw err;
      }
      if (!entry.isDirectory() || entry.isSymbolicLink()) throw new Error('Unsafe media directory.');
    }
    return current;
  }

  /** Strict deletion is available to maintenance/tests. Never accepts an external URL,
   * bare key, seed asset, directory, query string, encoded path or traversal. */
  async deleteManagedFile(reference: string): Promise<void> {
    const remote = referenceKey(reference, MEDIA_PREFIX);
    if (remote) {
      if (this.settings.spaces.provider !== 'spaces' || !this.s3) return;
      await this.s3.send(new DeleteObjectCommand({ Bucket: this.settings.spaces.bucket, Key: remote }));
      return;
    }
    const local = referenceKey(reference, `${this.settings.uploads.publicPath}/`, true);
    if (!local) return;
    const parent = await this.localParent(local, false);
    if (!parent) return;
    try {
      const file = path.join(parent, path.basename(local));
      const entry = await fs.lstat(file);
      if (!entry.isFile() || entry.isSymbolicLink()) return;
      await fs.unlink(file);
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
    }
  }

  /** Cleanup after a DB commit is best effort: storage outages must not undo HTTP success. */
  async removeUploadedFile(reference: string): Promise<void> {
    try { await this.deleteManagedFile(reference); } catch { this.warn('cleanup'); }
  }

  private warn(operation: 'upload' | 'cleanup'): void {
    // Do not log SDK errors, request URLs, object data or credentials. Even a custom
    // logger must not turn post-commit cleanup into an HTTP error.
    try { this.logger.warn(`Media ${operation} failed (${this.settings.spaces.provider}).`); } catch { /* best effort */ }
  }
}

export const mediaStore = new MediaStore({ spaces: config.spaces, uploads: config.uploads });
export const storeDataUrl = (scope: string, kind: MediaKind, dataUrl: string, reviewId?: string) =>
  mediaStore.storeDataUrl(scope, kind, dataUrl, reviewId);
export const removeUploadedFile = (reference: string) => mediaStore.removeUploadedFile(reference);
export const resolveMediaUrl = (referenceOrKey: string) => mediaStore.resolveMediaUrl(referenceOrKey);

import { prisma } from '../utils/prisma';
import logger from '../utils/logger';
import { removeUploadedFile } from './media.service';

/** Delete only unreferenced managed media, never an image still used in another slot. */
export async function cleanupOrphanedMedia(url: string | null | undefined): Promise<void> {
  if (!url || (!url.startsWith('/api/uploads/') && !url.startsWith('/api/media/'))) return;
  try {
    const references = await Promise.all([
      prisma.track.count({ where: { OR: [{ bannerUrl: url }, { logoUrl: url }, { imageUrl: url }] } }),
      prisma.trackPhoto.count({ where: { url } }),
      prisma.trackReviewPhoto.count({ where: { url } }),
      prisma.user.count({ where: { avatarUrl: url } }),
    ]);
    if (references.every((count) => count === 0)) await removeUploadedFile(url);
  } catch {
    // Cleanup must not turn an already committed profile/review into an HTTP failure.
    logger.warn('Media cleanup deferred; could not check or remove an unreferenced image.');
  }
}

import { PassStatus } from '../types/enums';
import { prisma } from '../utils/prisma';
import { seasonBounds } from '../utils/dates';

/**
 * Activate a pass: mark ACTIVE, set calendar-year expiry, and snapshot the
 * contract terms for every participating track into per-user Allotment rows.
 * Snapshotting means a later contract edit never silently rewrites a rider's
 * remaining days for a season already in flight.
 *
 * A paid pass snapshots an allotment at every active partner track; no
 * allotment row is what makes the scan refuse a venue, so coverage and the
 * ledger stay in one place.
 *
 * The default (free) tier snapshots nothing: no included days and no member
 * discount are what separate it from a paid pass, so it activates with an empty
 * ledger and a free account only ever sees the network, never a day count.
 */
export async function activatePass(passId: string) {
  const pass = await prisma.pass.findUnique({
    where: { id: passId },
    include: { tier: true, season: true },
  });
  if (!pass) throw Object.assign(new Error('Pass not found'), { status: 404 });

  const { endsAt } = seasonBounds(pass.seasonYear);

  return prisma.$transaction(async (tx) => {
    if (pass.tier.isDefault) {
      return tx.pass.update({
        where: { id: pass.id },
        data: {
          status: PassStatus.ACTIVE,
          activatedAt: pass.activatedAt ?? new Date(),
          expiresAt: endsAt,
        },
      });
    }

    const contracts = await tx.trackContract.findMany({
      where: {
        seasonId: pass.seasonId,
        isActive: true,
        track: { isActive: true },
      },
    });

    for (const c of contracts) {
      await tx.allotment.upsert({
        where: {
          userId_trackId_seasonYear: {
            userId: pass.userId,
            trackId: c.trackId,
            seasonYear: pass.seasonYear,
          },
        },
        create: {
          userId: pass.userId,
          trackId: c.trackId,
          passId: pass.id,
          seasonId: pass.seasonId,
          seasonYear: pass.seasonYear,
          includedDays: c.includedDays + pass.tier.extraDaysPerTrack,
          discountDayEnabled: c.discountDayEnabled,
          discountDayNumber: c.discountDayNumber,
          discountRate: c.discountRate,
          discountDaysAllowed: c.discountDaysAllowed,
          extraDayPriceCents: c.extraDayPriceCents,
        },
        update: {
          passId: pass.id,
          includedDays: c.includedDays + pass.tier.extraDaysPerTrack,
        },
      });
    }

    return tx.pass.update({
      where: { id: pass.id },
      data: {
        status: PassStatus.ACTIVE,
        activatedAt: pass.activatedAt ?? new Date(),
        expiresAt: endsAt,
      },
    });
  });
}

/**
 * Grant the default (free) tier to an account: one ACTIVE free pass for the
 * running season, snapshotting nothing. Register calls this for every new
 * account, and a cancelled paid pass falls back onto it.
 */
export async function grantDefaultTier(userId: string) {
  const tier = await prisma.passTier.findFirst({
    where: { isDefault: true, isActive: true },
    orderBy: { sortOrder: 'asc' },
  });
  if (!tier) return;
  const season = await prisma.season.findFirst({
    where: { isActive: true },
    orderBy: { year: 'desc' },
  });
  if (!season) return;
  const pass = await prisma.pass.create({
    data: {
      userId,
      tierId: tier.id,
      seasonId: season.id,
      seasonYear: season.year,
      status: PassStatus.PENDING,
      expiresAt: season.endsAt,
    },
  });
  await activatePass(pass.id);
}

export interface EntitlementRow {
  trackId: string;
  trackName: string;
  trackSlug: string;
  /** From the track's profile; null when the track has no site on file. */
  trackWebsite: string | null;
  /** From the track's profile; null when the track has no photo on file. */
  trackImageUrl: string | null;
  includedDays: number;
  freeDaysUsed: number;
  freeDaysRemaining: number;
  discountDayEnabled: boolean;
  discountDayNumber: number;
  discountRate: number;
  extraDayPriceCents: number;
  discountPriceCents: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
}

/** Per-track entitlement + remaining days for a rider's active pass. */
export async function getEntitlements(userId: string, passId: string): Promise<EntitlementRow[]> {
  const pass = await prisma.pass.findUnique({ where: { id: passId } });
  if (!pass) return [];
  const rows = await prisma.allotment.findMany({
    where: { userId, seasonYear: pass.seasonYear },
    include: { track: true },
    orderBy: { track: { name: 'asc' } },
  });
  return rows.map((a) => ({
    trackId: a.trackId,
    trackName: a.track.name,
    trackSlug: a.track.slug,
    trackWebsite: a.track.website,
    trackImageUrl: a.track.imageUrl,
    includedDays: a.includedDays,
    freeDaysUsed: a.freeDaysUsed,
    freeDaysRemaining: Math.max(a.includedDays - a.freeDaysUsed, 0),
    discountDayEnabled: a.discountDayEnabled,
    discountDayNumber: a.discountDayNumber,
    discountRate: a.discountRate,
    extraDayPriceCents: a.extraDayPriceCents,
    discountPriceCents: Math.round(a.extraDayPriceCents * (1 - a.discountRate)),
    discountDaysAllowed: a.discountDaysAllowed,
    discountDaysUsed: a.discountDaysUsed,
  }));
}

/**
 * Get the rider's current active (or latest) pass for a season. A paid pass
 * always wins over the default (free) one, so upgrading a free account does not
 * leave the free pass shadowing the pass the rider actually bought.
 */
export async function getCurrentPass(userId: string, seasonYear?: number) {
  const where: Record<string, unknown> = { userId };
  if (seasonYear) where.seasonYear = seasonYear;
  const passes = await prisma.pass.findMany({
    where,
    include: { tier: true, season: true },
    orderBy: [{ seasonYear: 'desc' }, { createdAt: 'desc' }],
  });
  const active = passes.filter((p) => p.status === PassStatus.ACTIVE);
  const paid = active
    .filter((p) => !p.tier.isDefault)
    .sort((a, b) => b.tier.priceCents - a.tier.priceCents)[0];
  return paid ?? active[0] ?? passes[0] ?? null;
}

import crypto from 'crypto';
import { prisma } from '../utils/prisma';
import { appUrl, sendPasswordResetEmail } from './mail.service';

/**
 * Reset links. The token is 32 random bytes handed to the rider once; only its
 * SHA-256 is stored, so the table cannot mint a working link. One live token per
 * account: issuing a new one retires the older unused rows, and using one
 * retires the lot.
 */

const TTL_MINUTES = Number(process.env.RESET_TOKEN_TTL_MINUTES || 30);

export const hashToken = (token: string) => crypto.createHash('sha256').update(token).digest('hex');

export const resetLinkFor = (token: string) =>
  `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;

export async function issueResetToken(userId: string): Promise<{ token: string; expiresAt: Date }> {
  // A rider who asks twice gets the newest link and the older one stops working.
  await prisma.passwordReset.deleteMany({ where: { userId, usedAt: null } });

  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + TTL_MINUTES * 60_000);
  await prisma.passwordReset.create({
    data: { userId, tokenHash: hashToken(token), expiresAt },
  });
  return { token, expiresAt };
}

/** The row behind a raw token, with its user — `null` when it is unknown. */
export async function findReset(rawToken: string) {
  if (!rawToken || rawToken.length < 16) return null;
  return prisma.passwordReset.findUnique({
    where: { tokenHash: hashToken(rawToken) },
    include: { user: true },
  });
}

export function resetIsUsable(row: {
  usedAt: Date | null;
  expiresAt: Date;
  user: { isActive: boolean };
}): boolean {
  return !row.usedAt && row.expiresAt.getTime() > Date.now() && row.user.isActive;
}

/** Issue a token and mail the link. The caller decides what to tell the browser. */
export async function sendResetLink(user: { id: string; email: string; name: string }) {
  const { token, expiresAt } = await issueResetToken(user.id);
  const link = resetLinkFor(token);
  const result = await sendPasswordResetEmail({
    to: user.email,
    name: user.name,
    link,
    expiresAt,
  });
  return { link, expiresAt, delivered: result.delivered, reason: result.reason };
}

import {
  PassStatus,
  RedemptionKind,
  ScanResult,
} from '../types/enums';
import { prisma } from '../utils/prisma';
import { verifyQrToken } from '../utils/qr';
import { dayKey, todayKey } from '../utils/dates';
import { getCurrentPass } from './pass.service';

export interface ScanOutcome {
  result: ScanResult;
  reasonCode: string;
  reason: string;
  approved: boolean;
  kind?: RedemptionKind;
  amountChargedCents?: number;
  rider?: { id: string; name: string; email: string };
  track?: { id: string; name: string };
  pass?: { id: string; status: string; seasonYear: number; expiresAt: string; tierName: string };
  remainingFreeDays?: number;
  includedDays?: number;
  discountDaysRemaining?: number;
  redemptionId?: string;
}

/** The allotment fields the gate's decision reads. Structural, so a Prisma
    `Allotment` row passes straight in. */
export type GateAllotment = {
  includedDays: number;
  freeDaysUsed: number;
  discountDayEnabled: boolean;
  discountRate: number;
  discountDaysAllowed: number;
  discountDaysUsed: number;
  extraDayPriceCents: number;
};

/** Everything the ticket window can know *before* it redeems: the rules the
    scan below walks, decided off the same rows. */
export interface GateInputs {
  /** null when the rider holds no pass at all. */
  pass: { status: string; expiresAt: Date } | null;
  trackName: string;
  /** A redemption already on today's ledger for this rider at this track. */
  redeemedToday: boolean;
  allotment: GateAllotment | null;
  now?: number;
}

/** What a redeem would hand over, or the denial that stops it. */
export type GateDecision =
  | { type: 'deny'; reasonCode: string; reason: string }
  | {
      type: 'redeem';
      kind: RedemptionKind;
      amountChargedCents: number;
      decrement: 'free' | 'discount' | 'none';
    };

/**
 * The gate's verdict for one rider — the single place the scan's rules live.
 * `validateScan` executes what this returns and the operator's rider search
 * renders it as the rider's standing, so the panel can never promise a day the
 * server would refuse, and the two can't drift apart.
 *
 * Order is the validator's own: pass state, same-day rule, allotment,
 * then free → discounted → nothing left.
 */
export function gateDecision(inp: GateInputs): GateDecision {
  const { pass, allotment, trackName } = inp;
  const now = inp.now ?? Date.now();

  if (!pass) {
    return { type: 'deny', reasonCode: 'NO_PASS', reason: 'This rider has no pass on their account.' };
  }
  if (pass.status === PassStatus.CANCELLED) {
    return { type: 'deny', reasonCode: 'PASS_CANCELLED', reason: 'This pass has been cancelled.' };
  }
  if (pass.status === PassStatus.PENDING) {
    return { type: 'deny', reasonCode: 'PASS_NOT_ACTIVATED', reason: 'This pass has not been activated yet.' };
  }
  if (pass.status === PassStatus.EXPIRED || pass.expiresAt.getTime() < now) {
    return {
      type: 'deny',
      reasonCode: 'PASS_EXPIRED',
      reason: `Pass expired on ${pass.expiresAt.toISOString().slice(0, 10)}.`,
    };
  }
  if (inp.redeemedToday) {
    return { type: 'deny', reasonCode: 'ALREADY_USED_TODAY', reason: 'Pass already used today at this track.' };
  }
  if (!allotment) {
    return { type: 'deny', reasonCode: 'TRACK_NOT_PARTICIPATING', reason: 'This pass is not valid at this track.' };
  }

  const freeRemaining = Math.max(allotment.includedDays - allotment.freeDaysUsed, 0);
  const discountRemaining = Math.max(allotment.discountDaysAllowed - allotment.discountDaysUsed, 0);

  if (freeRemaining > 0) {
    return {
      type: 'redeem',
      kind: RedemptionKind.FREE,
      amountChargedCents: 0,
      decrement: 'free',
    };
  }
  if (allotment.discountDayEnabled && discountRemaining > 0) {
    const price = Math.round(allotment.extraDayPriceCents * (1 - allotment.discountRate));
    return {
      type: 'redeem',
      kind: RedemptionKind.DISCOUNT,
      amountChargedCents: price,
      decrement: 'discount',
    };
  }
  return {
    type: 'deny',
    reasonCode: 'NO_DAYS_REMAINING',
    reason: `No days remaining at ${trackName} this season.`,
  };
}

/** A rider's standing at the gate: the verdict above, plus the counters and
    the day they already rode, in the shape the operator's panel renders. */
export interface GateStanding {
  /** true when nothing stands between this rider and a redeemed day. */
  ok: boolean;
  reasonCode: string | null;
  reason: string | null;
  /** What a redeem would hand over: a free day or a paid extra day. */
  kind: 'FREE' | 'DISCOUNT' | null;
  amountChargedCents: number | null;
  /** Today's entry at this track, if there already is one. */
  redeemedTodayAt: string | null;
  redeemedTodayKind: string | null;
  includedDays: number | null;
  freeDaysRemaining: number | null;
  discountDaysRemaining: number | null;
}

/** Build the panel's read off the decision, so the wording of a block is
    always the sentence a scan would print. */
export function gateStanding(
  decision: GateDecision,
  extras: {
    redeemedTodayAt?: Date | null;
    redeemedTodayKind?: string | null;
    allotment?: GateAllotment | null;
  } = {}
): GateStanding {
  const a = extras.allotment ?? null;
  return {
    ok: decision.type === 'redeem',
    reasonCode: decision.type === 'deny' ? decision.reasonCode : null,
    reason: decision.type === 'deny' ? decision.reason : null,
    kind: decision.type === 'redeem' ? (decision.kind as 'FREE' | 'DISCOUNT') : null,
    amountChargedCents: decision.type === 'redeem' ? decision.amountChargedCents : null,
    redeemedTodayAt: extras.redeemedTodayAt ? extras.redeemedTodayAt.toISOString() : null,
    redeemedTodayKind: extras.redeemedTodayKind ?? null,
    includedDays: a?.includedDays ?? null,
    freeDaysRemaining: a ? Math.max(a.includedDays - a.freeDaysUsed, 0) : null,
    discountDaysRemaining: a ? Math.max(a.discountDaysAllowed - a.discountDaysUsed, 0) : null,
  };
}

interface ScanInput {
  token: string;
  trackId: string;
  stationId?: string | null;
  operatorId?: string | null;
}

async function logEvent(input: {
  trackId: string;
  stationId?: string | null;
  passId?: string | null;
  userId?: string | null;
  riderName?: string | null;
  result: ScanResult;
  reasonCode: string;
  reason: string;
  kind?: RedemptionKind | null;
  remainingFreeDays?: number | null;
  amountChargedCents?: number;
  operatorId?: string | null;
}) {
  await prisma.scanEvent.create({
    data: {
      trackId: input.trackId,
      stationId: input.stationId ?? null,
      passId: input.passId ?? null,
      userId: input.userId ?? null,
      riderName: input.riderName ?? null,
      result: input.result,
      reasonCode: input.reasonCode,
      reason: input.reason,
      kind: input.kind ?? null,
      remainingFreeDays: input.remainingFreeDays ?? null,
      amountChargedCents: input.amountChargedCents ?? 0,
      operatorId: input.operatorId ?? null,
    },
  });
}

function deny(
  input: ScanInput,
  reasonCode: string,
  reason: string,
  ctx: Partial<ScanOutcome> = {}
): Promise<ScanOutcome> {
  return logEvent({
    trackId: input.trackId,
    stationId: input.stationId,
    passId: ctx.pass?.id,
    userId: ctx.rider?.id,
    riderName: ctx.rider?.name,
    result: ScanResult.DENIED,
    reasonCode,
    reason,
    operatorId: input.operatorId,
  }).then(() => ({ result: ScanResult.DENIED, reasonCode, reason, approved: false, ...ctx }));
}

/**
 * Validate a scan server-side. The client never sends a pre-computed verdict —
 * it sends the QR token; everything below runs against the live ledger.
 */
export async function validateScan(input: ScanInput): Promise<ScanOutcome> {
  // 1. Signature + expiry (anti-replay: tokens are short-lived + nonced).
  const verified = verifyQrToken(input.token);
  if (!verified.ok) {
    return deny(input, verified.reasonCode, verified.reason);
  }
  const { p: passId, u: userId } = verified.payload;

  // 2. Load the pass + rider + tier + track context.
  const pass = await prisma.pass.findUnique({
    where: { id: passId },
    include: { user: true, tier: true },
  });
  if (!pass || pass.userId !== userId) {
    return deny(input, 'PASS_NOT_FOUND', 'Pass not found for this rider.');
  }

  const track = await prisma.track.findUnique({ where: { id: input.trackId } });
  if (!track) return deny(input, 'TRACK_NOT_FOUND', 'Scanning station is not linked to a track.');

  const rider = { id: pass.user.id, name: pass.user.name, email: pass.user.email };
  const passInfo = {
    id: pass.id,
    status: pass.status,
    seasonYear: pass.seasonYear,
    expiresAt: pass.expiresAt.toISOString(),
    tierName: pass.tier.name,
  };
  const ctx: Partial<ScanOutcome> = { rider, track: { id: track.id, name: track.name }, pass: passInfo };

  // 3. Pass state, then every rule below, come from `gateDecision` — the one
  // copy of them, which the operator's rider search reads too.
  const today = todayKey();

  // 4–7. The rules themselves live in one place so the operator's rider
  // search can print the same verdict before the tap. Read every row the
  // decision needs, then let it decide.
  const [todaysReds, allotment] = await Promise.all([
    // Same-day rule: a pass covers one ride day at this track.
    prisma.redemption.findMany({
      where: { userId, trackId: track.id, day: today },
      select: { kind: true },
    }),
    prisma.allotment.findUnique({
      where: {
        userId_trackId_seasonYear: { userId, trackId: track.id, seasonYear: pass.seasonYear },
      },
    }),
  ]);

  const freeRemaining = allotment
    ? Math.max(allotment.includedDays - allotment.freeDaysUsed, 0)
    : 0;
  const discountRemaining = allotment
    ? Math.max(allotment.discountDaysAllowed - allotment.discountDaysUsed, 0)
    : 0;
  const baseCtx: Partial<ScanOutcome> = {
    ...ctx,
    ...(allotment
      ? {
          includedDays: allotment.includedDays,
          remainingFreeDays: freeRemaining,
          discountDaysRemaining: discountRemaining,
        }
      : {}),
  };

  const decision = gateDecision({
    pass: { status: pass.status, expiresAt: pass.expiresAt },
    trackName: track.name,
    redeemedToday: todaysReds.length > 0,
    allotment,
  });

  if (decision.type === 'deny') {
    return deny(input, decision.reasonCode, decision.reason, baseCtx);
  }

  return completeRedemption(input, {
    pass,
    rider,
    trackId: track.id,
    kind: decision.kind,
    amountChargedCents: decision.amountChargedCents,
    decrement: decision.decrement,
    ctx: baseCtx,
  });
}

async function completeRedemption(
  input: ScanInput,
  args: {
    pass: {
      id: string;
      userId: string;
      seasonId: string;
      seasonYear: number;
    };
    rider: { id: string; name: string; email: string };
    trackId: string;
    kind: RedemptionKind;
    amountChargedCents: number;
    decrement: 'free' | 'discount' | 'none';
    ctx: Partial<ScanOutcome>;
  }
): Promise<ScanOutcome> {
  const today = todayKey();
  const { pass, rider, trackId, kind, amountChargedCents, decrement } = args;

  const result = await prisma.$transaction(async (tx) => {
    const redemption = await tx.redemption.create({
      data: {
        userId: rider.id,
        passId: pass.id,
        trackId,
        stationId: input.stationId ?? null,
        kind,
        day: today,
        amountChargedCents,
        operatorId: input.operatorId ?? null,
      },
    });

    const allotment = await tx.allotment.update({
      where: {
        userId_trackId_seasonYear: {
          userId: rider.id,
          trackId,
          seasonYear: pass.seasonYear,
        },
      },
      data:
        decrement === 'free'
          ? { freeDaysUsed: { increment: 1 } }
          : decrement === 'discount'
            ? { discountDaysUsed: { increment: 1 } }
            : {},
    });

    return { redemption, allotment };
  });

  const freeRemaining = Math.max(result.allotment.includedDays - result.allotment.freeDaysUsed, 0);
  const discountRemaining = Math.max(
    result.allotment.discountDaysAllowed - result.allotment.discountDaysUsed,
    0
  );
  await logEvent({
    trackId,
    stationId: input.stationId,
    passId: pass.id,
    userId: rider.id,
    riderName: rider.name,
    result: ScanResult.APPROVED,
    reasonCode: kind === RedemptionKind.DISCOUNT ? 'APPROVED_DISCOUNT' : 'APPROVED',
    reason:
      kind === RedemptionKind.DISCOUNT
        ? `Approved — discounted extra day ($${(amountChargedCents / 100).toFixed(2)} due at the window).`
        : 'Approved.',
    kind,
    remainingFreeDays: freeRemaining,
    amountChargedCents,
    operatorId: input.operatorId,
  });

  return {
    // ctx first: the freshly recomputed counters below must win over any
    // pre-scan snapshot carried in ctx.
    ...args.ctx,
    result: ScanResult.APPROVED,
    approved: true,
    reasonCode: kind === RedemptionKind.DISCOUNT ? 'APPROVED_DISCOUNT' : 'APPROVED',
    reason:
      kind === RedemptionKind.DISCOUNT
        ? 'Approved — discounted extra day.'
        : 'Approved.',
    kind,
    amountChargedCents,
    redemptionId: result.redemption.id,
    remainingFreeDays: freeRemaining,
    includedDays: result.allotment.includedDays,
    discountDaysRemaining: discountRemaining,
  };
}

/**
 * Re-entry: the rider already spent today's visit at this track and is coming
 * back through the gate. Nothing moves — the day was taken at the first scan,
 * no allotment is decremented and no money is owed — so this only writes the
 * pass-through to the same event log the scans read back, which keeps today's
 * record of the gate whole.
 *
 * The rules are the scan's own pass checks plus the inverse same-day rule: a
 * rider with no entry today has nothing to re-enter, and is told so.
 */
export async function completeReentry(args: {
  riderId: string;
  trackId: string;
  stationId?: string | null;
  operatorId?: string | null;
}): Promise<ScanOutcome> {
  /** `deny` and `logEvent` read only the track, station and operator. */
  const gate = {
    token: '',
    trackId: args.trackId,
    stationId: args.stationId ?? null,
    operatorId: args.operatorId ?? null,
  };

  const rider = await prisma.user.findUnique({
    where: { id: args.riderId },
    select: { id: true, name: true, email: true },
  });
  if (!rider) {
    return deny(gate, 'NO_PASS', 'This rider has no pass on their account.');
  }

  const pass = await getCurrentPass(rider.id);
  const ctx: Partial<ScanOutcome> = {
    rider,
    pass: pass
      ? {
          id: pass.id,
          status: pass.status,
          seasonYear: pass.seasonYear,
          expiresAt: pass.expiresAt.toISOString(),
          tierName: pass.tier.name,
        }
      : undefined,
  };

  if (!pass) {
    return deny(gate, 'NO_PASS', 'This rider has no pass on their account.', ctx);
  }
  if (pass.status === PassStatus.CANCELLED) {
    return deny(gate, 'PASS_CANCELLED', 'This pass has been cancelled.', ctx);
  }
  if (pass.status === PassStatus.PENDING) {
    return deny(gate, 'PASS_NOT_ACTIVATED', 'This pass has not been activated yet.', ctx);
  }
  if (pass.status === PassStatus.EXPIRED || pass.expiresAt.getTime() < Date.now()) {
    return deny(gate, 'PASS_EXPIRED', `Pass expired on ${pass.expiresAt.toISOString().slice(0, 10)}.`, ctx);
  }

  // The inverse same-day rule: a re-entry is a second way through the same
  // day's gate, so there has to have been a first.
  const entry = await prisma.redemption.findFirst({
    where: { userId: rider.id, trackId: args.trackId, day: todayKey() },
    select: { id: true },
  });
  if (!entry) {
    return deny(gate, 'NOT_REDEEMED_TODAY', 'No entry to re-enter today at this track.', ctx);
  }

  const reason = 'Re-entry. The day was already redeemed, nothing was charged.';
  await logEvent({
    trackId: args.trackId,
    stationId: args.stationId ?? null,
    passId: pass.id,
    userId: rider.id,
    riderName: rider.name,
    result: ScanResult.APPROVED,
    reasonCode: 'RE_ENTRY',
    reason,
    operatorId: args.operatorId ?? null,
  });

  return {
    ...ctx,
    result: ScanResult.APPROVED,
    approved: true,
    reasonCode: 'RE_ENTRY',
    reason,
  };
}

import crypto from 'crypto';
import { Response } from 'express';
import config from '../config';
import { prisma } from '../utils/prisma';
import { addDays } from '../utils/dates';

export function hashToken(token: string): string {
  return crypto.createHash('sha256').update(token).digest('hex');
}

export async function createSession(
  userId: string,
  meta: { userAgent?: string; ip?: string } = {}
): Promise<{ token: string; expiresAt: Date }> {
  const token = crypto.randomBytes(32).toString('hex');
  const expiresAt = addDays(new Date(), config.session.ttlDays);
  await prisma.session.create({
    data: {
      userId,
      tokenHash: hashToken(token),
      userAgent: meta.userAgent?.slice(0, 250),
      ip: meta.ip,
      expiresAt,
    },
  });
  return { token, expiresAt };
}

export async function resolveSession(token: string | undefined) {
  if (!token) return null;
  const session = await prisma.session.findUnique({
    where: { tokenHash: hashToken(token) },
    include: { user: true },
  });
  if (!session) return null;
  if (session.expiresAt.getTime() < Date.now()) {
    await prisma.session.delete({ where: { id: session.id } }).catch(() => undefined);
    return null;
  }
  if (!session.user.isActive) return null;
  return session;
}

export async function destroySession(token: string | undefined) {
  if (!token) return;
  await prisma.session.deleteMany({ where: { tokenHash: hashToken(token) } });
}

export function setSessionCookie(res: Response, token: string, expiresAt: Date) {
  res.cookie(config.session.cookieName, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: config.isProd,
    expires: expiresAt,
    path: '/',
  });
}

export function clearSessionCookie(res: Response) {
  res.clearCookie(config.session.cookieName, { path: '/' });
}

/**
 * Enum values for the SQLite-backed schema.
 *
 * SQLite has no native enum type, so Prisma stores these as String and the
 * allowed values are defined here — used as both a value object and a type,
 * mirroring the `import { X } from '@prisma/client'` API the app code expects.
 */

function makeEnum<const T extends readonly string[]>(...values: T) {
  return values.reduce(
    (acc, v) => {
      (acc as Record<string, string>)[v] = v;
      return acc;
    },
    {} as { [K in T[number]]: K }
  );
}

