import { Request } from 'express';
import { Role } from './enums';

export interface AuthUser {
  id: string;
  email: string;
  name: string;
  role: Role;
  operatorTrackId: string | null;
}

export interface AuthRequest extends Request {
  user?: AuthUser;
}

export interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data?: T;
  errors?: unknown;
}

export interface Pagination {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export function success<T>(data: T, message = 'OK') {
  return { success: true, message, data };
}

export function error(message: string, errors?: unknown) {
  return { success: false, message, ...(errors !== undefined ? { errors } : {}) };
}

export function paginated<T>(items: T[], total: number, page: number, limit: number) {
  return {
    success: true,
    message: 'OK',
    data: items,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.max(Math.ceil(total / limit), 1),
    },
  };
}

/** Minimal RFC-4180 CSV writer — quotes fields when needed. */
export function toCsv(rows: Record<string, unknown>[]): string {
  if (!rows.length) return '';
  const headers = Object.keys(rows[0]);
  const escape = (v: unknown) => {
    const s = v === null || v === undefined ? '' : String(v);
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const lines = [headers.map(escape).join(',')];
  for (const row of rows) {
    lines.push(headers.map((h) => escape(row[h])).join(','));
  }
  return lines.join('\r\n') + '\r\n';
}

/**
 * Date helpers. Ride days are date-only keys stored as UTC midnight.
 *
 * `dayKey` reads the *UTC* components of what it is handed, so it is only for
 * naming an existing instant ("which calendar day is this timestamp?"). Feeding
 * it `new Date()` to mean "today" is wrong: at 9:54 PM Eastern the clock is
 * already 02:54Z tomorrow, so the day key comes out a day ahead. Use
 * `todayKey()` for today.
 */

export function dayKey(d: Date | string): Date {
  const date = typeof d === 'string' ? new Date(d) : d;
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

/**
 * Today on the venue's own clock: the local year/month/date, stored as a
 * UTC-midnight key so it compares directly against `day` columns. A redemption
 * filed at 9:54 PM belongs to the night it happened, not to tomorrow, so the
 * gate's day rolls over at local midnight.
 */
export function todayKey(): Date {
  const now = new Date();
  return new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
}

export function addDays(d: Date, days: number): Date {
  const copy = new Date(d);
  copy.setUTCDate(copy.getUTCDate() + days);
  return copy;
}

export function isSameDay(a: Date, b: Date): boolean {
  return a.getTime() === b.getTime();
}

export function seasonBounds(year: number): { startsAt: Date; endsAt: Date } {
  // Calendar-year season: Jan 1 00:00 UTC through Dec 31 23:59:59 UTC.
  return {
    startsAt: new Date(Date.UTC(year, 0, 1, 0, 0, 0)),
    endsAt: new Date(Date.UTC(year, 11, 31, 23, 59, 59)),
  };
}

export function formatDay(d: Date | string): string {
  const date = typeof d === 'string' ? new Date(d) : d;
  return date.toISOString().slice(0, 10);
}

const levels = { debug: 10, info: 20, warn: 30, error: 40 } as const;
type Level = keyof typeof levels;

const colors: Record<Level, string> = {
  debug: '\x1b[36m',
  info: '\x1b[32m',
  warn: '\x1b[33m',
  error: '\x1b[31m',
};
const RESET = '\x1b[0m';

const threshold: number =
  levels[(process.env.LOG_LEVEL as Level) in levels ? (process.env.LOG_LEVEL as Level) : 'info'];

function write(level: Level, msg: string, meta?: unknown) {
  if (levels[level] < threshold) return;
  const line = `${colors[level]}[${level.toUpperCase()}]${RESET} ${new Date().toISOString()} ${msg}`;
  const fn = level === 'error' ? console.error : level === 'warn' ? console.warn : console.log;
  if (meta !== undefined) fn(line, meta);
  else fn(line);
}

export const logger = {
  debug: (m: string, meta?: unknown) => write('debug', m, meta),
  info: (m: string, meta?: unknown) => write('info', m, meta),
  warn: (m: string, meta?: unknown) => write('warn', m, meta),
  error: (m: string, meta?: unknown) => write('error', m, meta),
};

export default logger;

import { z } from 'zod';

/**
 * The three keys a rider can be found by at the window. Same vocabulary the
 * gate's search sends, so a stray `field` is refused here rather than falling
 * through to "match anything".
 *
 * The gate submits an address or a number as a whole value; a name still
 * answers on part of one.
 */
export type LookupField = 'email' | 'name' | 'phone';

/** The shortest key each field takes. A name answers on its first letter —
    "R" is a real search at a busy window. */
export const LOOKUP_MIN: Record<LookupField, number> = {
  email: 2,
  name: 1,
  phone: 2,
};

/** What each field can hold, in characters. A phone's cap is on digits. */
export const LOOKUP_MAX: Record<LookupField, number> = {
  email: 254,
  name: 80,
  phone: 15,
};

/** The part before the @, at most. */
const EMAIL_LOCAL_MAX = 64;

/**
 * Control characters, zero-width joiners and bidi overrides: never part of a
 * name, an address or a number typed at a window. Stripped before anything
 * else, so a pasted string cannot smuggle them into a query.
 */
const CONTROL = /[\u0000-\u001F\u007F-\u009F\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g;

/** Collapse the whitespace left behind, so " Riley  Chen " is one name. */
export function sanitizeLookupText(raw: unknown): string {
  return String(raw ?? '')
    .replace(CONTROL, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/* A whole address: a local part, an @, a dotted domain, and a two-letter or
   longer TLD. Bare "riley", "riley@" and "riley@example" are all refused. */
const EMAIL =
  /^[A-Za-z0-9_%+-]+(?:\.[A-Za-z0-9_%+-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,}$/;
/* Letters in any script, marks, and the joiners a real name carries. No
   digits, no symbols, no markup. */
const NAME = /^[\p{L}\p{M}][\p{L}\p{M}\s'’.-]*$/u;
/* What a rider's number may be typed with; the digits themselves are counted
   separately. */
const PHONE_CHARS = /^[\d\s()+.-]+$/;

export type LookupCheck =
  | { ok: true; field: LookupField; text: string }
  | { ok: false; field: LookupField; text: string; message: string; incomplete?: boolean };

/**
 * One rule set for the gate's search, run on both sides: the panel refuses to
 * send a bad key, and the route refuses one that arrives anyway.
 */
export function checkLookupInput(field: LookupField, raw: unknown): LookupCheck {
  const text = sanitizeLookupText(raw);
  const fail = (message: string, incomplete = false): LookupCheck =>
    incomplete
      ? { ok: false, field, text, message, incomplete }
      : { ok: false, field, text, message };

  if (field === 'phone') {
    if (!text) return fail('Enter a phone number.', true);
    if (!PHONE_CHARS.test(text)) return fail('Phone can hold digits, spaces, and + ( ) - . only.');
    const digits = text.replace(/\D/g, '');
    if (digits.length > LOOKUP_MAX.phone) return fail('That is longer than a phone number.');
    const international = text.startsWith('+');
    const complete =
      international
        ? digits.length >= 8
        : digits.length === 10 || (digits.length === 11 && digits[0] === '1');
    if (complete) return { ok: true, field, text };
    if (international || digits.length < 10) {
      return fail(
        international
          ? 'Enter the full number, country code and all.'
          : 'Enter the full 10-digit phone number.',
        true
      );
    }
    return fail('Enter a 10-digit phone number, or 11 digits with a leading 1.');
  }

  if (field === 'email') {
    if (!text) return fail('Enter an email address.', true);
    if (text.length > LOOKUP_MAX.email) return fail('That is longer than an email address.');
    if (!EMAIL.test(text)) {
      return fail('Enter a whole email address: letters, digits and . _ % + - , one @, and a domain.');
    }
    if (text.split('@')[0].length > EMAIL_LOCAL_MAX) {
      return fail('The part before the @ is too long.');
    }
    return { ok: true, field, text };
  }

  if (text.length < LOOKUP_MIN[field]) return fail('Type a name to search.', true);

  if (text.length > LOOKUP_MAX[field]) return fail('That is longer than a name.');

  if (!NAME.test(text)) {
    return fail('Name can hold letters, spaces, hyphens and apostrophes only.');
  }
  return { ok: true, field, text };
}

/**
 * The form the database holds for a rider's number: digits behind one `+`
 * country code, never spaces or dashes. The seed's `tel()` builds the same
 * shape, and the gate's search matches a number by its digits however it is
 * typed at the window — so a number entered at signup or in the profile is
 * stored this way rather than as typed. Ten digits get the US `1`; an empty or
 * digit-less value is no number at all.
 */
export function normalizePhone(raw: unknown): string | null {
  const digits = sanitizeLookupText(raw).replace(/\D/g, '');
  if (!digits) return null;
  return `+${digits.length === 10 ? `1${digits}` : digits}`;
}

/** A query with no `field` matches any of the three keys, so it is checked
    against the loosest of them and still cannot carry markup or controls. */
export function checkAnyLookupText(raw: unknown): LookupCheck {
  const text = sanitizeLookupText(raw);
  if (text.length < 2) {
    return { ok: false, field: 'name', text, message: 'Enter at least two characters.' };
  }
  if (text.length > LOOKUP_MAX.email) {
    return { ok: false, field: 'name', text, message: 'That search is too long.' };
  }
  if (/[<>&"'`;\\/]/.test(text)) {
    return {
      ok: false,
      field: 'name',
      text,
      message: 'Search can hold letters, digits, spaces, @ . + - _ only.',
    };
  }
  return { ok: true, field: 'name', text };
}

/** The query shape the route accepts. `q` is optional only because the search
    still answers an empty one with no rows. */
export const lookupQuerySchema = z.object({
  q: z.string().optional().default(''),
  field: z.enum(['email', 'name', 'phone']).optional(),
  trackId: z.string().uuid().optional(),
});

import bcrypt from 'bcryptjs';

const SALT_ROUNDS = 12;

export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, SALT_ROUNDS);
}

export async function comparePassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

import { PrismaClient } from '@prisma/client';

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient | undefined };

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: process.env.NODE_ENV === 'development' ? ['error', 'warn'] : ['error'],
  });

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

export default prisma;

import crypto from 'crypto';
import config from '../config';

/**
 * QR scan tokens.
 *
 * The rider portal never renders a static, long-lived payload. It requests a
 * short-lived token from the server (GET /api/pass/qr-token) which is signed
 * with the server's QR secret and carries an expiry + random nonce. A
 * screenshot of an old QR therefore fails validation, and every scan is
 * re-validated server-side against the live ledger — the client never decides
 * whether a pass is good.
 *
 * Payload (base64url JSON): { p: passId, u: userId, n: nonce, e: expiryEpoch }
 * Token: <payload>.<hmac>
 */

export interface QrPayload {
  p: string; // passId
  u: string; // userId
  n: string; // nonce (anti-replay)
  e: number; // expiry, unix seconds
}

function b64url(input: Buffer | string): string {
  return Buffer.from(input).toString('base64url');
}

function sign(payloadB64: string): string {
  return crypto
    .createHmac('sha256', config.qr.signingSecret)
    .update(payloadB64)
    .digest('base64url');
}

export function issueQrToken(passId: string, userId: string, ttlSeconds?: number): {
  token: string;
  expiresAt: string;
  nonce: string;
} {
  const ttl = ttlSeconds ?? config.qr.ttlSeconds;
  const now = Math.floor(Date.now() / 1000);
  const payload: QrPayload = {
    p: passId,
    u: userId,
    n: crypto.randomBytes(12).toString('hex'),
    e: now + ttl,
  };
  const payloadB64 = b64url(JSON.stringify(payload));
  const token = `${payloadB64}.${sign(payloadB64)}`;
  return { token, expiresAt: new Date(payload.e * 1000).toISOString(), nonce: payload.n };
}

export type QrVerifyResult =
  | { ok: true; payload: QrPayload }
  | { ok: false; reasonCode: 'MALFORMED' | 'BAD_SIGNATURE' | 'EXPIRED'; reason: string };

export function verifyQrToken(token: string): QrVerifyResult {
  if (!token || typeof token !== 'string' || !token.includes('.')) {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  const [payloadB64, sig] = token.split('.');
  const expected = sign(payloadB64);
  const a = Buffer.from(sig || '');
  const b = Buffer.from(expected);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return { ok: false, reasonCode: 'BAD_SIGNATURE', reason: 'Invalid pass code signature.' };
  }
  let payload: QrPayload;
  try {
    payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString('utf8'));
  } catch {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  if (!payload?.p || !payload?.u || !payload?.e) {
    return { ok: false, reasonCode: 'MALFORMED', reason: 'Malformed pass code.' };
  }
  if (Math.floor(Date.now() / 1000) > payload.e) {
    return {
      ok: false,
      reasonCode: 'EXPIRED',
      reason: 'Pass code expired — ask the rider to refresh their QR code.',
    };
  }
  return { ok: true, payload };
}

import { z } from 'zod';

/**
 * The sanitising half of input handling, in one place.
 *
 * Every write route validates its shape with zod and sanitises its text here,
 * before the value reaches Prisma: control characters, zero-width joiners and
 * bidi overrides are stripped, whitespace is collapsed, the value is trimmed
 * and capped, and a URL is only accepted with an http(s) scheme or as a local
 * path. Numbers sent as query strings are clamped rather than trusted.
 *
 * Two rules the helpers encode:
 *  - Sanitise first, validate second. A preprocess step cleans the value, then
 *    the length / shape rules run on what would actually be stored.
 *  - Never build text from a non-string. `String({})` is "[object Object]" and
 *    lands in a row as if a rider typed it, so anything that is not a string,
 *    a finite number or a boolean becomes ''.
 */

/** Controls, zero-width joiners and bidi overrides — never part of real text. */
const CONTROL = /[\u0000-\u001F\u007F-\u009F\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g;
/** The same set, but a newline survives (review bodies, descriptions). */
const CONTROL_KEEP_NEWLINE =
  /[\u0000-\u0009\u000B-\u000C\u000E-\u001F\u007F-\u009F\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g;

/** A value as text, or '' when it is not something a person could have typed. */
export function toText(raw: unknown): string {
  if (typeof raw === 'string') return raw;
  if (typeof raw === 'number' && Number.isFinite(raw)) return String(raw);
  if (typeof raw === 'boolean') return String(raw);
  return '';
}

/** One line: controls stripped, runs of whitespace collapsed, trimmed, capped. */
export function cleanLine(raw: unknown, max = 300): string {
  return toText(raw).replace(CONTROL, '').replace(/\s+/g, ' ').trim().slice(0, max);
}

/** Many lines: newlines kept (normalised to \n), controls stripped, trimmed. */
export function cleanMultiline(raw: unknown, max = 2000): string {
  return toText(raw)
    .replace(/\r\n?/g, '\n')
    .replace(CONTROL_KEEP_NEWLINE, '')
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, max);
}

/** An empty string clears an optional field; anything else is cleaned text. */
export function cleanOptionalLine(raw: unknown, max = 300): string | undefined {
  if (raw === undefined) return undefined;
  return cleanLine(raw, max);
}

/** Digits only — the form a phone number is compared in. */
export function digitsOf(raw: unknown): string {
  return toText(raw).replace(/\D/g, '');
}

/** Letters, marks and the joiners a real name carries. */
const NAME = /^[\p{L}\p{M}][\p{L}\p{M}\s'’.-]*$/u;
/** An address: one @, a dotted domain, a two-letter-or-longer TLD. */
const EMAIL =
  /^[A-Za-z0-9_%+-]+(?:\.[A-Za-z0-9_%+-]+)*@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\.)+[A-Za-z]{2,}$/;

export function isEmail(text: string): boolean {
  return text.length <= 254 && EMAIL.test(text);
}

/**
 * A URL a browser may be pointed at: http(s), or a path on this origin
 * (`/api/uploads/...`, `/tracks/...`). `javascript:`, `data:`, `vbscript:` and
 * protocol-relative `//evil` are all refused, so a pasted link can never become
 * a script in an href.
 */
export function isSafeUrl(text: string): boolean {
  if (!text) return true;
  if (/[\s<>"'`]/.test(text)) return false;
  return /^https?:\/\/[^\s]+$/i.test(text) || /^\/[^/]/.test(text);
}

/** What an uploaded image may arrive as — the same set `storeDataUrl` writes. */
export const DATA_URL = /^data:image\/(png|jpe?g|webp|gif|avif);base64,[A-Za-z0-9+/=\s]+$/i;

export function isDataImageUrl(text: string): boolean {
  return DATA_URL.test(text.trim());
}

/** A pasted image data URL: controls and every whitespace character removed. */
export function cleanDataUrl(raw: unknown, max = 8_000_000): string {
  return toText(raw)
    .replace(CONTROL, '')
    .replace(/\s+/g, '')
    .slice(0, max);
}

/** An uploaded image, as the one shape `storeDataUrl` accepts. */
export function zDataImageUrl(max = 8_000_000) {
  return z.preprocess(
    (v) => cleanDataUrl(v, max),
    z.string().min(1, 'Pick an image.').refine(isDataImageUrl, 'Upload a PNG, JPG, WEBP, GIF or AVIF image.')
  );
}

/** A uuid as an id: refused as a 400 rather than reaching Prisma as a 500. */
export function uuidParam(raw: unknown, label = 'id'): string {
  return z.string().uuid(`${label} is not a valid id.`).parse(raw);
}

/** A number sent as a query string, clamped into range. */
export function clampInt(raw: unknown, fallback: number, min: number, max: number): number {
  const n = typeof raw === 'number' ? raw : Number(toText(raw).trim());
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, Math.trunc(n)));
}

/** True for a `YYYY-MM-DD` day that really exists. */
export function isDayString(text: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) return false;
  const [y, m, d] = text.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
}

// ---------------------------------------------------------------------------
// Zod field builders
// ---------------------------------------------------------------------------

/**
 * One line of text. `min` is checked against the sanitised value, so a name of
 * three spaces is empty, not valid.
 */
export function zLine(max: number, min = 0, message?: string) {
  return z.preprocess(
    (v) => cleanLine(v, max),
    z.string().min(min, message ?? `Enter at least ${min} characters.`).max(max, `Keep it under ${max} characters.`)
  );
}

/** Free text with newlines — a review body, a description, a note. */
export function zMultiline(max: number, min = 0) {
  return z.preprocess(
    (v) => cleanMultiline(v, max),
    z.string().min(min, `Enter at least ${min} characters.`).max(max, `Keep it under ${max} characters.`)
  );
}

/** A person's name: letters in any script, marks, spaces, hyphens, apostrophes. */
export function zName(min = 2, max = 80) {
  return z.preprocess(
    (v) => cleanLine(v, max),
    z
      .string()
      .min(min, 'Enter a name.')
      .max(max, `Keep the name under ${max} characters.`)
      .regex(NAME, 'Name can hold letters, spaces, hyphens and apostrophes only.')
  );
}

export function zEmail(max = 254) {
  return z.preprocess(
    (v) => cleanLine(v, max),
    z.string().min(1, 'Enter an email address.').max(max).refine(isEmail, 'Enter a valid email address.')
  );
}

/**
 * An account's sign-in address, lowercased. `User.email` is a case-sensitive
 * unique key in Postgres, so `Riley@x.com` and `riley@x.com` would otherwise be
 * two accounts, and a login or reset typed in the other case would miss.
 */
export function zAccountEmail(max = 254) {
  return z.preprocess(
    (v) => cleanLine(v, max).toLowerCase(),
    z.string().min(1, 'Enter an email address.').max(max).refine(isEmail, 'Enter a valid email address.')
  );
}

/** Optional email: '' clears the field, otherwise it must be a whole address. */
export function zEmailOptional(max = 254) {
  return z.preprocess(
    (v) => cleanLine(v, max),
    z
      .string()
      .max(max)
      .refine((v) => v === '' || isEmail(v), 'Enter a valid email address.')
  );
}

/** Optional phone: '' is allowed (the field clears), otherwise 7–15 digits. */
export function zPhone(maxChars = 40) {
  return z.preprocess(
    (v) => cleanLine(v, maxChars),
    z
      .string()
      .max(maxChars)
      .refine((v) => {
        if (v === '') return true;
        if (!/^[\d\s()+.-]+$/.test(v)) return false;
        const digits = digitsOf(v);
        return digits.length >= 7 && digits.length <= 15;
      }, 'Enter a phone number: 7 to 15 digits, spaces and + ( ) - . allowed.')
  );
}

/** A password: long enough to matter, capped so a 1 MB "password" is refused. */
export function zPassword(min = 8, max = 200) {
  return z
    .string()
    .min(min, `Password must be at least ${min} characters`)
    .max(max, `Password must be under ${max} characters`);
}

/** An http(s) URL or a local path; '' clears it. */
export function zUrl(max = 500) {
  return z.preprocess(
    (v) => cleanLine(v, max),
    z.string().max(max).refine(isSafeUrl, 'Enter a web address starting with http:// or https://.')
  );
}

/** A slug: lowercase letters, digits and single hyphens. */
export function zSlug(max = 80) {
  return z.preprocess(
    (v) => cleanLine(v, max).toLowerCase(),
    z
      .string()
      .min(2, 'Enter a slug.')
      .max(max)
      .regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'A slug holds lowercase letters, digits and hyphens.')
  );
}

export function zUuid(message = 'Not a valid id.') {
  return z.string().uuid(message);
}

/** A bare calendar day, checked for existence, not just shape. */
export function zDay() {
  return z.preprocess(
    (v) => cleanLine(v, 10),
    z.string().refine(isDayString, 'Pick a date.')
  );
}

/** An ISO date or datetime that `new Date()` can actually read. */
export function zDateish() {
  return z.preprocess(
    (v) => cleanLine(v, 40),
    z.string().min(4).refine((v) => !Number.isNaN(new Date(v).getTime()), 'Pick a valid date.')
  );
}
